QuestGearQuestInfo = {
  [5]={t="饥肠辘辘的基特斯",d="我已经困在这个鬼镇里好几个星期了，除了虫子和野草之外什么吃的都没有！我想吃点正常的食物，即使要多花点钱也无所谓。；给我找点美食来，我就给你大笔的奖赏。；听说夜色镇血鸦旅店的厨师格鲁奥做的黑蟹蛋糕很不错……",o="和厨师格鲁奥谈一谈。"},
  [6]={t="加瑞克·帕德弗特的赏金",d="加瑞克·帕德弗特，这个恶棍几周以来一直让我们的农民和商人心惊胆战，前几天有人在农场附近的小屋里看到了他的身影，大概在就是修道院东边过了桥以后的那片地方。带他的头颅回来见我，然后领取赏金吧！；不过你要小心一点，你。加瑞克身边总是有一帮暴徒，他可不是那么容易搞定的家伙。",o="杀死加瑞克·帕德弗特，带着他的头颅到北郡修道院去找维里副队长。",p=18,r={{i=182,n="加瑞克的徽记",c=1}},w={{i=6076,n="紧口短裤",c=1},{i=60,n="夹层外衣",c=1},{i=3070,n="军旗披风",c=1}},f=1},
  [7]={t="剿灭狗头人",d="你的第一个任务是清剿工作，你。一个狗头人部族占据了北边的森林。到那儿去，把你能看到的狗头人歹徒都杀掉。尽量减少他们的数量，好让我们有一天能把他们从北郡彻底赶出去。",o="杀死8只狗头人歹徒，然后向治安官玛克布莱德复命。",p=783},
  [8]={t="盗贼的交易",d="嘿，伙计！帮我一个忙如何？大堆僵尸和蜘蛛实在让我应接不暇。；现在我手里有一封要送到布瑞尔的信……送给一个名叫瑞尼的还是别的什么的旅店老板，别管她姓什么啦。；总之，那里是一个舒适而温暖的小地方，里面都是些希望重返真实自我的瘟疫受害者，当然那里也是你休息的好去处。你应该自己去看看……如果你愿意跑一趟，我会给你不错的报酬的。",o="把笔迹潦草的信件送给布瑞尔的旅店老板瑞尼。",r={{i=7628,n="笔迹潦草的信件",c=1}},w={{i=4604,n="森林蘑菇",c=5},{i=159,n="清凉的泉水",c=5}}},
  [9]={t="清理荒野",d="看看这片土地上都发生了些什么吧！这片土地曾为一群善良老实的农民们所有。但如今，一群该死的小贼把农民们全部赶走了。当然，除了老子我！但有些看守傀儡一直霸占着我的田地。；如果你觉着自己能够胜任这份工作的话，我希望你能帮忙清除掉20台傀儡。完成了任务之后，记得回来拿酬劳。如果你把我这片田地上的傀儡清光了的话，就去清除旁边田上的傀儡吧。",o="农夫萨丁要求你破坏掉20台看守傀儡。",w={{i=3578,n="收割者的短裤",c=1},{i=1561,n="收割者的长袍",c=1}},f=1},
  [10]={t="谢申克的救赎",d="啊，这真是太糟糕了！我派我手下最得力的助手，初级勘探员谢申克去沙漠东南面的那个叫做大裂口的地方进行探查。但是现在他失踪了，而他最后一份报告中显示大裂口到处都充斥着那些怪异的虫子。我现在已经派不出足够的人力来同时探查这片沙漠上的两大块重要的地区了。；我想派你去大裂口找谢申克，求求你了！也许他已经……但至少请帮我拿回他的勘探设备来。我恐怕那是可怜的谢申克最后的遗产了。",o="寻找初级勘探员谢申克的下落，把他或者他的勘探设备交给加基森的高级勘探员菲兹杜瑟。",p=82,r={{i=8593,n="谢申克的勘探设备",c=1}}},
  [11]={t="悬赏河爪豺狼人",d="有人在艾尔文森林的边界处看见了豺狼人，这些野蛮的动物在这儿肯定不会干什么好事。在了望塔南边的树林里有一大群豺狼人到处游荡，凭我们自己的兵力很难应付他们。；任何帮忙清除这些豺狼人的勇士都会受到暴风城军方的嘉奖。把他们的彩色豺狼人臂章带给我以证明你杀了他们。",o="给兵营的瑞尼尔副队长带去8个彩色豺狼人臂章。",r={{i=782,n="彩色豺狼人臂章",c=8}},w={{i=2249,n="民兵圆盾",c=1},{i=2238,n="顽童短裤",c=1}},f=1},
  [12]={t="西部荒野人民军",d="人民军只一个目标：保护西部荒野的安宁，并将和平带回到这片土地上来。不幸的是，和平总是以鲜血的代价来换取的。；我手下的一个斥候报告说，有一群迪菲亚捕兽者正在附近到处流窜并大肆破坏。最新的报告说他们出现在了西北方的詹戈洛德矿洞中，如果你想加入我们人民军的话，那么就先杀死15名迪菲亚捕兽者和15名迪菲亚走私者，然后回来向我复命。",o="哨兵岭的格里安·斯托曼要求你杀死15名迪菲亚捕兽者和15名迪菲亚走私者，然后回去向他报告。"},
  [13]={t="西部荒野人民军",d="有人看见一群凶残的迪菲亚抢劫者洗劫了金海岸矿洞和月溪镇，我们人民军绝不能对这样的事袖手旁观。马上就出发吧，$n，让圣光重新照耀西部荒野。；金海岸矿洞就在哨塔西边的海岸附近，作为训练的第二部分，我希望你能杀死15名迪菲亚抢劫者和15名迪菲亚强夺者。",o="哨兵岭的格里安·斯托曼要求你杀死15名迪菲亚抢劫者和15名迪菲亚强夺者，然后回去向他报告。",p=12},
  [14]={t="西部荒野人民军",d="一些迪菲亚路霸最近一直在避开我们，到处作恶。根据我手下最可靠的探子们的线报，这些迪菲亚路霸通常沿着从这里到西部荒野南部的道路打家劫舍。我们觉得他们现在应该就躲在南部的山丘那边，计划着下一步的行动。以人民军的名义，去杀死那些家伙。",o="哨兵岭的格里安·斯托曼要求你杀死15个迪菲亚路霸、5个迪菲亚巡路者和5个迪菲亚拳匪，然后回去向他报告。",p=13,w={{i=1566,n="人民军之剑",c=1},{i=1480,n="人民军之拳",c=1},{i=12296,n="人民军之星",c=1}},f=1},
  [15]={t="回音山调查行动",d="你，我的探子告诉我说，狗头人群落的规模远远大于我们的估计，一群狗头人劳工刚刚入侵了北边的回音山矿洞。；到矿洞里去，把他们都除掉。那里至少有8个狗头人劳工，杀光他们，如果你发现他们的数量远不止这么多的话，就赶快回报给我。",o="杀死8只狗头人劳工，然后向治安官玛克布莱德复命。",p=7},
  [18]={t="盗贼兄弟会",d="最近, 一伙新来的流寇停留在北郡一带，为祸四方。他们自称为迪菲亚兄弟会，向东过了河之后就能找到他们。；我不知道他们聚在一起到底想要干什么，但我确信他们不是什么好东西。给我带回一些他们的红色粗麻面罩，我就送你一把武器作为奖励。",o="给北郡的维里副队长带回8个红色粗麻面罩。",p=783,r={{i=752,n="红色粗麻面罩",c=12}},w={{i=2224,n="民兵匕首",c=1},{i=5580,n="民兵之锤",c=1},{i=1161,n="民兵短剑",c=1},{i=5579,n="民兵战锤",c=1},{i=1159,n="民兵短杖",c=1}},f=1},
  [19]={t="萨瑞尔祖恩",d="黑石前锋和黑石叛节者经常在这里和石堡要塞之间伏击我们，这群前锋的指挥官是个名叫萨瑞尔祖恩的兽人。把他的徽记给我带来。",o="将萨瑞尔祖恩的徽记带给湖畔镇的治安官马瑞斯。",p=20,r={{i=1260,n="萨瑞尔祖恩的徽记",c=1}},w={{i=1276,n="淬火圆盾",c=1},{i=6093,n="兽人粉碎者",c=1}},f=1},
  [20]={t="黑石氏族的威胁",d="黑石氏族穿越了燃烧平原并攻下了北方的石堡要塞。他们以那座要塞为据点，劫掠湖畔镇北边的人们，吓得全镇的居民都不敢外出，只能躲在镇子里瑟瑟发抖。；帮湖畔镇解决掉这个威胁吧。杀死黑石氏族的兽人，并带回来十把他们所用的破斧作为证明。；尽管黑石氏族是在北方威胁着我们，但我们也收到了他们在赤脊山脉东南部出现的报告。你可以在那里找到他们，然后猎杀他们。",o="给湖畔镇的治安官马瑞斯带回10把破斧。",r={{i=3014,n="破斧",c=10}}},
  [21]={t="回音山清剿行动",d="你上次的调查证实，回音山矿洞需要一次清剿行动。回到矿洞那边，帮我们清除那里所有的狗头人吧。；抓紧时间，你。狗头人无所顾忌地盘踞在矿洞里的时间越长，它们在北郡的据点也就越稳固。",o="杀死8只狗头人苦力，然后向北郡修道院里的治安官玛克布莱德复命。",p=15,w={{i=2186,n="旅行腰带",c=1},{i=2691,n="旅行之靴",c=1},{i=11192,n="旅行手套",c=1}},f=1},
  [30]={t="海狮试炼",d="第二个试炼是要寻找组成海狮坠饰的两个部分。其中的一半蕴含着海狮的敏捷天性，另一半蕴含着海狮那令人难以置信的耐力。德鲁伊汲取这两种特性，将它们运用到自己的水栖形态中。；与月光林地中的居民谈一谈，找到这两个部分，并将它们合并起来。最后把合并好的坠饰交给德迪利特·星焰。",o="寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。；在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。；将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。",p=28,r={{i=15885,n="海狮坠饰",c=1}}},
  [31]={t="水栖形态",d="你已经学完了掌握水栖形态所必须具备的所有知识，现在回到雷霆崖的图拉克·符文图腾那儿去吧。把坠饰拿给他看看，以此证明你已准备好接受新的知识。他会让你掌握变化为水栖形态的诀窍，让你在水中灵活自如。；再见，年轻的德鲁伊。我们会再见面的。",o="回到雷霆崖，让图拉克·符文图腾看看你的海狮坠饰。",p=30,r={{i=15885,n="海狮坠饰",c=1}},f=2},
  [33]={t="林中的群狼",d="影响那些狼的邪恶东西还没有消失。每天都有更多的狼受到感染。杀害自然的野兽让我感到痛苦，但我们必须消灭那些受到污染的幼狼，否则更大的灾祸就会接踵而至。；消灭山谷中那些受到感染的幼狼，把它们的皮给我带回来，作为你行动的证据。",o="给北郡修道院外的伊根·派特斯金纳带回8块病狼的皮毛。",p=5261,r={{i=750,n="硬狼肉",c=8}},w={{i=80,n="柔软的毛边鞋",c=1},{i=6070,n="狼皮护腕",c=1}},f=1},
  [34]={t="不速之客",d="前几天我的花园又被搞得一塌糊涂，不过现在我已经知道是哪个混蛋干的了。就是那只被治安官马瑞斯先生称作“贝利格拉布”的野猪。；你瞧，我在下一季来临之前都没法种我的水仙花了。全毁了！一切都被那只混蛋野猪给毁了！把那祸害给我干掉！把它的獠牙给我带回来，我会付给你酬劳的。它一般就在湖畔镇西南的田边闲逛，但有时候也会跑进我的花园里来。",o="湖畔镇的玛蒂·詹罗斯要求你杀死贝利格拉布，并带回它的獠牙作为证明。",r={{i=3631,n="贝利格拉布的獠牙",c=1}},f=1},
  [36]={t="杂味炖肉",d="我从来没有想过有一天会被迫离开我的农庄。但是现在，那些满是小贼和强盗的田地对我们来说已经是太过危险了。等法布隆修好他的车之后，我们就要逃离这里了。；或许你能帮我一个小忙？先让我把我的独家绝活杂味炖肉的食谱给抄下来，然后你帮我把它交给萨尔玛·萨丁。萨丁农场就在路口的另一边。",o="弗娜·法布隆要求你将她的杂味炖肉食谱交给萨尔玛·萨丁。",r={{i=2832,n="弗娜的杂味炖肉食谱",c=1}}},
  [38]={t="杂味炖肉",d="来帮我完成这道最华丽的西部荒野杂味炖肉吧！拜托啦，帮我找到以下这些材料：；3块秃鹫肉条；3只血牙野猪的头；3只鱼人的眼睛；3棵秋葵",o="萨尔玛·萨丁需要3块秃鹫肉条、3只血牙野猪的头、3颗鱼人的眼睛和3棵秋葵。",p=36,r={{i=729,n="秃鹫肉条",c=3},{i=730,n="鱼人的眼球",c=3},{i=731,n="血牙野猪的头",c=3},{i=732,n="成熟的秋葵",c=3}},f=1},
  [46]={t="悬赏鱼人",d="暴风城军队悬赏清除那些艾尔文森林内的鱼人潜伏者和鱼人强盗。杀了它们，把它们破损的鱼人鳞片给我带回来，暴风城军队会奖励你的。；鱼人在北面的石碑湖附近建造了一座村庄，另外在南面的溪流分叉处还有一座村庄。",o="给艾尔文森林东部的桥边的卫兵托马斯带去8个破损的鱼人鳞片。",r={{i=780,n="破损的鱼人鳞片",c=8}},w={{i=4840,n="长刺刀",c=1},{i=1158,n="结实的铁棍",c=1},{i=1008,n="古旧的剑",c=1}},f=1},
  [49]={t="琥珀酒",d="琥珀的颜色是我毕生之爱；就像西山夕阳下的云彩；为了它的诞生呀，勇敢的少年我召唤你；我要黑麦、大麦和玉米！；Amber is the hue of my life's longest love；Like the last embers of dusk in the sky above；Retrieve for me so that my love shall be born；One sack of each: barley, rye an",o="葛瑞姆·雷酒需要大麦、黑麦和玉米各一袋。",p=48,r={{i=738,n="一袋大麦",c=1},{i=739,n="一袋玉米",c=1},{i=740,n="一袋黑麦",c=1}}},
  [50]={t="琥珀酒",d="我捣！我搅！我捣！我搅！；少了玩意就没法搞好；我要一种够硬的金属来当罐儿；给我弄些真银来，我就唱完歌儿！ ；I'll mix and mix till we have a mash；For this will be our own private stash；A still must be fashioned of metal strong；Bring me some Truesilver so I can finish this so",o="葛瑞姆·雷酒需要一些真银。",p=49,r={{i=6037,n="真银锭",c=1}}},
  [51]={t="琥珀酒",d="还没过滤但是刚刚蒸馏；就像是新皮甲还没上油；然后得烧它七八斤炭呀；我说你赶紧动身去办呀！；Not yet filtered but freshly distilled；Like unseeded land waiting there tilled.；Next I will fashion our pile of charcoal；Deliver a sycamore branch, that is your next goal",o="带给葛瑞姆·雷酒一枝枫树枝。",p=50,r={{i=742,n="枫树枝",c=1}}},
  [53]={t="琥珀酒",d="甜美的液体清澈如婴儿泪；百年的陈酿色深如琥珀；但在把它放进地窖存着前；造个橡木大桶来盛着先！；Mellifluous liquid clear as a baby's tears；Turns a lovely deep amber over the years；But before we proceed to get lit to the hilt；A barrel of charred oak must be built",o="给葛瑞姆·雷酒带去一捆烧焦的橡木。",p=51,r={{i=743,n="一捆烧焦的橡木",c=1}},f=1},
  [54]={t="去闪金镇报到",d="你，如今你已经被证实是一位非常关心北郡的安全的$c了。现在我要派遣你去保卫艾尔文森林的周边地区。；如果你接下了这个任务，就把这些文件送到闪金镇的治安官杜汉手里。沿着向南的大道走，穿过北郡的关卡就能看到闪金镇了。",o="将治安官玛克布莱德的文件带给闪金镇的治安官杜汉。",p=21,r={{i=745,n="治安官玛克布莱德的文件",c=1}},f=1},
  [55]={t="摩本特·费尔",d="摩本特·费尔的老巢就在一个可以俯视乌鸦岭墓地的山顶上。他的日子就快要到头了……；杀掉他，让我们不被他的邪恶所侵害。为我复仇吧，也为了夜色镇的人民！",o="对摩本特·费尔使用摩本特的克星，杀掉他，然后把摩本特的克星交给斯温。",p=325,r={{i=7297,n="摩本特的克星",c=1}},w={{i=2954,n="守夜人马裤",c=1},{i=2953,n="守夜人披风",c=1},{i=1282,n="火花铁帽",c=1}},f=1},
  [56]={t="守夜人",d="作为守夜人的指挥官，我发过誓要保卫夜色镇人民的安全。暴风城已经把他们驻守在这里的部队撤了回去，现在我们只能依靠自己了。；如果你觉得可以胜任，就请帮助我们吧！到夜色镇南部的静谧花园去，杀掉8个骷髅战士和6个骷髅法师。我们必须尽量减轻亡灵所能够带来的压力！",o="夜色镇的指挥官指挥官阿尔泰娅·埃伯洛克要你去杀掉8个骷髅战士和6个骷髅法师。"},
  [57]={t="守夜人",d="你，我收到报告说有亡灵在森林里出没！如果你能应付的话，就到乌鸦岭的大墓地去杀15个骸骨魔和15个恐怖骸骨。另外，在夜色镇南部的静谧花园一带也都发现有骷髅在出没。我们一定要把这些亡灵驱逐出暮色森林！",o="指挥官阿尔泰娅·埃伯洛克要你去杀掉15个骸骨魔和15个恐怖骸骨。",p=56},
  [59]={t="布甲和皮甲",d="为了表彰你的智慧和勇敢，我把这个标记给你，用在护甲上应该很不错。你把它交给东谷伐木场的萨拉·迪博雷恩，她会为你做件合适的护甲。这件护甲在你为保卫艾尔文森林作战时应该用得到。；东谷伐木场就在卫兵托马斯所在的哨所的东面。",o="把暴风城护甲标记交给萨拉·迪博雷恩。",p=39,r={{i=748,n="暴风城护甲标记",c=1}},w={{i=1171,n="精心缝制的长袍",c=1},{i=2237,n="破旧的短裤",c=1}},f=1},
  [60]={t="狗头人的蜡烛",d="你好，$g亲爱的先生:尊贵的女士;！你有时间吗？；我和我兄弟在暴风城开了个药店，而我现在正要在这一带找些大蜡烛，以便提取其中的蜡。你能帮助我吗？；你可以在狗头人身上找到大蜡烛，我听说在艾尔文森林的矿洞一带有很多狗头人……在南边的法戈第矿洞和东边的玉石矿洞里都有不少。我推荐你去这两个矿洞里看看。",o="为闪金镇的威廉·匹斯特收集8支大蜡烛。",r={{i=772,n="大蜡烛",c=8}}},
  [62]={t="法戈第矿洞",d="出问题的还不止北郡的矿洞！我接到报告说艾尔文森林的法戈第矿洞已经成了狗头人的天堂。；去那里查看一下这些报告是否属实，然后回来告诉我。法戈第矿洞就在闪金镇的正南方，斯通菲尔德农场和马科伦农场之间。",o="调查法戈第矿洞，然后回到闪金镇去见治安官杜汉。"},
  [63]={t="水之召唤",d="沿着银松森林海岸前行，在瑟伯切尔的西边有一处被瘟疫玷污过的神殿。那里的水灵不再和我们交谈，你的任务就是消灭那个污染源并净化那个水池。；将元素护腕和剩馀的泉水放置在火盆上，就可以进行召唤水灵的仪式了。$rnB；把能够证明你完成了任务的证据带回来给我，然后我就会给你图腾。",o="击败堕落的水之魂，把堕落水之魂的护腕和剩馀的最纯净的水放在银松森林的圣泉火盆上。",p=220,r={{i=7812,n="堕落水之魂的护腕",c=1},{i=7811,n="剩余的最纯净的水",c=1}}},
  [68]={t="斯塔文的传说",d="你在旧提箱里找到了一封复满灰尘的信。",o="把复满灰尘的信交给书记员达尔塔。",p=67,r={{i=889,n="一封覆满灰尘的信",c=1}}},
  [70]={t="斯塔文的传说",d="斯塔文的名字让我想起点什么…哦，想起来了！；很多年前的一个雷雨交加的夜晚，有个信差到这儿来过夜避雨。快到午夜12点的时候，他一边尖叫着一边从楼上跑下来，苍白的脸上满是惶恐的神色，最后他穿着睡衣逃进了瓢泼的大雨中。；由于走得太匆忙，他忘了拿走楼上箱子里的信，不过后来也没有再回来取过。喏，这一封是写给斯塔文的一个住在暴风城运河区的朋友的，你自己拿去看吧。",o="从箱子中拿出斯塔文的未寄出的信，把它送到暴风城的运河区。",p=69,r={{i=910,n="一封未寄出的信",c=1}}},
  [71]={t="回复托马斯",d="把你找到的两块铭牌交给桥边的卫兵托马斯，让他知道两个卫兵的死讯。",o="把罗尔夫和马拉凯的铭牌交给艾尔文森林东部桥边的卫兵托马斯。",p=45,r={{i=735,n="罗尔夫和马拉凯的铭牌",c=1}}},
  [74]={t="斯塔文的传说",d="你在箱子里找到了几样东西：一些有霉味的、看上去像是传家宝的东西，一副家庭肖像画，一些打猎所得的战利品和几本旧书。在箱子底部的一个花瓶下面，你找到了一张被撕破的日记书页。",o="你找到的这张被撕破的日记书页给你提供了又一个线索。",p=72,r={{i=916,n="一张被撕破的日记书页",c=1}}},
  [75]={t="斯塔文的传说",d="我刚刚搬进来住的时候发现楼上的箱子里有一捆羊皮纸，我想看看那些羊皮纸上写了什么，但是迷雾却让我根本看不清楚。；给我这个快瞎了的老人帮个忙吧，去检查一下楼上箱子里的东西，看看有没有什么有关斯塔文的信息。我记得有一张褪色的日记书页，你肯定会对它感兴趣的。把它拿过来，我会尽力帮助你的。",o="治安官哈迦德要你从楼上的箱子里找出一张褪色的日记书页。",p=74,r={{i=921,n="一张褪色的日记书页",c=1}}},
  [76]={t="玉石矿洞",d="多亏了你，我们才知道法戈第矿洞里出现了很多狗头人。现在我们还需要一个人去更远处的玉石矿洞侦察。；去查看一下玉石矿洞，确定那里是否有狗头人。向东沿着大路走，一直走到阿祖拉之塔，然后往北走就会看到山脚下的矿洞。",o="查看玉石矿洞，然后回到闪金镇去向治安官杜汉报告。",p=62},
  [77]={t="收集蜜糖",d="我这里有德兰·杜佛斯需要的包装材料。我会帮助你为玛尔顿那烦人的老爸包装他要的蜜糖……不过你得给我多带几瓶蜜糖回来。它们就在靠近隐匿石一带，在那座荒废掉的部落村庄的箱子里，可恶的泥浆怪和软泥怪霸占了那块地方，有传言说它们是由一些大型软泥怪领导着的。但不管怎么样，你必须找到蜜糖并把它们带回来让我进行包装。",o="从隐匿石一带被部落废弃的基地中的箱子里找到10瓶辛特兰蜜糖。",p=650,r={{i=8684,n="辛特兰蜜糖",c=10}}},
  [78]={t="斯塔文的传说",d="我知道有人可以帮你。我以前领导暴风城卫队的时候，经常去夜色镇的血鸦旅店喝酒。那儿的老板斯密茨对当地的情况了如指掌。把这张东西给他，看看他对此有什么说法。",o="把褪色的日记书页带给暮色森林中夜色镇的旅店老板斯密茨。",p=75,r={{i=921,n="一张褪色的日记书页",c=1}}},
  [79]={t="斯塔文的传说",d="多年来我一直在追寻这个斯塔文的消息。几年前那些来访的贵族被杀之后，我曾和哈迦德一起去调查。我发现了这些沾满泥污的纸，但是一直没有都想到把这上面的笔迹和树林里的那个疯子联系在一起。你提供的线索证明了他的罪行。赶快把这个交给指挥官阿尔泰娅·埃伯洛克，告诉她你所发现的一切。",o="把沾满泥污的日记书页交给指挥官阿尔泰娅·埃伯洛克。",p=78,r={{i=938,n="沾满泥污的日记书页",c=1}}},
  [80]={t="斯塔文的传说",d="有一段时间我一直注意着斯塔文这个讨厌的家伙。如果这些东西都是他写的，那就足以给他定罪了。；书记员达尔塔多年以来一直负责着镇里的档案，他很擅长辨认笔迹。把这张纸给他，看看是否和档案里面斯塔文的签名笔迹相吻合。",o="把染血的日记书页交给书记员达尔塔。",p=79,r={{i=939,n="一张染血的日记书页",c=1}}},
  [82]={t="腐化之巢",d="好吧，你的报告中提到了虫子……我们现在知道的是……它们正使得原本是腐化之巢所在区域的水池变得干涸，其它方面我们一无所知。；首先我们要搞清楚敌人到底是谁！你得去腐化之巢那里，把那些虫子的肢体带回来给炼金师匹斯特苏格研究，这样我们就可以确定到底是谁在那里搞鬼了！",o="从腐化之巢找5个森提帕尔昆虫肢体，把它们交给加基森的炼金师匹斯特苏格。",p=992,r={{i=8587,n="森提帕尔昆虫肢体",c=5}}},
  [83]={t="红色亚麻布",d="北郡的迪菲亚盗贼戴粗麻布面罩，而艾尔文森林的迪菲亚盗贼戴的是亚麻布的，我可以用这些好的亚麻布做些东西。；给我找些亚麻布面罩，我可以用来给你做点什么。；有人在西南部的布莱克威尔南瓜田外看见过迪菲亚盗贼出没。",o="给东谷伐木场的萨拉·迪博雷恩带去6块红色亚麻布面罩。",r={{i=1019,n="亚麻布块",c=6}},f=1},
  [84]={t="比利的馅饼",d="这是你要的馅饼。把这东西交给那个比利的时候，别忘了告诉他我希望他吃了噎死！",o="把猪肉馅饼带给马科伦农场的比利·马科伦。",p=86,r={{i=962,n="猪肉馅饼",c=1}}},
  [86]={t="比利的馅饼",d="给我吃点馅饼，也许我就能想起来是谁拿着项链了。我知道另一个农场里的波尼斯老太太做的猪肉馅饼很棒……；我们的农场周围有野猪，如果你能给她找几块野猪肉，她就应该会给你烤一块馅饼。",o="给斯通菲尔德农场的波尼斯·斯通菲尔德带去4块野猪肉。",p=85,r={{i=769,n="大块野猪肉",c=4}}},
  [87]={t="金牙",d="我在法戈第矿洞旁边玩的时候，不小心掉了那根，呃……我是说我看见了那个老太太的项链。别问我它怎么会在那儿……和我没有关系！；不管怎样，我看到一个很壮实的镶着金牙的狗头人……他把项链捡起来跑到矿洞里了。你去找那个狗头人吧，我发誓，你肯定能在他身上找到项链的！",o="把波尼斯的项链带给斯通菲尔德农场的波尼斯·斯通菲尔德。",p=84,r={{i=981,n="波尼斯的项链",c=1}},f=1},
  [88]={t="公主必须死！",d="布拉克威尔一家有一头得过奖的猪，它名叫“公主”。这头母猪巨大无比，还经常偷偷溜到我的农场里偷吃我的蔬菜！；在它再次糟蹋了我的农场之前……必须把它给宰了！把它的项圈带回来证明你杀了它，我会给你一些奖赏的！；公主一般在布莱克威尔南瓜田出没，那个南瓜田就在东边，比马科伦农场还要往东。在它肚子饿了之前杀死她，然后再回来告诉我！",o="杀掉公主，把它的项圈带给斯通菲尔德农场的斯通菲尔德妈妈。",r={{i=1006,n="黄铜项圈",c=1}},w={{i=1173,n="饱受侵蚀的靴子",c=1},{i=1182,n="镶铜护腕",c=1},{i=11191,n="农夫之靴",c=1}},f=1},
  [89]={t="止水湖上的桥",d="上次兽人入侵的时候，我们被迫把所有能找到的铁都熔了来制造子弹、刀剑和盔甲。万不得已，我们向暴风城请求援助，让他们运一船金属材料过来。谁料一群赤脊山豺狼人劫持了运送金属的船只，并逃进了湖畔镇后的山中。；这样一来，我们这座桥的重修工程马上就要面临缺少材料的困境了。如果你能给我带回5根铁矛和5个铁铆钉，我一定会奖励你的。；快点去吧！",o="给湖畔镇的工头奥斯洛带回5根铁矛和5个铁铆钉。",p=125,r={{i=2856,n="铁矛",c=5},{i=1013,n="铁铆钉",c=5}},w={{i=1310,n="铁匠长裤",c=1},{i=1303,n="修桥工的手套",c=1},{i=1304,n="马术手套",c=1}},f=1},
  [93]={t="黑蟹蛋糕",d="我可以告诉你个秘密——黑“蟹”蛋糕实际上是用蜘蛛腿做的！听起来是有点恶心，不过这种蛋糕的味道绝对一流！给我找点粘糊的蜘蛛腿来，我很快就能给你做好。；听说结网毒蜘蛛身上很容易拿到这种东西——它们的巢穴就在东北部的丘陵和rn小河之间，暮色森林里的其它蜘蛛身上也有这东西。",o="收集6条粘糊的蜘蛛腿，把它们交给夜色镇的厨师格鲁奥。",p=5,r={{i=2251,n="粘糊的蜘蛛腿",c=6}}},
  [94]={t="法师的眼线",d="我的对手莫甘斯是个强大而邪恶的法师，他就住在赤脊山的伊尔加拉之塔里。我已经找到了一种监视他的方法，只要通过阿祖拉之眼，就可以在很远的地方看到他的一举一动。；不过要研究他的思想……我还需要进一步的帮助。；如果你愿意的话，就带着这个铭文饰品到伊尔加拉之塔去，把它放置在塔旁边的狮子雕像身上。；完成之后，阿祖拉的铭文饰品就会告诉我们，莫甘斯又在准备什么邪恶的计划。",o="把阿祖拉的铭文饰品放置到赤脊山伊尔加拉之塔旁边的狮子雕像身上。",r={{i=1083,n="阿祖拉的铭文饰品",c=1}}},
  [97]={t="斯塔文的传说",d="你，你赶快去告诉指挥官阿尔泰娅·埃伯洛克，这两个笔迹完全符合！她的怀疑是正确的！",o="把这个消息告诉指挥官阿尔泰娅·埃伯洛克。",p=80},
  [98]={t="斯塔文的传说",d="斯塔文·密斯特曼托是个恶贯满盈的罪犯，很多无辜的人都死在他手中。毫无疑问，他犯下了无数宗罪案，给夜色镇带来了又一个威胁。天知道这个恶棍又在策划什么邪恶的行动。斯塔文的家就在小镇北边，玩家，你去把他就地处死吧。；完事以后把他的系列戒指带给伊瓦夫人作为证明，毕竟是她的预感导致我们揭露了这个可怕的凶手，她为夜色镇立了一功。",o="干掉斯塔文·密斯特曼托，把他的系列戒指带给伊瓦夫人看看。",p=97,r={{i=3629,n="密斯特曼托家族戒指",c=1}},w={{i=2044,n="弃灵新月斧",c=1},{i=2043,n="弃灵之戒",c=1}},f=1},
  [99]={t="阿鲁高的愚行",d="在我对阿鲁高的魔法的越来越了解的同时，我对这个蠢货的鄙视与轻蔑也日益加深。我基本上完成了我对他所谓“拯救”的研究。；在我了解到是什么样的巫术导致了焚木村的奇怪现象之后，我也就算是了解透彻了。白天，那些农夫们都是好端端的人。但太阳一落山，他们就变成了月怒狼人。；我需要从阿鲁高给他们戴上的镣铐提取出一些能量来。带给我6副焚木镣铐，你。",o="给瑟伯切尔的达拉尔·道恩维沃尔带回6副焚木镣铐。",p=424,r={{i=3218,n="焚木镣铐",c=6}},w={{i=3586,n="削木斧",c=1},{i=3570,n="碾骨槌",c=1},{i=5242,n="灰烬魔杖",c=1}},f=2},
  [101]={t="惩罚图腾",d="有一股神秘而邪恶的势力在森林里蔓延，我们必须更加小心地保护自己，你。林中的夜风悄声告诉我，你很快就会遭遇巨大的危机。；尊贵的$c，如果你想保护自己，就请给我找来10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液。我会为你制作一个惩罚图腾，让那些企图伤害你的敌人自食其果。",o="收集10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液，把它们交给夜色镇的伊瓦夫人。",r={{i=1129,n="食尸鬼的牙齿",c=10},{i=1130,n="瓶装蜘蛛毒液",c=5},{i=2378,n="骷髅的手指",c=10}},f=1},
  [102]={t="西部荒野的豺狼人",d="暴风城已经把我们给遗弃了。一股腐朽与堕落的狂风正肆虐在西部荒野的平原之上。这里是我的故乡，我绝对不会背叛那些和我一样坚持留在这里的民众们。我们这些农夫必须站出来，为自己赢得生存的空间。；若你愿意接受我们派给你的任务，就去巡视西部荒野的草原吧。找到那些可恶的豺狼人，把它们干掉，似乎这些家伙与死亡矿井里的小贼们有些联系。给我带回八只豺狼人的爪子来，我会奖励你的英勇行为的。",o="给哨兵岭的丹努文队长带回8只豺狼人的爪子。",r={{i=725,n="豺狼人的爪子",c=8}},w={{i=1154,n="人民军腰带",c=1},{i=710,n="人民军护腕",c=1}},f=1},
  [104]={t="海岸上的威胁",d="当我的生命终结在了那片岩石上之后，我根本不知道死后的世界会是怎样的。那天晚上的灯塔一片漆黑，因为老瞎眼吓跑了管理员全家。他们本已经逃跑了，但那天晚上他们又回来想要点亮灯塔，结果老瞎眼带着一群野蛮的鱼人突袭了灯塔。这一次，管理员的全家都在我面前无助地死去了……；如果你在海岸边看到老瞎眼的话，就杀死它，把它的鳞片给我带回来，我会奖励你的。",o="将老瞎眼的鳞片交给西部荒野灯塔旁的葛瑞森船长。",r={{i=3636,n="老瞎眼的鳞片",c=1}},w={{i=1172,n="葛瑞森的火炬",c=1},{i=1557,n="深海圆盾",c=1},{i=5240,n="火炬魔杖",c=1}}},
  [105]={t="啊，安多哈尔！",d="啊，进攻安多哈尔并彻底击败那个巫妖的时刻终于来临了！；召唤者阿拉基就盘踞在安多哈尔的废墟中，他的贴身卫队无时无刻不在他的身边保护着他。你需要召集强大的盟友才能击败他。；消灭巫妖，你，从它的护符匣里拿出一块碎片来，作为你获胜的证据！",o="把阿拉基的护符匣碎片交给西瘟疫之地亡灵壁垒的高级执行官德灵顿。",p=5098,r={{i=17114,n="阿拉基的护符匣碎片",c=1}},f=2},
  [106]={t="年轻的恋人",d="天哪，我太痛苦了！我爱上了托米·乔·斯通菲尔德，但我们两家却有着不共戴天的仇恨。所以我不能去见他，可我无时无刻不在怀念那张英俊的面庞啊！；请你把这封信带给托米·乔，他一般会在斯通菲尔德农场西边的河流附近，他们的农场就在这里的正西方。",o="把梅贝尔的情书带给托米·乔·斯通菲尔德。",r={{i=1208,n="梅贝尔的情书",c=1}}},
  [107]={t="给威廉·匹斯特的信",d="威廉·匹斯特肯定有能让这两个年轻人见面的办法！；把这个便笺拿去交给威廉，他现在正住在闪金镇的狮王之傲旅店。",o="把斯通菲尔德老奶奶的便笺交给威廉·匹斯特。",p=111,r={{i=1252,n="斯通菲尔德老奶奶的便笺",c=1}}},
  [111]={t="托米的祖母",d="求求你，你，去和我的奶奶谈一谈吧。如果有人能想办法让我和梅贝尔在一起的话，那个人一定是奶奶。；她就在我们家的屋子里。",o="和斯通菲尔德农场的米斯通菲尔德老奶奶谈一谈。",p=106},
  [112]={t="收集海藻",d="我可以为梅贝尔配制一种隐形水，这样她就可以悄悄溜出马科伦农场去见托米·乔。不过我需要一些水晶海藻来配制这种药水。；水晶海藻一般生长在海里……不过有时候鱼人会收集它们。去看看水晶湖附近的鱼人身上有没有海藻，水晶湖就在闪金镇的东边。",o="收集4片水晶藻叶，把它们带给闪金镇的威廉·匹斯特。",p=107,r={{i=1256,n="水晶藻叶",c=4}}},
  [113]={t="昆虫研究",d="高级勘探员菲兹杜瑟必须尽快看到这份报告。实际上……每个人应该知道这件事的重要性：我们正面临着一个巨大的威胁，这个威胁不仅仅涉及到塔纳利斯和加基森，如果不及时控制的话，整个卡利姆多大陆的南部地区都会有麻烦！而且这个威胁显然已经迫在眉睫了。；让菲兹杜瑟把这份报告给你复制几份，然后你去把它广为传播。一定要让所有人都知道这个威胁的存在！",o="把这份报告带给加基森的高级勘探员菲兹杜瑟，让他按照炼金师匹斯特苏格的要求为你复制一份报告。",p=110,r={{i=8594,n="昆虫分析报告",c=1}}},
  [116]={t="旱季",d="我最近真是感觉有点没劲，你。这些酒瓶子都快空了，运酒的船也很久没来了，这都怪那些该死的兽人。；也许你帮我一个小忙？；我希望你能从住在西部荒野的葛瑞姆·雷酒那里搞一桶雷霆啤酒，从暴风城搞一桶葡萄酒，从夜色镇搞一瓶月光酒，还有还有，再从闪金镇搞一袋蜂蜜酒来。把这些好酒都给我弄来，我会重重谢你的。",o="湖畔镇的酒吧老板丹尼尔需要一桶雷霆啤酒，一桶葡萄酒，一瓶月光酒，还有一袋蜂蜜酒。",r={{i=1262,n="一桶雷霆啤酒",c=1},{i=1941,n="一桶葡萄酒",c=1},{i=1942,n="一瓶月光酒",c=1},{i=1939,n="一袋蜂蜜酒",c=1}},f=1},
  [118]={t="马掌",d="我把所有的铁都用来打造暴风城卫兵的装备，结果没有剩馀的铁来打马掌了！；把这封信带给闪金镇的铁匠阿古斯，信上说明了我现在的情况并要求他运一批马掌过来。",o="把弗纳的便笺交给艾尔文森林中闪金镇的铁匠阿古斯。",r={{i=1283,n="弗纳的便笺",c=1}}},
  [119]={t="回复弗纳",d="好的，我会给他送去50套马掌……；就是这些，你看，全部都打包好了，随时可以出发！告诉弗纳，我很高兴和他做生意，哦，对了，提醒他看清楚箱子上的标签！",o="回去找赤脊山湖畔镇的弗纳·奥斯古，把铁匠阿古斯的一箱马掌交给他。",p=118,r={{i=1284,n="一箱马掌",c=1}}},
  [120]={t="送往暴风城的信",d="这真是段难熬的日子呀，$c。兽人的攻势没完没了，如果援军还不来的话，湖畔镇就要保不住了！我现在委托给你的这封信是非常重要的。立刻将这份报告送给暴风城的马库斯·乔纳森将军。你把信送到了那边之后，就马上带着那边回复的消息回来，无论是好消息还是坏消息，我都要尽快知道。；现在就出发吧，快去快回！",o="所罗门镇长要求你给暴风城的马库斯·乔纳森将军送一封信，并且在完成任务之后尽快回报。",r={{i=1293,n="湖畔镇的现状",c=1}}},
  [121]={t="送往暴风城的信",d="在我等待着国王陛下的回应时，希望你能把这封信交给所罗门镇长。；快去吧，$c！",o="将暴风城的马库斯·乔纳森将军的回信带给湖畔镇的所罗门镇长。",p=120,r={{i=1294,n="将军的回信",c=1}}},
  [122]={t="雏龙的鳞片",d="我需要一些黑龙雏龙腹部的鳞片来支付从阿古斯那里买马掌的钱。如果你能帮我搞到6块鳞片的话，在付给阿古斯一些以后……我还能用剩下的给你做点好装备。；黑龙雏龙经常在湖畔镇南方游荡，猎杀它们的时候要多加小心。",o="从黑龙雏龙身上收集6片雏龙的腹鳞，把它们交给赤脊山的弗纳·奥斯古。",p=119,r={{i=1221,n="雏龙的腹鳞",c=6}},w={{i=6092,n="黑色雏龙战靴",c=1},{i=1302,n="黑色雏龙手套",c=1}},f=1},
  [123]={t="收货人",d="这是一张日程表，记录了某个人被称作“收货人”的人在某天某时会收到从艾尔文森林的矿洞运来的一车黄金。；根据日程表所述，这个收货人好像就住在艾尔文森林东部的布莱克威尔南瓜田附近。；这件事非常重要，你必须向闪金镇的治安官杜汉报告。",o="去闪金镇找治安官杜汉，把收货人的交易日程表交给他。",r={{i=2223,n="收货人的交易日程表",c=1}}},
  [124]={t="豺狼人的乱吠",d="似乎有这些整天攻城的兽人还不够乱！我发现最近老有一些混蛋豺狼人鬼鬼祟祟地沿着山脊在我的马场北面游荡，而且还偷我的马……；如果你能把这些豺狼人都干掉的话，我，还有我的马都会感谢你的。",o="杀掉10只赤脊山蛮兵和8只赤脊山秘法师，然后向弗纳·奥斯古复命。",p=119},
  [125]={t="丢失的工具",d="我本来可以在这儿大干一场的，你。可是，我的工具还没到货，由于镇子被包围了，我们很难得到外面来的补给。我本来托人从闪金镇把工具用马车运过来，可是桥被砸断了，他们只好改用船运，结果那船又被兽人的投石车给打沉了。不过，算是不幸中的万幸吧，我的工具箱没坏，它只是沉进了湖底。；帮我把工具箱找回来吧，你，我会付给你不错的酬劳的。",o="湖畔镇的工头奥斯洛希望你帮他找回沉入止水湖底的工具箱。",r={{i=1309,n="奥斯洛的工具箱",c=1}}},
  [126]={t="群山中的嚎叫",d="你，那些豺狼人居然还没死绝！我还能听见他们在湖畔镇周围的山区里打猎时发出的嚎叫声。其中有一个声音喊得最响——那是犹勒，他们的头儿。；干掉犹勒，把他的手下都给轰走！把这个混蛋的爪子给我带回来。；不过你得小心点，这家伙能当上他们的头儿自然是有两把刷子的。犹勒可不是个低能的混血豺狼人，他是纯种的……",o="将犹勒的爪子带回给湖畔镇的弗纳·奥斯古。",p=124,r={{i=3614,n="犹勒的爪子",c=1}},w={{i=1319,n="钢铁意志之戒",c=1},{i=2910,n="金色民兵靴",c=1}},f=1},
  [129]={t="免费的午餐",d="你能帮我一个小忙吗？我给卫兵帕克准备好了午饭，可他正在值勤……他是一个又高又壮的暴风城卫兵。他在外面是能自己保护自己的，可我们这样的寻常市民可不行，所以我没法去给他送饭……；所以呢，如果你能帮我把他的午餐带给他的话，我也会给你提供一份免费的午餐！帕克就在通往暮色森林的路上巡逻。",o="将卫兵帕克的午餐带给他，他就在通向夜色镇的路上巡逻。",r={{i=5534,n="帕克的午餐",c=1}}},
  [132]={t="迪菲亚兄弟会",d="我现在可是冒着生命危险在和你说话。迪菲亚那帮人也是听命于某个神秘人士的，我上次听说他们与许多种族都有过合作，豺狼人，狗头人，甚至还有地精。；把这张便笺交给斯托曼。上面写着我所知道的关于迪菲亚兄弟会的一切。",o="将威利的便笺交给西部荒野的格里安·斯托曼。",p=65,r={{i=1327,n="威利的便笺",c=1}}},
  [133]={t="食尸鬼假人",d="我住得离镇子太远了，根本得不到保护。那些食尸鬼和行尸走肉还没有把我吃掉简直是个奇迹！其实昨天还有一群噬骨者来敲击我房子四周的墙！；我得做个假人，一个用来吓唬食尸鬼的“稻草人”。我需要食尸鬼的肋骨来制作这个假人。你可以从食腐者、噬骨者、食脑者、腐烂者和瘟疫食尸鬼身上拿到这东西。；给我带足够的肋骨来，我就会给你一些奖赏。",o="收集7个食尸鬼的肋骨，然后把它们交给亚伯克隆比。",p=159,r={{i=884,n="食尸鬼的肋骨",c=7}}},
  [134]={t="食人魔盗贼",d="几个星期前，我离开家去远处采草药，有一群食人魔袭击了我！我落荒而逃的时候丢了一箱工具和草药。；这些食人魔在把我赶跑之后大摇大摆地回到了暮色森林南边的食人魔山上，我的箱子肯定就在那一带。；请帮帮我吧，你，我很需要这个箱子，请你一定要帮我拿回来。",o="把亚伯克隆比的箱子拿回来交给他。",p=133,r={{i=1349,n="亚伯克隆比的箱子",c=1}}},
  [135]={t="迪菲亚兄弟会",d="我现在很想知道威利所提到的“石匠”是个什么意思，或许这只是一个口误？石匠公会跟迪菲亚真的有联系吗？或许暴风城军情七处的首领马迪亚斯·肖尔会知道真相。把威利的便笺拿给他，看看他对这个越来越大的谜团有什么想法吧。他就在旧城区的兵营里。",o="将威利的便笺交给暴风城的马迪亚斯·肖尔。",p=132,r={{i=1327,n="威利的便笺",c=1}}},
  [140]={t="Captain Sander's Hidden Treasure",o="Locate Captain Sanders' chest and open it for your reward.",p=139},
  [141]={t="迪菲亚兄弟会",d="过去的石匠公会是由一个名叫艾德温·范克里夫的人运营着的。第一次兽人战争结束后，范克里夫承接下了在兽人们留下的废墟上重建暴风城的重任。很显然，范克里夫对国王陛下在重建工程完成之后给予他们的待遇非常不满意。总之，解释这一大堆具体的事情要花些时间。；我这里有一份详细的说明，让你拿到西部荒野去交给你的雇主。你得马上把这个给他带去！",o="将肖尔的报告交给西部荒野的格里安·斯托曼。",p=135,r={{i=1353,n="肖尔的报告",c=1}}},
  [142]={t="迪菲亚兄弟会",d="我们必须得找到迪菲亚兄弟会藏身的地方。你，我的探子报告说，迪菲亚帮的信使们经常出现在月溪镇、金海岸矿洞和詹戈洛德矿洞之间的路上。我希望你能抓住一个信使，要是他试图反抗，就干脆把他干掉，然后把他身上所有的东西带回来。",o="追捕西部荒野的迪菲亚信使，并将他身上携带着的信件交给斯托曼。",p=141,r={{i=1381,n="神秘的信件",c=1}}},
  [143]={t="送往西部荒野的信",d="暴风城的军队似乎遇到了些麻烦事，他们早就该到这里增援了，但直到现在还连个人影都没有。我们没多少时间可供浪费了！我不能再这样坐视人民继续无谓地牺牲而不去要求更多的增援。我听说西部荒野组建了一支民兵部队。；把这封信带给他们的领袖格里安·斯托曼。或许斯托曼的人在国王陛下的部队到达之前能来帮忙抵挡上一阵。",o="所罗门镇长要求你给西部荒野的格里安·斯托曼送一封信。",p=121,r={{i=1407,n="所罗门写给西部荒野的求救信",c=1}}},
  [144]={t="送往西部荒野的信",d="所罗门镇长的信让我感到心痛。但显然他并不知道西部荒野的战事也很吃紧——或者他知道，但不得不抱着一丝希望来寻求我们的帮助。如果不是暴风城对西部荒野的人民不闻不问的话，我们也不会需要创建民兵组织的。；将这封回信带给你在赤脊山的主人吧，$c。请转告他，我的心情也因为那么多勇士的牺牲而变得十分沉重。",o="将格里安·斯托曼的回信带给所罗门镇长。",p=143,r={{i=1408,n="斯托曼的回信",c=1}}},
  [145]={t="送往夜色镇的信",d="看来我又得有事麻烦你了。我写一了封信给艾尔罗·埃伯洛克公爵，请求他从他的精锐部队——暮色森林守夜人——中抽出一些人来协助湖畔镇的防务。这封信必须马上呈送给他，而且你在旅途中要多加小心。埃伯洛克公爵是夜色镇的行政官，那座小镇就在暮色森林中，小心不要迷路了。",o="所罗门镇长要求你给夜色镇的艾尔罗·埃伯洛克公爵送一封信。",p=144,r={{i=1409,n="所罗门写给夜色镇的求救信",c=1}}},
  [147]={t="猎杀收货人",d="如果这个“收货人”是私自从我们的矿洞里开采黄金的话，那么他就是在偷窃王国的金库！把他就地正法，然后把他的交易日程表上提到的戒指带给我。也许这枚戒指能告诉我们这个“收货人”是在为谁工作……；那张交易日程表上说“收货人”就藏在布莱克威尔南瓜田里，你应该到那儿去找他。",o="找到“收货人”并将他杀掉，然后带着收货人的戒指回来见治安官杜汉。",p=123,r={{i=2239,n="收货人的戒指",c=1}},w={{i=1360,n="暴风城链甲手套",c=1},{i=1183,n="橡皮腕甲",c=1}},f=1},
  [149]={t="幽灵的发丝",d="有个可怜的亡魂叫盲眼玛丽，她总是在夜色镇南部小山上的农宅里出没。；拿着这把鬼梳，让盲眼玛丽用它梳头。然后再把梳子拿回来，我可以从上面收集到需要的幽灵的头发。；小心点，那个屋子里潜伏着一些可怕的东西……",o="把鬼梳带给盲眼玛丽。",p=148,r={{i=1453,n="鬼梳",c=1}}},
  [150]={t="鱼人偷猎者",d="鱼人们如今也成了一个问题。大群的鱼人渔民在止水湖沿岸下锚撒网，都快把湖里的鱼捞光了！我们得在他们把湖里的鱼都吃光之前把他们赶走！；去猎杀那些鱼人！给我带回8片鱼人的鳍来，我会奖励你的。",o="给湖畔镇的码头管理员巴伦带回8片鱼人的鳍。",r={{i=1468,n="鱼人的鳍",c=8}},f=1},
  [151]={t="老马布兰契",d="可怜的老马布兰契呀！我们让它干的活儿实在是太多了，看来它已经要累垮了。虽然我在离开农场以前就喂过了它，可谁会料到马车会在半路上坏掉呢？如果你能从田里替它取来几捧燕麦的话，我会对你感激不尽的。我想，你可以在田边找到足够的燕麦，不过你首先要将周围那些可怕的机器人先干掉。",o="西部荒野的弗娜·法布隆要求你带给她8捧燕麦。",r={{i=1528,n="一捧燕麦",c=8}},f=1},
  [153]={t="红色皮质面罩",d="我们与迪菲亚兄弟会的战局总是瞬息万变。最近我一直在监视着他们的活动，根据长期观察的结果，我发现他们的成员都戴着一种特殊的红色皮质面罩。；给我带15条这种面罩回来吧，我会给你奖励的。",o="给哨兵岭的哨兵加里安带回15条红色皮质面罩。",r={{i=829,n="红色皮质面罩",c=15}},w={{i=3511,n="人民军披风",c=1},{i=5944,n="人民军胫甲",c=1},{i=12295,n="人民军护腿",c=1}},f=1},
  [154]={t="归还梳子",d="不！！！！！；快把这个梳子拿走！；我是个怪物，不会再有人说我好看了！",o="把幽灵的梳子拿回去交给夜色镇的伊瓦夫人。",p=149,r={{i=1518,n="幽灵的梳子",c=1}}},
  [155]={t="迪菲亚兄弟会",d="这么说，斯托曼就派了你这么一个芦柴棒一样的家伙来保护我？希望你能行，当然如果你再叫上几个朋友帮忙就好了。；你知道你要做些什么吧？我会把你带到迪菲亚盗贼的巢穴去，而你呢，就得保护好我。当然，你最好离我近点，越近越好。现在全迪菲亚兄弟会的人都想要我的脑袋呢。要是他们看见我和你在一起，一定会来把咱们都宰了的。；等你和你的朋友准备好之后，就来跟我说一声吧。",o="护送迪菲亚叛徒转至迪菲亚兄弟会的秘密藏身处。迪菲亚叛徒把你带到范克里夫和他的手下的巢穴之后，尽快回去向格里安·斯托曼汇报相关信息。",p=142},
  [156]={t="收集腐败之花",d="如果你能给我找些腐败之花来，我就可以酿造很多僵尸酒。；这种花很难找到，听说在恐怖骸骨和骸骨魔的头骨里可以找到这种花……不过至今我还没有亲眼见过！；乌鸦岭墓地和静谧花园里都有很多这样的骷髅，你可以在寻找腐败之花的时候顺便把他们干掉，夜色镇的人民会感激你的。",o="收集8个腐败之花，交给夜色镇的旅店店主斯密茨。",p=158,r={{i=1598,n="腐败之花",c=8}}},
  [157]={t="幽灵的发丝",d="这是你要的线，你。它有很多种用途，比如用来束缚邪恶的亡魂，或者给没有生命的东西注入生命。",o="把幽灵的发丝交给亚伯克隆比，他住在乌鸦岭墓地北边的房子里。",p=154,r={{i=1596,n="幽灵的发丝",c=1}}},
  [159]={t="僵尸酒",d="这是你要的僵尸酒……；不过要小心一点，这酒烈得足以把死人给呛活过来。",o="把僵尸酒交给乌鸦岭墓地北方小屋里的亚伯克隆比。",p=156,r={{i=1451,n="一瓶僵尸酒",c=1}}},
  [160]={t="给镇长的信",d="请把这封信交给夜色镇的艾尔罗·埃伯洛克镇长。；我和他是老朋友了……我敢说，当他读完信，并且知道了你为我做的事情……他一定会和我一样高兴的！哈哈哈哈！",o="把亚伯克隆比的信交给夜色镇的艾尔罗·埃伯洛克镇长。",p=134,r={{i=1637,n="写给艾尔罗的信",c=1}}},
  [161]={t="水坝危机",d="如果我的猜测没错的话，这是某种火药粉末。应该找个爆破专家来分析一下这到底是什么东西。阿什兰·暗石就在丹莫德和萨多尔大桥一带负责那里的警戒工作，我需要你尽快去找他，这是一段重要而危险的旅程，你。；走过奥加兹大门，沿着穿过湿地的大路一直到丹莫德去找爆破专家阿什兰·暗石。留心我的建议：沿着大路走，不要停留！",o="主工程师辛德维尔七世要你把怪味粉末交给湿地中丹莫德的炸药专家阿什兰·暗石。",p=199,r={{i=2563,n="怪味粉末",c=1}}},
  [166]={t="迪菲亚兄弟会",d="这里恐怕还有最后一个任务需要你来完成。我们必须派人去除掉艾德温·范克里夫。说实话，就这样对一个活生生的人宣判死刑，这实在令我非常痛心，但为了西部荒野人民的利益，我不得不让范克里夫永远安息。把范克里夫干掉之后，提他的头来见我。",o="杀死艾德温·范克里夫，把他的头交给格里安·斯托曼。",p=155,r={{i=3637,n="范克里夫的徽记",c=1}},w={{i=6087,n="西部荒野马裤",c=1},{i=2041,n="西部荒野外套",c=1},{i=2042,n="西部荒野法杖",c=1}},f=1},
  [167]={t="我的兄弟……",d="那时我们正在一个大矿洞中工作，就是那个隐藏在西部荒野月溪镇中的谷仓下面的矿洞……没人知道当时到底是怎么回事，总之矿道突然坍塌了，我逃了出来……可其它人就没那么好运了……我是说，从那以后我就再没听到过其它人的消息了。；看上去你的运气可能会比我们好一点。如果你能帮我找到弟弟的话，我会非常感谢你的。他总是戴着一块探险者协会徽章，所以如果你找不到他的话，至少那块徽章能给我带来一些安慰……",o="将工头希斯耐特的探险者协会徽章交给暴风城的维尔德·蓟草。",r={{i=1875,n="希斯耐特的徽章",c=1}},f=1},
  [168]={t="收集记忆",d="在那个可怕的日子，我的许多朋友都被埋在了矿洞里。如果你在冒险中正好路过月溪镇的那处矿洞的话，请帮忙留意一下有没有什么可以辨认他们身份的标志物品。如果你能找到他们的矿业工会会员卡的话，请一定要带给我，我好知道他们的结局，并与他们的家人谈谈如何为这次恐怖的事故善后。",o="给暴风城的维尔德·蓟草带回4张矿业工会会员卡。",r={{i=1894,n="矿业工会会员卡",c=4}},w={{i=2037,n="掘地工之靴",c=1},{i=2036,n="陈旧的矿工手套",c=1}},f=1},
  [170]={t="新的威胁",d="我希望你能帮我们一把，$c。在上一次穴居人袭击之后，我们的人手就明显不够了。；我听说他们现在已经遍布我们的国土，看来寒脊山谷也不能避免。东南部的山区和湖畔已经到处都是穴居人的身影了。；糟糕的事情还不仅仅是这些，几天前，他们袭击并占领了我们西边的营地！；我们这儿有些人手不足，$g孩子:姑娘;，我们需要强大的军队帮助我们赶走这些家伙。",o="巴尔林·霜锤让你去杀死6个石腭穴居人和6个壮实的石腭穴居人。",p=179,w={{i=6185,n="熊皮披肩",c=1},{i=2172,n="乡村腰带",c=1},{i=6173,n="棉鞋",c=1}},f=1},
  [173]={t="森林里的狼人",d="黑暗的势力正在笼罩暮色森林，而卡尔文主人正在努力驱除邪恶，保护夜色镇人民的安全是我们的职责。；你觉得自己有能力加入我们吗？；我以前也跟你想的一样，因为对哨所的安逸悠闲感到绝望，我投靠了卡尔文主人。如果你想要证明自己的实力，不是只靠嘴皮子说说就可以的。；去找夜行织影狼人较量较量吧，他们经常在阳光树林——阳光，哈！——和烂果园出没。",o="为夜色镇的卡洛尔杀掉6个夜行织影狼人。"},
  [174]={t="仰望星空",d="我的侏儒朋友考格说过要帮我制造一个可以用来观察星空的装置。我相信除了魔法之外，还有别的理由可以解释发生在这片森林中的奇怪变化。；根据考格的设计图，首先要去找一个手艺高超的技师，让他帮忙造一根青铜管。",o="夜色镇的维克托·安特拉斯要你给他找一根青铜管。",r={{i=4371,n="青铜管",c=1}}},
  [176]={t="通缉：霍格",d="通缉：霍格；巨型豺狼人霍格，现正在艾尔文森林西南部的树林里游荡。他成功地对抗了当前为止所有追捕他的行动。；暴风城已经为除去这只豺狼人设下了酬金，想得到酬金的猎手必须向闪金镇的治安官杜汉提供杀死霍格的证据。",o="杀死豺狼人霍格，把他那巨大的豺狼人爪带给治安官杜汉。",r={{i=1931,n="巨大的豺狼人爪",c=1}},w={{i=6085,n="步兵外衣",c=1},{i=6084,n="暴风城卫兵护腿",c=1},{i=6215,n="平衡长棍",c=1}},f=1},
  [177]={t="仰望星空",d="那副眼镜是我最珍贵的宝物，不过在发生了一件事情之后……我就把它丢在谷仓后面了。有个疯狂的食尸鬼曾经在那一带徘徊，可能是它把东西给捡走了。有人说那个邪恶的家伙住在静谧花园墓场出现。",o="从疯狂的食尸鬼那里拿回盲眼玛丽的眼镜，把它交给夜色镇的维克托。",p=175,r={{i=1946,n="玛丽的眼镜",c=1}}},
  [179]={t="矮人的交易",d="嘿，你是新来的吧？看来你需要些暖手的东西，对吗？；我想你应该想要一副保暖的手套。我是个热心肠，很愿意给你一副手套，不过我有个条件。；你帮我弄些狼肉来，我保证你不会被冻掉手指头。你觉得怎么样？",o="斯登·粗臂想要8块硬狼肉。",r={{i=750,n="硬狼肉",c=8}},w={{i=719,n="驯兔手套",c=1},{i=6171,n="驯狼手套",c=1},{i=2547,n="驯猪手套",c=1}},f=1},
  [181]={t="仰望星空",d="根据考格的设计图，现在我们还需要一种透镜来完成整个装置。我知道什么地方有合适的透镜，不过很难拿到。；有个叫扎克乌尔的食人魔住在暮色森林南部的土丘上，如果可以的话，你去把他的单片眼镜拿来吧，我可以用它做透镜。",o="在暮色森林南部的食人魔土丘上找到扎克乌尔，把他的单片眼镜带回夜色镇交给维克托。",p=177,r={{i=1968,n="食人魔的单片眼镜",c=1}},w={{i=7106,n="黄道手套",c=1},{i=7107,n="群星腰带",c=1}},f=1},
  [182]={t="巨魔洞穴",d="我和我的兄弟森内尔被派来调查丹莫罗各个地区的巨魔活动情况。参议院正在忙着对付那些不知道从哪里冒出来的穴居人，已经没工夫再关心巨魔了。；据我所知，在寒脊山谷南部山洞里生活的巨魔们日子并不好过，所以我觉得派大批军队去围剿它们是杀鸡用牛刀，只要一两支训练有素的小分队就已经绰绰有馀了。；你也许能给我们提供些帮助吧？当然，我会对你的帮助给予一定的报酬。",o="格瑞林·白须要你去杀掉10个霜鬃巨魔幼崽。",w={{i=2047,n="安威玛尔手斧",c=1},{i=2048,n="安威玛尔钉锤",c=1},{i=2195,n="安威玛尔匕首",c=1},{i=5761,n="安威玛尔战锤",c=1}},f=1},
  [183]={t="猎杀野猪",d="没什么能比得上用一整天的时间去打野猪更让人愉快的了，对吧？不过，寒脊山谷里的野猪太多了，你几乎已经不可能在那里再感受到狩猎的乐趣。你根本不需要去激怒它们，因为它们早就是怒气冲天，随时准备用獠牙把你拱上天了！事实上，这些过剩的野猪已经对我的日常狩猎形成了威胁。；长话短说吧，如果你能帮我杀掉些野猪，我真的会非常感激你的。",o="塔林·锐眼让你去杀掉8只规模峭壁野猪。",w={{i=79,n="矮人布质短裤",c=1},{i=61,n="矮人皮质短裤",c=1}},f=1},
  [185]={t="猎虎",d="当我还只是个小女孩的时候，我的父亲就开始训练我捕猎老虎。；一般来说，你会发现虎崽是非常容易追踪和猎杀的。因此，要猎杀它们根本不是什么麻烦的事情，你在探险队的营地附近很容易就能找到虎崽。；让我们来测试一下你的追踪技巧，看看你是否能猎杀这些野兽。",o="奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎幼崽。",p=583},
  [186]={t="猎虎",d="你学得很快，$c。让我们来测试一下你是否能杀死成年的猛虎，这次你的任务是去杀死十只荆棘谷猛虎。",o="奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎。",p=185},
  [187]={t="猎虎",d="现在我要教你些更高深的东西，然后测试一下你的技巧。去杀死十只老年荆棘谷猛虎以证明你的能力吧。如果你能做到这些的话，你就可以去面对最后的挑战了，最终，我会在奈辛瓦里大人的面前授予你猎虎大师的称号。；老年荆棘谷猛虎不但非常难找，而且也是最难以对付的。",o="奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只老年荆棘谷猛虎。",p=186},
  [188]={t="猎虎",d="现在你要面对的将是最后的挑战。我们这几周来一直在追踪一只神秘的老虎，我们称它为辛达尔。现在让我们来看看你能不能做到一件以前从来没有任何$r可以做到的事吧：去猎杀辛达尔，把它的爪子带回来以证明你完成了任务。；追踪它可不是一件简单的任务。",o="奈辛瓦里远征队的艾耶克·罗欧克要求你杀死辛达尔并带回它的爪子。",p=187,r={{i=3879,n="辛达尔的爪子",c=1}}},
  [189]={t="血顶巨魔的耳朵",d="该死的巨魔！他们杀死了我们派到丛林里去的人！我已经在和他们的冲突中损失太多优秀的护卫了。血债必须血来偿！这让我怎么向大财主里维加兹解释呀？；是该做决定的时候了……想想看，科博克……你可不是被派到这里来整日无所事事的……啊，有啦！你……你就是$n，是不是？你是来帮助我的，是不是？这份工作的奖励可是很丰厚的哦！；嗯嗯，给我带15只血顶巨魔的耳朵来，我就重重地酬谢你，如何？",o="给藏宝海湾的科博克带回15只血顶巨魔的耳朵。",r={{i=1519,n="血顶巨魔的耳朵",c=15}}},
  [190]={t="猎豹",d="如果你也想加入这个由赫米特先生组建的最强狩猎队，就必须先证明自己是一个能干的猎豹高手。放心，一开始不会太难的，千万别轻言放弃。你先去猎杀10只猎豹幼崽热热身吧。；当然，这只是让你热热身而已……",o="奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只猎豹幼崽。",p=583},
  [191]={t="猎豹",d="现在你已经可以更进一步了。如果你想继续证明自己有资格和我们这些优秀的狩猎能手合作的话，就去猎杀十只黑豹。；这些大家伙们都很强壮，它们可不比之前的猎豹幼崽那么好杀。",o="奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只黑豹。",p=190},
  [192]={t="猎豹",d="接下来的部分可就比较困难了。一个真正的猎豹能手必须要有能力杀死深喉猎豹这种荆棘谷中最危险的生物。去杀死十只深喉猎豹，向我们证明你的猎豹能力吧！；如果你很难找到它们的踪迹的话，就埋伏起来等它们出现……",o="奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只深喉猎豹。",p=191},
  [193]={t="猎豹",d="你几乎已经证明自己是一位优秀的猎豹能手了。有一只名叫巴尔瑟拉的豹子当前正潜伏在这片森林里，我们一直都没能找到它。去试试猎杀巴尔瑟拉吧，记得用上你所掌握的全部技巧。；将巴尔瑟拉的牙齿带回来给我，如果你成功了，你就将赢得我的尊敬！",o="奈辛瓦里远征队的埃尔加丁爵士要求你杀死巴尔瑟拉，并带回它的牙。",p=192,r={{i=3876,n="巴尔瑟拉的牙齿",c=1}}},
  [194]={t="猎龙",d="你觉得你的狩猎技术是最顶尖的？我马上就检验一下，看看你是不是在骗人。到丛林里去杀几只荆棘谷迅猛龙，这样一来我们就知道你是不是所谓的王牌猎人了。；当然，我是绝对不会告诉你在哪里才能找到它们的！追踪野兽本身就是挑战的一部分。",o="赫米特·奈辛瓦里二世要求你杀死10只荆棘谷迅猛龙。",p=583},
  [195]={t="猎龙",d="现在让我们来看看你能不能应付更大的挑战吧。杀进丛林里去，给我干掉十只残暴的鞭尾迅猛龙。可别说你不行啊！",o="赫米特·奈辛瓦里二世要求你杀死10只鞭尾迅猛龙。",p=194},
  [196]={t="猎龙",d="让我们来看看你能不能对付下一个挑战吧。这附近栖息着一种非常狡猾的迅猛龙，我们叫它丛林捕猎者。它们远比你之前捕猎的目标更难追踪和猎杀。猎杀十只丛林捕猎者，然后我就会告诉你这里最惹眼的目标是什么。",o="赫米特·奈辛瓦里二世要求你杀死10只丛林捕猎者。",p=195},
  [197]={t="猎龙",d="你已经证明了自己在这片丛林里的每次捕猎都不会空手而归，总能带回我们要求的猎物，因此我决定告诉你有关那只我从来也没能猎到的、最凶暴最残忍的迅猛龙的事情，艾耶克把那只迅猛龙叫作泰希斯。；如果你想证明自己真的是个捕猎专家的话，就把泰希斯杀掉，把它的爪子给我带回来，这可是其它王牌猎人都从没完成过的壮举。",o="赫米特·奈辛瓦里二世要求你杀死荆棘谷中最危险最狡猾的迅猛龙泰希斯。",p=196,r={{i=3877,n="泰希斯的爪子",c=1}}},
  [199]={t="水坝危机",d="你取了些怪味粉末的样品。",o="回去见主工程师辛德维尔七世，把你找到的线索交给他。",p=250,r={{i=2563,n="怪味粉末",c=1}}},
  [202]={t="库尔森上校",d="你一次又一次地证明了自己的能力，而你的足智多谋略似乎甚至能与库尔森媲美。如果……如果你愿意彻底投身到与库尔森斗争的事业中去的话……也许你将成为我们反抗军的救星！；他就躲在那个名叫“储藏室”的洞穴深处发号施令。你必须进入那个洞穴，干掉他身边的保镖，最终把库尔森和他的副官们都给除掉。；出发吧，你。我们的生命与希望，如今都已经全部掌握在你的手中了。",o="杀掉6名库尔森精英和4名库尔森副首领，并将库尔森的徽记交给反抗军营地里的多伦上尉。",p=574,r={{i=3615,n="库尔森的徽记",c=1}},f=1},
  [204]={t="库尔森的药物",d="要想和库尔森搏上一搏，我们就必须削弱他们的医疗队伍。他在那里聚集了大批医疗人员，他们能用密林药剂治疗自己的部队，并用毒草汁液对我们的人下毒。；我们要用这些药物来治疗我们自己的战士，同时我们也需要一份毒液的样本来研制解药。到库尔森的营地去把这两样东西找来吧，药品应该就在那些医疗人员和战士的身上，而毒草汁液大概是保存在营地中的一些物资箱里的。",o="给反抗军营地里的尤瓦中士带回7份密林药剂和1份毒草汁液。",r={{i=2633,n="密林药剂",c=7},{i=2634,n="毒草汁液",c=1}},w={{i=4140,n="棕榈叶肩垫",c=1},{i=4126,n="游击队之刀",c=1}},f=1},
  [206]={t="麦佐斯",d="库尔森的确是该死，不过……到底是谁将他带上了这条邪恶的道路呢？通过研究，我已经找到了真相：是一个名叫麦佐斯的食人魔法师干的。他住在荆棘谷东部的食人魔山中，据说他擅长心灵控制魔法，我也确信正是他使得库尔森上校堕落的。；如果麦佐斯继续活在这世上，他的邪恶法术就有可能影响到更多人，或许又会出现另一个库尔森上校。；杀死他，把他的心灵之眼带回来，这正是他用来诱惑他人堕落的物品。",o="将心灵之眼交给反抗军营地里的尼麦兹修士。",r={{i=3616,n="心灵之眼",c=1}},f=1},
  [207]={t="库尔森的秘密",d="库尔森上校曾是个伟大而高贵的人，我必须得找到让他堕落至此的原因！他一定是被巨魔的魔法给控制了。要想搞清楚这一点的话，我们就得先研究一下巨魔的传说故事。；据说荆棘谷中的巨魔遗迹中隐藏着四块石板，我必须得看看这些石板上到底记述了些什么东西！你去给我拓一份这些石板上的文字来，把拓片都交给我。；第一块石板在巴拉尔废墟里，第二块石板在暗礁海的海底，第三块和第四块应该都在祖昆达废墟里。",o="找到4块石板并将上面的内容带回去交给尼麦兹修士。",r={{i=2005,n="巨魔传说第一章",c=1},{i=2006,n="巨魔传说第二章",c=1},{i=2007,n="巨魔传说第三章",c=1},{i=2008,n="巨魔传说第四章",c=1}}},
  [208]={t="王牌猎人",d="你，你现在已经成为了一位够格进入我们狩猎队的猎手了。无论是洛丹伦的战场还是危机四伏的丛林，我在哪里都没有见过有谁能像你这样拥有如此强大的战斗能力。；你成功地杀死了凶残的辛达尔，狡猾的巴尔瑟拉和强悍的泰希斯。但对于这片丛林中的猎人们来说，虎王邦加拉什的头才代表着至高无上的荣耀。这只白虎正是我来这里的原因，我注意它已经很久了。如果你能杀死虎王邦加拉什，那么你无疑是这里最优秀的猎人。",o="赫米特·奈辛瓦里二世要求你将虎王邦加拉什的头带回来给他。",r={{i=3880,n="邦加拉什的头",c=1}},w={{i=17686,n="狩猎高手的猎弓",c=1},{i=17687,n="狩猎高手的火枪",c=1}}},
  [210]={t="克拉兹克的烹调锅",d="在营地里，我是专门负责伙食的。过去的活真的很多，让我每天都要忙到死，直到我从藏宝海湾的地精商人那里买了台多功能机械烹调锅才有所改观。这锅实在是太棒了！它节省了我许多的时间……我是说，在它坏掉之前！；你能帮我把这锅带到那个地精商人那里去，让他给我修理一下吗？他的名字叫克拉兹克。",o="把克拉兹克的烹调锅带给藏宝海湾的地精克拉兹克。",r={{i=4085,n="克拉兹克的烹调锅",c=1}}},
  [211]={t="啊，安多哈尔！",d="啊，进攻安多哈尔并彻底击败那个巫妖的时刻终于来临了！；召唤者阿拉基就盘踞在安多哈尔的废墟中，他的贴身卫队无时无刻不在他的身边保护着他。你需要召集强大的盟友才能击败他。；消灭巫妖，你，从它的护符匣里拿出一块碎片来，作为你获胜的证据！",o="把阿拉基的护符匣碎片交给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。",p=5097,r={{i=17114,n="阿拉基的护符匣碎片",c=1}},f=1},
  [213]={t="恶性竞争",d="太猖狂了！吉尔里兹把贸易亲王们指定的要员们都从这里赶了出去，这件事已经够糟的了，现在他居然还和那些声名狼籍的海盗们往来！；里维加兹不会坐视不理的，他允许我按自己的方式来解决这些问题。；我的方式是什么？偷！最近，风险投资公司的地质学家们正在研究他们从矿里挖出的一种奇怪的蓝色水晶，从那群地质学家手里搞些样本回来给我，当然，我不关心你用怎样的手段去搞。",o="给藏宝海湾的科博克带回8块打磨过的水晶。",r={{i=4106,n="打磨过的水晶",c=8}}},
  [214]={t="红色丝质面罩",d="迪菲亚兄弟会的人都会戴着一种红色的面罩，这显然已经是个尽人皆知的秘密了。但我们又了解到，这个面罩的材料是他们的成员在帮会内部地位的象征。；既然如此，那么我希望你出马杀死一些兄弟会的高阶成员。他们的最高阶成员无疑都躲在范克里夫的秘密藏身处附近。作为证据，你要给我带回10条红色丝质面罩来，这样我才能给你奖励。祝你好运，你。",o="给哨兵岭哨塔的哨兵瑞尔带回10条红色丝质面罩。",p=155,r={{i=915,n="红色丝质面罩",c=10}},w={{i=2074,n="结实的短剑",c=1},{i=2089,n="贝雕匕首",c=1},{i=6094,n="破甲之斧",c=1}},f=1},
  [216]={t="蓟皮熊怪的麻烦",d="蓟皮熊怪在威胁我们的扩张！我们东面的蓟皮村挡住了从这里通往碎木哨岗的道路，这是一条可以包围阿斯特兰纳的道路，没有它，我们就会让联盟得到一条额外的扩张路线。；你我们决不允许有这样的缺口存在！；进入蓟皮村，尽量减少那些熊怪的数量。你会为这项任务得到补偿的，但更重要的是，你会为部落尽到你的职责！",o="杀死8个蓟皮复仇者和8个蓟皮萨满祭司。他们大部分都位于佐拉姆海岸东部的蓟皮村里。任务完成后回到灰谷佐拉姆加前哨站的卡拉恩·阿玛卡那里复命。"},
  [217]={t="保卫国王的领土",d="你，我的侦察兵已经找到了最近一段时间来频频组织穴居人对我们发动袭击的首领。这帮洛克莫丹的怪物好象是由一个叫格劳姆格的酋长领导的，不过格劳姆格身边守卫森严，有两个精英护卫纳什尔和布劳勒尔从不离他左右。；如果你想证明自己的价值的话，你，我希望你能接下杀掉格劳姆格和他那两个手下的任务。一旦穴居人失去了领导，我们就有机会把这些怪物重新赶回地下。",o="杀掉穴居人首领格劳姆格及他的两个护卫，纳什尔和布劳勒尔。然后回到南部警戒塔向拉格弗斯上尉报告。",p=263,w={{i=1436,n="戍边长裤",c=1},{i=6187,n="矮人防御者",c=1},{i=1832,n="幸运长裤",c=1}},f=1},
  [218]={t="被窃取的日记",d="我的日记！那帮巨魔把它拿到洞穴里去了。拿着日记的那个家伙……他是一个皮肤和面颊上都涂着奇特印记的青面獠牙的家伙，我打从娘胎里出来后还没见过像他那样丑的。；你应该能对付那些巨魔，帮我把我的日记拿回来怎么样？",o="格瑞林·白须要你去杀掉冷酷的格瑞克尼尔，并取回他的日记。",p=182,r={{i=2004,n="格瑞林·白须的日记",c=1}},w={{i=6176,n="矮人鸢盾",c=1},{i=5581,n="光滑的手杖",c=1}},f=1},
  [219]={t="失踪人员",d="终于…有人来了……来自联盟的朋友！；救救我…求你了…；我只记得…一群邪恶的兽人让我们团全军复没……大多数人都被杀了，我的头被狠狠地打了一下，眼前一黑就倒下去了。现在我被关在这个洞里，奄奄一息……；我必须得回到镇上去…拜托了…你是我最后的希望了……",o="保护基沙恩下士回到赤脊。",w={{i=3555,n="所罗门法袍",c=1},{i=1275,n="军官链甲外衣",c=1},{i=3431,n="骨钉皮甲",c=1}},f=1},
  [220]={t="水之召唤",d="在给你图腾之前，伊斯伦还会有一个任务让你去完成。我给你的那瓶水在任何情况下都会很有用。；去吧，去找伊斯伦。我们会再见的。",o="把一瓶最纯净的水交给贫瘠之地提度斯阶梯的水之先知伊斯伦。",p=1534,r={{i=7810,n="一瓶最纯净的水",c=1}}},
  [221]={t="森林里的狼人",d="你可能已经注意到了，在树林周围有些个头较大的狼人和那些夜行织影狼人一起游荡。据我们所知，大多数狼人都是这类夜行黑暗狼人。；我还发现在小镇西南的烂果园里已经到处都是他们的身影了，这些狼人比你之前遇到的那些更难对付。；小心点。",o="为夜色镇的卡洛尔杀掉12个夜行黑暗狼人。",p=173},
  [222]={t="森林里的狼人",d="你之前的功绩使我确信，你已经可以去对付森林里最凶猛的狼人了。；在这一带所有的狼人中，夜行邪齿狼人和夜行堕落狼人是最危险的。他们就住在南边的洞穴和矿井里。；你甚至能从很远的地方看见他们的篝火。",o="为夜色镇的卡洛尔杀掉8个夜行邪齿狼人和8个夜行堕落狼人。",p=221},
  [223]={t="森林里的狼人",d="拿着这个，$n。把这个带给卡尔文主人。；<他取出一张褪色的羊皮纸交给你>；如果再多些像你这样的力量加入，我们就能让守夜人相形见拙！也许到那个时候，我们就能够彻底解决这些现在令我们疲惫不堪的危机。",o="把卡洛尔的便笺交给乔纳森·卡尔文。",p=222,r={{i=2113,n="卡洛尔的便笺",c=1}},w={{i=2902,n="信念披风",c=1},{i=1547,n="信仰之盾",c=1}},f=1},
  [224]={t="保卫国王的领土",d="我们要保卫洛克莫丹，你！国王的士兵都在遥远的战场上英勇作战，但我们的家园却危机丛生。每个裂缝里都有穴居人在不断冒出来！四处横行的穴居人已经成了铁炉堡最大的威胁，我们一定要消灭这些恶心的怪物！；我们需要像你这样勇敢的冒险家来帮忙消除穴居人的威胁。杀掉10个碎石穴居人和10个碎石怪斥候，然后回来向我汇报。",o="南部警戒塔的巡山人库伯弗林特要你杀掉10个碎石穴居人和10个碎石怪斥候。"},
  [228]={t="摩拉迪姆",d="我的探子说摩拉迪姆沿着一条穿过墓地的弯曲怪异的小路，在暮色森林中四处游荡。我们曾把他的尸体埋在山上那座小屋的后面，你知道在哪儿吧？；除了祝你好运之外，我没什么能帮你的了。",o="杀掉摩拉迪姆，把他的头骨交给夜色镇的指挥官阿尔泰娅·埃伯洛克。",p=227,r={{i=3514,n="摩拉迪姆的徽记",c=1}}},
  [230]={t="斯温的营地",d="挖开土堆之后，你发现了一本不大的书，上面沾满了泥土。；书上没有写标题，不过……书里写着一些斯温想要知道的东西。",o="把你从斯温的农场找到的书交给他。",p=95,r={{i=2161,n="斯温农场中的书",c=1}}},
  [231]={t="女儿的爱",d="拿着这个，请把这个放到他的坟墓上。也许…也许这样他就可以知道我现在过得很好，而且我们也不会因为他所做的事责怪他。；<她含着眼泪，把戴在右手上的一只戒指摘下放在你手里>；还有……谢谢你，$n。",o="把莎拉·拉迪莫尔的戒指拿到摩根·拉迪莫尔的坟墓上去。",p=229,r={{i=2162,n="莎拉之戒",c=1}},f=1},
  [232]={t="金格的货物",d="皇家药剂师学会需要你的帮助。仔细听好了，这个行动对你我都有好处。；隔壁的药剂师基佛看上去有些……疯疯癫癫的，但如果他的研究项目能早点找到一个有眼光的买家的话，早就已经得到丰厚的成果了。幸运的是，现在我已经把这个研究项目买了过来。我要你把这份订货单交给蓝月杂货店的店主奥雷萨多·卢卡那里，他会给你一只实验工具包。当你拿到工具包之后就尽快回来向我报告，我会告诉你下一步任务的详细情况。",o="把订货单交给幽暗城的奥雷萨多·卢卡。",r={{i=8525,n="金格的订货单",c=1}}},
  [233]={t="寒脊山谷的送信任务",d="嗯，$g小子:姑娘;，我想也许你不会帮我这个忙的。今天从隧道那边来了一大堆信，我想我没时间把它们都给发出去了。；这些信都是寄给塔林·锐眼的。沿着这条路向西走就能找到他，就在结冰的湖泊附近。；你能帮我这个忙么？",o="把这一摞信件送给寒脊山谷的塔林·锐眼。",p=179,r={{i=2187,n="一摞信件",c=1}}},
  [237]={t="保卫国王的领土",d="巡山人库伯弗林特总是在我面前称赞你，$c。因此现在我要交给你一个极其重要的任务，你必须不断给那些入侵的穴居人施加压力，直到我们的兄弟们从联盟前线回来。；到南部的丘陵去，杀掉10个碎石怪击颅者和10个碎石怪先知。你的行动可以为我们赢得一点时间，完成任务后就回来向我报告。",o="南部警戒塔的巡山人格拉维戈要你杀掉10个碎石怪击颅者和10个碎石怪先知，然后回去向他汇报。",p=224},
  [238]={t="金格的货物",d="东西都准备好了，$n。毫无疑问，药剂师金格正在等着这批货。马上把这些东西送到她那里去，告诉她我已经把价钱记在学会的帐上了。另外，请代我向她致以最高的敬意。；好了，不要再站在这里了，快点出发吧！",o="把采样工具包交给幽暗城的药剂师金格。",p=232,r={{i=8523,n="野外实验工具包",c=1}}},
  [245]={t="蜘蛛的威胁",d="你好啊，$c。你有没有看到过在西边出没的那些蜘蛛？这些八条腿的东西实在是太多了，多到我们没法应付，指挥官又没有多馀的人力可以从夜色镇派来协助我们。；我实在是不好意思向你开口，不过……看样子你好像能对付它们。我不能承诺给你什么贵重的宝贝，不过如果你帮助我们除掉这些肮脏的臭虫，我肯定会奖赏你的。；哦，对了，给你个忠告：尽量别碰到它们的毒液。",o="守夜人道茨要你杀15只规模结网毒蜘蛛。",f=1},
  [247]={t="The Hunt Completed",f=2},
  [248]={t="监视",d="我监视伊尔加拉之塔已经很久了，并且我发现，莫甘斯与占据了石堡要塞的兽人之间起了矛盾。我不知道他们之前产生纷争的原因是什么，但你可以帮我揭开谜底。；带上阿祖拉的铭文饰品，然后到那个能监视石堡要塞的岗哨顶部去。；找一个合适的地方，把铭文饰品放进去，一个盒子或者罐子之类的东西都可以，只要铭文饰品不会被注意到就行，那样我的目的就达到了。",o="爬上赤脊山石堡要塞一旁的哨塔。；为阿祖拉的铭文饰品找一个合适的容器。",p=94,r={{i=1083,n="阿祖拉的铭文饰品",c=1}}},
  [249]={t="莫甘斯",d="在长期的侦察监视之后，我终于发现了莫甘斯的计划。；他正在寻找月神镰刀……而且，他甚至可能已经找到了。如果他有了那东西，整个赤脊山脉地区，甚至是整个暴风王国都会被他的黑暗力量所征服。；我还没有想到对付莫甘斯的办法，但我怕如果现在不行动的话，也许以后就没有机会了。所以我希望你能杀进伊尔加拉之塔与莫甘斯交战。；战胜他，然后把他的暗影坠饰带回来给我。如果你成功了的话，整个王国都将以你为傲。",o="击败莫甘斯。；将他的阴影坠饰带给塞欧克瑞图斯，他就在艾尔文森林内的阿祖拉之塔中。",p=248,r={{i=3617,n="暗影坠饰",c=1}},f=1},
  [251]={t="翻译亚伯克隆比的信",d="请把你给我的这封信拿给希拉·沃宁迪看看。他对语言和古代艺术很有研究——我看也只有他能翻译这封信了。",o="把写给艾尔罗的信拿给希拉·沃宁迪。",p=160,r={{i=1637,n="写给艾尔罗的信",c=1}}},
  [252]={t="翻译好的信件",d="天哪！如果信上所写的内容都是真的，那亚伯克隆比所做的事情……太可怕了！；你最好还是把翻好的信拿回去给艾尔罗看看。；快一点，我感觉到这座小镇的末日就要到了……",o="把翻好的信带给艾尔罗·埃伯洛克公爵。",p=401,r={{i=1656,n="翻译好的信件",c=1}}},
  [253]={t="藏尸者的妻子",d="藏尸者是个我们经常用来吓唬孩子的故事里的人物。他曾是个善良的炼金师，但因为妻子伊莉莎的死而变得疯狂。为了让妻子复活，藏尸者用黑暗的魔法将自己的精华放入了亡妻的胸膛里。；伊莉莎复活了……不过她也受到了诅咒，开始疯狂地攻击人类，藏尸者不得不将他的妻子埋了起来。；他的精华就是他全部的力量，找到他妻子的坟墓，把他的精华拿回来，就可以打破他的力量。",o="找到伊莉莎的坟墓，从她的身上取回藏尸者的精华，把它交给艾尔罗·埃伯洛克。",p=252,r={{i=2382,n="藏尸者的精华",c=1}},f=1},
  [256]={t="通缉令：卓克苏尔",d="以塞尔萨玛镇长之令：；卓克苏尔，袭击塞尔萨玛镇、巨石水坝及挖掘场的食人魔的领导者和组织者。现要求不惜采用一切手段杀死卓克苏尔。；若有人呈上杀死卓克苏尔的证明，镇长将给予巨额奖金。；卓克苏尔最后一次出现是在洛克莫丹东北部的食人魔营地里。",o="杀了卓克苏尔，把他的徽记带给塞尔萨玛的镇长埃罗恩·钝鼻。",r={{i=2561,n="卓克苏尔的徽记",c=1}},w={{i=6189,n="坚固的链甲护肩",c=1},{i=6191,n="基布拉之靴",c=1}},f=1},
  [257]={t="自豪的猎人",d="你觉得自己可以和勇敢的达瑞尔相提并论？我可不这么认为，当然咯，如果你不服气的话，完全可以试试看。我会让你去做一件非常困难的事情，困难到以你的能力恐怕根本没法摆平，所以就算你完成不了也用不着气馁。；有一群秃鹰在这一带筑巢，你去试试能不能把它们解决掉？告诉你吧，如果你能在十五分钟里完成这个任务，我就把我的弓剑或是火枪送给你。<他轻蔑地上下打量着你>；看上去你也没什么可以输掉的东西。",o="杀死6只山鹫，然后回到旅行者营地见年轻的达瑞尔，时限为15分钟。",w={{i=2903,n="达瑞尔的猎弓",c=1},{i=2904,n="达瑞尔的猎枪",c=1}},f=1},
  [258]={t="猎人的挑战",d="你叫$n，对吧？看得出来，完成第一个考验之后，你已经被骄傲冲昏了头脑，不是吗？我跟你说过的，那没什么了不起。；你应该再试试去捕杀野猪。相信我，这和捕杀寒脊山谷里那些野猪可不一样，所以你最好当心点。这次我只给你十二分钟。；失败了也别难过。不过如果你成功了，我就把我的衬衣脱下来给你！；我有没有跟你说过我这个着名的伤疤是怎么来的？没有？好吧，两年前的一天……",o="杀掉5只老山猪，然后回到旅行者营地去见年轻的达瑞尔，时限为12分钟。",p=257,f=1},
  [261]={t="血色之路",d="坦率地说，我们现在正在与天灾军团交战。他们是一群致力于腐化我们的人民、污染我们的土地的恶魔。我们一定要在他们将我们最后的堡垒彻底血洗、将我们的世界彻底拖入黑暗之前阻止他们。我们血色十字军发誓要奉献出全部身心，与天灾军团斗争到底。；如果你也如此宣誓了的话，鼓起你的勇气并证明你的忠诚——去与凄凉之地的亡灵劫掠者们作战吧，它们都聚集在那个地区南部的白骨之谷里。；只有这样，十字军才会接纳你。",o="杀掉30个亡灵劫掠者，然后向尼耶尔前哨站的安东修士复命。"},
  [262]={t="模糊的人影",d="我一定要搞清楚那个躲在暗处目睹我全家被杀的人到底是谁！；求求你了，你，你已经表现出了你的足智多谋，请你帮我找出那个模糊的人影到底是谁，我一定要知道他到底是谁！；我没法再给你提供更多线索了，不过……拿着这本你在农场里找到的书，也许镇上有人能够帮助我们找到它的主人。",o="带着你从斯温的农场找到的书，把它拿给夜色镇上的人看看。",p=230,r={{i=2161,n="斯温农场中的书",c=1}}},
  [263]={t="保卫国王的领土",d="巡山人告诉我你很勇敢也很能干，你。我们这儿就需要像你这样的$r。穴居人的问题一点也没有好转，预备军都被派到前线去了，我们在这儿孤立无援。不过现在我们有你这样一个经验丰富的$c，事情就好办一些了。；去杀掉10个碎石怪萨满祭司和10个碎石怪断骨者，让我们瞧瞧你是不是名副其实的穴居人杀手。",o="南部警戒塔的巡山人沃尔班要你杀掉10个碎石怪萨满祭司和10个碎石怪断骨者。",p=237},
  [265]={t="继续搜寻",d="拿回你的书吧，你，祝你好运。你可以去问问镇上的其它人，他们也许还能给你提供更多的线索。；对了，我还有个线索可以提供给你——这本书的作者不是夜色镇的人，不过书却是在镇里买来的。",o="看看其它的镇民有没有关于模糊的人影的线索。",p=262,r={{i=2161,n="斯温农场中的书",c=1}}},
  [266]={t="调查旅店",d="这是你的书，祝你好运。；你不妨去旅店里查查看，如果你要找的那个人在镇上待过的话，那么很可能有人在旅店里见过他。",o="到旅店去查一查关于模糊人影的线索。",p=265,r={{i=2161,n="斯温农场中的书",c=1}}},
  [268]={t="回复斯温",d="你找到的那本书……我还没有写完。我从斯文的农场里逃走的时候，不得不把书留在那儿……；拿着这个，把这本完整的日记带给斯温。这一本对在他的农场上所发生的事情描述得更完整。；这几个星期以来，我一直把这本日记放在身边，不过如果把它交出来之后我就不用面对斯温和他的愤怒的话，我宁愿把这东西交给他。",o="把基特斯的日记交给斯温。",p=453,r={{i=2560,n="基特斯的日记",c=1}}},
  [269]={t="寻求指引",d="到暴风城去找光明大教堂的主教法席恩，把基特斯的日记给他看一看，告诉他你决心要和摩本特·费尔进行面对面的较量。；虽然暴风城抛弃了夜色镇，但是法席恩主教是个善良而又睿智的人，也许他能给你一些帮助。；你的使命非常危险，不过请动作快点，你。笼罩夜色镇的黑暗力量无时无刻不在变得更加强大。",o="把基特斯的日记交给暴风城的主教法席恩。",p=323,r={{i=2560,n="基特斯的日记",c=1}}},
  [271]={t="维林的报复",d="你没被达瑞尔气得昏头昏脑吧？虽然我不愿意承认，但达瑞尔还是有点能耐的。；一年前，整个旅行者营地里的猎人都在捕猎一只巨熊，不过没有一个人能解决掉它。后来，达瑞尔也去试了试，结果他的脸上就留下一道了丑陋的伤疤。；如果你能杀了那只熊，就算是达瑞尔也会哑口无言的。；那只名叫奥尔苏迪的熊就住在塞尔萨玛附近的山上。",o="杀掉奥尔苏迪，把它的首级带给旅行者营地里的达瑞尔。",p=258,r={{i=2713,n="老黑炭的头",c=1}}},
  [272]={t="海狮试炼",d="第二个试炼是要寻找组成海狮坠饰的两个部分。其中的一半蕴含着海狮的敏捷天性，另一半蕴含着海狮那令人难以置信的耐力。德鲁伊汲取这两种特性，将它们运用到自己的水栖形态中。；与月光林地中的居民谈一谈，找到这两个部分，并将它们合并起来。最后把合并好的坠饰交给德迪利特·星焰。",o="寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。；在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。；将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。",p=29,r={{i=15885,n="海狮坠饰",c=1}}},
  [274]={t="水坝危机",d="这不是一般的炸药粉末。看看这些银色的小晶体。还有这股特别的味道！不用说这就是爆盐粉末了！爆盐本身没什么危害，不过一旦它沾上水，那威力，啧啧！足够把整个铁炉堡给炸上天！；要想阻止这种东西爆炸就需要四种东西：潜伏者的毒液，莫格罗什水晶，一滴鳄鱼的眼泪和一些拆弹胶质。现在你得赶紧把我的话告诉辛德维尔，否则就来不及了！",o="阿什兰·暗石要你回去见洛克莫丹的主工程师辛德维尔七世，把有关这种炸药的新发现告诉他。",p=161,r={{i=2609,n="拆弹胶质",c=1}}},
  [275]={t="大地上的脓疱",d="我不知道是怎么回事，但是堕落正在湿地上蔓延。沼泽爬行者出现了，他们就像是腐烂而危险的脓疱。要制止这些脓疱，就必须把他们驱散开，把它们赶回沼泽。；这些沼泽爬行者一般都在湿地的水道里活动。",o="杀死8只沼泽爬行者，然后向湿地的绿色守卫者雷希耶尔复命。",p=277,w={{i=3558,n="沼泽守护者长袍",c=1},{i=1273,n="森林链甲",c=1},{i=2263,n="林木之刃",c=1}},f=1},
  [276]={t="践踏之爪",d="藓皮豺狼人在湿地平静地生活了许多年，但如今他们的数量却膨胀了不少。他们的脚正践踏着沼泽地中的灌木与花朵，他们污浊的斧子也砍伐了太多的树木。；他们已经令这里的自然失去了平衡。为了湿地的安宁，必须削减这些豺狼人的数量。；去杀死15名藓皮豺狼人和10名混血藓皮豺狼人，他们就在南边的奥加兹大门附近活动。完成任务之后再回来向我复命。",o="杀死15名藓皮豺狼人和10名混血藓皮豺狼人，然后向湿地的绿色守卫者雷希耶尔复命。"},
  [277]={t="火焰管制",d="藓皮豺狼人们正在大量地砍伐湿地的树木，用树干和树枝当柴火来烧。我不能再容忍这样的行为了！；把藓皮豺狼人生火用的打火石都给我抢过来。除了年幼的藓皮豺狼人和混血藓皮豺狼人以外，其它所有的藓皮豺狼人身上都会带着打火石。",o="给绿色守卫者雷希耶尔带回9块粗制打火石。",p=276,r={{i=2611,n="粗制打火石",c=9}}},
  [278]={t="水坝危机",d="你必须立刻去收集拆弹用的原料，你。潜伏者的毒液在洛克莫丹的蜘蛛身上可以找到，鳄鱼的眼泪在洛克湖一带的鳄鱼身上也有。不过莫格罗什水晶很难找到。东北边矿井里的食人魔开采这种水晶，不过即使在那里，莫格罗什水晶也不常见。；我们必须要作好准备才能粉碎黑铁矮人的计划！你找齐了这些材料之后就立刻回来找我，我会把它们做成拆弹剂。",o="主工程师辛德维尔七世要你收集一份潜伏者的毒液，一块莫格罗什水晶和一滴鳄鱼的眼泪。",p=274,r={{i=2606,n="潜伏者的毒液",c=1},{i=2607,n="莫格罗什水晶",c=1},{i=2939,n="狂怒之血",c=1}}},
  [279]={t="海中的鱼人",d="可恶的鱼人正在从深海里源源不断地爬出来，它们沿着海岸线创建自己的村庄和定居点。这些家伙给我们的渔民和商人带来了极大的困扰，我们必须要阻止这种行为。；它们当中有一个叫高布勒尔的头目最近一直带着一群蓝腮鱼人埋伏在道路旁，抢劫过往的商旅，得手之后又马上撤回它们的村子。现在我们的通商道路非常危险，所以我们想要通过悬赏来解决这个问题。；高布勒尔和它的跟班们就躲在北边的河口附近。找到它，把它干掉，然后把它的徽记给我带回来。",o="杀掉12个蓝腮鱼人。；杀掉高布勒尔并砍下它的头。；将高布勒尔的徽记交给米奈希尔港的卡尔·波兰。",r={{i=3618,n="高布勒尔的徽记",c=1}}},
  [280]={t="水坝危机",d="今天早些时候我发现有一些黑铁矮人背着一只大木桶向水坝游去，糟糕的是那一带没有巡山人可以拦住他们！我怀疑他们已经把爆盐炸药放到了水坝下面，随时都有可能爆炸！我马上就把这些成分混合在一起制成拆弹剂。；完成了！现在我要你把这个混合剂拿去，和木桶里的炸药搅拌在一起！快一点！我们没时间了！",o="主工程师辛德维尔七世要你游到水坝底部，找到装着炸药的木桶，然后把拆弹剂放进去，阻止将要发生的爆炸。",p=278,r={{i=2610,n="拆弹剂",c=1}}},
  [282]={t="森内尔的观察站",d="我原打算让我的学徒帮我把报告带给我的兄弟森内尔。但是，你看他那德性……我想如果有一个更可靠的人替我去送的话就更好了。如果你不介意的话，可以去一趟吗？；嗯……你要穿越隧道，一路走到卡拉诺斯。；在穿越隧道前，别忘了去和巡山人萨鲁斯聊聊，那里的穴居人简直成灾了。；顺着这条路回到安威玛尔，然后向东就能到隧道了，萨鲁斯就在附近。",o="和巡山人萨鲁斯谈一谈。",p=218,r={{i=2619,n="格瑞林的报告",c=1}}},
  [283]={t="A Dark Threat Looms",o="The Disarming Mixture seemed to take effect. Return to Chief Engineer Hinderweir to report the good news.",p=280,w={{i=2907,n="矮人伐木斧",c=1},{i=2908,n="荆棘之刃",c=1}},f=1},
  [286]={t="归还雕像",d="你把这个木桶从垃圾里拖了出来，刚一打开它，一尊精心包裹在稻草中的银制小雕像就掉了出来。这是一个头发很长的年轻圣骑士高举战锤的样子。；这一定就是米奈希尔雕像了！你必须马上把它交还给米奈希尔港的卡尔·波兰。",o="将米奈希尔雕像还给湿地米奈希尔港的卡尔·波兰。",p=285,r={{i=2625,n="米奈希尔雕像",c=1}},w={{i=2950,n="冰柱魔棒",c=1},{i=2949,n="水手之靴",c=1}},f=1},
  [287]={t="霜鬃巨魔要塞",d="我快要来不及提交报告了，你能帮我一下吗，$n？我只想知道这些巨魔躲在什么地方，不过我看见这么多的巨魔就怕得不敢进去了。；你要做的是……进到山洞里，在里面到处走走，干掉一些巨魔，然后再回来。；顺着向北的路离开卡拉诺斯，当你走到一座桥前的时候，再沿着冰冻的河流向西一直走到涌冰湖。你会发现烈酒村就在湖的西岸，而巨魔要塞就在村庄的西南边。",o="侦查霜鬃巨魔要塞，替卡拉诺斯的森内尔·白须杀掉5个霜鬃猎头者。",p=420,w={{i=3216,n="保暖冬衣",c=1},{i=2900,n="石质圆盾",c=1}},f=1},
  [288]={t="第三舰队",d="我曾经是浪花女神号上的大副——浪花女神是库尔提拉斯第三舰队的主力战舰。这是一支多灾多难的舰队，说它多灾多难是因为……它在最后一次出航中遇到了红龙的袭击。这些龙是被兽人控制的！；红龙喷出的火焰对我们的战舰来说简直是毁灭性的……我们的舰队在这片海域被烧得一干二净，全军复没。我是那次灾难的唯一幸存者……；……哦，我的头疼得像鼓槌在敲！我需要一些让我头脑清醒的东西，好让我继续讲述我的故事。",o="为大副菲兹莫斯买一份壶装蜜酒。",r={{i=2594,n="壶装蜜酒",c=1}}},
  [289]={t="被诅咒的船员",d="<缓过气来的菲兹莫斯继续讲述他的故事……>；我是这支倒霉的库尔提拉斯第三舰队中唯一的幸存者，整支舰队都在北方的海岸附近复灭了。不过，虽然我是舰队中唯一活着的人，却不是唯一一个依然在这里出现的人！因为，在一条已经沉没的船里，藏有巨大的、可怕的宝藏，它所拥有的可怕魔力将我的弟兄们的灵魂束缚在被海水侵蚀的船体里。；如果你能超度我的那些被诅咒的弟兄们，也许你就能破除那个诅咒。",o="杀死13个被诅咒的水手、5个被诅咒的水兵和大副斯涅利格。把斯涅利格的鼻烟盒交给米奈希尔的大副菲兹莫斯。",p=288,r={{i=3619,n="斯涅利格的鼻烟盒",c=1}}},
  [290]={t="解除诅咒",d="为了破除诅咒，解救我所有的兄弟，就必须要把装在我船上的那个鬼东西拿回来进行净化！我不知道它是什么，但我知道它被存放在船上的保险箱里，而保险箱的钥匙一向是由哈林多尔船长保管的。；我的老船长仍时常出现我的梦里，在我的那艘已毁灭了的无畏号的甲板上走来走去……去找到钥匙，用它打开无畏号上的保险箱。；然后，在你获得那件被诅咒的东西以后，把它交给镇上的牧师，戈罗林·钢眉。",o="从哈林多尔船长那里拿到无畏号的保险箱钥匙。；用钥匙打开无畏号上的保险箱。",p=289,r={{i=2629,n="无畏号的保险箱钥匙",c=1}}},
  [292]={t="帕雷斯之眼",d="打开箱子之后，你看到了一颗发黑的宝珠，它还在闪烁着可怕的光芒。这就是菲兹莫斯所说的宝藏：一颗被诅咒的帕雷斯之眼。；把被诅咒的帕雷斯之眼交给住在米奈希尔港的矮人牧师戈罗林·钢眉，请他驱除附着在它上面的诅咒。",o="把被诅咒的帕雷斯之眼交给湿地米奈希尔港的戈罗林·钢眉。",p=290,r={{i=2944,n="被诅咒的帕雷斯之眼",c=1}}},
  [293]={t="净化帕雷斯之眼",d="我无法驱散帕雷斯之眼上的诅咒。它是由人类牧师手工制造的，所以你最好去暴风城寻找帮助。去和大主教本尼迪塔斯谈谈吧，他是暴风城光明大教堂的领导者，他能帮你解决问题。；我希望如此。",o="把被诅咒的帕雷斯之眼交给大主教本尼迪塔斯，他就在暴风城的光明大教堂里。",p=292,r={{i=2944,n="被诅咒的帕雷斯之眼",c=1}},f=1},
  [294]={t="奥莫尔的复仇",d="当前我们所面临的形势十分严峻，这已经是众所周知的事了。我们刚挖出这些骨头，它们就招来了一大群迅猛龙。这些凶残的野兽杀光了我的弟兄们，并把我、麦琳和可怜的勘察员困在了这上面。；帮我把湿地里的这些迅猛龙都给杀光，你。杂斑迅猛龙和杂斑尖啸龙就在山崖的西边，要是你有能力对付它们的话，每种都给我杀上十只。；这只不过是我对它们的复仇计划的开始而已！",o="维尔加挖掘场的奥莫尔·铁衣要求你杀死10只杂斑迅猛龙和10只杂斑尖啸龙。"},
  [295]={t="奥莫尔的复仇",d="现在是时候让这些该死的迅猛龙为它们的嗜血而后悔了。在悬崖下面还有一些杂斑刺喉龙和杂斑锯齿龙，每种都给我杀10只，它们要为自己的所作所为付出代价！",o="奥莫尔·铁衣要求你杀死10只杂斑刺喉龙和10只杂斑锯齿龙，然后回到维尔加挖掘场向他复命。",p=294},
  [296]={t="奥莫尔的复仇",d="在你下到悬崖底部的时候，我碰巧发现了有一只很特别的迅猛龙在那边站着休息。它比一般的迅猛龙的体形要大得多，看上去也特别凶猛。我敢打赌它就是那群迅猛龙的首领，就是它带着手下来这里毁了整个挖掘场。；我现在交给你最后一个任务，你。以正义的名义，审判萨尔图斯！当然，考虑到它所犯下的重罪，它唯一能得到的判决就是死刑！把它的一只爪子给我带回来作为它已死的证据。",o="维尔加挖掘场的奥莫尔·铁衣要求你杀死萨尔图斯，并在任务完成之后带着它的一只爪子向他复命。",p=295,r={{i=3638,n="萨尔图斯的爪子",c=1}},w={{i=3493,n="迅猛龙终结者",c=1},{i=3566,n="迅猛龙杀手护甲",c=1},{i=5246,n="挖掘之杖",c=1}},f=1},
  [297]={t="收集石像",d="不久前，就在那些穴居人像雨后的蜗牛一样冒出来之前，我们发现了一大批奇特的小石像。但是还等我们开始着手研究它们，穴居人就把我们从废墟里赶了出来！这些石像有种奇特的效力，它可以让那些穴居人变得更加疯狂！；给我拿几个石像回来——我想研究研究，所以你得把它们从穴居人手上给我抢过来！你可以在挖掘场里到处都是的穴居人身上拿到这些石像。",o="收集8个小石像，把它们交给麦格玛尔·落斧。",r={{i=2636,n="小石像",c=8}},w={{i=5241,n="矮人火枪",c=1},{i=6186,n="穴居人切割者",c=1},{i=3154,n="塞尔萨玛战斧",c=1}},f=1},
  [298]={t="挖掘进度报告",d="我这里有一份报告要赶快送到塞尔萨玛去——这是一份挖掘进度报告，还有一份再次重申我们需要更多的火药粉的报告！你把它带给吉恩·角盔，他是我们在塞尔萨玛的联系人。；这个任务没什么麻烦的，但你一定要完成它。",o="把铁环挖掘场的进度报告带给塞尔萨玛的吉恩·角盔。",r={{i=2637,n="铁环挖掘场的进度报告",c=1}}},
  [299]={t="发现历史",d="在迅猛龙大举入侵之前，我找到了一块名叫戈奥兹之石的巨大石碑。我翻译好的文字被分成了四部分，散落在挖掘场中的四个不同的地方。这些文字描述的是一个“神圣的计划”和一个“注定的命运”。；我们应该马上把它们都收集起来，而不是继续在这里浪费时间。但是我已经很老了，恐怕没办法再杀出去跟那些凶猛的野兽作战了。但是你不同，你年轻而强壮。；到挖掘场里去搜索这四片失落的石板：阿度斯石板、莫德尔石板、高尔姆石板和奈尔鲁石板。它们应该被藏在某些古董器物里，另外",o="勘察员维尔加要求你在挖掘场中搜索4块石板的碎片，它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片。",r={{i=2658,n="阿度斯碎片",c=1},{i=2659,n="莫德尔碎片",c=1},{i=2660,n="高尔姆碎片",c=1},{i=2661,n="奈尔鲁碎片",c=1}},f=1},
  [301]={t="向铁炉堡报告",d="我们必须得到上级的批准才能给铁环挖掘场送去更多的火药粉。把他的报告带到铁炉堡的探险者协会总部去，交给勘察员塔伯斯·雷矛。他可是个急性子的家伙，如果听说铁环挖掘场的进展如此缓慢，他一定会暴跳如雷的。；你可以在探险者大厅里找到他。",o="把铁环挖掘场的进度报告交给勘察员塔伯斯·雷矛。",p=298,r={{i=2637,n="铁环挖掘场的进度报告",c=1}}},
  [303]={t="黑铁战争",d="战火席卷了整个世界。当许多精锐的矮人士兵们为了联盟而牺牲在前线时，我们自己的土地却沦为了这群邪恶的黑铁矮人觊觎的目标。他们已经攻陷了萨多尔大桥，丹莫德也岌岌可危。；我们要你去聚集起一股力量，并将战线推回去。如果你能杀死十名黑铁矮人、五名黑铁隧道工、五名黑铁破坏者和五名黑铁爆破手的话，就能为我们组织反击争取到宝贵的时间。；兵贵神速，快出发吧！",o="丹莫德的莫特雷·加玛森要求你杀死10名黑铁矮人、5名黑铁隧道工、5名黑铁破坏者和5名黑铁爆破手。"},
  [304]={t="艰巨的任务",d="我手下的大部分士兵都在丹莫德的战役中死去了，我的亲兄弟也在萨多尔峡谷上的西桥被毁的时候不幸牺牲。唉，黑铁矮人真是个像恶魔一般邪恶的族群。根据罗戈收集到的情报，这群在湿地四处肆虐的暴徒的领袖是一个名叫巴尔加拉斯的术士。他是个十分胆小谨慎的家伙，在把手下的士兵送上战场执行命令的时候，他自己往往却躲藏在某个不为人知的地方，躲避着任何可能面临的危险。；如果你能找到这个懦夫，杀了他，把他的耳环拿来给我，我会给你支付可观的酬劳的，$c。",o="杀死邪恶的巴尔加拉斯，把他的耳环带给丹莫德外的布莱德·长须。",r={{i=3639,n="巴尔加拉斯的耳环",c=1}},w={{i=2916,n="金狮之盾",c=1},{i=2917,n="宁静之戒",c=1}},f=1},
  [307]={t="肮脏的爪子",d="东边的银泉矿洞很久以前就枯竭了。矿工联盟把它改造成了储藏库，不过现在狗头人占据了那里，把他们肮脏的爪子放在了我们矮人制造的工具上！；我们很快就能把这些害人虫赶走，但是矿工联盟要求我们在冲进去大开杀戒之前，先把洞里的矿工装备拿出来。这是个艰难的任务——你也许需要几个帮手。；他们的装备就在矿工联盟的储物箱里，祝你好运。",o="到银泉矿洞去收集4套矿工装备，然后向巡山人卡尔·雷矛复命。",r={{i=2640,n="矿工装备",c=4}},w={{i=3166,n="铁心链甲",c=1},{i=3161,n="监护者法袍",c=1},{i=3160,n="铁板圆盾",c=1}},f=1},
  [309]={t="Protecting the Shipment",o="Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband.",p=454,w={{i=3217,n="工头腰带",c=1},{i=6188,n="泥泞践踏者",c=1}},f=1},
  [310]={t="针锋相对",d="我不得不承认，雷酒系列的那帮家伙酿酒水平还真不赖。但是他们应该知道他们的酒并不是世界上最好的！也许你能帮我让他们了解这一点……；给，带上这桶热麦酒，想办法潜入卡拉诺斯的雷酒酿造厂的酒窖，把他们的雷霆啤酒和我们的换一下。然后，我们就等着看好戏吧，顾客们肯定会更喜欢我的酒！；如果有人看着酒桶的话，你就得想办法转移他的视线……",o="到卡拉诺斯的雷酒酿造厂酒窖里去，把一桶雷霆啤酒换成热麦酒。",r={{i=2548,n="一大桶热麦酒",c=1}}},
  [312]={t="马克格拉恩的干肉",d="我原本储备了一个月的干腌肉准备过冬，为了防止野熊把肉衔走，我把它们锁在了储藏柜里。但是在我外出打猎的时候，一个叫做冰须的野兽偷走了我的储藏柜！可笑的是那个蠢货撬不开这只用瑟银铸成的柜子。；但是如果拿不回这些肉，我就会饿死的。你的身手看来不错，也许你能帮我取回储藏柜？你瞧我拖着这条废腿也没办法把那只柜子抢回来……",o="从冰须的洞穴里拿回装有马克格拉恩的干肉的储藏柜。",r={{i=2667,n="马克格拉恩的干肉",c=1}},w={{i=6177,n="铁铸护腕",c=1},{i=10550,n="毛织手套",c=1}},f=1},
  [314]={t="保护牲畜",d="午夜的时候，我们听到了吵闹的声音。今天早上我才发现羊圈里少了两只羊，那头名叫瓦加什的野兽袭击了我们的牲畜。由于国王麦格尼的军队大都在遥远的战场上与联盟其它的种族并肩作战，所以没有人能对付得了瓦加什。；也许你有勇气找到这只猛兽并杀了它。把它的一颗牙齿交给我作为证明，我会奖赏你的。瓦加什就躲在这里的农场附近，小心点，它非常凶残。",o="山羊农场的鲁德拉·冻石要你杀了瓦加什，并且把它的牙齿给她带回去。",r={{i=3627,n="瓦加什的牙齿",c=1}},w={{i=10549,n="牧民长裤",c=1},{i=2817,n="硬皮外套",c=1},{i=3103,n="寒脊之锤",c=1}},f=1},
  [315]={t="完美烈酒",d="我正在寻求可以酿制出完美的酒的方法。我知道我能酿造出来，我缺的只是一份正确的酿酒配方……；霜鬃巨魔在东边的山坡上种植了一种叫做微光草的植物，他们通常在奇怪的部族仪式上用到它。我们矮人还没有发现这种草有什么用途，不过它的口味非常特别……我要把这种植物用在我的酒里！；从霜鬃先知那里给我弄一些微光草来，或者你也可以从巨魔用来装微光草的篮子里偷一些。",o="收集6束微光草，把它们交给烈酒村的雷杰德·麦酒。",r={{i=2676,n="微光草",c=6}},w={{i=2905,n="羊毛披风",c=1},{i=2326,n="常春藤编织护腕",c=1}},f=1},
  [317]={t="贝尔丁的补给",d="我正在准备为攻城坦克旅执行一项任务。这次任务会持续很长时间，所以我得预先收集能够维持一个月的物资。贝尔丁正忙着rn修理我的坦克，你能帮我去弄一些东西来吗？；我需要一些毛皮来做床垫，还要一些野猪肉作为食品储备。猪肉当然是从野猪身上割下来的，最好的毛皮是熊皮……在灰色洞穴南部的雪地上到处都是这两种动物的踪迹。",o="收集4大块野猪肉和2张厚熊皮，把它们交给钢架补给站的驾驶员贝隆·风箱。",r={{i=769,n="大块野猪肉",c=4},{i=6952,n="厚熊皮",c=2}}},
  [319]={t="艾沃沙酒",d="我有一桶酿制好的艾沃沙酒，不过……你能帮我个忙吗？烈酒村急需人手去对付在村子附近溜达的野兽。有时它们离我们非常近，那真是太危险了。；我们并不害怕这些熊啊，豹啊，野猪啊——任何一个有自尊的矮人都不会害怕——不过，如果你能替我把它们搞定的话，我就能腾出更多的时间来酿酒了。",o="杀掉6头冰爪熊、8只老峭壁野猪和8只雪豹，然后回到烈酒村的雷杰德·麦酒那里。",p=318},
  [320]={t="艾沃沙酒",d="这是你要的艾沃沙酒，你。再次感谢你给予我们的帮助。",o="把这桶艾沃沙酒交给钢架补给站的驾驶员贝隆·风箱。",p=319,r={{i=2696,n="一桶艾沃沙酒",c=1}},w={{i=1011,n="锋利的战斧",c=1},{i=1010,n="瘤木短杖",c=1},{i=10547,n="露营小刀",c=1}},f=1},
  [322]={t="格瑞曼德·艾尔默",d="暴风城矮人区有一个名叫格瑞曼德·艾尔默的矮人武器匠会用这种光铸铁来打造武器。；我已经把你找到的这些铁锭用木箱装好了。把这个箱子交给格瑞曼德，再把你的事情告诉他。我敢打赌他一定会义愤填膺地马上着手为你打造武器的，嘿嘿，那肯定是把就连摩本特·费尔看到了也会心惊胆颤的武器！",o="将这箱光铸铁锭交给格瑞曼德·艾尔默。",p=324,r={{i=2712,n="一箱光铸铁锭",c=1}}},
  [323]={t="证明你的实力",d="摩本特·费尔是个亡灵巫师，也是黑暗强盗的帮凶。我希望你能去除掉摩本特·费尔，不过在了解你真正的实力之前，我还不能贸然拿你的生命开玩笑。；你已经证明了你的勇气，不过如果你想要面对面地和这个巫师作战，首先得证明你能应付得了他的爪牙。",o="杀掉15个骷髅袭击者、3个骷髅医师和3个骷髅看守，然后回来见斯温。",p=268},
  [324]={t="丢失的铁锭",d="你好不容易把那块光铸铁锭从泡在水里的箱子中拿了出来，显然，是鱼人偷走了其馀的铁锭。猎杀飞翔鱼鹰号残骸周围的鱼人，拿到它们身上带着的光铸铁锭。",o="收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。",p=321,r={{i=2702,n="光铸铁锭",c=5}}},
  [325]={t="整装待发",d="你已经准备好了吗，你？祝你好运！我期待着你凯旋归来！",o="现在你已经得到了强大的武器，去向暮色森林的斯温复命吧。",p=322,r={{i=7297,n="摩本特的克星",c=1}}},
  [328]={t="隐藏的钥匙",d="尽管在这些档案文件里都没有提到列兵索尔森，但你发现在赫罗德的一本帐薄后面绑着一只小小的黄铜钥匙。；你还在研究他的其它笔记时发现了其中有一小部分提到，在一个“安全的保险箱”中装有大量的文件。这个保险箱应该在库尔森营地后山的某处洞穴之中，他们管那里叫“储藏室”。；如果你能找到这个保险箱并用这把黄铜钥匙打开它的话，或许里面的文件有助于找到导致索尔森身份暴露的内鬼。",o="使用黄铜钥匙打开书呆子赫罗德的保险箱。",p=200,r={{i=2719,n="黄铜钥匙",c=1}},f=1},
  [329]={t="找出内鬼！",d="在箱子里的这些贵重物品之中，还有一张满是灰尘且写得十分潦草的便笺。尽管几乎已经没法辨认了，但你能看出来这便笺上面似乎描述了列兵索尔森所走的路线。这应该是他的巡逻路线，以及反抗军方面与他接头的人员与时间。签名只有一个字母：M。；毫无疑问，这应该是索尔森身边的人写下的便笺，而且这个人就是反抗军营地中的卧底。",o="将沾泥的便笺交给叛军营地里的多伦上尉。",p=328,r={{i=2720,n="沾泥的便笺",c=1}}},
  [331]={t="Report to Doren",o="Speak with Lieutenant Doren.",p=330,w={{i=4139,n="丛林行者便鞋",c=1},{i=4123,n="寒铁肩铠",c=1}},f=1},
  [335]={t="名酿",d="维沙克公爵最近正在贵族议会中兴风作浪，他似乎知道一些我们的事情，而且还游说其它议员们，要他们通过他提出的对这里进行一次全面调查的提案。我有一个计划，能让维沙克迷上些别的什么东西……但我需要你的帮助。；在夜色镇郊区的斯塔文的花园里生长着一种名叫蒂罗亚之泪的白色小花，去给我弄一朵来。另外我还需要一些麝鼠根，那种东西只生长在湿地，就在巨石水坝下的瀑布底部。",o="黑爪加尔德斯要求你从夜色镇给他摘1朵蒂罗亚之泪，再从湿地给他采一块麝鼠根。",r={{i=2779,n="蒂罗亚之泪",c=1},{i=2784,n="麝鼠根",c=1}}},
  [336]={t="名酿",d="维沙克公爵与所有人一样有自己的弱点，他对酒的爱好胜过一切。更可恶的是，这个蠢货整天想着把我们这个小小的酒馆给弄关门了，而他自己却呆在楼上整夜整夜地喝个不停，至于那些像滚雪球一样越攒越多的账单，他是肯定不会付的。好吧，让我们看看维沙克会有多喜欢我们给他准备的这种特制佳酿：黑爪烈酒。这一定会很有意思的，$n。；把这个带给他，看看他的反应如何，我觉得这傻瓜可能会在祈愿厅里当场开喝。",o="将黑爪烈酒带给祈愿厅里的维沙克公爵。",p=335,r={{i=2788,n="黑爪烈酒",c=1}}},
  [337]={t="一本破旧的历史书",d="这本书的封面已经有被刮坏的痕迹，还沾上了泥污，但是书脊上“暴风城的历史”的字样仍然清晰可见。打开书的第一页，可以看到上面盖着暴风城图书馆的印章。；看起来似乎有人从图书馆借出了这本书却从来没有归还……",o="把《暴风城的历史》这本书还给暴风城图书馆。",r={{i=2794,n="一本破旧的历史书",c=1}}},
  [338]={t="荆棘谷的青山",d="如果奈辛瓦里知道了这一切，他一定会很生气的！；出于对我的信任，他让我来校对他的小说《荆棘谷的青山》的手稿。一开始事情进行得非常顺利，但昨天一阵大风吹过了营地，结果把手稿吹得满天都是！；我已经很努力地找回了大部分的书页，但还是有几页被吹进了丛林中。请你帮我把这四章里的掉落的那几页书都给收集起来吧。；等这四章手稿都搜集齐了以后，把它们还给我。",o="收集《荆棘谷的青山》的手稿中丢失的页面。在集齐四章书之后，将它们还给巴尼尔·石罐。",p=583,r={{i=2756,n="荆棘谷的青山 - 第一章",c=1},{i=2757,n="荆棘谷的青山 - 第二章",c=1},{i=2758,n="荆棘谷的青山 - 第三章",c=1},{i=2759,n="荆棘谷的青山 - 第四章",c=1}}},
  [346]={t="克里斯托弗的书",d="现在我已经把这本书抄完了，这里是《金属的延展性》的原本。感谢你的耐心，还有，如果你见到米尔顿的话，请替我向他道歉，我拖了那么长时间真有些不好意思。",o="回到教堂广场，将《金属的延展性》交给克里斯托弗修士。",p=347,r={{i=2795,n="《金属的延展性》",c=1}},f=1},
  [347]={t="瑞斯班矿石",d="瑞斯班矿石是根据第一个发现他的人——巴尔特·瑞斯班——的名字来命名的。这种矿石在冶炼之后虽然没有铁那么坚硬，但它有一种纯正的黑色，许多抄写员都用它来制作墨水或染料。在北边的瑞斯班矿洞里就可以找到这种矿石。；我们通常会有一些存货，但最近大家都忙于抵抗兽人的进攻，没空去采集这种矿石。此外……这段时间以来，赤脊豺狼人占据了瑞斯班矿洞，而且他们的苦工也正在采集这些矿石。；所以如果你需要的话，就得自己去那里找了。",o="收集5袋瑞斯班矿石，把它们带给北郡图书馆的帕克斯顿修士。",p=345,r={{i=2798,n="瑞斯班矿石",c=5}}},
  [348]={t="荆棘谷热疫",d="我病了…病得……非常厉害……；我…染上了…荆棘谷热疫…致死的疾…疾病……；……只…只有吃下…野人莫…莫…莫克…的精华…才…才有救…那…是…一只残忍而…狡猾的…野兽。；……巫医安巴格瓦巫师…是…唯一会…召唤…它…的人……；找到…住在南边…海岬…洞穴…里的安巴格瓦……；……快点…我就要死了…就要死了……",o="找到巫医安巴格瓦并要求他召唤出野人莫克，然后将野人莫克的精华交给芬·菲兹拉克。",r={{i=2797,n="莫克的精华",c=1}}},
  [351]={t="寻找OOX-17/TN！",d="你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然打开了，变成了一个看起来像是由侏儒创造的那种机器装置！一个噼里啪啦的声音从这个蛋形机器装置中传了出来。；“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它的话，我会奖励你的！请把这个定向器带到我的母体机器人那里。我现在已经为你勘探出了它的所在地！它现在就在塔纳利斯的大裂口那里！”",o="把定位器带到奥格索普的母体机器人那里。",r={{i=8623,n="OOX-17/TN定位器",c=1}}},
  [354]={t="阿加曼德系列",d="阿加曼德系列曾是提瑞斯法林地中最富有的系列。我过去曾在他们的磨坊里工作……当然，我是说在瘟疫降临之前。；天灾军团入侵的时候，阿加曼德系列的人们加固了他们的庄园，并说服了在他们家做工的人留下来帮助他们抵抗天灾军团。我们实在是太蠢了，但我们至少是愚蠢而忠诚。；而阿加曼德系列用荣耀之类的幌子让我们去送死，结果现在他们倒成了天灾军团的走狗！；为了被遗忘者，你必须去剿灭堕落于瘟疫之中的阿加曼德系列！把表明他们身份的标记带回来给我。",o="把格里高的标记、妮萨的标记和萨尔曼的标记交给布瑞尔的库勒曼·法席恩。",r={{i=2829,n="格里高的遗物",c=1},{i=2828,n="妮萨的遗物",c=1},{i=2830,n="萨尔曼的遗物",c=1}}},
  [357]={t="巫妖的身份",d="北边澈水湖中的一个小岛上住着一个巫妖。虽然他是个独立的亡灵，不过他认为其它所有的亡灵都是天灾军团的奴隶，他的爪牙会袭击任何靠近他的人。；他是个无主之人，所以黑暗女王想要招降他。如果他确实精通于巫术的话，那么他的知识会对我们很有帮助。；不过我得先看过他的法术书才能了解他的身份和学问。潜入他的营地，把书拿回来见我。",o="把巫妖的法术书带给幽暗城的比索·埃斯沙德。",p=405,r={{i=2833,n="巫妖的法术书",c=1}}},
  [358]={t="盗墓贼",d="北边的加伦鬼屋你去过吗？那个地区的西南角是一大片乱坟岗，里面葬着提瑞斯法一带的大量因瘟疫而死的人。；那边坟墓里的尸体大多没能变亡灵，但最近天灾军团派出了一群腐皮豺狼人到那里去收集尸体，以此来壮大他们的军队。我们不能允许这样的事情发生！；你的任务有两个：杀光躲在乱坟岗和加伦鬼屋里的腐皮豺狼人，并把他们身上的防腐剂抢回来，正是这种防腐剂使他们活过来的。",o="杀死腐皮盗墓贼和混血腐皮豺狼人。；给布瑞尔的执政官塞弗伦带回8瓶防腐剂。",r={{i=2834,n="防腐剂",c=8}},w={{i=6063,n="钢质护手",c=1},{i=3439,n="僵尸皮靴",c=1}},f=2},
  [364]={t="无脑的僵尸",d="我们被遗忘者正在与巫妖王的天灾军团作战，那支军队包括用亡灵法术唤起的亡灵军队，大陆北方的那些愚蠢的野兽，还有那些永远遭受折磨的鬼魂。；在这个村庄的北部有大量的无脑僵尸到处横行，我们必须消灭他们。消灭他们，即使他们以前可能是我们的兄弟姐妹也不要手软，那些行尸走肉如今只不过是巫妖王的奴隶罢了。",o="暗影牧师萨维斯让你杀掉5个无脑的僵尸和5个丑陋的僵尸。",w={{i=3275,n="麻布手套",c=1},{i=11847,n="破碎的披风",c=1}},f=2},
  [365]={t="悲伤之地",d="看看谁来了？你看上去是个菜鸟$c吧。如果你想向黑暗女王陛下证明自己的实力，就得先学会我们被遗忘者行事的几条基本原则。；这里的西边有个农场，那块地上的人呀，就跟腐烂尸体上的苍蝇一样多。更糟糕的是，血色十字军从他们的哨塔里跑出来巡逻的时候，也可能会经过那里。给这些渣滓们好好地上一课吧，把他们的宝贝南瓜给我偷10颗来。；偷到10颗南瓜以后，就把它们交给布瑞尔的药剂师乔汉。",o="从位于布瑞尔西边、丧钟镇北边的农场中偷10颗南瓜来，把它们交给布瑞尔的药剂师乔汉。",r={{i=2846,n="提瑞斯法南瓜",c=10}}},
  [366]={t="归还书籍",d="很久以前，冈瑟尔和我，还有现在隶属于天灾军团的图勒·鸦爪，我们三人是很好的朋友，我们曾一起在肯瑞托学习魔法。；冈瑟尔和我都是大瘟疫的牺牲品，冈瑟尔后来成为了巫妖王的手下。现在我得知他脱离了巫妖王的魔爪，这真是个好消息。；我们一定要找到他。我给他的书上施放了一个魔咒，当他看到这本书的时候就会知道我也已经摆脱了巫妖王的控制，希望他在知道这一点以后会加入我们。",o="到冈瑟尔居住的小岛去归还他的法术书。",p=357,r={{i=3016,n="冈瑟尔的法术书",c=1}}},
  [367]={t="致麻药剂",d="希尔瓦娜斯大人最近交给了我们皇家药剂师学会一项很有挑战性的命令。黑暗女王相信我们的知识与新发明的魔法将会是她击败阿尔萨斯的有力武器，她要求我们研制出一种新的药剂，这种药剂要比以前出现在艾泽拉斯大陆上的任何一种都要更加猛烈，它会把阿尔萨斯和他的天灾军团彻底毁灭。；我的研究结果表明，野兽的血液也许是一种重要的药引。给我带回五瓶黑暗犬的血液来，我要验证一下自己的理论。",o="布瑞尔镇里的药剂师乔汉要求你收集5瓶黑暗犬的血液。",r={{i=2858,n="黑暗犬的血液",c=5}}},
  [368]={t="致麻药剂",d="在你帮我收集样本的同时，我的实验报告也出来了。看来我还需要更多的材料来进行进一步的研究，适当加强这种致麻药剂的威力。我要确保它们对天灾军团有效，在最短的时间内让它们失去狂暴的战力。根据我多年药理学的研究所得，药性即物性，那些麻木不仁的邪鳍鱼人与我将要配制的药剂不谋而合。；我需要5片邪鳍鱼人身上的鳞片，在北边或者西边的海滩上应该就能找到那些鱼人。",o="布瑞尔镇里的药剂师乔汉要求你收集5片提瑞斯法林地的邪鳍鱼人的鳞片。",p=367,r={{i=2859,n="邪鳍鱼人的鳞片",c=5}}},
  [369]={t="致麻药剂",d="在你出去收集鳞片的时候，我已经在我的藏书中找到了一些古老而有趣的文章。夜行蜘蛛分泌的毒液既是毒素又是良药，若能找到两者之间的临界点，就能提取出世界上威力最强的致麻药素。你该知道，天灾兵团是很难对付的敌人，不费点脑子可不行。；给我带些夜行蜘蛛的毒液回来，让我完成这个实验。我想知道毒液中的感染性元素是否能和我最新研制出来的病原体共存。据说这种蜘蛛一般在提瑞斯法林地的东部出没。",o="布瑞尔镇里的药剂师乔汉要你去收集4份邪恶的夜行蜘蛛的毒液样本。",p=368,r={{i=2872,n="邪恶夜行蜘蛛的毒液",c=4}},f=2},
  [370]={t="与血色十字军的战争",d="执行官阿伦的文件中对如何清除这群在我们的土地上肆虐的人类的问题作了详细的部署。情报表明，血色十字军派遣了派瑞恩队长以及足有一个整编旅的部队进驻了布瑞尔西南方的废塔。；去杀掉派瑞恩队长、3名血色十字军狂热者和3名血色十字军传教士，然后向我回报。",o="布瑞尔的执行官塞加德要求你杀掉派瑞恩队长、3名血色狂热者和3名血色传教士。",p=427},
  [371]={t="与血色十字军的战争",d="我们仍然处于战争状态中，而且血色十字军正在逐渐壮大。执行官阿伦给我的报告中提到，在瓦松队长的指挥下，血色十字军正以提瑞斯法东南部巴尼尔农场附近的那座废塔为据点肆意劫掠。；去杀掉瓦松和5名血色十字军苦行修士，这对十字军来说将是一次沉重的打击！",o="布瑞尔的执行官塞加德要求你杀掉瓦松队长和5名血色苦行修士。",p=370},
  [372]={t="与血色十字军的战争",d="血色十字军已经从提瑞斯法林地北部的废塔出发，穿过了法奥之墓。根据当前我们所掌握的情报，一个名叫麦拉其的军官指挥着这支邪恶的部队，他是个非常残忍的家伙。；我相信你能完成这个非常重要而又危险的任务。以黑暗女王陛下的名义，杀死麦拉其和他的两名保镖！",o="布瑞尔的执行官塞加德要求你刺杀麦拉其队长及他的两名保镖。",p=371,w={{i=3445,n="典礼小刀",c=1},{i=3071,n="迅捷短柄斧",c=1}},f=2},
  [373]={t="未寄出的信",d="搜查艾德温·范克里夫的尸体时，你从一堆杂乱的物品中找到了一封还未来得及发出的信。地址一栏上写着巴隆斯·阿历克斯顿，暴风城石工协会，城市大厅，教堂广场。；这显然是最近刚刚写好并封上的。",o="将艾德温·范克里夫的信交给巴隆斯·阿历克斯顿。",r={{i=2874,n="一封未寄出的信",c=1}}},
  [374]={t="死亡证明",d="执行官塞加德告诉我说你最近和血色十字军干上了，提瑞斯法林地里现在到处都是这帮讨厌的家伙。；黑暗女王麾下的瓦里玛萨斯大人计划将人类这种艾泽拉斯大陆上的渣滓与垃圾彻底清除掉。但当前的状况是，人类当中最麻烦的一群家伙——血色十字军——已经杀入了提瑞斯法林地，我们必须得面对他们的挑衅。；去吧，去给这群该死的血色十字军一点颜色看看，$c。给我带回10枚血色十字军徽记之戒，以此证明你对伟大的黑暗女王陛下与瓦里玛萨斯大人的忠诚。",o="给布瑞尔的亡灵卫兵伯吉斯带回10枚血色十字军徽记之戒。",p=427,r={{i=2875,n="血色十字军徽记之戒",c=10}},w={{i=3435,n="僵尸皮护腕",c=1},{i=3437,n="扣环腰带",c=1},{i=12299,n="网格手套",c=1}},f=2},
  [375]={t="死亡之寒",d="好冷啊……可怕的瘟疫正如冰冷的毒蛇一般在我的血管中逡巡，也许很快我就会彻底失去意志，但这世上没有任何东西能够阻止我为我们伟大的黑暗女王效命。一接到命令，我就开始为希尔瓦娜斯大人军队中那些死去的战士缝制尸袋。；但现在我的手却因为寒冷而颤栗不已。如果你能给我带回五张夜行蝙蝠的毛皮和一些粗线的话，我就可以给自己缝条毯子了。帮帮我，你，这样我就可以继续为黑暗女王陛下的事业效力了。",o="给布瑞尔的格雷森·戴德马带回5张夜行蝙蝠的毛皮和一些粗线。",r={{i=2876,n="夜行蝙蝠的毛皮",c=5},{i=2320,n="粗线",c=1}},w={{i=3833,n="内行披风",c=1},{i=5939,n="缝纫手套",c=1}},f=2},
  [376]={t="被诅咒者",d="我的任务包括照料受伤的士兵，缝制铠甲和衣服，还有为暗影牧师萨维斯提供任何他可能需要的支持。；看起来，你也即将加入到为他效力的队伍中……我猜是要猎杀那些没脑子的家伙。好吧，如果你还想留着你的小命的话——我想你一定是的——也许我能帮助你。我这里没有足够的狼爪子和蝙蝠翅膀了，如果你能帮我弄一些来的话，我会帮你找几件铠甲。在这里的西北方可以找到大群的狼和蝙蝠。",o="新兵艾尔雷斯需要6只食腐狼的爪子和6只夜行蝙蝠翼。",r={{i=3265,n="食腐狼的爪子",c=6},{i=3264,n="夜行蝙蝠翼",c=6}},w={{i=6060,n="麻布护腕",c=1},{i=2173,n="旧皮腰带",c=1}},f=2},
  [377]={t="罪与罚",d="贵族议会好象嫌他们对暮色森林的漠不关心还不够过分，现在他们居然无视夜色镇议会的存在，决定把迪克斯特·瓦德囚禁在暴风城，而不是按照埃伯洛克公爵大人的判决将这个恶棍斩首！；迪克斯特·瓦德是在把墓地里的尸体卖给摩本特·费尔时被抓住的，这理应是死罪。可是暴风城却认为他们才拥有对他的处决权！；去暴风城的监狱把瓦德杀掉，把他的手给我带回来作为证明，我会奖赏你的。",o="夜色镇的米尔斯迪普议员要你杀死迪克斯特·瓦德，并把他的手带回来作为证明。",r={{i=3628,n="迪克斯特·瓦德的手掌",c=1}},w={{i=2033,n="大使之靴",c=1},{i=2906,n="夜色郡锁甲护腿",c=1}},f=1},
  [378]={t="卡姆·深怒",d="你已经向我们展示出了你对麦格尼陛下的忠诚，$c。而且我也深刻地感受到了你对那些黑铁矮人的仇恨。；我必须要坚守岗位，因此，我不得不把一个本应由我亲自去完成的重要任务交给你。根据罗戈收集到的情报显示，卡姆·深怒正是袭击萨多尔大桥的元凶。由于֦ɀ布下的邪恶计划，长须才失去了他的亲人。；这个刽子手由于某些政治原因被扣押在了暴风城的监狱里。我要他死，你。为了长须！杀死卡姆·深怒，把他的徽记给我带回来！",o="丹莫德的莫特雷·加玛森要求你把卡姆·深怒的徽记交给他。",p=303,r={{i=3640,n="卡姆·深怒的徽记",c=1}},w={{i=3562,n="辩护腰带",c=1},{i=1264,n="碎头者",c=1}},f=1},
  [379]={t="口渴的比格维兹",d="你需要能量源，我可以帮你。但是你知道我要什么吗？我要喝的！给我弄五只废土水袋来，然后我就会把4711-FTZ交给你。；现在……你想知道在什么地方可以找到废土水袋，对吗？去这里的东边找废土游牧民吧，他们身上会带着这种水袋。",o="给加基森的首席工程师沙克斯·比格维兹带去五只废土水袋。",p=243,r={{i=8483,n="废土水袋",c=5}}},
  [380]={t="夜行蜘蛛洞穴",d="我们的一项最重要的任务就是获取赖以生存的自然资源。即使在当年联盟最鼎盛的时候，黄金资源也是非常缺乏的。；这里的西北面有一处金矿，我们需要矿洞里的资源，但是那里蜘蛛横行，我们根本无法进去采掘金矿。我手上没有人可以去完成这项任务，所以我们只有一步一步慢慢地来。去那里看看吧，也许你能做些什么……",o="执行官阿伦要你去杀掉8只小夜行蜘蛛和5只夜行蜘蛛。",p=376,w={{i=3270,n="麻布外衣",c=1},{i=3273,n="皱褶锁甲外衣",c=1},{i=3272,n="僵尸皮护腿",c=1}},f=2},
  [381]={t="血色十字军",d="得知我们在金矿的进展非常顺利，你一定很开心吧？得益于你的帮助，我们终于可以把注意力放到别的事情上了。；我的斥候报告说，一支血色十字军的小分队在东南方创建了营地。血色十字军是一个卑鄙的组织，他们视我们为死敌，只要有一个亡灵——无论是巫妖王的爪牙还是我们被遗忘者——还活着，他们就不会停止追杀我们的行动。所以我们必须先发制人！；你要多加小心，这些邪恶而狂妄的十字军是一群非常危险的家伙。",o="从血色信徒和血色新兵身上收集12枚血色十字军臂章，把它们交给执行官阿伦。",p=380,r={{i=3266,n="血色十字军臂章",c=12}},w={{i=3268,n="亡灵匕首",c=1},{i=3269,n="亡灵木槌",c=1},{i=3267,n="亡灵短剑",c=1},{i=5779,n="亡灵重剑",c=1}},f=2},
  [382]={t="十字军信使",d="布瑞尔那边的上级给我发来的文件显示，有一个从血色修道院出发的血色十字军斥候已经潜入了丧钟镇。有报告说这个人携带着非常重要的情报。至于更多的细节，我不得而知。但不管怎么样，我们必须得到这份情报！；你是我眼下能调动的最合适的人选，$n。找到那个信使，带回你能弄到的任何情报。",o="到十字军营地去杀掉信使迈文·考加尔，将你发现的情报交给执行官阿伦。",p=381,r={{i=2885,n="血色十字军文件",c=1}},w={{i=3277,n="执行官法杖",c=1},{i=3276,n="亡灵卫兵圆盾",c=1}},f=2},
  [383]={t="重要情报",d="我必须将这些东西交给我的上级——执行官塞加德，他就在布瑞尔。有了这份详尽的情报，我们就能给血色十字军以沉重的打击。你在丧钟镇对我们做出了很大的贡献，现在我要你去把这份情报及时交给塞加德，我想他能帮你找到更多能让你大展身手的工作。；沿着这条路向北走出丧钟镇，在进入提瑞斯法林地以后，你很快就会来到一个十字路口，这时向东走，然后一直向前就可以到布瑞尔了，路上有一座炉灰庄园可以帮你确认自己的方向。",o="把血色十字军文件交给布瑞尔的执行官塞加德。",p=382,r={{i=2885,n="血色十字军文件",c=1}}},
  [385]={t="捕猎鳄鱼",d="很多猎人到洛克莫丹来都是为了捕猎这里的鳄鱼。总有一些商人专门寻找这种鳄鱼皮，用它们来制作衣物或是护甲，还有些人则喜欢品尝鳄鱼肉。；我们一直在进行这种贸易，但交易量并不是很大，因为鳄鱼很凶猛，而且它们一般都盘踞在洛克湖中的小岛上。嘿，别被我的话给吓倒了，和鳄鱼较量一番对你来说也是一种历练。；你看能不能……",o="收集5块鳄鱼肉和6张鳄鱼皮，把它们交给旅行者营地里的马雷克·铁心。",r={{i=2924,n="鳄鱼肉",c=5},{i=2925,n="鳄鱼皮",c=6}},f=1},
  [386]={t="伸张正义",d="可怕的塔格尔是加塞尔佐格手下的一个高级杀手。他杀人的手法十分残忍，即使以兽人的标准来看也是残暴无比。那些为了保卫国家而奋勇作战的战士们落在他手里都会被他折磨致死。这个恶棍现在被关在暴风城的监狱里，被判处了死刑。不过，这件事情好象出了点小差错，一个官僚习气十足的贵族推迟了处死他的日期。我敢打赌这里面一定有鬼。；处死塔格尔吧，你。到暴风城的监狱里去，在他玩出什么把戏之前把他干掉。",o="把塔格尔的徽记带给湖畔镇的卫兵伯尔顿。",r={{i=3630,n="塔格尔的徽记",c=1}},w={{i=3400,n="磷铝长剑",c=1},{i=1317,n="硬根法杖",c=1}},f=1},
  [391]={t="监狱暴动",d="让我们把话挑明了说吧，$n：我不信任你。但是，现在的情况紧急，我也管不了那么多了。；你到下面去干掉那个该死的斯瑞德，把他的徽记带给我。；还有，如果你胆敢跟他合计什么把戏，或者你不上来了的话……只要被我抓到你，就准备跟那群蛆死在一块吧。",o="杀死巴基尔·斯瑞德，把他的徽记带给监狱的典狱官塞尔沃特。",p=389,r={{i=2926,n="巴基尔·斯瑞德的徽记",c=1}}},
  [392]={t="好奇的访客",d="在斯瑞德刑期的第一年里，从来从没有人探视过他。我猜当时迪菲亚兄弟会认为他已经彻底没用了，所以准备任他自生自灭。；然而几个月前，一切都变了。有人开始定期探视他……每周一到两次。那是个奇怪的男人，沉默寡言。我有点疑心，但他的证件是真实且合法的。；他的名字叫麦里克，这是他的一些资料。我觉得他可能不会再来探视斯瑞德了。",o="将神秘访客的资料交给暴风城的巴隆斯·阿历克斯顿。",p=391,r={{i=8687,n="神秘访客的资料",c=1}}},
  [393]={t="往日的阴影",d="我确实没什么线索，$n。但或许另外有人能帮上你的忙，而且他还欠了我一个人情——好了，现在不是说那个的时候。暴风城兵营中的军情七处首领马迪亚斯·肖尔或许能轻松搞定这类事。；如果说有谁知道这事的话，一定就是他，他此刻就在旧城区。",o="与旧城区的马迪亚斯·肖尔谈一谈。",p=392,r={{i=8687,n="神秘访客的资料",c=1}}},
  [396]={t="觐见国王",d="我准备了一份报告呈递给国王陛下。当我听说了你最近的事迹之后，我认为你是递送这份报告的最佳人选。别担心，国王陛下一定会嘉奖你的。；你的觐见已经被列入了陛下的日程表，所以你最好快点到暴风要塞里去等待召见。",o="将有关迪菲亚兄弟会的报告送给暴风要塞里的国王瓦里安·乌瑞恩。",p=395,r={{i=2956,n="有关迪菲亚兄弟会的报告",c=1}},f=1},
  [397]={t="You Have Served Us Well",o="Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.",p=336,f=1},
  [398]={t="悬赏：蛆眼",d="悬赏：蛆眼！；这只名叫蛆眼的豺狼人臭名昭着，即使是在它的同类眼中都显得非常邪恶而污秽，它因为对被遗忘者们犯下了不可饶恕的罪名而被判处了死刑，这只卑鄙的野兽为巫妖王的军队偷盗了无数的尸体。上次有人看到蛆眼作恶是在布瑞尔北边的加伦鬼屋。；布瑞尔镇将为执行这项判决的勇敢者提供一份高额的奖金。完成任务之后，请将这只野兽的爪子交给执行官塞加德。；只有弱者才会有怜悯之心。",o="杀死蛆眼，并将他的爪子交给布瑞尔的执行官塞加德以换取酬劳。",r={{i=3635,n="蛆眼的爪子",c=1}},w={{i=5941,n="黄铜鳞甲短裤",c=1},{i=3444,n="提勒的外衣",c=1}},f=2},
  [404]={t="腐烂的爪子",d="有一小撮天灾军团的士兵已经渗入了提瑞斯法林地，在布瑞尔以西一带的旧桥附近活动。；去那边去增援我们的部队，杀光所有你见到的腐烂的死者和破碎的尸体。把他们都给我拆成骨头架子，然后把他们那腐烂的爪子给我带回来，我会奖励你的。",o="给布瑞尔的亡灵卫兵迪林格尔带回7只腐烂的爪子。",r={{i=2855,n="腐烂的爪子",c=7}}},
  [405]={t="流浪的巫妖",d="幽暗城里的一位法力强大的高阶法师比索·埃斯沙德给了我一个任务，让我去为他找一个与天灾军团有着丰富斗争经验的勇士。你，你，显然就是他要找的人。；现在立刻去向比索报到，他会给你指派新的任务。我也不清楚任务的细节，但大致上好象是要招安一名独居的巫妖之类的。这份工作可能会很危险。；去做好准备吧，玩家。你绝对不能失败。；比索就在幽暗城的魔法区里。",o="将塞弗伦的命令交给幽暗城的比索·埃斯沙德。",p=358,r={{i=3017,n="塞弗伦的命令",c=1}}},
  [408]={t="系列墓穴",d="如今阿加曼德磨坊已经成了天灾军团的一处重要据点，其中防守最为坚固的地方就是阿加曼德的系列墓穴了。天灾军团的一个兵团就驻守在那里，他们由一个名叫达高尔队长的骷髅领导着。他们还利用某种通灵术复活了阿加曼德系列的死者们，并打算利用它们来对付我们。；我们绝对不能允许这种事情发生，你必须阻止它。到阿加曼德系列墓穴去，战胜那些还魂的阿加曼德系列的死尸们。；还有，把达高尔队长的徽记也给我带回来。",o="杀死8个哀嚎的鬼魂和8个腐烂的古尸。；消灭达高尔队长，并将他的徽记交给布瑞尔的执政官塞弗伦。",p=355,r={{i=3082,n="达高尔的徽记",c=1}},w={{i=3446,n="暗木法杖",c=1},{i=3440,n="碎骨者",c=1}},f=2},
  [409]={t="证明忠诚",d="你说你没有被巫妖王控制住自己的思想，这一点已经由比索在我书上灌入的魔法证实了。但是，你仍然得先证明自己是天灾军团的敌人，这样我才会彻底信任你。；在这座岛屿南边的小岛上有一处古老而血腥的祭坛，那里当前被一个强大的天灾军团斥候莉莉丝·奈法拉所占据着。；从我身边的这个木箱里拿出一根诱灵蜡烛，然后将其点燃并放到祭坛上，莉莉丝会很快醒来。消灭莉莉丝，这样一来，我就会相信你确实是巫妖王的敌人了。",o="拿上一根诱灵蜡烛。；召唤出莉莉丝·奈法拉并杀死她。；然后向岛上的冈瑟尔回报。",p=366},
  [411]={t="巫妖归顺",d="拜托你，请将这块虚空宝石带给我的老朋友比索。这样我就能和他交流了……我有好多事想和他说呢。",o="将虚空宝石交给幽暗城的比索·埃斯沙德。",p=409,r={{i=3081,n="虚空宝石",c=1}},f=2},
  [412]={t="自动净化装置",d="通过对诺莫瑞根现状的进一步分析，我们发现不但那些该死的穴居人没有被消灭，反而有更多的侏儒变成了丧心病狂的、邪恶的怪物。；我和奥齐希望用我们的最新发明——自动净化装置——来扭转这种局面。这台机器即将大功告成，不过我们急需一些多档齿轮和自适应齿轮才能搞定最后的部分，请从诺莫瑞根的麻疯侏儒那里弄些过来吧。",o="收集8个多档齿轮和8个自适应齿轮，把它们交给卡拉诺斯的拉兹·滑链。",r={{i=3083,n="自适应齿轮",c=8},{i=3084,n="多档齿轮",c=8}},w={{i=3152,n="驾驶手套",c=1},{i=3153,n="浸油的披风",c=1}},f=1},
  [413]={t="微光酒",d="我希望我兄弟维拉特能够品尝一下我最新酿制的微光酒。他是一个在南面的警戒塔里执勤的巡山人，就是靠近洛克莫丹边界的那两座哨塔里的一座。；他不是酿酒师，但是他非常喜欢喝酒，而且我相信他一定喜欢这种酒的。；你能替我把这桶微光酒交给他吗？",o="把这一大桶微光酒交给巡山人维拉特·麦酒。",p=315,r={{i=3085,n="一大桶微光酒",c=1}}},
  [416]={t="狗头人的耳朵",d="我们在西边遇到了点麻烦。坑道鼠狗头人在那里的丘陵地带建起了巢穴，把我们的地盘弄得乌烟瘴气！；我们必须把他们给消灭掉。去捕杀那些坑道鼠狗头人，把他们的耳朵拿回来给我，我就给你赏金。；坑道鼠狗头人的巢穴就在塞尔萨玛北边的山脚下。",o="收集12只坑道鼠的耳朵，把它们带给塞尔萨玛的巡山人卡德雷尔。",r={{i=3110,n="坑道鼠的耳朵",c=12}},w={{i=3158,n="褐色毛护腕",c=1},{i=860,n="骑兵战靴",c=1}},f=1},
  [417]={t="驾驶员的复仇",d="莫里·铁钻在他的日记中写道，他受到了一头名叫癞爪的巨型冰爪熊的袭击。他赶走了这只野兽，不过自己也已遍体鳞伤。；从莫里尸体上的伤痕判断，癞爪一定又折回来杀死了他。；然而，莫里在他的日记中写下了他最后的遗愿：；杀死癞爪，为我复仇。",o="杀死癞爪。；把它的肮脏的爪子和莫里·铁钻的日记交给驾驶员塞克·锤足。",p=419,r={{i=3183,n="肮脏的爪子",c=1},{i=3117,n="莫里·铁钻的日记",c=1}},w={{i=2218,n="工匠匕首",c=1},{i=1009,n="紧凑战锤",c=1}},f=1},
  [419]={t="The Lost Pilot",o="Find Pilot Hildelve.",f=1},
  [420]={t="森内尔的观察站",d="隧道里的穴居人非常具有攻击性，它们会毫不犹豫地对隧道中的过客发动袭击。不过你看起来挺结实的，应该不会有什么危险。；方向？如果你要找森内尔，就到卡拉诺斯去吧。；一直穿过隧道，出去之后沿着大路向前走，没几步就到卡拉诺斯了。",o="把格瑞林的报告交给卡拉诺斯的森内尔·白须。",p=282,r={{i=2619,n="格瑞林的报告",c=1}}},
  [421]={t="证明你的价值",d="希尔瓦娜斯主人已经授命瓦里玛萨斯大人全权负责征服南方的人类和矮人的领土。；但阿鲁高那个蠢货——过去他是达拉然的大骗子，现在他是影牙城堡里一只中了诅咒的困兽——他那不计后果的魔法给银松森林里那座极具战略意义的要塞带来了一场大浩劫。；我需要一些拥有优秀战斗技巧的人帮我把阿鲁高rn留下的烂摊子给收拾掉。杀死5只月怒白头狼人以证明你的实力吧，这些野兽一般都在山脚下的道路两旁游荡。",o="瑟伯切尔的达拉尔·道恩维沃尔要求你杀死5只月怒白头狼人。"},
  [422]={t="阿鲁高的愚行",d="阿鲁高这样一个施法能力比一张纸还要浅薄的家伙居然能够得到肯瑞托的承认，这让我实在难以想象。；现在最重要的是，搞清楚阿鲁高究竟使用了什么魔法，这样一来我才能对付他，并为黑暗女士平定银松森林。；阿鲁高曾经住在桥北的麦田旁，一名亡灵哨兵回报说，他发现了阿鲁高拥有的几本法术书，但无法偷取它们。把其中一本名叫《阿鲁高的拯救》的法术书从其它书里找出来，并带回来给我。",o="为瑟伯切尔的达拉尔·道恩维沃尔找回《阿鲁高的拯救》。",p=421,r={{i=3155,n="阿鲁高的拯救",c=1}}},
  [423]={t="阿鲁高的愚行",d="在我研究过阿鲁高的书以后，我最坏的设想不幸被证实了。肯瑞托竟在那个连给达拉然的法师们扫屋子都不配的家伙干出那种愚昧行径的时候完全不闻不问，一群蠢货！；阿鲁高使用了附有魔法的物品来加强他薄弱的施法能力。我需要尽快研究一下这些物品。去杀掉一些月怒暴食者和月怒魔魂狼人，收集他们身上带着的魔法镣铐供我研究之用。这些污秽的生物在北边和东边到处都是。",o="给瑟伯切尔的达拉尔·道恩维沃尔带回6副暴食者镣铐和3副魔魂镣铐。",p=422,r={{i=3156,n="暴食者镣铐",c=6},{i=3157,n="魔魂镣铐",c=3}}},
  [424]={t="阿鲁高的愚行",d="看来想揭开隐藏在阿鲁高所用的巫术中的黑暗秘密并不简单，这比我想象中要花掉的时间多出很多。；但与此同时，我需要你来帮忙处理一下我们的亡灵哨兵发现的一个小问题。似乎阿鲁高的魔法已经控制了东南方山中的埃利姆矿洞。；这座矿洞对瓦里玛萨斯大人的推进有着非常重要的意义。；我希望你能干掉矿洞里的工头，白毛狼人格瑞姆森。只要他一死，矿洞就是我们的了。",o="杀死白毛狼人格瑞姆森，把他的头带给瑟伯切尔的达拉尔·道恩维沃尔。",p=423,r={{i=3634,n="格瑞姆森的徽记",c=1}}},
  [425]={t="邪恶的伊瓦",d="我正在和哥哥奎恩执行侦察银松森林的任务，并准备向最高执行官哈德瑞克复命。但我们进行得不太顺利——我们穿过这座农庄的时候，被食尸鬼伊瓦袭击了。；我们从伊瓦那里逃了出来，但他还是重创了奎恩。喝了你给他的药水以后，哥哥正逐渐痊愈，但这段时间里伊瓦仍可能会过来。；杀死伊瓦，以保证奎恩有足够的时间复原吧。伊瓦一般都躲在谷仓那里，在我放松警戒的时候它就会开始行动。",o="杀死邪恶的伊瓦，并将伊瓦的徽记带给伊瓦农庄的兰妮·尤瑞克。",p=430,r={{i=3621,n="伊瓦的徽记",c=1}},w={{i=3453,n="软垫护腕",c=1},{i=3583,n="风化腰带",c=1}},f=2},
  [426]={t="磨坊告急",d="天灾军团正试图在阿加曼德磨坊那边创建起一座前哨基地。如果他们得逞了，那么他们在提瑞斯法的军事行动将得到有利的支持。；上头已经发话下来了，必须将磨坊那边的天灾军团势力全部清除干净。；到磨坊那边去，从断骨士兵和碎颅士兵身上收集锯齿肋骨，再从暗眼骷髅法师身上收集焦黑的徽记。；你只需沿着道路一直向西走，过桥以后在第一个岔路口转向北就行了。当你看到风车的时候，战斗随时都会开始。",o="收集5根锯齿肋骨和3个焦黑的徽记，然后向布瑞尔的亡灵卫兵迪林格尔回报。",p=404,r={{i=3162,n="锯齿肋骨",c=5},{i=3163,n="焦黑的徽记",c=3}},w={{i=3447,n="墓穴行者之靴",c=1},{i=3834,n="结实的布质长裤",c=1}},f=2},
  [427]={t="与血色十字军的战争",d="执行官阿伦大人提供给我们的文件中指出，我们将无法避免与那些卑劣的血色十字军进行一场战争。我们已经知道了他们穿越提瑞斯法林地所走的那条小径的确切位置。；但亡灵卫兵还有其它艰巨的任务，巫妖王的军队正在夜色中逐渐壮大起来。我们需要一些像你这样的志愿者来把那群血色十字军送进坟墓。；顺着镇外的道路向西走，穿过索利丹农场到废塔那里去，杀死10名血色十字军战士。以此来证明你有足够的能力为黑暗女王陛下服务。",o="布瑞尔的执行官塞加德要求你杀掉10名血色战士。",p=383},
  [429]={t="荒野之心",d="我的哥哥奎恩被食尸鬼伊瓦打成了重伤，我不知道在没有魔法帮助的情况下，他是否还能痊愈。尽管我不是一个药剂师，但我知道我们的药剂师能用变色的狼心制作治疗药水。；帮我收集一些心脏并带给南边坟场的药剂师伦弗利尔，然后把做好的药水带回来。；这附近和东边的玛尔丁果园之间有不少座狼在到处游荡。",o="收集6颗变色的狼心，把它们交给瑟伯切尔的药剂师伦弗利尔。",r={{i=3164,n="变色的狼心",c=6}}},
  [430]={t="回到奎恩身旁",d="这就是那种能帮助奎恩·尤瑞克复原的药水。；现在，如果你没什么事的话，我就先失陪了。我还有重要的工作要继续……",o="将奎恩的药水带给瑟伯切尔北方伊瓦农场的奎恩·尤瑞克。",p=429,r={{i=3165,n="奎恩的药水",c=1}}},
  [434]={t="伏击！",d="等我做好间谍机器人的伪装，他会进去和莱斯科瓦谈话。守卫会让他进去的。；在你帮我准备材料的同时，我会暗示马尔松，让他再次和莱斯科瓦会面，我甚至会给他一点假消息，好让他对此深信不疑。；接下来，莱斯科瓦就会让他的卫兵解散，然后在花园里等马尔松。等你听到他们谈起迪菲亚兄弟会的时候就采取行动。你要把他们两个都干掉。听懂了吗？；当你完成任务之后，尽快向提亚斯回报。",o="等待葛瑞格·莱斯科瓦公爵和沉默之刃马尔松在花园里的对话结束，杀死他们两个，之后向暴风城的提亚斯回报。",p=2746},
  [435]={t="Escorting Erland",o="Escort Erland through the wolves, to Rane Yorick.",f=2},
  [437]={t="亡者农场",d="我们在银松森林的探子回报说，腐皮豺狼人在北边的一处名叫亡者农场的地方创建了一个基地。我们已经派遣了小股突袭部队去对付他们，但每次他们都能得到女妖奈塔拉什的增援，每次都是她的魔法击溃了我们的部队。；我们必须杀掉奈塔拉什。；到亡者农场去杀掉那里的腐皮豺狼人。如果没有看到奈塔拉什的话，就继续屠杀腐皮豺狼人直到她出现为止，然后击败她。；她的灵魂将会变成尘土。把这些尘土带回来，作为你杀死了她的证明。",o="清剿亡者农场的腐皮豺狼人。；当奈塔拉什出现时，把她也杀掉。；将奈塔拉什的灵魂带给瑟伯切尔的高级执行官哈德瑞克。",r={{i=3622,n="奈塔拉什的灵魂",c=1}},f=2},
  [439]={t="线索",d="在一大堆尸体中间，有一只裸露的手。这是一只女人的手，虽因瘟疫而导致皮肤上布满红痘，但仍然十分白皙。；她的手上戴着一只戒指。你从尸体的手上取下这只戒指，看到戒指内环中有一道铭文：；“赠予黛丽娅”",o="将黛丽娅的戒指带给瑟伯切尔的高级执行官哈德瑞克。",p=438,r={{i=3234,n="黛丽娅的戒指",c=1}}},
  [440]={t="黛丽娅的戒指",d="如果你想找到黛丽娅的丈夫或情人，也就是送给她戒指的那个人的话……去找布瑞尔的执政官塞弗伦谈谈吧。他或许拥有最近的死亡记录，当然，如果你走运的话，还能发现谁是黛丽娅。；但我也不抱希望。无论给她戒指的人是谁，现在恐怕也已经死了。如果他成了亡灵，也就不会再关心黛丽娅了。",o="将黛丽娅的戒指带给布瑞尔的执政官塞弗伦。",p=439,r={{i=3234,n="黛丽娅的戒指",c=1}}},
  [441]={t="拉林夫与幽暗城",d="黛丽娅有个丈夫叫拉林夫，他现在居住在幽暗城。如果居住在布瑞尔的这位黛丽娅就是这只戒指的主人，想必他应该知道。；拉林夫就在幽暗城的贸易区。",o="把黛丽娅的戒指交给拉林夫。",p=440,r={{i=3234,n="黛丽娅的戒指",c=1}}},
  [442]={t="突袭芬里斯岛",d="现在是把天灾军团彻底赶出银松森林的时候了。；你必须再去一次那个岛，杀死图勒·鸦爪，把他的徽记提来见我！；这个任务非常危险，但是你也应该知道它的重要性，你。所以你只能成功，不能失败。",o="将图勒的徽记带回给瑟伯切尔的高级执行官哈德瑞克。",p=448,r={{i=3623,n="图勒的徽记",c=1}},w={{i=3461,n="法官长袍",c=1},{i=3462,n="鹰爪之击",c=1}},f=2},
  [443]={t="腐皮豺狼人的脓液",d="在我们对芬里斯岛展开一次突袭行动之前，我们必须得弄清楚谁是腐皮豺狼人背后的真正主人，我们的药剂师们相信它们的体内发生了某种神秘的变化。；到破旧渡口东边的芬里斯岛去，收集一些腐皮豺狼人身上流出的脓血，然后把脓液交给瑟伯切尔外的药剂师伦弗利尔。",o="给瑟伯切尔的药剂师伦弗利尔带去8瓶腐皮豺狼人的脓液。",p=438,r={{i=3236,n="腐皮豺狼人的脓液",c=8}}},
  [444]={t="腐皮豺狼人的产生",d="我还原了你带给我的脓液，并把它们分离成了一些基本成分。我的发现还不是结论性的，但我可以肯定恶魔法术和死灵法术在这脓液的产生过程中起了极其重要的作用。；在我继续研究脓液的同时，我希望你能给幽暗城的比索·埃斯沙德带些样本过去。比索虽然不是一名药剂师，但他在魔法方面的学识将会帮助我们揭开这些腐皮豺狼人的秘密。；快去吧，比索就住在幽暗城的法师区。",o="将脓液样本交给幽暗城的比索·埃斯沙德。",p=443,r={{i=3237,n="脓液样本",c=1}}},
  [446]={t="图勒·鸦爪",d="这种脓液是我以前的一个同僚图勒·鸦爪制成的。在大战之前，他是一个有着大好前途的年轻法师，但在巫妖王的势力崛起之后，他背叛了他的朋友与兄弟，加入了天灾军团。；我没料到他还活着，更没有想到的是，原来是他在领导腐皮豺狼人与我们对抗。；我对他的许多法术都有所了解，应该能帮忙调制出一种能击败他们的药剂。把这个卷轴交给药剂师伦弗利尔，卷轴上面写着调制药水所需要的咒语。",o="把比索的卷轴交给银松森林中的药剂师伦弗利尔。",p=444,r={{i=3250,n="比索的卷轴",c=1}}},
  [447]={t="奇妙的配方",d="天灾军团的威胁越来越严重。不过，只要我的药剂成功，我们就可以一劳永逸地消灭这些邪恶的存在。；我的研究已经证明，将灰熊心脏中提取出的药素和蜘蛛血混合在一起，就可以制成一种让天灾军团丧失邪恶力量的药剂。从西北方的粘丝洞中的蜘蛛身上和银松森林中游荡着的熊身上采集一些样本回来，然后把它们送给幽暗城皇家药剂师学会里的大药剂师法拉尼尔。",o="收集6个灰熊的心脏和6份粘稠的血液样本，并将这些东西送给幽暗城的大药剂师法拉尼尔。",r={{i=3253,n="灰熊的心脏",c=6},{i=3254,n="粘稠的血液",c=6}}},
  [449]={t="亡灵哨兵的报告",d="尽管奎恩的伤基本已经好了，但我仍想尽可能快地把报告呈送给高级执行官哈德瑞克。这里面的情报对被遗忘者来说十分重要，它将关系到我们在整个银松森林的统治地位。",o="将亡灵哨兵的报告的报告交给瑟伯切尔的高级执行官哈德瑞克。",p=435,r={{i=3252,n="亡灵哨兵的报告",c=1}}},
  [450]={t="奇妙的配方",d="其实你还能为皇家药剂师学会再做一些事情，你。；当初阿鲁高在整个森林中施展了他那可恶的魔法时，我们当中一位最有前途的成员——药剂师伯纳德，也被他诅咒了。现在伯纳德已经变成了一个忠于阿鲁高的傀儡。即使这样伯纳德的研究成果可能对我们非常有用，因为他在多年以前曾经研究过一种遏制天灾军团的药剂。；将伯纳德的日记从他在焚木村旅店中的研究室里找出来，然后把日记交给药剂师伦弗利尔。",o="从焚木村的旅店中找到伯纳德的日记，把它交给瑟伯切尔的药剂师伦弗利尔。",p=447,r={{i=3255,n="伯纳德的日记",c=1}}},
  [451]={t="奇妙的配方",d="根据博拉尔德的研究日记，采自湖岸爬行者和潜藏者身上的苔藓会对我们制造出这种药剂大有助益。这些野兽就栖息于东边的洛丹米尔湖中的群岛上。；他还提到曾在一只邪鳍鱼人身上发现了一种非常稀有的硬瘤，显然这种瘤很难得到，博拉尔德也只找到了一个。；收集一些苔藓和那种稀有的瘤，把它们带给幽暗城的大药剂师法拉尼尔。",o="收集6份湖岸爬行者苔藓的样本、6份湖岸潜藏者苔藓的样本和1块硬瘤，把它们交给幽暗城的大药剂师法拉尼尔。",p=450,r={{i=3256,n="湖岸潜藏者苔藓",c=6},{i=3257,n="湖岸爬行者苔藓",c=6},{i=3258,n="硬瘤",c=1}},w={{i=3451,n="夜光之药",c=1},{i=3582,n="耐酸披风",c=1}},f=2},
  [452]={t="Pyrewood Ambush",o="Help Deathstalker Faerleia kill the Pyrewood Council.",w={{i=3450,n="费雷亚之盾",c=1},{i=2818,n="延展皮裤",c=1},{i=3449,n="秘法披肩",c=1}},f=2},
  [453]={t="搜寻乌鸦岭",d="祝你好运，你。我希望你能找到这个家伙，也希望他还活着。；外面可没有夜色镇这么安全，他可能早就成了野兽的猎物。",o="找到那个模糊的人影。你的线索：；他不是夜色镇的本地人。；他是个紧张而敏感的人。；他离开夜色镇往西边去了。",p=266,r={{i=2161,n="斯温农场中的书",c=1}}},
  [456]={t="自然的平衡",d="你好，你。我是管理员伊尔萨莱恩。我的职责是维护幽影谷一带的自然平衡。；今年的春雨似乎比往年来得都要连绵不绝，这导致了森林中某些动物的过度繁殖，而其它动物就遭了殃。；其中，夜刃豹和草刺野猪的族群已经过于庞大了，幽影谷无法为它们提供更多的食物。去吧，年轻的$c，去减少野猪和夜刃豹的数量，以保证自然的和谐。",o="杀死4只夜刃豹幼崽和4只草刺野猪幼崽，然后向管理员伊尔萨莱恩复命。",w={{i=5394,n="箭术训练手套",c=1},{i=11187,n="树叶护腕",c=1}},f=1},
  [457]={t="自然的平衡",d="削减幽影谷地中生物幼兽的数量是一个很好的开始，你，但这还远远不够。；如果问题不能得到根本解决的话，森林中的资源还是很快就会被耗尽的。杀死某些生物对于生长在这片土地上的所有生物来说都是有益的。为了自然的平衡，到森林里去清除一些癞皮夜刃豹和一些草刺野猪吧。",o="管理员伊尔萨莱恩要求你杀死5只癞皮夜刃豹和5只草刺野猪。",p=456,w={{i=5405,n="布织披风",c=1},{i=6058,n="被熏黑的皮腰带",c=1}},f=1},
  [459]={t="森林守护者",d="一些邪恶的事物正在泰达希尔的森林中滋生着。看看那些原先性情温和的熊怪们居住的地方吧。他们放弃了自己的家园，聚集在了所谓的脊骨部落的名下。；一定是那些腐朽毒恶的魔苔的瘴气造成了这种变异。小劣魔和劣魔也在幽影谷滋生开来，惊扰着这里的居民。；去和这些小劣魔和劣魔战斗吧，你，观察一下他们是否真的是受了魔苔的影响。",o="收集8块魔苔，把它们交给塔琳德拉。",p=458,r={{i=3297,n="魔苔",c=8}},w={{i=5398,n="布织护腿",c=1},{i=5399,n="追踪之靴",c=1},{i=11190,n="藤蔓手套",c=1}},f=1},
  [460]={t="支离破碎",d="你看上去跟那帮腐皮豺狼人不一样，这真好。我都快绝望了……；我叫奥拉瑞克，过去曾是图勒的大管家兼保镖。他用他的魔法“保护”了我，使我免受“亡灵疫病”的影响，但他的魔法也让我变成了这个半死不活的样子。而且，自从图勒创造了那群该死的腐皮豺狼人之后，他竟然拿走了我的徽记……还把它给那群豺狼人当球踢！；拜托，把我带到芬里斯城堡的马厩旁……",o="将奥拉瑞克的徽记带到他的坟墓旁。",r={{i=3317,n="会说话的徽记",c=1}}},
  [461]={t="密室",d="我知道在这城堡中有间密室，密室里藏着一件对图勒和他的同伙们来说很宝贵的东西，也许那里面也有些对你很有用的东西。把我带到那里去！；这密室就在城堡西南的塔里，在一处满是灰尘的柜子后面。；带上我的身子，但是不要靴子…这靴子就没合适过……",o="将奥拉瑞克带到密室去。",p=460,r={{i=3318,n="奥拉瑞克的遗骸",c=1}}},
  [464]={t="龙喉战旗",d="按理说，龙喉氏族的兽人应该已经在第二次兽人战争中全部被消灭干净了呀。那时，他们失去了对红龙的控制，而被奴役了许久的红龙对兽人极度仇恨，所以就到处猎杀他们。只有一小部分龙喉兽人从格瑞姆巴托逃了出来，躲进了维尔加挖掘场东边的山里。；现在他们的族群似乎又恢复了兴盛，有线报说他们在米奈希尔的东北方创建了一座营地。；我们要你去进攻那座营地，并带回一些战旗作为功勋评定的证据。",o="给斯托菲队长带回8面龙喉战旗。",p=473,r={{i=3337,n="龙喉战旗",c=8}}},
  [465]={t="纳克罗什的优势",d="当你在和那些龙喉氏族的兽人作战时，我们又获得了更多有关他们的作战计划的情报。；首先是一个坏消息，纳克罗什正在大量地建造投石车，计划一举攻陷米奈希尔！还有一个好消息，经过在丹奥加兹一带的艰苦奋战，我们已经把他们的援军彻底挡了回去！；现在你所要做的就是毁掉那些投石车，它们当前仍被停放在龙喉氏族的营地里。；给，带上这些火绒。你得先在营地里杀出一条血路，找到那些投石车，然后再用这些火绒烧了它们。；完成这一切之后，就去找纳克罗什，把他给干掉。我们",o="摧毁所有的龙喉投石车。",p=464,r={{i=3339,n="矮人火绒",c=1}}},
  [466]={t="火岩矿石",d="我听说最近在湿地一带发现了一种特别稀有的矿石，大家管它叫火岩，那矿洞就在奥加兹大门西北方的一处洞穴里。火岩矿石非常不稳定，它很容易爆炸，但我敢说，如果加工方法正确的话，它就可以用来制作威力强大的炮弹！；给我搞一些火岩矿石的样本来，我可以去找个够胆的家伙来对它进行实验。；哦，要想采集到这些矿石的话，你可得懂点采矿技术才行。如果你完全不懂的话，那么……就找个懂行的朋友一起去吧！",o="给丹莫罗的驾驶员迪恩·石轮带回6份火岩矿石。",r={{i=3340,n="火岩矿石",c=6}},f=1},
  [471]={t="学徒的职责",d="我把我的学徒派到了沼泽那边去，希望他能给我搞到一些着名的巨型鳄鱼的皮回来。然而他一直都没回来，我只好亲自去找他……怎么说呢，反正我当时看到了一些比较惨的场面。；医生说他很快就会恢复健康的，但现在，我仍然急需鳄鱼皮！；……要是你能帮我杀几条这种凶猛残忍的大鳄鱼，从它们身上给我剥几张皮下来，我会非常高兴的。沿着海岸北上，走过了那些鱼人搭建的简陋小屋之后就能找到鳄鱼了。",o="为米奈希尔港的詹姆斯·哈洛兰带回6张巨型鳄鱼的皮。",p=484,r={{i=3348,n="巨型鳄鱼的皮",c=6}},w={{i=2545,n="柔软的链甲护腿",c=1},{i=3561,n="弹力雨布",c=1}},f=1},
  [474]={t="击败纳克罗什",d="现在所有的投石车都被烧掉了，找到纳克罗什酋长，把他干掉。",o="杀掉纳克罗什酋长。；将纳克罗什的徽记交给斯托菲队长。",p=465,r={{i=3625,n="纳克罗什的徽记",c=1}},w={{i=3209,n="上古长剑",c=1},{i=6194,n="削木短斧",c=1}},f=1},
  [478]={t="地图与符记",d="<你迅速从箱子里中拿起了坠饰并将箱子重新盖好。>",o="将这个奇怪的坠饰交给瑟伯切尔的暗影牧师奥利斯特。",p=477,r={{i=3353,n="刻有符文的坠饰",c=1}}},
  [479]={t="调查安伯米尔",d="达拉尔正在尝试着定位出达拉然法师们施法时的能量流向。现在，我们必须要尽我们一切努力来暂缓他们的进程……；那些咒术师、法师和保卫者恐怕会拼死保护坠饰。你必须清除掉这些阻碍，并把饰物抢到手。；沿着大路向南走，在岔路口转向东边就可以到安伯米尔了。",o="为瑟伯切尔的暗影牧师奥利斯特抢到8个达拉然坠饰。",p=482,r={{i=3354,n="达拉然坠饰",c=8}}},
  [480]={t="法师的头领",d="一位具有强大法力的大法师正在监管着启动节点的行动。在当前的形势下，我们只有杀死那个大法师才有可能阻止他们了。这将是个艰巨的任务，无疑会有许多法师与守卫层层护卫着他。；你必须出发了，尽快结果掉他。大法师死了以后，把他的法杖带回来给我。现在就去，快！",o="杀死达拉然大法师，并把他的法杖交给瑟伯切尔的暗影牧师奥利斯特。",p=479,r={{i=3515,n="阿塔瑞克之杖",c=1}},w={{i=3452,n="角枝魔棒",c=1},{i=3585,n="迷彩外套",c=1}},f=2},
  [481]={t="达拉尔的推理",d="把这个饰物交给达拉尔·道恩维沃尔，或许他能从中发现一些蛛丝马迹。",o="把刻有符文的坠饰交给瑟伯切尔的达拉尔·道恩维沃尔。",p=478,r={{i=3353,n="刻有符文的坠饰",c=1}}},
  [483]={t="唤醒圣物",d="瘤背部族的熊怪正在西边的班奈希尔兽穴里肆虐。；除非我们伸出援手，否则那些正在沉睡的德鲁伊将永久地陷于翡翠梦境中，对即将降临的噩运浑然不觉。只有拿到所有的唤醒圣物，我们才能将休眠仪式打断。；到兽穴里去帮我找回鸦爪神符、黑色羽毛、天蓝之石和筑巢符文。德鲁伊们把这些圣物藏在神圣的盒子里，把它们带给我，我要准备进行唤醒仪式。",o="找回四件唤醒圣物，把它们交给多兰纳尔的阿斯瑞达斯·熊皮。",p=476,r={{i=3405,n="鸦爪神符",c=1},{i=3406,n="黑色羽毛",c=1},{i=3407,n="天蓝之石",c=1},{i=3408,n="筑巢符文",c=1}},w={{i=9599,n="树皮护腿",c=1},{i=9603,n="粗砂法杖",c=1}},f=1},
  [484]={t="小鳄鱼皮",d="我是皮匠詹姆斯·哈洛兰。我用鳄鱼皮做东西的手艺可是艾泽拉斯第一流的，每天都有大船把我的产品一箱一箱地运到世界各地的港口去。；你见过埃纳尔了吧？他也是专门为我提供新鲜鳄鱼皮的诸多猎人之一。；最近我这里的小鳄鱼皮供应量在直线下降，鉴于当前我真的很缺货，如果你能帮我弄些小鳄鱼皮回来，我会给你开出一个非常不错的价码。你可以在镇外的沼泽里找到那种小鳄鱼。",o="为米奈希尔港口的詹姆斯·哈洛兰带回4张小鳄鱼皮。",r={{i=3397,n="小鳄鱼皮",c=4}}},
  [485]={t="找到OOX-09/HL！",d="你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。；“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于隐匿石那一带的河水源头附近！”",o="把定位器带到奥格索普的母体机器人那里去。；奥格索普的母体机器人位于辛特兰的河水源头，就在隐匿石的附近。",r={{i=8704,n="OOX-09/HL定位器",c=1}}},
  [486]={t="大槌乌萨尔",d="现在我们必须去解救猛禽德鲁伊了。如果我们现在失败了，他们就将永远迷失于睡梦中。；我将为苏醒仪式做好准备，不过为了进行这个仪式，就必须杀死造成现在这种混乱局面的罪魁祸首。只有到那时，仪式才能正常进行和完成。；大槌乌萨尔把一切都搞得一团糟，现在只有让它为此付出代价，猛禽德鲁伊才能重获自由。到西南边的脊骨堡去杀了它！",o="杀掉大槌乌萨尔，然后回到多兰纳尔的阿斯瑞达斯·熊皮那里。",p=483,w={{i=5459,n="防御者之斧",c=1},{i=5587,n="棘根木棒",c=1}},f=1},
  [488]={t="赛恩的要求",d="我知道你渴望工作，对你来说今天是个幸运的日子，因为我今天只能靠你这个乳臭未干的$c来帮忙了。；你知道，你，我可以使你非常幸福，我可以让你拥有你从未想过的好东西。但是首先，你必须给我带些东西来。；我在森林里的工作需要一些材料……给我拿来三颗夜刃豹的牙齿、三根巨翼枭的羽毛和三份树林蜘蛛丝。",o="给多兰纳尔外面的赛恩·腐蹄带去3颗夜刃豹的牙齿、3根巨翼枭的羽毛和3份树林蜘蛛丝。",r={{i=3409,n="夜刃豹的牙齿",c=3},{i=3411,n="巨翼枭的羽毛",c=3},{i=3412,n="树林蜘蛛丝",c=3}}},
  [491]={t="给比索的魔杖",d="图勒曾经告诉过我，很久以前，他和两名同僚利用各自手中的魔杖混合造出了一根新的魔杖。这根魔杖是友谊的象征。不过图勒虽然珍视他的友谊，但他却更珍视这件物品，并且不会允许自己与别人共同拥有这样一件宝物。所以他偷走了这支魔杖，将它藏在了芬里斯城堡。；就是这个。将这个魔杖送给比索·埃斯沙德，许多年前他曾是图勒的好朋友。我相信他会需要的。",o="将狼人魔杖带给幽暗城法师区的比索·埃斯沙德。",p=461,r={{i=3425,n="织纹魔杖",c=1}},w={{i=3457,n="践踏长裤",c=1},{i=3458,n="皱褶锁甲手套",c=1},{i=3581,n="锯齿小刀",c=1}},f=2},
  [496]={t="沉醉之药",d="唉，又在塔伦米尔度过了倒霉的一天。这里的新鲜空气让我浑身都不舒服，你。；要不是在这儿能很容易找到对付天灾军团的必要材料，我才不待在这鬼地方。朋友，请帮我早点结束这样的灰暗日子吧，尽快帮我收集到这些东西：10个灰熊的舌头，还有非常稀少罕见的食苔蛛的毒液。塔伦米尔周围到处都是熊和食苔蛛。",o="塔伦米尔的药剂师林度恩要你去收集10个灰熊的舌头和一些食苔蛛的毒液。",r={{i=3476,n="灰熊的舌头",c=10},{i=3477,n="食苔蛛的毒液",c=1}}},
  [498]={t="拯救行动",d="酋长派我和其它一些战士从敦霍尔德拿回一件东西，并调查这个所谓的辛迪加。；我们到敦霍尔德去转了一圈，很惊讶地在那里看到了很多人类。我们勇敢地和他们战斗，不过他们在人数上占有绝对的优势。我们当中有些同伴被俘虏了，不过我逃了出来。；敦霍尔德就在这里的东南部，过了河就是。德鲁尔和托格萨还被囚禁在那里，你得去把他们救回来。",o="塔伦米尔的克鲁斯克要你把德鲁尔和托格萨从敦霍尔德城堡救出来。",w={{i=3752,n="兽人步兵外衣",c=1},{i=3733,n="兽人作战链甲",c=1}},f=2},
  [500]={t="破碎岭食人魔",d="破碎岭食人魔在奥特兰克城废墟附近的山上挖了一座小丘。我的侦察兵告诉我，他们现在还占领了那片遗迹。；我们可不能让他们在那儿享福，一旦他们觉得在那儿生活很安全，下一步就会转移到丘陵地带，然后就是我们南海镇了！；到北方的奥特兰克山去猎杀几个食人魔。把他们那肮脏的指节骨带回来，我会给你奖赏的。",o="从奥特兰克山的破碎岭食人魔身上收集9个肮脏的指节骨，把它们带给南海镇的治安官雷德帕斯。",r={{i=2843,n="肮脏的指节骨",c=9}}},
  [501]={t="镇魂之药",d="哦，你……希尔斯布莱德的花都开了，空气这么清新，让我不得不沉湎在这种痛苦之中。我从肮脏的窗子里望出去，渴望着那一天早点到来，让我立即脱离这鸟语花香的痛苦环境。；我喜欢整天坐在这里思考，消灭天灾军团的使命正在召唤我，请你帮帮我吧。我的研究表明，暴烈的山地狮的血液能让天灾兵团失魂落魄，请给我找一点来，让我们做点有趣的事吧。",o="收集10瓶山地狮的血液，把它们交给塔伦米尔的药剂师林度恩。",r={{i=3496,n="山地狮的血液",c=10}},w={{i=2230,n="野猪手套",c=1},{i=3741,n="践踏战靴",c=1},{i=6482,n="踏火靴",c=1}},f=2},
  [503]={t="高迪尔",d="从你拿到的文件来看，高迪尔被关在北边的一个辛迪加基地里，很有可能就在奥特兰克山。他已经被关押太久了，你必须尽快把他救出来。",o="救出高迪尔，然后回到塔伦米尔去见克鲁斯克。",p=533,r={{i=3704,n="锈铁钥匙",c=1}}},
  [504]={t="破碎岭好战者",d="你已经和破碎岭食人魔打过交道了，现在我要你去好好教训教训他们……；到奥特兰克遗迹去猎杀那些破碎岭好战者。我希望你多干掉一些——只有这样才能让这帮畜生离联盟的领土远一点。",o="杀死10个破碎岭好战者，然后回南海镇向治安官雷德帕斯报告。",p=500,w={{i=5249,n="燃火魔杖",c=1},{i=3763,n="圆月盾",c=1}},f=1},
  [505]={t="辛迪加刺客",d="我是南海镇的新镇长，前一任镇长被刺杀之后，我刚刚上任。那些刺客一直都没有找到，不过据我们调查，几乎可以肯定他们是由辛迪加雇佣的——辛迪加是一个由邪恶的贵族掌管着的盗贼组织，而那些贵族则是已经陷落的奥特兰克王国的遗老遗少。；根据我们最新的消息，辛迪加在由部落占据的小镇塔伦米尔的北方设有好几座营地，到那儿去杀掉那里的辛迪加成员。",o="杀死12个辛迪加劫匪和8个辛迪加盗贼，然后回到南海镇向赫尼·马雷布镇长报到。",w={{i=3758,n="十字军腰带",c=1},{i=3759,n="隐居先知手套",c=1}},f=1},
  [507]={t="奥里登·匹瑞诺德",d="匹瑞诺德一定要被除掉，这个卑鄙的家伙绝不能继续在这世上逍遥了。他的领地就在北边的洛丹米尔湖岸上。去完成这个任务，$n，别忘了把酋长想要的项链也拿到手，然后再回到这里来。",o="杀了奥里登·匹瑞诺德领主，并从他的情人艾丽萨身上拿回塔蕾莎的项链。",p=506},
  [508]={t="塔蕾莎的礼物",d="项链吗？当然可以给你……拿走它吧！我不想再跟他有什么瓜葛了……求求你，别杀我……",o="把塔蕾莎的项链交还给希尔斯布莱德丘陵中塔伦米尔的克鲁斯克。",p=507,r={{i=3498,n="塔蕾莎的项链",c=1}},w={{i=3764,n="螳螂之靴",c=1},{i=3765,n="掠夺者肩铠",c=1}},f=2},
  [509]={t="破除天灾",d="又是新的一天，又有一种新的药剂要配制。要我说，我宁愿让那些可怜的家伙去和天灾军团互相拼命，反正他们就喜欢互相残杀。；既然黑暗女王要加速这个过程，不如在这段恐怖的日子里再给这片土地加点料怎么样？；我有个计划，你，你现在到奈杉德哨岗去，那地方在塔伦米尔的南边，南海镇的东边。给我找6朵泥头花来让我配制药剂。",o="收集6朵泥头花，把它们交给塔伦米尔的药剂师林度恩。",r={{i=3502,n="泥头花",c=6}}},
  [510]={t="预备行动计划",d="这些文件当中有一份物资清单，清单里包括各种日常物品（食物、武器、衣服）和其它工具（面具、油、毒药）。；不过其中提到最重要的就是：尽高速缓冲得清单中的物资，为文件里所说的“针对南海镇的重要使命”进行准备。",o="把预备行动计划带给南海镇的赫尼·马雷布镇长。",r={{i=3718,n="预备行动计划",c=1}}},
  [511]={t="密文信件",d="桌上有一封用密文写成的信，你根本没法读懂。",o="把密码信交给南海镇的博学者迪布斯。",r={{i=3521,n="复杂的密码信",c=1}}},
  [513]={t="破除天灾",d="就在我觉得这一天又要无趣地打发掉的时候，你给我带来了这些泥头花。；等我把它们混合在一起。我们还需要幽暗城的大药剂师法拉尼尔给药剂里加上他的腐蚀胶体，然后就等着看好戏吧！；把这个泥头花药拿去交给大药剂师法拉尼尔，你，现在就去。",o="把泥头花药交给幽暗城的大药剂师法拉尼尔。",p=509,r={{i=3506,n="泥头花药",c=1}}},
  [514]={t="铁炉堡的译码者",d="我在铁炉堡有个同僚也许可以帮忙破译这封信。到铁炉堡的探险者联盟去找勘察员塔伯斯·雷矛谈一谈，告诉他是我让你去的，把这封信给他看。黑石塔以北如果还有人能读懂这封信的话，那一定就是他了。",o="把密码信带给铁炉堡的勘察员塔伯斯·雷矛。",p=511,r={{i=3521,n="复杂的密码信",c=1}}},
  [515]={t="破除天灾",d="泥头花药？太棒了！我怎么就没想到过这个呢？；让我给这种药剂里面加入我研制的性能胶体。；如果要激活泥头花水里的活力成分，林度恩就得先弄到强力巨魔之血药水，还有南海岸的刺脊纳迦的鳞片和碎鳍鱼人的眼球。你去找到这些试剂，林度恩会知道怎么处理它们的。天哪，我真想早点知道他的实验进行得怎么样了！",o="把泥头花水、1瓶强力巨魔之血药水、5块刺脊纳迦的鳞片和5颗碎鳍鱼人的眼球交给塔伦米尔的药剂师林度恩。",p=513,r={{i=3508,n="泥头花水",c=1},{i=3388,n="强力巨魔之血药剂",c=1},{i=3509,n="刺脊纳迦的鳞片",c=5},{i=3510,n="碎鳍鱼人的眼球",c=5}},w={{i=3749,n="高阶药剂师披风",c=1},{i=3747,n="冥想腰带",c=1}},f=2},
  [516]={t="博伦的巢穴",d="我收到报告说，一群天灾军团的亡灵正在附近集结，准备对我们进行一次袭击。既然得到了这样的情报，我们就本应该先下手攻击他们，把他们的计划粉碎在襁褓中才对。；但不幸的是，我的情报十分有限，只知道他们在一个名为博伦的巢穴的山洞里集结。确切的位置我也不清楚，但应该在安伯米尔附近的山区中。；我相信以你的能力和才智，一定可以找到他们，干掉他们。",o="找到博伦的巢穴，杀死6名鸦爪苦工和6名鸦爪守护者，然后向瑟伯切尔的暗影牧师奥利斯特汇报。",f=2},
  [517]={t="破除天灾",d="新药剂终于进入了实验阶段，不过呆在阴冷的屋子里这么多天，我的脑筋都快打结了，让我们以“破除天灾”之名找点乐子吧。；到丹加洛克去，你知道，就是到那些肮脏的小矮人出没的军营里去，给我偷一桶矿工烈酒出来，有了它，你我就可以畅饮美酒狂欢了，你。",o="将一桶矿工烈酒交给塔伦米尔的药剂师林度恩。",p=515,r={{i=3517,n="矿工烈酒",c=1}}},
  [518]={t="意志之冠",d="玛格索尔和他的破碎岭食人魔在奥特兰克废墟已经泛滥成灾了。不减少食人魔的数量的话，我们就很难去对付玛格索尔。；等他们的实力被削弱以后，我们就能继续前进了。；懂了吗？好的。去吧。",o="塔伦米尔的梅里萨拉要你去杀掉10个破碎岭虐待者。"},
  [519]={t="意志之冠",d="塔尔格、玛克拉克和戈洛姆斯都是玛格索尔的下属。我们不知道食人魔的忠心来源于什么，不过他们对玛格索尔可是死心塌地。；把他们的徽记给我带回来，$n，接下来就是干掉玛格索尔，彻底瓦解那些食人魔。",o="干掉塔尔格、玛克拉克和戈洛姆斯，把他们的徽记带给塔伦米尔的梅里萨拉。",p=518,r={{i=3550,n="塔尔格的徽记",c=1},{i=3551,n="玛克拉克的徽记",c=1},{i=3552,n="戈洛姆斯的徽记",c=1}}},
  [520]={t="意志之冠",d="玛格索尔的下属都死了，剩下的就是杀掉玛格索尔，取回意志之冠。他当然不想失去那顶王冠，所以我想你最好……首先将他周围的障碍都干掉。；找到玛格索尔，把他的徽记和王冠一起带回来。破碎岭的抵抗就到此为止了。",o="杀了玛格索尔，带着他的徽记和意志之冠去塔伦米尔见梅里萨拉。",p=519,r={{i=3553,n="玛格索尔的徽记",c=1},{i=3554,n="意志之冠",c=1}}},
  [521]={t="意志之冠",d="剩下的任务就是把意志之冠交给幽暗城的沙琳德拉。她会派人送去给希尔瓦娜斯大人。我得警告你，别想把它留着自己用，玛格索尔的死就是最好的例子。",o="把意志之冠交给幽暗城的沙琳德拉。",p=520,r={{i=3554,n="意志之冠",c=1}},f=2},
  [522]={t="刺客的契约",d="这是一份刺杀赫尼·马雷布镇长的契约。合约已经封好，并用一个特殊的徽记之戒在红蜡上做了标记。",o="把刺客的契约带给南海镇的赫尼·马雷布镇长。",r={{i=3668,n="刺客的契约",c=1}}},
  [525]={t="更大的谜团",d="我已经译出了这封信，不过还是不知道它是什么意思。你是在奥特兰克丘陵的盗贼身上找到这封信的吗？真奇怪……；你应该把它拿去给南海镇的镇长看看。虽然这封信的含义不甚明了，但是南海镇离奥特兰克最近，如果有什么威胁正在临近的话，我想应该先告诉他。",o="把被破译的信件交给南海镇的赫尼·马雷布镇长。",p=514,r={{i=3518,n="被破译的信件",c=1}}},
  [527]={t="希尔斯布莱德之战",d="和我说话的时候要立正，$c。；我受瓦里玛萨斯的直接领导。在我们的药剂师研制出新型瘟疫之前，我们必须要压制住人类的攻势。；有消息表明，希尔斯布莱德镇是个防守很薄弱的小镇。你的第一个任务是扰乱敌人的食品供给和基础设施建设。；从这里往西边方向进发，你的目标是希尔斯布莱德平原最北边的农场，在那里大开杀戒的同时，别忘了把当地的农场主——农夫雷恩和农夫盖兹也给干掉。",o="杀掉6个希尔斯布莱德雇农和6个希尔斯布莱德农夫，还有农夫雷恩和农夫盖兹，然后返回塔伦米尔向达萨利亚报告。"},
  [528]={t="希尔斯布莱德之战",d="北方农场被袭击的消息让人类的村民们惊慌失措，你干得很出色。；我们的哨兵报告说有农民向希尔斯布莱德南部逃散——这些傻瓜以为他们可以藏在果园里逃过一死。；去结果他们吧，你。回到希尔斯布莱德农场去，把这些东躲西藏的农民找出来，以黑暗女王的名义杀了他们。；解散！",o="杀死15个希尔斯布莱德农民，然后回到塔伦米尔向达萨利亚汇报。",p=527},
  [529]={t="希尔斯布莱德之战",d="希尔斯布莱德的人类进行了顽强的抵抗，这实在有点出乎我的意料。问题的关键在于，有几个铁匠在为那些镇民提供武器，我们得切断他们的所有供给线。；你的任务是干掉铁匠维林坦，还有他的那些学徒也得杀了。还有，把他们库存的铁也给抢回来。等我们征服了希尔斯布莱德并开始准备进攻南海镇的时候，这些物资就显得非常重要了。",o="杀掉铁匠维林坦和4个希尔斯布莱德见习铁匠，并从那里抢回一箱铁材，然后向塔伦米尔的达萨利亚汇报。",p=528,r={{i=3564,n="一箱铁材",c=1}}},
  [530]={t="丈夫的复仇",d="瓦德雷曾经是我的好朋友，但他也是杀害我妻子的凶手。虽然我已经不知道悲伤为何物了，但我复仇的念头却一直没有改变。去帮我杀了瓦德雷，把他那双邪恶的手带给我，我会奖赏你的。；我最后一次听到他的消息时，他正准备从银松森林南部的格雷迈恩之墙逃往吉尔尼斯王国。",o="杀掉瓦德雷·莫莱。；把他的双手带给幽暗城的拉林夫·安迪恩。",p=441,r={{i=3613,n="瓦德雷的手掌",c=1}},f=2},
  [532]={t="希尔斯布莱德之战",d="希尔斯布莱德镇现在一片混乱，我们相信它很快就要被攻陷了。但是，我们必须继续坚持对敌人不断地发动攻击，直到把所有的人类渣滓都完全从这里赶出去为止。；虽然人类损失惨重，但他们仍然团结在领袖的周围继续抵抗。我们得除掉他们的首领波恩塞德镇长，当然还有镇议会的成员。最后别忘了毁掉他们的政治文件《希尔斯布莱德宣言》，顺便把镇里的文档也都偷过来。",o="杀掉波恩塞德镇长和4个希尔斯布莱德议员，摧毁《希尔斯布莱德宣言》，偷取希尔斯布莱德城镇文档，然后回到塔伦米尔向达萨利亚汇报。",p=529,r={{i=3657,n="希尔斯布莱德城镇文档",c=1}}},
  [533]={t="秘密潜入",d="我们终于得到了关于高迪尔的线索。人类不停地到处转移他，但是我们已经缩小了搜索范围，现在我们的注意力主要集中在北边的那个辛迪加营地里。；到那儿去打探一下，然后回来向我报告。",o="把关于高迪尔下落的消息带回来给塔伦米尔的克鲁斯克。",p=498,r={{i=3601,n="辛迪加信件",c=1}}},
  [536]={t="清理海岸",d="我从暴风城守卫被调到这个鸟不生蛋的南海镇来做守卫，这镇子简直是一无是处……整日整夜都是一股鱼腥味。；更别提治安官雷德帕斯了……他还想要我去对付那帮鱼人，哈！；我很难打起精神去跟西部海岸上的那群奇形怪状的鱼人作战。如果你愿意替我去干掉它们，我会很感激你的。",o="南海镇的法尔林·奥里涅尔中尉要你去杀掉10个碎鳍潮行鱼人和10个碎鳍智者。"},
  [539]={t="希尔斯布莱德之战",d="希尔斯布莱德城镇文档里的记录表明，碧玉矿洞已经处于联盟的控制之下——这个矿洞是联盟兵工厂运转所需的铁矿石的主要来源。；虽然我们已经对希尔斯布莱德镇进行了致命的打击，但是联盟还是积极地支持和保护着碧玉矿洞。；这个矿洞就在希尔斯布莱德的正南方。到那里去杀了他们的工头，一个名叫邦德斯的人类，顺便把那里的矿工也干掉。这样的行动可以给联盟传达一个足够清楚的讯息。",o="杀死工头邦德斯和10个希尔斯布莱德矿工，然后回到塔伦米尔向达萨利亚汇报。",p=532},
  [540]={t="保全书籍",d="那些野蛮的食人魔现在就驻扎在奥特兰克废墟，一想起他们会把那里的书籍怎么样，我就感到毛骨悚然。你一定要尽力去完成我给你的任务！；进入奥特兰克废墟，找到食人魔夺走的书籍。把你找到的所有东西都带给我，特别是这本书：《格里雷克之臂》。这本书里写着巨魔的古老学说，我一定要学。奥特兰克是完整保存这本书的唯一地方。",o="把5本失而复得的书籍和包含《格里雷克之臂》的破旧的皮书带给南海镇的博学者迪布斯。",p=538,r={{i=3658,n="失而复得的书籍",c=5},{i=3659,n="破旧的皮书",c=1}}},
  [541]={t="希尔斯布莱德之战",d="矮人正在协助人类？这帮肮脏的小东西。；我们得看看这所谓的联盟的实力到底如何。等这些矮子知道我们的厉害之后，看他们还愿不愿意继续给人类卖命！；我们知道这些矮人的据点在哪里，他们在希尔斯布莱德东南部沿着索拉丁之墙的地方创建了一个被称作丹加洛克的军营。你的最终目标是攻占丹加洛克，$c。他们的首领达伦·铁山上尉必须得死。",o="到丹加洛克去杀掉8个巡山人、4个火枪手、2个牧师，还有达伦·铁山上尉，然后回到塔伦米尔向达萨利亚汇报。",p=539},
  [544]={t="誓死追赃",d="我本来是到塔伦米尔来做研究的，不过现在我手头上有个麻烦一定要尽快解决掉。你知道，几个月前曾有四个被遗忘者从幽暗城逃了出来。他们抛弃了自己的同伴，这没什么，但问题是……他们偷了黑暗女王的东西。；这些小偷闯入了一间秘密的地窖，偷走了四件供药剂师研究用的神器。黑暗女王命令我们把这四件神器找回来。；小偷从幽暗城逃到了达拉然，而那些巫师则把他们收留在洛丹米尔收容所里。",o="找到被遗忘者的叛徒，取回他们偷走的神器，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。",r={{i=3691,n="血石之楔",c=1},{i=3689,n="血石弹球",c=1},{i=3690,n="血石碎片",c=1},{i=3688,n="血石卵石",c=1}}},
  [546]={t="死亡的纪念品",d="听说达萨利亚让你和希尔斯布莱德的人类作战，我很嫉妒你……；你在外面享受屠杀人类、掠夺城镇、恐吓无辜者的快乐，而我却像木头一样待在塔伦米尔做守卫。；你能可怜可怜像我这样的老亡灵卫兵吗？你知道我在收集人类的徽记，正好你还要和人类战斗一段时间。那么，能不能在你作战的这段时间里顺便给我收集30个徽记来？我会让你的努力物有所值的。",o="塔伦米尔的亡灵卫兵沙穆萨想要30个希尔斯布莱德人类徽记。",p=527,r={{i=3692,n="希尔斯布莱德人类徽记",c=30}},f=2},
  [547]={t="亨伯特的长剑",d="高级执行官达萨利亚派我从远处监视丹加洛克。我在一个隐蔽的角落里扎了营，但是那天早上我在烧水的时候离开了一会儿去找柴火……；等我回来时，发现放在营地里的装备已经不见了。；一定是那些丹加洛克的矮人侦察兵从这儿经过的时候把东西拿走了。我必须得拿回我的剑！如果你能帮我拿回来的话，我会很感激你的。但是那儿的矮人真是太多了……也许你很难在他们当中找出那个小偷。",o="从丹加洛克拿回亡灵卫兵亨伯特的长剑，然后回到塔伦米尔把剑还给他。",r={{i=3693,n="亨伯特的长剑",c=1}},w={{i=3750,n="骨纹胸甲",c=1},{i=3751,n="佣兵护腿",c=1}},f=2},
  [549]={t="通缉：辛迪加成员",d="经由黑暗女王希尔瓦娜斯授权，辛迪加组织的全部成员都将被处死！那些已经被羁押和俘虏的辛迪加成员必须立刻处决。残馀的辛迪加成员当前在塔伦米尔东南部的敦霍尔德城堡废墟聚集。；任何向高级执行官达萨利亚证明自己完成了这个任务的人都会受到重赏。",o="杀死10个辛迪加盗贼和10个辛迪加哨兵，然后回到塔伦米尔向高级执行官达萨利亚报告。",f=2},
  [550]={t="希尔斯布莱德之战",d="由于你在希尔斯布莱德战役中的英勇表现，我已经向上级写了这封褒奖状以表扬你。；把这密封的奖状带给幽暗城的布拉贡·血拳，你可以满怀骄傲地去见他，$c。",o="把达萨利亚的奖状交给幽暗城的布拉贡·血拳。",p=541,r={{i=3701,n="达萨利亚的奖状",c=1}},w={{i=6282,n="神圣的葬礼长裤",c=1},{i=3761,n="骷髅之盾",c=1},{i=3822,n="黑暗符文剑",c=1}},f=2},
  [551]={t="附有魔法的羊皮纸",d="这张羊皮纸上被施加了某种咒语，使其无法被破译。但是，卷首的一个词却很容易辨认：；； 纳伽兹；",o="将这张附有魔法的羊皮纸带给希尔斯布莱德丘陵中南海镇的博学者迪布斯。",r={{i=3706,n="附有魔法的羊皮纸",c=1}}},
  [552]={t="赫尔库拉的复仇",d="正在赫尔库拉大人即将完成他的巫妖仪式的紧要关头，一群人类暴徒发现了他在山上进行仪式的位置，把他残忍地杀害了。更糟的是，他们把他的遗骨埋在了南海镇的墓地里。；这种不尊重伟大的巫师的行径绝对是无法让人接受的。作为他的学徒，我一定要让复仇降临在南海镇。；首先我们得找到赫尔库拉的魔棒，前不久，一群雪怪侵袭了赫尔库拉的巢穴。毫无疑问是他们当中的一个拿走了赫尔库拉的魔棒。",o="从雪怪手上拿回赫尔库拉的魔棒，把它交给塔伦米尔的学徒塞万德。",r={{i=3708,n="赫尔库拉的魔棒",c=1}}},
  [556]={t="石雕",d="达拉然巫师的一项举世闻名的能力就是他们可以操纵如元素生物这样的从其它空间来的强大生物，他们使用魔法石雕作为控制这些元素生物的工具，现在大法师伍德格莱尔想找些石雕来研究。；进入达拉然巫师的领地，去给我找些用旧的石雕回来。；你可以在任何一个达拉然市民的身上找到这种石雕，不过我建议你还是去收容所一带找找，那里可比达拉然安全多了。",o="收集10个用旧的石雕，把它们带给塔伦米尔的看守者贝尔杜加。",r={{i=3714,n="用旧的石雕",c=10}}},
  [559]={t="法尔林的证据",d="你相信吗，$n？雷德帕斯对咱们杀了那么多鱼人还是不满意——哦，别谦虚了，你在这方面还挺有本事。现在他又要我证明我真的杀过鱼人，他要我把那些冰凉的、粘糊糊的鱼人徽记带去让他过目，这样我才能得到他的肯定。",o="南海镇的法尔林·奥里涅尔中尉要你从西部海岸的鱼人身上收集10颗鱼人的徽记。",p=536,r={{i=3716,n="鱼人的徽记",c=10}}},
  [560]={t="法尔林的证据",d="你知道，$n，我真的不想碰这些鱼人的徽记……既然是你解决了它们，那你能不能再帮我把它们送去给雷德帕斯？",o="把一袋鱼人的徽记交给南海镇的治安官雷德帕斯。",p=559,r={{i=3717,n="一袋鱼人的徽记",c=1}}},
  [562]={t="升官之道",d="我以前在暴风城的导师发来消息告诉我联盟的高级将领已经开始关注纳迦带来的威胁了。根据他打听来的消息，任何人在这方面有所表现的话，都很有可能得到提拔，或者至少是调动工作岗位。；不过有一个小问题……我对付不了纳迦，$n。哦，当然，我能阻止酒吧里的醉汉互相争吵，也能拖走好斗的乞丐，不过纳迦对我来说就太难对付了。你一定得帮我这个忙，$n。",o="南海镇的法尔林·奥里涅尔中尉要你去杀掉10个刺脊滩行者和10个刺脊海妖。",p=561,f=1},
  [564]={t="损失惨重",d="没有什么事比失去这些骏马更让我烦心了。相信我，就是那些讨厌的亡灵、可恶的辛迪加恶匪和其它害人的东西在这一带到处游逛，杀了我们不少的马匹。；不过我可以对着我爷爷的墓碑发誓，对这些马匹威胁最大的还是奥特兰克上的山地狮。它们总是从山上跑下来给我捣乱！；你觉得自己是个英雄？那就去做点什么来证明吧！",o="南海镇的达伦·玛尔维要你杀掉8只山地狮和10只巨型山地狮。",w={{i=3753,n="牧羊人束带",c=1},{i=3754,n="牧羊人手套",c=1}},f=1},
  [565]={t="巴图罗的雪人毛皮披风",d="我，伟大的巴图罗，将为你做一件闻名世界、全联盟皆知的雪人毛皮披风！；不信你就到处跑跑看，能不能再找件更棒的。每个人都会说：“巴图罗，没有比这更好的披风了！”当然，当然没有。；巴图罗需要一个毛布卷，一件由技艺高超的制皮匠缝制的山地披风，一股细线，当然还要有雪人的毛皮！把这些东西带给我，我就让你看看我的本事！",o="给南海镇的巴图罗·吉塞提找一个毛布卷、一件山地披风、一股细线和10块雪人的毛皮。",r={{i=2997,n="毛布卷",c=1},{i=2321,n="细线",c=1},{i=3719,n="山地披风",c=1},{i=3720,n="雪人的毛皮",c=10}},f=1},
  [566]={t="通缉：瓦杜斯男爵",d="高级执行官达萨利亚发出命令，通缉名叫瓦杜斯男爵的人类，此人对被遗忘者犯下了重罪。瓦杜斯是辛迪加组织的高级人物。；最后一次有人见到他是在塔伦米尔北部的奥特兰克山高地上。；杀死他，然后带着他的徽记去见高级执行官达萨利亚换取报酬。",o="杀了瓦杜斯男爵，把他的徽记带给塔伦米尔的高级执行官达萨利亚。",r={{i=3626,n="瓦杜斯男爵的徽记",c=1}},f=2},
  [567]={t="危险！",d="危险！；以下这个希尔斯布莱德人是危险人物，已被高级执行官达萨利亚悬赏捉拿：；通缉犯书记员赫拉斯·怀特斯蒂德杀害了亡灵卫兵托马。；通缉犯平民维尔克斯杀害了药剂师埃利。；通缉犯矿工哈克特杀害了亡灵卫兵弗雷。；通缉犯农夫卡拉巴伏击运往幽暗城的物资。；这些敌人都躲藏起来了，很难找到，杀掉他们有重赏。",o="塔伦米尔的高级执行官达萨利亚悬赏通缉书记员赫拉斯·怀特斯蒂德、平民维尔克斯、矿工哈克特和农夫卡拉巴。",w={{i=3742,n="劫掠之弓",c=1},{i=3743,n="哨兵圆盾",c=1},{i=5250,n="焦木魔杖",c=1}},f=2},
  [568]={t="格罗姆高保卫战",d="向你致敬，$c！；你来得真是时候。身为酋长委派到这个丛林基地中的指挥官，我肩负着保卫所有部落成员安全的光荣使命，我们在此的任务是保证对斯通纳德的供应线不被此地的怪物所侵扰。；因此，我将委任你来负责减轻格罗姆高附近的迅猛龙给我们带来的威胁。当你取得了显着的进展后，就向我复命吧。",o="格罗姆高营地的指挥官阿格罗戈什要求你杀死15只鞭尾迅猛龙。"},
  [569]={t="格罗姆高保卫战",d="在第一次进入这片丛林中的时候，我们根本就没想和当地的土着部落发生任何冲突。我们任务中最重要的部分就是保持对斯通纳德的供应线的畅通。但当前的情况很复杂，附近的一群食人魔占领了格罗姆高东南方的米扎废墟。他们从来就没把我们的警告放在眼里，频繁地伏击我们的补给车队。；我授命你去解决掉这群冥顽不化的食人魔。；到米扎遗迹去吧，就算不能把他们驱逐出这片地区，至少也得让他们好好尝尝苦头。",o="格罗姆高营地的指挥官阿格罗戈什要求你杀死10个食人魔蛮兵和5个食人魔巫医。",p=568,f=2},
  [570]={t="摩克萨尔丁的魔法",d="部落必须意识到丛林中蕴含着的无尽的魔法力量，并尽快学会利用它来为自己服务。到当前为止，我的仪式都是很成功的，现在我已经能够施放很强大的魔法了。勇敢的$c，我决定为你制作一件特殊的魔法物品。；给我找一些深喉猎豹的爪子和一颗雌虎的牙齿来，不过你要注意，并不是任何牙都可以用的。你必须找到品质最纯正的牙齿才行。；这种野兽一般都潜藏在丛林中，但你在附近也能找到，只要从米扎废墟那边渡过河流，然后向东南方走就行了。",o="格罗姆高营地的先知摩克萨尔丁要求你给他带回8只深喉猎豹的爪子和一颗雌虎的牙齿。",r={{i=3838,n="深喉猎豹的爪子",c=8},{i=3839,n="雌虎的牙齿",c=1}}},
  [571]={t="摩克萨尔丁的魔法",d="现在我要你去寻找一件非常难以得到的物品。；为了将这些羽毛、爪子和牙齿中的魔法力量连接在一起，我必须要创建一个魔法阵，而这魔法阵只有用成年猩猩的肌腱才能做成。；具体说来，老迈的薄雾谷猩猩身上的肌腱就很合适。他们一般栖息在藏宝海湾的东面。；你必须找到足够新鲜健康的肌腱才行，这就是说，你有可能要杀死很多大猩猩才能找出一条合我心意的肌腱来rn。",o="给格罗姆高营地的先知摩克萨尔丁带回1根成年大猩猩的肌腱。",p=572,r={{i=3862,n="成年大猩猩的肌腱",c=1}}},
  [572]={t="摩克萨尔丁的魔法",d="你刚才从那些野兽身上收集到的这些材料只是制造那件强力魔法物品的第一步。在我使用萨满仪式将这些物品合成之后，你就会得到一件极为有用的工具，它可以帮你更好地为酋长和部落效力。；但你先得帮我收集一些丛林捕猎者的羽毛来，据说迅猛龙将这些羽毛当作它们的臂章。在格罗姆高的南边，离大竞技场不远的地方就有一个迅猛龙部族，你可以到那里去看看。",o="给格罗姆高营地的先知摩克萨尔丁带回10根丛林捕猎者的羽毛。",p=570,r={{i=3863,n="丛林捕猎者的羽毛",c=10}}},
  [573]={t="摩克萨尔丁的魔法",d="现在我们只差最后一种材料就可以完成这个魔法了。；向南走到一处面对西侧海岸的高崖之上，你会发现一处圣泉。这处圣泉是许多学者争论的焦点，艾泽拉斯上的所有种族都认为这泉中的水乃是神为他们的子民所创造的。；给我带一瓶圣泉的水回来，这是我给你的最后一个任务啦。不过，你得小心点。有一群纳迦卫兵正守在圣泉的附近，你得先对付他们才能取到泉水。",o="格罗姆高营地的先知摩克萨尔丁要你去取回一瓶圣泉之水，同时还要求你杀死10名纳迦探险者。",p=571,r={{i=737,n="圣泉之水",c=1}},f=2},
  [574]={t="特种部队",d="如今我们已经在很大程度上削弱了他的正规部队，但这就意味着你得直接去面对他手下的精锐部队。如果那些家伙没有被派出去袭击我们落单的士兵的话，他们就应该驻扎在库尔森营地后山上一处名为“储藏室”的洞穴里。；我私下里认识许多库尔森的手下，他们都是身经百战的老兵，对库尔森忠心耿耿，而且最要命的是，他们对敌人毫不手软。这对你来说恐怕不是个简单的任务，你。多加小心。；你战胜了他们以后，就去向我的长官多伦上尉复命吧。",o="杀掉10名库尔森特种兵和6名库尔森精神医师。；然后向反抗军营地的多伦上尉复命。"},
  [575]={t="供与求",d="“前无古人，后无来者，南海一带最好的也是世界最好的皮匠。”他们就是这么叫我的。我！崔斯里克！最好的皮……呃，好吧。；我的皮货以质量优质而远近闻名，都是鉴赏家们的首选之物！；我最近收到了来自工匠行会的雷德沃克斯主管的订单，他需要十二双刨花皮靴。啊，就是那种由我制作的、非常抢手的靴子。；不过要想做那种靴子的话，我需要一些鳄鱼皮才行。在荆棘谷北边的河边有很多鳄鱼，你看能不能……",o="收集2张淡水鳄的皮，把它们交给藏宝海湾的崔斯里克。",r={{i=4053,n="淡水鳄的皮",c=2}}},
  [576]={t="海盗的眼睛",d="站住！谁在那边？；啊，如果没有那只特制的魔法眼，我就是个废人了。当初在一次战斗中，我失去了我的眼睛！但幸运的是，我们的船停靠在米奈希尔港时，一位旅行法师送给了我一只特制的玻璃眼，这样我才又能看见东西了。；不过昨天晚上我参加了袭击血帆海盗的行动，在跳出船的时候玻璃眼睛不小心给弄丢了。一定是那帮血帆海盗拿走了我的眼睛！看来他们这群混蛋已经找到了到藏宝海湾来的路。；你能不能帮帮我这个老海盗，把我的眼睛给找回来？",o="藏宝海湾的独眼迪兹要求你从血帆海盗那里找回他的眼睛。",p=595,r={{i=3897,n="迪兹的眼睛",c=1}}},
  [577]={t="收集鳄鱼皮",d="嗯，这些靴子已经基本定型，接下来就要开始打磨表面了。但你带来的皮似乎少了点，做不出足够的鞋垫来。；“那现在我们得干什么呢，崔斯里克？”你肯定会马上问这种问题，哈哈，你跟崔斯里克说话可真不幸啊，因为我马上就要给你派活干啦！；没人会去观察鞋垫的，所以我们只要找点又厚又便宜的鳄鱼皮就行了。纳菲瑞提湖旁边的那种钳嘴鳄鱼就不错。",o="给藏宝海湾的崔斯里克带回5张钳嘴鳄鱼的皮。",p=575,r={{i=4104,n="钳嘴鳄鱼的皮",c=5}}},
  [578]={t="海潮之石",d="如果个岛上确实有水元素和地精法师的鬼魂的话，也就是意味着在那里可以采到海潮之石！；我希望你能找到这座闹鬼的岛屿，去看看上面到底是怎么回事。哦，如果你想知道更多的有关海潮之石的信息的话，可以带着这张凭证去暴风城图书馆，他们会帮你找到我最初读过的那本传说的手抄本。；真的是加兹班首先发现那种石头的吗……?",o="为藏宝海湾的大财主里维加兹找到闹鬼的岛屿。",p=616},
  [581]={t="耶尼库的下落",d="厄运！厄运降临在我们酋长的小儿子耶尼库身上……按照部族里的习俗，他被过继给了祖尔格拉布的巨魔，但我们暗矛部族随后便决定跟随兽人酋长萨尔离开家乡，可怜的耶尼库就此与我们失去了联系。我是从奥格瑞玛回到荆棘谷来的，我回来寻找我们酋长的孩子。；我相信是血顶部族抓住了他。；如果你愿意帮助我的话，就去干掉血顶部族的那帮家伙吧，他们就在北边。把他们的獠牙给我带来。",o="给格罗姆高营地的尼姆布亚带回9根血顶巨魔的獠牙。",r={{i=3901,n="血顶巨魔的獠牙",c=9}}},
  [582]={t="狩猎行动",d="我们必须弄清楚耶尼库是否还活着。；杀掉一些血顶部落的猎头者，并把他们身上挂着的皱缩的徽记给我取回来。你必须要收集尽可能多的首级回来，这样我才能检查一下耶尼库的头在不在其中。；如果耶尼库真的被血顶氏族给杀了，他们的酋长，那个名叫甘祖拉恩的家伙，就一定会遭受长达600年的恶毒诅咒！；去吧，你。沿海岸北上，在祖丹亚废墟和祖昆达废墟那里就有很多血顶猎头者在活动。",o="给格罗姆高营地的尼姆布亚带去20个皱缩的徽记。",p=581,r={{i=1532,n="皱缩的徽记",c=20}},w={{i=4133,n="暗矛腕轮",c=1},{i=4132,n="暗矛护臂",c=1}},f=2},
  [584]={t="血顶徽记",d="感谢蛇神，耶尼库的徽记并不在当中。但我们仍不清楚他的状况……；我们必须知道真相，不过，恐怕只有血顶氏族的酋长和巫医才知道这些事，而他们又是我们暗矛部族的敌人，所以他们是绝对不会老老实实地告诉我们真相的，恐怕他们只有在死了以后才会愿意和我们谈谈！；把甘祖拉恩和奈兹里奥克的徽记给我带回来，然后放进这个锅里去。；他们就躲在祖昆达废墟里的深处。只要有他们的徽记……我们就能和他们好好谈谈了。",o="将甘祖拉恩的徽记和奈兹里奥克的徽记带回格罗姆高营地，放入冒泡的大锅中。",p=582,r={{i=3904,n="甘祖拉恩的徽记",c=1},{i=3905,n="奈兹里奥克的徽记",c=1}}},
  [589]={t="歌唱水晶",d="传说荆棘谷的中心地带深藏着一块宝石，这块宝石的名字叫心灵之眼，其中蕴涵着巨大的力量。如果你得到了这块宝石，也许我们就能用它将失落于黑暗之中的耶尼库拯救出来。；我会与丛林之灵们商谈，向他们询问心灵之眼的位置。与此同时，你要去一趟东南方的水晶矿洞，从那里的铁腭蜥蜴身上收集一些蓝色波光碎片。这些水晶非常稀有，但我们需要利用其中的魔法能量来控制心灵之眼。",o="给格罗姆高营地的肯维雷带回3块蓝色波光碎片。",p=588,r={{i=3911,n="蓝色波光碎片",c=3}}},
  [591]={t="心灵之眼",d="心灵之眼当前落在了一个食人魔法师的手里，他就住在东边的莫什奥格食人魔山的深处，他的名字是麦佐斯。我自暗矛部落还在荆棘谷定居的时候就知道他了，他是一个邪恶的家伙，而且法力非常强大。；如果确实是他拿着心灵之眼的话，他的魔法就会具有极大的威力。；你必须从这个麦佐斯的手中抢到心灵之眼。这确实是件危险的工作，但这也是我们拯救耶尼库的唯一希望了。",o="将心灵之眼交给格罗姆高营地里的肯维雷。",p=589,r={{i=3616,n="心灵之眼",c=1}}},
  [592]={t="拯救耶尼库",d="我已经将心灵之眼重塑为一颗灵魂宝石。你必须先用它震慑住耶尼库，成功之后，就立刻把宝石放在他的额头上，这样才能抽取出他的灵魂。；接下来把宝石交给尼姆布亚就可以了。；耶尼库和流亡者赞吉尔一起住在阿博拉兹废墟，只要沿着水晶海岸走到荆棘谷的海角那边就能找到了。",o="将装满的灵魂宝石交给尼姆布亚。",p=591,r={{i=3913,n="装满的灵魂宝石",c=1}},w={{i=4134,n="尼姆布亚的秘法之杖",c=1},{i=6723,n="勇气勋章",c=1}},f=2},
  [596]={t="染血的白骨项链",d="我是被派来格罗姆高帮助尼姆布亚完成他的任务的，但……我发现这里还有些更有意义的事要做。；血顶部族是我们的敌人。将敌人的战利品抢过来将极大地鼓舞我们的士气，同时也能给对方以沉重的打击。也许你可以帮我们部族猎杀血顶部族的成员……；他们就居住在北边，干掉那些血顶巨魔，把染上它们鲜血的白骨项链给我拿回来。你拿回来越多项链，我们就会越尊敬你。",o="给格罗姆高营地的肯维雷带回25串染血的白骨项链。",r={{i=3915,n="染血的白骨项链",c=25}},f=2},
  [598]={t="裂骨项链",d="你已经收集了足够多的血顶氏族的战利品，现在我要交给你一项新的任务。劈颅部族居住在东南方，以前我们一直和他们互无往来。虽然暗矛部落已经不住在荆棘谷了，但现在我们却卷入了与他们的冲突之中。；所以，我要你去猎杀他们，把他们的裂骨项链带回来给我。如果你在我们这场战争中帮助了我们暗矛部族，就一定会赢得我们的友谊。",o="给格罗姆高营地的肯维雷带回25串裂骨项链。",p=596,r={{i=3916,n="裂骨项链",c=25}},w={{i=4137,n="暗矛之鞋",c=1},{i=4136,n="暗矛之靴",c=1}},f=2},
  [600]={t="风险投资公司",d="最近，风险投资公司在荆棘谷一带展开了一系列的行动，这让我们这些诚实努力的地精们，你看，比如我，根本没办法在这里讨生活了！拜托，你一定要帮帮我！；风险投资公司打算在北边的水晶矿洞那里采矿，可是由于那边的石化蜥蜴到处肆虐，他们根本没办法进入矿洞，只能在周围的山上开采歌唱水晶。；去把他们的水晶都抢来，让他们知道他们不该在这片丛林里如此嚣张。；还有……嗯嗯……把那些水晶给我带回来当证据！",o="给藏宝海湾的克兰克·菲兹巴布带回10块蓝色歌唱水晶。",p=605,r={{i=3917,n="蓝色歌唱水晶",c=10}},w={{i=5253,n="地精点火器",c=1},{i=4128,n="银铲",c=1}}},
  [601]={t="水元素",d="这些水元素无疑是传说中发现了海潮之石的地精法师加兹班召唤的。也许你知道，海潮之石会诅咒任何挪动它的人，就是说，会让那个倒霉的家伙从这个世界上彻底消失。；应该有什么办法可以破除这个该死的诅咒，我们可以请一位达拉然的法师来帮我们分析一下水元素胳膊上戴着的护腕里的魔法。你能不能回到那岛上帮我收集一些进行魔力分析所需的样本？",o="为藏宝海湾的大财主里维加兹收集6个水元素护腕。",p=578,r={{i=3923,n="水元素护腕",c=6}}},
  [602]={t="魔法分析",d="据我所知，达拉然的法师们已经成功地将那座魔法城市整个搬到了诺森德，原址那里只剩下一座大坑了。不过仍然有一些法师留了下来，你应该能找到一个愿意帮我们检查护腕的法师。根据我对那些法师的了解，他们是绝对不会拒绝任何与魔法有关的谜题的。；将这包水元素的护腕拿给他们，让他们看看能不能找到解除石头上的诅咒的方法。你去找大法师安斯雷姆·鲁因就好了。我以前跟他打过交道，他的学识非常渊博。",o="将水元素护腕交给达拉然巨坑的大法师安斯雷姆·鲁因。",p=601,r={{i=3960,n="一包水元素护腕",c=1}}},
  [604]={t="血帆海盗",d="克拉兹高度赞扬了你为黑水海盗做出的重要贡献。我信任你，因此我要赋予你一个对于舰队来说至关重要的任务。；我们要求你渗透进血帆海盗创建在蛮荒海岸的南方指挥部。偷袭他们的营地，将他们的海图与计划书都给我带回来，我们必须要搞清楚这群渣滓到底想干点什么。",o="藏宝海岸的舰队指挥官卡拉·海角要求你杀死10名血帆流氓并将血帆海图和血帆计划书带回去。",p=599,r={{i=3920,n="血帆海图",c=1},{i=3921,n="血帆计划书",c=1}}},
  [605]={t="歌唱水晶碎片",d="歌唱水晶是荆棘谷的一种特产，它对某些人来说有着非常重要的价值。我本想运一些歌唱水晶到别的地方去卖，可那该死的风险投资公司想要独占它，所以，像我这样诚实的商人看来就无法亲自去收集水晶了！；我决定雇佣你。；荆棘谷中的蜥蜴都有吞食这种水晶的习性，这可以使它们的皮肤变得更硬。因此，我们可以从它们身上收获到一些高品质的水晶。；随便哪只蜥蜴身上都会有水晶，但最容易对付的是在北边的海岸附近活动的那些蜥蜴。",o="为克兰克·菲兹巴布收集10块歌唱水晶碎片。",r={{i=3918,n="歌唱水晶碎片",c=10}}},
  [606]={t="吓唬病鬼",d="你知道这里最让我受不了的是什么吗？这儿的人都有死也不还赌债的毛病！现在已经有一大群家伙欠着我的钱了。你能帮我催一下债吗？；第一个要催的就是住在港口那边的“病鬼”菲利普。他上个礼拜欠得实在是太多了，我一定要把这笔钱给要回来！但是要想拿到它，我们就得好好吓唬吓唬他。；到镇子外边去猎杀一些老迈的薄雾谷猩猩，然后从它们身上搞点内脏杂碎什么的，把这些玩意丢给那病鬼。最好别让他想到那是动物内脏，让他想点更糟的。",o="给藏宝海湾的“病鬼”菲利普带回5块薄雾谷猩猩的内脏。",r={{i=3919,n="薄雾谷猩猩的内脏",c=5}}},
  [607]={t="向马克基雷回报",d="给，把这个布袋给海狼。告诉他，我是想还他钱的！我发誓！！；我只是喝多了点，迷路了而已，还有……总之是一团糟了。他会理解我的——你可别乱说啊！",o="将菲利浦的还款交给“海狼”马克基雷。",p=606,r={{i=3922,n="菲利浦的还款",c=1}}},
  [608]={t="血帆海盗",d="打击一下菲尔拉伦的脆弱神经吧！他连划着小船穿越水晶湖都做不到，更别说独自率领整支舰队来和我们对抗了。；血帆海盗一定会为他们的粗心大意而付出代价的。现在我们已经掌握了他们的攻击计划，完全可以在他们什么还都不知道的时候抢先下手。；我们并不需要派出全部的舰队，只要一支勇敢的冒险者队伍就能轻易完成这任务。$n，带上你最优秀的同伴守在菲尔拉伦的登陆点，杀掉血帆的指挥官。这样他们的舰队不用多久就可以去喂鱼了……",o="藏宝海湾的舰队指挥官卡拉·海角要求你杀死血帆海盗的斯蒂沃特船长，尼哈鲁船长和舰队指挥官菲尔拉伦。",p=604},
  [609]={t="讨债行动",d="我这儿的白条已经少了许多啦，但还是有许多没信誉的家伙欠着我的钱。；接下来，我们得对付“畸形足”玛雷·维尔金斯、火柴棍乔乔，还有拇指苏克。；这帮家伙的债欠了好久，我看他们是不想还了！后来，我听说他们被什么人给骗到丛林里去了。我当然不关心他们到底会怎么样——我要的是我的钱！；他们应该就在东北方的阿博拉兹废墟和朱布瓦尔废墟里。找到他们，把我的钱拿回来。",o="给藏宝海湾的“海狼”马克基雷带回玛雷的畸形足、乔乔的金色望远镜和苏克的巨型戒指。",p=607,r={{i=3924,n="玛雷的畸形足",c=1},{i=3925,n="乔乔的金色望远镜",c=1},{i=3926,n="苏克的巨型戒指",c=1}}},
  [610]={t="帅小伙子邓肯",d="我老爸派你来的？我还以为那怪老头已经早就放弃掉我了呢。；我之所以离家出走确实不是他的错，他只是不应该为我安排好一条乏味的人生道路，并希望我欣然接受它。我怎么能忍受整天读着那些发霉的书本，整天和那帮灰头发加驼背的乏味老头法师们在一起！；如果你需要我的匕首，你可能得从一个叫“帅小伙子”邓肯的血帆海盗那里夺回来。我想你只要教训教训他，他就会屈服的。",o="从“帅小伙子”邓肯那里夺回凯特琳的匕首。",p=603,r={{i=4027,n="凯特琳的匕首",c=1}}},
  [611]={t="海潮的诅咒",d="这么说你正在寻找某个祭坛喽？好吧，虽然我不像我老爸那样是个研究巨魔遗迹的专家，但我对你正在寻找的岛屿也略知一二，在岛的附近有一座沉没在水底的巨魔城市，我想你应该到那里去碰碰运气。；既然是你帮我找回了我的匕首，借去用用当然没有任何问题……但我希望你用完以后能还给我！",o="用凯特琳的匕首摧毁海潮祭坛，然后杀死加兹班，将海潮之石带给大财主里维加兹。",p=610,r={{i=4034,n="海潮之石",c=1},{i=4027,n="凯特琳的匕首",c=1}},f=1},
  [613]={t="玛雷的腿",d="该死！那见鬼的玛雷居然在他的假腿上安了一个锁，我还死活都打不开！他的宝贝，还有他欠我的钱，都藏在那条假腿里！；我们得想办法找到钥匙才行。玛雷这家伙过去因为喜欢和住在东北边食人魔山上的莫什奥格食人魔赌博而出名，而且他告诉过我——我是说当他还活着的时候——他每次赢了一票大的之后都会去一趟那里，所以，或许那边的食人魔会有他的钥匙。；要真是如此的话，你八成得大开杀戒才能搞到钥匙……",o="把玛雷的钥匙带给藏宝海湾的“海狼”马克基雷。",p=609,r={{i=3930,n="玛雷的钥匙",c=1}}},
  [614]={t="船长的箱子",d="我过去在一条专跑从这里到卡利姆多的棘齿城的航线上干过。我是个很优秀也很有名望的船长。；直到……；那些该死的海巨人毁了我的生活！他们打沉了我的船，杀光了我的水手，把我丢在一条救生艇上，让我漂回了藏宝海湾。还有，其中一个名叫高拉什的巨人还把我的箱子给偷走了，他说要拿这东西当鼻烟盒，简直是神经病！；我听说有人看见高拉什最近在东边的海岸一带闲逛。找到他，把我的箱子给抢回来！快去，你会得到一位船长的敬意的。",o="将斯莫特的箱子交给藏宝海湾的海克拜瑞·斯莫特。",r={{i=3932,n="斯莫特的箱子",c=1}},f=1},
  [617]={t="一捆海蛇草",d="听说你正在找活做，你？要是你够胆的话，我这儿倒是有件不错的活正要找人呢。；你听说过最近有许多人都在找一处泉水么？是的，有一群纳迦也在找。我有个叫格罗伊的朋友吧，他最近出了一大笔钱，想买一些纳迦称之为海蛇草的东西。我也不清楚那到底是什么，只知道是一种很值钱的海草。他也没说要那玩意干什么，不过他确实出了一个好价钱，大概需要一捆吧。；你帮我搞来10根这种什么草，那我们就可以跟他做笔交易啦。不久前有人看见这里北边的海滩上出现了不少纳迦。",o="给藏宝海湾的海盗布劳兹带回10根海蛇草。",r={{i=4029,n="海蛇草",c=10}}},
  [618]={t="挑战奈古拉什",d="奈古拉什总是一副随时准备把一切都吞下去充饥的样子。；那些巨人袭击我们的船的时候，奈古拉什直接冲向了我的厨房，不过他可不像其它巨人那样喜欢吃人。奈古拉什要的是酒……还有我秘制的烧烤秃鹰翅膀。嘿，这可都是我的拿手菜，我当年可是跑到荒芜之地才弄到这食谱的！；如果你想把奈古拉什给引出来，只要用点酒再加上一碟烤翅就行啦。把这些东西放进我们当初丢在东南边海岸上的救生艇里，然后你就等着奈古拉什闻到食物的味儿乖乖上钩吧！",o="将10块烧烤秃鹰翅膀和5瓶密林葡萄酒带到斯莫特船长的救生艇上去。；然后杀死奈古拉什，将斯莫特的弯刀交给荆棘谷的斯莫特船长。",p=615,r={{i=3935,n="斯莫特的弯刀",c=1}}},
  [621]={t="赞吉尔的秘密",d="流亡者赞吉尔和他的追随者们住在藏宝海湾东北方的朱布瓦尔废墟和阿博拉兹废墟里，这个家伙已经被他的部族放逐了。为什么？这个……；据说是因为赞吉尔掌握了某种可以将自己的心灵与他人连接在一起的方法，而他所属部族的领袖就因此非常害怕他。他让他的追随者们喝下了一种从植物中萃取出来的液体，用它来压抑他们的自我意识并加强他们的力量。；他的这种药剂对那些试图控制别人的家伙来说有非常大的价值。；给我弄些这种药剂的样本来，我要研究一下……",o="收集12份赞吉尔的药剂，把它们交给藏宝海湾的克兰克·菲兹巴布。",r={{i=4016,n="赞吉尔的药剂",c=12}}},
  [622]={t="向卡雷布下士回报",d="在你离开的这段时间里我已经把这锅替你修好啦。我甚至还免费加装了一个特制的蒸汽哨，看，华丽吧！这下面还装了一个新的自动菜刀，专门用来切蹄膀的！；没错，克拉兹克的烹调锅将为你带来百分之百的烹调乐趣，我敢打赌它的主人会非常满意的！",o="将修理过的烹调锅交给叛军营地的卡雷布下士。",p=627,r={{i=1987,n="修理过的烹调锅",c=1}},f=1},
  [627]={t="克拉兹克的要求",d="在阿拉希高地北部的枯须峡谷中有一处山洞，那里有一种十分稀有的矿石：血石。那个山洞里的血石虽然不是品质最佳的，但即使是低等级的血石也是很有价值的……当然这只是对那些懂得如何使用它们的人来说。；我需要一些这种血石。；我会在这里修补你的锅子，不过，当我修锅的时候……你去给我弄些血石来吧。对，多带点回来，我当然会给你报酬的。；嗯嗯，要是你连这点事都搞不定，就去找个能搞定的人帮你！",o="给藏宝海岸的克拉兹克带去4块次级血石矿。",p=210,r={{i=4278,n="次级血石矿",c=4}}},
  [628]={t="刨花皮靴",d="既然里面的东西都已经做完了，那么就只剩下外面的表层部分了。表层一定要用质量最好的老鳄鱼的皮。这种皮甚至比帆布还要结实，用它就可以完成我的完美设计。；虽然要找到完美的皮很难，但这种老海鳄的皮是唯一能配得上我的设计的材料了。老海鳄只会在其它鳄鱼被攻击的时候才会出来保护族群，所以恐怕你得先杀些普通鳄鱼引它们出来。",o="给藏宝海湾的崔斯里克带回1张老鳄鱼的皮。",p=577,r={{i=4105,n="老鳄鱼的皮",c=1}}},
  [630]={t="瓶中信",d="你，我的一切都全靠你了！是蓝鬃猩猩之王穆克拉把我抓进来的，它统治着这岛上所有的野兽，它们不顾我的反抗，用这些铁链把我给锁在这儿。如果你能杀了它，从它身上找到能够打开这套镣铐的钥匙的话，我会好好报答你的。；它通常在这座岛的北边活动，但你一定得小心，它绝对是一个很难对付的家伙。",o="杀死穆克拉并带着钥匙回去救出普巴尔公主。",p=594,r={{i=4103,n="镣铐钥匙",c=1}}},
  [632]={t="萨多尔大桥",d="很显然，可怜的老伊本瑟遭遇到了黑铁矮人的伏击，已经战死了。但你突然注意到了他紧握着的拳头中似乎有一张皱皱的羊皮纸。；将这条令人沮丧的消息告诉拉格·加玛森，并把你的发现报告给他。",o="向湿地中丹莫德的拉格·加玛森回报，并将你在伊本瑟尸体上找到的羊皮纸交给他看看。",p=631,r={{i=4429,n="深怒的命令",c=1}}},
  [633]={t="萨多尔大桥",d="天呀！不！可怜的伊本瑟，这实在是一个悲剧。；我们绝对不能让他就这样白白牺牲了。你发现的这张羊皮纸上写道，是卡姆·深怒在背后组织了这次进攻，并且，他还在萨多尔峡谷的阿拉希高地那一侧囤积了不少炸药。；如果他们用这些炸药摧毁了桥梁的话，那么我们的通向北边的主要补给线就会被彻底切断！必须摧毁这些炸药，$n！完成了这个任务后立刻回来向我复命。；你是我们最后的希望了。",o="摧毁堆积的炸药。",p=632,w={{i=4504,n="矮人卫兵披风",c=1},{i=4505,n="沼泽长裤",c=1}},f=1},
  [637]={t="苏利·巴鲁的信",d="你手中的这封信湿淋淋的，已经面目全非了，只有几页像是得到了精心保护的信纸上的字迹还能辨认。；这封信是写给铁炉堡的萨拉·巴鲁女士的，开头写着，“亲爱的萨拉……”",o="把苏利·巴鲁的信交给铁炉堡的萨拉·巴鲁。",r={{i=4432,n="苏利·巴鲁的信",c=1}}},
  [639]={t="激流堡符印",d="在古代，巨魔曾与阿拉索帝国以及我们最强大的对手——被称为“激流堡的伊格纳乌斯”的托尔贝恩作战。托尔贝恩总是挥舞着托卡拉尔剑进行作战。在古代语中，托卡拉尔是“巨魔杀手”的意思。；然而，现在托尔贝恩子孙的势力已大不如前了，他们的要塞也已经变成了废墟。；托卡拉尔剑是由几块符印保护的，这些符印现在都在激流堡的幸存者手中，我们必须获得它们。；辛迪加组织拥有第一块——这一块应该就在他们驻扎于激流堡的那群人中的某个人手里。",o="帮落锤村的森古拿回激流堡符印。",r={{i=4440,n="激流堡符印",c=1}}},
  [640]={t="破碎的符印",d="索拉斯·托尔贝恩的墓室由三块符印护卫，这其中的第一块你已经从辛迪加手中得到了。另外两块更难得到，因为它们被牢牢地控制在激流堡的民兵手里。；索拉丁符印被索拉斯的儿子加林分成了五块，分别由一个激流堡守卫者掌握。取回这些符印，把它们交给巨魔祭司托尔甘，他能够将它们合成一块完整的符印。",o="从激流堡的守卫者那里取回5块符印碎片，把它们交给落锤村的托尔甘。",p=639,r={{i=4450,n="符印碎片",c=5}}},
  [641]={t="索拉丁符印",d="复原得完美无缺。现在，这块完整的符印可以被用于打开托尔贝恩墓穴上的封印了。把它交给森古吧，他一定还有别的任务要你完成。",o="把修复的索拉丁符印交给落锤村的森古。",p=640,r={{i=4453,n="索拉丁符印",c=1}}},
  [642]={t="被困的公主",d="我叫密斯莱尔，我是大地的公主。巨人们俘获了我，把我拘禁在阿拉希高地的地下深处。这些水晶碎块是我和外界交流的唯一途径。；帮帮我。这些巨人的盟友——枯须狗头人——就在东边的枯须峡谷里活动，那里有一块类似水晶碎块。要激活那块水晶，你必须从狗头人那里收集到密斯莱尔之尘，然后把它们放在水晶上。；求求你了，你，帮帮我吧！",o="收集密斯莱尔之尘。；把它们放在枯须峡谷中的虹光水晶碎块上。",r={{i=4435,n="密斯莱尔之尘",c=12}}},
  [643]={t="阿拉索符印",d="尽管他们还没有控制激流堡，更不要说整个阿拉希高地，但那人类王子却率领着剩馀的骑士在乡间疾驰。我不能理解他为什么这么做，谁又能理解人类的思维方式呢？；且不管他到底是怎么想的，最重要的是他把一块符印交给了瓦罗卡尔中尉，也就是那群骑士的首领。找到这个人，把他的符印带回来交给我。",o="取回阿拉索符印，把它交给落锤村的森古。",p=641,r={{i=4458,n="阿拉索符印",c=1}}},
  [644]={t="托尔贝恩符印",d="打开索拉斯·托尔贝恩墓室所需的最后一块符印掌握在他儿子手中。他深居在激流堡的一座由民兵控制的教堂里。加林王子的保卫措施非常严密，他本人也是一名强大的勇士，所以这次你的任务会是非常艰巨的。",o="杀掉加林·托尔贝恩王子，把托尔贝恩符印带给落锤村的森古。",p=643,r={{i=4466,n="托尔贝恩符印",c=1}}},
  [645]={t="托卡拉尔",d="将四块符印放在一起，它们就能互相结合形成一块完整的符印。毫无疑问，这块符印能够击破托尔贝恩地墓室里的防护魔法。；托尔贝恩的遗体就埋葬在激流堡教堂后的密室中。去取回托卡拉尔。",o="从激流堡的托尔贝恩墓室中取回托卡拉尔剑。",p=644,r={{i=4467,n="伊格纳乌斯符印",c=1}}},
  [646]={t="托卡拉尔",d="光芒慢慢地褪去，石鞘中的托卡拉尔剑已经松动了。",o="把托卡拉尔剑交给落锤村的森古。",p=645,r={{i=4468,n="入鞘的托卡拉尔",c=1}},w={{i=4508,n="血斑护甲",c=1},{i=4507,n="斗士之盾",c=1}},f=2},
  [648]={t="Rescue OOX-17/TN!",o="Escort OOX-17/TN to Steamwheedle Port, then report to Oglethorpe Obnoticus in Booty Bay.",p=351,w={{i=9643,n="光磁盾牌",c=1},{i=9644,n="蛋温测量计时器",c=1}}},
  [651]={t="禁锢之石",d="在阿拉希高地上散布着4块禁锢之石，这些石头将我牢牢地钉在地下。；要想解除它们，你就必须解除最坚固的那块：内禁锢之石。首先，你必须搜集到其它三块石头的钥匙。；这些石头都有守护者在看守，但是如果你足够聪明或者足够幸运的话，就能找到消灭这些守卫的办法。",o="从西禁锢之石、东禁锢之石和外禁锢之石中搜集烈焰钥匙、海浪钥匙和雷霆钥匙。；把它们带到内禁锢之石处。",p=642,r={{i=4483,n="烈焰钥匙",c=1},{i=4484,n="海浪钥匙",c=1},{i=4485,n="雷霆钥匙",c=1}}},
  [652]={t="打开钥匙之石",d="禁锢之石的开启基本解开了这些束缚着我的东西，可还有一把牢不可破的锁让我无法动弹。你看到这圈石头中的那块钥匙之石了吗？开锁的钥匙在弗兹鲁克手中，他是囚禁我的巨人之一，也是这石锁的看护人。；你必须从弗兹鲁克那里获得一把名叫“秩序魔棒”的钥匙来打开钥匙之石。；你已经为我做了这么多，$n，只是再帮个微不足道的小忙……我会对你更加感激不尽的！",o="找到并杀死弗兹鲁克，然后把秩序魔棒带到阿拉希高地的钥匙之石旁。",p=651,r={{i=4469,n="秩序魔棒",c=1}}},
  [654]={t="塔纳利斯的样本",d="启动能量源之后，野外实验工具包开始闪光和震动，看来它开始按照预定的程序工作了。；我会立刻将它送走。；根据首席工程师比格维兹所说的，你现在还有一些时间在塔纳利斯沙漠收集你所需的数据。；当你完成任务之后就尽快回到他那里。",o="收集8份蜥蜴样本、8份土狼样本和8份蝎子样本，然后在能量源耗尽之前把野外实验工具包还给加基森的首席工程师比格维兹。",p=379,r={{i=9440,n="可用的石化蜥蜴标本",c=8},{i=9441,n="可用的土狼标本",c=8},{i=9438,n="可用的蝎子标本",c=8},{i=8523,n="野外实验工具包",c=1}}},
  [656]={t="召唤大地公主",d="你必须在密斯莱尔恢复力量之前打败她。否则，一旦等到她聚集到足够的能量，密斯莱尔就会向追捕她的人发起挑战！有一些人自信能控制住她，但是如果她真能被控制住，巨人们有必要先发制人把她囚禁起来吗？；这是个疯狂的逻辑，难道不是吗？；你必须在第一次和她接触的密斯莱尔水晶碎块那里将她召唤出来，然后打败她。在打败她之后搜出她身上的怪异镣铐，然后与密斯莱尔水晶碎块缚在一起。；只有这样做才能再次将密斯莱尔囚禁起来。",o="到密斯莱尔水晶碎块去召唤她，然后打败她。；搜出她身上的怪异镣铐，将其和密斯莱尔水晶碎块缚在一起。",p=692,r={{i=4473,n="怪异镣铐",c=1}}},
  [658]={t="新的瘟疫？",d="是费恩让你来找我们的吧？我一点都不吃惊，那家伙总是担心这个担心那个的。；我们监视这个农场已经有些时候了，基恩洛说她不久前看见有一个信使从那间小房子里走出来，往南边去了。；她平时话有些多，不过在这种危险的地方，我总是相信她的直觉。；嗯……你的追踪能力怎么样？我们认为那个信使可能是带着信去塔伦米尔了。如果你能弄到那些文件，就有可能帮助我们搞清楚在希尔斯布莱德所发生的那些怪事。",o="找到被遗忘者信使，把她的密封的信件交给格沙克农场里的奎艾。",p=659,r={{i=4482,n="密封的信件",c=1}}},
  [661]={t="Hints of a New Plague?",o="Find Phin Odelic in Southshore.",p=660,w={{i=15455,n="落尘长袍",c=1},{i=15456,n="快步护腿",c=1}},f=1},
  [662]={t="深海打捞",d="奥布里领船进入海湾，我们确信能在这里发现宝藏。先驱号安全靠岸，但是当处女号和银松之魂号靠近港口的时候，退潮开始了。此时发生了怪事！；那两艘船撞上了什么东西……似乎是暗礁中的什么庙宇……它们很快就沉没了，这真是一场灾难。；我们必须要在离开以前去取回他们的日志和航海图，这些有价值的信息绝对不能留给任何其它人！",o="大副尼兹利克斯让你从处女号和银松之魂号中取回航海图和航海日志。",p=663,r={{i=4487,n="处女号的航海图",c=1},{i=4489,n="处女号的航海日志",c=1},{i=4488,n="银松之魂号的航海图",c=1},{i=4490,n="银松之魂号的航海日志",c=1}}},
  [664]={t="船长的复仇",d="啊，多么可怕的生活！我本以为我再也不能像现在这样坐在火堆旁呼吸着新鲜的空气了！；船员们为了拯救我那美丽漂亮的处女号尽了全力。愿神保佑他们，保佑他们的心灵。；奥布里船长的船安全地进了港，可我们就没那么幸运了，大浪弄沉了我们的船。；前一秒钟我们还漂浮在海上，转眼间就又被海浪吞没。而那些该死的纳迦还杀死了所有的幸存者！我逃到这里来，算是勉强保住了性命。；我要让那些野兽去死！",o="法迪尔海湾的斯迪加特船长要你去杀掉10个刺脊袭击者和3个刺脊巫师。"},
  [665]={t="水下宝藏",d="既然我们已经整装待发，那么帮助奥布里先生寻找丢失的精灵宝藏就是当务之急了！；在黑暗的海底，如果没有任何辅助手段的话，要想找到那些宝藏几乎是不可能的。博士做的潜水镜可以派上大用场，不过他要从山上的洞穴里弄些魔石来，好给他的潜水镜附上魔法。；但是那座洞穴已经被诅咒了！只要我们靠近洞穴就会遭到伏击。你得掩护我，让我控制魔石的能量，将它注入到潜水镜里。",o="护送菲兹索普教授到洞穴里去并平安返回。"},
  [666]={t="水下宝藏",d="宝藏在海床上放了那么长时间，早已经被岩石包裹起来了。但是借助潜水镜中的魔法力量，你可以轻而易举地锁定这些宝藏。；侏儒的创造能力实在是让人惊叹！；那么你去把寻宝潜水镜借来用用，$n，看你能不能帮奥布里船长找回些丢失的宝藏。；我可以潜游到那儿，可是……嗯……在这片安全而干燥的土地上，我有些重要的科学研究要做……嗯，是这样的。",o="法迪尔海湾的德拉克里格博士要你去收集10块精灵宝石并在完成任务后归还寻宝潜水镜。",p=665,r={{i=4492,n="精灵宝石",c=10},{i=4491,n="寻宝潜水镜",c=1}},w={{i=4547,n="侏儒除草器",c=1},{i=4548,n="自动战锤",c=1}}},
  [667]={t="Death From Below",o="Protect Shakes O'Breen during the attack.",p=670,w={{i=4550,n="冷水之戒",c=1},{i=4549,n="海焰指环",c=1}}},
  [668]={t="水下宝藏",d="我们不要让奥布里船长等了。他急着想看到这些宝藏呢。这不正是我们在这儿的原因吗？；和这些海盗们打了几个星期的交道以后，我和教授都意识到，手里拿着海盗的宝藏永远是不安全的。；拿着这些，$n，把它们交给奥布里。",o="把精灵宝石交给阿拉希高地中法迪尔海湾的奥布里船长。",p=666,r={{i=4493,n="精灵宝石",c=1}}},
  [669]={t="水下宝藏",d="舰队指挥官卡拉·海角一定想马上知道我们找到了什么。；你也看到了，我们还不能离开这儿。不单单是因为潮水太低的缘故，还因为那些被我们惊动的可恶家伙正密切地注视着我们的一举一动。；假如你能把口信带给藏宝海湾的舰队指挥官卡拉·海角，并告诉他我们已经发现宝藏的话，你可就帮了我们黑水海盗的大忙了。把这件东西交给舰队指挥官卡拉·海角，这样他就会确信你说的是真的了。",o="把精灵宝石样本交给荆棘谷藏宝海湾的舰队指挥官卡拉·海角。",p=668,r={{i=4502,n="精灵宝石样本",c=1}}},
  [670]={t="水下宝藏",d="嘿，$n，看来你是个喜欢冒险的$r。在我们重新进货之前，我的船队会一直停泊在藏宝海湾。；这里即将发生一些大事，我得找人把相关的绝密信息通报给在阿拉希海岸上的沙克斯·奥布里。；你可以确保将口信安全而保密地送达吗？",o="把海角船长的密信送给阿拉希高地中法迪尔海湾的沙克斯·奥布里。",p=669,r={{i=4494,n="海角船长的密信",c=1}}},
  [671]={t="邪恶的魔法",d="我感觉空气中弥散着一种奇怪的东西……这种感觉在我的血液中不断升腾。对此我感到很奇怪，于是便着手去寻找给我造成这种不安的原因，然后我就在西边的诺斯弗德农场找到了一些邪恶的召唤法术留下的痕迹。当我慢慢地靠近时，我的热血开始沸腾，胸中的怒气不断上升。；我在地上发现了一枚血石护符，那是用在恶魔召唤仪式中的东西。可是，我找到的这枚血石护符的能量已经被耗尽了。现在我需要再弄一些来研究，可我不敢回农场去了。你能帮我找一些来吗？",o="帮落锤村的托尔甘找10枚血石护符。",r={{i=4495,n="血石护符",c=10}}},
  [672]={t="振奋精神",d="我们把他安顿下来，不断地鼓舞他，向他讲述我们在卡利姆多创建伟大的奥格瑞玛城的故事，但所有的这些都无法打动他。；关于我们年轻的酋长的故事，拥有奥格瑞姆的战甲和战锤的萨尔酋长……也许吧……也许吧！我们新发现的萨满魔法或许会带给他新的希望。这值得一试！；我们可以给他一件小东西，对……给我带些迅猛龙的眼睛，我要看看我们能做些什么。",o="从高地阔步龙和高地长尾龙身上取得10个高地迅猛龙的眼球，把它们交给落锤村的托尔甘。",p=655,r={{i=4512,n="高地迅猛龙的眼球",c=10}}},
  [673]={t="邪恶的魔法",d="我确信有一个强大的术士居住在激流堡城内。这个术士经常通过一种魔法物品来召唤大量的恶魔。我们必须毁掉他的能量源泉。；找到这个术士，杀掉他。把所有你在他身上发现的物品都拿来给我，我会设法销毁它的。我们绝对不能让这片大地再被玷污了！",o="取回玛雷兹·考尔的血石宝珠，把它交给落锤村的托尔甘。",p=671,r={{i=4510,n="邪恶的血石宝珠",c=1}},w={{i=4543,n="白龙皮盔",c=1},{i=4545,n="亮银护腕",c=1}},f=2},
  [674]={t="振奋精神",d="把这枚护符交给戈穆尔，看看迅猛龙的力量能否唤醒这位勇士的血管中曾经燃烧过的火焰。",o="把迅猛龙利爪护符交给阿拉希高地落锤镇的戈穆尔。",p=672,r={{i=4526,n="迅猛龙利爪护符",c=1}}},
  [676]={t="落锤之战",d="软弱的家伙……他们全都是懦夫……你，$c，你在看什么？你觉得自己有什么特殊的么？怎么不去证明一下？；阿拉希的落锤村哨所正受到攻击。再不增派援兵的话，他们就会全军复灭的。；不过在你去那里之前，是不是应该先试试看自己够不够格？阿拉希的激流堡东北部有个食人魔的营地，石拳部族的食人魔就住在那里。等你搞定了那里的食人魔和执行者之后，再去向落锤村的杜拉姆法尔报告吧。",o="杀掉8个石拳食人魔和10个石拳执行者，然后去阿拉希高地的落锤村哨所找杜拉姆法尔。"},
  [677]={t="短兵相接",d="枯木巨魔和阿拉希的石拳食人魔联合起来，要把我们赶出这片土地，但我们决不会把命运交给他们掌控！我们要除掉他们，让他们知道谁是这儿真正的主宰。；巨魔背弃了我们，食人魔想要把我们当作美味的食物——我们决不能允许这种事情发生。；现在，让我们从南边的枯木巨魔开始吧。去杀掉他们，让他们血流成河！",o="杀死10名枯木掷斧者、10名枯木猎头者和8个枯木巫医，然后回到落锤村哨所的杜拉姆法尔那里。",p=676},
  [678]={t="短兵相接",d="你，你的强大已经是有目共睹的了。现在让我们看看你如何去面对一个真正的敌人。；从这里往西南走，在通往矮人修建的那座大桥的途中，有一个石拳食人魔的老巢。如果我没搞错的话，那儿的虐待者和法师对你来说应该是个难度不小的挑战——至少到现在为止对于我们来说是这样的。；尽可能多地杀死他们，无论最终是胜利还是失败，无论回来见我的是你自己还是你的灵魂，我都会赞赏你在战斗表现出的坚韧精神。",o="杀死10个石拳蛮兵和4个石拳法师，然后向落锤村哨所的杜拉姆法尔复命。",p=677},
  [679]={t="短兵相接",d="你，现在是时候和这些家伙算总账了……很明显你完全有能力帮我们完成这最后的一击。这些与我们为敌的蠢货的领导者已经在激流堡废墟里创建了巢穴。激流堡的废墟……那是人类软弱无能的最好证明！；找到那些石拳领主和他们的萨满祭司，把他们全都杀掉，这些妄图将我们赶离家园的蠢货们活不了多久了！",o="杀死7个石拳萨满祭司和3个石拳领主，然后向落锤村哨所的杜拉姆法尔复命。",p=678,w={{i=9520,n="沉默猎手",c=1},{i=9521,n="裂颅者",c=1}},f=2},
  [680]={t="真正的威胁",d="你帮我丈夫干得不错，$c，可他并不知道为什么落锤村会遭受攻击。；奥卡拉尔是玛格索尔派到激流堡去的走狗，他非常害怕我的丈夫。很多年前，我的丈夫打败了他，他巴不得我的丈夫早点死去。；我占卜到奥卡拉尔给我的丈夫设下了陷阱，并且感觉到了那些食人魔正在伺机害他……；如果他知道那些食人魔在哪里的话，一定会不顾三七二十一地杀过去。所以……请你帮我杀死奥卡拉尔吧。",o="杀死奥卡拉尔，将他的徽记带给落锤村哨所的科林法尔。",p=678,r={{i=4551,n="奥卡拉尔的徽记",c=1}},w={{i=4976,n="雾彩褶裙",c=1},{i=4977,n="落锤之剑",c=1}},f=2},
  [681]={t="诺斯弗德农场",d="我们正在为激流堡而战，然而我们却逐渐落入下风。我们、食人魔以及辛迪加分别控制着这座城市的一部分，现在我们这三方势力陷入了整日互相征战却毫无突破的僵局。；然而，当敌人们力量开始逐渐增强的时候，我们却在慢慢地变弱。；我们需要南海镇的援助，但是辛迪加控制了我们和南海镇之间的领地，因此那边的补给很难运到这里来。；到辛迪加在诺斯弗德农场的基地去干掉他们，也许这样做能让我们补给线上的压力大大减轻，然后才能有更多的物资平安运抵这里。",o="杀掉6个辛迪加雇佣兵和10个辛迪加路霸，然后回到避难谷地去向尼艾丝队长复命。"},
  [682]={t="激流堡徽章",d="我们的民兵分队正在和控制着激流堡的辛迪加成员激战。为了刺激他们那群乌合之众与我们作战，辛迪加的头目们使出了重金悬赏的手段，只要有人能杀死我们的民兵，并从他们身上缴获激流堡徽章，辛迪加都会给予奖励。；我们必须夺回那些徽章——决不能让刽子手们用我们的战士的性命来换取金钱！；到激流堡城内的辛迪加控制区去杀掉那些歹徒，取回我们的徽章。",o="把7枚激流堡徽章交给位于避难谷地的尼艾丝队长。",p=681,r={{i=4506,n="激流堡徽章",c=7}},f=1},
  [683]={t="萨拉·巴鲁的请求",d="$n，我对你有个小小的请求。；这张便笺是我写给铁炉堡的国王麦格尼·铜须的。对于你这种曾为联盟的事业英勇作战的$r来说，这个任务再容易不过了。；以我在现在这种状态去觐见国王陛下是很不合适的，我相信你应该可以理解。",o="把萨拉·巴鲁的便笺交给铁炉堡的国王麦格尼·铜须。",p=637,r={{i=4514,n="萨拉·巴鲁的请求",c=1}}},
  [684]={t="通缉：玛雷兹·考尔",d="重金悬赏玛雷兹·考尔。这个兽人是辛迪加组织的高级顾问和技工，人们最后一次看见她是在激流堡内的辛迪加控制区。；赏金请到尼艾丝队长处领取。；请注意：玛雷兹是一个强大而狡猾的术士，她和恶魔有着非常密切的联系。追杀她时务必非常小心。",o="把玛雷兹的徽记交给避难谷地的尼艾丝队长。",r={{i=4515,n="玛雷兹的徽记",c=1}},f=1},
  [685]={t="通缉：奥图和法库雷斯特",d="激流堡民兵团重金悬赏法库雷斯特公爵和他的保镖奥图的徽记。法库雷斯特是辛迪加在阿拉希地区的主要领导者，他的死将使该组织在这一地区的活动陷入瘫痪。；他的保镖奥图不是我们的战略目标，但他生性凶残，已经杀死了许多激流堡的士兵。；赏金请到尼艾丝队长处领取。",o="把法库雷斯特和奥图的徽记交给避难谷地的尼艾丝队长。",r={{i=4516,n="奥图的徽记",c=1},{i=4517,n="法库雷斯特的徽记",c=1}},w={{i=5247,n="悲伤魔棒",c=1},{i=4745,n="骑兵护腕",c=1}},f=1},
  [689]={t="国王的礼物",d="我们的国王要建一座纪念碑向一个叫苏利·巴鲁的士兵致敬？你是说那个可怜的士兵是在萨多尔大桥的悲剧中死的？；唉，艾泽拉斯还会有和平吗？；不管怎样，国王下达的任务就是第一要务。我要用最好的石头来建这座纪念碑，你到希尔斯布莱德的丘陵洞穴为我找一些奥特兰克花岗岩来吧。",o="铁炉堡的大石匠玛布勒斯坦要5块奥特兰克花岗岩。",p=686,r={{i=4521,n="奥特兰克花岗岩",c=5}}},
  [691]={t="证明实力",d="你，别怕斯奎尔图。他是因为事情太多才变得这么暴躁。在我们等他完成侦察任务的时候，为什么不做些更有意义的事情呢？马林派我到这里来为他收集一些试剂，对于如何收集这些物品，我感到很困惑。不过现在你来了，我想我的问题也解决了。；我需要这些东西：枯木巨魔的獠牙，枯木巨魔的医药包和一把暗影猎手的小刀。；你能帮我找到这些吗？枯木巨魔一般都在阿拉希高地的东南一带出没。",o="帮避难谷地中的学徒克里汀收集10个枯木巨魔的獠牙，4只枯木巨魔的医药包和1把暗影猎手的小刀。",r={{i=4503,n="枯木巨魔的獠牙",c=10},{i=4522,n="枯木巨魔的医药包",c=4},{i=5040,n="暗影猎手的小刀",c=1}}},
  [692]={t="遗失的卷轴碎片",d="密……密斯莱尔卷轴？！你要那东西干什么？它强大的魔法力量可以把密斯莱尔召唤到地面上来，那时候我们就有大麻烦了！；也许……也许已经太迟了，也许她已经自由了。密斯莱尔可能正在为报复我们而聚集力量。如果是这样，那你就必须掌握着这至关重要的卷轴！；……太糟了，它被毁掉了。愤怒的元素生物偷走了卷轴，并将它撕成了碎片。现在它们又在为这些碎片争斗不休。；如果你能搜集那些碎片的话，也许我们还有希望将它修复成原来的样子……",o="把破损的卷轴碎片、弄皱的卷轴碎片和烧焦的卷轴碎片带给迷失者塞尔杜林。",p=687,r={{i=4518,n="破损的卷轴碎片",c=1},{i=4519,n="弄皱的卷轴碎片",c=1},{i=4520,n="烧焦的卷轴碎片",c=1}}},
  [693]={t="特雷莱恩的符咒魔杖",d="你好啊，你，很抱歉我以前对你那么凶……我可以断定特雷莱恩的第一件宝物的所在：它在石拳大厅的考格雷什手里。顺便说一句，他已经可以使用冰爆术来教训不听话的手下，看来离他完全掌握魔杖力量的日子也已经不远了。；石拳大厅就在这里的南边，萨多尔大桥的东边。从那个食人魔手里把那根魔杖拿回来吧。；rn在你回来之前，我要想想我们要怎样解决激流堡的问题。",o="帮避难谷地的斯奎尔图找到特雷莱恩的符咒魔杖，并把它带回来。",p=691,r={{i=4525,n="特雷莱恩的符咒魔杖",c=1}}},
  [694]={t="特雷莱恩的防御",d="休息好了吗？；我们的下一步计划和激流堡的阿拉索之塔周围的食人魔有关。我们必须首先开启这座塔的防御系统，当然，前提是你能活着到达存放那些物品的地方。为此，首先我们需要一些石拳萨满祭司经常携带着的宝石。他们把宝石从塔里带了出来，但他们没有什么机会占有这些宝石了。；从他们那里弄一块宝石，把它送去给克里汀——他能够给宝石附魔，这样一来，宝石就可以当钥匙用了。",o="找到一块碧蓝玛瑙石，把它交给避难谷地处的学徒克里汀。",p=693,r={{i=4527,n="碧蓝玛瑙石",c=1}}},
  [696]={t="进攻高塔",d="以下是你要找的东西：特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙。；所有这三样东西应该都在塔中的箱子里，你打开这些箱子应该不会有什么问题，只是要当心那些食人魔就成。；阿拉索之塔的防御不会作用于那些食人魔，因此你必须时刻准备战斗。如果那些食人魔发现你在偷他们的东西，你就少不了一场恶战。；多加小心，祝你好运。",o="找到特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙，把它们交给避难谷地的斯奎尔图。",p=695,r={{i=4530,n="特雷莱恩的护符匣",c=1},{i=4531,n="特雷莱恩的宝珠",c=1},{i=4532,n="特雷莱恩的黑玛瑙",c=1}}},
  [697]={t="马林的要求",d="把这封信送到暴风城去，让马林知道我和克里汀很快就可以回家了。对于你给我们的帮助，马林一定会好好回报你的，你，对于这一点我深信不疑。；祝你旅途顺利。",o="将给大法师马林的信交给暴风城法师区里的大法师马林。",p=696,r={{i=4533,n="给大法师马林的信",c=1}},w={{i=4975,n="警觉圆盾",c=1},{i=15104,n="翼展长靴",c=1}},f=1},
  [698]={t="缺乏补给",d="我正努力为我们在东边海滩那里的哨所收集一些补给品，托克卡尔已经尽了他的全力。但他又要值勤，又要为他的士兵们做饭，一天这么下来就没什么时间了。；他们很喜欢吃盐齿鳄鱼的肉，但我没时间为他们再送去一批补给了。你能帮我这个忙吗？；盐齿鳄鱼幼崽的肉不如成年鳄鱼的口感好，所以你别猎杀小鳄鱼，等它们长大了再吃它们也不迟。",o="给悲伤沼泽的托克卡尔带去8块新鲜的盐齿鳄鱼肉。",r={{i=6169,n="新鲜的盐齿鳄鱼肉",c=8}}},
  [699]={t="缺乏补给",d="我们之所以被部署在这里，是为了警戒在这片海岸附近出没的鱼人，以防它们——或者任何其它什么东西——威胁到斯通纳德，当然，要是他们太嚣张了点的话，我们也会去给它们一些颜色看看。这工作可不轻松，我们几乎很少有自由的时间，所以只好拜托你来帮忙了，当然，我是说如果你愿意的话。；加工得当的盐齿钳嘴鳄的爪子可以用来制作精良的武器，给我带些它们的爪子回来，我就会送你一件精致的武器作为酬谢。",o="给悲伤沼泽的托克卡尔带去6只盐齿钳嘴鳄的爪子。",p=698,r={{i=6168,n="盐齿钳嘴鳄的爪子",c=6}}},
  [700]={t="A King's Tribute",o="Report to King Magni Bronzebeard.",p=689,f=1},
  [701]={t="迅猛龙的狡诈",d="只要借助一些特别的物品，我就能创造出一件注入了迅猛龙的狡诈力量的东西！这样就应该能让戈穆尔了解到我们新的能量，并重新找回潜藏着的勇士的力量！；我需要迅猛龙的心脏来完成这件物品和法书。",o="从高地猎兽龙身上获取12颗迅猛龙的心脏，把它们交给托尔甘。",p=675,r={{i=4513,n="迅猛龙的心脏",c=12}}},
  [702]={t="迅猛龙的狡诈",d="拿着这颗宝珠，用它的能量来给戈穆尔灌入迅猛龙力量的精髓。这一定会让他的精神备受鼓舞，并给予他新的生活目标。当他恢复正常之后，我们就可以向他说明部落现在的状况，在我们永无止境的战斗中，这位伟大的战士也将帮上大忙。",o="把托尔甘的宝珠交给阿拉希高地落锤镇的戈穆尔。",p=701,r={{i=4528,n="托尔甘的宝珠",c=1}}},
  [704]={t="阿戈莫德的命运",d="阿戈莫德送来的最后一份报告让我感到十分困惑，现在他死了，我就更难受了！他提到挖掘队在奥达曼附近的挖掘场找到了一些“远古的石罐”。我担心是他找到的罐子影响了穴居人，就像这里发现的小石像一样。；我要你去找到那些罐子，把它们拿回来以供研究。到奥达曼挖掘场去收集那些罐子吧，完成之后再回到我这里来。",o="收集4个雕纹石罐，把它们交给洛克莫丹的勘察员基恩萨·铁环。",p=739,r={{i=4610,n="雕纹石罐",c=4}},f=1},
  [705]={t="潜水采珍珠",d="荒芜之地是一个无比荒凉的地方，是凶残的捕食者和食腐动物的乐园。这里的一切都令人感到恐慌，尤其是对于我这样的小个子地精来说。为了生存，我不得不机灵些！；我知道闪光弹的制作方法，也常用它来吓走野兽。不过，作为原料之一的蓝珍珠粉快要用完了。你能不能帮我找些蓝珍珠回来？当然我会给你足够的报酬。；呵呵，这个东西并不是那么好找的，恐怕你得走不少的路了。我所需要的蓝珍珠可以在暗礁海的牡蛎身上找到。；对，就是位于荆棘谷的那个暗礁海。",o="收集9枚蓝珍珠，把它们交给荒芜之地的里格弗兹。",r={{i=4611,n="蓝珍珠",c=9}},w={{i=4086,n="闪光步枪",c=1},{i=5248,n="闪烁魔杖",c=1}}},
  [709]={t="化解灾难",d="天哪……天哪！厄运就要降临了。它已经朝我而来了！厄运就要降临了！；不，我不能说……不能说出他们的名字，否则会被他们听到的！但是，如果我们……如果我们对他们有更多了解的话……也许我们就可以知道如何击败他们！；也许……；到奥达曼去。不！我说过！你必须找到……找到雷乌纳石板……对，找到它！别让我再提到那个名字！；它深藏在那里，就在一个古代的箱子里……这个箱子甚至比矮人族群的年代还要久远……",o="把雷乌纳石板带给迷失者塞尔杜林。",r={{i=4631,n="雷乌纳石板",c=1}}},
  [710]={t="研究石元素",d="在荒芜之地，我停下了所有手头的事情来专注于我的最新项目：元素禁锢镣铐。；这些镣铐一旦完成，就可以让法师们在更广的范围内召集更加强大的元素生物。首先，我需要些小石头碎块，来检验我最新的攻击性咒语和小发明。；你可以从西面那里的次级石元素身上收集到这些碎片，能给我弄一些来吗？",o="收集10块小石头碎块，把它们交给荒芜之地的鲁特维尔·沃拉图斯。",r={{i=4626,n="小石头碎块",c=10}}},
  [711]={t="研究石元素",d="你，你的能力超过了我所有学徒的总和。；我所需的下一个部分需要花些功夫。只要你稍加留心，就能在石元素身上找到一些大石片。他们的身体更加庞大，因而会有足够大的碎片来供我试验。你可以在西边远一点的地方或者东南方的山地边缘找到它们。；不用太着急，测试你带来的小石头碎块还需要花些时间。",o="收集3块大石片，把它们交给荒芜之地的鲁特维尔·沃拉图斯。",p=710,r={{i=4627,n="大石片",c=3}}},
  [712]={t="研究石元素",d="你，我还需要从荒芜之地的元素生物身上弄一些东西：巨型石元素身上的护腕。据我估测，那些护腕完全可以检验出我的镣铐所具有的力量。；我的占卜显示，在西南边有一批巨型石元素。我想起来了，那附近好像还有一些食人魔。；给我带5个护腕来，我想5个就足够了。阿布总是放错我的试剂和实验品，这方面它的名声可不太好。",o="收集5个石缚护腕，把它们交给荒芜之地的鲁特维尔·沃拉图斯。",p=711,r={{i=4628,n="石缚护腕",c=5}}},
  [713]={t="至关重要的冷却剂",d="让我来告诉你些有关冰霜之油的事情吧：没有别的什么东西能够像它一样防止发动机或者齿轮过热。；它的冷却性能和润滑效果无与伦比。不仅如此，它还有助于保存附着在魔法物品上的魔力。；我需要一小瓶冰霜之油以加强镣铐的魔力，好让它们足够强大，不然我可没法阻止那些被召唤来的“朋友们”对我们大开杀戒。；我在奥特兰克有一个名叫布洛金的地精朋友，他能教你制取冰霜之油的方法。",o="找到冰霜之油，把它交给荒芜之地的鲁特维尔·沃拉图斯。",r={{i=3829,n="冰霜之油",c=1}}},
  [714]={t="发条式什么什么仪",d="你，你所做的一切都是超一流的。；<鲁特维尔的注意力显然从工作中移开了>；如果我们曾在卡拉诺斯见过，你随时都可以来申请工作。；哎呦！快抓住……对，那个。谢谢。；我现在还需要一件东西。虽然是件小东西，但是也非常关键的东西，它就是精密的发条式同步协调陀螺仪。；如果你能帮我找一个的话，我就能完成工作啦。",o="给荒芜之地的鲁特维尔·沃拉图斯带去一个发条式同步协调陀螺仪。",p=713,r={{i=4389,n="发条式同步协调陀螺仪",c=1}}},
  [716]={t="有备无患",d="我知道鲁特维尔疯狂起来会有多么危险，你最好让我给你制作一些装备以防万一。也许它能保护你免受鲁特维尔新发明的折磨。；我一直都在研究那些你给他找来的石头，所以我想我能造出一些不错的护腕来供你使用。嗯，它们当然都是附有魔法的。；我只需要一些铁匠打造的青铜花纹护腕就可以帮你造出附魔的护腕了。",o="给荒芜之地的卢希恩·枪穗带去一些青铜花纹护腕。",p=712,r={{i=2868,n="青铜花纹护腕",c=1}}},
  [717]={t="大地的震颤",d="显然，我们不能保证黑龙布莱克拉什和赫玛图斯仍能被囚禁在莱瑟罗峡谷里。大批黑龙盘踞在那里的现状以及食人魔试图偷走大地印章的事实说明后面将会有更可怕的事情发生。；黑龙的监狱由三块符石维持着，只有使用大地印章才能得到它们，而那些符石就是打破封印的关键。；$n……我们要确保那些黑龙的梦想永远无法成真。",o="用大地印章激活钻石柱、玛瑙石柱和紫水晶石柱并拿到三颗符石。；把符石放在大地封印上，释放黑龙布莱克拉什和赫玛图斯。；杀了这两条黑龙，把布莱克拉什的锁链、赫玛图斯的锁链和大地印章交给加瑞克。",p=732,r={{i=4615,n="布莱克拉什的锁链",c=1},{i=4645,n="赫玛图斯的锁链",c=1},{i=4640,n="大地印章",c=1}},w={{i=11193,n="火风胸甲",c=1},{i=11194,n="棱鳞锁甲",c=1},{i=11195,n="战铸胸甲",c=1},{i=11196,n="灵爆勋章",c=1}},f=1},
  [718]={t="饥肠辘辘",d="在匆忙撤出奥达曼挖掘场的途中，我们不得不丢弃了很多补给物资，那些柯什营地里的食人魔像兀鹫看见了腐烂的尸体一样疯狂地掠夺我们扔掉的物资，呃，那些家伙闻起来也和晒了好几天的尸体没什么区别……；不管怎么说，他们抢走了我们装着武器的马车，而且现在……现在的状况实在是只能用窘迫两个字来形容了——我们现在几乎什么吃的都找不到了。；就连腌菜也要吃光了，你看……能不能帮我们弄点什么吃的来？",o="帮西格鲁·铁斧找回补给箱。",r={{i=4629,n="补给箱",c=1}}},
  [719]={t="矮人的工具",d="你好，$c。千万要小心四周。这里到处都是黑铁矮人，似乎都是属于暗炉部族的。；他们刚刚袭击了我们的挖掘场……杀死了那里几乎所有的人，包括我的老板铁趾格雷兹，只有我侥幸逃了出来。；挖掘场在这里的北面，我想找回我们的一些物资，尤其是我的好运锄。；你能帮帮我吗？如果找不到其它的，至少帮我找回我的锄头吧。",o="找到雷杜尔的好运锄，把它交给铁趾挖掘场南边的勘察员雷杜尔。",r={{i=4616,n="雷杜尔的好运锄",c=1}},f=1},
  [722]={t="铁趾的护符",d="你很勇敢……<咳嗽>……为了我来到奥达曼，$c。；如果你真要帮助我……那么……<咳嗽>……你就必须找到……帮我找到我的护符。；它在……马格雷甘·深影的手里。他就在这附近……肯定在这片废墟上。如果你不能阻止他的话，那枚护符将会引导他……<咳嗽>……找到卷轴。你，就看你的了。；请……拿到那枚护符。；卷轴一旦落入黑铁矮人的手里……一切就都太晚了……",o="找到铁趾的护符，把它交给奥达曼的铁趾。",p=721,r={{i=4635,n="铁趾的护符",c=1}}},
  [723]={t="铁趾的遗愿",d="<铁趾捂着伤口，老半天才缓过劲来，他接着说道>；找到雷杜恩，你……把护符交给他。<猛烈的咳嗽>他……<咳嗽>知道该怎么办。雷杜恩知道我一直在寻找我们种族的起源，他也……<咳嗽>知道阻止暗炉部族是我的使命。不能让他们找到卷轴……<咳嗽>",o="把铁趾的护符交给荒芜之地的勘察员雷杜恩。",p=722,r={{i=4635,n="铁趾的护符",c=1}}},
  [724]={t="铁趾的遗愿",d="好吧……谁知道下一步该做些什么？；史学家卡尼克！没错！；他就在铁炉堡里。我想我们可以从他那里寻求一些帮助。铁趾和他曾经共同在奥达曼挖掘古代神器，估计暗炉矮人已经对他们的底细了如指掌了。；去把铁趾的不幸遭遇告诉卡尼克，然后把护符交给他——他会告诉你该怎么办。",o="把铁趾的护符交给铁炉堡的史学家卡尼克。",p=723,r={{i=4635,n="铁趾的护符",c=1}}},
  [725]={t="亡者的警告",d="你，你赶快去找顾问贝尔格拉姆，把你看到的一切都告诉他，问问他我们下一步该怎么做。这封信会让他了解的消息。；与此同时，我会和铁趾的亡灵交谈，也许他所知道的事情能够帮助我们解决那帮暗炉部族的家伙带来的麻烦。让我们祈祷吧。",o="找到顾问贝尔格拉姆，把便笺交给他。",p=724,r={{i=4622,n="给顾问贝尔格拉姆的密信",c=1}}},
  [727]={t="远赴铁炉堡",d="石板说明了不少问题，但这还不够，远远不够！；有这么一本书，它是雅格因在若干年前写的笔记，上面记载着一些……我想方设法要避开的人……他们在世界各地都珍藏着这本书的复制本。而他们中最有学问的人也一直在研究它，因为它包含着极其丰富的知识……可以让我们免遭灾难的知识！；到铁炉堡去找葛利·硬骨，把徽章拿给他看看，他就会相信你是他们中的一员。向他要到雅格因的笔记……然后马上把它交给我！",o="把战锤印章交给铁炉堡的葛利·硬骨。",p=709,r={{i=4648,n="战锤徽章",c=1}}},
  [728]={t="远赴幽暗城",d="石板说明了不少问题，但这还不够，远远不够！；有这么一本书，它是雅格因在若干年前写的笔记，上面记载着一些……我想方设法要避开的人……他们在世界各地都珍藏着这本书的复制本。而他们中最有学问的人也一直在研究它，因为它包含着极其丰富的知识……可以让我们免遭灾难的知识！；到幽暗城去找看守者贝尔杜加，把徽章拿给他看看，他就会相信你是他们中的一员。向他要到雅格因的笔记……然后马上把它交给我！",o="把战锤印章交给幽暗城的看守者贝尔杜加。",p=709,r={{i=4648,n="战锤徽章",c=1}}},
  [731]={t="健忘的勘察员",d="好吧，那么，霍莉……哦，不对，你不是霍莉。霍莉去哪儿啦？；不说这个了，那不是我们要讨论的话题。我们必须找到那把石刷……我是说神秘的化石！我们必须找到化石。达纳苏斯的探险者协会希望能看到我的工作进展情况。；如果你准备好了，就和我说一声，我们去寻找那把刷子……我是说化石！我们要找到一些能让协会满意的东西。；你准备好了吗？",o="在勘察员雷姆塔维尔搜寻神秘化石的时候保护他，然后回到奥伯丁的考古学家霍莉那里。",p=729},
  [732]={t="大地的震颤",d="我听西格鲁说，你在过去几天帮了他的大忙。现在我也需要你的帮助。我的主人，肯瑞托的大法师克拉苏斯派我来结束莱瑟罗峡谷的混乱局面。；我不能透露这次任务的确切性质以及我要完成的使命，但是这个任务真的非常重要。；有一伙四处游荡的食人魔偷走了一件名叫大地印章的东西，我必须要把它拿回来。如果你能帮我找到它，我就让你知道更多的消息。",o="帮加瑞克取回大地印章。",p=718,r={{i=4640,n="大地印章",c=1}}},
  [733]={t="搜集行动",d="如果不能弄到一些物资来建构防御工事和其它的必要设施，我们在这里的处境就会非常糟糕。我发现这个地区的食人魔居然有许多金属碎片，也许传说在荒芜之地有攻城坦克失踪的事情并非杜撰……；无论如何，勘察员对我们营地的状况非常担忧，所以我要尽早开工。；食人魔的主营地就在火山洞穴，从这里往西一直走就能找到。",o="帮西格鲁收集7块金属碎片。",p=718,r={{i=4630,n="金属废料",c=7}},w={{i=4652,n="萨尔巴克之盾",c=1},{i=4653,n="铁踵之靴",c=1}},f=1},
  [737]={t="禁断的知识",d="$n，我这里有你想要的笔记，我想不需要我再提醒你要保管好它了吧？特别是绝对不要让它落入敌人之手。；这本书里记录了很多真相……；……可以毁灭你的真相。",o="把雅格因的笔记交给塞尔杜林。",r={{i=4647,n="雅格因的笔记",c=1}}},
  [738]={t="Find Agmond",o="Find Agmond.",p=707,f=1},
  [739]={t="莫达洛克",d="阿戈莫德留下的足迹表明他是从西边走过来的。从沙石上的斑斑血迹不难看出，矮人阿戈莫德爬行了好一段距离。；爬到这里的时候，他终于被死神带走了。；经过仔细显示，你在旁边的沙石中发现了几个潦草写下的字迹：“莫达洛克”。；字迹就在阿戈莫德的手边。",o="干掉杀害阿戈莫德的凶手：莫达洛克。；顺便杀掉12个石窟断骨者。；然后向洛克莫丹的勘察员基恩萨·铁环报告。",p=738,f=1},
  [741]={t="健忘的勘察员",d="勘察员雷姆塔维尔要把神秘的化石送给达纳苏斯的探险者协会？可是我不太想把他一个人留在这里。；给你，$n，把这块神秘的化石交给达纳苏斯的首席考古学家杜瑟·灰须。",o="把神秘的化石交给达纳苏斯的首席考古学家杜瑟·灰须。",p=731,r={{i=4654,n="神秘的化石",c=1}},w={{i=5629,n="锤拳手套",c=1},{i=5630,n="生毡手套",c=1},{i=11936,n="古物猎手腰带",c=1}},f=1},
  [744]={t="准备典礼",d="你，我的兄弟很快就要去面见血蹄酋长了，我要为他做一个头饰，这对我来说是一种荣耀。；在我处理这些皮革的时候，你能不能帮我一个忙？我没有时间去收集足够的羽毛，不知道你能否帮助我去收集一些呢？；你应该可以在雷霆崖北面和西北面的鹰身人身上找到尺寸合适的羽毛。我需要6片碧蓝色的和6片古铜色的羽毛来完成我的头饰。",o="收集6根碧蓝色的羽毛和6根古铜色的羽毛，把它们交给雷霆崖的伊恩·鹰爪。",r={{i=4752,n="碧蓝色的羽毛",c=6},{i=4753,n="古铜色的羽毛",c=6}},w={{i=4968,n="紧缚皮甲",c=1},{i=4967,n="部落战士之盾",c=1}},f=2},
  [746]={t="矮人的挖掘场",d="西北部有些矮人正在准备修建一座挖掘场。他们认为地下埋藏着某些秘密，事实也的确如此，不过挖掘和污染大地并不是获得这些秘密的正确途径。；收集矮人的挖掘工具，把它们全都毁掉，然后把这些被损坏的工具带给我。；要毁掉这些工具的话，你必须得找到一块铁砧才行。在雷霆崖就有一处铁匠铺，不过任何铁砧——包括矮人营地里的——都可以用来毁掉工具。",o="收集5个勘察员的锄头。；在铁匠铺砸碎这些勘察员的锄头。；把5件损坏的工具交给血蹄村的贝恩·血蹄。",r={{i=4703,n="损坏的工具",c=5}},w={{i=4969,n="固化护腕",c=1},{i=4970,n="粗糙的科多护腿",c=1}},f=2},
  [747]={t="开始狩猎",d="欢迎来到纳拉其营地，$n。你来到这里的消息很快就传遍了部族。或许很快有一天你会被迎去雷霆崖上的大城市里，但首先，你必须先向我们证明你的能力。；我们这些生活在红云台地上的牛头人无疑对自己优秀的狩猎技术最为自豪，当然，牛头人只为生存需要和竞技而狩猎。我们库存的肉已经不多了，另外我们还需要羽毛来做衣服。现在去猎杀附近的平原陆行鸟来给村庄提供补给吧，同时你也可以借此证明自己的能力。",o="纳拉其营地的格鲁尔·鹰风要求你带给他7片平原陆行鸟的羽毛和7块平原陆行鸟肉。",r={{i=4739,n="平原陆行鸟肉",c=7},{i=4740,n="平原陆行鸟的羽毛",c=7}},w={{i=4954,n="游牧民腰带",c=1},{i=4910,n="彩色链甲手套",c=1}},f=2},
  [748]={t="毒水",d="那些地精和他们的爪牙污染了我们神圣的水井！我们必须制止他们！；要想净化所有的水井，我得先制造出相应的净化图腾，然后你把图腾拿到水井那儿去完成净化的仪式。；首先，我们给冰蹄之井制作一个净化图腾，这需要大地的帮助。去猎捕一些草原狼和成年平原陆行鸟，把它们的爪子带回来给我，它们就在西南方活动。",o="收集6只草原狼的爪子和4只平原陆行鸟的爪子，把它们交给血蹄村的穆尔·雷角。",r={{i=4758,n="草原狼的爪子",c=6},{i=4759,n="平原陆行鸟的爪子",c=4}}},
  [750]={t="继续狩猎",d="善于狩猎的牛头人从不仅仅将他的猎物看作战利品，这些生活在平原上的野兽对我们的生存有着极为重要的意义。如果你能带回一些珍贵的山狮皮的话，就会令部族里的长老们对你刮目相看。你可以在南边的山区找到它们。；我们的孩子需要衣服，部族里的帐篷也需要维修了。",o="纳拉其营地的格鲁尔·鹰风要求你带给他10张山狮皮。",p=747,r={{i=4742,n="山狮皮",c=10}},w={{i=4908,n="游牧民护腕",c=1},{i=4913,n="彩色链甲腰带",c=1}},f=2},
  [751]={t="被破坏的货车",d="撬开盖子之后，你发现了堆得满满的矿石，这又一次证明了风险投资公司确实在莫高雷地区有采矿活动。在矿石的最上面有一捆文件。；你可以依稀听见东部丘陵的顶部传来丁丁当当的声音，还可以看见从一大堆篝火上升起的浓烟。",o="把风险投资公司文件交给血蹄村附近的摩林·云行者。",p=749,r={{i=4834,n="风险投资公司文件",c=1}}},
  [753]={t="一件琐事",d="我这一生也算是经历了不少磨难，走了不少路，现在我这一把老骨头也没什么力气啦。我仍然在为部族尽力，但有些时候，我还真感觉有些力不从心。；不过，你这$c似乎是正想找点什么事情做做呀。正好，让我来看看你的体力如何吧。把水井旁的这个水罐交给我儿子，他就在纳拉其营地里。；记住，即使是最琐碎的小事，只要你做得够好，也能获得长老们的首肯。",o="在井边拿一只水罐。；把它带给纳拉其营地里的鹰风酋长。",p=752,r={{i=4755,n="水罐",c=1}}},
  [754]={t="净化冰蹄之井",d="我已经做好了可以净化冰蹄之井的图腾。现在你就把它拿到那儿去完成净化仪式。冰蹄之井就在东南边，有许多地精把守着那里！；这不是个简单的任务，不过如果我们想要重新使用那里的水，就必须得这么做。；祝你好运，你。",o="用冰蹄之井净化图腾为冰蹄之井完成净化，然后回来见穆尔·雷角。",p=748},
  [756]={t="雷角图腾",d="要制作雷角之井净化图腾，你必须先去收集莫高雷平原上的肉食动物的爪子。去捕猎草原捕食者和平原狮，然后把它们的爪子带回来见我。；它们就在这里的东边和西边活动。",o="收集6个草原捕食者的爪子和6个平原狮的爪子，把它们带给穆尔·雷角。",p=754,r={{i=4801,n="草原捕食者的爪子",c=6},{i=4802,n="平原狮的爪子",c=6}}},
  [757]={t="力量仪祭",d="大地之母仪祭对于每一个想要在雷霆崖得到尊重的年轻牛头人来说都是非常重要的。；但在那之前，你必须先通过力量仪祭的试炼。在这个试炼中，你必须通过杀死部族的敌人来证明你的勇猛。；生活在东边的刺刃峡谷中的刺背野猪人侵占了我们部族不少的土地，他们偷袭我们的狩猎小队，还在晚上到村子里来偷东西。；杀死他们，展示出你的英勇无畏吧。拿着它们的腰带去见纳拉其营地的酋长，他将证明你通过了试炼。",o="杀掉刺刃峡谷的刺背野猪人并带回8条刺背腰带，把它们交给纳拉其营地的鹰风酋长。",p=755,r={{i=4770,n="刺背腰带",c=12}},w={{i=1382,n="石质钉锤",c=1},{i=1383,n="石质轻斧",c=1},{i=2137,n="切肉刀",c=1},{i=5776,n="长者之杖",c=1},{i=5777,n="勇士之斧",c=1}},f=2},
  [758]={t="Thunderhorn Cleansing",o="Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull.",p=756,f=2},
  [759]={t="蛮鬃图腾",d="还剩下一口井需要净化，它是以蛮鬃部族的名字命名的。要想净化这口井，你必须从大地上寻找一种凶猛的肉食动物的牙齿，那就是草原狼前锋的牙齿。去北边寻找草原狼前锋，拿到我要的东西之后再回来。；这些草原狼前锋经常在雷霆崖的山脚下游荡。",o="收集8颗草原狼前锋的牙齿，把它们交给血蹄村的穆尔·雷角。",p=758,r={{i=4803,n="草原狼前锋的牙齿",c=8}}},
  [760]={t="Wildmane Cleansing",o="Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.",p=759,w={{i=3443,n="典礼轻斧",c=1},{i=4961,n="守梦法杖",c=1}},f=2},
  [762]={t="邪恶的使者",d="拉格纳罗斯派因弗努斯大使到苦痛堡垒去监督暗炉矮人在奥达曼挖掘神器的工作。；我们的同胞已经遭受了惨重的伤亡，然而这样的情况仍然在继续。我不愿去猜测他们会找到多少强大的神器并用它们来对付铁炉堡。；我们的目的很简单，$c。回到荒芜之地去，干掉因弗努斯大使。在除掉了这个威胁之后，把你完成任务的证据交给顾问贝尔格拉姆。；现在马上出发吧。",o="杀死苦痛堡垒中的因弗努斯大使，把证明他已死亡的信物交给铁炉堡的顾问贝尔格拉姆。",p=726,r={{i=4621,n="因弗努斯大使的护腕",c=1}},f=1},
  [763]={t="大地之母仪祭",d="要想继续大地之母仪式，你必须先通过两个小试炼。现在也正好是你去积累积累经验的时候了，$n。；到血蹄村去找那里的酋长，凯恩之子贝恩·血蹄吧。你可以在那儿继续你的冒险历程并得到雷霆崖的长老们的承认。；把这个图腾带给贝恩。他会读懂我刻在上面的符号，并帮助你继续修行。；顺着这条从纳拉其营地通向外面的路快点出发吧，千万别迷路了。",o="顺着离开纳拉其营地的路将鹰风图腾带给血蹄村的贝恩·血蹄。",p=757,r={{i=4783,n="鹰风图腾",c=1}}},
  [765]={t="菲兹普罗克主管",d="根据你从箱子里拿来的文件可以看出，风险投资公司已经制定了很多把我们从这儿赶走的计划，然后他们就能随心所欲地掠夺我们的土地了。；他们为了利润居然可以堕落到这种程度，这简直让我感到厌恶和惊骇。我们要除掉这个阴谋的策划者，他就是菲兹普罗克主管。你可以在被破坏的货车以东的风险投资公司矿洞里找到他，把他的笔记板带给我，让我们看看有没有什么有价值的东西。",o="杀掉菲兹普罗克主管，把他的笔记板带给血蹄村的摩林·云行者。",p=751,r={{i=4819,n="菲兹普罗克的笔记板",c=1}},w={{i=4974,n="简易小刀",c=1},{i=4964,n="地精打击者",c=1}},f=2},
  [766]={t="马兹拉纳其",d="我祖父曾讲述过他和一只叫马兹拉纳其的陆行鸟战斗的故事，说起过它那邪恶的红眼睛，剃刀般锋利的爪子，只要被它咬一口，你就会身中剧毒。；在我穿越平原的时候，正巧遭遇了它，肩膀被它咬了一口。它比我祖父所说的还可怕！我需要一些东西来帮我解毒：一颗狼心，狮子的腿骨，平原陆行鸟的鳞片和猛鹫的胃。；快点，我快要不行了。",o="收集草原狼的心脏、平原狮的腿骨、平原陆行鸟的鳞片和猛鹫的胃各一份，把它们交给血蹄村的茂尔·祈雨。",r={{i=4804,n="草原狼的心脏",c=1},{i=4805,n="平原狮的腿骨",c=1},{i=4806,n="平原陆行鸟的鳞片",c=1},{i=4807,n="猛鹫的胃",c=1}},w={{i=4972,n="峭壁行者长靴",c=1},{i=4973,n="平原猎手护腕",c=1}},f=2},
  [768]={t="收集皮革",d="你好，年轻的$r。我从你的眼中看到了你重回原野捕猎的渴望。希望你能为你的部族带来荣耀！；我擅于利用各种兽皮来为雷霆崖的居民制作护甲和衣物。；如果你能帮我搞到一些兽皮的话，那我就可以用它们来为你制作一些你需要的东西。",o="收集12块轻皮，把它们交给雷霆崖的维尔伦·陆行者。",r={{i=2318,n="轻皮",c=12}},w={{i=5936,n="兽皮腰带",c=1},{i=4962,n="双层手套",c=1}},f=2},
  [770]={t="The Demon Scarred Cloak",o="Find someone who knows of Ghost Howl.",w={{i=4971,n="斯考恩的战锤",c=1},{i=3079,n="斯考恩的火枪",c=1}},f=2},
  [771]={t="幻象仪祭",d="要想通过幻象仪祭，你必须先找到制作先知之水的试剂。；我需要一些水井石，你可以在莫高雷一带的水井附近找到它们。另外，你还得在这周围的大树下面找到一些琥珀颗粒。；这两种东西都具有强大的元素力量，把它们结合起来，用部族之火点燃之后，你可以看到一个幻象。追随它，它就会引领你进入这个神圣使命的下一个阶段。",o="收集2块水井石和2个琥珀颗粒，把它们带给血蹄村的扎尔曼·双月。",p=767,r={{i=4808,n="水井石",c=2},{i=4809,n="琥珀颗粒",c=2}}},
  [772]={t="Rite of Vision",o="Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.",p=771,w={{i=4906,n="雨靴",c=1},{i=4958,n="日炎披风",c=1}},f=2},
  [776]={t="大地之母仪祭",d="你已经通过了大地之母仪祭，在雷霆崖赢得了你自己的一席之地。；不过要维持你现在获得的荣誉，你还必须不断证明你自己的价值。；我们生来就是猎手，$n。在莫高雷城下有一只非常强大的科多兽，我们称它为阿兰其亚。把它的角带来，向我证明你追踪和捕猎的能力。",o="雷霆崖的凯恩·血蹄要你将阿兰其亚的角带给他。",p=775,r={{i=4841,n="阿兰其亚的角",c=1}},f=2},
  [777]={t="不祥的感觉",d="好吧，拿去吧。；我现在要去找个掩体……；你要不要一起来？",o="把5号齿轮交给鲁特维尔·沃拉图斯。",p=734,r={{i=4846,n="5号齿轮",c=1}}},
  [778]={t="不祥的感觉",d="哈哈！完成啦！镣铐完成啦！；记住这个时刻，卢希恩,记住这个时刻，阿布！你准备好了吗？你将亲眼看见炼金术、工程学和魔法的完美结合。；我将召集一个强大的元素生物。今天，对于我们来说，是具有里程碑意义的一天！",o="击败法姆雷托守护者，并将鲁特维尔的元素禁锢镣铐交还给鲁特维尔。",p=777,r={{i=4847,n="鲁特维尔的元素禁锢镣铐",c=1}}},
  [780]={t="斗猪",d="生活在东边的刺刃峡谷中的斗猪已经侵占了我们部族的狩猎场。正在与我们交战的刺背野猪人把这些野猪训练成了凶暴而富有攻击性的生物。；去把这些可恶的家伙杀掉，再带些猪头和肋排回来，我们可以炖肉给孩子们吃。",o="纳拉其营地的格鲁尔·鹰风要求你去干掉斗猪，并带给他8块斗猪头和8块斗猪肋排。",p=750,r={{i=4848,n="斗猪头",c=8},{i=4849,n="斗猪肋排",c=8}},f=2},
  [781]={t="纳拉其营地的危机",d="在仔细查看了地图之后，你意识到刺背野猪人的酋长正计划着对纳拉其营地展开进一步攻击。；鹰风酋长必须马上得知这个消息。",o="将刺背野猪人的进攻计划交给纳拉其营地的鹰风酋长。",r={{i=4850,n="刺背进攻计划",c=1}},f=2},
  [782]={t="破碎的联盟",d="在第二次兽人战争期间，部落与死亡之翼之间曾有过盟约，我们也因此得知死亡之翼的两个副手——黑龙布莱克拉什和赫玛图斯——现在正被囚禁在莱瑟罗峡谷里。；如今我们要让堕落的昔日盟友们“安静”一点，我们要恢复部落的荣耀。我们雇佣了索格伦和他的食人魔雇佣兵团帮我们夺回大地印章，也就是那把可以打开黑龙监狱的钥匙。；然而，索格伦背叛了我们，他打败了我们，将大地印章占为己有。",o="杀掉索格伦，把大地印章交给卡加斯的高恩。",r={{i=4640,n="大地印章",c=1}}},
  [784]={t="背信弃义的人类",d="库尔提拉斯的人类曾在普罗德摩尔将军的率领下大举进攻杜隆塔尔，彻底破坏了在共同抵抗阿克蒙德和他的恶魔大军时由酋长和吉安娜·普罗德摩尔定下的互不侵犯协议。；我们击退了人类的进攻，并攻下了提拉加德城堡。但最近，由本尼迪克上尉率领的后备军又重新占领了提拉加德城堡，对我们的家园构成了新的威胁，这些人类从不遵守外交协议。；到南方的提拉加德城堡去消灭那些人类侵略者，证明你的勇气和荣誉。",o="杀死10个库尔提拉斯水手和8个库尔提拉斯水兵，再把本尼迪克上尉干掉，然后回剃刀岭向加索克复命。"},
  [786]={t="科卡尔半人马的进攻",d="小声点，$c。科卡尔半人马就在西边科卡尔峭壁的山脊上。；昨天晚上，我潜入了他们的村庄，发现这些肮脏的野兽准备同时向杜隆塔尔的巨魔和兽人发动三波攻势。；我们决不能让他们的入侵计划得逞！你可以召集一些兵力，潜入科卡尔峭壁并粉碎他们的进攻计划。；他们已经把进攻计划分别交给了三个首领，准备由他们率领三股部队同时行动。",o="在森金村外面的拉尔·猎齿要求你粉碎科卡尔峭壁内的三份进攻计划。",w={{i=4933,n="老战士披风",c=1},{i=6062,n="粗绳护腕",c=1}},f=2},
  [788]={t="小试身手",d="第一项任务将在力量方面对你进行考验。我本来可以把你派去贫瘠之地猎杀科多兽，不过呢，照实说，你活着比死了对我们来说更有用。；我相信你更合适和那些杂斑野猪斗一斗，往北边走就可以找到它们。",o="杀掉8只杂斑野猪，然后向大兽穴里的高内克报告。",w={{i=4915,n="软毛靴",c=1},{i=4914,n="磨损的皮手套",c=1}},f=2},
  [789]={t="工蝎的尾巴",d="无论是强大的战士还是笨拙的新手，都有可能会倒在蝎尾上的毒针之下。在这里的西北方有大量蝎子在活动，给我带8条蝎尾回来，以此来证明你的战斗能力吧。；事实上，它们尾巴上的毒针正是制作解毒剂的重要材料，解毒剂便是从毒针中提取的。我们需要长期备有大量的解毒剂，以防止像你这样的新手被蝎毒所害……；但我肯定你是不会需要这种玩意的，对吧？",o="给大兽穴中的高内克带回8根工蝎的尾巴。",p=788,r={{i=4862,n="工蝎的尾巴",c=10}},w={{i=4919,n="软毛腰带",c=1},{i=4920,n="磨损的斗篷",c=1}},f=2},
  [790]={t="萨科斯",d="玩家！我差点就神不知鬼不觉地死在这鬼地方了！我在谷里捕猎蝎子的时候，突然看到一只看上去特别凶恶的蝎子。当时我就决定以它为猎物，打算在它那硕大的钳子钳住我的腿以前，先重重地给它来上那么一下子。；但我忘记了它还有根毒刺，毒刺猛扎了下来，一下子就刺进我的胸口。拜托，你一定得替我报仇！只有这样才能留存我的名誉！我是在南边的高地上碰上它的。",o="杀死萨科斯并将它的爪子带回去交给哈纳祖。",r={{i=4905,n="萨科斯的爪子",c=1}}},
  [792]={t="邪灵劣魔",d="我相信你会在试炼谷学到很多东西，年轻的$c。；我本是被派到这处谷地里来指引和教育你们的，但我却在这里发现了一些不洁之物……；一群自称为火刃氏族的兽人潜入了试炼谷，他们躲进了东北方的一处洞穴里，而他们的邪灵劣魔则肆虐着周边的一大片地区。；作为你对抗火刃氏族的第一个任务，我命令你消灭这些劣魔。尽可能地多杀一些，如果杀完了它们之后你还活着的话，就回来向我复命。",o="杀死8只邪灵劣魔，然后向大兽穴外的祖雷萨复命。",w={{i=4924,n="粗糙的木棒",c=1},{i=4925,n="粗糙的手刀",c=1},{i=4923,n="粗糙的短柄斧",c=1},{i=5778,n="粗糙的手杖",c=1}},f=2},
  [793]={t="破碎的联盟",d="大地印章由三块符石控制，它们分别被放置在莱瑟罗峡谷的钻石柱、玛瑙石柱和紫水晶石柱中。用大地印章就可以取下符石并打开大地封印。；当心点，$n，黑龙布莱克拉什和赫玛图斯是很难对付的。杀掉它们，把它们身上的锁链交给我。",o="用大地印章激活钻石柱、玛瑙石柱和紫水晶石柱并拿到三颗符石。；把符石放在大地封印上，释放黑龙布莱克拉什和赫玛图斯。；杀了这两条黑龙，把黑龙布莱克拉什的锁链、赫玛图斯的锁链和大地印章交给高恩。",p=782,r={{i=4615,n="布莱克拉什的锁链",c=1},{i=4645,n="赫玛图斯的锁链",c=1},{i=4640,n="大地印章",c=1}},w={{i=11193,n="火风胸甲",c=1},{i=11194,n="棱鳞锁甲",c=1},{i=11195,n="战铸胸甲",c=1},{i=11196,n="灵爆勋章",c=1}},f=2},
  [794]={t="火刃奖章",d="我通过预言术发现在火刃集会所的深处藏有一件蕴涵着强大力量的物品，它被一些猛兽和黑暗的魔法守卫着。；那件物品叫作火刃奖章，你的下一个任务就是找到它，把它从集会所里偷出来。；不过你可得小心，因为奖章的属主可能是一个火刃部落中的强者，他也许要比你以前对付过的那些家伙要强上许多倍。；现在就出发吧，你，那个洞穴就在这里的西北方。",o="给大兽穴外的祖雷萨带回火刃奖章。",r={{i=4859,n="火刃奖章",c=1}},w={{i=4921,n="灰尘覆盖的护腿",c=1},{i=4922,n="粗糙的链甲外衣",c=1},{i=6713,n="破裤子",c=1}},f=2},
  [804]={t="Sarkoth",o="Bring the news of Hana'zua's plight to Gornek at the Den.",p=790,w={{i=4916,n="软毛外衣",c=1},{i=4917,n="磨损的链甲护腿",c=1}},f=2},
  [806]={t="黑暗风暴",d="你，我有个不妙的消息。对火刃氏族的调查表明，杜隆塔尔境内还有不少这个氏族的势力。这是我们绝对不能允许的！在他们站稳脚跟、滋生邪恶之前，我们必须把他们消灭掉。；有个名叫费索·暗雷的地精术士就居住在西北部的雷霆山里，他和他的那群爪牙就在那里制造混乱。；去干掉他，再把他的爪子带回来给我！",o="把费索的爪子带给剃刀岭的奥戈尼尔·魂痕。",p=823,r={{i=4869,n="费索的爪子",c=1}},f=2},
  [812]={t="救命如救火",d="你……你来得真是时候，快救救我……；我在毒尾蝎战斗的时候一不小心被蛰伤了，毒液正在不断侵蚀我的血液。看样子…我最多再撑一个小时就得玩完了，我想请你帮个忙…；奥格瑞玛的考格汉知道怎么做解毒剂，快去找他…你，我…我支持不了多久了……",o="找到毒尾蝎的解毒剂，把它交给杜隆塔尔西北边境的林纳格。",r={{i=4904,n="毒尾蝎解毒剂",c=1}},w={{i=4937,n="带电圆盾",c=1},{i=4929,n="轻便蝎壳护甲",c=1}},f=2},
  [816]={t="丢失的孩子",d="你，请帮帮我吧！我的儿子克鲁恩几天前到西边的怒水河畔捕猎鳄鱼，却一直没有回来，我现在觉得不妙了。；尽管他十分强壮，但他的固执和自尊常常让自己陷入麻烦。我警告过他，鳄鱼是强大而凶猛的动物，可他一听就火了，掉头就走。；如果你找不到他，至少也请给我带来一些关于他的消息，不管是好的还是坏的……就算把怒水河畔每只鳄鱼的肚子剖开也要找到点什么。",o="把关于克鲁恩的消息告诉剃刀岭西北部农场中的米莎·托克伦。",r={{i=4891,n="克鲁恩的护身符",c=1}},f=2},
  [819]={t="老陈的空酒桶",d="张贴在酒桶一角的纸条上写着：“老陈 - ；祝汝精神得提升，祝汝精神永提升。”",o="找到对老陈的空酒桶有所了解的人。",r={{i=4926,n="老陈的空酒桶",c=1}}},
  [821]={t="老陈的空酒桶",d="你想尝尝老陈的雷霆佳酿吗？哈哈，这东西可是很带劲的哦。老陈把酿酒术教给了我师傅，我师傅又传给了我。去帮我找一些酿酒的材料，然后你就会得到物有所值的回报！；帮我带5颗草原狮的獠牙、5个平原陆行鸟的肾脏和1根雷霆蜥蜴的角回来，然后我就可以酿酒了。；这些东西都可以在贫瘠之地找到。",o="收集5颗草原狮的獠牙、5个平原陆行鸟的肾脏和1根雷霆蜥蜴的角，把它们交给棘齿城的酿酒师德罗恩。",p=819,r={{i=4893,n="草原狮的獠牙",c=5},{i=4894,n="平原陆行鸟的肾脏",c=5},{i=4895,n="雷霆蜥蜴的角",c=1}}},
  [824]={t="大地之环的耶努萨克雷",d="大地之环是个萨满祭司的团体，他们致力于研究和保护自然界中的元素。他们忘掉的关于上古之神的知识可能比大多数学者知道的还要多。；你很幸运，我认识灰谷的大地之环的成员。到佐拉姆海岸边上的佐拉姆加前哨站去，向耶努萨克雷展示你找到的这个东西。如果有谁对这颗水球的重要性有所了解的话，那么非他莫属了。",o="将被污染的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。",p=1918,r={{i=16408,n="被污染的水球",c=1}},w={{i=16659,n="灵巧腰带",c=1},{i=16660,n="泥潭盾牌",c=1},{i=16661,n="软柳斗篷",c=1}},f=2},
  [825]={t="海底沉船",d="我得到消息说普罗德摩尔舰队的残骸仍在杜隆塔尔的近海，就在提拉加德城堡的东边。；与人类结盟的侏儒是一群粗俗的小东西，但是他们掌握着先进的机械技术。我们必须对任何潜在的敌人都了如指掌，同时我们的族人也可以从这些新知识中受益。；$n，潜到那些沉船中，给我拿来联盟使用的工具。",o="剃刀岭的加索克要你从海岸边的舰队残骸中打捞出3件侏儒的工具。",p=784,r={{i=4863,n="侏儒的工具",c=3}},w={{i=4936,n="踏泥靴",c=1},{i=4928,n="沙漠腕甲",c=1},{i=4935,n="金属束带",c=1}},f=2},
  [826]={t="扎拉赞恩",d="巫医扎拉赞恩就住在东边的回音群岛上，那些岛屿曾经是我们的家园。；扎拉赞恩从那里不断派出他的爪牙来到这边的大陆上，用妖术控制我们的同胞，将他们也变成扎拉赞恩的傀儡。；我们必须阻止他。；打败扎拉赞恩和他的爪牙——那些曾经是我们的朋友和亲人的暗矛巨魔。把扎拉赞恩的徽记给我带回来，作为你已经斩杀了这个恶魔的证明。",o="打败扎拉赞恩。；杀死8个巫毒巨魔和8个妖术巨魔。；把扎拉赞恩的徽记带给加德林大师。",r={{i=4866,n="扎拉赞恩的徽记",c=1}},w={{i=4946,n="轻便长靴",c=1},{i=4940,n="迷雾手套",c=1}},f=2},
  [827]={t="骷髅石",d="你。火刃氏族就躲在奥格瑞玛东部的骷髅石山洞里。他们在洞中进行邪恶的仪式，用灼热项圈去燃烧自己的身体。；我相信他们戴上这些项圈之后便会获得恶魔的力量，不过如果要确定这一点，我还得收集一些项圈来做研究。；到骷髅石去，从那些火刃祭司身上找些灼热项圈给我，让我来揭开他们的秘密。",o="在骷髅石中的火刃祭司身上收集灼热项圈，；然后交给玛高兹。",p=828,r={{i=4871,n="灼热项圈",c=6}},w={{i=4947,n="锯齿匕首",c=1},{i=4939,n="坚固的重剑",c=1},{i=4948,n="刺钉之锤",c=1}},f=2},
  [829]={t="尼尔鲁·火刃",d="你带回来的灼热项圈是充满恶魔力量的强大器物工具。它们的来源恐怕已经不是我这样的萨满祭司所能探究的了。我们必须找个专精于此的术士来研究它们。；把这个项圈带给尼尔鲁·火刃。他是个技艺高超的术士，但他却擅长使用自己所掌握的恶魔力量来对抗恶魔，还声称他对恶魔的研究都是有益于部落的。不管这些话是真是假，如果我们要对付那些信仰恶魔的家伙，就需要他的帮助。；你可以在奥格瑞玛的暗影裂口找到尼尔鲁。",o="给奥格瑞玛的尼尔鲁·火刃带去一个项圈样本。",p=827,r={{i=6658,n="项圈样本",c=1}}},
  [830]={t="将军的命令",d="你打开了陈旧褪色的信封，发现了一份看上去很正式的文件，上面盖着普罗德摩尔将军的徽记。；这封信看上去很重要，剃刀岭的指挥官加索克应该会对它感兴趣。",o="把普罗德摩尔将军的命令带给剃刀岭的加索克。",r={{i=4883,n="普罗德摩尔将军的命令",c=1}}},
  [834]={t="沙漠之风",d="我叫雷兹拉克，是加兹鲁维的手下。他派我来这里跟杜隆塔尔的兽人作生意……除了那些商队以外，一切都进行得很顺利，商队的安全根本没法保证！你知道吗，这给我添了不少麻烦！；上次发出的一批货物——还说肯定能平安送达呢——结果被一票鹰身人从半道上给劫了去……它们好像是从那什么烈风峡谷来的……；反正，拿不到那批货我就死定了！帮帮忙吧……沿着大峡谷向南走，你就会看到直接切入山壁东西两面的沟壑。",o="为奥格瑞玛城外的雷兹拉克取回5个装满货物的袋子。",r={{i=4918,n="装满货物的袋子",c=5}}},
  [835]={t="保卫商路",d="加兹鲁维跟我说过：“雷兹拉克呀，有一件事情你必须铭记，那就是如果你想把事情做好，就得亲力而为。”；我不能让那些商队全都有来无回，所以我得自己解决这rn件事才行。枯水谷在烈风峡谷的东边，那里的鹰身人多到数不胜数，只要把它们全都给做了，那条路就彻底安全了。；当然，加兹鲁维还教过我另一点，那就是“有钱能使磨推鬼”。那么，你愿意帮我的忙吗，$n？",o="为奥格瑞玛附近的雷兹拉克杀掉12个尘风暴徒和8个尘风雷巫。",p=834,w={{i=4932,n="切翼之刃",c=1},{i=4931,n="桃木短弓",c=1},{i=4938,n="斑纹木杖",c=1}}},
  [836]={t="Rescue OOX-09/HL!",o="Escort OOX-09/HL to the shoreline beyond Overlook Cliff, then report to Oglethorpe Obnoticus in Booty Bay.",p=485,w={{i=9645,n="侏儒发明家之靴",c=1},{i=9646,n="侏儒潜水装置",c=1}}},
  [840]={t="部落的新兵",d="嗯，你看上去很强壮。；是这样的，我的好朋友卡加尔正在为贫瘠之地招募新兵。我知道你想为部落做点有用的事，这次你的机会来了。；把这封募兵信交给卡加尔，看看他会不会签字。",o="沿着剃刀岭西部的小路一直前进，过桥之后就可以进入贫瘠之地。；在桥对面的兽人前哨找到卡加尔·战痕，将你的募兵信交给他。",r={{i=4992,n="募兵信",c=1}}},
  [843]={t="加恩的报复",d="我一直在这里孤独地徘徊着。；巴尔莫丹的矮人对我们的领土从来都没有半点尊重。烈性的炸药在地面上炸出了一个又一个深深的钻孔，嘈杂的机器切开了山丘和平原，曾经属于我们部族的美好家园现在成了那些破坏成性的矮人们的领地。；我们曾希望通过外交途径与他们和解，但是一切努力最终都以失败告终。现在是做出决断的时候了。；用武力将这些矮人从巴尔莫丹的挖掘场赶走，把他们的头儿勘察员卡兹戈姆的日记带来交给我。",o="加恩·石塔让你杀死15个巴尔丹挖掘者和5个巴尔丹工头。；把卡兹戈姆的日记交给加恩·石塔。",r={{i=5006,n="卡兹戈姆的日记",c=1}}},
  [844]={t="平原陆行鸟的威胁",d="你的第一个任务是非常简单的。；东边的平原陆行鸟总是对我们的食物补给心怀鬼胎，它们已经成了十字路口的一大祸害。；杀掉那些平原陆行鸟，把它们的鸟喙给我带回来。",o="收集7个陆行鸟的喙，把它们交给十字路口的瑟格拉·黑棘。",r={{i=5087,n="陆行鸟的喙",c=7}}},
  [845]={t="斑马的威胁",d="斑马虽然并非贫瘠之地上最凶猛的野兽，但也比平原陆行鸟强悍了许多。不要担心，我们总有一天会派你去挑战比斑马更强大的敌人，但现在你最好用它们练练手。；去猎杀北边和南边的斑马，并且收集它们的蹄子。完成这个任务之后，也许你就可以去见识见识真正的猛兽了。",o="杀死快步斑马并收集4只斑马蹄，把它们交给十字路口的瑟格拉·黑棘。",p=844,r={{i=5086,n="斑马蹄",c=4}}},
  [846]={t="加恩的报复",d="很显然，矮人们依靠炸药和那些吵闹的机械来进行挖掘，而且不久后他们肯定会再派一个新的工头来接手这里。；我要让这些矮人自食其果。按照这日记上面写着的配方，只要把硝化甘油、木浆和硝酸钠混合起来，就能制造出一种强力的炸药。据我们所知，城堡中的火枪手、战士和军官都拥有这些物资。；为我收集这些物资，我要制造出一种让矮人们永远都不会忘记的炸药！",o="加恩·石塔要你将6瓶硝化甘油、6份木浆和6份硝酸钠交给他。",p=843,r={{i=5017,n="硝化甘油",c=6},{i=5018,n="木浆",c=6},{i=5019,n="硝酸钠",c=6}}},
  [848]={t="菌类孢子",d="贫瘠之地的绿洲里隐藏着一个谜。生命的能量从绿洲之水中涌出，给那些汲取水分的动植物带来了勃勃生机。；与此同时，这种能量也在慢慢地改变这些动植物。；在绿洲附近生长着一种蘑菇，我们这些洛丹伦的药剂师都认为这种蘑菇的孢子中包含有一些特殊的物质，它对我们非常有用。；帮我带一些孢子回来，我们会非常感谢你的。",o="收集4个菌类孢子，把它们交给十字路口的药剂师赫布瑞姆。",r={{i=5012,n="菌类孢子",c=4}}},
  [849]={t="加恩的报复",d="按照卡兹戈姆的日记上所述的方法制造出来的炸药应该不会有问题。；那么，我们开始吧。；首先我有一项特殊的任务要交给你完成。拿上这只爆破筒，去炸掉巴尔莫丹的飞行器。；这个飞行器不仅是巴尔莫丹军事设施的关键部分，也是一架可怕的杀戮机器。更重要的是，它是权力的象征，而它对我们的部族来说则代表着一段耻辱的回忆。；我会为你的成功感到自豪，你也将得到丰厚的奖励。",o="摧毁巴尔莫丹的飞行器，然后向加恩·石塔回复。",p=846,f=2},
  [850]={t="科卡尔首领",d="半人马的问题困扰着牛头人已经很多年了，最近，贫瘠之地的科卡尔半人马开始形成真正的威胁。通常他们散居在这片土地上，不过他们当中已经产生了新的首领，他把一盘散沙的半人马集合在一起。；为了保护我们的家园，这些半人马领袖就必须要除掉。；帮我带回巴拉克·科多班恩的徽记，他在北方的遗忘之池附近驻营。；除掉他，然后再回到我这里。",o="把巴拉克的徽记交给十字路口的雷戈萨·死门。",r={{i=5022,n="科多班恩的战利品",c=1}}},
  [851]={t="狂热的维罗戈",d="有一个被称作狂热的维罗戈的半人马在贫瘠之地四处游荡，通常很难找到他，不过他的营地就在东南方的死水绿洲附近，你应该可以在那里把他给引诱出来。；到死水绿洲附近的半人马营地去，斩杀那里的半人马。虽然这会让你处于很危险的境地，不过如果你能杀死足够多的半人马，他们就会发出警报，之后维罗戈就会现身。；把他的徽记带给我，我要把它和巴拉克·科多班恩的徽记放在一起。",o="把维罗戈的徽记交给十字路口的雷戈萨·死门。",p=850,r={{i=5023,n="维罗戈的徽记",c=1}}},
  [852]={t="赫兹鲁尔·血印",d="赫兹鲁尔·血印是贫瘠之地的科卡尔半人马的首领。他凶猛、残忍，诡计多端。消灭他就可以瓦解半人马部落，从而极大地削弱他们对我们的威胁。；去杀了他。就像对付巴拉克和维罗戈那样，带回赫兹鲁尔的徽记。；他和他的手下驻扎就在西南方的甜水绿洲一带。",o="把赫兹鲁尔的徽记交给十字路口的雷戈萨·死门。",p=851,r={{i=5025,n="赫兹鲁尔的战利品",c=1}},f=2},
  [853]={t="药剂师扎玛",d="我用你给我的孢子制成了药剂。现在我必须把它送给我的同事，药剂师扎玛。如果你愿意帮忙把这个带给她，她会拿一些我们存储下来的炼金术用品奖励你的。；她就在预见之池里，那是一个位于雷霆崖下面的洞穴。通向洞穴的小路非常隐蔽，不过你可以在灵魂高地下面找到这条小路。；快点出发吧，这种药剂的效力只能持续很短的一段时间，在这段时间里必须要送到扎玛那里。",o="在药剂的效力消失之前，把提炼过的孢子交给雷霆崖的药剂师扎玛。",p=848,r={{i=5027,n="提炼过的孢子",c=1}},w={{i=2458,n="初级坚韧药剂",c=4},{i=2457,n="初级敏捷药剂",c=4},{i=2456,n="初级活力药水",c=3},{i=2459,n="迅捷药水",c=2}},f=2},
  [855]={t="半人马护腕",d="在与科卡尔半人马的战斗中，你已经证明了自己。不过，他们仍然是个威胁。这些半人马的首领的死对我们来说是非常好的消息，不过你必须继续削减他们军队的人数。；为此我会交给你一项赏金任务。；到科卡尔半人马的领地去，干掉他们的士兵，收集他们的半人马护腕。当你能带回足够多的护腕的时候，部落会奖赏你的。",o="收集15个半人马护腕，把他们交给十字路口的雷戈萨·死门。",r={{i=5030,n="半人马护腕",c=15}},w={{i=5346,n="兽人战弓",c=1},{i=5344,n="尖角斧",c=1},{i=5345,n="石木锤",c=1}},f=2},
  [858]={t="打火钥匙",d="你该不会是斯布特瓦夫派来的吧？我被困在这儿了。我在不知道需要钥匙才能启动伐木机的情况下就贸然跳了进来。更蠢的是，当另一台伐木机的操作员问我是否一切正常的时候，我居然慌了神！我没有告诉他我手里没钥匙，而只是说机器有些问题。；我们要赶紧离开这里！到起重机上的控制室去，那里的管理员应该有这台伐木机的钥匙。；帮我离开这儿！",o="取得打火钥匙，把它交给维兹克兰克。",r={{i=5050,n="打火钥匙",c=1}}},
  [861]={t="猎人之道",d="我看得出来，你是个渴望探索的$c。我也渴望到处漫游，至少曾经是这样……；漫游，狩猎。狩猎是牛头人最高的荣誉。；如果你真想走猎人这条路的话，梅洛·石蹄可以给你一些指引，他就在雷霆崖的猎人高地上。；要向他证明你的能力和决心，你就必须把莫高雷一带的平原徘徊者的爪子带给他看。平原徘徊者非常凶猛、狡猾——对于一个想要成为猎手的年轻$c来说再合适不过了。",o="收集4只平原徘徊者的爪子，把它们带给雷霆崖的梅洛·石蹄。",r={{i=5203,n="平原徘徊者的爪子",c=4}}},
  [862]={t="掘地鼠炖肉",d="像你样一个$c在贫瘠之地肯定会饿得前心贴后背，你看我，我就已经饿了整整一天了。；我跟你说吧，我可以为你做一道大餐，不过得要先弄一些掘地鼠来。；那些可恶的巴尔莫丹矮人几乎把这里的掘地鼠都给吃光了！你到rn南边的巴尔莫丹去给我带一些掘地鼠回来吧。；如果你连这都搞不定的话，就不要再自称是经验丰富的冒险家了！",o="给十字路口的格拉布弄到8只掘地鼠。",r={{i=5051,n="掘地鼠",c=8}},f=2},
  [863]={t="逃跑",d="我想我要好好学学才行……应该不会很难。就这些按钮，一个操纵杆和两个……对了，你准备好要出发了吗？",o="保护维兹克兰克以及他偷来的地精伐木机返回棘齿城的斯布特瓦夫那里。",p=858,w={{i=5326,n="燃烧之杖",c=1},{i=5327,n="油污工匠短裤",c=1}}},
  [864]={t="向药剂师金格回报",d="“搞定了，现在能量源已经被安全卸载，而你的数据也被完全保留下来了。好了，接下来就只有祝你一路顺风了，希望你的科学实验一切顺利。”；那个地精转身开始继续做加基森水业公司的事情。你小心翼翼地把封好的实验工具包收起来，然后准备把它带回幽暗城。药剂师金格正在那里等着你向他进行回报。",o="把实验工具包带给幽暗城的药剂师金格。",p=654,r={{i=8527,n="封装的野外实验工具包",c=1}},w={{i=9634,n="技艺手套",c=1},{i=9635,n="大药剂师斗篷",c=1},{i=11502,n="学识护肩",c=1}},f=2},
  [865]={t="迅猛龙角",d="贫瘠之地的迅猛龙比其它地区的更加聪明狡猾，我想它们的智慧就来自它们的角！如果是这样的话，我可以将它们的角磨成粉末，制成“智慧饮料”，然后就能卖个大价钱！！！；我想你应该能帮我的忙……从赤鳞镰爪龙身上弄一些完整的迅猛龙角来，它们就栖息在贫瘠之地的南部以及靠近灰谷森林边界的贫瘠之地北部。",o="从赤鳞镰爪龙身上收集5根完整的迅猛龙角，把它们交给棘齿城的米希瑞克斯。",r={{i=5055,n="完整的迅猛龙角",c=5}}},
  [866]={t="根须样本",d="贫瘠之地的草药似乎和其它地方的不大一样。它们的属性几乎相同，不过这里的绿洲之水却令它们发生了一些改变，使它们变得有那么一点点特别了。；我想找出这些草药到底有什么特别之处……然后看看它们有没有利用价值！；如果你精通草药的话，就帮我在贫瘠之地收集一些这种草药的根须样本吧。把这些样本交给我，这样一来，我就能比较一下它们与其它地区的草药之间的差异了。",o="把根须样本交给棘齿城的麦伯克·米希瑞克斯。",r={{i=5056,n="根须样本",c=8}}},
  [867]={t="鹰身强盗",d="这些该死的鹰身人长期以来不停地攻击和掠夺我们的补给商队。现在我们要给她们一点颜色看看了：我们要割断她们的喉咙，削减她们的数量。；我一直在她们的巢穴附近细心观察，而且已经确定了谁是她们的领导者。我们应该首先以削弱她们的基础作战力量为目标，这样才能彻底击败她们。；慢慢来，先去干掉那些在西北方出没的巫翼鹰身人和巫翼游荡者，然后给我带8只巫翼鹰身人的爪子回来吧。这应该是一个不错的开始……",o="收集8只巫翼鹰身人的爪子。；把它们交给十字路口的达索克·快刀。",r={{i=5064,n="巫翼鹰身人的爪子",c=8}}},
  [868]={t="蝎卵",d="嘿，你，奥格瑞玛城里的主人派我到十字路口来观察这片土地并记录这里所发生的一切。；我的目标之一是在巨人旷野南方出现的昆虫状生物。我们对这种生物知之甚少，所以我把它作为我的主要研究课题，希望能发现点什么。它们似乎有超出一般生物的智能。；拿着这个掘地铲，从土丘里收集一些它们的卵。不过你要当心，这些生物一旦收到同伴的警报，就会立刻蜂拥而至。",o="把12枚异种蝎卵和掘地爪交给十字路口的科兰。",r={{i=5058,n="异种蝎卵",c=12},{i=5059,n="掘地铲",c=1}},w={{i=6503,n="小丑长袍",c=1},{i=6502,n="紫罗兰鳞甲",c=1}},f=2},
  [869]={t="偷钱的迅猛龙",d="不久前，我们警戒塔中的一箱银币被偷走了。那是十字路口警卫的薪水，当然我们必须找回这箱银币。；奇怪的是……被窃那天，我们逮住了那群小偷中的一个。它……它居然是一只迅猛龙！简直难以置信！；我不知道迅猛龙要这些银币做什么，不过我也不关心这个——我只关心能不能取回我的银币。杀掉那些迅猛龙，这样它们就不会再偷我们的东西了！；在贫瘠之地猎杀这些迅猛龙，把它们的头颅给我拿回来。",o="收集12颗迅猛龙的头颅，把它们交给十字路口的加兹罗格。",r={{i=5062,n="迅猛龙的徽记",c=12}}},
  [870]={t="遗忘之池",d="很久以前，贫瘠之地曾是个郁郁葱葱、生机盎然的地方。但是战争与灾难接二连三地降临在这片土地上，最后就剩下了这一片干燥荒芜的不毛之地。事实就是这样，真让我伤心。；不过，在过去的几年里，贫瘠之地出现了新的绿洲，生机又在这片土地上重现。我们德鲁伊感觉到了在很深的地下有一股试图冲出地面的力量。；我们必须找到这股力量的源泉，请到十字路口西北边的遗忘之池去一趟，在那里的湖水中搜寻力量的源泉，然后回到这里来。",o="向图加·符文图腾报告你的发现。"},
  [871]={t="野猪人的袭击",d="所有的野猪人都是我们的敌人，而其中有些家伙特别让人讨厌。；对我们而言，当前最大的麻烦就是钢鬃野猪人部族不停地对我们与杜隆塔尔之间的补给线发起攻击。我的探子一直在寻找这些袭击事件的指挥者，但是在找到真正的幕后主使之前，我们总得想些办法来对那些可恶的野猪人进行打击才行。；从这里的东北方向开始搜寻，你应该很容易就能找到他们的巢穴，野猪人的巢穴都好像是破土而出的带刺藤蔓一样的建筑物。去找到他们，把这些肮脏的家伙彻底干掉。",o="在钢鬃野猪人的营地里杀掉8个寻水者、8个织棘者和3个猎手，然后向十字路口的索克复命。"},
  [872]={t="野猪人的头目",d="你，我的探子目击了一次针对杜隆塔尔商队的袭击，又是那群该死的钢鬃野猪人干的。其中有一个家伙是这次袭击事件的策划者和组织者：克里尼格·糟鼻。有人在这里的东北方见到过他，就在通往杜隆塔尔的大路的正南方。如果我们要结束这一切威胁，就必须杀了克里尼格·糟鼻。；我们一定要终止这没完没了的袭击，要让他们吃吃苦头。完成任务之后，带上克里尼格·糟鼻的獠牙回来见我。",o="杀掉8个钢鬃地卜师、8个钢鬃防御者和他们的头目克里尼格·糟鼻。；把克里尼格·糟鼻的獠牙交给十字路口的索克。",p=871,r={{i=5063,n="克里尼格·糟鼻的獠牙",c=1}},w={{i=5275,n="束带",c=1},{i=5328,n="紧束腰带",c=1}},f=2},
  [873]={t="依沙瓦克",d="依沙瓦克是这片水域的主宰，它力大无穷、威武庄严。海岸上的人类都怕它，因为已经有太多的人类被它杀死。；但我不怕，因为它对我来说是一次很有价值的挑战，一个值得尊敬的猎物。；如果你准备好了，那么就到海里去寻找海中的巨兽依沙瓦克吧。；它的灵魂包容在他的心中，听着它跳动的声音，你就将看到自己的命运。",o="把依沙瓦克的心脏交给玛伦·星眼。",p=874,r={{i=5104,n="依沙瓦克的心脏",c=1}},w={{i=5356,n="烙印魔棒",c=1},{i=5357,n="山谷守护者",c=1}},f=2},
  [875]={t="鹰身人首领",d="哈哈哈，$n，你还想接下一单任务？好呀，我真是太高兴了。；这次的任务是剿灭无水岭的鹰身人首领。只有巫翼杀戮者才能成为鹰身人首领，这一点你可以从她们携带的戒指上判断出来。她们其实就是一伙乌合之众，在无水岭一带应该就有不少。只要杀死6个首领就足以对她们的这个母系氏族造成毁灭性的打击了。；$n，你一定要让她们死得很惨，我要让那些下贱的鹰身人知道和部落作对是多么愚蠢的事。",o="从巫翼杀戮者那里收集6枚鹰身人首领之戒，把它们交给十字路口的达索克·快刀。",p=867,r={{i=5065,n="鹰身人首领之戒",c=6}}},
  [876]={t="塞瑞娜·血羽",d="你在上次与鹰身人首领的战斗中表现得十分出色，所以我希望由你来帮我做最后一件事。；塞瑞娜·血羽是很久前被雷克萨杀死的鹰身人族长的妹妹。显然，这些针对部落商队的袭击是她对我们采取的报复行为。；你的任务就是干掉她，把她的徽记带给我。我将会把她的徽记挂在下一次发出的商队的车顶上……让那些鹰身人好好看看跟部落作对的下场。",o="杀掉塞瑞娜·血羽，把她的徽记交给十字路口的达索克·快刀。",p=875,r={{i=5067,n="塞瑞娜·血羽的徽记",c=1}},w={{i=5321,n="优雅短剑",c=1},{i=5279,n="鹰身人剥皮刀",c=1},{i=5318,n="斑马战斧",c=1}},f=2},
  [877]={t="死水绿洲",d="你在遗忘之池找到的地缝也许在贫瘠之地的其它绿洲中也存在。如果是这样的话，那么这些地缝就有可能是绿洲的生命之源。；我们应该验证一下。；带上这些种子，它们已经失去生命的活力。把它们带到东南方的死水绿洲去，如果那里有地缝的话，就把这些种子放在里面……然后仔细地观察一下。",o="调查死水绿洲，然后返回十字路口向图加·符文图腾报告。",p=870},
  [878]={t="野猪人的内战",d="你必须杀了我的敌人。<猪哼声>你必须帮助碎牙，帮助钢鬃野猪人。我们的部族都非常依赖自己的精神领袖——他们可以召唤大地的力量，<猪哼声>使他们让野猪人的部族变得强大……<猪哼声>；如果你想要知道是谁频繁对部落<猪哼声>发动袭击，那你就应该帮助碎牙！你去杀了刺背野猪人的精神领袖，削弱他们，这样钢鬃野猪人就可以打败他们，统治贫瘠之地了！",o="杀掉6个刺背寻水者、12个刺背织棘者和12个刺背地卜师，然后到陶拉祖营地的碎牙那里复命。"},
  [879]={t="内奸",d="有三个来自剃刀沼泽的部族参与了对部落的袭击。<猪哼声>他们非常狡诈而无情，如果你打败了他们，不仅仅是十字路口，整个贫瘠之地都将迎来和平……<猪哼声>至少野猪人不会再对你们构成威胁了。<猪哼声>；你要找的是纳克、卡兹和洛克·奥克班恩，他们就在贫瘠之地的最南边活动。他们中的一个是施法者，另一个是追踪者，他们的首领是个战士。<猪哼声>；杀了他们，杀了这帮背叛我的家伙。",o="杀掉纳克、卡兹和洛克·奥克班恩，把它们的徽记交给陶拉祖营地的碎牙。",p=5052,r={{i=5074,n="卡兹的徽记",c=1},{i=5073,n="纳克的徽记",c=1},{i=5072,n="洛克·奥克班恩的徽记",c=1}}},
  [880]={t="变异的生物",d="你，你的发现真让人难以置信。这些绿洲拥有一些特殊的力量，谁也不知道这些力量是怎样来的。；我想知道这几片绿洲是如何影响那些饮用过绿洲里的水的动物的。；去捕获一些在甜水绿洲和死亡绿洲活动的绿洲钳嘴龟，把它们的龟壳给我带过来，我得好好研究一下。",o="收集8块变异的钳嘴龟壳，把它们交给十字路口的图加。",p=877,r={{i=5098,n="变异的钳嘴龟壳",c=8}}},
  [881]={t="埃其亚基",d="白雾，也就是我们所说的埃其亚基，是草原狮的首领。它在捕食猎物时悄无声息地行动，就像大地上浮起的一层薄薄的白雾。它的每次出击都是一击毙命，它的猎物甚至来不及恐惧和痛苦就已魂飞魄散。；你会体会到的，因为我要让你去猎杀埃其亚基。它的巢穴就在十字路口的东北边，在那些巨大的科多兽骨附近。；去吧，当你走到它的巢穴附近时，就吹响这个号角，它正在等着你呢。",o="把埃其亚基的皮交给十字路口的瑟格拉·黑棘。",p=903,r={{i=5100,n="埃其亚基的皮",c=1}}},
  [882]={t="伊沙姆哈尔",d="伊沙姆哈尔是贫瘠之地最凶猛残忍的赤鳞龙，它狩猎并不是为了健身或是食物，而是因为狩猎是它最大的爱好，伊沙姆哈尔天生就是个杀手。；你，你会了解到它的天性的，因为你很快就要动身去追踪这条赤鳞龙了。；开始这次猎杀行动吧。先去杀死一只它最喜欢捕猎的动物——斑马，然后把斑马肉挂在棘齿城西北边的枯树上。当伊沙姆哈尔闻到肉味的时候，它就会出现的。；那时，你可要做好准备。",o="把伊沙姆哈尔的牙齿交给陶拉祖营地的乔恩。",p=3261,r={{i=5101,n="伊沙姆哈尔的牙齿",c=1}}},
  [887]={t="南海海盗",d="我当然希望格雷兹里克中将能够保护我们在这片海域上来来往往的商船。贸易巨头们向商船舰队里砸了这么多的金子进来，而这些海盗却在胡作非为，袭击我的船只，还偷走了我的货物！；我听说南海海盗就在南方的海岸边扎营，他们可以说是我的眼中钉肉中刺，假如格雷兹里克搞不定他们，也许你能帮我除掉他们。",o="帮棘齿城的加兹鲁维杀死12个南海歹徒和6个南海炮兵。"},
  [888]={t="被窃的货物",d="我希望取回所有丢失的货物，但我想那不太可能。不过，有些货物是我必须要取回的！；正如你所见的，我的天文台马上就要建好了，现在只差两块镜片中较小的一块。第一块已由杜隆塔尔的商队运到，第二块运上了船，但现在还没有到。对了，我还没有收到藏宝海湾的崔斯里克给我发来的靴子！；到海盗营地去一趟，看看能不能找到这些货物吧。",o="帮棘齿城的加兹鲁维取回一箱靴子以及一块望远镜片。",p=892,r={{i=5076,n="一箱靴子",c=1},{i=5077,n="望远镜片",c=1}},w={{i=5337,n="巡旅手套",c=1},{i=5320,n="多层软布靴",c=1}}},
  [890]={t="丢失的货物",d="我一直在等从藏宝海湾发来的最后一批货物！我确信是海盗偷走了它们，不过为了保险一点，我还是希望你能去一趟码头，帮我问问迪兹维格……问问我的货物是否已经入库。；把我的帐本交给迪兹维格，让他赶紧把我的存货记录和他的出货单校对一下。",o="把加兹鲁维的账本交给棘齿城的码头管理员迪兹维格。",p=887,r={{i=5080,n="加兹鲁维的账本",c=1}}},
  [891]={t="北方城堡的火炮",d="我又有一艘船被北方城堡里的那些狂热的人类给击沉了！；到了该和那帮混蛋算账的时候了。他们的偏执让他们变成了一群疯子。为了取乐，这些不计后果的呆瓜向每一个进入他们视野的目标开火。；从这里向南走，沿着商旅海岸就可以抵达北方城堡，干掉他们的人，然后把他们士兵的徽章给我拿回来作为证明。为了我心爱的舰队，你必须杀了法莫斯队长和她那些疯狂的炮兵！",o="棘齿城中的沙罗萨斯船长要你收集10枚塞拉摩徽章并干掉法莫斯队长、炮兵维桑恩和炮兵斯密瑟。",r={{i=5078,n="塞拉摩徽章",c=10}},w={{i=5309,n="海盗步枪",c=1},{i=5310,n="水手裤",c=1}},f=2},
  [892]={t="丢失的货物",d="我这边的出货记录似乎没什么问题，$n。回去告诉加兹鲁维，他似乎不太走运。不出意料的话，应该是有海盗偷走了他的货物。；很遗憾我不能为他做些什么了。呃……不过你可以告诉他，我从安德麦弄了些东西给他，什么时候他有空的话就过来拿一下吧。",o="把加兹鲁维的账本交还给棘齿城的加兹鲁维。",p=890,r={{i=5080,n="加兹鲁维的账本",c=1}}},
  [893]={t="野猪人的武器",d="在巨人旷野以南的地区，生活着大群的钢鬃野猪人。据我所知，他们曾是一群无能的铁匠，不过有人告诉我说，野猪人们现在已经逐渐开始改良他们的那些破烂武器了。我想要从他们那里弄些武器样品来进行研究。；如果你能帮我带回来几件武器的话，部落会以你为荣的。帮我带回一把捕猎者用的匕首，一根先知用的魔杖，和一面战士用的盾牌。",o="给陶拉祖营地的塔特纳克·钢炉带去一把钢鬃背刺匕首、一根烧焦的钢鬃魔杖和一面钢鬃大盾。",r={{i=5093,n="钢鬃背刺匕首",c=1},{i=5092,n="烧焦的钢鬃魔杖",c=1},{i=5094,n="钢鬃大盾",c=1}},w={{i=5322,n="破坏之锤",c=1},{i=5323,n="长明灯笼",c=1}},f=2},
  [898]={t="逃离监牢",d="终于有人来救我了！；你居然能躲过那些守卫，这简直是太不可思议了。这帮塞拉摩的狂热分子已经毫无理智可言了。他们击沉了我们的船只，俘虏了我这个唯一的幸存者，还称我为联盟的敌人和威胁。；你看我像是要威胁谁的样子吗？我不过是在棘齿城和藏宝海湾之间来回奔波的下等水手而已。；一下子说了这么多，你愿意帮我返回棘齿城吗？等你准备好了，我们就马上越狱。",o="护送基尔萨瑞斯·火枝安全地返回棘齿城的沙罗萨斯船长那里。",w={{i=5311,n="扣带长靴",c=1},{i=5312,n="铆钉护手",c=1}},f=2},
  [899]={t="复仇的怒火",d="我的全家都被刺背野猪人杀害了，$c。也许你能体会这种失去亲人的伤痛，也许你不能……每天我都等在这里，从日出到日落，寻找这些罪无可赦的恶魔。；从那天起，除了关在那边的俘虏之外，我见一个野猪人就杀一个。但这依然远远无法平息我复仇的欲望。；我想你这个$c能够帮助我。；去杀掉那些野猪人，能杀多少就杀多少。带回它们的獠牙，让我们一起为它们的死亡而庆贺吧。",o="收集60根刺背野猪人的獠牙，把它们交给十字路口的曼科里克。",r={{i=5085,n="野猪人的獠牙",c=60}},w={{i=5314,n="野猪猎人斗篷",c=1},{i=6477,n="草地腰带",c=1}},f=2},
  [900]={t="什么什么平衡器",d="三个控制阀门都处于打开状态。根据控制面板上的指示说明，在拆卸零件之前必须要把这三个阀门关闭。",o="关闭燃油控制阀、调节阀和主控制阀，然后再使用控制台。",p=894},
  [901]={t="什么什么平衡器",d="关闭设备后就可以开启控制面板，从控制台中移出主动式负载平衡器。一切准备就绪，现在你需要做的就是取得可以打开控制台的钥匙。",o="从工匠斯尼格斯那里拿到能打开控制台的钥匙。",p=900,r={{i=5089,n="控制台钥匙",c=1}}},
  [902]={t="什么什么平衡器",d="揭开控制台的盖子之后，你看见了密密麻麻缠绕在一起的电线、管子和其它各种奇形怪状的机械装备——其中大多数看起来没有什么实际用途。你把它们拨向一边，在控制台的最里边找到了主动式负载平衡器。一只机械臂把它从机架上拽了出来。",o="把主动式负载平衡器交给棘齿城的斯布特瓦夫。",p=901,r={{i=5054,n="主动式负载平衡器",c=1}},w={{i=5324,n="技师之锤",c=1},{i=5325,n="焊接盾牌",c=1}}},
  [903]={t="草原上的徘徊者",d="现在是该让你迎接一些真正的挑战了。贫瘠之地的徘徊者是一种很强悍的动物，而且非常致命。你可以在草丛里找到这些野兽，它们一般都在十字路口的西南边。；猎杀它们的时候要多加小心，你，不然的话，你很快就会发现自己的角色不再是捕猎者，而是猎物。",o="帮十字路口的瑟格拉·黑棘收集7只徘徊者的爪子。",p=845,r={{i=5096,n="猎手之爪",c=7}}},
  [905]={t="狂暴的镰爪龙",d="$n，你要做的下一步事情是打败你的猎物，并找到它们的巢穴。；去猎杀南边的赤鳞迅猛龙，然后拿走它们戴着的羽毛。把羽毛放在死水绿洲西南边的赤镰龙巢穴里，让它们知道你无所畏惧！",o="杀死赤鳞迅猛龙并收集它们的羽毛，把这些羽毛放在3个赤鳞镰爪龙的巢穴里，然后返回十字路口的瑟格拉·黑棘那里。",p=881},
  [906]={t="内奸",d="$r，带上洛克·奥克班恩的徽记去见索克吧。*猪哼的声音*他应该知道我的部族发生过什么事。哈，他不知道我也参与了*猪哼的声音*这些事情，但我敢肯定他会对你的所作所为给予奖励的。*猪哼的声音*；我们不会再见面了。*猪哼的声音*",o="把洛克·奥克班恩的徽记交给十字路口的索克。",p=879,r={{i=5072,n="洛克·奥克班恩的徽记",c=1}},w={{i=5316,n="树皮外套",c=1},{i=5317,n="干苔外套",c=1}},f=2},
  [907]={t="被激怒的雷霆蜥蜴",d="现在，$n，你必须面对强大的雷霆蜥蜴。这些野兽的体型非常巨大，连大地也会随着它们的行进而震颤。与它们作战时一定要多加小心，一次小小的失误就会让你丢了性命。；你可以在南贫瘠之地找到雷霆蜥蜴，当你击败它们之后再回来见我。",o="收集3瓶雷霆蜥蜴的血液，把它们交给陶拉祖营地的乔恩·星眼。",p=882,r={{i=5143,n="雷霆蜥蜴的血液",c=3}}},
  [913]={t="雷鹰的嘶鸣",d="雷鹰是一种凶猛的野兽，$n。现在你应该去挑战它们了，把它们的翅膀给我带回来，作为你获胜的证明。；完成这个任务，你就差不多可以结束在我这里的训练了。",o="找到一只雷鹰，杀掉它，然后把它的翅膀交给陶拉祖营地的乔恩·星眼。",p=907,r={{i=5164,n="雷鹰的翅膀",c=1}},w={{i=5302,n="生命之环",c=1},{i=5306,n="御风法杖",c=1}},f=2},
  [914]={t="尖牙德鲁伊",d="哀嚎洞穴中的那些尖牙德鲁伊，曾经是一些高尚的德鲁伊，他们的目标是治愈贫瘠之地的创伤。然而，现在他们却想把这片土地据为己有——曾经高贵的理想变成了扭曲的妄想，我们决不能让他们得逞。；尖牙德鲁伊组织共有四个首领，我在梦中见过他们，即便是现在，他们的面孔仍然萦绕在我的脑海中。打败他们，把他们的宝石给我拿来。；去吧，你。他们就潜伏在哀嚎洞穴的深处。",o="将考布莱恩宝石、安娜科德拉宝石、皮萨斯宝石和瑟芬迪斯宝石交给雷霆崖的纳拉·蛮鬃。",p=1490,r={{i=9738,n="考布莱恩宝石",c=1},{i=9739,n="安娜科德拉宝石",c=1},{i=9740,n="皮萨斯宝石",c=1},{i=9741,n="瑟芬迪斯宝石",c=1}},w={{i=6505,n="新月法杖",c=1},{i=6504,n="翼刃",c=1}},f=2},
  [916]={t="树林蜘蛛的毒囊",d="我是为了观察居住在黑丝洞的树林蜘蛛才来到幽影谷的。这些森林蜘蛛是另一种体型更小的蜘蛛的近亲；我相信世界之树在它们身上产生某些特殊的影响，我需要一些样本来研究它们以证实这一点。；首先，我需要一些它们的毒液，帮我从这些蜘蛛身上收集一些树林蜘蛛的毒囊吧，它们就在北方的黑丝洞一带活动。有了毒囊，我就可以研究一下这种毒与它们的近亲体内的剧毒有何相似之处。",o="给奥达希尔的基尔沙兰·风行者带回10个树林蜘蛛的毒囊。",r={{i=5166,n="树林蜘蛛的毒囊",c=10}},w={{i=10544,n="棘木之槌",c=1},{i=5392,n="棘木匕首",c=1},{i=5393,n="棘木法杖",c=1},{i=5586,n="棘木之刃",c=1}},f=1},
  [917]={t="树林蜘蛛的卵",d="现在我已经得到蜘蛛的毒液，不过我还需要一些活体样本以便更好地进行研究。不幸的是，抓来一只活的巨型蜘蛛对你来说也许太困难了，年轻的$c。而且，我也没办法处理一只巨型蜘蛛！；但如果你能找到一枚还未孵化的蜘蛛卵的话，从卵里提取样本作为研究材料就变得容易多了，而且我也能对付卵中未孵化的蜘蛛。；在黑丝洞的深处一定有蜘蛛的巢穴。拜托了，帮我到那里去找一枚蜘蛛卵吧。",o="给奥达希尔的基尔莎兰带回1枚树林蜘蛛的卵。",p=916,r={{i=5167,n="树林蜘蛛的卵",c=1}},w={{i=5395,n="林地之盾",c=1},{i=4907,n="林地外套",c=1},{i=11189,n="林木长袍",c=1}},f=1},
  [918]={t="林精的种子",d="泰达希尔的林精是代表自然的元素生物，它们以某种方式反映了我们这里的自然生态的情况。；所以看到林精变得如此愤怒真让人感到担忧。；我相信这与土壤有关。我一直在用不同的方法种植植物，可以用林精的种子来试验一下。我请求你，能在奥拉密斯湖周围的林精那儿收集一些种子给我吗？",o="给奥拉密斯湖边的德纳兰带去8粒林精的种子。",p=997,r={{i=5168,n="林精的种子",c=8}}},
  [919]={t="林精的新芽",d="小林精在奥拉密斯湖周围和涌泉湖以西迅速成长。我害怕它们会的数量会多到无法控制——我们应该在它们惹出乱子之前把它们从土地上清除。；你在湖边行走的时候，如果看到任何林精的新芽长出来，就顺便除掉它。让我们的土地免受污染！",o="给奥拉密斯湖边的德纳兰带去12个林精的新芽。",r={{i=5169,n="林精的新芽",c=12}},w={{i=5606,n="园艺手套",c=1},{i=6061,n="玄武岩护腕",c=1}},f=1},
  [921]={t="大地之冠",d="是该出发去追寻并探索你的自己的命运了，$n。但是在你走出我们美丽的森林之前，你应该首先好好了解我们近代的历史。；自海加尔山战役之后，我们的族人改变了许多。因为消耗了全部的力量来击败阿克蒙德并赶走燃烧军团，诺达希尔再度被暗淡的阴影笼罩……；有一个你必须去完成的任务，到奥达希尔北边的月亮井里装一瓶水，然后把它拿回来给我。",o="装满水晶瓶并将其带回给奥达希尔顶部的特纳隆·雷拳。",p=920,r={{i=5184,n="装满水的水晶瓶",c=1}}},
  [922]={t="雷利亚·绿树",d="你，你能给我的朋友雷利亚·绿树带去一粒种子吗？他是个住在达纳苏斯的德鲁伊，我们上次谈话时，他对我的林精研究工作很感兴趣。他有自己的想法，如果有粒可以用来作试验的种子的话，他一定会非常感激的。；谢谢你，你。你帮了我一个大忙。希望有一天你能看到我的劳动成果。；雷利亚一般会在塞纳里奥区的路上闲逛。",o="给达纳苏斯的雷利亚·绿树带去一粒林精的种子。",p=918,r={{i=5168,n="林精的种子",c=1}}},
  [923]={t="青苔之瘤",d="一种邪恶的力量正在森林中滋生。我们到处寻找邪恶之源，但当我们找到的时候……为了泰达希尔的安全，我们必须消灭掉那些已经无法挽救的林精。生长在泰达希尔北部的涌泉湖的林精所受的污染最为严重，你必须消灭它们！；消灭在那里发现的林精，收集生长在它们身上的青苔之瘤，然后把那些瘤交给我，让我烧掉它们。",o="收集5个青苔之瘤，然后把它们交给达纳苏斯的雷利亚·绿树。",p=922,r={{i=5170,n="青苔之瘤",c=5}},f=1},
  [924]={t="恶魔之种",d="恶魔之种是燃烧军团使用的一种强大工具，它生长在鬼雾峰洞穴里的恶魔火坛上。；我已经准备好了能量石，只要把它放在恶魔之种附近，就可以切断它与燃烧军团的联系。；从石台上取一块能量石，把它带到鬼雾峰上的火焰祭坛去。从这里一直往西走，然后在交叉路口向北转，鬼雾峰就在你的左边。从鬼雾峰北坡爬上去应该是最安全的路线。；动作快点——石头的魔力在很短的时间内就会耗尽。",o="取一块有瑕疵的能量石。在能量石失去魔法之前把它带到火焰祭坛去，然后向雅克塞罗斯复命。",p=809,f=2},
  [927]={t="布满苔藓的心脏",d="恶臭的黑苔兽的心脏上长满了又黑又油腻的苔藓。事实上，如果它没有那缓慢而有节奏的心跳，也许你根本就看不出这是颗心脏来。；也许德纳兰会想要研究一下这颗心脏。",o="将布满苔藓的心脏交给奥拉密斯湖畔的德纳兰。",r={{i=5179,n="布满苔藓的心脏",c=1}}},
  [928]={t="大地之冠",d="关于月亮井和泰达希尔的点点滴滴实在是太多了，我无法一一告知给你，这需要你自己去探索。科瑞萨斯·月怒正在等着你。我已经把你所带回来的水倒入了这个容器中，把它送到科瑞萨斯那里去吧。；出发吧，科瑞萨斯就在多兰纳尔的月亮井旁。你只需要沿着奥达希尔南边的小路走出幽影谷，沿着鹅卵石铺成的小路一直走，然后向西转就行了。；注意，你要一直沿着路走，$n。最近路旁的森林里出现了许多危险的野兽。",o="将装着半瓶水的瓶子交给多兰纳尔的科瑞萨斯·月怒。",p=921,r={{i=5186,n="装着半瓶水的瓶子",c=1}}},
  [929]={t="大地之冠",d="首先，让我告诉你必须要完成的任务的其它一些细节。达纳苏斯的德鲁伊需要使用泰达希尔的月亮井的水，所以月亮井的水需要不断地补充。使用这种特制的瓶子，你可以收集起月井之水。；带着这个瓶子去东边的星风村，装满村外的月井里的水，再带回来给我。你完成任务之后，我将继续讲述台纳隆的故事……",o="用月亮井的水装满翡翠瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。",p=928,r={{i=5639,n="装满水的翡翠瓶",c=1}}},
  [931]={t="发光的树叶",d="植物上的叶子泛着微弱的光，产生了一种不断变化的光晕。；你觉得德纳兰可能会想要研究这种东西。",o="给奥拉密斯湖畔的德纳兰带去1片发光的树叶。",r={{i=5190,n="发光的树叶",c=1}}},
  [932]={t="扭曲的仇恨",d="$n，你必须提高警惕，我们不能对这件事袖手旁观。萨特就够我们头疼的了，而眼前的这件事更是火烧眉毛。；有个名叫迈雷纳斯的恶棍就住在附近的地狱石洞穴里，他在那儿聚集了一大批骁勇的战士为自己卖命，他的心如无月的夜晚一般黑暗，他当前正在密谋着一些极端邪恶的勾当。；到这里北边的洞穴去找他，带他的徽记来见我。",o="杀掉迈雷纳斯，带他的徽记去见多兰纳尔的塔隆凯·捷根。",r={{i=5221,n="迈雷纳斯的徽记",c=1}},w={{i=5419,n="野兽护腕",c=1},{i=2571,n="藤蔓包裹",c=1}},f=1},
  [933]={t="大地之冠",d="在达纳苏斯城门的东南方还有一口月亮井，就在阿里斯瑞恩之池的岸边。由于瘤骨熊怪的数量无节制地增长，以及他们对于这个地区的疯狂攻击，哨兵们根本无法有效地控制这一地区。；在寻找月亮井的时候小心点，一定要时刻握紧你的武器。",o="用月亮井的水装满红玉瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。",p=929,r={{i=5645,n="装满水的红玉瓶",c=1}}},
  [935]={t="大地之冠",d="没有生命的赋予者阿莱克斯塔萨和时间之王诺兹多姆的祝福，泰达希尔的成长就很难一帆风顺。我不断收到有奇怪的猛兽出现的报告，而疯狂的熊怪也开始不断地袭击路人。；我只能希望大德鲁伊们能尽快找到解决的方法。我会将把你带来的所有月亮井水都灌入这个瓶中，然后让你把它带到达纳苏斯去。；把这只瓶子交给范达尔·鹿盔，你可以在德鲁伊之林里找到他。",o="将装满月亮井水的瓶子带给在达纳苏斯的大德鲁伊范达尔·鹿盔。",p=7383,r={{i=5188,n="装满月亮井水的瓶子",c=1}},w={{i=5596,n="灰木弓",c=1},{i=5595,n="灌木之锤",c=1}},f=1},
  [937]={t="神谕林地",d="我和一个哨兵小组被派到这里来保护神谕之树免受鹰身人的威胁。它们已经在沼泽周围建造了很多巢穴，我们正在试着把它们赶回去。；神谕之树曾派信使到达纳苏斯去通报这一情况，但一群鹰身人在中途杀死了那个信使。；如果你认为你能胜任这项任务的话，就到它们的巢穴里去，杀死它们，把它们的腰带拿回来作为证明。",o="收集6条血羽腰带，把它们交给神谕林地里的哨兵阿瑞尼亚·碎云。",r={{i=5204,n="血羽腰带",c=6}},w={{i=5592,n="镣铐束腰",c=1},{i=5591,n="雨点斗篷",c=1}},f=1},
  [938]={t="密斯特",d="这只猎豹的毛皮是很特别的暗灰色，与四周的森林几乎融为一体。她静静地躺在地上，你发现她伤得很重，背部和腹部都有很深的伤口。；她抬起头盯着你，蓝色的双眼闪着智慧的光芒。她似乎希望跟随你。",o="护送密斯特去神谕之树附近的月亮井旁找哨兵阿瑞尼亚·碎云。",w={{i=5590,n="绳结护腕",c=1},{i=5593,n="峭壁圆盾",c=1},{i=5618,n="守候披风",c=1}},f=1},
  [939]={t="萨瓦里克长笛",d="打败萨瓦里克之后，你仔细看着从他的尸体上拿到的木制长笛。；这根带节的木棍摸起来很结实，但是当你把它拿在手中翻看时，笛子表面的纹理似乎突然开始旋转了起来。你猛然间感觉到了一丝恐惧……；你摇了摇头，感到这可能是你的感觉在和你开玩笑。；可能其它的萨特身上有关于你所发现的东西的线索。将你发现的线索交给费伍德森林南部的德鲁伊，艾瑞丹·蓝风。",o="将萨瓦里克长笛和5个碧火魔符交给费伍德森林南部的艾瑞丹·蓝风。",r={{i=11668,n="萨瓦里克长笛",c=1},{i=11674,n="碧火魔符",c=5}}},
  [940]={t="泰达希尔",d="你的事迹在森林里传扬，$n。鹰身人已经被赶走，森林恢复了平静，这里的生物再次感受到了安全和宁静。我几乎已经不敢派信使去大德鲁伊那里了，但我知道你会帮我把信息安全送达的。；把消息传递给他，我知道森林将保佑你安全地将信息送达目的地。",o="把神谕之树的报告交给达纳苏斯的大德鲁伊范达尔·鹿盔。",p=937,r={{i=5219,n="刻字的树皮",c=1}},f=1},
  [942]={t="健忘的勘察员",d="这块化石和我在铁炉堡看到的一块化石非常的相似。一个名叫弗拉冈特的考古学家把它带到了我们一年一度的冒险者年会上。他坚信那块化石中蕴藏着奇特的魔力，而且那种魔力是可以被提取出来的。；上一次我听到弗拉冈特的名字时，他还住在米奈希尔港的深水旅店里，正在等着被护送到维尔加挖掘场去。把雷姆塔维尔的化石交给他，也许他能揭开化石中蕴含着的秘密。；去米奈希尔的船都是从暴风城出发的。",o="把神秘的化石交给米奈希尔港的考古学家弗拉冈特。",p=741,r={{i=4654,n="神秘的化石",c=1}}},
  [943]={t="健忘的勘察员",d="嗯，我在那里会议之后把原始样品交给了勘察员维尔。最近，我在洛克莫丹发现了雷鲁之石，我认为它就是解开神秘化石的钥匙。；当我准备赶往维尔加挖掘场的时候，遭到了迅猛龙的攻击，雷鲁之石也给弄丢了。；我不知道是哪只迅猛龙吞掉了这块石头，但如果你能找回它，我应该就可以释放这些化石中的魔力了。当然，我们也需要最初从维尔加挖掘场取回的那枚化石。",o="米奈希尔港的考古学家弗拉冈特要你把雷鲁之石带给他。",p=942,r={{i=5233,n="雷鲁之石",c=1},{i=5234,n="弗拉冈特的化石",c=1}},w={{i=5627,n="古代之刃",c=1},{i=5626,n="削骨巨斧",c=1}},f=1},
  [944]={t="主宰之剑",d="我很奇怪纳迦为什么会出现在这里，在黑海岸。但更奇怪的是……暮光之锤。那些信rn徒崇拜非常非常古老的大地之神，一个很久以前就被打败的神。；主宰之剑就是那个古神被打败的地方。；去那里找到更多暮光之锤的信徒。；带上这瓶占卜之水。等你到了主宰之剑之后，就用它制造一个占卜之碗，通过那个碗，你可以直接和我通话。",o="收集信息，然后使用占卜之水创造出一个占卜之碗，并利用这个碗和安努通话。",p=948},
  [947]={t="洞中的蘑菇",d="我正在研制一种药剂，需要一种生长在特定洞穴里的稀有蘑菇才能配制。这个洞穴位于壁泉河瀑布的后面，在东边稍稍偏北的地方。；我本来准备自己去，不过古树之林建议我不要靠近那个地方。我们尊贵的盟友觉得那个洞穴是黑海岸新出现的邪恶势力的藏身之处。；你，请你帮我收集那些蘑菇。与此同时，请显示一下那处洞穴以便确认古树所担心的事情。",o="收集5个粗柄蘑菇和1个毒帽蘑菇，把它们交给奥伯丁的巴瑞萨斯·月影。",r={{i=5271,n="粗柄蘑菇",c=5},{i=5270,n="毒帽蘑菇",c=1}},f=1},
  [950]={t="向安努回复",d="仔细阅读暮光之书会让人发疯。只要盯上一小会儿，书上的字就开始游动乱舞，原本美妙的插图和花边也扭曲得变了形。；为了不至于让神志陷入混乱之中，你只好赶快撕下了一张写着这些可怕的文字的书页。",o="把令人发狂的书页交给安努。",p=949,r={{i=5272,n="令人发狂的书页",c=1}}},
  [951]={t="玛塞斯特拉遗物",d="你在主宰之剑找到的那页书来自于一本古籍……一本精灵撰写的古籍。但它已经被暮光之锤诅咒和玷污了，看来暮光之锤的信徒是希望用古代精灵的魔法将他们古老的主人重新召回我们的世界。；到东北边的玛塞斯特拉废墟去看看，找到那些古代的遗物。如果我能研究一下它们的话，也许能搞清楚暮光之锤打算如何使用那些精灵的魔法。",o="收集6个黑暗深渊遗物，把它们交给古树之林的安努。",p=950,r={{i=5273,n="黑暗深渊遗物",c=6}},w={{i=5757,n="硬木棍",c=1},{i=5615,n="巡林人之剑",c=1}},f=1},
  [955]={t="巴莎兰",d="如果要我把一生的故事都讲出来，恐怕你会失去耐心。简单地说，我的一生漫长而痛苦，而现在这种鬼魅般的生活更是对我最痛苦的折磨。；我被魔法囚禁在这里。也许我说的话有些夸张，但我可以向你发誓，如果你能帮我找到从这里逃脱的办法，我一定会对你感激不尽的。现在我被施加了封印，如果你能帮我拿些萨特和劣魔的耳环，我也许能找到一些线索。",o="帮巴莎兰的阿斯特利安收集8只劣魔耳环。",p=954,r={{i=5336,n="劣魔耳环",c=8}}},
  [956]={t="巴莎兰",d="如果劣魔开始与施加在我身上的封印频频联系的话，我想我已经猜到原因了。毫无疑问，这枚封印已经落入指挥他们的萨特的手中。；我强烈地感觉到了这一点，$n。某个萨特得到了那个封印。如果你能得到它，或许就可以帮我冲破这牢笼，我将对你不胜感激。",o="获取远古月亮石封印，把它交给巴莎兰的阿斯特利安。",p=955,r={{i=5338,n="远古月亮石封印",c=1}}},
  [957]={t="巴莎兰",d="某位非常强大的贵族制造了这个用来囚禁我的封印。在南方的亚米萨兰有一处与这里相似的废墟，那里至今仍燃烧着远古的火焰，那蓝色的火焰可以摧毁这个封印。；不过在那片废墟里，你千万要当心，$n……",o="用亚米萨兰废墟中的远古火焰摧毁远古月亮石封印，然后回到巴莎兰的阿斯特利安那里。",p=956,w={{i=7229,n="探险者的外衣",c=1},{i=5617,n="流浪者护腿",c=1},{i=5604,n="精灵魔杖",c=1}},f=1},
  [958]={t="上层精灵的工具",d="玩家，我有一项任务交给你。；你去过亚米萨兰废墟吗？如果还没有，你可以在通向南方的大路东侧找找看。亚米萨兰废墟曾经是众多暗夜精灵贵族的家园，而如今那里却成为他们滥用魔法的见证。；据哨兵的报告，那些贵族的亡灵依然在使用古代的魔法武器进行抵抗。我们必须获得那些遗物，只有这样我们才有可能真正摧毁那些亡灵。",o="帮奥伯丁的桑迪斯·织风取回7个上层精灵的遗物。",r={{i=5360,n="上层精灵的遗物",c=7}},f=1},
  [962]={t="毒蛇花",d="幽暗城的皇家药剂师学会派我来这儿完成一个特殊的任务，$n。我想你会愿意帮助我的，因为黑暗女王领导下的被遗忘者将会通过我的任务得到进一步的加强。；近来我在研究一种罕见的植物，它的名字叫毒蛇花，我相信这种药草有着巨大的能量。；不幸的是，它只生长在哀嚎洞穴的最深处，那是贫瘠之地最危险的洞穴之一。",o="为雷霆崖的药剂师扎玛收集10朵毒蛇花。",r={{i=5339,n="毒蛇花",c=10}},f=2},
  [963]={t="永志不渝",d="永恒之井的战斗结束以后，亚米萨兰被毁灭了，全城的暗夜精灵都成为了这座城市的陪葬，其中就有我的至爱安娜雅。；我也没有想到，在那次灾难过去了数千年之后，对安娜雅的回忆依然萦绕在我的梦中。有一次，当我恍恍惚惚地在黑海岸的森林里游荡的时候，我发现自己正置身于亚米萨兰的废墟之中……我居然看见了我的至爱——她那饱受折磨的亡魂。；她必须得到自由，但我没有勇气去做，因为让她得到自由，就必须先摧毁她的亡灵。",o="释放安娜雅·晨路的灵魂，把她的坠饰交给奥伯丁的塞瑞利恩·白爪。",r={{i=5382,n="安娜雅的坠饰",c=1}},f=1},
  [964]={t="骸骨碎片",d="通灵学院大门的钥匙名叫骷髅钥匙，它一定是由某具骸骨制造而成——事实上是若干具骸骨——并在适当的模具中使用最坚硬的金属进行加固。天生就能打开通灵学院大门的人拥有一种特殊的力量，这种力量能让钥匙发挥作用。；重要的事情要优先处理掉，你。我们需要一些骸骨碎片来制造钥匙。安多哈尔内的骸骨应该符合我们的要求，但是安多哈尔城外的那些骸骨也许同样有效。",o="将15块骸骨碎片交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",p=838,r={{i=14619,n="骸骨碎片",c=15}}},
  [966]={t="奥萨拉克斯之塔",d="一群术士在这座塔的里里外外住了下来。我本应该早些回去向艾莉萨报告，但我想如果我亲自去报告的话也许会错过些什么。；德尔格伦怀疑这伙人聚集在塔周围是要密谋什么坏事，但我们对此知之甚少。；我手里有一些术士的羊皮卷轴碎片，但我还需要更多的碎片才能解开这个谜。对了，我必须警告你，千万不要冒险进入塔中，因为塔里的术士非常可怕！",o="在奥萨拉克斯之塔附近帮巴苏尔·影击收集4块破旧的羊皮纸。",p=965,r={{i=5348,n="破旧的羊皮纸",c=4}}},
  [967]={t="奥萨拉克斯之塔",d="我的主人，净化者德尔格伦，是一位伟大的圣骑士。为了保护森林不受恶魔和亡灵的袭扰，德尔格伦一直在尽全力帮助我们。他向我传授了圣光术和各种其它的战斗技巧。；你必须尽快把这个教派的消息告诉德尔格伦。；他就驻扎在南方的灰谷森林里的迈斯特拉岗哨。请快一点，我非常担心这个暗滩教派带来的威胁会越来越大。",o="把巴苏尔的信送给灰谷森林中的净化者德尔格伦。",p=966,r={{i=5354,n="写给德尔格伦的信",c=1}}},
  [969]={t="祝你好运",d="啊，我一看见你就知道——你想要一个幸运符咒。玛艾里无所不知！；在冬泉谷的南部有一道峡谷，那里的巨人身上有时候带有一种具有强大能量的冰块，当然你也可以自己从峡谷中收集冰块碎片。；带给我四片霜槌碎片回来，然后我的幸运符咒就是你的了。",o="收集4块霜槌碎片，把它们交给永望镇的巫医玛艾里。",r={{i=12334,n="霜槌碎片",c=4}}},
  [970]={t="奥萨拉克斯之塔",d="巴苏尔的这封信里的消息真是可怕。这个暗滩教派对我们而言始终是一个很大的威胁，必须尽快清除才行。我和东北方的奥迪拉兰城中的暗滩教派打过交道，他们中的一个人持有一枚灵魂宝石，其中蕴藏着有关这个教派的魔法的秘密。；把它交给我，我应该有办法从中找出一些信息来。",o="搜集一枚发光的灵魂宝石，并把它交给迈斯特拉岗哨的净化者德尔格伦。",p=967,r={{i=5366,n="发光的灵魂宝石",c=1}}},
  [971]={t="深渊中的知识",d="你也许知道，我喜欢收集各种知识：古老的知识，有用的知识，可以打开神秘通路的知识，可以唤醒沉睡之人的知识。；据说有本古老的书卷叫做洛迦里斯手稿，它被藏在黑海岸的黑暗深渊底部。那里是往日死去的精灵安息的地方。那些精灵在他们的城市被毁灭之前都有着广博的知识。；到黑暗深渊去找手稿吧，我不会忘记你为我做的事，即使到世界毁灭的那一天……",o="把洛迦里斯手稿带给铁炉堡的葛利·硬骨。",r={{i=5359,n="洛迦里斯手稿",c=1}},f=1},
  [973]={t="奥萨拉克斯之塔",d="伊克鲁德·玛格苏尔，没错，我了解他。他可是一个强大的兽人术士，就住在火痕神殿里，那是一个位于灰谷西南的极端邪恶的地方。；至今他并没有给我们造成太大的麻烦，而我也没工夫去对付他，不过现在看起来……他的死期到了。",o="把伊克鲁德·玛格苏尔之书交给迈斯特拉岗哨的净化者德尔格伦。",p=970,r={{i=5533,n="伊克鲁德·玛格苏尔之书",c=1}},w={{i=5622,n="祭司之戒",c=1},{i=5613,n="净化者法杖",c=1}},f=1},
  [974]={t="究根问底",d="对我来说，这里的温泉简直就是个不解之谜，这些热量究竟是哪里来的？；这些水池离火羽山那么近，我真的想知道火山和温泉之间到底有没有关系。我制作了一个测温计来读取火山的温度，我想要找到温度最高的地方。它是按照我独创的计量单位进行测量的！；拿着这个温度计，当你经过某个炎热的地方，就顺便读取一下那里的温度！",o="安戈洛尔环形山的克拉兰克要你去找到火羽山中温度最高的地方。；当你找到一个看上去很热的地方时，就右键点击温度计来测量当地的温度。不断尝试，直到你找到温度最高的地方。",r={{i=12472,n="克拉兰克的温度计",c=1}}},
  [976]={t="奥伯丁的补给品",d="德尔格伦让我给奥伯丁的哨兵艾莉萨·星风捎信，顺便给她提供一定的补给，但是我讨厌一个人上路。密林深处到处危险的敌人，我可不想让这些物资和信息落到他们的手里。；如果你或者其它人能担当我的护卫，我们现在就可以出发了。有你的帮助，我坚信这些物资一定能平安运抵奥伯丁。",o="护送费罗·艾隆汉安全地穿越灰谷森林，然后和迈斯特拉岗哨的净化者德尔格伦谈一谈。",p=973,w={{i=5323,n="长明灯笼",c=1},{i=6721,n="柯尔的胸甲",c=1}},f=1},
  [977]={t="雪怪计划！",d="现在我已经有了遮盖机体的东西，然后只需再有一件东西就成了。好吧，实际上是两件。两支角！；冰蓟雪人王和冰蓟雪人女王身上都有这样的角，它们就住在东南边的洞穴里。那里的雪人数量众多，我想你不会找不到它们的。；记住，我只要外观最好的角——绝对不要有伤痕的或者破碎的角！",o="为永望镇的乌米收集2支完美的雪人角。",p=3783,r={{i=12367,n="完美的雪人角",c=2}}},
  [978]={t="月光羽毛",d="从辛特兰收集到的枭兽羽毛中包含着魔法能量的痕迹。这些能量……看来并不是枭兽能够运用的，它们只是简单地蕴含在这些生物体内——而带有这种能量的都是最强悍的枭兽。；在研究这个问题的过程中，我听说在白雪皑皑的冬泉谷那有很多的枭兽。那些生物是否携带着相同的能量呢？请帮我找到这个问题的答案，你。到冬泉谷去收集它们的羽毛，然后把它们交给我。",o="从冬泉谷收集10片月光羽毛，然后将它们带给鲁瑟兰村的艾瑞拉斯·琥珀。",p=3661,r={{i=12383,n="月光羽毛",c=10}}},
  [981]={t="The Tower of Althalaxx",o="Talk to Delgren the Purifier at Maestra's Post.",p=1143,w={{i=10043,n="虔敬裹腿",c=1},{i=5614,n="大天使之击",c=1}},f=1},
  [982]={t="深不可测的海洋",d="从我们现在所在位置沿着海岸一直往北可以看到两艘沉船——银色清晨号和迷雾之纱号。这两艘船在穿越茫茫大海，最终将要达到奥伯丁的时候遇到了那些可恶的鱼人，它们现在只能躺在海底作为那些恶棍的战利品了。；这两艘船的船长都没有能幸免于难，他们的日志以及其它有价值的东西还锁在船里的箱子中。我希望你能帮我找到这些东西，这对于那些生还的船员也是颇有意义的。",o="找到银色清晨号的保险箱和迷雾之纱号的保险箱，把它们交给奥伯丁的高尔博德·钢手。你可以在村庄北部遇难的船只里找到这两只箱子。",r={{i=12191,n="银色清晨号的保险箱",c=1},{i=12192,n="迷雾之纱号的保险箱",c=1}},w={{i=15401,n="水滴手套",c=1},{i=15402,n="绳索护手",c=1}},f=1},
  [983]={t="传声盒827号",d="嘿！看看我这划时代的最新发明：传声盒！通过它，你可以和很远的人进行交谈！；也许你已经见过它们了，嗯，就是那些上面有操纵杆的盒子。不过传声盒有一个毛病，就是它们需要经常性的维护。；而且每一个盒子的问题都不一样，不过我在这个问题上做得就很巧妙！你看，我把每一个盒子都放在那些能给它提供最合适的修理零件的生物附近。现在传声盒827号出了点故障，它就在奥伯丁的南边，需要6只蟹腿来进行修理。我会奖赏你的……",o="收集6只蟹腿，把它们放进传声盒827号。",r={{i=5385,n="蟹腿",c=6}}},
  [984]={t="熊怪的威胁",d="你，我来这里是想看看魔苔的影响有多么厉害。我的一些同胞险些被泰达希尔的一个堕落的熊怪杀死，而我发誓不会让类似的情况再次出现……更别提更糟糕的情况了。；在黑海岸，我已经看见了一系列有关各种生灵堕落的线索，但我需要找到这种堕落是否有蔓延的迹象。我想我们仍然应该通过熊怪来进行调查，你可以帮我找到一个熊怪的营地吗？如果你发现了任何情况，就马上回来报告我。",o="在黑海岸找到一处堕落熊怪的营地，然后向奥伯丁的特伦希斯报告。"},
  [985]={t="熊怪的威胁",d="你，在侦察敌人方面，你已经展示了足够的才能。但你与他们作战的技能如何呢？；并不是所有的冒险者都喜欢面对面的遭遇战，我是某些冒险者更喜欢潜行之类的隐秘行动。；如果你觉得自己能行，就到奥伯丁南边的那个熊怪营地吧，那里的熊怪对我们构成了极大的威胁。在那一带活动的都是黑木部族的熊怪，去杀掉8个黑木探路者和5个黑木风语者，然后回来向我报告。",o="杀掉8个黑木探路者和5个黑木风语者，然后回到奥伯丁向特伦希斯汇报。",p=984},
  [986]={t="失踪的主人",d="你，你帮了我很多忙，我能不能再请求你帮助一下锐爪和他的主人沃科尔？我可以帮你精心制作一件有魔力的斗篷，它能够让你在寻找沃科尔时畅通无阻，免受黑海岸上任何猛兽的阻挠。；不过要制作这件斗篷，我需要从月夜雄虎或者月夜雌虎身上获取几张上等毛皮。你可以在急弯河以南找到那些月夜猛虎。",o="收集5张优质月夜猛虎毛皮，把它们交给奥伯丁的特伦希斯。",p=985,r={{i=5386,n="优质月夜猛虎毛皮",c=5}}},
  [992]={t="加基森水业公司",d="如果你感兴趣的话，我们现在正在为加基森水业公司招聘兼职初级勘探员。；那些游牧民不断地侵占我们的水井，这迫使我们不得不去勘探更多的水源！沙漠中到处都可能有水的存在，但是只有聪明人才能找到它们。；拿着这个瓶子，到流沙岗哨旁的水池那里帮我采集一些水样回来。那个水池旁边有些巨魔在看守着，小心点，完成任务之后尽快把水样送到我这里来。",o="用未使用的寻水器在流沙岗哨旁边的池中采集水样。一旦你收集到水样，就尽快将其交给加基森的高级勘探员菲兹杜瑟。",r={{i=8585,n="使用过的寻水器",c=1}}},
  [994]={t="Escape Through Force",o="Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.",p=993,f=1},
  [995]={t="偷偷溜走",d="好吧。我们走。；记住，在你逃脱以后，到奥伯丁去找特伦希斯。我会自己赶去那里的。",o="离开熊怪洞穴，然后去见奥伯丁的特伦希斯。",p=993,f=1},
  [997]={t="德纳兰的泥土",d="你在往南方旅行吗？你要去奥拉密斯湖吗？如果是这样的话，我有个任务想请你帮忙……；我的同伴德纳兰在湖的东岸有个营地，他在那儿对泰达希尔的植被进行研究和试验。他想要一包达纳苏斯的稀土，但送货的在路上耽搁了，我这两天才刚刚收到稀土。；你能把这包稀土带给他吗？",o="把稀土交给奥拉密斯湖畔的德纳兰。",r={{i=5391,n="稀土",c=1}}},
  [1001]={t="传声盒411号",d="细小的声音噼里啪啦地从机器内部传出来。；“这里是维兹班恩！下一个传声盒在奥伯丁北部海岸上的某个地方。我的记性有时候不太好，不好意思！；那台传声盒的编号是411，需要3颗蛇颈龙的眼球来修理。你可能得跳进漆黑冰冷的大海深处去寻找黑海岸鱼龙……真抱歉……；就像上次一样，只要你给传声盒带去维修所需的物资，它就会给你吐出报酬的。*打嗝*……什么？没事，我很好！”",o="从位于传声盒411号附近的深海中收集3颗黑海岸蛇颈龙的眼球。",p=983,r={{i=5412,n="蛇颈龙的眼球",c=3}}},
  [1002]={t="传声盒323号",d="传声盒突然静了下来，然后你听见维兹班恩又开始说话。；“下一个传声盒的编号是323。它在奥伯丁北部，不过……我的麦酒哪儿去了？什么？哦，在路上，小桥边，你不会找不到它的。”；维兹班恩咕哝咕哝地说了一些不连贯的话，然后你听见大口喝酒的声音。；“这个传声盒需要月夜猛虎的牙齿来维修……需要6颗。”",o="收集6颗月夜猛虎的牙齿，把它们放进传声盒323号。",p=1001,r={{i=5413,n="月夜猛虎的牙齿",c=6}}},
  [1007]={t="远古雕像",d="我有一项任务交给你，你。；当我坐船经过被淹没的佐拉姆废墟的时候，受到了纳迦的攻击。这些家伙突然从水里冒出来，他们的利爪差点就把我撕个粉碎！我想尽办法带上所有可以带走的物资逃了出来，然后在这里搭建了一个简易的营地。；但是，当我逃上岸的时候……我最重要的宝贝不见了。；求求你，你，找到我遇袭的地方，帮我寻找一尊古代雕像。正是为了它，我才会鼓起勇气闯入佐拉姆海岸这么危险的地方。",o="把远古雕像交给塔尔伦，他的营地就在佐拉姆海岸附近。",r={{i=5424,n="古代雕像",c=1}}},
  [1008]={t="佐拉姆海岸",d="在我们的西北海岸，也就是佐拉姆海岸一带，潜伏着一股邪恶的势力。；佐拉姆海岸是已经被毁灭的佐拉姆城残存的部分，佐拉姆主城在大爆炸中被摧毁，沉到了海底，这些很久以前发生的事情已经快要被暗夜精灵忘却了。；现在，纳迦又回来了。至于他们为什么会回来，谁也不知道。但是这些并不重要，我们必须杀了这些魔鬼，把他们送回地狱！；完成任务之后，就立刻回来向我报告。",o="收集20颗怒尾纳迦的徽记，把它们交给阿斯特兰纳的辛德瑞尔。",r={{i=5490,n="怒尾纳迦的徽记",c=20}}},
  [1009]={t="卢泽尔",d="除非你能找到可以打开雕像上的那只锁的钥匙，否则雕像的秘密将永远无法解开。；那把钥匙其实是一枚戒指——佐拉姆之戒。在这座城市被很久以前那场大爆炸所掀起的波涛淹没之前，佐拉姆之戒曾经属于这座城市的统治者。；这枚戒指已经丢失很多年了，不过纳迦最近找到了它。；他们的领导者卢泽尔就住在佐拉姆北部边缘的一个小岛上。请帮我取回这枚戒指吧，你。",o="找到佐拉姆之戒，把它交给佐拉姆海岸边的塔尔伦。",p=1007,r={{i=5445,n="佐拉姆之戒",c=1}},f=1},
  [1010]={t="巴斯兰的头发",d="在北边那座巴斯兰鬼屋的废墟上，曾经生长着一种叫做巴斯兰的头发的植物，它能够让人的灵魂安宁下来。；在村庄里有个患病的孩子，我想他的病痛不仅仅是肉体上的。你愿意帮我到巴斯兰鬼屋去寻找一些巴斯兰的头发吗？我需要用它来医治这个孩子。；巴斯兰鬼屋就在迈斯特拉岗哨以北，灰谷和黑海岸交界的地方。",o="收集5份巴斯兰的头发，把它们带给灰谷的奥雷迪尔·阔叶。",r={{i=5437,n="巴斯兰的头发",c=5}}},
  [1011]={t="被遗忘者的病菌",d="被遗忘者——部落中的亡灵势力——已经潜入了灰谷，现在就潜伏在我们的废墟和洞穴之中。我们认为他们的目标是在暗夜精灵的领地上散播疾病。这一点必须尽快得到确认！；被遗忘者在南边有一个营地，就在朵丹尼尔兽穴附近，那是他们制造和封装毒物的地方。攻入那个营地，给我偷取一瓶病毒，我得研究一下这些毒药，这样才能搞清他们真正的意图。",o="找到一瓶病毒，把它交给林歌神殿中的凯尼斯·静风。",r={{i=5440,n="一瓶病菌",c=1}}},
  [1012]={t="疯狂的德鲁伊",d="在我和被遗忘者的毒物抗争的时候，曾经在恍惚之中产生了一段幻觉，我看到朵丹尼尔兽穴中的德鲁伊被亡灵下毒害死了！他们现在是游荡的幽灵，他们的灵魂离开了身体，并且变得越来越疯狂。；为了让德鲁伊的灵魂早日安息，你必须进入朵丹尼尔墓穴，杀死那些昔日的德鲁伊领袖：坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云。；赶快去吧。",o="杀死这些德鲁伊：坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云，然后向慰藉之林中的凯尼斯·静风复命。",p=1011,f=1},
  [1013]={t="乌尔之书",d="你，在影牙城堡里有一本书，它被称作乌尔之书，我很想得到它。乌尔在天灾军团到来之前曾是达拉然的一位伟大的法师，他对其它世界的研究对……被遗忘者中的某些团体……很有价值。；到影牙城堡去找到这本书，把它交给我，我会向黑暗女王汇报你的贡献。",o="把乌尔之书交给幽暗城炼金区里的看守者贝尔杜加。",r={{i=6283,n="乌尔之书",c=1}},w={{i=6335,n="灰色长靴",c=1},{i=4534,n="钢环护腕",c=1}},f=2},
  [1014]={t="除掉阿鲁高",d="现在我已经对整个诅咒有了一个全面的了解，并开始着手研究如何补救了。；但阿鲁高依然好好地住在影牙城堡中。在干掉阿鲁高之前，我们还不能宣称银松森林已经是黑暗女士的地盘。；但是，我得去搞明白怎样才能根除他的魔法影响，$n。所以我只能把除掉阿鲁高的任务交给你了。；到影牙城堡去，永远地结束阿鲁高的肮脏法术。把他的徽记给我带来！影牙城堡去，永远地结束阿鲁高的肮脏法术。把他的徽记给我带来！",o="杀死阿鲁高，把他的徽记带给瑟伯切尔的达拉尔·道恩维沃尔。",r={{i=5442,n="阿鲁高的徽记",c=1}},f=2},
  [1016]={t="元素护腕",d="拿着这张占卜卷轴——它可以侦测出那些水元素是谁召唤出来的。但是你必须从水元素身上拿到一些东西才能查到真相。；只需几个完整的元素护腕就可以完成占卜过程，其它类型的护腕对我们没什么用，但是也许会有商人想要收购那些东西。当你拿到了完整的元素护腕之后，就对它使用占卜卷轴，得出结果之后回到我这里来，让我们看看下一步该怎么办。",o="收集5个完整的元素护腕，并对它们使用占卜卷轴。然后把使用过的占卜卷轴带给银风避难所的哨兵维尔莉妮·星坠。",r={{i=5455,n="使用过的占卜卷轴",c=1}}},
  [1020]={t="奥雷迪尔的药剂",d="你，我合成了一种药剂，相信它能帮助这个饱受折磨的孩子。把药带到阿斯特兰纳去，交给这孩子的父亲皮尔图拉斯·怀特姆恩。；顺着这条路向南走，然后向东转，就能看到阿斯特兰纳了。",o="把奥雷迪尔的药剂交给阿斯特兰纳的皮尔图拉斯·怀特姆恩。",p=1010,r={{i=5460,n="奥雷迪尔的药剂",c=1}}},
  [1022]={t="狼嚎谷",d="尽管我们投入了大量的物资和人力想要将剩馀的恶魔赶出北方的费伍德森林，但是看来似乎并没有什么效果。我们只能把大部分的恶魔御于灰谷之外。；在北方的费伍德森林附近，有一群神秘的狼人占据了麦尔莎迪丝神殿的废墟。他们令人心颤的嗥叫使得那个地区得了个“狼嚎谷”的名字。保存在神殿中的麦尔莎迪丝之书也许能让我们知道这些狼人出现在这里的原因。",o="到狼嚎谷去，研究一下麦尔莎迪丝之书，然后向林歌神殿的哨兵梅丽瑞亚·霜影复命。"},
  [1023]={t="莱恩的净化",d="在检查泰洛尼斯的遗物时，你发现了一本完好无损的日记。；你收起日记之后就离开了泰洛尼斯的尸体。；接下来你唯一要做的事情就是找到泰洛尼斯一直在寻找的那颗宝石。莱恩曾经提到过宝石就在这个地区，也许在鱼人的手里……",o="找到发光的宝石，连同泰洛尼斯的日记一起交给阿斯特兰纳的莱恩·狼行者。",p=991,r={{i=5463,n="发光的宝石",c=1}}},
  [1024]={t="莱恩的净化",d="你得自己去进行研究，但是从泰洛尼斯的记录来看，你下一阶段的工作将是去寻找达图尔所造的魔棒的其它部分。我建议你从伊瑞斯湖东部的月亮井开始。如果你准备好了，就沿着这条路越过环绕着伊瑞斯湖的群山，然后向北走。；一个名叫莎尔蒂恩的树妖会在那里为你提供向导。记得带上宝石，如果莎尔蒂恩愿意帮你重造魔棒，她肯定会需要这块宝石的。",o="在东北方的月亮井旁找到莎尔蒂恩。",p=1023,r={{i=5463,n="发光的宝石",c=1}}},
  [1026]={t="莱恩的净化",d="情况越来越糟糕了。；莱恩的猜测是对的，我很了解达图尔的发明以及这个地区的树人——至少我曾经了解。树人们现在开始堕落了，他们的灵魂变得扭曲。；如果你想要找到魔棒的下一块碎片的话，就必须先找到一把木制钥匙，用它来打开锁住这块碎片的箱子。；这把木制钥匙就在东北方的费伍德森林附近的一个树人手里。得到了钥匙之后，你就可以顺着这条路向西走，在靠近费伍德森林的边界地区寻找一小块林间空地……箱子就藏在那里的某个地方。",o="找到木制钥匙和一段达图尔的魔棒，然后回到月亮井的莎尔蒂恩那里。",p=1024,r={{i=5464,n="铁杆",c=1}}},
  [1027]={t="莱恩的净化",d="魔棒的最后一段是由朵丹尼尔的德鲁伊保管的，但是我不清楚他们把它藏到了什么地方。很抱歉，恐怕我只能帮你这么多了。；我所能告诉你的就是：顺着这条通向贫瘠之地的路一直走下去，这群德鲁伊隐居在路的东边，可是他们也没法帮助你，因为他们最近被杀死了……那是一段我不愿再回忆的过去。；如果你找到了最后一段魔棒，就把它带回来交给我，我会帮你修复魔棒的。",o="找到达图尔的魔棒的最后一段，然后回到月亮井旁的莎尔蒂恩那里。",p=1026,r={{i=5519,n="铁质柄头",c=1}}},
  [1028]={t="莱恩的净化",d="这是完整的魔棒，你。修复它并不难……难的是找到神殿，并再次赋予它能量。；对于像你这样已经完成了这么多艰巨工作的人来说，只要稍加留意和努力，这个任务也不会太难。；从这儿向东南方走——那里人迹罕至，所以要多加小心——路上记得留意正北方。神殿就隐藏在围绕着那片林地的山峦中。；到了那儿之后，把魔棒放在神殿中……剩下的就交给魔法去完成吧，祝你好运。",o="找到隐藏的神殿并给达图尔的魔棒重新注入魔力。",p=1027,r={{i=5547,n="重铸的魔棒",c=1}}},
  [1031]={t="塞纳留斯的树枝",d="安妮莉亚把手放在你的肩头上，慢慢地把你拉近她的身边。她艰难地喘着气，抬手指向北方的拱门。在她的气息渐渐变得微弱，眼睛慢慢地闭上之前，安妮莉亚留下了最后一句话：“被他夺走了……加萨里斯……”她临终时还在想着要让塞纳留斯的树枝回到树妖的手中。",o="杀掉加萨里斯，把塞纳留斯的树枝交给林歌神殿的伊莉亚娜。",p=1021,r={{i=5461,n="塞纳留斯的树枝",c=1}},w={{i=5820,n="精灵衬肩",c=1},{i=11229,n="明鳞腰带",c=1}},f=1},
  [1033]={t="月神之泪",d="我曾把挽救蕾拉的生命的希望寄托于奥雷迪尔的医术上，可让我担心的是，那只能延缓疾病在我孩子体内的蔓延而不能让她彻底痊愈。我们一定要找到更有效的药物！感谢奥雷迪尔，他告诉我如果第一种治疗方法不能起作用的话，还有下一步的治疗方法。；有一种名叫月神之泪的特殊的石头，只有在阿斯特兰纳东部的伊瑞斯湖中心的小岛上才能找到它。奥雷迪尔说这块石头能治疗一切疾病……求求你，你，帮我找来月神之泪，祈求它能结束我孩子的痛苦。",o="找到月神之泪，把它交给阿斯特兰纳的皮尔图拉斯·怀特姆恩。",p=1020,r={{i=5493,n="月神之泪",c=1}}},
  [1034]={t="星尘废墟",d="月神之泪减轻了我女儿的一些病痛，感谢艾露恩，她发恶梦的次数也大大减少了。可是……她仍发着高烧。；奥雷迪尔告诉我，在南方的星尘废墟中可以找到一种结晶的星尘，或许它能缓解蕾拉的高烧。请你帮我收集一些星尘吧。；愿艾露恩保佑你速去速回。",o="收集5份星尘，把它们交给灰谷的皮尔图拉斯·怀特姆恩。",p=1033,r={{i=5494,n="一份星尘",c=5}}},
  [1035]={t="坠星湖",d="蕾拉的高烧退了，但她还是很虚弱。我想她很难靠自己的力量康复，我们可能要借助月亮石的魔力才能让她痊愈。；过去我们常在东南部的坠星湖搜集月亮石……但是沼泽兽来了之后就不行了。；这群野兽的领袖是一个沼泽兽智者，它成堆成堆地收集所有从天上掉下来的月亮石。现在，你得从沼泽兽智者那里取回一枚月亮石。；要达到这一目的，恐怕你必须先杀了那个沼泽兽智者。",o="从沼泽兽智者那里取回一枚陨落的月亮石，并把它带给阿斯特兰纳的皮尔图拉斯·怀特姆恩。",p=1034,r={{i=5508,n="陨落的月亮石",c=1}},w={{i=5814,n="溪流护甲",c=1},{i=6722,n="野兽镣铐",c=1},{i=17047,n="冷光披肩",c=1}},f=1},
  [1038]={t="维琳德的日记",d="你是由麦尔萨迪斯之书中得知这一切的？我认为你应该去检查一下她的所有物品，虽然那样做可能不太妥当。用这把钥匙可以打开她放在哨兵小屋里的储物箱。她把平时的工作都记录了下来，因此你从她的日记中应该可以了解到很多事情。；我应该告诉你，哨兵们认为她是因为某些特殊的原因而离开的，她随时都有可能再回来。女祭司过去做过很多让我们对她倍加信赖的事情。",o="在维琳德的箱子里搜寻她的日记，把日记连同钥匙一起交给达纳苏斯的塞恩提尔·刃纹。",p=1037,r={{i=5520,n="维琳德的日记",c=1},{i=5521,n="维琳德的钥匙",c=1}}},
  [1043]={t="月神的镰刀",d="你的故事听上去不像是假的……我不能完全理解你的动机，不过如果你想要除掉暮色森林的狼人，我就不需要了解这些。；在南方有一座矿山，很多狼人在那里出没……天知道他们是从哪里冒出来的，不过据我们所知，他们最早就是在那里出现的。；去忙你的吧，不过如果你有什么重要消息，请一定要告诉我。我们需要所有能帮我们对抗邪恶的信息。",o="去找关于月神镰刀的消息，然后回到夜色镇见乔纳森·卡尔文。",p=1042},
  [1044]={t="Answered Questions",o="Return to Thyn'tel Bladeweaver in Darnassus.",p=1043,w={{i=5817,n="月神之弓",c=1},{i=5818,n="月光魔杖",c=1}},f=1},
  [1045]={t="莱恩的净化",d="暗夜精灵是个历史悠久的种族，但是他们的傲慢毁灭了他们的世界。现在，这样的傲慢也毁掉了我们的生活，一切都失控了……；我把许多灾难归咎于那些精灵们，但是我们也应该为自己的行为承担责任。即使在堕落之前，我们也具有非常邪恶的一面。；兰恩·血牙就是这种邪恶面的体现。对权力的渴望，无尽的物欲……现在的堕落只会让他更加强大。我的心中燃烧着对这些精灵的怒火，但我对他们的后代并无恶意，我们也必须管教好自己的儿女，让他们不再重蹈我们的复辙……",o="杀死兰恩·血牙和4个血牙保镖，并拿到兰恩·血牙的徽记，然后向密斯特拉湖附近的克罗尔格复命。",p=1030},
  [1046]={t="莱恩的净化",d="回到你自己的部族去吧，让他们知道你在这里取得的胜利。；向他们展示你的战利品，并享受胜利的荣耀吧……",o="把兰恩·血牙的徽记交给阿斯特兰纳的莱恩·狼行者。",p=1045,r={{i=5388,n="兰恩·血牙的徽记",c=1},{i=5462,n="达图尔的变形魔棒",c=1}},w={{i=5815,n="冰川石",c=1},{i=17046,n="开槽之刃",c=1}},f=1},
  [1048]={t="深入血色修道院",d="当黑暗女王陛下将主要精力放在对付北方的天灾军团时，我更关心那些身边的问题。；毫无疑问，有一群自称为血色十字军的人类渣滓正在威胁着我们的领土。提瑞斯法林地当前正被这群红蚂蚁逐渐侵蚀和占据。；到修道院里去干掉大检察官怀特迈恩与她手下的那些军官，$c。",o="杀掉大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色十字军勇士赫洛德和驯犬者洛克希，然后向幽暗城的瓦里玛萨斯回报。",w={{i=6802,n="预兆之剑",c=1},{i=6803,n="预言藤杖",c=1},{i=10711,n="龙血项链",c=1}},f=2},
  [1049]={t="堕落者纲要",d="大地之环对那些被遗忘者开诚布公，但是谁又知道那些亡灵们对我们到底有什么意图？；虽然被遗忘者与我们结了盟，但他们从来就以精于欺诈而闻名。我们的这个盟约实在是太草率了，也许凯恩会睿智地留意到来自奥格瑞玛的警告。；在血色修道院深处，那些疯狂的人类狂热者们守卫着《堕落者纲要》。虽然这帮家伙是如此的疯狂和顽固，但他们的研究也许会对我们有些用处。",o="从血色修道院里找到《堕落者纲要》，把它交给雷霆崖的圣者图希克。",r={{i=5535,n="堕落者纲要",c=1}},w={{i=7747,n="邪恶防护者",c=1},{i=17508,n="力石圆盾",c=1},{i=7749,n="终结宝珠",c=1}},f=2},
  [1050]={t="泰坦神话",d="未来是已经命中注定了的！我们的命运就像雨点落入大海一样无可改变。；不过研究过去也许可以让我们预见未来，并提前做好一些准备。；在灾难降临在洛丹伦之前，提瑞斯法林地中有一处藏有许多书籍的地方——老修道院的图书馆，据说有一本《泰坦神话》就收藏在哪里。；把它给我拿回来，也许我们可以一起揭开过去的秘密。",o="从修道院拿回《泰坦神话》，把它交给铁炉堡的图书馆员麦伊·苍尘。",r={{i=5536,n="泰坦神话",c=1}},f=1},
  [1051]={t="沃瑞尔的复仇",d="虽然我现在是个独立的亡灵，但我恐怕无法再为黑暗女王效力，因为我觉得支撑我生命的力量都被毁了。；这一切都是那个审讯员韦沙斯造成的！他折磨了我好几个星期，还拿走我的结婚戒指送给了他的妻子。那个混蛋！；复仇……我要复仇！；那个自负的笨蛋总是吹嘘他的宝贝老婆南茜多么多么娇艳，她就住在洛丹米尔湖一带，去杀了她，把我的结婚戒指还给我那在塔伦米尔生活的妻子莫尼卡。；请帮助我完成这最后的愿望……",o="把沃瑞尔·森加斯的结婚戒指还给塔伦米尔的莫尼卡·森古特斯。",r={{i=5538,n="沃瑞尔的结婚戒指",c=1}},w={{i=7750,n="悲哀衬肩",c=1},{i=4643,n="十字军斗篷",c=1}},f=2},
  [1052]={t="血色之路",d="我们血色十字军拥有着从壁炉谷到提瑞斯法林地一线的许多要塞。这些要塞构筑了保护洛丹伦大陆的主要防线，我们为此感到十分自豪。；你在南艾泽拉斯对抗亡灵的行动已经证明了你的价值。但真正的威胁仍然来自正在洛丹伦北部蔓延的瘟疫。；到一处叫做南海镇的城镇去，在那里找到一个名叫莱雷恩的十字军战士，把这封由我亲自密封的表彰信交给他，他将会护送你转至充满荣耀的血色修道院。",o="将安东修士的表彰信带给南海镇的虔诚的莱雷恩。",p=261,r={{i=5539,n="表扬信",c=1}}},
  [1053]={t="以圣光之名",d="我曾怀着荣耀、忠诚、自豪的心情加入了血色十字军。我曾坚信他们有着将艾泽拉斯的所有亡灵生物都消灭干净的崇高理想。；但自从我在提瑞斯法林地的修道院里待了一阵之后，我意识到他们现在已经几近疯狂了。他们认为除了那些穿着十字军制服的人之外的所有人都已经感染了瘟疫，而任何被怀疑感染上瘟疫的无辜者都要遭到他们无情的拷打。；以圣光的名义，血色十字军必须被铲除掉。你，$n，必须消灭这个疯狂的组织。",o="杀死大检察官怀特迈恩，血色十字军指挥官莫格莱尼，十字军的勇士赫洛德和驯犬者洛克希并向南海镇的莱雷恩复命。",p=1052,w={{i=6829,n="平静之剑",c=1},{i=6830,n="咬骨之斧",c=1},{i=6831,n="黑暗威胁",c=1},{i=11262,n="洛瑞卡宝珠",c=1}},f=1},
  [1057]={t="夺回焦炭谷",d="你应该能猜出来，身为森林之灵的守护者的我为什么会如此愤怒。；你翻越了无数山岭来到这里，一路上你应该已经看到在这片土地上都发生了些什么。贪婪正在将这神圣的山脉引向毁灭的深渊。；南方的焦炭谷正在遭受那群贪得无厌的机械化工业大军的荼毒。更糟的是，那里的鹰身人竟然拒绝让我们进入那里抚慰大地受到的创伤。；把这群肮脏的鹰身人给我赶出去，$n！",o="石爪峰的守护者奥巴格姆要求你杀死7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。"},
  [1058]={t="金吉尔的森林魔法",d="我实在是太兴奋了！；笼子里的三个小精灵！但我们该对我们这些整天都要抱着树的小朋友们做些什么呢？有了！让他们尝尝那个……他们是怎么叫它来着……“森林魔法”的滋味吧！；我首先需要一些苔藓分泌出来的石爪苔液，然后你再从那些凶悍的夜行虎身上给我搞点胡须来。啊，对了，还要许多的巨角鹿眼珠子。还有还有，差点忘记了，还要一块灵龙的鳞片！；这些东西都能在石爪峰上找到，动作快点，$n，我要准备施展这森林魔法了！",o="玛拉卡金的巫医金吉尔需要5瓶石爪苔液、5根夜行虎须、30颗巨角鹿的眼球和1块灵龙的鳞片。",r={{i=5582,n="石爪苔液",c=5},{i=5584,n="夜行虎须",c=5},{i=5585,n="巨角鹿的眼球",c=30},{i=5583,n="灵龙的鳞片",c=1}},w={{i=6664,n="巫毒衬肩",c=1},{i=6665,n="妖术护腕",c=1}},f=2},
  [1059]={t="Reclaiming the Charred Vale",o="Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.",p=1057,w={{i=6675,n="弹性护腕",c=1},{i=6676,n="治安官圆盾",c=1}},f=1},
  [1062]={t="地精侵略者",d="由地精运营的风险投资公司进入了石爪山西部，开始无节制地砍伐树木、焚烧森林。森林中的山灵们已经几乎要被地精带来的痛苦与愤怒逼疯了。我们必须阻止风险投资公司的恶行！；向西进入巨木谷，你可以在那里找到正在工作的地精和他们的仆从——告诉他们，部落决不会允许他们把石爪山弄得一团糟。用他们最容易理解的语言——暴力——来和他们沟通……",o="杀死15个风险投资公司樵夫，然后向石爪山与贫瘠之地交界处的希雷斯·碎石复命。"},
  [1065]={t="塔伦米尔之旅",d="为了把风险投资公司赶出石爪山，我们就必须采取极端的措施。极端的，但是不用流血。；我的一个同事可能有我们需要的工具，他叫林度恩，就住在希尔斯布莱德丘陵的塔伦米尔镇，那地方在遥远的洛丹伦地区。；要去希尔斯布莱德的话，就要先乘飞艇到我们的首都幽暗城，然后往北到提瑞斯法林地，再往西南进入银松森林，最后再转向东南才能到希尔斯布莱德丘陵。；找到林度恩，把这封信带给他，里面详细叙述了我们需要什么样的帮助。",o="把扎玛的信带给塔伦米尔的林度恩。",p=1064,r={{i=5628,n="扎玛的便笺",c=1}}},
  [1066]={t="无辜者之血",d="我要制造一种毒药，给风险投资公司的那些暴力分子一点教训，让他们不再那么嚣张。这样就能解决部落在石爪山的问题了，不是吗？；不过要制造毒素的话，我还需要一些无辜者之血，这种东西很难找。；幸运的是，这个地区的人类强盗组织——辛迪加组织雇佣了一些暗影法师……这些法师为了自己的邪恶目的专门收集无辜者之血。；到东南方的敦霍尔德城堡去，你可以在那里找到不少辛迪加暗影法师。",o="为塔伦米尔的药剂师林度恩收集5瓶无辜者之血。",p=1065,r={{i=5620,n="无辜者的血",c=5}}},
  [1067]={t="返回雷霆崖",d="毒药做好了。用它来对付风险投资公司的话，一定能让我们无往而不利，甚至可能还会有一些意想不到的效果。我得说，看见我的研究成果能在战场上发挥作用真是太令人兴奋了！；不过在使用之前，你得先把它拿去给药剂师扎玛。她会想出让毒药发挥最大效果的方法。",o="把林度恩的毒药交给雷霆崖的药剂师扎玛。",p=1066,r={{i=5588,n="林度恩的毒药",c=1}}},
  [1071]={t="侏儒学者",d="你看，你，我也是伟大的魔法、化学和工程学研究会的成员，我的目标……嗯嗯，我的使命，便是好好教导这帮暗夜精灵们，让他们知道魔法、化学和工程学的融合便可拯救他们的森林！；但这是一场艰苦的战斗，地精们的繁殖速度简直就像兔子一样。我甚至没有时间去搞新的发明！；我需要些时间来进行计划和组织。但这需要你的帮助，去帮我把东边狂风峭壁那里的绿皮玩意们干掉一些。",o="杀掉10名风险投资公司樵夫和10名风险投资公司砍树工，然后向石爪山的加克希姆·尘链复命。",p=1085},
  [1073]={t="失职+药剂=快乐",d="哈哈哈……你来搞硝酸甘油炸药是为了阻止地精们破坏森林？！；我现在不关心你和加克希姆到底熟不熟了……我可以把这玩意给你，谁管最后是你还是他们被炸成碎片！；但是还有一个小问题，我现在身边没有成品。；只要你把我需要的材料带给我，我就可以马上给你做一些。；但在这之前，至少你得证明你在炼金术方面不是个白痴。",o="给铁炉堡的洛玛克·链带拿去4瓶初级法力药水和2瓶初级坚韧药剂。",p=1072,r={{i=2455,n="初级法力药水",c=4},{i=2458,n="初级坚韧药剂",c=2}}},
  [1074]={t="失职+药剂=快乐",d="去吧，陌生人。小心点……这玩意很容易被引爆的。；如果你真是加克希姆的朋友，别忘了替我跟他问个好。如果不是的话，那么就祝你被炸飞吧。",o="将硝酸甘油炸药带回石爪山，交给加克希姆·尘链。",p=1073,r={{i=5732,n="NG-5",c=1}}},
  [1076]={t="西部荒野中的恶魔",d="啊，有了。一个传信法术……我相信你需要的就是这种效果。；我会为你做一张抄写有这道法术的卷轴，不过要完成它，我得先弄些尘魔的残骸来。；在我找到其它的材料之前，你能到西部荒野去给我抓一只这种邪恶的生物回来吗？它们的确很危险，但我肯定，如果你想为加克希姆的实验做点什么贡献的话，没什么是你不能搞定的。；我会在这里等你回来。",o="将尘魔的残骸带回给暴风城的科林·玛林。",p=1075,r={{i=5669,n="尘魔的残骸",c=1}}},
  [1077]={t="给加克希姆的特快专递",d="拿着这个吧，你。这张卷轴会满足你的要求的。；当你再见到加克希姆的时候，记得替我向他问好。我正等着听到你们凯旋的消息呢。；再见。",o="将通讯卷轴交给石爪山的加克希姆·尘链。",p=1076,r={{i=5731,n="通讯卷轴",c=1}}},
  [1078]={t="完鳞归玛伦",d="旅行者们一直在问我有关石爪山的事情，看来那里已经成为一个公认的最佳冒险场所了——当然前提是你没有在寻找双足飞龙、元素生物，也没有跟风险投资公司扯上关系。；在石爪山脉深处的焦炭谷中还居住着一群披着厚重鳞片的蜥蜴。把那些鳞片磨成灰就是我施放一些法术所必需的原料。；如果这些蜥蜴还活着的话，你能不能帮我搞一些它们的鳞片来？；注意点时间，不用太着急，而且我会付给你不错的酬劳。",o="给暴风城的科林·玛伦带回8片水晶鳞片。",r={{i=5675,n="水晶鳞片",c=8}},f=1},
  [1081]={t="Reception from Tyrande",o="Find Tyrande Whisperwind in Darnassus.",p=1082,w={{i=7334,n="风霜长袍",c=1},{i=7335,n="灰色外套",c=1},{i=7336,n="野木锁甲",c=1}},f=1},
  [1087]={t="塞纳留斯的遗产",d="你根本无法想象到我是多么地憎恶这片污浊的土地。石爪峰那里有一小撮可怜兮兮的塞纳留斯族类和暗夜精灵的德鲁依们聚集起来，妄图彻底抑制住魔法的传播……甚至还妄想着夺回他们深深眷恋着的极南之地的森林。；尽管我很乐意回到加德纳尔去享受传授魔法的快乐，但在我的工作完成之前，主人恐怕是不会让我回去的。；我确信你和我一样，对暗夜精灵一族及他们盟友都没有任何好感。所以，请帮助我吧，这样一来，我们都能得到令自己满意的结果。",o="为石爪峰附近的布莱林·火拳杀死4名塞纳留斯的儿子，4名塞纳留斯的女儿以及4名塞纳里奥植物学家。"},
  [1088]={t="奥达努斯",d="他们自以为能够阻止魔法的传播，但他们无疑大错特错了！他们自以为能藏得住奥达努斯，但我一定要他死！；魔法赋予了我真知……没错，我能看到他。一处岔路……就在灰谷森林中的一棵巨树的顶部。这棵巨树的名字叫作……瑞恩伍德。它是森林之神最初的几位子嗣之一。当初，在我找到奥达努斯之前，他就从石爪峰离开了，但现在，他的生命即将结束！；把他的徽记带回来给我，我将送给你一件强力的魔法物品作为礼物。",o="将奥达努斯的徽记带给石爪峰的布莱林·火拳。",p=1087,r={{i=5686,n="奥达努斯的徽记",c=1}}},
  [1089]={t="大兽穴",d="德鲁依们在石爪城堡中建造了一个石爪猛禽洞穴，在那里面保存着一些威力强大的物品。；他们制订了一整套详细的防范方案来避免这些物品落入他人之手。；幸运的是，我想尽一切办法从他们当中的某个人口里套出了一些有用的细节。；只要你找到那个洞穴入口处的一只小灯笼，就可以拿到守门人的钥匙。用这把钥匙就可以打开隐藏在洞穴中各处的暗格，而暗格里就藏有能打开中央大仓库的工具。",o="到石爪峰上的洞穴中去，使用守门人的钥匙拿到能打开石爪峰顶的猛禽洞穴储藏室的物品。",p=1088,r={{i=5689,n="沉睡者的钥匙",c=1},{i=5690,n="利爪钥匙",c=1},{i=5691,n="古墓钥匙",c=1}},f=2},
  [1091]={t="向凯拉回报",d="你，把这些信拿去交给凯拉。我确定她会对里面的内容有兴趣，至少哨兵部队会感兴趣。；记得告诉她，我们的行动是有多么的成功，哦，还有，别忘了强调一下，如果不用点魔法的话，我们是不可能成功的。",o="将风险投资公司函件带给石爪山脉的凯拉·影矛。",r={{i=5717,n="风险投资公司函件",c=1}}},
  [1092]={t="格雷苏的要求",d="我想我也应该赶紧跑路了。这件事情马上就会传到上头人的耳朵里，而且他们肯定不会给我好果子吃。；我得从这里偷偷逃出去，然后去见菲兹克斯。如果他能给我找到一份新工作就再好不过了！；我得先把这里给打扫打扫，不能留下什么痕迹，而你最好现在就动身，马上把矿石的样本给菲兹克斯送去。他说他就在狂风峭壁西边建了一片营地，祝你走运！",o="将未经化验的矿石送到石爪山的菲兹克斯那里。",p=1090,r={{i=5733,n="未经化验的矿石",c=1}}},
  [1093]={t="超级收割机6000",d="风险投资公司到底在搞什么鬼啊，嗯？他们到底在想些什么呀？地精的公司里竟然雇佣了一个侏儒！；好在斯布特瓦夫是个识货的家伙，知道我是个天才，他在我被公司炒了以后马上就雇佣了我！；据说公司正在制造一种新型的大型伐木机，斯布要把我这东西的设计书偷来给他。不过格雷苏——那个满手是血的侏儒——他一看见我就想把我给干掉……或许你能替我去把设计书给偷来？你应该可以在他们的操作员身上找到它。",o="为石爪山的菲兹克斯偷来超级收割机6000型的设计图。",r={{i=5734,n="超级收割机6000型的设计图",c=1}}},
  [1094]={t="新的指示",d="这信封里有我被撵走之后风险投资公司方面的全部情报……公司内部文件，一些操作手册，技术设备……嗯嗯，当然还有超级收割机6000型的蓝图。；斯布特瓦夫就在贫瘠之地的棘齿城，你应该很容易找到他的……特征？太明显了，他的皮肤是绿色的。",o="将密封的信封交给贫瘠之地棘齿城的斯布特瓦夫。",p=1093,r={{i=5735,n="密封的信封",c=1}}},
  [1096]={t="格雷苏",d="我只见过格雷苏一次，但我得告诉你，那家伙一眼看上去就知道他不好对付。他的一部分身体似乎已经残废了，于是他给自己装上了一些金属部件和装备，这样他的部分肢体就机械化了。；格雷苏就在西北方峭壁湖的湖岸边上监视着整个地区的工作进展。我想我是没办法去那里了……但你看起来也许有能力对付他。；如果你能为我干掉他的话，我会付给你不错的酬劳的。",o="将格雷苏的机械臂带给石爪山脉的菲兹克斯。",p=1095,r={{i=5736,n="格雷苏的机械臂",c=1}},w={{i=6667,n="技师披风",c=1},{i=6668,n="绘图员长靴",c=1}}},
  [1098]={t="Deathstalkers in Shadowfang",o="Find the Deathstalker Adamant and Deathstalker Vincent.",f=2},
  [1100]={t="亨里格的日记",d="你慢慢打开亨里格·独眉的这本破旧的日记……",o="阅读亨里格·独眉的日记。",r={{i=5790,n="独眉的日记",c=1}}},
  [1101]={t="卡尔加·刺肋",d="可怜的赫尔拉斯！还有这个矮人……他是多么的勇敢。；我们不能让他们白白牺牲。卡尔加·刺肋……必须受到制裁。；当然，深入剃刀沼泽是非常危险的，但现在已经没有时间通知达纳苏斯了。$n，组织一支队伍去杀掉卡尔加·刺肋。；把她的徽章交给我，作为她已死的证明。",o="把卡尔加·刺肋的徽章交给萨兰纳尔的法芬德尔。",p=1100,r={{i=5792,n="卡尔加·刺肋的徽章",c=1}},w={{i=4197,n="绿宝石护肩",c=1},{i=6742,n="石拳束带",c=1},{i=6725,n="石饰圆盾",c=1}},f=1},
  [1102]={t="奥尔德的报复",d="凯恩是个高贵而睿智的领导者，是他带我们在雷霆崖创建了新的家园。；但我绝对不会原谅那些将我们从世代相传的土地上赶走的家伙。我们在贫瘠之地的南部生活了数十年，这片土地对我们来说是神圣的。但我们却被为数众多的敌人赶了出去。；我要对卡尔加·刺肋这个恶棍进行报复，就是他在剃刀沼泽纠集了大批邪恶的部队，让我们背井离乡。；把他的精华给我带来，这样我才能安息，你。",o="把卡尔加·刺肋的精华交给雷霆崖的奥尔德·石塔。",r={{i=5793,n="卡尔加·刺肋的精华",c=1}},w={{i=4197,n="绿宝石护肩",c=1},{i=6742,n="石拳束带",c=1},{i=6725,n="石饰圆盾",c=1}},f=2},
  [1105]={t="硬化龟壳",d="我的兄弟正在为他的火箭车研究一种新燃料。他很聪明，真的，他真是太聪明了……我想他设计的新燃料一定非常强悍，甚至可以蚀穿车子的底盘！；为了防止这种情况的出现，我想应该要加固一下燃料箱。；这片平原上的乌龟有很硬的壳，我想用它们来制造火箭车的新燃料箱，这样就可以装载我兄弟的新燃料了。；你看起来很可靠，愿意去给我弄一些这样的壳吗？",o="收集9块硬化龟壳，把它们交给闪光平原的维兹尔·铜栓。",r={{i=5795,n="硬化龟壳",c=9}}},
  [1106]={t="流放者马特克",d="我正在研制一种新的发动机，它可以让赛车开得更快！快到飞起来！我只要有一个能承受重压的活塞就能够完成这个发动机了，但是之前所有的活塞样品试验都失败了，就因为活塞的质地不够硬！；我想有人知道怎么解决这个问题。；他叫流放者马特克，是个伟大的铁匠，他比任何人都更加了解金属的特性。把这封信交给他，我知道他能帮我！；但他在很远的地方，在艾泽拉斯大陆上的荒芜之地，和一个地精同住在一个营地里！；去找到他吧！",o="把菲兹尔·铜栓的信带给荒芜之地的流放者马特克。",r={{i=5827,n="菲兹尔·铜栓的信",c=1}}},
  [1108]={t="精铁碎片",d="我大老远地跑到这儿来并不是为了躲开什么人。你，如果你有足够的勇气，那么荒芜之地的矿藏绝对可以让你大发横财。；有一种被称作精铁的矿石，据说它具有很强的耐压和耐热性，这也许会对菲兹尔的车有所帮助。；但是我们需要进一步地确定。去帮我找些精铁的样品来测试它的特性吧。；真正的精铁矿石深藏在奥达曼，但荒芜之地的石窟穴居人身上常常带着一些矿石碎片，给我找一些这种矿石碎片来。",o="收集10块精铁碎片，把它们交给荒芜之地的流放者马特克。",p=1106,r={{i=5797,n="精铁碎片",c=10}}},
  [1109]={t="蝙蝠的粪便",d="就如你所见到的一样，$n，我们正要在皇家药剂师学会进行一个非常…嗯…有趣的实验。；作为这里的领导者，我的职责就是监管所有最具潜质的化学实验。所以说我总是梦想太多，时间太少！；你看上去是个擅长跑腿的$c，也许你可以帮我的忙。；我需要一种稀有的原料，这种原料只有在产于剃刀沼泽的一种罕见的蝙蝠身上才能找到。去剃刀沼泽帮我带回一些沼泽蝙蝠的粪便来，然后我们就可以开工了……",o="帮幽暗城的大药剂师法拉尼尔带回一堆沼泽蝙蝠的粪便。",r={{i=5801,n="沼泽蝙蝠的粪便",c=1}}},
  [1111]={t="码头管理员迪兹维格",d="满足人们的需要就是我的工作，现在那边的侏儒弟兄们需要一些零件。一星期前那些零件就已经运到棘齿城了，但我一直都没有时间去取货。；所以……你愿意替我跑一趟吗？到棘齿城去，将这张零件订单交给码头管理员迪兹维格——他很可能就在码头上忙活。；我的朋友，这些工作的报酬可是非常诱人的哦……",o="把克拉维尔的零件订单交给贫瘠之地棘齿城的码头管理员迪兹维格。",r={{i=5799,n="克拉维尔的零件订单",c=1}}},
  [1112]={t="给克拉维尔的零件",d="你，这是克拉维尔要的货。你把货交给他的时候记得转告他……如果他想要更多的特别订货，就必须得付更多的钱！",o="把克拉维尔的零件交给千针石林中闪光平原的克拉维尔·浓须。",p=1111,r={{i=5800,n="克拉维尔的零件",c=1}}},
  [1114]={t="侏儒的货物",d="既然手续齐备，那你就把这些零件带给菲兹尔·铜栓吧。他为此已经等待很久了——我相信他不会在意我从他那些零件中拿了点小东西……；当然我也不会和他提这件事情，这对于他来说只是九牛一毛而已，没什么意义。；相信我。",o="把精密赛车零件交给菲兹尔·铜栓。",p=1112,r={{i=5802,n="精密赛车零件",c=1}}},
  [1116]={t="沼泽中的梦境粉尘",d="你打听到的有关纳兹的消息真是帮了我一个大忙，你，确实帮了我一个大忙。既然你已经特意大老远地从闪光平原赶来……那么你是否愿意再多走些路呢？；在我想办法打听相关信息的时候，你何不去帮我收集一些东西呢？；嗯……怎么样？帮我找一些梦境粉尘吧，你可以在悲伤沼泽的幼龙和龙族的身上找到梦境粉尘。我很喜欢在鼻烟袋里放一点梦境粉尘！；给我弄些梦境粉尘来，你，我会用你需要的信息和你进行交换。",o="为藏宝海湾的克拉兹克收集10份梦境粉尘。",p=1115,r={{i=5803,n="梦境粉尘",c=10}}},
  [1117]={t="地精的谣言",d="看来我要好好对待自己了，把那瓶稀有的精灵葡萄酒送掉，然后开始减肥！但是我找到了一些你正在寻找的信息。；拿着这个，我写了一封信，其中包含了一些关于我们的朋友纳兹的有趣的事情。你可以随便怎么处理它——我自己去传播的话会很危险。；记住不要告诉任何人你是从哪里得到它的！",o="把地精的谣言带给千针石林中闪光平原的克拉维尔·浓须。",p=1116,r={{i=5804,n="地精的谣言",c=1}}},
  [1119]={t="赞吉尔的药剂和蠢人酒",d="我已经搞清楚怎样用赞吉尔的药剂和烈性酒来合成更强力的饮料了，我称它为蠢人酒。我知道这东西正是克拉维尔所需要的，但回头你别忘了告诉我它的效果到底如何。；还有，你，别把这东西放太久，赞吉尔的药剂对酒中的酵母有一种超乎寻常的影响，能让它迅速爆发出惊人的活力来，因此你也就无法长时间保持蠢人酒的新鲜了。",o="把蠢人酒交给千针石林中闪光平原的克拉维尔。",r={{i=5806,n="蠢人酒",c=1}}},
  [1122]={t="向菲兹巴布报告",d="蠢人酒的效果太妙啦！我打赌下一场比赛我们必胜，而且……我很想看看喝了那些酒的家伙们出丑！；眼下我只有一个任务交给你了——把这封信带给藏宝海湾的克兰克·菲兹巴布，他一定会很想知道这项试验是不是成功了。；而且我们希望以后能够得到更多的蠢人酒！",o="把蠢人酒试验报告交给石爪山脉藏宝海湾的克兰克·菲兹巴布。",r={{i=5807,n="蠢人酒试验报告",c=1}}},
  [1124]={t="废土",d="在安戈洛环形山以西，穿过西北部的山脊，是一片荒芜的土地——希利苏斯。很少有人知道，暗夜精灵曾在那里与一个邪恶而诡异的种族进行过一场恶战。邪恶最终被封印了，但是我怀疑它们正在蠢蠢欲动，想要让恐惧卷土重来……；去寻找我们派往希利苏斯的一名使者，莱耶·星击。他就在勇士之墓，那儿是在战争中牺牲的勇士们安息的地方。把这封信交给他，他就会信任你。",o="在希利苏斯的勇士之墓附近找莱耶·星击谈谈，把拉比恩的信交给他。",r={{i=17355,n="拉比恩的信",c=1}}},
  [1125]={t="南风村的灵魂",d="在我们的西南方有个悲惨的地方——南风村的遗迹。我们就从那里开始吧，你。；根据我所掌握的情报，那座村庄曾经是暗夜精灵在希利苏斯的基地。很久以前异种蝎群攻陷那里，并将其夷为一片废墟。我简直不敢去想象南风村被虫群吞没的恐怖景象……；那些饱受痛苦的德鲁伊和哨兵的亡魂在那座遗迹中漫无目标地游荡。探索那个地区，并释放那些悲惨的灵魂。",o="在南风村释放8个被折磨的德鲁伊和8个被折磨的哨兵的灵魂，然后向希利苏斯勇士之墓的莱耶·星击复命。",p=1124},
  [1126]={t="塔中之巢",d="我们必须找到南风村的异种蝎巢穴，而我知道有一个方法可以找到它。以我的经验来看，它们对于周围的环境很敏感，这也就解释了为什么它们会在听到灵魂的死亡嚎叫之后发起攻击。；塔里的异种蝎群最为强大——就是那座有很多飞虫围绕着的塔。爬上那座塔，然后骚扰虫巢。向我汇报你所发现的东西！如果你找到了什么有价值的东西，就把它带回来给我。",o="爬上南风村的塔，找寻激活异种蝎群的方法。把任何你认为不寻常的东西交给希利苏斯勇士之墓的莱耶·星击。",p=1125,r={{i=17346,n="异种蝎粘液包裹的物体",c=1}}},
  [1131]={t="钢齿土狼",d="有时我们为了食物而狩猎，有时我们为了荣耀而狩猎，而有时我们为了得到大地母亲的教诲而狩猎。；但是这次我让你去捕猎的却是一个例外中的例外，我要你去杀死一个不被大地母亲所祝福的生物。；这个名叫钢齿土狼的生物游走于贫瘠之地南面的千针石林，它是个残暴的统治者，它率领着其它的土狼，给原本平静的兽群带来恐惧和无谓的伤亡。；找到钢齿土狼，你，找到它，打败他。",o="把钢齿土狼的肋骨带给雷霆崖的梅洛。",p=1130,r={{i=5837,n="钢齿土狼的肋骨",c=1}}},
  [1135]={t="风巢双足飞龙的毒囊",d="你也许知道，兽人们通常会驯化双足飞龙以供骑乘之用。但很少有人知道，从某种角度来说，双足飞龙的毒液比它们本身更有价值。如果你不介意狩猎双足飞龙的话，那么……我有一项工作交给你。；在千针石林的西边有一个叫风巢的地方，生活在那里的双足飞龙的毒液不但毒性非常强烈，而且价值极高。",o="收集10个风巢双足飞龙的毒囊，把它们带给塞拉摩的菲欧拉·长耳。",r={{i=5809,n="风巢双足飞龙的毒囊",c=10}},f=1},
  [1136]={t="霜喉雪人",d="你，你现在得去跑一趟远路，而且我想你应该已经准备好了。；你的任务是去猎捕霜喉雪人，它是奥特兰克山里的一个雪人。霜喉雪人可不是那么容易就能被抓到的，因为它白色的毛皮与山中的皑皑白雪融合在了一起，很难分辨，而且它极少暴露自己。；不过现在我要教教你如何把像它这样的家伙给引诱出来。拿着这个卷轴，我已经在上面写好了诱捕霜喉雪人的方法。；现在就动身吧，你。你的旅途漫长而充满挑战。只有当你拿回霜喉雪人的鬃毛的时候，你的任务才算是完成了。",o="把霜喉雪人的鬃毛带给雷霆崖的梅洛·石蹄。",p=1131,r={{i=5811,n="霜喉的鬃毛",c=1}},f=2},
  [1137]={t="News for Fizzle",o="Speak with Fizzle Brassbolts in the Shimmering Flats.",p=1108,w={{i=6729,n="菲兹尔的折叠点火器",c=1},{i=6732,n="侏儒技师手套",c=1}}},
  [1138]={t="海中的水果",d="我爱螃蟹，螃蟹就好像是海中的水果！你可以把它烤了吃、煮了吃、炖了吃、炸了吃、炒了吃、煎了吃；你可以把螃蟹做成螃蟹色拉、螃蟹汤、螃蟹炖肉、黑胡椒螃蟹、柠檬汁炖螃蟹、清蒸螃蟹和铁炉堡特级螃蟹——这就是螃蟹存在的意义！；我现在要留在这里钓鱼，所以没有办法自己去找到上好的螃蟹肉。你可以从暗礁蟹和硬壳潮行蟹身上得到品质上乘的螃蟹肉，然后把它们烤了吃、煮了吃……",o="收集6块优质蟹肉，把它们交给奥伯丁的古博·布拉普。",r={{i=12237,n="优质蟹肉",c=6}},w={{i=15405,n="剥壳手套",c=1},{i=15406,n="甲壳长靴",c=1}},f=1},
  [1139]={t="意志石板",d="通过切断暗炉部族与黑石塔的联系，我们已经成功减缓了他们的行动。不过，铁趾的遗愿仍未完成，他不能就这么白白死去。他的梦想是要找到意志石板，那是一块注入了魔法能量的石头碎片。利用这种魔法，泰坦赋予那些由他们创造出来的物体以鲜活的生命，甚至将思想和意志赐予这些生命。；我们必须赶在暗炉部族之前找到意志石板。；返回奥达曼去找到石板，然后立刻回到这里。",o="找到意志石板，把它们交给铁炉堡的顾问贝尔格拉姆。",p=762,r={{i=5824,n="意志石板",c=1}},f=1},
  [1140]={t="奥萨拉克斯之塔",d="兽人们写起字来比小孩子的涂鸦好不到哪里去。当我决定去学习他们的语言时，我的许多部下都曾经取笑过我，但我想这样做还是有助于进一步了解我们的敌人。；从伊克鲁德的乱七八糟的文字中，我们可以知道埃瑟里克斯仍掌握着两颗灵魂宝石，它们分别在灰谷东北部的夜道谷和萨提纳尔，这两个地方都是被萨特控制的地区。；千万小心点，$n，面对那些被萨特之血浸透了地面的神殿，即使是像你这样经验丰富的$c也会心神不宁的。",o="在夜道谷和萨提纳尔找到被禁锢的上层精灵的灵魂，释放它们，然后回到迈斯特拉岗哨的净化者德尔格伦那里。",p=973},
  [1141]={t="钓鱼世家",d="布拉普系列一向以酷爱钓鱼而闻名。我的名字叫古博·布拉普，我在钓鱼。；在这个地区我最希望钓到的鱼是黑海岸石斑鱼。以前我会坐船出海专门钓这些石斑鱼，但是由于那些该死的鱼人的出现，我已经很久没有出海钓鱼了。我打赌那些鱼人早把这里的石斑鱼给吃光了。；那么说来，你愿意帮我抓一些黑海岸石斑鱼回来？如果你愿意的话，我可以给你一把货真价实的布拉普系列鱼竿！这根鱼竿可是钓鱼时的乘手工具啊！",o="为奥伯丁的古博·布拉普抓6条黑海岸石斑鱼。",r={{i=12238,n="黑海岸石斑鱼",c=6}},f=1},
  [1142]={t="临终遗言",d="我现在很虚弱……没…没多久可活了。；……那个勇…勇敢的矮人，亨里格·独眉，已经被派去警…警告法芬德尔了……；但…我死…死之前……；……我的妻子，塔莎拉……我们两人定情的坠饰…被…那群卑鄙的入侵者…偷走了……；拜……拜托你，找到它……把它还给在达纳苏斯的塔莎拉……；……还有……告诉她……我爱她……",o="将塔莎拉的坠饰带给达纳苏斯的塔莎拉·静水。",r={{i=5825,n="塔莎拉的坠饰",c=1}},w={{i=6751,n="悲伤披风",c=1},{i=6752,n="枪骑兵战靴",c=1}},f=1},
  [1143]={t="奥萨拉克斯之塔",d="我知道了。如果你所说的是真的，那么我们必须马上发起进攻。我认为埃瑟里克斯就住在塔上。不过你要当心，在他的周围有很多强大的术士，比你以前所见到过的任何术士都还要可怕。",o="杀掉埃瑟里克斯·纳拉辛，把他的徽记交给奥萨拉克斯之塔附近的巴苏尔·影击。",p=1167,r={{i=5383,n="埃瑟里克斯·纳拉辛的徽记",c=1}}},
  [1144]={t="Willix the Importer",o="Escort Willix the Importer out of Razorfen Kraul.",w={{i=6748,n="猴子戒指",c=1},{i=6750,n="蛇环",c=1},{i=6749,n="猛虎指环",c=1}}},
  [1145]={t="疯狂的虫群",d="许多路过十字路口的旅行者都曾帮助过我从巨人旷野收集虫卵，他们大都知道那里的生物有多么可怕。我们现在有足够的证据说明，那里的昆虫远远比我主人想象中的还要可怕。；我需要有一个信使到奥格瑞玛去找贝尔戈洛姆·石槌。这个任务并不简单，你必须要严肃地对待这个任务。；贝尔戈洛姆一般就在战士公会外面。",o="把科兰的密信交给奥格瑞玛的贝尔戈洛姆·石槌。",r={{i=5846,n="科兰的密信",c=1}}},
  [1146]={t="疯狂的虫群",d="这么说，科兰对这些昆虫得出和我相同的结论了——它们的威胁确实比我预想的要大。；几天前有一个从千针石林回到我这儿的猎人受了重伤，现在情况非常危急。他是和一个突击队一起被派去执行任务的，本来他们要将一个矮人挖掘队从闪光平原驱逐出去，但是在行动中，许多这种昆虫从挖掘场的一个岩洞里倾巢而出，几乎使突击队全军复没。；突击队是由摩克塔·克林率领的，现在他们正在闪光平原的边境上寻求庇护。把我的这封信交给他吧。",o="把贝尔戈洛姆的密信交给千针石林的摩克塔·克林。",p=1145,r={{i=5850,n="贝尔戈洛姆的密信",c=1}}},
  [1148]={t="虫群的样本",d="你仔细观察着这个壳。当你把它拿在手中翻来复去观察的时候发现它的构造很复杂，这让它变得异常坚固。这个壳不同于你所见过的任何东西。你进一步检查尸体，发现这些生物非常有力，而且进化程度也很高。；再看看这个壳，你想科兰应该会有兴趣进一步研究这些生物。这可以帮他搞清楚它们到底是什么，以及它们是从哪儿来的。",o="收集1颗异种蝎的心脏、5只异种蝎的爪子和3个完整的异种蝎壳，把它们和你手中的这个破碎的异种蝎壳一起交给十字路口的科兰。",r={{i=5855,n="异种蝎的心脏",c=1},{i=5854,n="异种蝎的爪子",c=5},{i=5853,n="完整的异种蝎壳",c=3}}},
  [1149]={t="信仰的试炼",d="你已经找到我了——或者是命运把你带到了我这儿，不管怎么样，现在你来到了这里，一段新的旅程即将开始。；生命是由多种要素构成的：精神，身体，思想。某些要素可以由它所属的文化传统来衡量，而某些要素……我们就只能期望是自己与生俱来的特质了。如果你同意的话，我将要求你进行针对这些要素的试炼。；如果你通过了这些试炼，你将变得更为强大。如果你没通过，你也许会感受扭曲虚空的黑暗。；第一个试炼就是信仰的试炼。",o="如果你有坚定的信仰，就从那个可以俯瞰千针石林的木板跳下去。"},
  [1150]={t="耐力的试炼",d="我很高兴看到你的勇气依然不减。既然你的信念已经不可动摇，那么现在就让我们来对你的体能进行试炼吧。；首先是耐力的试炼。到乱风岗西边的飞羽洞穴去一趟，进入那些鹰身人的巢穴最深处，毁掉它们的粮食储备rn。那样肯定会让它们勃然大怒，如果你能够在鹰身人的围攻之中生存足够长的时间，那么格林卡·血啸就会亲自出来对付你——杀了她，把她的爪子带给我，以此来证明你完成了试炼。",o="把格林卡的爪子交给千针石林的多恩·平原行者。",p=1149,r={{i=5843,n="格林卡的爪子",c=1}}},
  [1151]={t="力量的试炼",d="在远古之神的时代，元素生物主宰着世界。他们崇拜远古之神，这些神灵用他们的力量将元素生物和世界紧密地结合了起来。当远古之神消失时，元素生物便从我们的世界上消失了，现在只有非常强大的法师才能将它们召唤回来。；当然万事皆有例外，有些元素生物很强大，足以凭自己的力量在这个世界上生存，其中一个就是罗卡里姆。；为了通过力量试炼，你必须在千针石林里找到罗卡里姆，然后杀了它。",o="把罗卡里姆的碎片交给千针石林的多恩·平原行者。",p=1150,r={{i=5844,n="罗卡里姆的碎片",c=1}}},
  [1153]={t="新的矿石样本",d="玩家，你过去帮我做了不少事情。酋长对我所完成的工作非常满意，并且要求我继续负责这里的一系列任务。我在酋长面前对你的作为大加赞赏，现在我要再次请求你的帮助。；近来有一批旅行者从南方过来，他们在一个被称为千针石林的地方杀死了一个狗头人，从它身上得到了一块非同寻常的矿石，但这些旅行者不想卖掉它。我想要弄到一个那样的矿石样本来进行研究。",o="从砂齿掘地工或砂齿勘探员那里找一块未精炼的矿石样本，把它交给陶拉祖营地的塔特纳克·钢炉。",p=893,r={{i=5842,n="未精炼的矿石样本",c=1}},f=2},
  [1154]={t="知识试炼",d="你已经通过了多恩的试炼，现在你想通过下一个试炼了。非常好。但是到当前为止，你面对过的挑战还都是小儿科。锻炼你的身体很容易，但锻炼你的思想就完全是另外一回事了。；让我来简单地解释一下：找到我说的那本书，研究它，然后回答我提出的关于其内容的问题。；你一定会问是哪本书？是《巨龙的遗产》。它在灰谷南部的朵丹尼尔的底部，被死去的德鲁伊和杀害他们的凶手保护着。",o="找到《巨龙的遗产》，把它还给位于灰谷和石爪山之间的石爪小径里的布劳格·幽魂。",p=1152,r={{i=5860,n="巨龙的遗产",c=1}}},
  [1160]={t="知识试炼",d="我会告诉你必须去寻找的东西，我还会向你提出我的问题，但我做这些并不是因为你想证明你自己。知识远比力量重要，即使别人在能力上超越了你，你对世界的认知也会让你更胜一筹。；到提瑞斯法林地北部的修道院去一趟，在那儿的图书馆里有一本名叫《亡灵的起源》的书，它曾被那些现在已经堕落了的圣骑士用来对抗我们。；把这本书给我拿来。",o="找到《亡灵的起源》，把它交给幽暗城的帕科瓦·芬塔拉斯。",p=1159,r={{i=5861,n="亡灵的起源",c=1}}},
  [1164]={t="科娜塔一家",d="贱人！猪头！科娜塔竟然还活着！我在这里受苦受难，她居然全家和睦健康，人丁兴旺的。我被她抛弃了！；我已经没有家了，他们都被天灾带走了。我的财产也都在战争中被抢光烧光了。这些也就算了，然而就是她和她的那些野种们，竟然厚着脸皮趁我不在的时候偷走了我家最后一件值钱的东西。；我倒是不再关心那些被偷的东西了。现在我要的是他们的徽记！；到阿拉希高地去，避难谷地的东北方有一个达比雷农场，去那里把他们都干掉！",o="将科娜塔、法迪尔和马塞尔的徽记交给幽暗城的吉纳维·卡隆。",r={{i=5830,n="科娜塔的徽记",c=1},{i=5832,n="马塞尔的徽记",c=1},{i=5831,n="法迪尔的徽记",c=1}},w={{i=4443,n="恐怖肩铠",c=1},{i=2032,n="迦兰护腕",c=1}},f=2},
  [1166]={t="莫格穆洛克的任务",d="向莫格穆洛克大王鞠躬致敬吧！；是雷克萨让我做了石槌氏族的领袖！；我是个好领袖，是我保卫氏族安全。；大龙来了，烧了我们的家园，是我这么个有头脑的食人魔在这儿给氏族找了个新家。；离开原来的家的时候太匆忙，我忘了点东西。小$r，去把我的东西拿来。往南走，去拿回我的烈酒、鼻烟和保险箱。你做好了我就会喜欢你。",o="蕨墙村的莫格穆洛克大王要你从石槌废墟拿回他的烈酒、鼻烟和保险箱。",r={{i=5834,n="莫格穆洛克的鼻烟",c=1},{i=5835,n="莫格穆洛克的烈酒",c=1},{i=5836,n="莫格穆洛克的保险箱",c=1}},f=2},
  [1168]={t="黑龙军团",d="雷克萨让莫格穆洛克做大王。莫格穆洛克只知道权力，很少关心食人魔。；黑龙杀了很多食人魔，还杀了萨尔格的妻子。莫格穆洛克叫我们逃跑，让我们到这儿来。；食人魔应该战斗。食人魔不逃跑。莫格穆洛克只关心他自己。；我只把石槌村叫做家。我喜欢南边。；帮食人魔打黑龙军团。我们要复仇。我们要回家。",o="蕨墙村的萨尔格要你去杀掉10个火鬃斥候，10个火鬃灰尾龙人和5个火鬃守卫。",w={{i=9705,n="萨尔格的鞋带",c=1},{i=9706,n="萨尔格的碟子",c=1}},f=2},
  [1169]={t="群龙之首",d="莫格穆洛克那个懦弱的傻瓜只知道权力，他整日和萨尔格争夺着氏族的领导权，大概只有我才在想着要找出袭击我们以前家园的邪恶势力的源头。；干嘛用这种疑惑眼神看我，$n？你以为我会像个粗俗的混蛋那样说话吗？就因为我是个食人魔？；说正事吧，从那些大尺寸小的黑龙身上弄些心脏和舌头回来给我，也许我可以找出这邪恶的源头。",o="蕨墙村的德拉兹辛比要你给他收集7条灼热之舌和7颗灼热之心。",r={{i=5840,n="灼热之舌",c=15},{i=5841,n="灼热之心",c=15}},w={{i=9703,n="烧焦的斗篷",c=1},{i=9704,n="盗马贼手套",c=1}},f=2},
  [1172]={t="奥妮克希亚的血脉",d="黑龙谷到处都是奥妮克希亚的子嗣，决不能让它们继续繁殖下去了！；赶紧到尘泥沼泽南部的巨龙沼泽去，那儿肯定是奥妮克希亚的巢穴。找到那里的龙蛋，把它们给毁了。；如果他们还在不断滋生，我们就别想夺回石槌村。；至于莫格穆洛克这个家伙……我自有办法。",o="蕨墙村的德拉兹辛比要你去毁掉5枚奥妮克希亚的蛋。",p=1171,w={{i=10700,n="绘饰之靴",c=1},{i=10701,n="苏泰克之靴",c=1}},f=2},
  [1173]={t="挑战莫格穆洛克",d="你竟敢挑战莫格穆洛克？；啊啊啊啊啊啊啊！；我来踩扁你这个小$r！；什么时候准备好挨揍就告诉我。",o="打败莫格穆洛克，再把消息带给蕨墙村的德拉兹辛比。",p=1172,w={{i=10703,n="恶魔匕首",c=1},{i=10704,n="冰指碎片",c=1}},f=2},
  [1176]={t="减轻负重",d="说到赛车，每一点都很重要！不论是动力输出的调整，压力线圈的松紧，或者是对于整部机车重量的控制，每一项都很关键，所以你必须考虑所有的东西。；我们用秃鹫的骨头对赛车进行了改造，这样就提供了力量与重量的完美平衡，真棒。更棒的是，我们可以很容易地得到更多的秃鹫骨头，因为这一带到处都是秃鹫。；去帮我找一些秃鹫骨头来，我会给你个好价钱的。",o="给闪光平原的普兹克找10根空心秃鹫骨。",r={{i=5848,n="空心秃鹫骨",c=10}}},
  [1177]={t="饿！",d="马德是大食人魔。；我饿了。；去抓点鱼来。给马德找吃的。；你喂饱马德，不然马德就吃你。",o="尘泥沼泽北部的马德克拉什要你去抓8条泥鳍小鱼。",r={{i=5847,n="泥鳍小鱼",c=8}},w={{i=9518,n="泥泞手套",c=1},{i=9519,n="踏泥草靴",c=1}}},
  [1182]={t="地精赞助商",d="瞧，纳菲瑞提湖那边的地精风险投资公司的伐木机上都装备了最新型号的燃料调节器。我觉得，普兹克要是能拿到调节器的详细设计图，一定可以善加利用它。糟糕的是，那边的工头比我预计的要精明得多，要取得设计图似乎并不容易。；你看起来应该有能力去拿到那张设计图。据我所知，他把那些东西都锁在了屋子里。",o="将燃料调节器的蓝图交给藏宝海湾的大财主里维加兹。",p=1181,r={{i=5852,n="燃料调节器的蓝图",c=1}}},
  [1183]={t="地精赞助商",d="你现在就赶快出发吧。替我向普兹克问好，顺便告诉他，如果他需要什么东西，就尽管跟我说。我期待着他能马上打破记录！",o="把燃料调节器的蓝图带给闪光平原的普兹克。",p=1182,r={{i=5852,n="燃料调节器的蓝图",c=1}}},
  [1184]={t="Parts of the Swarm",o="Return to Belgrom Rockmaul in Orgrimmar.",p=1148,w={{i=6737,n="枯叶短裤",c=1},{i=6738,n="血色月牙刀",c=1}},f=2},
  [1187]={t="拉泽瑞克的调整",d="我知道，普兹克是个伟大的机械师，但是他不敢加大油门赶超别人。但我不像他那么胆小。；在普兹克赛车的设计完成后，我花了点时间做了一些小小的修改。把控制器松一松，改造某些结构，增加更多的润滑剂，诸如此类。；我从加基森的史瑞夫那里订了一个爆盐增压器，但是那运货的飞艇却一头栽进了尘泥沼泽！$n，帮我去把东西取回来吧！",o="为闪光平原的拉泽瑞克取回爆盐增压器。",p=1186,r={{i=5862,n="爆盐增压器",c=1}}},
  [1188]={t="安全第一",d="等等，这是怎么回事？史瑞夫打开了保险装置？这样会限制推进器的输出功率的。我说过那个装置要关掉！对我来说开着那东西一点好处也没有！；你必须把这个拿到塔纳利斯沙漠中的加基森去，让史瑞夫把那该死的保险装置给我拆了。",o="把塔纳利斯爆盐增压器交给加基森的史瑞夫。",p=1187,r={{i=5862,n="爆盐增压器",c=1}}},
  [1189]={t="安全第一",d="看，我已经按照拉泽瑞克的要求去做了。我跟他说过，在关闭安全装置时要当心点，否则即使是最小的错误也会酿成大错，轻则让整辆赛车无法移动，重则把他直接在车里烧成灰。；如果真的那样的话可就太丢人了，我们到哪里去找第十九个愿意入伙的赛车手呢？",o="将改进型爆盐增压器还给千针石林闪光平原的拉泽瑞克。",p=1188,r={{i=5865,n="改进型爆盐增压器",c=1}},w={{i=6726,n="拉泽瑞克的安全带",c=1},{i=6727,n="拉泽瑞克的赛车手套",c=1}}},
  [1195]={t="神圣之火",d="千针石林的加拉克半人马一直在保护着一件神器，它的历史可以追溯到半人马刚刚在这片土地上出现的时候。；我们要得到它，但我们必须得有一瓶来自于暗夜精灵月亮井的水。；要取水还必须找一个特殊的瓶子，在灰谷森林中心地带靠近林中树居一带出没的树妖或许就有这种瓶子。在靠近弗伦河西岸的大路南面有一口月亮井，你可以在那里装满水，然后把它带回来给我。",o="把装满水的蚀刻瓶交给雷霆崖的赞金·石蹄。",r={{i=5868,n="装满水的蚀刻瓶",c=1}}},
  [1196]={t="神圣之火",d="把这装满水的蚀刻瓶给乱风岗的劳恩·峭壁行者带去吧。你可以搭乘贫瘠之地南部边境的升降梯去千针石林。",o="把装满水的蚀刻瓶交给乱风岗的劳恩·峭壁行者。",p=1195,r={{i=5868,n="装满水的蚀刻瓶",c=1}}},
  [1197]={t="神圣之火",d="你找来的水可以暂时浸湿守护半人马遗物的火焰，但是效果不会持续很久，所以你必须行动迅速。；半人马的要塞——加拉克峭壁——就在这里的北边，火焰就保存在那座重兵把守的要塞中。；小心点，加拉克半人马的数量众多，他们决不会轻易放弃如此珍贵的东西。",o="拿到裂开的蹄子，把它交给乱风岗的劳恩·峭壁行者。",p=1196,r={{i=5869,n="裂开的蹄子",c=1}},w={{i=6739,n="峭壁行者之弓",c=1},{i=6740,n="碧蓝腰带",c=1}},f=2},
  [1199]={t="暮光之锤的末日",d="通过祭祀上古之神的古代仪式，暮光之锤的成员获得了强大而混乱的力量，这些信徒正在试图唤回他们黑暗的主人，在这个世界上继续传播死亡与恐惧。；现在我们可以确信，暮光之锤已经和纳迦结成了联盟，集结在灰谷海岸边的黑暗深渊中。；我们必须阻止他们在那座古代神殿的深处所筹划的险恶计划。；向暮光之锤发起攻击，然后带回你的战利品，我们会重重酬谢你所做的一切。",o="收集10个暮光坠饰，把它们交给达纳苏斯的银月守卫玛纳杜斯。",r={{i=5879,n="暮光坠饰",c=10}},f=1},
  [1200]={t="黑暗深渊中的恶魔",d="力量在我身上逐渐流失，我需要你的帮助！；很久以前，这里曾是雄伟的月神之殿。然而，不幸却降临了这里，上古之神的堕落势力从地下突现，玷污了神圣的月亮井，最终使得这里成为了一片废墟。；阿库麦尔，上古之神的仆人，从水中突然出现。；暮光之锤的信徒与纳迦联合在一起，占领了这片土地。梦游者克尔里斯领导着他们为阿库麦尔而战，以许多无辜的生命来换取邪恶的力量。；你一定要阻止这些恶魔！杀了克尔里斯，把他的徽记交给达纳苏斯的塞尔高姆！",o="把梦游者克尔里斯的徽记交给达纳苏斯的哨兵塞尔高姆。",p=1198,r={{i=5881,n="克尔里斯的徽记",c=1}},w={{i=7001,n="墓碑节杖",c=1},{i=7002,n="极光圆盾",c=1}},f=1},
  [1201]={t="塞拉摩间谍",d="部落和联盟正处于某种令人不安的休战期。两大阵营之间的小规模的冲突和暗杀活动时有发生，而我们的职责就是确保部落始终占据上风！；现在正是行动的时候。；联盟派了一些间谍驻扎在蕨墙村的东部，他们监视着村子，把我们的动向报给告塞拉摩，决不能让他们继续下去。；去追踪那些间谍，把他们干掉。让他们的头儿知道我们决不会允许他们的间谍在我们面前晃来晃去！",o="杀掉9个塞拉摩间谍，然后回到蕨墙村去见纳泽尔·血矛。"},
  [1203]={t="加尔的剑",d="我要切点东西，呃……我不能告诉你我要切什么，不过……反正我需要把剑。一种特殊的剑……；我叫它快剑。；你能帮帮我吗？那些鱼人，你知道，像鱼的人，像人的鱼，它们之中有一个名叫刺脊的，手里有一把巨剑，它就在这里北边的海滩附近。；不过，不要等到明天再去找。我切的东西可不能放太久……",o="将刺脊的剑交给尘泥沼泽的“沼泽之眼”加尔。",p=1206,r={{i=3853,n="月钢宽剑",c=1}}},
  [1204]={t="泥石龟蟹汤",d="我正在研究一道叫作“泥石龟蟹汤”的菜，现在我还需要一些原料……唉，我觉得我真是不适合在尘泥沼泽里长途跋涉！；那么，你，你能帮我去打猎吗？首先，我需要泥石龟的舌头，这些海龟经常在海岸附近出没。；不过我要的还不是一般的舌头！听说有些泥石龟的舌头是分叉的……；他们说那样的舌头吃起来味道特别好，而且我也很喜欢给我的菜里加点特别的风味……",o="给塞拉摩的摩根·斯特恩收集8个分叉的泥石龟舌。",r={{i=5883,n="分叉的泥石龟舌",c=8}}},
  [1206]={t="加尔和蜘蛛眼",d="用眼睛制成饮料的味道非常好，可惜很多生物都只有两只眼睛。；不过蜘蛛有很多眼睛，很多很多。黑雾蛛眼汁很好喝，醇美而味咸！真是没有比那更好的饮料了……；黑雾蜘蛛就在西边的黑雾洞穴里活动。你说这些蜘蛛的名字是来自这个洞的名字呢，还是有别的什么说法？",o="收集20颗黑雾蜘蛛的眼球，把它们交给水光庄园的“沼泽之眼”加尔。",p=1218,r={{i=5884,n="黑雾蜘蛛的眼球",c=20}}},
  [1218]={t="沼泽蛙的腿",d="我喜欢烧菜，喜欢沼泽地里特产的美食，比如油炸绿青蛙腿之类的。；不过青蛙腿都用完了。不过庄园附近到处都是青蛙。肥肥的沼泽青蛙。你觉得你能帮我弄些青蛙腿吗？很简单，只需要殴打它们的脑袋，帮我带回蛙腿就可以了。；然后我就可以做出好吃的东西来，好好地饱餐一顿，还能给你一些。；你想尝尝吗？",o="为尘泥沼泽的“沼泽之眼”加尔收集10条沼泽蛙的腿。",r={{i=3713,n="舒心草",c=3}}},
  [1219]={t="兽人的报告",d="你可以在松土里看到一只紧紧握起来的兽人的手，手里抓着一根用骨头刻出来的管子，里面塞着一张粘着泥土的羊皮纸。；羊皮纸上的文字都是兽人的文字……这看上去很重要。",o="把间谍的报告交给塞拉摩的艾登中尉。",r={{i=5917,n="间谍的报告",c=1}}},
  [1238]={t="遗失的报告",d="你可以在松土里看到一只紧紧握起来的兽人的手，手里抓着一根用骨头刻出来的管子，里面塞着一张粘着泥土的羊皮纸。；羊皮纸上是一个在塞拉摩侦察了好几个星期的兽人写的报告。；浏览过羊皮纸之后，你决定立刻把它送给蕨墙村的兽人情报官。",o="把间谍的报告交给蕨墙村的纳泽尔·血矛。",r={{i=5917,n="间谍的报告",c=1}}},
  [1239]={t="被取下的徽记",d="继续挖掘了一番之后，你找到了一颗男性兽人的徽记，上面还有参差不齐的划痕。",o="把兽人的徽记交给蕨墙村的纳泽尔·血矛。",p=1238,r={{i=5918,n="兽人的徽记",c=1}}},
  [1240]={t="巨魔巫医",d="我们必须弄清楚玛格究竟是怎么死的！唯一的方法就是使用巨魔的巫术。把玛格的徽记拿给肯维雷，他就在荆棘谷的格罗姆高营地里。；肯维雷是暗矛巨魔里最强的巫医，能和玛格·夜眼的灵魂说话的人也只有他了。",o="把兽人的徽记带到荆棘谷的格罗姆高营地里，交给肯维雷。",p=1239,r={{i=5918,n="兽人的徽记",c=1}}},
  [1241]={t="失踪的使节",d="最近我们派出了一名外交使节转至塞拉摩与吉安娜·普罗德摩尔女士会晤，但那位使节没能抵达目的地。；我坚信是迪菲亚兄弟会密谋了这个事件，但我并不清楚具体的过程。使节失踪的消息对外严密封锁，但这件事情迟早要被曝光。；国王的密探已经行动起来，在全城范围内寻找线索，但我打算私底下再找一些人来解决此事。；我的一个老朋友乔贞现在就在英雄谷中。将这封便笺带给他，然后听他的命令行事。",o="在暴风城的英雄谷找到乔贞。",p=1274,r={{i=5948,n="写给乔贞的信",c=1}}},
  [1242]={t="失踪的使节",d="把这张便笺带给埃林·提亚斯，除此以外不要和他说任何话。你只需要礼貌地等着他的回答就是了。不用担心，他一定会回答你的。；我必须再跟你清清楚楚地说一遍，你：把这件事看得认真点，在任何人面前都要管好你的嘴。；你可以在他的奶酪店“提亚斯奶酪坊”里找到他，就在贸易区。祝你好运。",o="将乔贞的密信带给暴风城贸易区的埃林·提亚斯。",p=1241,r={{i=5946,n="给埃林的密信",c=1}}},
  [1243]={t="失踪的使节",d="乔贞，你这老小子……那么，事情就是这样了，是吧？；好吧，我会处理的。我倒是希望他早点死了呢！；这么着，你。我会开始派出我在这里的线人，不过你得帮我跑跑腿，好给我省点钱。；到暮色森林的夜色镇去找守夜人巴库斯——他总是在镇子北边的路上巡逻。告诉他你正在为我调查迪菲亚兄弟会的活动，他会把他知道事情一股脑儿都告诉你的。",o="将密信带给暮色森林的守夜人巴库斯。",p=1242,r={{i=5960,n="给守夜人巴库斯的密信",c=1}}},
  [1244]={t="失踪的使节",d="迪菲亚兄弟会的活动？好吧，他们总是在活动。就算他们按兵不动，我们也仍然视之为威胁。；但现在我认为，最近事情变得有点奇怪。大概是在两三周前吧，他们的许多密探都在腐草农场附近频繁出没。由此看来，那里一定是发生了什么重要的事情。；你为什么不先去那里调查调查呢？记得把你调查到的结果拿给我看看。；那座农场就在由西部荒野进入暮色森林的大路南边。",o="找到迪菲亚记事本，把它带回给暮色森林的守夜人巴库斯。",p=1243,r={{i=5947,n="迪菲亚记事本",c=1}}},
  [1245]={t="失踪的使节",d="哎呀，如果这只是个用来干扰你的视线的幌子，那他们也未免搞得太复杂了，我也不太清楚这东西到底是什么。把它交给提亚斯吧——他一定能弄明白其中的意义。千万小心，别让任何人把它抢走。我们都知道，这事可比我的命还重要，甚至比他的命还要重要。；最后，拜托你一件事，你，别对任何人说起我帮助过你。我的上司如果知道我对这件事有所了解而又没有向他们汇报的话，没准会绞死我的。",o="将迪菲亚记事本带给暴风城的埃林·提亚斯。",p=1244,r={{i=5947,n="迪菲亚记事本",c=1}}},
  [1249]={t="失踪的使节",d="你说是埃林派你来的？好吧，现在我要拿出十倍的热情来招待你。想要什么尽管说，我会竭尽全力来帮助你的。；嗯，你说的是干柴？似乎是没听说过的名字，但我一定会注意他的。；别抬头，你，壁炉旁边的那家伙正往我们这边看呢。这家伙似乎有点太专心地听我们的对话了，你明白我的意思吗？如果我是你，我就会趁他溜走之前好好教训教训他。",o="在塔伯克·贾恩逃跑前制服他，然后回米奈希尔港旅店去找米克哈尔。",p=1248},
  [1251]={t="黑色盾牌",d="有一面被烧毁旅店的大火熏黑了的铁盾牌和倒塌的烟囱连在一起，这根烟囱是树荫旅店烧毁之后留下的几段残砖断瓦中的一部分。；这面铁盾牌可以从烟囱的砖上拿下来。",o="把被熏黑的铁盾牌带给蕨墙村的克罗格。",r={{i=5919,n="被熏黑的铁盾牌",c=1}}},
  [1252]={t="帕瓦尔·雷瑟上尉",d="地上闪过的一道光芒把你的视线引到碎石的下面。你拨开了碎石，发现灰尘下有一枚白色的徽章，表面上印有金色的船锚，那是塞拉摩的标记。；锚的下面刻着“帕瓦尔·雷瑟上尉”的字样。",o="把雷瑟的徽章拿给塞拉摩的盖兰·维米斯队长。",r={{i=5950,n="雷瑟的徽章",c=1}}},
  [1253]={t="黑色盾牌",d="有一面被烧毁旅店的大火熏黑了的铁盾牌和倒塌的烟囱连在一起，这根烟囱是树荫旅店烧毁之后留下的几段残砖断瓦中的一部分。；这面铁盾牌可以从烟囱的砖上拿下来。",o="把被熏黑的铁盾牌交给塞拉摩的盖兰·维米斯队长。",r={{i=5919,n="被熏黑的铁盾牌",c=1}}},
  [1258]={t="还有螃蟹！",d="新菜谱里还需要一种大螃蟹的腿，不过尘泥沼泽的污壳螃蟹可不行！唯一合适的螃蟹在悲伤沼泽里，离这儿很远。；螃蟹腿的壳是构成这道菜的外观的一大要素，所以我必须要新鲜而且没有任何疤痕的蟹腿。一只成熟螃蟹大概只有一条或两条这样的腿，而我却需要大量的螃蟹腿来试验菜谱。；那么，你……你愿意跑一趟吗？",o="给塞拉摩的摩根·斯特恩收集12根新鲜的螃蟹腿。",p=1204,r={{i=5938,n="新鲜的螃蟹腿",c=12}},f=1},
  [1261]={t="玛尔格的嘱托",d="可恶的龙虾人！我是不会束手待毙的！啊…但是…我已经死了，看来它的确是把我杀掉了……；但是我的使命，我的使命啊！你，你必须替我完成它。；我曾在塞拉摩附近监视一队在海滩上露营的联盟士兵，其中一个士兵身上配戴着一件饰品，是那种镶嵌着很多宝石，再有钱的士兵也买不起的饰品！；那天晚上，我溜进他们的营地，偷走了那件饰品，但是在我返回基地的途中，一个污壳龙虾人杀死了我！；你，你必须找到那只该死的龙虾人，并夺回那件饰品。",o="把宝石坠饰带给蕨墙村的纳泽尔·血矛。",p=1240,r={{i=5942,n="宝石坠饰",c=1}}},
  [1262]={t="向佐尔报告",d="很奇怪的是，玛尔格偷取的这件饰品居然是一个普通士兵的东西。它的主人也许掩饰了自己真正的身份，或者那个士兵本身就是个窃贼！；不管事实是怎样的，总之这是一件贵族的饰品。如果我们想要揭开这个谜团，就必须找出它真正的主人。；带着饰品去奥格瑞玛找佐尔·孤树吧。他对联盟那边的事情颇有了解，应该会知道这件饰品是否和暴风城的贵族们有关系。",o="把镶宝石饰品带给奥格瑞玛的佐尔·孤树。",p=1261,r={{i=5942,n="宝石坠饰",c=1}}},
  [1265]={t="失踪的使节",d="亨德尔？是的，我知道这个人。不过你找我的士兵有什么事呢？；埃林派你来找他？嗯，好吧，我感觉有些不妙了。你肯定遇到了麻烦，因此埃林才让你来先找我的。我理解你可能不愿告诉我详情，但请明白这一点：我有责任保护好这片土地。如果你是来制造麻烦的话，最好能先得到我的允许。；据我所知，亨德尔就驻守在塞拉摩外的第一座哨塔上。请自己多加小心！",o="在警戒哨岗中打探亨德尔下士的消息。",p=1264},
  [1267]={t="The Missing Diplomat",o="Speak to Jaina Proudmore in Dustwallow Swamp.",p=1324,f=1},
  [1269]={t="帕瓦尔·雷瑟上尉",d="地上闪过的一道光芒把你的视线引到碎石的下面。你拨开了碎石，发现灰尘下有一枚白色的徽章，表面上印有金色的船锚，那是塞拉摩的标记。；锚的下面刻着“帕瓦尔·雷瑟上尉”的字样。",o="把雷瑟的徽章带给蕨墙村的克罗格。",r={{i=5950,n="雷瑟的徽章",c=1}}},
  [1273]={t="盘问雷瑟",d="我花了很长时间终于找到雷瑟了。他躲藏得很好。；奥格隆担心他在沼泽地里待了这么久可能已经疯了，你跟我来，咱们一起去从他那里套出一些我们需要的答案。",o="和奥格隆一起去和雷瑟谈一谈，然后回到蕨墙村见克罗格。",p=1269,w={{i=6797,n="啄眼者",c=1},{i=6798,n="爆破火枪",c=1}},f=2},
  [1275]={t="研究堕落",d="愚蠢的血精灵们已经彻底陷入了对魔法的狂热之中了，难道他们没有见到卡利姆多大陆上的萨特与纳迦们身上发生了些什么吗？；我总觉得血精灵们也将会踏上这样一条不归之路，但是艾泽拉斯已经无法再承受多一种被魔法扭曲了心智的怪物了。；我希望能够研究一下萨特和纳迦的脑干组织，这样也许就能了解那些精灵们的命运将会走向何方。在灰谷海岸边的黑暗深渊中有许多萨特和纳迦，你去那里找一找吧。；这将会是一段漫长的旅程，一路小心，$n。",o="奥伯丁的戈沙拉·夜语需要8块堕落者的脑干。",r={{i=5952,n="堕落者的脑干",c=8}},w={{i=7003,n="虫壳护腕",c=1},{i=7004,n="教士斗篷",c=1}},f=1},
  [1318]={t="Unfinished Gordok Business",o="Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.；According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of t",r={{i=18336,n="戈多克力量护手",c=1}},w={{i=18366,n="戈多克护手",c=1},{i=18367,n="戈多克手甲",c=1},{i=18368,n="戈多克手套",c=1},{i=18369,n="戈多克裹手",c=1}}},
  [1319]={t="黑色盾牌",d="我很抱歉帮不了忙，$n，不过可以给你介绍个能帮忙的人。卡兹·双链是我们最好的铁匠，他就在铁匠铺给人打铁器。；把盾牌拿给他，看看他能告诉你什么。",o="把被熏黑的铁盾牌拿给塞拉摩的卡兹·双链看一看。",p=1253,r={{i=5919,n="被熏黑的铁盾牌",c=1}}},
  [1321]={t="黑色盾牌",d="嗯……我看不出这个盾牌有什么特别之处。我们应该把它拿给铁匠杜高尔，看看他有什么说法。不过我也不抱太大希望……",o="把被熏黑的铁盾牌拿给蕨墙村的杜高尔看一看。",p=1251,r={{i=5919,n="被熏黑的铁盾牌",c=1}}},
  [1322]={t="黑色盾牌",d="嗯，在盾牌的边上这儿刻着字，可惜烧过了读不出来。；要用些酸液洗干净，用沼泽地里的暗牙蜘蛛的毒液就可以了。那些蜘蛛盘踞在一座旧矿洞里，现在那里被称为黑雾洞穴。给我找点它们的毒囊来，我可以把盾牌清洗一下以便辨认。",o="为蕨墙村的杜高尔收集5个酸性毒囊。",p=1321,r={{i=5959,n="酸性毒囊",c=5}}},
  [1324]={t="失踪的使节",d="什么？！你到这里来就是为了指控我和迪菲亚兄弟会有染？！我无法容许你这么侮辱我！看来我非得好好教训教训你才行。",o="击败尘泥沼泽的亨德尔下士。",p=1266},
  [1358]={t="给赫布瑞姆的样本",d="我有一位名叫赫布瑞姆的药剂师同事当前正在卡利姆多大陆工作。他正在研究洛丹伦大陆上的毒物在卡利姆多大陆生物身上所造成的影响。为了帮赫布瑞姆的忙，我收集了提瑞斯法和银松森林一带各种蜘蛛的蛛毒，现在需要找人帮我把这些毒液给他带去。；他就在贫瘠之地的一处名为十字路口的镇子上。要找到他，你必须先搭飞艇到兽人的首都奥格瑞玛去，然后步行向南去杜隆塔尔，最后向西进入贫瘠之地，这样很快就可以到达十字路口了。",o="把一箱蜘蛛毒带给贫瘠之地的药剂师赫布瑞姆。",p=1359,r={{i=6016,n="狼心样本",c=1}},w={{i=10637,n="酿酒者手套",c=1},{i=10638,n="覆体斗篷",c=1}},f=2},
  [1359]={t="给金格的货物",d="你拿来我的狼心具有与众不同的特质。从中提炼出的特殊毒素甚至可以毒死长着这种心脏的狼！；这让我感到非常惊讶，所以我们必须对此进行深入的研究。把这几份心脏样本送到我的同事药剂师金格那里。你应该可以在幽暗城的炼金房里找到她。",o="将狼心样本交给幽暗城的药剂师金格。",p=3221,r={{i=10283,n="狼心样本",c=1}}},
  [1364]={t="马森的请求",d="马森大人的指示再简单不过了：将这篇重要的文章递交给守望堡的看守者马哈尔巴。；但我从来没有去过诅咒之地！这段路程太可怕了！；我在悲伤沼泽那边迷了路，被一大群像是植物一样的沼泽生物给包围了。它们在我身边徘徊着，似乎是想要攻击我，所以我就飞也似的逃了回来……结果我在慌乱中把文章给弄丢了。我敢肯定是有只怪物把它给捡跑了。；你能帮我找回文章并把它送给马哈尔巴吗？",o="夺回《卡德加的空间收敛研究笔记》，将它送给守望堡的看守者马哈尔巴。",r={{i=6065,n="卡德加的空间收敛研究笔记",c=1}},w={{i=10747,n="导师的腰带",c=1},{i=10748,n="漫步长靴",c=1}},f=1},
  [1365]={t="戴兹帕可汗",d="科卡尔并不是凄凉之地唯一的半人马部族。许多半人马部族都游弋在这片干燥的平原上，他们相互残杀，纷争不断。他们的窝里斗对我们来说不是件坏事，因为半人马强壮而且残忍，如果这些半人马联合起来对付我们的话，那将是极其可怕的力量。；在他们联合起来之前，我们必须将他们各个击破。；你的第一个任务是让科卡尔部族出现内乱，只要干掉他们的首领戴兹帕可汗就可以了。；科卡尔村就在东北方。去吧，祝你好运。",o="把戴兹帕可汗的徽记交给凄凉之地的费古尔·双刃。",r={{i=6066,n="戴兹帕可汗的徽记",c=1}}},
  [1366]={t="悬赏半人马",d="既然你已经震慑了半人马部族，那么现在该让他们出点血了。开始在凄凉之地猎杀半人马吧，我不关心你去猎杀哪一个部族，收集半人马耳朵就是了。；减少他们的数量也就等于削弱他们的野心，打消他们不断扩张的念头。；祝你狩猎愉快，你。",o="收集15只半人马的耳朵，把它们交给凄凉之地的费古尔·双刃。",p=1365,r={{i=6067,n="半人马的耳朵",c=15}},w={{i=6780,n="紫丁香腰带",c=1},{i=6784,n="加固护手",c=1}},f=2},
  [1369]={t="破碎之泪",d="吉尔吉斯以为半人马之母瑟拉达丝在护佑着我们，他们都是蠢货！没有人在护佑半人马，玛格拉姆部族不需要护佑！我们是最强的！；让吉尔吉斯半人马知道他们有多蠢——到他们村庄附近的洞穴里去一趟，他们把那种名叫瑟拉达丝之泪的水晶石藏在了洞里。毁掉那些水晶，把碎片交给我！",o="继续和玛格拉姆部族保持良好的关系，把3块破碎之泪交给玛格拉姆村庄的瓦鲁格。",r={{i=6083,n="破碎之泪",c=3}}},
  [1370]={t="偷取物资",d="在作战之馀，我们为了食物而打猎。肉可以为我们补充力量，吃饱喝足之后作战会更加勇敢。；玛格拉姆部族的半人马和我们一样，他们贮藏多馀的肉食，这样他们就能进行更持久的战斗。如果你能去袭击他们在东部的村庄，并且偷走他们贮藏的肉，他们的力量就会衰竭。",o="把6包粗制干肉交给吉尔吉斯村的智者乌泰克。",r={{i=6069,n="粗制干肉",c=6}},w={{i=3463,n="破损的银星",c=200},{i=3464,n="火焰之箭",c=200},{i=3465,n="爆破弹药",c=200}}},
  [1371]={t="瓦鲁格的玩具",d="很久以前，有一个小侏儒来到凄凉之地。他是乘着马车来的，车上装着奇怪而有趣、燃烧后会放出五彩缤纷的焰火的东西，还有一些没有生命、但是居然可以自己移动的东西。我杀了这个小侏儒，不过在那之前……他让我乐坏了。；我从他的马车上拿走了我最喜欢的东西，那是个木头做的人偶，在我把它砸得粉碎之前，它总是在那里向我招手。；现在我想要一个新的，帮我弄一个来！",o="继续和玛格拉姆部族保持良好的关系，给玛格拉姆村的瓦鲁格找到一个高级假人。",p=1369,r={{i=4392,n="高级假人",c=1}}},
  [1373]={t="盎格库尔",d="你还需要更多的行动来证明自己，我要你去很远的地方完成一个任务，所以从现在开始，吉尔吉斯部族就要独自和玛格拉姆部族作战了。；大地把很多的秘密告诉了聆听它声音的人，我听到的秘密是关于一种红色水晶的。这种被称作德莱尼水晶的东西最近才出现在这片大陆上，它来自一个遥远的地方，那里的山脉在天空中悬浮，恶魔掌控着那里的一切。；给我带一片德莱尼水晶碎片来，它能让我的魔法变得强大无比！这片德莱尼水晶碎片应该就在悲伤沼泽的失落者盎格库尔手里。",o="继续和吉尔吉斯部族保持良好的关系，并把德莱尼水晶碎片交给凄凉之地吉尔吉斯村的智者乌泰克。",p=1370,r={{i=6190,n="德莱尼水晶碎片",c=1}}},
  [1374]={t="杰恩可汗",d="大地告诉我说，玛格拉姆部族变得越来越衰弱了。现在是干掉他们的可汗的时候了！；把玛格拉姆部族的杰恩可汗的徽记给我取来！",o="把杰恩可汗的徽记交给凄凉之地吉尔吉斯村的智者乌泰克。",p=1373,r={{i=6072,n="杰恩可汗的徽记",c=1}}},
  [1375]={t="沙卡可汗",d="你帮助了玛格拉姆部族，我喜欢你。现在去杀了吉尔吉斯的可汗！他叫沙卡，我要他的徽记！",o="继续和玛格拉姆部族保持良好的关系，把沙卡可汗的徽记交给凄凉之地玛格拉姆村的瓦鲁格。",p=1371,r={{i=6073,n="沙卡可汗的徽记",c=1}}},
  [1380]={t="赫鲁萨可汗",d="你，你帮助我们战胜了玛格拉姆部族。现在，请再帮助我们打败玛洛迪部族吧！干掉他们的首领赫鲁萨可汗！；要挑战他，先要吹响玛洛迪号角，这把号角就在长矛谷中的一处高耸的峭壁上。；而要吹响号角，你必须得到一只哨嘴。这种东西很少见，只有萨鲁赫可汗的心腹们才有资格携带。；号角一响，玛洛迪半人马就会蜂拥而至。放手屠杀他们，直到赫兰萨出现。；赫兰萨可汗手里有一把……一把钥匙。把这把钥匙交给我，我就会告诉你有关它的秘密。",o="继续和吉尔吉斯部族保持良好的关系，把玛洛迪钥匙碎片交给吉尔吉斯村的智者乌泰克。",p=1374,r={{i=6077,n="玛洛迪钥匙碎片",c=1}},w={{i=6773,n="吉尔吉斯链甲",c=1},{i=6774,n="乌泰克的手指",c=1}}},
  [1381]={t="赫鲁萨可汗",d="吉尔吉斯可汗已经被干掉，现在轮到玛洛迪了！干掉他们的首领赫鲁萨可汗！；要挑战他，先要吹响玛洛迪号角，这把号角就在长矛谷中的一处高耸的峭壁上。；而要吹响号角，你必须得到一只哨嘴。这种东西很少见，只有萨鲁赫可汗的心腹们才有资格携带。；号角一响，玛洛迪半人马就会蜂拥而至。放手屠杀他们，直到赫兰萨出现。；赫兰萨可汗手里有一把……一把钥匙。把这把钥匙交给我，我就会告诉你有关它的秘密。",o="和玛格拉姆保持良好的关系，把玛洛迪钥匙碎片交给凄凉之地玛格拉姆村的瓦鲁格。",p=1375,r={{i=6077,n="玛洛迪钥匙碎片",c=1}},w={{i=6788,n="玛格拉姆猎人腰带",c=1},{i=6789,n="半人马葬礼毛毯",c=1}}},
  [1382]={t="奇怪的联盟",d="我们的确很幸运，半人马氏族之间正在同室操戈。如果他们拧成一股绳，那将会是一股无法阻挡的力量。没错，我们很幸运，所以我们应该紧紧抓住现在的这种优势。；众多半人马部族中的一支——吉尔吉斯，正在与玛格拉姆部族激烈地战斗。我希望在我们进攻玛格拉姆的同时，吉尔吉斯部族也能同时发动攻击。；去和智者乌泰克谈谈吧，他就在凄凉之地西南的吉尔吉斯营地外面。也许我们可以通过他来和吉尔吉斯结成联盟，同时对玛格拉姆发起致命的攻击！",o="和吉尔吉斯部族创建良好的关系，然后和智者乌泰克谈一谈。"},
  [1383]={t="真言药水",d="我脑中已经想到了合适的药剂配方，可以让口风最紧的人喝下之后也知无不言。；要制成这种药水，我需要几颗沼泽地中的暗影黑豹的心脏，另外还需要住在那儿的泥沼之王的蘑菇。$n，像你这么能干的人一定可以说服他给你一个蘑菇的。；最后一味药是绿龙的血液，比如伊萨里奥斯的洞穴外面的那些。；事不宜迟，你赶快出发吧！",o="乞丐鬼屋的药剂师法奥斯丁需要5颗暗影黑豹的心脏、1颗泥沼之王的蘑菇和一些绿色雏龙之血。",p=1372,r={{i=6080,n="暗影黑豹的心脏",c=5},{i=6081,n="泥沼之王的蘑菇",c=1},{i=6082,n="绿色雏龙之血",c=1}},w={{i=6832,n="荒芜披风",c=1},{i=11265,n="峭壁木槌",c=1}},f=2},
  [1385]={t="野蛮外交",d="凄凉之地是一片杀戮场。半人马部族之间互相残杀，我们担心最后的胜利者会不断扩张领土，并最终威胁到我们的要塞。我们决不能允许这种情况出现。；我们必须学会如何打败半人马部族，为了打败他们……我们就必须和诸多半人马部族中的一支结盟。玛格拉姆部族与吉尔吉斯部族正在互相征伐，如果你去攻打吉尔吉斯部族，那么玛格拉姆部族就会视你为盟友。；想办法得到玛格拉姆部族的信任，然后去和瓦鲁格谈谈，他就在凄凉之地东南的玛格拉姆村里。",o="和玛格拉姆部族创建良好的关系，然后和瓦鲁格谈一谈。"},
  [1387]={t="悬赏半人马",d="半人马的社会是由多个部族组成的，每一个部族都有各自的领袖和纲领。所有的半人马部族只有一点是相同的：残忍。；如果我们要寻求和平，就必须先消灭这些半人马。你的任务就是消灭他们。；在凄凉之地猎杀半人马，割下他们的耳朵。给我尽可能多带些半人马的耳朵回来。；为了联盟，请一定要这么做，你，只有这样，和平才会降临这片土地。",o="收集15个半人马耳朵，把它们交给尼耶尔前哨站的麦尔金斯下士。",r={{i=6067,n="半人马的耳朵",c=15}},f=1},
  [1388]={t="真言药水",d="一切都在按照计划进行，$n。把真言药水交给莱度斯，他会告诉你怎样使用它……；哈哈！",o="把法奥斯丁的真言药水交给乞丐鬼屋的亡灵哨兵莱度斯。",p=1383,r={{i=6086,n="法奥斯丁的真言药水",c=1}}},
  [1393]={t="Galen's Escape",o="Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox."},
  [1394]={t="Final Passage",o="Speak to Dorn Plainstalker in Thousand Needles.",p=6628,w={{i=6804,n="风雷之锤",c=1},{i=6806,n="跳动之火",c=1}},f=2},
  [1396]={t="逼近的野兽",d="我的车队本来是要去守望堡的，但我们没能到达目的地。食人魔攻击了我们，他们杀死了护卫，然后将所有的货物全都给抢走了，那帮该死的家伙逃进了逆风小径。；只有我一个人逃过了他们的袭击。我曾发誓要保护好那些货物，发誓要把它们安全送到守望堡！；但这一带的野兽太多了。拜托，不要让那群野兽侵入我们的营地！",o="杀死8只小盐齿鳄鱼、10只沼泽纺丝蛛和10只沼泽虎，然后向悲伤沼泽的卫兵比格斯报告。"},
  [1398]={t="晒干的流木",d="我对你实在是感激不尽，你。你有一颗充满荣耀的心。现在，我想我仍需要谦卑地请您帮我完成另一个任务。；如果我还想到守望堡去的话，就一定得修好这辆马车。因此……我需要一些木材，我要的是结实的干木，而不是从那些沼泽中的树上砍下的像海绵一样松软的木头。；你，请到东边的海滩上去找些已经被太阳晒干的流木，把它们给我拿来。",o="给悲伤沼泽的卫兵比格斯带回8块晒干的流木。",p=1421,r={{i=6146,n="晒干的流木",c=8}}},
  [1421]={t="丢失的货物",d="那些失落者们攻过来的时候，我一下子就被吓呆了。等我回过神来，就看见一只受惊的马拖着车一路狂奔出去，窜入了北边的失落者村庄里。；那辆车上运的是非常贵重的施法材料，都是守望堡的巫师们急需的。找到我们的材料，你，帮我把它们带回来。",o="在农田避难所中找到商队的货物，并拿到巫师的材料，把它交给卫兵比格斯。",p=1396,r={{i=6170,n="巫师的材料",c=1}}},
  [1424]={t="泪水之池",d="酋长大人派我们去调查阿塔哈卡神庙中发生的奇怪现象。；阿塔莱巨魔是由一群使用黑暗法术的施法者组成的部族，以惯于运用禁断的魔法而着称。你可以想象一下，当我们到达那里，却发现整座庙已经沉入了水中时，我们会有多么惊讶。；现在那里被一群自称是艾泽拉斯保卫者的绿龙占据着。；我们得弄清楚那里到底发生了些什么事。去探索一下泪水之池周围，收集一些阿塔莱神器。有了这些信息，我就可以开始把这个谜一点一点地给解开了。",o="斯通纳德的费泽鲁尔要求你收集5件阿塔莱神器。",r={{i=6175,n="阿塔莱神器",c=10}}},
  [1426]={t="海中的威胁",d="我一点都不喜欢大海，更不喜欢那些从深海里游上来的生物。他们都是些强大野蛮而又盲目的蠢货。要是我有足够的气力，我就会去成百上千地屠杀鱼人。不过现在我还没那么凶悍，所以就只好退而求其次，只要能看见这群鱼人死在任何遵从着部落意愿的勇士手里，我也就满足了。；你怎么样呢，$c？你能杀死多少鱼人？你愿意和鱼人当中最强的一群较量较量吗？",o="杀掉10个沼泽鱼人、10个沼泽喷墨鱼人和10个沼泽食腐鱼人，然后向悲伤沼泽的卡塔尔回报。",p=1422},
  [1427]={t="Threat From the Sea",o="Speak with Tok'Kar in the Swamp of Sorrows.",p=1426,w={{i=9680,n="托克卡尔的鱼人穿刺者",c=1},{i=9678,n="托克卡尔的鱼人粉碎者",c=1},{i=9679,n="托克卡尔的鱼人斩切者",c=1}},f=2},
  [1429]={t="阿塔莱流放者",d="当你勇敢地在泪水之池周围冒险的时候，我的斥候带回了一张用血写成的卷轴。那看起来像是对阿塔莱部族中的某位祭司的审判书。；这位祭司被判处了阿塔莱部族中的极刑，他的命运将比死亡还要更可怕。；他被放逐到了极北的辛特兰，被迫与一群枯木巨魔住在一起。；我会帮你把这些物品包好的，请你带着它们去找到这位流放者，或许你能从他那里得知他们的部族到底使用了怎样的魔法。任务完成之后，请立刻向我回报。",o="将一捆阿塔莱神器交给辛特兰的阿塔莱流放者。",p=1424,r={{i=6193,n="一捆阿塔莱神器",c=1}}},
  [1430]={t="新鲜的螃蟹腿",d="最近我的顾客总是会来买鲜嫩多汁的螃蟹肉，特别是那些巨型淤泥蟹的肉。；如果你最近要去海边转转的话，最好能帮我带一些螃蟹腿到奥格瑞玛去，我会付你可观的报酬的。；海岸就在这里的东边，那里遍地都是螃蟹，很容易就可以弄到螃蟹腿。",o="给悲伤沼泽的达尔带去10条巨大的螃蟹腿。",r={{i=6184,n="巨大的螃蟹腿",c=10}},f=2},
  [1435]={t="灵魂的燃烧",d="对那些为了某些自私的理由而背叛了自己首领的卑劣生物们而言，死亡是他们最合适的归宿。但对于那些将自己的全部身心奉献给黑暗的家伙们来说，死亡还远远不够。；拿着这块宝石，当你附近有火刃氏族的爪牙死去时，就启动宝石上面的魔法。这个法术会拯救堕落的灵魂，将它们拉出黑暗的深渊，灌注到宝石里。；在这些宝石中灌入了灵魂之后，把它们带回来交给我，我会妥善处置它们。；现在就出发吧，多加小心。",o="将15块燃烧宝石转变为灌入灵魂的燃烧宝石，然后把它们交给凄凉之地的玛乌林·碎骨。",p=1433,r={{i=6436,n="燃烧宝石",c=1},{i=6435,n="灌入灵魂的燃烧宝石",c=15}}},
  [1436]={t="Alliance Relations",o="Speak to Keldran in Orgrimmar.",p=1435,w={{i=6744,n="卡普兰的手套",c=1},{i=6745,n="迅疾斗篷",c=1}},f=2},
  [1439]={t="寻找泰拉尼斯",d="兽人杀掉了我们所有的护卫和仆从，然后把我们带到了这里。天啊，那真是太可怕了！我以为他们肯定也会杀了我们，不过显然它们有别的计划。；泰拉尼斯试图和他们交涉，我想他试图用对奥术的了解来博得他们的好感……我不知道他为什么要那么做。；没有找到哥哥的下落，我就不离开这里。找到他，然后再回来救我吧。",o="去凄凉之地找到泰拉尼斯·玛雷姆。",p=1438,r={{i=6767,n="泰拉尼斯的坠饰",c=1}}},
  [1440]={t="Return to Vahlarriel",o="Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.",p=1439,w={{i=9687,n="斗士腰带",c=1},{i=9698,n="洞察手套",c=1},{i=9699,n="军营披风",c=1},{i=11884,n="月光披肩",c=1}},f=1},
  [1445]={t="阿塔哈卡神庙",d="他提到了迦玛兰的预言？；这位阿塔莱部族的精神领袖相信，只要哈卡从扭曲虚空回到艾泽拉斯，这位神祗就将赐予阿塔莱部族的每一个成员以永恒的生命。；若你问我怎么看，我会说这实在是一个只会带来灾难的愚蠢行为。；你说那个流亡者提到了魔法神像？这令我十分担心。如果这种东西确实是那个阿塔莱召唤仪式中的必需品，那我们就必须弄清楚这东西中蕴藏着怎样的力量。；到那个神庙里去一趟，把这些神像都给我带回来！",o="收集20个哈卡神像，把它们带给斯通纳德的费泽鲁尔。",p=1444,r={{i=6181,n="哈卡神像",c=20}},f=2},
  [1446]={t="预言者迦玛兰",d="我的枯木同伴们对贸然闯入他们领地的陌生人不太和善。；我吗？我连家都没有了。我原本属于悲伤沼泽的阿塔莱部族，不过现在却被我的同胞流放到这里来了。；我们的精神领袖迦玛兰曾有过一个“预言”，他声称召唤哈卡会带给阿塔莱部族永恒的生命。；但是我觉得有些不对劲的地方，如果这个预言仅仅是为了操纵我们，那我们该怎么办？；我要为他们流放我的举动rn复仇，给我把迦玛兰的徽记带回来，也许这样我的同胞就可以重获自由。",o="辛特兰的阿塔莱流放者要你给他带回迦玛兰的徽记。",r={{i=6212,n="迦玛兰的徽记",c=1}},w={{i=11123,n="雨行护腿",c=1},{i=11124,n="流放者头盔",c=1}}},
  [1447]={t="失踪的使节",d="没错，你显然不是到暴风城里来的最聪明的$c，但如果你现在不赶快给我消失的话，你就是最笨的那个了！；嘿，你还不走？那就跟我的朋友过过招吧！",o="击败暴风城的达舍尔·石拳。",p=1246},
  [1448]={t="调查神庙",d="我年轻的时候，也是像你这样活力充沛，有一股冲劲的。；但现在我老了，也不能像当初那样在这片大陆上到处冒险了。啊，真是怀念那段日子啊！；但我过去的冒险生涯中却里还有一个未解之迷。在我的最后一次任务中，探险者协会派我去调查阿塔哈卡神庙，据说那座庙宇就在悲伤沼泽里。；但当时我却感到害怕，只是坐在狮鹫上飞过了这片地方，自然，我并没有找到神庙。；你愿意满足一个老矮人最后的愿望吗？或许你走路过去的话就可以找到神庙……",o="暴风城的布罗哈恩·铁桶要求你去找到阿塔哈卡神庙。"},
  [1452]={t="拉普索迪的卡利姆多鸡尾酒",d="嗝儿！；你是那疯子加蠢蛋布罗哈恩派来的啊？我们倒是一起经历过一次大……大冒险……嗝儿！；如果你想要知道我那时候掉进沼泽里的时候看到了什么，行，不过我得先喝上一杯好的。要知道那底下可不是什么美景……嗝儿！；要不这么着吧……如果你给我弄些原料来配制卡利姆多鸡尾酒，我就告诉你。；至于原材料，先去塔纳利斯搞点大鹏的砂囊……然后，然后……我看看……再去菲拉斯弄点格罗多克猩猩和铁鬃熊的肝脏来……；这便是唯一能打开我的话匣子的东西，美味的卡利姆多鸡尾",o="辛特兰的拉普索迪·铁铲要求你带给他3块大鹏的砂囊、3块格罗多克猩猩的肝脏和3块铁鬃熊的肝脏。",p=1451,r={{i=6257,n="大鹏的砂囊",c=3},{i=6258,n="铁鬃熊的肝脏",c=3},{i=6259,n="格罗多克猩猩的肝脏",c=3}}},
  [1456]={t="卡尼托的海难",d="真有趣。；其实，我们也不是一点希望都没有。；在那个海岸更靠北的大海深处，有一片暗夜精灵的废墟。一个纳迦部落把那里当成了他们的家，他们管那地方叫什么来着……滑刺……不，是滑刃部族！我想我们可以去那里碰碰运气。；如果有什么人能够深入到那么远的南部，那他们一定非常强大。如果你要去找卡尼托的东西，那么就准备对付更加强大的纳迦——滑刃潮行者或者滑刃海巫吧。",o="找到卡尼托的背包，把它交给凄凉之地的克雷迪格·安戈尔。",p=1455,r={{i=6245,n="卡尼托的背包",c=1}}},
  [1457]={t="卡尼托的背包",d="去把卡尼托的东西交给铁炉堡的罗顿吧，他会付你报酬的。；哈哈，我敢跟你打赌，他一定会盛情邀请你加入我们的。；再一次感谢你，$n，你干得很好。；回去的时候要多加小心，别耽误太多的时间——卡尼托不是那种很有耐心的人，但是毫无疑问，他是非常慷慨的。",o="把卡尼托的背包交给铁炉堡的罗顿·石锤。",p=1456,r={{i=6245,n="卡尼托的背包",c=1}},w={{i=6791,n="恶棍之靴",c=1},{i=6792,n="血染肩铠",c=1}},f=1},
  [1458]={t="寻物公司的委托",d="我到这里来的一个主要任务就是帮莱弗维奇收集材料，莱弗维奇是卡拉诺斯城中的一个侏儒法师。罗顿总觉得这件事对我们来说轻而易举，却对我们这里人手短缺的现状视而不见。；他列出的清单上的前几件物品应该很容易找到，如果你帮我找到它们的话，就可以获得丰厚的报酬。；首先你得从东边的怨怒萨特身上弄一些角和爪子回来，然后我们再来寻找清单上列出的其它物品。",o="收集10只怨怒萨特的爪子和10根怨怒萨特的角，把它们交给凄凉之地的克雷迪格·安戈尔。",p=1453,r={{i=6246,n="怨怒萨特的爪子",c=10},{i=6247,n="怨怒萨特的角",c=10}}},
  [1459]={t="寻物公司的委托",d="莱弗维奇货单上的下一条……我看看……哦，在这里。；非常简单，而且说明也写得非常清楚。他需要荒土蝎的毒液和科多兽的毛皮。清单上写得很清楚：这两件东西分别来自两个特定的物种：毒液来自于荒土鞭尾蝎，而毛皮则来自老迈的科多兽，注意，既不是濒死的科多兽也不是远古科多兽。；法师……他们总是要一些稀奇古怪的东西……",o="收集7瓶鞭尾蝎的毒液和3块老迈科多兽的毛皮，把它们交给凄凉之地的克雷迪格·安戈尔。",p=1458,r={{i=6248,n="鞭尾蝎的毒液",c=7},{i=6249,n="老迈科多兽的毛皮",c=3}}},
  [1466]={t="寻物公司的委托",d="这是物品列表上的最后一些东西了，我不会撒谎，撒谎可不是件光彩的事情。恐怕你得花更多的时间去寻找这些……；我已经说了这么多了，言归正传。莱弗维奇的要求是：从噬法魔犬，法师猎手或者灵能猎犬那里收集大脑；从地狱魔女、地狱巫女或地狱修女那里收集魔女之翼；还有……从末日看守队长或者末日看守领主那里收集末日看守之血。；是不是很简单啊？呵呵……如果你不想接这项任务的话，我也能理解。",o="收集10个地狱犬的脑子、10对魔女之翼和10瓶末日看守之血，把它们交给凄凉之地的克雷迪格·安戈尔。",p=1459,r={{i=6250,n="地狱犬的脑子",c=10},{i=6251,n="魔女之翼",c=10},{i=6252,n="末日看守之血",c=10}}},
  [1467]={t="寻物公司的委托",d="要想得到报酬，你就得去一趟铁炉堡，亲自和罗顿谈谈。他会非常乐意收到莱弗维奇的包裹的。把这个交给他，然后你应该就能收到报酬了。；别担心，我回去以后会替你美言几句的，从理论上讲我应该不会在这个鬼地方呆太久的。",o="把莱弗维奇的包裹交给铁炉堡的罗顿·石锤。",p=1466,r={{i=6253,n="莱弗维奇的包裹",c=1}},w={{i=6793,n="镀金护腕",c=1},{i=6794,n="雷火手套",c=1}},f=1},
  [1469]={t="拉普索迪的故事",d="在出发前，我喝了整整一桶的烈酒。嗝儿！；那是怎样的一次飞行呀！布罗哈恩跟着我飞了几圈，还是没看见庙。嗝儿！；我喝得有点醉了，结果没抓稳就从坐骑上掉了下去。我一头栽进了水里，而且沉到了底儿，这个时候我竟然看见了那座庙。不过很快就从不知道哪里冒出了一大群巨魔把我给围了起来，废话，当然得快溜了！不过我还是从那些巨魔手中搞了点纪念品回来。给，把这个带给布罗哈恩，告诉他神庙确实就在那下面。嗝儿！",o="将阿塔莱石板碎片交给暴风城的布罗哈恩·铁桶。",p=1452,r={{i=6287,n="阿塔莱石板碎片",c=1}}},
  [1473]={t="虚空中的生物",d="看来大家一致认为你已经可以学习如何召唤虚空行者了。；虚空行者是一种由虚空中的混乱力量所构成的实体，如果你召唤出虚空行者但却不能控制住它的话，你就会被它撕成碎片。；世上第一个虚空行者是埃加林召唤出来的，而在他的魔典中也详细地写明了整个召唤过程。；不幸的是，这本书被血色十字军的一个成员给偷走了，他把书藏在十字军在西边占据的一座塔中。把它给我拿回来，然后我就可以把召唤虚空行者的方法传授给你了。",o="夺回埃加林的魔典，把它交给诅咒神庙中的凯伦丁·哈加尔。",r={{i=6285,n="埃加林的魔典",c=1}}},
  [1475]={t="进入阿塔哈卡神庙",d="根据传说，阿塔哈卡神庙是供奉着古代神祗“夺魂者阿塔哈卡”的神圣祭坛，有一个名叫阿塔莱的巨魔部族世世代代守护着这座庙宇，据说从来也没人能进到庙中去一窥究竟。；潜到泪水之池底部并从庙中取出古代的神器是件很困难的事，但这却正是我要你去做的，$n。；帮我收集一些完整的阿塔莱石板，把它们带回来给我，这样一来我就能以英雄的身份回到探险者协会去了。我会和你一起分享这份荣耀。",o="为暴风城的布罗哈恩·铁桶收集10块阿塔莱石板。",p=1469,r={{i=6288,n="阿塔莱石板",c=10}},f=1},
  [1476]={t="纯洁者精华",d="有荣誉感与善良的人？这种人到底存在过吗？；在进行了多年的研究并翻阅了无数的典籍与传说之后，我终于找到了两个符合我们标准的人。；第一个叫达林·弗治维特，他将自己的全部身心都投入到了拯救那些被遗弃在格雷迈恩之墙外的洛丹伦难民的事业中。；另一个叫科马·韦拉德。此人对他失踪了的爱人忠贞不渝，一直以来都在湿地中寻找着他的爱人的下落。；把他们的精华交给凯伦丁，不过首先，让我先告诉你到哪里去找。",o="将达林和科马的精华交给诅咒神殿里的凯伦丁·哈加尔。",p=1472,r={{i=6312,n="达林的精华",c=1},{i=6313,n="科马的精华",c=1}}},
  [1480]={t="堕落者",d="这片被裁下来的皮子很臭，似乎已经有点腐烂了, 值得注意的是，这块看上去干燥而松脆的东西却异常柔软。；在摊开它之后，你可以清楚地看见其中一面上有着用某种语言写成的红色标记文字。在皮子的底端有一个十分清晰的符号，你认为这是个签名。；也许玛乌林能告诉你些什么？",o="把恶魔之皮拿给凄凉之地的玛乌林·碎骨看看。",r={{i=20310,n="恶魔之皮",c=1}}},
  [1481]={t="堕落者",d="我可以在拥有适当材料的情况下找到这个恶魔领主。；如果他确实如我推测的一般强大，那我就得先准备一些只有从非常危险的生物身上才能收集到的物品。既然你是为酋长做事的，那么我想你应该会接受我交付给你的任务吧。；首先，我需要破坏他的反侦测结界。去给我找一块萨特的头皮来，不过并不是任何萨特的头皮都可以的，只有怨怒巡影者的头皮才能用。；从凄凉之地东北部的古代遗迹附近开始找起吧。",o="给凄凉之地的玛乌林·碎骨带回一张巡影者的头皮。",p=1480,r={{i=6441,n="巡影者的头皮",c=1}}},
  [1482]={t="堕落者",d="如果有一块神谕水晶就好了。这种东西一般都是由纳迦制造出来用于预言的。；从这里向西北方向走，一直沿着海岸线前进，你会看到一个巨大的珊瑚礁，纳迦们通常在那一带活动。你可以在那里找到神谕水晶。滑刃纳迦并非善类，而且他们也不会对你的闯入表示欢迎，所以你要小心点，动作快点。；等你回来以后，我们就可以开始寻找魔王阿兹雷索克了。",o="给凄凉之地的玛乌林·碎骨带回一块神谕水晶。",p=1481,r={{i=6442,n="神谕水晶",c=1}}},
  [1485]={t="邪灵劣魔",d="我们之前的术士，在这里得到的只有部落的不信任，虽然我们现在得到了一些容忍，但是部落仍然对我们没有丝毫敬爱。；这令我们术士们更加团结在一起，当然，也有一些人选择了隐居的生活，独自研究着他们的魔法。我不会强迫或引导你选择其中的任何一条道路，只会帮助你变得更加成熟。；在我教会你召唤恶魔的方法之前，先给我带六颗邪灵劣魔的徽记回来，在东北方的山洞里就能找到这种生物。",o="给鲁赞带回6颗邪灵劣魔的徽记。",r={{i=6487,n="邪灵劣魔的徽记",c=6}}},
  [1486]={t="变异皮革",d="由于纳拉雷克斯彻底陷入了他的恶梦之中，有一种此前没有见过的野兽突然侵入了哀嚎洞穴。；这些邪恶的生物有着某种奇怪的、不属于这个世界的特性。在我看来，虽然它们本性邪恶，但它们的存在对卡利姆多的居民也并不是完全没有价值的。我相信它们的皮革在制皮业中可能会非常有用。；如果你愿意接下这个任务的话，那就到洞穴深处去，想办法帮我找一些变异皮革吧。",o="哀嚎洞穴的纳尔帕克想要20张变异皮革。",r={{i=6443,n="变异皮革",c=20}},w={{i=6480,n="光滑的蛇鳞护腿",c=1},{i=918,n="变异皮包",c=1}}},
  [1487]={t="清除变异者",d="纳拉雷克斯有着一个崇高的目标。；我们这位伟大的领袖一直想要进入翡翠梦境，将那片如今已经变得一片荒芜的土地变回过去那样茂密的森林，但似乎有一些可怕的事发生了。；纳拉雷克斯的梦境不知为什么突然转化成了一场恶梦，同时，大量的堕落生物出现在了洞穴之中。；一些纳拉雷克斯的信徒正在想办法来唤醒我们的领袖，而我此时的职责就是清除洞穴中的那些邪恶生物。；去吧，$n，勇敢地把那些变异的生物都清除干净。",o="哀嚎洞穴的厄布鲁要求你杀掉7只变异破坏者、7只剧毒飞蛇、7只变异蹒跚者和7只变异尖牙风蛇。",w={{i=6476,n="图样：蛇鳞腰带",c=1},{i=8071,n="烧灼之棒",c=1},{i=6481,n="达格米尔护手",c=1}}},
  [1488]={t="堕落者",d="虽然我对这个魔王阿兹雷索克一无所知，但我同意玛乌林的观点：我们一定要尽快消灭掉这个恶魔，尤其是他正在逐渐控制火刃氏族为他的邪恶目的服务。；到了你实现自己的诺言，为酋长和部落而战的时候了，我也相信你有能力召集一只小队去刺杀这个恶魔领主和他的爪牙。；如果你准备好了，就直接向南方出发，消灭了这个威胁之后就回来向我复命。",o="杀掉魔王阿兹雷索克和祖格卡，然后向凄凉之地的塔卡塔·钢刃复命。",p=1484,w={{i=6746,n="黑陶圆盾",c=1},{i=6747,n="执行者肩铠",c=1}},f=2},
  [1489]={t="哈缪尔·符文图腾",d="你带来的兽皮有一种奇怪的斑点，一种我从来没有见过的斑点。我确信绿洲里的水是造成这些斑点的原因，我甚至能够感受到它们给这片土地带来的混乱，这片土地现在死气沉沉的，就好像是长眠不醒了一样。；哀嚎洞穴一定就是这一切问题的源头。但是，在你去那里调查以前，先去找德鲁伊长老哈缪尔·符文图腾谈谈吧。我托人给他捎了信，把关于在贫瘠之地所发生的一切都转告给他了。这位博学的长者应该能给你很多忠告。；他就在雷霆崖的长者高地上。",o="和哈缪尔·符文图腾谈一谈。",p=880},
  [1498]={t="防御之道",d="作为一个战士，你最重要的任务是……保护。我们是部落的护盾和壁垒，我们要保护比我们弱小的同胞的安全。如果你要加入我们，那你就必须先证明自己与我们一样拥有着无比的勇气。；到杜隆塔尔的雷霆山去，那里有不少闪电蜥蜴和雷霆蜥蜴。去猎捕那些蜥蜴，向我证明你比它们更加强大！在它们的攻击面前要毫不畏缩，把它们的鳞片给我带回来作为证明。；快点出发吧，完成这个任务之后，我将继续让你进行训练课程。",o="给贫瘠之地前沿哨所的犹塞克带回5块烧焦的鳞片。",p=1505,r={{i=6486,n="烧焦的鳞片",c=5}}},
  [1499]={t="Vile Familiars",o="Speak with Zureetha Fargaze.",p=1485,w={{i=4925,n="粗糙的手刀",c=1},{i=5778,n="粗糙的手杖",c=1}},f=2},
  [1501]={t="虚空中的生物",d="很少有术士能活得够久的……我们冒着巨大的风险来研究恶魔，风险越大，回报越大。你必须尽快成熟起来，这样才会成为对酋长和部落有用的人。；现在是该让你去学习新的召唤法术了。；首先，你必须夺回维尔加石板，那个东西被火刃氏族的术士偷走了，现在石板被保存在他们的巢穴里，那个巢穴就在奥格瑞玛城东的骷髅石。有了石板之后，我会教你如何召唤虚空行者。",o="为奥格瑞玛的甘鲁尔·血眼找回维尔加石板。",r={{i=6535,n="维尔加石板",c=1}}},
  [1503]={t="锻造好的钢锭",d="你，我会给你一柄武器，但首先我需要你的帮助。几天前的一个晚上，西北边的那些钢鬃部落的家伙摸进了我的营地，他们不敢和我正面交战，但是他们知道我眼睛不好使，所以就想办法用响声把我引出来，然后派几个同伙溜进去偷了我的东西！；他们偷走了一只铁箱子，里面是一些铸造好的钢锭。如果你能够找到它们的话，我就会给你一件你用得到的武器。；你应该可以在钢鬃野猪人的营地里找到那只铁箱子，把那些钢锭给我拿回来。",o="把锻造好的钢锭带给贫瘠之地的索恩格瑞姆·火眼。",p=1502,r={{i=6534,n="锻造好的钢锭",c=1}},w={{i=7326,n="索恩格瑞姆的斧头",c=1},{i=7328,n="索恩格瑞姆的钉锤",c=1},{i=7327,n="索恩格瑞姆的匕首",c=1},{i=7329,n="索恩格瑞姆的长剑",c=1}},f=2},
  [1511]={t="肯兹格拉的伤药",d="我得告诉你们，可能还会有其它人来向我讨伤药，所以我得在这里随时做好准备。；快回去吧，$n。你得注意，一开始只能给他一半伤药！这一半足以让他在活动的时候不再出血，免得失血过多而死。等过了一个晚上之后再给他另一半。；总之，你得把它带给陶拉祖营地里的劳格玛。根据他派来的上一个信使所说的，他应该已经知道多格兰被关在哪儿了。",o="将肯兹格拉的伤药交给陶拉祖营地的步兵劳格玛。",p=1510,r={{i=6624,n="肯兹格拉的伤药",c=1}}},
  [1512]={t="爱的礼物",d="赞卡沙年轻而美丽，却得跟一个残废过上一辈子……我可不能让她受这种苦。；别管我了，$n。谢谢你。我将会在战斗中光荣地结束我的生命，而不是拖着这破碎的躯壳白白度过后半辈子。；拜托，别把这些告诉我的老婆……我可不想让她在良心上受谴责。",o="把沾满泥土的坠饰带给奥格瑞玛的甘鲁尔·血眼。",p=1515,r={{i=6625,n="沾满泥土的坠饰",c=1}}},
  [1515]={t="多格兰之囚",d="你为这件事儿出了很多力，所以你如果愿意帮忙帮到底的话，我当然不会阻止你。但我没办法派给你更多的人了，所以你恐怕只能一个人去救多格兰……；多格兰被关在北边的一处野猪人营地里。注意那里的两座小屋子，如果他还没被杀掉或者因为伤口恶化而死掉的话，那群野猪人应该会严密看守他的。；祝你好运。",o="把肯兹格拉的伤药带给贫瘠之地的多格兰。",p=1511,r={{i=6624,n="肯兹格拉的伤药",c=1}}},
  [1516]={t="大地的召唤",d="是时候了，年轻的$c。你的肉体已经足够强壮，而你的精神也已如大地一般坚韧。你选择了遵循萨满之道，这代表着你拥有无可置疑的睿智。；；让大地来指引你的命运，让它成为你的一部分吧。但你必须自己去面对大地的力量，如果你已经准备妥当，你就会看见一些只有萨满祭司才能理解的事物。；去北边去搜寻那些地狱捕猎者，给我带一对它们的蹄子回来，然后我们再来好谈谈你的未来。",o="给试炼谷的坎纳甘·地鸣带去2只地狱捕猎者的蹄子。",r={{i=6640,n="地狱捕猎者的蹄子",c=2}}},
  [1519]={t="大地的召唤",d="是时候了，年轻的$c。你的身体已经够强壮，你的精神如大地一般坚韧，这正是你已经成熟的标志。；大地引领并教导着我们的族人，以后你也将得到它的指引。但在那之前，你必须先通过试炼。在你完成了试炼之后，就会看到那些只有我们才能看到的东西。；往东边去，找到刺背野猪人的萨满祭司，把他们在仪式中使用的药膏拿回来一些。在你得到了足够的药膏之后再回来向我复命。",o="给纳拉其营地的鸦羽先知带回2份仪式药膏。",r={{i=6634,n="仪式药膏",c=2}}},
  [1524]={t="火焰的召唤",d="你已经有足够的力量来运用火焰图腾了，不过这并不意味着你已作好了充分的准备。；沿着杜隆塔尔的怒水河前进，在河水流入无尽之海的地方，有一条隐蔽的小路，它通向这片大陆上最高的山峰之一。沿着这条小路走到最高处，你就会看到一处由泰尔夫·祖拉姆看守的圣殿，那就是眠炎圣殿。；把这个火炬交给泰尔夫·祖拉姆，它是你试图驯服火焰力量的证明。用圣殿里的火盆点燃火炬并把它带回来，我就会将火焰图腾交给你。",o="把眠炎火炬带给杜隆塔尔的泰尔夫·祖拉姆。",r={{i=6653,n="眠炎火炬",c=1}}},
  [1525]={t="火焰的召唤",d="你该不是到这儿来上历史课的吧？你是要得到永恒之火和你的火焰图腾。；首先，你要制造一个灵契，并将你和它连接起来。；只要你给我找来两样东西，我就可以为你制造火焰灵契。第一件是火焰焦油，这个相对而言比较简单，钢鬃野猪人的施法者通常会带着这种东西。；另一件则比较危险：从火刃氏族的祭司身上找一个试剂袋。你可以在奥格瑞玛东部找到他们。",o="找到1个火焰焦油和1个试剂袋，把它们交给杜隆塔尔的泰尔夫·祖拉姆。",p=1524,r={{i=5026,n="火焰焦油",c=1},{i=6652,n="试剂袋",c=1}}},
  [1526]={t="火焰的召唤",d="火焰灵契已经做好了，现在你必须面对火焰元素的灵魂。在圣殿中使用灵契，然后去挑战山顶上的火焰之魂。他不会在你没有准备好的时候就攻击你，不过他知道你能看见他。；你必须迅速打倒他，你，拖得越久他的力量就会越强大。在击败他之后，将他的馀烬放在火盆里，然后点燃火炬。",o="击败火焰之魂，将馀烬放在恒焰圣殿屋顶的火盆里。",p=1525,r={{i=6653,n="眠炎火炬",c=1},{i=6655,n="余烬",c=1}}},
  [1527]={t="火焰的召唤",d="你手中紧握着火炬离开火盆，望向远处的杜隆塔尔，神圣的火焰随风狂舞，令你感到心中充满了激动和兴奋。；你沿着小路回到贫瘠之地去找卡纳尔·菲斯。",o="将恒焰火炬交给贫瘠之地的卡纳尔·菲斯。",p=1526,r={{i=6654,n="恒焰火炬",c=1}},f=2},
  [1534]={t="水之召唤",d="现在，你必须带上这个水囊，深入到那片被暗夜精灵称为灰谷的茂密森林中，那地方就在贫瘠之地的北方。；进入森林之后向西走，顺着隔断石爪山与灰谷的山脉前进，你会在密斯特拉湖的尽头发现一处圣地：星尘废墟。在那里的湖中央有一眼小喷泉。；取回一些喷泉水，那是制作灵契所需的最后一种水样，然后我就可以把你送回伊斯伦那里了。",o="到灰谷的星尘废墟去，将空的蓝色水囊盛满泉水，然后把它交给贫瘠之地的布瑞恩。",p=1536,r={{i=7770,n="装满水的蓝色水囊",c=1}}},
  [1535]={t="水之召唤",d="要得到我的信任并从我这里取得灵契，你就必须找到最纯洁的水。在你寻找这种水样时，别忘了注意周围的动静。要小心那些依赖这种水生存并守护着它的生物，要注意这种水是如何影响森林和荒漠的。看看这种维持生命的特殊物质是如何强迫这些生物进行杀戮的。；让我们先从一个简单的任务开始吧：在我的小屋下面有一小池这种珍贵的液体，装满这个水囊后再回来找我。",o="到野猪人的水池去，用井中的水装满空的棕色水囊，然后把水囊交给贫瘠之地的布瑞恩。",p=1530,r={{i=7769,n="装满水的棕色水囊",c=1}}},
  [1536]={t="水之召唤",d="很久以前，我和一些同伴一起去过希尔斯布莱德丘陵。我们为了保护自己而和那里的人类作战，后来发现自己正置身于一个由被遗忘者控制的小镇：塔伦米尔。；在那里，我有一个特别的发现：小镇中心有一口清泉小井。我不清楚镇中那些被感染的居民是否清楚它的价值——那口井是那片被亵渎的土地上唯一一块未受亵渎的神圣之地。；用这只水囊帮我带回一些那口井里的水。",o="用塔伦米尔的井水装满空的红色水囊，然后把它交给贫瘠之地的布瑞恩。",p=1535,r={{i=7771,n="装满水的红色水囊",c=1}}},
  [1560]={t="Tooga's Quest",o="Show Tooga the way back to his wife, Torta.",w={{i=9638,n="海龟护腕",c=1},{i=9642,n="巨龟指环",c=1}}},
  [1579]={t="小齿轮",d="我到奥伯丁来仅仅是因为这里相当的安静。我喜欢在安静的地方进行发明创造，因为在一夜痛饮之后，铁炉堡的喧嚣足以让我发疯！；因此我乘船来了奥伯丁，路上喝了不少酒，结果我一不小心就把一盒小齿轮掉在了船上！；我不能确定把它们掉在什么地方了，但如果你愿意到大海里钓钓看的话，也许……",o="收集8个小齿轮，把它们交给奥伯丁的维兹班恩·曲针。",r={{i=6717,n="小齿轮",c=8}}},
  [1644]={t="圣洁之书",d="愿圣光护佑那些孩子，他们大多因为几年前那次亡灵天灾的袭击而失去了家庭。；我丈夫约翰为我收集给孩子们做衣服裤子的布料，不过我没时间做，因为我得成天忙着照顾他们的饮食起居。；什么？你愿意帮忙？赞美圣光，也感谢你，好心的你。；如果你能给我找点亚麻布来的话,我就能给孩子做衣服了，那可真是帮了我的大忙。",o="给暴风城的斯蒂芬妮·特纳收集10块亚麻布。",p=1643,r={{i=2589,n="亚麻布",c=10}}},
  [1648]={t="圣洁之书",d="我和我的妻子在暴风城管理着一家孤儿院，帮助在过去几年里因为亡灵天灾的袭击而失去双亲的孩子们。我差不多每个月都要来铁炉堡收集这里的居民捐赠的物资，而且我也会和不同的团体商谈，尽可能地寻求他们的帮助。；这样的旅程往往让人苦恼，因为它很费时间而且收效甚微。；如果能找到些亚麻布来让我妻子给那些孤儿做些衣服的话，我想我就可以寄些东西回家了。",o="收集10块亚麻布，把它们交给铁炉堡的约翰·特纳。",p=1647,r={{i=2589,n="亚麻布",c=10}}},
  [1652]={t="The Tome of Valor",o="Speak to Duthorian Rall in Stormwind.",p=1651,f=1},
  [1654]={t="正义试炼",d="如果你愿意接受奖赏的话，我会给你奖赏的。请不要误会，我的慷慨取决于你能给我多少帮助，不过这样的同盟关系对你我都有好处。；我可以为你制作一把配得上你的成就的武器，一把象征着圣骑士的精神和圣光的武器，不过首先，你要给我找到制作这把武器所需的材料。我已经列出了所需的材料，现在得有一个勇敢能干的人去找到它们。你愿意去完成这个任务吗，$n？",o="按照乔丹的武器材料单上的说明去寻找一些白石橡木、精炼矿石、乔丹的铁锤和一块科尔宝石，然后回到铁炉堡去见乔丹·斯迪威尔。",p=1653,r={{i=6994,n="白石橡木",c=1},{i=6993,n="乔丹的精炼矿石",c=1},{i=6895,n="乔丹的铁锤",c=1},{i=7083,n="净化过的科尔宝石",c=1}}},
  [1665]={t="巴特莱比的酒杯",d="好吧，这是我的酒杯。等等！让我先把酒喝光……给你。",o="把巴特莱比的酒杯交给伯加德。",p=1640,r={{i=6781,n="巴特莱比的酒杯",c=1}}},
  [1667]={t="蛀牙杰克",d="是伯加德派你来的吗？是的，我这里的确有一些剩馀的武器，不过首先有一项任务交给你……；不久以前，一个被称作蛀牙杰克的迪菲亚混蛋捉弄了我。天很黑，他穿着一件暴风城卫兵的衣服，我还以为他是治安官杜汉呢。他说他要我那个旧的暴风城治安官徽章，我就把徽章给了他……然后他便大笑起来，在我反应过来之前就跑掉了！；帮我取回我的勋章！蛀牙杰克应该是把徽章放在南边的迪菲亚盗贼营地里了。",o="从蛀牙杰克的营地里取回治安官哈迦德的徽章，把它交给治安官哈迦德。",p=1666,r={{i=6782,n="治安官哈迦德的徽章",c=1}},w={{i=6979,n="哈加德的战斧",c=1},{i=6983,n="哈加德的战锤",c=1},{i=6980,n="哈加德的匕首",c=1},{i=6985,n="哈加德的剑",c=1}},f=1},
  [1678]={t="维吉雷克",d="如果你想提高自己在战士中的地位，那么你就必须变得更加坚韧一些。我可以教你一些新的技能，不过在此之前，你要向我证明你能够对付真正的敌人。；维吉雷克是这一地区最强大的巨魔，也是你即将挑战的对手。他住在霜鬃要塞南方山脚下的棚屋里。；把维吉雷克的徽记交给我，让我看看你的勇气和力量。",o="将维吉雷克的徽记交给铁炉堡的穆伦·雷矛。",p=1679,r={{i=6799,n="维吉雷克的徽记",c=1}}},
  [1679]={t="穆伦·雷矛",d="你好，战士！你有很大的潜力，不过你还要学习更多的技巧才行，穆伦·雷矛是最合适向你传授这些技巧的矮人。；你可以在铁炉堡军事区的军事大厅里找到穆伦。当你准备要成为一名真正的勇士的时候，就去和他谈谈吧。",o="和穆伦·雷矛谈一谈。"},
  [1681]={t="铁环营地",d="我的导师，斯塔基·铁环，原本在丹莫罗东部的盔枕湖南边有一处独家小院。他在那里向别人传授铁匠的技能，他绝对是最棒的。；不过，有一天，他的一个学生带给他一块奇特的矿石。铁环把它叫做暗影矿石，他很希望能用它做点什么，可是，之后不久……一伙黑铁矮人袭击了他的小院。他们杀死了所有的人！；到铁环的小院去，你，为我的导师复仇，然后把那块暗影矿石给我带回来。",o="把暗影矿石交给铁炉堡的托姆斯·深炉。",p=1680,r={{i=6800,n="暗影矿石",c=1}}},
  [1682]={t="Grey Iron Weapons",p=1681,w={{i=6978,n="暗影战斧",c=1},{i=6982,n="暗影钉锤",c=1},{i=6981,n="暗影匕首",c=1},{i=6984,n="暗影长剑",c=1}},f=1},
  [1683]={t="沃鲁斯·邪蹄",d="在我向你传授知识之前，你必须显示出决心。；有一个名叫沃鲁斯·邪蹄的萨特找到了我们的一口月亮井，就在班奈希尔兽穴的东南方。他正在井中戏耍，用他邪恶的身躯污染纯洁的井水。；到月亮井那里去找到沃鲁斯，把他干掉。把他的角给我带回来，然后我就会向你传授更高级的战士技能。；去月亮井的路不太好找，但是如果你细心一点的话，应该不会迷路的。",o="将沃鲁斯的角交给达纳苏斯的艾兰娜瑞。",p=1684,r={{i=6805,n="沃鲁斯的角",c=1}}},
  [1686]={t="艾鲁拉的阴影",d="你已经学会很多东西了，你。现在我们将为你制作一件精良的武器，一件属于战士的武器。；要完成这一使命，你必须去一趟黑海岸。；很久以前，有一条船在奥伯丁灯塔附近触礁，许多装有月神矿石的箱子沉入了海底。；首先，你必须打败守护那些矿石的亡魂——艾鲁拉的阴影。作为一船之长，她对自己施加了诅咒，变成了一个在海洋深处巡游的亡魂，时时刻刻保护着船上的货物。打败她，摘下她的徽章，然后收集丢失的月神矿石。",o="将艾鲁拉的徽章和8块月神矿石交给达纳苏斯的艾兰娜瑞。",p=1683,r={{i=6808,n="月神矿石",c=8},{i=6809,n="艾鲁拉的徽章",c=1}}},
  [1688]={t="苏伦娜·凯尔东",d="我曾有一个名叫苏伦娜·凯尔东的学生。她过去和现在的你一样，一心渴求学习到强大的术士魔法，而且她也拥有着十分了得的天赋。更难能可贵的是，她很年轻，而且很漂亮。我最近又看见她了，那个背叛了我的女人！；那时候她和迪菲亚兄弟会里的一个小贼埃尔兰·杜德摩尔私奔了。她走掉其实倒也没什么，但我曾送给她一条血石项圈，我必须把它拿回来。；现在她的性命对我来说一点都不重要了。你应该可以在布莱克威尔南瓜田找到她，到那儿去把我的东西给夺回来！",o="为暴风城的黑暗缚灵者加科因夺回苏伦娜的项圈。",r={{i=6810,n="苏伦娜的项圈",c=1}}},
  [1690]={t="废土的公正",d="你！是你出马帮助加基森水业公司的时候了！；那些废土游牧民几乎占据了塔纳利斯沙漠上所有的水井！如果得不到这些水井的控制权，那我们的水源供应很快就会出现问题。如果你想帮助我们的话，就去解决那些该死的游牧民吧！；从这里往东走，去干掉10个废土窃贼和10个废土强盗，然后立即向我报告。你一定要为我们这些人……呃……地精们伸张正义啊，不管怎么样，快点行动吧！",o="去加基森的东面杀掉10个废土窃贼和10个废土强盗，然后向总工程师比格维兹复命。"},
  [1692]={t="铁匠玛希尔",d="我把你收集到的月神矿石装进了一只箱子。把它交给铁匠玛希尔，他会帮你打造一件月神武器。；玛希尔住在靠南的地方，就在这座建筑物的另一侧。",o="把这箱月神矿石交给铁匠玛希尔。",p=1686,r={{i=6812,n="一箱月神矿石",c=1}}},
  [1693]={t="Weapons of Elunite",p=1692,w={{i=6966,n="月神之斧",c=1},{i=6968,n="月神钉锤",c=1},{i=6969,n="月神匕首",c=1},{i=6967,n="月神之剑",c=1}},f=1},
  [1701]={t="弗伦的铠甲",d="我已经给了你一面精致的盾牌，不过我们的合作决不会就此结束。我知道如何铸造异常坚固的铠甲，但是铸造起来并不容易，我需要一些稀有的材料，只要你愿意跑跑腿，我保证会为你打造一件。；你觉得怎么样，你？如果你愿意接受挑战的话，我会给你一份列表，上面记载着我需要的材料和到可以找到这些材料的地点。",o="收集必需的材料，将它们交给暴风城的弗伦·长须。",p=1702,r={{i=6838,n="烧焦的蜘蛛牙",c=50},{i=6839,n="烧焦的奇美拉角",c=12},{i=6840,n="光滑的奇美拉角",c=1},{i=6841,n="燃素",c=1}}},
  [1702]={t="铸盾师",d="你，当你完成挑战时，我就看出你是个厉害的家伙啦。当然，我说话算话，我会按照承诺给你奖励……；不过，这件礼物在暴风城。；去跟我的朋友弗伦·长须谈谈吧，他在暴风城的矮人区里。我敢说他是你见过的最棒的铸盾师，他欠我一份人情。；给，把这桶热麦酒交给弗伦，让他为你制造一副盾牌。那品质绝对让你满意！",o="将这桶热酒交给弗伦·长须。",p=1699,r={{i=6843,n="一桶热酒",c=1}},f=1},
  [1705]={t="燃烧之血",d="我很不愿意相信弗伦可能发现了什么新奇的东西。不过，为了确认这一点，我要把他的技术应用到这副新的铠甲上。如果你能帮我找来这些原料，你，你就能拥有这样的一件铠甲。；要制造这件铠甲的话，我需要一些燃烧之血和一块燃烧之石。；我知道唯一能找到它们的地方是暮色森林，那些在罗兰德末日矿洞里出没的夜行狼人拥有燃烧之血，而他们的首领加特斯比尔则拥有燃烧之石。；愿好运永远与你同在，你.",o="把20瓶燃烧之血和1块燃烧之石交给暴风城的格瑞曼德·艾尔默。",r={{i=6844,n="燃烧之血",c=20},{i=6845,n="燃烧之石",c=1}}},
  [1706]={t="Grimand's Armor",p=1705,f=1},
  [1707]={t="收集水袋",d="你好啊，你！我叫鲁格伦克，如果你想要找些事情干，我们这里现在就有一件重要的工作给你！；没有什么能比帮我带回一些废土水袋来更能令我这个老家伙开心的了。那可都是我们的水——就是那些混蛋把它们偷走了！你每给我带回五只废土水袋来，加基森水业公司就会奖励给你一个可以用来碰运气的小包裹。更重要的是，我们会永远记住你所提供的帮助！",o="收集5只废土水袋，把它们交给加基森的鲁格伦克。",r={{i=8483,n="废土水袋",c=5}}},
  [1708]={t="铁珊瑚",d="我希望在我自己的铠甲上应用弗伦·长须的新技术。因为你帮了弗伦的忙，而他又帮了我的忙，所以当我做好铠甲以后，你可以第一个试用它！；要打造铠甲的话，我就得弄到一种特别的珊瑚，灼热珊瑚。它只生长在一个地方——湿地的米奈希尔港南边的海岸地带。；只要你给我带来我足够多的灼热珊瑚，我就可以马上开始铸造铠甲啦。快点，你，我恨不得现在就开始工作！",o="收集20块灼热珊瑚，把它们交给铁炉堡的科罗莫特·钢尺。",r={{i=6848,n="灼热珊瑚",c=20}}},
  [1709]={t="Klockmort's Creation",p=1708,f=1},
  [1710]={t="晒焦的蛋壳",d="我很想测试一下弗伦·长须的最新发现，希望能将它用于我正在研究的新式铠甲上，我认为弗伦的技术一定能产生最好的结果。；你愿意帮助我吗？如果你愿意帮我收集制造铠甲所需的原料，我就会帮你也做一件。；我需要晒焦的巨翼双足飞龙蛋壳，这种飞龙大都栖息在千针石rn林的风巢中。在它们的巢下可以找到我要的蛋壳，当你收集了足够数量的蛋壳之后就赶快回来找我。",o="把20个晒焦的蛋壳交给达纳苏斯的玛希尔。",r={{i=6849,n="晒焦的蛋壳",c=20}}},
  [1711]={t="Mathiel's Armor",p=1710,f=1},
  [1712]={t="塞克隆尼亚",d="我几十年来都在关注着这个地方。我关注着，希望有一天能看到强大的塞克隆尼亚被人击败。但迄今为止，我还没有找到一个能打败风之王的勇士。；也许你就是那个勇士。；证明给我看吧，给我找来召唤塞克隆尼亚所需的东西，这样你就能证明自己是一个伟大的勇士。也许你能打败他并夺得他的旋风之心。；这样的话，我将把这颗心的力量注入一把武器里，供你在今后的冒险旅程中使用。；这张羊皮纸上写着我需要的东西。",o="把巴斯拉的羊皮纸上列出的东西交给奥特兰克的捕风者巴斯拉。",p=1791,r={{i=3357,n="活根草",c=8},{i=3901,n="血顶巨魔的獠牙",c=30},{i=6851,n="流放精华",c=1}}},
  [1713]={t="召唤",d="我已经准备好仪式要召唤塞克隆尼亚了。当他被召唤出来时，你必须打败他，然后得到他的旋风之心。我将用它来把塞克隆尼亚的力量注入到一件武器中。；你，你准备好面对风之王了吗？",o="将旋风之心带给捕风者巴斯拉。",p=1712,r={{i=6894,n="旋风之心",c=1}}},
  [1738]={t="同心树",d="为了你的到来，我拨开时间的迷雾，搜寻了整个世界，终于找到了你在寻找的东西。；在上古战争的一场战斗中，有一对恋人一起倒下了。在他们死去的地方，一棵同心树茁壮地生长了起来，那是他们至死不渝的爱情的象征。；那棵树应该足以用来引诱魅魔，你可以在灰谷森林西北的奥迪拉兰废墟里找到它。",o="从灰谷取回同心树，把它交给暴风城法师区里的黑暗缚灵者加科因。",p=1716,r={{i=6912,n="同心树",c=1}}},
  [1740]={t="索兰鲁克宝珠",d="当燃烧军团中的某个恶魔失宠以后，他们的灵魂就会被囚禁在宝珠中，供他们的法师或者术士差遣。；很多宝珠被赐给了艾泽拉斯的恶魔之仆。即使是一颗破碎的宝珠，仍然可以蕴含着强大的恶魔力量。；索兰鲁克宝珠碎成了两块，其中的一块又被砸成碎片，分发给黑暗深渊中的暮光之锤侍僧使用。另一块比较大的碎片在影牙城堡的一个巫师的手中。把它们找来给我，我可以用这些碎片重塑宝珠。",o="找到3块索兰鲁克宝珠的碎片和1块索兰鲁克宝珠的大碎片，把它们交给贫瘠之地的杜安·卡汉。",r={{i=6914,n="索兰鲁克宝珠的碎片",c=3},{i=6915,n="索兰鲁克宝珠的大碎片",c=1}},w={{i=6898,n="索兰鲁克宝珠",c=1},{i=15109,n="索拉鲁克法杖",c=1}}},
  [1782]={t="Furen's Armor",p=1701,f=1},
  [1784]={t="圣洁之书",d="在我陷入苦战以前，我和穆里顿在那座小房子附近几乎干掉了一个黑铁间谍。我们亲眼看见他们的头儿给他一条手令，于是我们就想把他干掉，然后抢到那条手令。；铁炉堡议会里的一些家伙还不相信丹莫罗有黑铁矮人的存在。只要能得到那条手令，我们不仅能证实他们的确在这个地区活动，还能知道他们到底想要做什么。；去拿到那份手令，然后把它交给穆里顿，你。",o="从盔枕湖附近的黑铁矮人那里取回一份黑铁手稿，把它交给铁炉堡的穆里顿·热炉。",p=1783,r={{i=6847,n="黑铁手稿",c=1}}},
  [1787]={t="圣洁之书",d="我们以后再来谈生命符记的事情吧，现在最重要的是把那份迪菲亚盗贼阅读过的文件拿回来。如果能得手的话，我们就能证明迪菲亚盗贼混入艾尔文森林了，甚至还有可能了解到他们的计划是什么。；你觉得你有能力把这些文件从这座小岛上的迪菲亚盗贼手里拿过来吗？；如果你拿到文件的话，就把它交给贾森，顺便告诉他我现在没事了。",o="从石碑湖小岛上的迪菲亚巫师手中拿到迪菲亚手稿，把它交给暴风城的贾森·坦诺姆。",p=1786,r={{i=6846,n="迪菲亚手稿",c=1}}},
  [1792]={t="Whirlwind Weapon",p=1713,w={{i=6975,n="旋风之斧",c=1},{i=6977,n="旋风之剑",c=1},{i=6976,n="旋风之锤",c=1}}},
  [1796]={t="魔化金线血袍",d="我要帮你制作的第一件装备就是长袍，你要负责为我收集若干材料，然后我会把它们组合到一起。这样你就将拥有有首件能使你变得更加强大的装备。；首先，你必须给我拿来一件奥法之袍。你可以去找个裁缝帮忙制作，也可以从其它冒险者手中购买——当然如果你能自己制作的话就更好了。但是无论如何，你要先把奥法之袍交给我，然后我们才能开始。",o="将奥法之袍交给贫瘠之地的梅纳拉·沃伦德。",r={{i=5770,n="奥法之袍",c=1}}},
  [1799]={t="宝珠碎片",d="很好，那么我们开始吧。；首先，你必须到里面去跟我的助手们谈谈，然后决定自己要走哪条路——他们会给你更详细的解释。；然后，你必须到凄凉之地的玛诺洛克集会所去，从那里的某个术士身上找到一颗地狱火珠。你要净化这颗宝珠，隐居在尘泥沼泽南部的一个名叫塔贝萨的法师会帮你完成净化。她肯定会帮助你，因为我们曾有共同的过去。；我再强调一次，这些任务没完成之前，你就别回来见我。",o="在棘齿城外的塔里与梅纳拉的侍僧们谈话，选择自己修行的方式。；然后给尘泥沼泽的塔贝萨带去一颗地狱火珠。",r={{i=7291,n="地狱火宝珠",c=1}}},
  [1802]={t="阴谋之书",d="它是丢了，不过我知道一些可以帮你找到它的线索。；这本书的复制品只有一本，而且它也已经被损坏了，很大一部分的书页全都被撕了下来，现在听说它们落入了千针石林的半人马手里。；其馀的部分在南海镇的西岸丢失了，原本这些书页是要用船送往米奈希尔港的，不过却从来也没能送到。；你看，我告诉了你这么多消息，好歹你也得在找回东西以后拿来给我看看吧？",o="为铁炉堡的克罗姆·粗臂找回发霉的书籍和破损的手稿。",p=1758,r={{i=6931,n="发霉的书籍",c=1},{i=6997,n="破损的手稿",c=1}}},
  [1803]={t="阴谋之书",d="啊！你果然是个品位与我相当的术士呀。事实上，能得到阴谋之书一直是我的一大心愿。你知道那本书一度曾被保存在洛丹伦城里吗？然而，那本书如今已经被摧毁了，大部分的书页都不见了。到底是哪个白痴干出这样可憎的事？；据说，失落的那一半当前在千针石林中的一群半人马手里。；剩下的另一半本来是要被转移到铁炉堡去的，不过在押运过程中丢失在了南海镇西部的海滩上。",o="给幽暗城的约拉·安尼森带回发霉的书籍和破损的手稿。",p=1801,r={{i=6931,n="发霉的书籍",c=1},{i=6997,n="破损的手稿",c=1}}},
  [1805]={t="阴谋之书",d="这书上写的东西是我这几年中看过的文章里最有趣的。这边的书很少，选择也很少——大多数的书都是地理方面的——而且，我都把它们翻来复去地读了好些遍了。我真希望斯坦哈德能抽空给我也送一本这样的书来。；去和他谈谈吧，他在你离开的时候托人给我带来了口信，说是要交给你一个任务，要求你找回三根召唤魔棒。；当然，为了答谢你允许我继续看这本书，我告诉你一个小秘密：你可以在湿地的兽人龙喉氏族那里找到你要的东西。",o="将翻修过的书籍和3根导能魔棒交给棘齿城的斯坦哈德·法尔杉。",p=1803,r={{i=7006,n="翻修过的书籍",c=1},{i=6930,n="导能魔棒",c=3}}},
  [1806]={t="The Test of Righteousness",o="Wait for Jordan Stilwell to finish forging a weapon for you.",p=1654,f=1},
  [1819]={t="切割者奥拉格",d="当亡灵天灾席卷提瑞斯法林地的时候，我们曾经抓住他们中的一员进行研究。他具有自己的意志，并自称为切割者奥拉格。但是，虽然他的意志是自由的，但他仍然只是一个被巫妖王掌控和奴役着的傀儡。；我们希望能够让他脱离巫妖王的控制，但是失败了。现在，我看是时候让他彻底地“解脱”了。；让他解脱，杀了他。；激活北部陵墓那里的颅骨石机关，解除奥拉格身上的魔法封印。；然后……做好准备，你。",o="杀死切割者奥拉格，然后和亡灵卫兵迪林格尔谈一谈。",p=1818},
  [1821]={t="阿加曼德家传武器",d="在我活着的时候，阿加曼德系列是我的主人，但他们也是让我死去的罪魁祸首！现在他们得到了应有的报复，阿加曼德系列已经成为了巫妖王手下的行尸走肉。；现在我要剥夺他们最后的荣耀。到他们系列的墓地里去，帮我抢来他们的传家之宝：一把剑，一柄斧，一柄匕首，还有一把钉锤。将这些东西全都给我拿来！；阿加曼德系列墓穴就在阿加曼德磨坊的最北端，那里有许多亡灵天灾的部队和死去的阿加曼德族人守卫着。",o="把阿加曼德家传长剑、阿加曼德家传战斧、阿加曼德家传钉锤和阿加曼德家传匕首交给库勒曼·法席恩。",p=1820,r={{i=7567,n="阿加曼德家传战斧",c=1},{i=7568,n="阿加曼德家传匕首",c=1},{i=7569,n="阿加曼德家传钉锤",c=1},{i=7566,n="阿加曼德家传长剑",c=1}}},
  [1822]={t="Heirloom Weapon",p=1821,w={{i=7115,n="家传战斧",c=1},{i=7117,n="家传之锤",c=1},{i=7116,n="家传匕首",c=1},{i=7118,n="家传长剑",c=1}},f=2},
  [1824]={t="巨人旷野的试炼",d="要通过试炼，你必须一直向南到巨人旷野去，在那里有一大群叫做异种蝎的昆虫生物。我以前从未在贫瘠之地看到过这种生物，也不知道它们的到来究竟预兆着什么。；把它们的触角交给我，你，要刚刚割下来、还再抽搐的那种。不要浪费时间，因为一旦你把触角割下来，它们很快就会彻底失去活力。在规定的时间内把触角带给我，这样你就通过了考验。",o="收集5根颤抖的触角，把它们带给贫瘠之地陶拉祖营地的鲁迦。",r={{i=7119,n="颤抖的触角",c=5}},f=2},
  [1838]={t="野蛮护甲",d="我听说了关于你的英勇事迹，所以希望能为你制作一套护甲，这能够帮助你去为部落作出更多更伟大的贡献。；但是制作这样一件护甲需要你的帮助，你，如果你能帮助我，那你也就帮助了部落里所有的铁匠。；拿着这个卷轴，这是我经过无数不眠之夜，强睁着我半瞎的眼睛写下的，上面记载着制作护甲所需要的材料。把卷轴上所列出的材料帮我找来，我会为你制作一套护甲。",o="为索恩格瑞姆收集15根烟雾铁锭、10份蓝铜粉、10块铁锭和1瓶燃素。",p=1825,r={{i=7126,n="烟雾铁锭",c=15},{i=7127,n="蓝铜粉",c=10},{i=3575,n="铁锭",c=10},{i=6841,n="燃素",c=1}}},
  [1842]={t="萨特之蹄",d="我可以为你铸造一副具有很强魔法力量的野蛮手套。但是首先，你必须先替我去收集这样的魔法力量。；为了获取这片森林的力量，许多萨特聚集在灰谷的东北面，它们在那里贪婪地吸取和破坏着森林的力量。你可以从它们肿胀的蹄子上判断出到底是哪些萨特在吸取灰谷的魔力。；这些蹄子都有不小的魔法力量，把它们给我带来，这样我就可以给你铸造野蛮手套了。",o="收集7只完整的萨特之蹄，把它们交给杜隆塔尔森金村的尤拉莱克。",r={{i=7128,n="完整的萨特之蹄",c=7}}},
  [1843]={t="Brutal Gauntlets",p=1842,f=2},
  [1844]={t="奇美拉之角",d="我会帮你铸造头盔，但是你必须向我证明你值得我这么做。；石爪山的西南面是一个名叫焦炭谷的山谷，那里曾经是一片郁郁葱葱的森林，但是现在已经被完全被污染，那里剩下的生物也都被痛苦和绝望逼疯了。；现在我就要派你去那里，你。；你必须去焦炭谷找到雌奇美拉，杀死她，让她从苦痛中得到解脱，把她那光滑的奇美拉角带给我作为你完成任务的证据，然后我就会为你铸造头盔。",o="把光滑的奇美拉角交给雷霆崖的奥姆·石蹄。",r={{i=6840,n="光滑的奇美拉角",c=1}}},
  [1845]={t="Brutal Helm",p=1844,f=2},
  [1846]={t="龙喉胫骨",d="要铸造野蛮腿甲，我就需要一些结实的胫骨。湿地里的龙喉兽人就有非常合适的胫骨，我就需要那样的。；但是你一定要确保胫骨是绝对牢固的，在你收集它们的时候记得要试一下它们是不是足够牢固：如果你能徒手把它们弄碎，那么它们肯定不符合我的要求。",o="给幽暗城的维罗拉·奈特雷带去8根结实的龙喉胫骨。",r={{i=7134,n="结实的龙喉胫骨",c=8}}},
  [1847]={t="Brutal Legguards",p=1846,f=2},
  [1848]={t="Brutal Hauberk",p=1838,f=2},
  [1858]={t="碎手氏族",d="你得去想办法把塔赞的包给弄开，这样咱们才能把里面的东西拿出来。这锁的结构还真挺复杂的，所以你想要弄开它的话就只能靠钥匙了。；如果你没有在塔赞的尸体上找到钥匙，那他就一定把钥匙放到某个安全的地方去了……啊，对了！他有一个助手叫加摩尔，是个彻头彻尾的大酒鬼，你八成能在酒馆里找到这家伙。我建议你“安静地”把钥匙从他手里搞来。",o="偷来塔赞的钥匙，用它打开他的背包，然后将里面的物品交给奥格瑞玛暗影裂口的瑟祖克。",p=1963,r={{i=7295,n="塔赞的日志",c=1}},f=2},
  [1861]={t="明镜湖",d="大规模的魔法战争已经使得原本稳定的魔法流开始出现异常的波动。我们正在努力调查这种波动究竟会造成怎样的影响，而有些人已经做好了最糟糕的打算！；但是现在还不能轻易下结论，我们们要派你去收集更多的信息。；拿着这个水袋，到艾尔文森林明镜湖瀑布的底部收集那里的水样，然后把水样给我带回来，这样我就可以用它来进行魔法污染情况的研究了。",o="把一份明镜湖水的样本交给暴风城的詹妮亚·坎农。",p=1860,r={{i=7206,n="明镜湖水的样本",c=1}},w={{i=7508,n="草原宝珠",c=1},{i=9513,n="草原法杖",c=1}},f=1},
  [1880]={t="法师文档存储器",d="我们法师能做的事情可不仅仅是弹动一下手指变出美丽的火花那么简单！我们控制着魔法，控制着构建这个世界的源泉！当然，这需要极大的决心和极强的能力，还有知识……足够多的知识！；我发明的一台设备——法师文档存储器——里面存储着无数的知识。不过问题是，我把它弄丢了！当我们逃离诺莫瑞根的时候，我把它留在城外一座小屋的箱子里，现在那地方麻疯侏儒横行！；你，请帮我取回我的法师文档存储器！",o="帮彬克找回她的法师文档存储器。",p=1879,r={{i=7226,n="法师文档存储器",c=1}},w={{i=7507,n="奥法宝珠",c=1},{i=9514,n="奥法之杖",c=1}},f=1},
  [1882]={t="巴尼尔农场",d="东边的瘟疫之地处于混乱的状态。巫妖王控制下的天灾军团将邪恶的魔法灌入土地之中，腐化并杀死那里的一切生灵。虽然瘟疫具有强大的破坏力量，但是我们——被遗忘者的法师——相信它必定可以被清除掉。；首先，我们必须判断出它在提瑞斯法到底散播到了怎样的程度。到提瑞斯法东部的巴尼尔农场去，在那里的花园中收集一些金鱼草，然后再回来。",o="将巴尼尔金鱼草交给幽暗城法师区的安娜斯塔西娅·哈特威尔。",r={{i=7227,n="巴尼尔金鱼草",c=1}},w={{i=7507,n="奥法宝珠",c=1},{i=9514,n="奥法之杖",c=1}},f=2},
  [1884]={t="魂能骨堆",d="回音群岛的术士扎拉赞恩扰乱了杜隆塔尔的魔法流。他那些邪恶的魂能骨堆就是造成这一切的罪魁祸首，他把那些骨堆放在回音群岛的主岛上。；骨堆破坏了我们的生活，还让在黑暗角落里隐藏着的术士和恶魔获得源源不断的力量。；你必须在魔法流被彻底改变之前摧毁那些魂能骨堆，你。",o="摧毁4个魂能骨堆，然后向森金村的安苏瓦汇报。",w={{i=7508,n="草原宝珠",c=1},{i=9513,n="草原法杖",c=1}},f=2},
  [1886]={t="亡灵哨兵",d="想加入瓦里玛萨斯大人的精英卫队——亡灵哨兵的话，你首先必须证明自己的价值。；坦城地说吧，$n，你很可能在这种证明自己价值的任务中丧命，所以我劝你最好三思而行。；现在，我有一个任务要你去完成。有一位来往于银松森林与幽暗城之间的信使，他叫阿斯托·哈德恩，由于特殊的公务需要，我必须得到他身上的一些私人物品。至于采用怎样的策略去得到这些物品，那是你的事情，不要问我。；如果你的好奇心能小一点，不那么关心这些物品的用途的话，你会过得更自在一些。完成",o="得到阿斯托的介绍信，并将其交给盗贼区的米奈特·卡加德。",p=1885,r={{i=7231,n="阿斯托的介绍信",c=1}}},
  [1898]={t="亡灵哨兵",d="这封介绍信足以使安德隆认为你就是他正在等的那位信使。我之前已经见过安德隆了，估计以他那点脑子是根本不会怀疑你的。；瓦里玛萨斯大人怀疑安德隆正在为某些其它的组织提供援助。他想知道那是个什么组织，而且你要收集到充分的证据。；我要求你在与安德隆的谈话中把这些信息都给套出来，他的店就在炼金房旁边。",o="与幽暗城的安德隆·甘特交谈。",p=1886,r={{i=7231,n="阿斯托的介绍信",c=1}}},
  [1899]={t="亡灵哨兵",d="你在我背后的书架上就可以找到记有你的主子最需要的信息的账本。把它交给他们，记得代我问他们好。哦，还有，告诉他们，如果他们觉得与我合作确实不错，并且还打算按日程继续合作下去的话，他们最好还是派你来。",o="将阿斯托的账本交给幽暗城盗贼区的米奈特·卡加德。",p=1898,r={{i=7294,n="安德隆的账本",c=1}}},
  [1918]={t="被污染的水元素",d="被毁灭的水元素留下了一颗水球，它令你感到极端的厌恶，仿佛污染密斯特拉湖的所有物质都包含在这颗水球中一样。；你不清楚谁会对这个感兴趣，不过碎木哨岗的马斯托克·维尔西斯——那个最初派你来这里的家伙——也许对此有所了解。",o="将被污染的水球交给灰谷碎木哨岗的马斯托克·维尔西斯。",r={{i=16408,n="被污染的水球",c=1}}},
  [1920]={t="调查蓝色隐士",d="有报告称，法师区的蓝色隐士旅店里出现了异常的魔法波动。一些隐形的奇怪生物徘徊在旅店里，我担心那里已经有了一道魔法裂隙。；我希望你去调查一下旅店，捕获那些生物。用旅店中的显形卷轴让它们现出原形，然后用封灵箱抓住它们。当你抓到足够数量的隐形生物之后，就带上装满了的封灵箱和显形卷轴回到我这里来。",o="从詹妮亚·坎农身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给巫师圣殿里的詹妮亚·坎农。",r={{i=7292,n="装满的封灵箱",c=3},{i=7247,n="一盒封灵箱",c=1},{i=7308,n="显形卷轴",c=1}}},
  [1921]={t="收集原料",d="你帮了你的法师同行们很多忙，现在是为你制作巫师长袍的时候了。维恩·拉尔森可以帮你这个忙，不过你必须把必需的原料交给她。；制袍用的亚麻布很容易找到，不过你还必须得到充能裂隙宝石，唯一出产这些宝石的地方是在洛克莫丹的银泉矿洞，它们大多被密封在矮人矿工协会的箱子里。；收集好亚麻布和宝石之后，把它们交给法师区拉尔森服装店里的维恩·拉尔森。",o="把10匹亚麻布和6颗充能裂隙宝石交给暴风城的维恩·拉尔森。",p=1920,r={{i=2589,n="亚麻布",c=10},{i=7249,n="充能裂隙宝石",c=6}}},
  [1938]={t="乌尔的暗影魔法研究论文",d="很久以前，三个法师在暴风城里一起学习法术，直到其中的一个开始研究黑暗魔法。他原本并不想深入其中，但是却发现自己在不经意间越陷越深。最终，他被放逐出了暴风城。；这个被放逐的法师就住在赤脊山的伊尔加拉之塔中，他手中有一本强大的魔法书——《乌尔的暗影魔法研究论文》。；我们这些暴风城的法师希望能把那本书拿回来。你要做的就是溜进伊尔加拉之塔，帮我们取回那本书。",o="将《乌尔的暗影魔法研究论文》交给暴风城的高阶巫师安多玛斯。",r={{i=7266,n="乌尔的暗影魔法研究论文",c=1}}},
  [1940]={t="新鲜的蜘蛛丝",d="你一直在帮助我们，你。我想，也许你应该换一件好点的长袍了，一件更适合资深法师地位的长袍。如果你能收集到必需的原料，我们就帮你做一件新的长袍。；你必须进入暮色森林，猎捕那里的食腐独行蛛。抽出它们的丝，但只有最好的、最纯的丝才行。你得到足够的蛛丝后，就把它们交给维恩·拉尔森来帮你缝制长袍，她就在法师区的拉尔森服装店里。",o="找到8束新鲜的蜘蛛丝，把它们交给暴风城的维恩·拉尔森。",p=1938,r={{i=7267,n="新鲜的蜘蛛丝",c=8}}},
  [1941]={t="Manaweave Robe",p=1921,f=1},
  [1942]={t="Astral Knot Garment",p=1940,w={{i=7511,n="星结长袍",c=1},{i=9516,n="星结外衣",c=1}},f=1},
  [1944]={t="克萨维亚之水",d="传说中的克萨维亚城位于灰谷的东部，据说在那里可以找到所有智者都渴望获得的古代知识，而克萨维rn亚之水也具有超强的魔法力量。；我需要一些克萨维亚之水——要从水源直接取得的那种。；拿着这只瓶子，去寻找传说中的克萨维亚城吧。从那里最高的瀑布底部收集水样，然后把它交给我。在那里你要步步小心，萨特占领了整个遗迹，它们一定不会喜欢让多事的法师侵入它们的领地。",o="将克萨维亚水样交给奥格瑞玛的迪诺。",r={{i=7268,n="克萨维亚水样",c=1}}},
  [1945]={t="欢笑的姐妹",d="我已经把为你制作新袍子的事情安排妥当了，就等你来提供一些材料……；我需要一些头发来制作你的法袍，你应该可以在灰谷的树妖身上弄到符合条件的头发，那些树妖们都聚集在林中树居那里。；当你找到足够的材料之后，就把它们交给贫瘠之地十字路口的基尔哈拉，他是一个巨魔裁缝。他正等着为你制作最新款的法袍。",o="给十字路口的基尔哈拉带去12缕欢笑姐妹的头发。",p=1944,r={{i=7270,n="欢笑姐妹的头发",c=12}}},
  [1946]={t="Nether-lace Garment",p=1945,w={{i=7512,n="虚灵长袍",c=1},{i=9515,n="虚灵外套",c=1}},f=2},
  [1950]={t="解封咒语",d="我可以给你书，但你得先帮助我！；你要找的书被锁在我的魔法箱里了。必须念出一些咒语才能打开它，但是我忘记这些咒语了！通常都是我的助手帮我记这些事情，但现在他也不知道跑哪里去了。；如果你想要我的书，那就得先找到我的学徒！到赛车道周围去问问——如果幸运的话，会有人知道他在哪里的。要么把他给我带回来，要么从他那儿问到咒语，不然就别想打开我的箱子！",o="找到提尔斯保险箱的解封咒语，然后向提尔斯复命。",p=1949},
  [1951]={t="能量仪祭",d="嗯……我想起来了，我的书已经没有了！你要知道，我欠了一屁股的债，不得不把最后一册《能量仪祭》卖掉来还债，我把它卖给了一个牧师……；他是血色十字军的成员。他一定把那本书带到了他们的根据地——提瑞斯法林地里的血色修道院图书馆去了！；如果你想要那本书的话，就得去一趟修道院。很抱歉给你带来这么多麻烦，这些天我已经有些头昏脑涨了……",o="将《能量仪祭》交给尘泥沼泽的塔贝萨。",p=1950,r={{i=7274,n="能量仪祭",c=1}}},
  [1952]={t="Mage's Wand",o="Speak with Tabetha after her ritual.",p=1951,w={{i=7514,n="冰怒魔杖",c=1},{i=11263,n="虚空灵力魔杖",c=1},{i=7513,n="怒火魔杖",c=1}}},
  [1954]={t="地狱火宝珠",d="首先，我们必须弄到一颗有魔力的宝珠。火刃氏族的术士有高质量的宝珠……糟糕的是，他们将恶魔收入了宝珠里！当然我们可以解决这个问题，对……我们可以。；到凄凉之地去，从火刃召唤师那里夺取一颗地狱火宝珠。那帮家伙通常在玛诺洛克集会所活动。；拿到宝珠之后就尽快返回我这儿来。",o="将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。",p=1953,r={{i=7291,n="地狱火宝珠",c=1}}},
  [1955]={t="驱除魔鬼",d="既然我们已经得到了召唤师的宝珠，现在就让我们来把恶魔从里面驱赶出来。我能做到，这部分相当容易。；我有个艰巨的任务给你，你必须在恶魔出现的时候杀死它。；而且动作要够快。如果你耗时过久的话，或许它就会再跳进去，那我们又得重来一次了！；所以你得准备好最强的技能和所有的物品，如果你有朋友的话，也一起叫上。这件事情不会很轻松的。",o="杀死宝珠之魔，然后与塔贝萨谈一谈。",p=1954},
  [1956]={t="奥达曼的能量源",d="既然恶魔已经被消灭了，接下来我们就得去找一个能量源。不幸的是，最合适的能量源往往非常古老而且极难获得。有的时候，命运就喜欢这样捉弄你，难道不是吗？；所以，为了得到能量源，你必须到奥达曼去打败那里的黑曜石守卫。他体型巨大而且很难对付，但是你可以从他身上得到我们所需要的能量源！；祝你好运，你。如果你运气不好的话，那么……很高兴认识你。",o="找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。",p=1955,r={{i=8053,n="黑曜石能量源",c=1}}},
  [1957]={t="法力怒灵",d="我们几乎已经要大功告成了，但是最后一步也是最危险的，你。；我有一颗空的召唤宝珠，准备给它注入力量。我们将通过一道魔法裂缝来完成这个步骤，首先，我会念一段咒语来打开裂缝，此时特殊的生物——法力怒灵将大量涌出来。你必须打败这些生物以释放它们的能量，我会及时用宝珠收集这些能量。；在裂缝关闭之前杀死足够多的法力怒灵，我会把所有收集起来的能量注入你的宝珠。",o="在限定时间内杀死12只法力怒灵。",p=1956},
  [1958]={t="Celestial Power",p=1957,w={{i=7515,n="苍穹宝珠",c=1},{i=9517,n="苍穹手杖",c=1}}},
  [1960]={t="调查炼金店",d="在炼金房的奥格诺恩炼金店里有一股奇怪的魔法波动。由魔法能量构成的隐形生物在商店里四处游荡，这其中一定有什么原因，我们必须找到它！；我希望你去调查一下，捕获那些生物。用我身后的显形卷轴让它们现出原形，然后用封灵箱抓住它们。当你抓到足够数量的隐形生物之后，就带上装满了的封灵箱和显形卷轴回到我这里来。",o="从安娜斯塔西娅·哈特威尔身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给幽暗城的安娜斯塔西娅·哈特威尔。",r={{i=7292,n="装满的封灵箱",c=3},{i=7247,n="一盒封灵箱",c=1},{i=7308,n="显形卷轴",c=1}}},
  [1961]={t="收集原料",d="你，是时候为你制作你的第一件法师袍了。那会是你地位的标志，同时也是对你的一次考验。；你必须从银松森林的达拉然法师身上获得制作法袍所必需的法力宝石。那些法师和我们拥有相似的信仰，所以杀掉他们会是一件让人感到不快的事情，但是既然他们不具备抵御我们的力量，那他们也就没有继续存活下去的价值了。；把宝石和亚麻布交给法师区裁缝店里的乔瑟夫·格里高利，他会为你制作你的第一件法师袍。",o="把10块亚麻布和6块达拉然法力宝石带给乔瑟夫·格里高利。",p=1960,r={{i=2589,n="亚麻布",c=10},{i=7293,n="达拉然法力宝石",c=6}}},
  [1962]={t="Spellfire Robes",p=1961,f=2},
  [1963]={t="碎手氏族",d="酋长行事的方法实在是有些太谨慎了。他总是很小心地不让部落显得过于锋芒毕露。一旦我们足够强大了，我们的力量将能征服一切。部落必须重现往日的荣耀和尊严，而现在看来能做到这一点的就只有我们碎手氏族了。；我们必须在暗中积蓄力量，再突然向敌人发起致命的打击，神不知鬼不觉地将敌人除掉。如果你想加入我们，就必须先为我完成一个任务，以此来证明你自己的价值。；有个名叫塔赞的巨魔在棘齿城附近和海盗们做交易，而他那里有我感兴趣的消息。杀了他，把他的背包拿来给",o="杀死塔赞，把他的背包带给奥格瑞玛暗影裂口的瑟祖克。",p=1859,r={{i=7209,n="塔赞的背包",c=1}}},
  [1978]={t="亡灵哨兵",d="辛迪加？我竟然从来都没有想到是他们，看来奥特兰克的那些贵族们自从背叛联盟以后真是愈加堕落了。；瓦里玛萨斯大人知道了这些一定会非常高兴，另外，既然你在这次侦查行动中表现得这么出色，那么，就由你把我们的调查结果给他送过去吧。；啊，我怎么可能忘了说这个呢！；欢迎加入亡灵哨兵的行列。",o="将安德隆的账本交给幽暗城黑暗女王大厅里的瓦里玛萨斯。",p=1899,r={{i=7294,n="安德隆的账本",c=1}},f=2},
  [1998]={t="芬维克·萨托斯",d="瓦里玛萨斯大人刚刚给我下达了一道命令，要求我派人去把一个对我们构成巨大威胁的家伙立刻铲除掉。他的名字是芬维克·萨托斯，瓦里玛萨斯大人认为他是一群在银松森林中肆虐的亡灵的领袖。；一接到这个任务，我马上就想到了你，$n。我坚信，以你的能力一定可以将这个任务轻松完成。；我们派遣到银松森林的亡灵哨兵们发回的最新报告中指出，萨托斯就躲藏在洛丹米尔湖岸边的一处废弃码头上。",o="杀掉芬维克·萨托斯，把他的徽记交给幽暗城盗贼区的米奈特·卡加德。",r={{i=7306,n="芬维克的徽记",c=1}}},
  [2038]={t="宾格斯的补给品",d="好象在洛克湖坠机还不够倒霉似的，湖心小岛上来的穴居人还袭击了我，抢走了我的工具和气压炸弹。没有旋翼机没有炸药，我什么都干不了！；去帮我找回工具和气压炸弹，你。为了诺莫瑞根！",o="找回宾格斯的装备：；$宾格斯的气压炸弹、宾格斯的扳手、宾格斯的榔头和宾格斯的螺丝起子。",r={{i=7343,n="宾格斯的扳手",c=1},{i=7345,n="宾格斯的螺丝起子",c=1},{i=7346,n="宾格斯的榔头",c=1},{i=7376,n="宾格斯的气压炸弹",c=1}},f=1},
  [2040]={t="地底突袭",d="诺莫瑞根已经被那群卑鄙懦弱的穴居人们完全占据了！情况很紧急，或许你能帮上我们的忙，你。；在死亡矿井深处有一台功能强大的地精伐木机，找到这台伐木机并带回它的能源供应机件。有了这台伐木机的能源供应机件，我们就能给高速钻孔挖掘机供应足够的能量，用它来钻透这里与诺莫瑞根之间的岩石。钻开一条路，给他们来一次侏儒式的突袭！",o="从死亡矿井中带回规模高能发动机，将其带给暴风城矮人区中的沉默的舒尼。",r={{i=7365,n="小型高能发动机",c=1}},w={{i=7606,n="极地护手",c=1},{i=7607,n="紫貂魔杖",c=1}},f=1},
  [2098]={t="基尔卡克的钥匙",d="想要当一个出色的海盗可不简单呀，你这个旱鸭子是不会理解的。我们的生活并不仅仅只是掠夺和痛饮！唉，我的船在海岸附近被那些可恶的鱼龙给弄沉了。；我希望我的大副能够重新回来工作！；当我被冲到海岸的时候，大副的钥匙在岩石上折断了，接着又被黑海岸那一带的怪物给偷走了，我只记得隐约看见一些狂暴暗礁蟹、凶猛的森林陆行鸟和几个鱼人正在搜寻船的残骸……",o="找到基尔卡可钥匙的3段碎片，把它们交给基尔卡克·旋杆。",r={{i=7498,n="基尔卡克钥匙的头部",c=1},{i=7499,n="基尔卡克钥匙的中部",c=1},{i=7500,n="基尔卡克钥匙的尾部",c=1}}},
  [2118]={t="瘟疫蔓延",d="一种疾病正在黑海岸蔓延，它能够控制一切与它接触的灵魂和肉体。；这种瘟疫对蓟熊的影响最大，使得这种曾经高贵的动物现在几乎变成了毁灭和杀戮的机器——它们变得狂暴，完全失去了理智。我有一种方法应该可以治疗这种病。；把这个陷阱放到森林的空地上。任何狂暴蓟熊经过时，都会在短时间内变得驯服。一旦蓟熊安静下来了，就上前安抚它，减轻它的痛苦（使用/soothe命令），然后它就会跟你走。把它带到这里来，你。",o="活捉一只狂暴蓟熊，把它带到萨纳瑞恩那里。"},
  [2138]={t="清除疫病",d="正如我所担心的，这种疗法没有起到效果。；对我来说，任何野生动物的死都是一件令我难过的事情，但是我们必须杀掉这些感染了瘟疫的狂暴蓟熊。；你，回到森林里去，杀掉20只狂暴蓟熊。这虽然无法驱散瘟疫，但可以在短期内降低狂暴蓟熊对这片森林和森林里的居民们带来的破坏。",o="到森林里去杀掉20头狂暴蓟熊。",p=2118},
  [2139]={t="萨纳瑞恩的希望",d="你，我们用惨痛的代价换取了黑海岸和奥伯丁的平安。；你杀了很多早已病入膏肓的动物，减轻了森林的痛苦，也解脱了这些动物的灵魂。尽管这种状况只能持续一小会儿，但是奥伯丁的人民感谢你。；我要交给你最后一项任务，请注意，这将是又一次的杀戮任务。我希望这是最后一次让你去做这样的事情，你。；有一只雌蓟熊住在东北方的一个靠近巴莎兰的洞穴里，杀了她。",o="找到雌蓟熊，然后杀掉它。",p=2138,w={{i=7738,n="常青手套",c=1},{i=7739,n="林木斗篷",c=1}},f=1},
  [2198]={t="破碎的项链",d="你找到了一条破碎的项链，但是破旧不堪的外表并不能掩饰它高超的制作工艺。项链已经破碎，原本应该镶在项链上的三块宝石不见了。在项链的内侧印有铁炉堡的徽记，旁边还刻着三个小字：“TdK”。；如果你想要了解这条项链背后的故事，你就必须找到它的主人。也许那个徽记和小字就是线索……",o="找到破碎的项链的来源，从而了解其潜在的价值。",r={{i=7666,n="破碎的项链",c=1}}},
  [2199]={t="昂贵的知识",d="我在铁炉堡可是鼎鼎有名的珠宝匠！好吧，我承认那是以前的我……因为一个竞争对手的污蔑让我变成现在这个样子！名声不好在这行里就根本混不下去。结果，你看，我现在就变得穷困潦倒。；现在，我要你给我搞五块银锭来，这样我才能完成我手头上的这份订单——看来这是我唯一的一份订单了。；你给我五块银锭之后，我就会回答你所有关于这条项链的问题。",o="给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。",p=2198,r={{i=2842,n="银锭",c=5}}},
  [2201]={t="寻找宝石",d="从这个圣骑士的日记上看，只有奥达曼才有可能是项链上的那三块宝石的所在地。如果日记的描述还算准确的话，在奥达曼里有大量的暗炉矮人和穴居人在活动。；知道了这些信息之后，对宝石的搜索行动就可以开始了。当你收集到所有的宝石之后，通过塔瓦斯德的占卜之瓶和他联系来获取下一步的指示。",o="在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。",p=2200,r={{i=7669,n="破碎项链上的红宝石",c=1},{i=7670,n="破碎项链上的蓝宝石",c=1},{i=7671,n="破碎项链上的黄宝石",c=1}}},
  [2202]={t="奥达曼的蘑菇",d="你，我听说有一种紫色蘑菇刚刚被发现，它们似乎只在奥达曼挖掘场里生长。我需要十二个这样的蘑菇来进行炼金术的研究。；你要多加小心，这种蘑菇会喷射出有毒的孢子。；帮我这个忙吧，我会给你丰厚的报酬，另外还可以让你尝尝我收藏多年的好酒！",o="收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。",p=2258,r={{i=8047,n="紫色蘑菇",c=12}}},
  [2204]={t="修复项链",d="你现在需要去为项链找到它的“精神”力量，奥达曼无疑最适合的地方。据说那里有很多的石人跑来跑去，对吗？那么，杀死他们当中最强大、最邪恶的那个石人，然后把他身上的能量源夺过来！我敢保证可以把那能量源里的能量重新注入到项链之中。；如果没有那样的能量源，想要修复项链根本是不可能的。取得能量源之后尽快回到铁炉堡来找我，然后我们就能把项链完全恢复到原来的状态啦！",o="从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。",p=2201,r={{i=7672,n="破碎项链的能量源",c=1}}},
  [2206]={t="连偷带抢",d="我们派在外面的探子回报说，迪菲亚兄弟会在闪金镇南部的活动相当频繁。报告中还说道，迪菲亚兄弟会控制了杰罗德码头，并利用它将大量的违禁品从赤脊山走私到西部荒野去。；我要你想办法到码头旁的屋子里去一趟，把里面的船运时间表给我偷出来，那东西应该就在码头主管的衣服口袋里。；……还有，你，如果你的行动被发现了的话，暴风城军情七处将不会承认你的存在。",o="找到迪菲亚码头主管，从他那里为马迪亚斯·肖尔拿到迪菲亚船运时间表。",r={{i=7675,n="船运时间表",c=1}},f=1},
  [2239]={t="奥宁的报告",d="你是说采石场？是的，我几乎天天都能看见那些庞大的蒸汽坦克从营地边经过。；我在东边布下的线人告诉我，这些机车是从铁炉堡出发的，在古博拉矿场稍作停留之后，在卡拉诺斯补给燃料，由于某些该死的原因，他们用了很长的时间才经过诺莫瑞根，最后在铁炉堡卸下了货物。；情况全都写在这份报告里了，$c。把它交给霍夫丹，让他好好计划下一步的行动。",o="把奥宁的报告交给铁炉堡的霍夫丹。",p=2238,r={{i=7715,n="奥宁的报告",c=1}},f=1},
  [2240]={t="密室",d="现在我手头有个任务。；我们要找到一间被称作卡兹穆尔大厅的密室。问题是这个房间在一扇巨大的门后面，而那扇门被锁住了！幸运的是，我知道如何打开它。；我把所有东西都写在我的日记里了，就在这个台子上。我的队伍现在被困在这里……所以呢，$n，你必须为我们找到卡兹穆尔大厅！；阅读我的日记，探索那间密室，然后向铁炉堡探险者协会的勘察员塔伯斯·雷矛汇报。",o="阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。",p=2398,w={{i=9626,n="矮人冲锋斧",c=1},{i=9627,n="探险者联盟之星",c=1}},f=1},
  [2242]={t="命运的召唤",d="我们相信有一个萨特可以帮助我们搞清泰达希尔的森林中究竟发生了什么。但不幸的是，他可不会老老实实地跟我们合作。；他的藏身之处就在神谕林地外围的一棵树上，但是与他接触的人——无论是使用武力还是试图交涉——都被他杀死了。也许只有偷偷摸摸地行动才是唯一可行的方案，你。；去看看塞希尔的包裹里有些什么，然后回来向我报告。",o="找到远古的塞希尔，带回任何你可能发现的线索。",r={{i=7737,n="塞希尔的日记",c=1}},f=1},
  [2258]={t="荒芜之地的试剂",d="玩家，我需要你的帮助。我是个略有名气的炼金术者，现在我想请你去荒芜之地帮我弄些试剂来。；我需要以下物品：5个秃鹫的胃囊，10颗峭壁山狗的牙齿，还有5个石元素的碎片。当然，你可以从那里的野兽身上弄到这些东西，但是假如你不是那么善于战斗的话，就去找一些朋友帮帮忙吧。；帮我找到这些物品，我就会给你些钱作为报酬。愿意试试吗？",o="转至荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。",r={{i=7847,n="秃鹫的胃囊",c=5},{i=7846,n="峭壁山狗的牙齿",c=10},{i=7848,n="石元素的碎片",c=5}}},
  [2278]={t="白金圆盘",d="财宝室的中间是四块巨大的白金圆盘，每块圆盘上都刻满了各种各样的未知文字和图案。你的手触摸这些圆盘的时候，你感到了一丝震动。就在你接触圆盘的一瞬间，一个巨大的石头守卫者的形象出现在了你的面前。；“你好。我是知识的守卫者。土灵的创造者所留下的一切有关这个种族的知识都已经存储在了这张诺甘农圆盘上了。”；你发掘到了迄今为止这个世界上最宝贵的知识财富！",o="和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。"},
  [2279]={t="白金圆盘",d="再次触及诺甘农圆盘让你的手感受到了又一次的震颤。这一次从圆盘传出了一种奇怪的研磨声。；你的背包忽然沉了一下。打开背包之后，你发现了一张迷你版的圆盘！；毫无疑问，在任何对艾泽拉斯大陆历史感兴趣的人手中，这张圆盘都绝对是无价之宝。铁炉堡的探险者协会是一个非常有名的探险团体，也许他们能好好利用这张圆盘。",o="把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。",p=2278,r={{i=6064,n="迷你白金圆盘",c=1}}},
  [2280]={t="白金圆盘",d="再次触及诺甘农圆盘让你的手感受到了又一次的震颤。这一次从圆盘传出了一种奇怪的研磨声。；你的背包忽然沉了一下。打开背包之后，你发现了一张迷你版的圆盘！；毫无疑问，在任何对艾泽拉斯大陆历史感兴趣的人手中，这张圆盘都绝对是无价之宝。雷霆崖的先知们对历史知识的了解程度享誉整个部落，也许他们能好好利用这张圆盘。",o="把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。",p=2278,r={{i=6064,n="迷你白金圆盘",c=1}}},
  [2283]={t="搜寻项链",d="我们有工作要交给你做，不过能否完成要看你有没有胆子！；在荒芜之地的深处有一个名叫奥达曼的挖掘场，我们最近听说有个没脑子的圣骑士在里面挂了。我之所以如此关心这个问题是因为那蠢货身上带着一条非常珍贵的项链，项链上有三块大宝石：一块红宝石，一块蓝宝石和一块黄宝石。；现在的问题是，我们需要它，而且我们会付给完成这个任务的人最丰厚的报酬。也许那条项链已经受到了损坏，但是不管怎么样，只要你把它带给我们，就总是会有办法修好它。",o="在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。",r={{i=7666,n="破碎的项链",c=1}}},
  [2338]={t="翻译日记",d="杜佛斯那个蠢货是不可能恢复项链的力量的，不过我可以。现在我要做的就是好好研究一下项链，然后给你制作一条跟它完全一样的复制品。请把项链借给我作为我帮你翻译日记的交换吧，在你出发去找寻宝石的这段时间里，我应该可以完成对项链的研究和对日记的翻译工作。；这个交易很简单明了，而且没有别人可以帮你翻译日记。你看怎么样？",o="将项链借给加卡尔。作为交换，他将帮你翻译日记。",p=2318,r={{i=7886,n="未翻译的日记",c=1}}},
  [2339]={t="寻找宝贝",d="日记已经全部翻译完毕了。；其中的关键是红宝石在暗炉矮人手里，黄宝石在穴居人手里，而蓝宝石则在一个名叫格瑞姆洛克的穴居人那里。；你需要一个强力能力源来让项链重新恢复以前的力量，这一点是德兰·杜佛斯所不知道的。我所能想到唯一符合如此要求的能量源应该在奥达曼的最强生物身上，所以你必须深入奥达曼的最底层，杀掉所有看上去最强的生物，这样你就肯定可以获得它。；当你把所有东西找全之后就尽快把它们带回来给我。",o="从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。；红宝石被藏在暗影矮人层层设防的地区。；黄宝石藏在穴居人活动地区的一个瓮中。；蓝宝石在格瑞姆洛克手中，他是穴居人的领袖。；能量源可能在奥达曼的某个最强生物的手中。",p=2338,r={{i=7669,n="破碎项链上的红宝石",c=1},{i=7670,n="破碎项链上的蓝宝石",c=1},{i=7671,n="破碎项链上的黄宝石",c=1},{i=7672,n="破碎项链的能量源",c=1}}},
  [2340]={t="交付宝石",d="只要采用相同的材料进行制作，任何的项链和宝石的组合都能发挥作用。而这个能量源才是真正给项链提供力量的关键……我希望如此。；只要能量源能够一直保持正常运转，我随时都可以为你制作这么一条项链。；去奥格瑞玛找德兰·杜佛斯完成你们的交易吧。记住不要透露任何关于项链的信息，当你回来的时候，我会给你一个特别的惊喜的。",o="把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。",p=2339,r={{i=7887,n="项链和珠宝",c=1}}},
  [2341]={t="Necklace Recovery, Take 3",o="Visit Jarkal Mossmeld in Kargath to see if he was successful.",p=2340,f=2},
  [2359]={t="克拉文之塔",d="我为如何进入这座塔的问题头痛好久了，你。最近从暮色森林来了一船货物，同时还来了不少守卫。；他们是谁？我也有着和你一样的疑问。我所知道的是——他们不是人类。；不管怎么样，这批货物中有一只特殊的箱子——我想这就是那些亡灵在守护的东西。带着狼牙棒的那个家伙手里有那座塔的钥匙。；拿到钥匙，进入塔里，看看箱子中到底有什么，然后去向马迪亚斯报告。",o="偷取迪菲亚塔楼钥匙，进入迪菲亚塔楼，看看暮色森林的箱子里到底有什么东西，然后向暴风城的马迪亚斯·肖尔汇报。",p=2360,r={{i=7908,n="克拉文·摩特维克的日记",c=1},{i=7923,n="迪菲亚塔楼钥匙",c=1}}},
  [2361]={t="Restoring the Necklace",p=2204,f=1},
  [2418]={t="能量石",d="不久之前，我和暗炉矮人打过一段时间的交道。他们把我带到了苦痛堡垒，让我对两种来自于奥达曼的奇怪石头进行研究。我发现这两种石头如果经过正确的处理，就会变成相当理想的能量源。能在那个废旧的挖掘场里发现这样的东西让我感到十分惊奇！；之后，在我告诉他们这个秘密之后，那帮该死的家伙就把我踢出了苦痛堡垒，然后自己在奥达曼挖掘更多的石头。；我要为自己搞一些那种石头！帮我带那两种石头来，我会给你丰厚的报酬的。",o="给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。",r={{i=8009,n="德提亚姆能量石",c=8},{i=8052,n="安纳洛姆能量石",c=8}},w={{i=9522,n="能量石环",c=1},{i=10358,n="杜拉辛护腕",c=1},{i=10359,n="持久长靴",c=1}}},
  [2438]={t="翡翠摄梦符",d="班奈希尔兽穴的德鲁伊守护者盖洛拉斯·塔文斯伦曾经给了我一个翡翠摄梦符。这种强大的护符可以吸取翡翠梦境的能量，给拿着它的人带来好运。；不过，我把它放在星风村的衣柜里了，没办法把它取回来……星风村原本是个宁静的小村子，但现在那里受到了熊怪的侵袭。；你能不能帮我拿回摄梦符，$c？",o="将翡翠摄梦符交给多兰纳尔的塔隆凯·捷根。",r={{i=8048,n="翡翠摄梦符",c=1}}},
  [2439]={t="白金圆盘",d="这东西真是个惊人的发现。如果这里储存的知识都是正确的话，那么这些圆盘所涉及的古代泰坦——或者说造物之神——肯定和我们的起源有所联系！我们要用尽可能多的时间来研究它。；至于你，英勇的$c，把这个凭证交给大厅里的丁尼塔·石衣，你一定会为你的伟大发现得到应有的报酬！；准备好了之后就回到我这里来，探险者协会还有很多事等着你去做！",o="把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。",p=2279,r={{i=8070,n="报酬凭证",c=1}},w={{i=3928,n="优质治疗药水",c=5},{i=6149,n="强效法力药水",c=5}}},
  [2440]={t="白金圆盘",d="我要把精力都集中在这些圆盘上，它们一定会向我展示其真正的作用。；至于你，你，你的努力也会得到我的回报。把这个证明交给雷霆崖的炼金师本娜·冰蹄，她会给你一样不错的东西作为回报，还会给你一些我私人收藏的药水。；尽快回来见我，我感觉这个发现还会让我有很多事要忙。",o="把报酬凭证交给雷霆崖的本娜·冰蹄。",p=2280,r={{i=8070,n="报酬凭证",c=1}},w={{i=3928,n="优质治疗药水",c=5},{i=6149,n="强效法力药水",c=5}}},
  [2478]={t="基本不可能的任务",d="你必须从工头希里克斯身上偷出塔楼的钥匙，你。拿到钥匙之后，就把它收好——你也许用得到它。；记住，毒药已经让塔楼里的所有人都变得虚弱不堪。尽你所能给那些家伙制造混乱和破坏——不要手下留情！；等里面所有人都倒下之后，你就可以去打开加里维克斯的箱子，然后拿走赞吉尔的改良药剂。把加里维克斯的徽记和药剂一起交给奥格瑞玛的申苏尔。",o="从工头希里克斯那里偷出希里克斯的塔楼钥匙，进入塔楼，然后杀掉两个变异风险投资公司工人、两个风险投资公司巡逻员、两个风险投资公司看守。；杀掉大工头普兹克·加里维克斯，取得他的徽记，然后打开加里维克斯的箱子，拿走赞吉尔的改良药剂。将药剂和加里维克斯的徽记交给奥格瑞玛的申苏尔，等候进一步的指示。",p=2458,r={{i=8074,n="加里维克斯的徽记",c=1},{i=8072,n="希里克斯的塔楼钥匙",c=1},{i=8073,n="赞吉尔的改良药剂",c=1}}},
  [2479]={t="希诺特的帮助",d="把这个混合物的样本交给塔伦米尔的瑟尔格·希诺特。；只有瑟尔格能治得了你所中的毒。如果你能活得久一点的话，他还能教你制造并使用这种毒药的方法。",o="到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。；要去塔伦米尔，可以搭乘飞艇到幽暗城，然后沿着大路向南穿过银松森林，直到希尔斯布莱德丘陵。跟着路标走！",p=2478,r={{i=8087,n="赞吉尔的药剂样品",c=1}}},
  [2499]={t="奥肯斯古尔",d="在湖南岸的山洞里有一个名叫奥肯斯古尔的林精，它正在使居住在奥拉密斯湖周围的所有生物变得堕落。；我不敢离那里太近，不过即使从远处看去，我也能看得很清楚：奥肯斯古尔已经被一颗我所见过的最大的肿瘤所毒害了……那个肿瘤简直可以被称作庞然大物。；你，你已经帮了我许多忙，不过我还要请你做一件事。杀掉奥肯斯古尔，拿到它身上的肿瘤，让这个堕落之源永远从我的家园消失。",o="奥拉密斯湖的德纳兰要你去拿到奥肯斯古尔身上的巨大的瘤。",p=2498,r={{i=8136,n="巨大的瘤",c=1}},w={{i=5458,n="泥木腰带",c=1},{i=5589,n="苔藓覆盖的护手",c=1}},f=1},
  [2500]={t="荒芜之地的材料",d="玩家，我需要你的帮助。我是个小有名气的炼金师，我需要你去荒芜之地帮我找一些原材料。；我需要这些东西补充我的库存：五个秃鹫的胃囊、十颗峭壁山狗的牙齿和五块岩石元素碎片。当然你可以从这些动物身上拿到这些东西，不过如果你不擅长打仗的话，可以找些擅长的朋友。；找到这些东西给我，作为交换你可以得到一些钱币。；好吧，你觉得怎么样？",o="从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。",r={{i=7847,n="秃鹫的胃囊",c=5},{i=7846,n="峭壁山狗的牙齿",c=10},{i=7848,n="石元素的碎片",c=5}}},
  [2518]={t="月神的泪水",d="萨丝拉曾经受到月神的宠爱，这只优雅而纯洁的蜘蛛在月光下的迷雾中编织着银线，用以收集银色的露水，并将这种有治疗功效的露水存放在这个大殿里。；不过最近萨丝拉却突然变得疯狂起来，她的后代也受到了威胁。；找到萨丝拉，你，结束她的痛苦。她住在泰达希尔的北部边界。找到她的银色丝囊，把它们交给我。",o="达纳苏斯月神殿的女祭司艾茉拉让你把萨丝拉的银色丝囊交给她。",r={{i=8344,n="银色丝囊",c=1}}},
  [2520]={t="萨丝拉的祭品",d="现在你必须完成交给你的任务。拿上银色丝囊，然后将它作为萨丝拉的祭品献给艾露恩，让这只蜘蛛得以安息。；找到大殿中央的喷泉，在那儿放下祭品。神圣的泉水可以净化并清洗让萨丝拉发疯的堕落力量。；完成任务之后再回来见我。",o="女祭司艾茉拉让你将萨丝拉的银色丝囊放在大殿的喷泉处，然后回去见她。",p=2518,w={{i=9600,n="饰带短裤",c=1},{i=9601,n="软垫靴",c=1}},f=1},
  [2521]={t="为库米沙效力",d="你，你的小脑袋能理解一颗无瑕的德莱尼水晶球有多么珍稀吗？无数德莱尼人终其一生就想要寻找一块这样的水晶，可是却屡遭失败，一直没能达到愿望。；你现在就站在库米沙面前，你知道库米沙想要什么，而且你还愿意帮助我？很好，$r……在你探索者个区域的过程中，只要找到一颗无瑕的德莱尼水晶球，就把它带回来给我，我会以你永远都无法想象的财富回报你。",o="在你探索诅咒之地的旅程中，如果碰巧发现了无瑕的德莱尼水晶球，就把它交给收藏家库米沙。；你要知道，这种宝石是整个艾泽拉斯最珍稀的水晶。诅咒之地上的任何一种生物都有可能带着一颗无瑕的德莱尼水晶球。；每找到一颗，你都会得到相应的酬劳。",r={{i=8244,n="无瑕的德莱尼水晶球",c=1}}},
  [2541]={t="沉睡的德鲁伊",d="这里的瘤背萨满祭司找到了一种可以在德鲁伊休眠时将他的灵魂和肉体分离的方法。熊怪就这样驱使着我的肉身，利用我去袭击那些对班奈希尔兽穴进行侦查的人。现在我沉睡在翡翠梦境里，无法阻止他们。；你一定要帮帮我。瘤背萨满祭司用一种特殊的符咒来完成这种仪式，我希望能研究一下这种咒符。$n，全靠你了。",o="将一个萨满巫毒符咒交给班奈希尔兽穴的奥本·怒爪。",r={{i=8363,n="萨满巫毒符咒",c=1}}},
  [2561]={t="利爪德鲁伊",d="在研究过这个咒符之后，你，我知道该做什么了。请拿着它，然后照我说的去做。；你必须到班奈希尔兽穴的深处去，在那里，你会发现我那失去灵魂的躯体……虽然我对将要让你这么做感到很遗憾，但是除此之外我找不到其它可以让我摆脱瘤背熊怪控制的办法了。；你必须杀了我的肉身，然后对我的尸体使用巫毒咒符。完成这个任务之后就请回到我这里来。",o="奥本·怒爪要求你去杀掉他那失去灵魂的身体，然后对其尸体使用巫毒咒符。",p=2541,w={{i=9598,n="沉睡长袍",c=1},{i=18957,n="灌木之刃",c=1}},f=1},
  [2581]={t="弯牙土狼的颚骨",d="众所周知，土狼的颚骨具有强大的力量，不过它能折断三英寸厚的瑟银条吗？不可能，决不可能，可是我却亲眼看到了这种事情。；到诅咒之地去给我弄三个弯牙土狼的颚骨回来，路上顺便打一些野猪和蝎子，因为我还需要两片诅咒之地的野猪肺和一个厚甲蝎螯。",o="收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。",r={{i=8391,n="弯牙土狼的颚骨",c=3},{i=8392,n="诅咒之地的野猪肺",c=2},{i=8393,n="厚甲蝎螯",c=1}}},
  [2583]={t="野猪的活力",d="这片不毛之地上生活着两种野猪：灰鬃野猪和地狱野猪。；看来这些野兽的耐力十足，这让它们几乎可以不受任何伤害，因此其它动物都无法与之抗衡。；我们要做进一步的研究，你。你给我弄三片诅咒之地的野猪肺、两个厚甲蝎螯和一颗石化蜥蜴的大脑来，我就可以从中提炼出一种超强的药剂。而你就将成为我的第一个实验对象！",o="收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。",r={{i=8392,n="诅咒之地的野猪肺",c=3},{i=8393,n="厚甲蝎螯",c=2},{i=8394,n="石化蜥蜴的大脑",c=1}}},
  [2585]={t="决定性的打击",d="你见过它们作战吗，你？我是说那些蝎子。你有没有见过他们优美、敏捷的动作？有没有看到过它们那迅捷的攻击？；如果我们能将它们的敏捷性分离出来并制成药剂，那我们就发达了……我的意思是……那将是我们对科学的一大贡献！；帮帮我吧，你，我可以送给你一份实验样品。你我需要三个厚甲蝎螯，两个秃鹫的砂囊和一片诅咒之地的野猪肺。",o="收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。",r={{i=8393,n="厚甲蝎螯",c=3},{i=8396,n="秃鹫的砂囊",c=2},{i=8392,n="诅咒之地的野猪肺",c=1}}},
  [2601]={t="石化蜥蜴的大脑",d="这块荒地上到处都是红石蜥蜴，你。这些蜥蜴的族群比这里的其它任何生物都要兴旺。；我曾经在远处观察过它们的捕猎和其它日常活动——这些野兽表现出了某种思考过程，它们的智商甚至比某些人型生物还要高。；我得研究一下他们的脑子！；给我找十颗蜥蜴的大脑来，你。还有，你必须再找两个秃鹫的砂囊，否则我就无法完成药物的配制。",o="收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。",r={{i=8394,n="石化蜥蜴的大脑",c=10},{i=8396,n="秃鹫的砂囊",c=2}}},
  [2603]={t="秃鹫的活力",d="死亡在这片被诅咒的土地上长出了翅膀，$c。我曾亲眼目睹那些秃鹫将探险者的尸体狼吞虎咽地吃掉——有时它们甚至会吃下携带着致命疾病的尸体。它们身体内部的系统竟然能够抵御席卷了这片土地的瘟疫，这的确令我感到十分惊奇。；请帮助我进行研究，你！我需要秃鹫的砂囊，还需要两块弯牙土狼的颚骨作为原料。；我会和你五五分成的。",o="收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。",r={{i=8396,n="秃鹫的砂囊",c=10},{i=8391,n="弯牙土狼的颚骨",c=2}}},
  [2605]={t="口渴的地精",d="住在大沙漠里真是活受罪！我都要被烤干了。；不过我有个主意。听说有一种被称作露水收集者的生物就在西南方活动……它们有一种特殊腺体，可以用来储藏水分。；如果能得到这种腺体，我就可以畅饮一顿，至少滋润滋润我的嘴唇！你能帮帮我吗，你？；找到有一大片仙人掌的地方，你，露水收集者常在那里出没。",o="找到1个饱满的露水腺，把它交给加基森的马林·诺格弗格。",r={{i=8428,n="饱满的露水腺",c=1}}},
  [2606]={t="好味道",d="呸！这个东西真难吃！这个主意也不过如此嘛……；等等，你说什么？哦，我知道，我知道，你认为我不该就这么放弃它。那么，好吧。；对了，我有个主意！一个妙极了的主意！去和我朋友斯普琳科谈谈吧——她是个出色的厨师。告诉她我们想做什么，还有我们想要知道加点什么才能把让人这东西咽下去。；我的意思是，如果它这么难吃的话，总得让它有些让人兴奋的东西才行……可是我现在就是感觉不到。",o="马林·诺格弗格让你与加基森的斯普琳科谈一谈。",p=2605,r={{i=8603,n="灌木露水",c=1}}},
  [2608]={t="赞吉尔之触",d="哦，天哪，你看上去就象死人一样。纠正一下——我见过死人，你看上去比死人还要糟，简直像是死了又死！；哈哈！诺拉姆，你听见了吧？把它记下来！；*咳嗽*嗯，好吧。为了帮助你，我得先给你抽点血。别担心，只有前几次抽血会有点疼……大概前五十次吧……准备好了之后就躺下（使用/lay指令），你。",o="用/lay指令躺下，接受道克·米希匹克斯的治疗。如果他找不到病因，就找不到治疗的方法。",p=2607},
  [2641]={t="斯普琳科的秘密佐料",d="在我还小的时侯，我姐姐包揽了所有烧饭的活，那简直是糟透了！她做的有些东西简直让我无法忍受——直到我发现了一种被我称作“秘密佐料”的东西，只要加上一点……啧啧！味道好极了！；你问那是什么东西？嗯，是一种被称作紫色水生菇的蘑菇。如果你要我把这个尝起来像拖把一样的东西变成可以下咽的食品，那么我建议你去一趟辛特兰，到那里去找一个小湖泊。；哦，记住了，紫色水生菇只有在水下才能找到。",o="加基森的斯普琳科要你去给她找到一颗紫色水生菇。",p=2606,r={{i=8526,n="紫色水生菇",c=1}}},
  [2661]={t="给马林的粉末",d="这是紫色粉末，你，把它交给马林，告诉他，他欠我一个人情！",o="斯普琳科让你把紫色粉末交给加基森的马林·诺格弗格。",p=2641,r={{i=8528,n="紫色粉末",c=1}}},
  [2681]={t="禁锢我们的石头",d="要击败拉瑟莱克和他的手下，只靠你一个是不够的。；召集一队勇士，让我的同伴摆脱永恒的折磨吧！你要打碎十八块石头。；努力战斗吧，你。",o="解救九个拉瑟莱克的仆从、三个瑟温妮的仆从、三个奥利斯塔的仆从和三个戈洛尔的仆从。完成任务后，回到部落英雄的灵魂这里。",p=2801},
  [2701]={t="Heroes of Old",o="Open the chest and claim your reward.",p=2702},
  [2741]={t="超级测蛋器",r={{i=8564,n="角鹰兽的蛋",c=1}}},
  [2742]={t="林吉被困住了！",d="嘿，那边的$r！；请你帮林吉逃出去，我知道像你这样的$r不喜欢林吉，不过林吉求你了！我要逃出去！；如果$r帮林吉逃出这里，$r就可以得到一些好东西……；林吉在望海崖藏了个大秘密。",o="护送林吉逃出奎尔丹尼小屋，然后在望海崖找到他藏起来的东西。"},
  [2744]={t="恶魔猎手",d="那三个魔王受到拉瑟莱克的保护。；为了让他们忠诚地为他效力，拉瑟莱克使他们在诅咒之地可以使用几乎无限的力量。他们佩戴的护符和他们的命运联系在一起，并使他们变得不老不死。只要他们待在诅咒之地，你就没法杀了他们，他们的生命力可以维持到世界末日。；我认识一个也许可以帮助你的朋友，你。到艾萨拉地区的小岛上去找恶魔猎手洛拉姆斯·萨里比迪斯谈谈吧。",o="与艾萨拉的洛拉姆斯·萨里比迪斯谈一谈。",p=2743},
  [2746]={t="必备物品",d="提亚斯要加快实施计划了吗？好吧，我们可以做到，不过我还没准备好。你知道，我要做的是最困难的部分，而你是负责动手的人，明白吗？很好。；我要让你先帮我准备些东西，这样我就可以对间谍机器人进行伪装，让它安全地骗过那些守卫。；给我带回一些丝绸和几只苹果来。丝绸你自己去找，不过城外那个克拉拉的小农场上有非常合适的苹果。",o="将3块丝绸和2只克拉拉的新鲜苹果交给暴风城的泰里恩。",p=2745,r={{i=4306,n="丝绸",c=3},{i=8683,n="克拉拉的新鲜苹果",c=2}}},
  [2751]={t="野人装甲",d="这只铁锤在沃姆什系列中传了二十代，你。我们熔铸的铁有成千上万吨。不幸的是，这门技艺到了奥罗克手中却传不下去了，这是沃姆什系列的耻辱——我既没有亲属，又无法生育后代。；决不能让沃姆什的祖传技艺和我一起死去！必须有人继承它，不管他是不是沃姆什系列的后裔！；向奥罗克证明你的能力吧，你。给奥罗克找来这些东西：两副青铜花纹护腕，两把青铜巨剑和两只锋利的爪子。把这些找来，我们再继续。",o="将2副青铜花纹护腕、2把青铜巨剑和2只锋利的爪子交给奥格瑞玛的奥罗克·沃姆什。",r={{i=2868,n="青铜花纹护腕",c=2},{i=7957,n="青铜巨剑",c=2},{i=5635,n="锋利的爪子",c=2}}},
  [2752]={t="铁肩铠",d="奥罗克可以看出你眼中的渴望，你。你像海绵一样渴望吸收沃姆什的智慧。；我会教你三样东西！；到铁砧那边去，感受熔炉的热量，为奥罗克铸造四把青铜战斧和四把青铜战锤，然后你才能学习制造铁肩铠。",o="将4把青铜战斧和4把青铜战锤交给奥格瑞玛的奥罗克·沃姆什。",p=2751,r={{i=7958,n="青铜战斧",c=4},{i=7956,n="青铜战锤",c=4}}},
  [2753]={t="踩在脚下",d="奥罗克还剩两课要教给你，你。我知道你的肌肉很疼，不过为了沃姆什系列，你还要继续！；把四顶绿铁头盔、四个绿铁护腕和四个绿铁护腿拿来给奥罗克——你可以学到知识，你的敌人也会更加痛苦！",o="将4顶绿铁头盔、4副绿铁护腕和4副绿铁护腿交给奥格瑞玛的奥罗克·沃姆什。",p=2752,r={{i=3836,n="绿铁头盔",c=4},{i=3835,n="绿铁护腕",c=4},{i=3842,n="绿铁护腿",c=2}}},
  [2754]={t="疯狂之角",d="这是奥罗克教你的最后一课，你。回到神圣的铁砧和锻炉旁去！将两只结实的铁锤、两双镀银青铜战靴和两副镀银青铜手套交给奥罗克。；你会看到敌人眼中的恐惧！",o="将2只结实的铁锤、2双镀银青铜战靴和2副镀银青铜手套交给奥格瑞玛的奥罗克·沃姆什。",p=2753,r={{i=3851,n="结实的铁锤",c=2},{i=3482,n="镀银青铜战靴",c=2},{i=3483,n="镀银青铜护手",c=2}}},
  [2756]={t="古老的技艺",d="很久以前，阿图尔克可以碾碎敌人的徽记，将它们磨成粉做灯丝……很久以前，$r。现在酋长号召各部族和平相处。那些往日的敌人，现在我们只能用厌烦的眼光看着他们！；我知道这很难以接受，不过这就是萨尔的意愿。；实在是让我感到悲哀！你是来学习的，那你就学吧！给我拿四套钢质胸甲和四顶钢质头盔来，你可以在锻造它们的时候尝到战争的滋味！",o="将4套钢质胸甲和4顶钢质头盔交给奥格瑞玛的铁砧阿图尔克。",r={{i=7963,n="钢质胸甲",c=4},{i=7922,n="钢质头盔",c=4}}},
  [2758]={t="锻造的本源",d="我像你这么大的时候，在一个名叫加尔文的矮人门下学习了铸造护甲的技术。在他离开这里转至藏宝海湾之前，曾让我向他许诺，要帮助训练所有决心在锻造这门技艺上学有所成的人——于是这么多年来，我一直在这么做。；现在是时候让你学点新东西了。给我打造六套金鳞护腕，你就会知道锻造的本源是什么了，你。",o="将6副金鳞护腕交给暴风城的巨锤汉克。",r={{i=6040,n="金鳞护腕",c=6}}},
  [2760]={t="秘银会",d="我们招募的人几乎没有能平安抵达藏宝海湾的，你。即使是意志最坚定的铁匠也难以抵挡这枚徽章的光芒，他们难免会产生私吞的贪念。他们都是傻瓜，因为与你即将得到的巨大财富相比，这枚徽章只是沧海一粟而已！；去找到加尔文，把徽章交给他。他住在这里的北面，就在祖尔格拉布和莫什奥格食人魔山之间的地方。",o="和荆棘谷的加尔文谈一谈。",r={{i=8686,n="秘银坠饰",c=1}}},
  [2766]={t="寻找OOX-22/FE！",d="你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。；“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于深痕谷中的一个山洞里！”",o="把定位器带到深痕谷附近山洞中的奥格索普的导航机器人旁边。",r={{i=8705,n="OOX-22/FE定位器",c=1}}},
  [2767]={t="拯救OOX-22/FE！",d="那个侏儒的声音再次从那个机器人中传了出来：；“我需要你帮忙把OOX-22/FE移动到一个安全的开阔地，这样它才可以启动起飞程序。它自带隐形系统，但是我需要一点时间来远程启动这个系统。请你把这个机器人从现在的位置护送到被遗忘的海岸去！那里是个非常理想的起飞点，有足够的空间作为机器人起飞的跑道！”；“将它护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯——完毕！”",o="安全护送OOX-22/FE到达目的地，然后向藏宝海湾的奥格索普·奥布诺提斯报告。",p=2766,w={{i=9647,n="实验失败的飞行装置",c=1},{i=9648,n="锁链长巾",c=1}}},
  [2768]={t="探水棒",d="布莱中士偷了我的东西！他说只是借一下，但那混蛋却偷了我宝贵的探水棒！没有这根棒子，我就不知道该在哪里打井找水！；去找到布莱，把我的探水棒拿回来！我听说他带着一帮恶名远扬的冒险者去了西边的祖尔法拉克古城寻宝，你肯定可以在那里找到他。；但愿那里的巨魔已经把他干掉了，因为如果你必须打败他才能拿回探水棒的话，那必将是一场恶仗。",o="把探水棒交给加基森的首席工程师沙克斯·比格维兹。",r={{i=8548,n="探水棒",c=1}},w={{i=9533,n="石工兄弟会之戒",c=1},{i=9534,n="工程学协会头盔",c=1}}},
  [2770]={t="加兹瑞拉",d="在塔纳利斯沙漠的巨魔古城祖尔法拉克深处，有一个神圣的池塘。巨魔可以从那个池塘里召唤一头巨大的野兽——加兹瑞拉！它凶猛异常，甚至连它的鳞片都会因为巨大的能量而发出声响。我要用它的能量来给我的赛车增加动力！；把加兹瑞拉的鳞片给我弄来！；不过，召唤加兹瑞拉的方法是巨魔的秘密。如果你想要面对加兹瑞拉的话，首先就要从巨魔那里弄到召唤它的方法。",o="把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。",r={{i=8707,n="加兹瑞拉的鳞片",c=1}}},
  [2782]={t="林吉的秘密",d="这块石板上布满了枯木巨魔的印记。林吉的秘密真是难以猜测……；或许你手头上的东西非常宝贵。当然，这东西也很有可能一文不值。悲伤中的枯木巨魔为了摆脱困境什么事情都干得出来……",o="奥兰·斯内克威瑟是个学者，她对枯木巨魔很有研究，也许她可以帮你看看这块石板。奥兰就住在幽暗城的魔法区里。",p=2742,r={{i=8724,n="林吉的秘密",c=1}}},
  [2784]={t="失落的荣耀",d="请听听我的故事，$r。",o="聆听部落英雄的灵魂讲述他的故事。"},
  [2801]={t="悲伤的故事",d="请你一定要先听听我的故事。",o="聆听部落英雄的灵魂讲述他的故事。"},
  [2821]={t="质量的保证",d="我对于皮革制作的哲学是要做就做最好——没有商量馀地。任何说质量不要紧的人都是想要把丹莫罗的那些水货卖给你！；在寻求高质量材料的过程中，我接触到了厚重的雪人皮。雪人是菲拉斯土生土长的一种生物，大多在深痕谷活动。我需要一些它们的皮，如果你给我十张的话，我可以让你在我的皮货中选一件。如果你觉得听起来还算公平，那我们就成交了吧。",o="给羽月要塞的普拉特·马克格鲁比带去10张厚重的雪人皮。",r={{i=8973,n="厚重的雪人皮",c=10}},w={{i=9630,n="普拉特的手工长靴",c=1},{i=9631,n="普拉特的手工护手",c=1}},f=1},
  [2822]={t="质量的保证",d="我为自己制作的皮革作品感到骄傲，它们也值得我骄傲，质量是永不可能妥协的东西。任何说质量不要紧的人都是在信口乱说！；在寻求高质量材料的过程中，我接触到了厚重的雪人皮。雪人是菲拉斯土生土长的一种生物，大多在深痕谷活动。我需要一些它们的皮，如果你给我十张的话，我可以让你在我的皮货中选一件。如果你觉得听起来还算公平，那我们就成交了吧。",o="给莫沙彻营地的杉多尔·迅蹄带去十张厚重的雪人皮。",r={{i=8973,n="厚重的雪人皮",c=10}},w={{i=9633,n="杉多尔的手工长靴",c=1},{i=9632,n="杉多尔的手工护手",c=1}},f=2},
  [2841]={t="设备之战",d="侏儒的技术——两年前它最普遍的用途是被当作笑话，但是时代确实变了，现在他们建造的新型钻探设备比我们所有伐木机加起来都要精密。我需要它的设计图，你！；不幸的是，这些设计图被锁在麦克尼尔·瑟玛普拉格身边的一只保险箱里了。更糟的是，保险箱的密码只有麦克尼尔·瑟玛普拉格一人知道。；尽你所能得到那个密码，你。把设计图给我带回来！",o="从诺莫瑞根拿到钻探设备蓝图和麦克尼尔的保险箱密码，把它们交给奥格瑞玛的诺格。",r={{i=9153,n="钻探设备蓝图",c=1},{i=9299,n="",c=1}},w={{i=9623,n="公民长袍",c=1},{i=9624,n="旅行皮裤",c=1},{i=9625,n="双链护腿",c=1}},f=2},
  [2845]={t="迷路的沙恩",d="你能带我回到我的朋友罗克比特身边吗？他本来是要照看我的……但我总是不知不觉之间就迷路了。这里有这么多好看的东西，我东看看西看看就不知道该怎么走了。；但是有一样东西可以一直吸引我的注意力。；在这个箱子里有一只对我来说最为珍贵的铃铛，我就喜欢听它的声音。我保证，如果我走失了，只要你摇响铃铛，我就会马上跑回来。",o="从箱子里拿取沙恩的铃铛，然后护送沙恩·飘叶回到罗克比特的营地。",p=2844,r={{i=9189,n="沙恩的铃铛",c=1}},w={{i=9656,n="花岗岩护手",c=1},{i=9657,n="葡萄藤腰带",c=1}},f=1},
  [2846]={t="深渊皇冠",d="很久以前我曾经拥有一件美丽的珍宝，深渊皇冠。它不仅美丽——而且它对于知道怎么使用它的人来说更是一件拥有巨大力量的宝贝。；所以当水占师维蕾萨听说皇冠的事情之后，她就发誓要得到它。维蕾萨派人在我外出的时候到我家来偷走了皇冠，这些卑鄙的小偷！；我要取回我的皇冠！到位于塔纳利斯沙rn漠中的巨魔城市祖尔法拉克去，把皇冠从她手上抢回来。把它还给我，你会得到报酬的。",o="将深渊皇冠交给尘泥沼泽的塔贝萨。",r={{i=9234,n="深渊皇冠",c=1}}},
  [2847]={t="蛮皮护甲",d="$n，你已经是个很熟练的制皮匠了！我知道一些装备的制作方法，你可能会感兴趣……那就是蛮皮护甲！蛮皮中包含了野葡萄的混乱而强大的力量，你可以在这片茂盛的森林中找到这种植物，也可以在森林中的某些动物身上找到。用它制作的装备简直是无以伦比！；我会把制作蛮皮护甲的方法教给你，条件是你要为我做点事情。首先你得给我带十块厚皮来，等你拿来十块厚皮之后我们再详谈。",o="给羽月要塞的普拉特·马克格鲁比带去10块厚皮。",r={{i=4304,n="厚皮",c=10}}},
  [2854]={t="蛮皮护甲",d="$n，你已经是个很熟练的制皮匠了！我知道一些装备的制作方法，你可能会感兴趣……那就是蛮皮护甲！蛮皮中包含了野葡萄的混乱而强大的力量，你可以在这片茂盛的森林中找到这种植物，也可以在森林中的某些动物身上找到。用它制作的装备简直是无以伦比！；我会把制作蛮皮护甲的方法教给你，条件是你要为我做点事情。首先你得给我带十块厚皮来，等你拿来十块厚皮之后我们再详谈。",o="给莫沙彻营地的杉多尔·迅蹄带去10块厚皮。",r={{i=4304,n="厚皮",c=10}}},
  [2862]={t="与豺狼人开战",d="豺狼人……它们现在不再只是一个小麻烦了，它们已经对我们形成了巨大的威胁！这些豺狼人是不是菲拉斯的原住民已经不重要了；如果我们无法有效地对抗它们，那我们早晚都会被赶出这个地区的。；豺狼人最近对营地的攻势愈演愈烈，因此我们需要你的帮助来削弱它们的数量。带给我十份豺狼人的鬃毛，我会为你付出的努力而给予优厚的报酬。；赶快出发吧！",o="将10份木爪豺狼人的鬃毛交给莫沙彻营地的哈杜肯·迅蹄。",r={{i=9237,n="木爪豺狼人的鬃毛",c=10}}},
  [2863]={t="突然袭击",d="我们计划在很短的时间里拿下豺狼人的领导者——按他们自己的说法是突击队员。如果我们顺利地执行了这个计划……不仅他们的内部会出现混乱，而且这也会向他们愚蠢的脑袋传达一个信息，那就是我们有能力而且必将消灭他们！；我想让你成为传达这个信息的使者，你必须在一小时内消灭五个突击队员，否则我们还会处于这种僵局中。",o="在1个小时内杀死5个木爪突击队员，并向哈杜肯·迅蹄汇报。",p=2862},
  [2869]={t="憎世纳迦之战",d="我们认为，无论纳迦想要干什么，他们最终的目的无非是完全占据这座岛屿，由此我们制定了相应的行动计划。我们要尽早采取攻击行动来消除这种威胁，否则就可能全盘皆输。；给我带来十块完整的憎世纳迦的鳞片——你应该知道如何获得这东西。这样一来，纳迦在萨尔多岛上的力量就被大大削弱了，这对我们是非常有利的。",o="收集10块憎世纳迦的鳞片，把它们交给羽月要塞的拉托尼库斯·月矛。",p=3130,r={{i=9247,n="憎世纳迦的鳞片",c=10}}},
  [2870]={t="击败沙尔扎鲁",d="$n，新的侦查报告让我们对纳迦部队的组成有了一个更清晰的概念。纳迦的皇室成员在他们的部队中具有最高的权威性。；皇室成员中的沙尔扎鲁是个极端残酷的纳迦，侦查报告表明最近他在南部的遗迹中发现了一块奇怪的古代遗物，那个地方就在恐怖之岛那里。；你的任务就是结果他，然后把那块遗物给我带回来进行研究。",o="消灭沙尔扎鲁，然后把神秘遗物交给羽月要塞的拉托尼库斯·月矛。",p=2869,r={{i=9248,n="神秘遗物",c=1}}},
  [2871]={t="递送遗物",d="如果你能帮我将这个东西送给我的妻子维斯提亚，那我会非常感激的。她不仅是我们这里的女祭司，也会是你所见过的最博学的学者之一。我即使抓破头皮也搞不清楚这个东西到底是什么，可我的妻子不同，如果世界上有人能知道这东西是什么，那无疑就是她了……我们也迫切地需要知道真相！；拜托了，$n。",o="将神秘遗物交给羽月要塞的维斯提亚·月矛。",p=2870,r={{i=9248,n="神秘遗物",c=1}},w={{i=9663,n="黎明骑兵胸甲",c=1},{i=9664,n="卫戍头盔",c=1}},f=1},
  [2873]={t="斯杜雷的货物",d="我欠藏宝海湾的“海狼”马克基雷一些朗姆酒，那是打赌输的，但我现在一瓶朗姆酒都没有了！科尔戈船长偷了我最后一船货，他把它们藏在南边的那个戒备森严的海盗镇里。；如果你能找到我的那批朗姆酒并把它们给我拿回来的话，那我就可以向马克基雷证明，藏宝海湾的那些酒跟我的朗姆酒比起来只能被称作垃圾！",o="将斯杜雷的货物交给热砂港的斯杜雷。",p=2872,r={{i=9244,n="斯杜雷的货物",c=1}}},
  [2874]={t="给马克基雷的货物",d="再次感谢你的帮助，你。这里有一瓶热砂港朗姆酒。把它交给马克基雷，这样他就可以抛弃藏宝海湾烈酒，改喝热砂港朗姆酒了！",o="将斯杜雷的瓶子交给藏宝海湾的“海狼”马克基雷。",p=2873,r={{i=9245,n="斯杜雷的瓶子",c=1}},w={{i=9636,n="剑客腰带",c=1},{i=9637,n="断骨长靴",c=1}}},
  [2879]={t="艾奎尼克斯法杖",d="看来这根法杖可能就是艾奎尼克斯法杖了。它事实上是把钥匙，你可以用它打开位于北方废墟中的艾奎尼克斯石碑。；找到仍在那片废墟中燃烧的四团烈火：萨姆哈之焰、拜尔坦之焰、伊姆贝尔之焰和莱哈萨之焰。从这些火焰那里采集它们的精华。然后在艾奎尼克斯石碑旁使用这些精华，把它们的能量注入法杖。如果这真的是艾奎尼克斯法杖的话，你就可以打开石碑，并得到存放在里面的古物。",o="给特洛亚斯的法杖注入能量，并找到艾奎尼克斯石碑。",p=2943,r={{i=9306,n="艾奎尼克斯法杖",c=1}}},
  [2880]={t="巨魔部族项链",d="直接说吧，$c——我们不属于联盟！蛮锤部族是独立的，我们依靠自己所做的事情来证明自己的价值，不像那些只会说废话的家伙一样，用闲聊来掩饰自己什么都不想做的态度！；如果你要和我们作朋友，那么首先向我们证明你的价值！那些遍布辛特兰的巨魔有时会带着他们部族的项链。给我带五条项链过来作为友好的证明吧！",o="给鹰巢山的弗拉加尔带去5条巨魔部族项链。",r={{i=9259,n="巨魔部族项链",c=5}}},
  [2903]={t="作战计划",d="既然我们已经发现了豺狼人的作战计划，接下来要做的就是把计划交给莫沙彻营地的哈杜肯·迅蹄。他或者那儿的其它什么人也许可以进一步弄清楚豺狼人到底想要做什么。",o="把木爪豺狼人的作战计划交给莫沙彻营地的哈杜肯·迅蹄。",p=2902,r={{i=9266,n="木爪豺狼人的作战计划",c=1}},w={{i=9661,n="大地屏障",c=1},{i=9662,n="跨山长靴",c=1}},f=2},
  [2904]={t="一团混乱",d="<克努比呻吟着>发……发生什么事了？；我只记得自己被一队黑铁矮人抓住了，他们暴打了我一顿，把我跟这些丑陋的穴居人扔在一块儿。；快救我出去，你！；我有个计划：把我带到出口，如果我们能活着走出去的话，你就到藏宝海湾去，告诉斯库提我去了棘齿城，然后警告廷克维斯，黑铁矮人准备制造超强的钻探设备。；让我们开始吧！",o="将克努比护送到出口，然后向藏宝海湾的斯库提汇报。",w={{i=9535,n="焊接护腕",c=1},{i=9536,n="精灵之翼",c=1}}},
  [2926]={t="诺恩",d="事故后，诺恩想的说的都离不开两个主题：如何将穴居人赶出诺莫瑞根，以及如何为席卷诺莫瑞根的瘟疫找到治疗的方法。；幸运的是，拉兹和我已经快要研究出一种治疗方法了——要不然就是一种很强劲的朗姆酒的配方。我们要试过才知道！当然，为了检验我们的理论是否成立，我们需要一些东西，准确地说，是诺莫瑞根城里那些穴居人身上的辐射尘。用这个小瓶子装一些泛着绿光的辐射尘，然后把它带回来！",o="用空铅瓶对着辐射入侵者或者辐射抢劫者，从它们身上收集放射尘。瓶子装满之后，把它交给卡拉诺斯的奥齐·电环。",p=2927,r={{i=9284,n="装满的铅瓶",c=1}}},
  [2928]={t="陀螺式挖掘机",d="太糟糕了，你。我们没有足够的零件让我们的陀螺式挖掘机部队进入丹莫罗。；我们需要的是零件，你，更多的零件。说到寻找零件，难道还有比诺莫瑞根更好的地方吗？我听说那里的机器人像牧区的牛似的到处游荡。；我要你做的就是到诺莫瑞根去，把这些机器人拆开，拿出它们的内部装置。给我弄两打来就够了。",o="收集24副机械内胆，把它们交给暴风城的舒尼。",r={{i=9309,n="机械内胆",c=24}},w={{i=9608,n="舒尼的扳手",c=1},{i=9609,n="欺诈手套",c=1}},f=1},
  [2929]={t="大叛徒",d="我以前曾经非常信任麦克尼尔，我从未想过他会背叛我和所有侏儒同胞。他为什么要背叛我们？为了权力？为了金钱？这些东西只要加以时日他都可以拥有。现在我们背井离乡，那个疯子掌握了政权，成了个什么都没有的国王……；我们要夺回诺莫瑞根，你。在夺回自己的城市之前，我们决不停止努力。如果你想加入我们，就先去完成一个简单的任务：杀了那个叛徒，麦克尼尔·瑟玛普拉格。",o="到诺莫瑞根去杀掉麦克尼尔·瑟玛普拉格。完成任务之后向大工匠梅卡托克报告。",w={{i=9623,n="公民长袍",c=1},{i=9624,n="旅行皮裤",c=1},{i=9625,n="双链护腿",c=1}},f=1},
  [2930]={t="抢救数据",d="在逃离诺莫瑞根的时候，我们留下了太多的数据！非常重要的数据！；我需要一张彩色穿孔卡片，你可以从诺莫瑞根城里的矩阵式打孔计算机3005-D型里找到这种卡片。不过糟糕的是，要得到它的话，你就必须先接近低级安全终端，也就是A型，B型和C型计算机，然后用不同的穿孔卡片开启它们，从白色的卡片开始……而且我们把所有的穿孔卡片都留在城里了。；这真是一场灾难！你能帮忙吗？",o="将彩色穿孔卡片交给铁炉堡的大机械师卡斯派普。",r={{i=9316,n="彩色穿孔卡片",c=1}},f=1},
  [2933]={t="毒液瓶",d="这些瓶子里装有绿色的毒液。；由村庄中这种瓶子的数量来看，枯木巨魔一定很重视这些东西。或许塔伦米尔的药剂师会对这些毒液的样本感兴趣。",o="将毒药瓶交给塔伦米尔的某个药剂师。",r={{i=9321,n="毒液瓶",c=1}}},
  [2934]={t="完好无损的毒囊",d="我必须要有一个你带来的那种毒液的新鲜样本才能进行研究。生产毒液的蜘蛛一定生活在辛特兰一带——猎捕这些蜘蛛，直到你找到一个完好无损的毒囊，把它给我带来。巨魔们的沙德拉洛城附近有许多蜘蛛，到那里去找找吧。；别耽搁了，毒囊一定要非常新鲜才行。",o="将完好无损的毒囊交给塔伦米尔的药剂师林度恩。",p=2933,r={{i=9322,n="完好无损的毒囊",c=1}}},
  [2936]={t="蜘蛛之神",d="枯木巨魔崇拜蜘蛛之神，他们从她那里收集极具威力的毒液。如果你想要毒液，就必须召唤他们的蜘蛛之神！；要召唤她的话，你就必须知道她真正的名字，刻有这个名字的石板被埋藏在一座墓穴中，那墓穴就在塔纳利斯沙漠中的巨魔城市祖尔法拉克，由殉教者塞卡守卫着墓穴的入口。；击败塞卡，阅读那块石板，找到蜘蛛之神的名字。知道了她的名字之后就回到我这里来。",o="阅读塞卡石板，了解枯木巨魔的蜘蛛之神的名字，然后回到加德林大师那里。",p=2935},
  [2937]={t="召唤沙德拉",d="拿着这张羊皮纸，在辛特兰的沙德拉洛祭坛上念诵羊皮纸上的咒文。这样就可以召唤蜘蛛之神沙德拉。",o="在沙德拉洛祭坛上击败沙德拉，把它的毒液交给塔伦米尔的药剂师林度恩。",p=2936,r={{i=9324,n="沙德拉的毒液",c=1}}},
  [2938]={t="送往幽暗城的毒药",d="你在枯木巨魔的蜘蛛之神身上采集的毒液真是一个重大的发现！只消一小滴，我就可以杀死足足二十只兔子。当然，有些兔子很幼小，小得足以放在手掌上，它们对毒药的抵抗力非常低，但你也不能否认这种毒药极具威力！；我想要给我的上级——幽暗城炼金房的大药剂师法拉尼尔——送去一些样本，我敢说他也会对此很感兴趣的。",o="将法拉尼尔的包裹交给幽暗城的大药剂师法拉尼尔。",p=2937,r={{i=9436,n="法拉尼尔的包裹",c=1}},w={{i=9649,n="皇家徽记外衣",c=1},{i=9650,n="荣誉卫兵胸甲",c=1},{i=10686,n="战争之盾",c=1}},f=2},
  [2941]={t="海龟照片",d="我一生中研究了许多课题，最近我迷上了遍布辛特兰海滩地区的钳嘴龟。我特别想看到一只名叫加莫里塔的大型钳嘴龟，本来呢，我想要自己去一趟，但繁重的研究工作让我不得不留在这里。如果能搞到一张它的画像就好了。；把这封信交给塔纳利斯的克格尔·曲藤。她为我发明了一种可以快速获取图像的装置，我想她把那个东西叫做“快照”……",o="把信交给塔纳利斯的克格尔·曲藤。",p=2940,r={{i=9329,n="简短的便笺",c=1}}},
  [2942]={t="晨光石",d="石碑中的东西被你拿出来的一瞬间，你突然感到艾奎尼克斯法杖的力量开始衰竭。",o="将闪光的石头和艾奎尼克斯法杖交给羽月要塞的特洛亚斯·月风。",p=2879,r={{i=9307,n="闪光的石头",c=1},{i=9306,n="艾奎尼克斯法杖",c=1}},w={{i=9654,n="碑石长条",c=1},{i=9655,n="播种指环",c=1}},f=1},
  [2943]={t="向特洛亚斯回复",d="给你，你。请小心保管我的书。；现在快点出发吧，特洛亚斯正在翘首企盼你的回归呢！",o="把书交给羽月要塞的特洛亚斯·月风。",p=2944,r={{i=9331,n="菲拉斯的历史",c=1}}},
  [2944]={t="超级摄影器FX",d="先来看看我的发明吧，你。你所要做的只是将它对准任何一个你想要拍摄的物品，然后按下这个按钮。；你说的辛特兰的生物是什么？加莫里塔？好吧，祝你好运，希望你能找到它。我坚信达蕾恩会对你给她的照片很满意的。；不说那么多了，这是给你的超级摄影器。玩得开心点！",o="用超级摄影器FX给加莫里塔拍张照片，然后把它交给鲁瑟兰村的达蕾恩·轻风。",p=2941,r={{i=9330,n="加莫里塔的照片",c=1},{i=9328,n="超级摄影器FX",c=1}}},
  [2945]={t="脏兮兮的戒指",d="你在一个黑铁矮人的尸体上发现了一枚戒指。但要辨认戒指的细节却很困难，泥土和坚硬的污垢将它整个包裹了起来，你根本没法戴上它。你觉得它是用某种珍贵的金属制成的，似乎还镶着宝石。；如果你想好好看看这枚戒指的话，就得找些东西把戒指表面的污垢清理掉。",o="想方法把脏兮兮的戒指弄干净。",r={{i=9326,n="脏兮兮的戒指",c=1}}},
  [2947]={t="戒指归来",d="打开由超级清洁器5200型制作的盒子之后，你看到了一枚闪闪发光的戒指！你戴上了戒指，立刻感觉身体中涌动着神奇的力量。；戒指的内侧有一个很小的铁炉堡徽记，旁边刻着三个字母：“TdK”。；这可能是它以前的主人或是制作者的姓名缩写。是将这枚戒指留着自己用，还是把它物归原主，这要由你自己来决定……",o="你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。",p=2945,r={{i=9362,n="闪亮的金戒指",c=1}}},
  [2948]={t="侏儒的手艺",d="听着，$n，这戒指当然是你的……但是我可以给你做一枚更好的！就像我说的一样，那种设计实在太简单了。现在我的技术更加娴熟了，只要你付我三十个银币的费用，我就可以帮你制作一枚新戒指！好吧，事实上还要再加一点点……；我现在手头很紧，我的所有存货都用完了。如果你给我一块银锭和一块绿玛瑙，我就可以让戒指看起来更加闪亮华贵！；相信我！",o="将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给铁炉堡的塔瓦斯德·基瑟尔。",p=2947,r={{i=9362,n="闪亮的金戒指",c=1},{i=2842,n="银锭",c=1},{i=1206,n="绿玛瑙",c=1}},f=1},
  [2949]={t="戒指归来",d="打开由超级清洁器5200型制作的盒子之后，你看到了一枚闪闪发光的戒指！你戴上了戒指，立刻感觉身体中涌动着神奇的力量。；戒指的内侧有一个很小的奥格瑞玛徽记。徽记旁刻着一行字母，但即使是经过清理之后也只能看清三个：“NOG……”；这可能是它以前的主人或是制作者的姓名缩写。是将这枚戒指留着自己用，还是把它物归原主，这要由你自己来决定……",o="你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。",p=2945,r={{i=9362,n="闪亮的金戒指",c=1}}},
  [2950]={t="诺格的手艺",d="不，不，不——我当然不是突然就说这枚戒指是我的。嗯，我通常不这样做，但你提供的关于黑铁矮人的情报很有用，所以我会破例为你改造你的戒指，我的手艺绝对比制作这个小东西的家伙要高超得多。嗯，八成是个侏儒做的……；如果你给我拿来一块银锭、一块绿玛瑙和三十枚银币作为加工费的话，我就可以在戒指中加入白银和玛瑙的精华来加强其魔力。怎么样，感兴趣吗？",o="将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给奥格瑞玛的诺格。",p=2949,r={{i=9362,n="闪亮的金戒指",c=1},{i=2842,n="银锭",c=1},{i=1206,n="绿玛瑙",c=1}},f=2},
  [2951]={t="超级清洁器5200型！",d="这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：；：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”",o="将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。",r={{i=9308,n="脏兮兮的东西",c=1}}},
  [2954]={t="石头卫士",d="“向你致意——我是把守入口的守护者。除非你拥有完整的奥丹姆圆盘，否则我不会让你进入奥丹姆城。”；这个石头卫士一定就是派你来这里的人希望能在这里找到的东西。看来你必须在继续探索之前找出石头卫士背后隐藏的故事。",o="询问诺甘农的石头卫士，搞清楚它要让你干什么，然后再次点击它脚下的奥丹姆石座。"},
  [2967]={t="返回雷霆崖",d="你打开了底座，白金圆盘又一次突然出现在你的背包里。；你从石头守卫那里获取了许多信息，而且白金原盘又回到了你的手中，现在你应该回雷霆崖向纳拉·蛮鬃汇报这个大发现了。",o="与雷霆崖的纳拉·蛮鬃谈一谈。",p=2954,r={{i=6064,n="迷你白金圆盘",c=1}}},
  [2970]={t="菲拉斯的正义",d="辛达尔已经跟你说过了，我们准备去和恐怖图腾部族作战。干掉几个牛头人对我们两个来说不是什么问题，但如果你愿意帮忙的话，我们还是很欢迎的。；看到下面那个营地了吗？东边有更多这样的营地。运用你的战术，尽可能让那些牛头人多吃些苦头。当他们被你和辛达尔打得落花流水之后，我们再回到这里来碰头。",o="杀掉12个恐怖图腾博学者、10个恐怖图腾袭击者和6个恐怖图腾萨满祭司，然后向菲拉斯的耶尔卡·月纹汇报。",p=2969},
  [2972]={t="菲拉斯的正义",d="在这片蛮荒的土地上，辛达尔和我有无数的方法来报答你，但我们想让你有更多的成就感。把我的戒指拿去吧，如果你哪一天到了泰达希尔，就去一趟达纳苏斯城里的月神殿。你可以在那里找到高阶祭司泰兰德·语风。她看到这枚戒指就会知道我们在这里一切安好，并相信你所说的一切。；你，我们都很感谢你。",o="将耶尔卡的徽记之戒交给达纳苏斯的高阶女祭司泰兰德·语风。",p=2970,r={{i=9368,n="耶尔卡的徽记之戒",c=1}},w={{i=10705,n="火柳护腕",c=1},{i=10706,n="夜鳞束带",c=1}},f=1},
  [2973]={t="新斗篷的光辉",d="你好，$c。我和我的伙伴们正准备去菲拉斯执行任务。；我的妻子科琳很喜欢新衣服，所以我想为她做一件用小精龙的翅膀装饰的新披风。你能帮帮我吗？长着美丽翅膀的小精龙在莫沙彻营地的西边。",o="给莫沙彻营地的克鲁伊格·碎颅带去10个闪光的小精灵翅膀。",r={{i=9369,n="闪光的小精灵翅膀",c=10}}},
  [2974]={t="可怕的发现",d="什么？！你在这一地区碰到牛头人了？你开玩笑吧！他们长什么样？！；恐怖图腾氏族！你看到他们了？贝尔戈洛姆对他们这种生物很有兴趣……甚至出重金悬赏他们。；你必须得回去，$c。回去给我带些他们的角回来……如果可以的话，尽可能多弄一些。你可别低估了恐怖图腾氏族，回去杀了他们，让菲拉斯的河流被他们的鲜血染红。",o="收集20支恐怖图腾之角，把它们交给莫沙彻营地的克鲁伊格·碎颅。",p=2973,r={{i=9460,n="恐怖图腾之角",c=20}}},
  [2975]={t="菲拉斯的食人魔",d="戈杜尼食人魔在这一地区的影响已经不容忽视了。你，你可以清楚地看到这一点，他们的存在污染了这片土地。在他们进一步扩张之前，我们一定要把他们赶回去。；沿着河向北走，你会找到他们的前哨营地。去杀掉他们，你。我们必须告诉这些食人魔：他们在这里不受欢迎。",o="莫沙彻营地的洛卡·奥赫要你杀掉10个戈杜尼食人魔、10个戈杜尼食人魔法师和5个戈杜尼蛮兵。"},
  [2976]={t="可怕的发现",d="什么？！；啊，我确实提到过奖赏，对吗？好吧，我知道了；你完成了任务，我觉得你应该得到最高的奖赏。把这些角拿去，我会帮你把它们放到箱子里。到荣誉谷去找贝尔戈洛姆·石槌，向他汇报你所见的一切，他会表彰你的。；祝你一路平安，$c，再次感谢你。",o="将一箱恐怖图腾之角交给奥格瑞玛的贝尔戈洛姆·石槌。",p=2974,r={{i=9462,n="一箱恐怖图腾之角",c=1}},w={{i=11858,n="征战斗篷",c=1},{i=11859,n="碧月宝珠",c=1}},f=2},
  [2977]={t="返回铁炉堡",d="你打开了底座，白金圆盘又一次突然出现在你的背包里。；你从石头守卫那里获取了许多信息，而且白金原盘又回到了你的手中，现在你应该回铁炉堡向探险者协会汇报这个大发现了。",o="与铁炉堡的史学家卡尼克谈一谈。",p=2954,r={{i=6064,n="迷你白金圆盘",c=1}}},
  [2978]={t="戈杜尼卷轴",d="你捡起了这个沾满泥土的卷轴，发现上面写着某种集会或仪式的内容。洛卡·奥赫应该会对这个卷轴以及它对戈杜尼食人魔的意义感兴趣。",o="将戈杜尼卷轴交给莫沙彻营地的洛克·奥汉。",r={{i=9370,n="戈杜尼卷轴",c=1}}},
  [2979]={t="黑暗仪式",d="这些好像是某种黑暗仪式的计划，你。根据我所了解的情况，这种仪式是由戈杜尼食人魔中的大法师进行的。；从某个戈杜尼大法师身上给我弄一颗宝珠来。；法师的宝珠蕴含了巨大的力量，它可以帮我们搞清楚更多关于这种仪式的细节。",o="莫沙彻营地的洛卡·奥赫希望你找到一颗戈杜尼之宝珠。",p=2978,r={{i=9371,n="戈杜尼宝珠",c=1}}},
  [2987]={t="戈杜尼钴矿石",d="我刚刚到达菲拉斯时，曾听说这里的戈杜尼食人魔有一些有趣的矿石。天知道食人魔用矿石来干什么，但他们确实在很小心地保护那种东西！他们有意隐藏这些矿石，以免我们接触到它。；如果你愿意的话，我会把我的铲子给你。到北面的戈杜尼前哨站去，给我挖些戈杜尼钴矿回来。注意找那些泛着蓝光的矿石，然后就挖！",o="莫沙彻营地的奥尔文·吉兹米克需要12块戈杜尼钴矿石的样本。",r={{i=9463,n="戈杜尼钴矿石",c=12},{i=9466,n="奥尔文的铲子",c=1}},w={{i=9658,n="玛哈林之靴",c=1},{i=9660,n="星眼披风",c=1}},f=2},
  [2988]={t="枯木巨魔的牢笼",d="我们最强大的狮鹫的儿子失踪了！几天前，沙普比克和它的父母外出打猎时失踪了，我们认为是巨魔抓走了它。；你必须帮帮我们！到枯木巨魔的两个村子里去搜一搜那里的笼子，看看沙普比克是不是被关在里面。",o="检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。"},
  [2989]={t="祖尔祭坛",d="沙普比克没有和枯木巨魔在一起，那么或许是邪枝巨魔带走了他……到邪枝巨魔控制地区的西部边缘去，在那里的祖尔祭坛上找一找吧。",o="检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。",p=2988},
  [2990]={t="萨迪斯·格希德",d="把这根羽毛交给占卜师萨迪斯·格希德。几年前，他离开鹰巢山去寻求黑暗的知识，但他内心深处仍是一个不折不扣的蛮锤矮人！；也许他的智慧能帮助我们找到沙普比克。；这根羽毛是从它的巢穴里拿出来的，如果你把它交给萨迪斯，那么他也许就可以用占卜法术找到沙普比克。；祝你好运，你。你可以在诅咒之地找到萨迪斯，他就在守望堡的法师塔上。",o="将沙普比克的羽毛交给诅咒之地的萨迪斯·格希德。",p=2989,r={{i=9468,n="沙普比克的羽毛",c=1}}},
  [2991]={t="耐克鲁姆的徽章",d="我会帮你找出那头狮鹫的下落，但你得先为我做点事情。巨魔城市祖尔法拉克里面有一个名叫耐克鲁姆的巨魔，他拥有一枚徽章，我很想研究一下那东西。把徽章交给我，我就帮你找到沙普比克。；祖尔法拉克在塔纳利斯的沙漠中。",o="将耐克鲁姆的徽章交给诅咒之地的萨迪斯·格希德。",p=2990,r={{i=9471,n="耐克鲁姆的徽章",c=1}}},
  [2994]={t="拯救沙普比克",d="你必须得救出沙普比克！；杀进邪枝巨魔那座城市——辛萨罗的山顶，从邪恶祭司海克斯那里拿到沙普比克笼子的钥匙，找到沙普比克，把它救出来！",o="到辛萨罗山顶去，杀掉邪恶祭司海克斯，找到沙普比克笼子的钥匙，然后救出沙普比克。",p=2993,w={{i=9651,n="狮鹫骑士战锤",c=1},{i=9652,n="狮鹫骑士护腿",c=1}},f=1},
  [3062]={t="黑暗之心",d="艾丹娜·邪爪是居住在西面废墟里的北泉鹰身人的皇后。她是个彻头彻尾的恶魔，我听说她的心是水晶做的。除了对别人的仇恨之外，她没有一丝其它的情感。你必须干掉艾丹娜，把她的黑心交给我。；我听说鹰身人有一种号角——在废墟北部的邪爪石那里吹响号角就可以召来她。；当她发现召唤她的是死亡的命运而不是她的同族时，她会有多么惊讶啊！",o="莫沙彻营地的塔罗·刺蹄要你给他拿去艾丹娜·邪爪的黑心。",r={{i=9528,n="艾丹娜的黑色坠饰",c=1}},w={{i=9665,n="羽冠手套",c=1},{i=9666,n="硬角束带",c=1}},f=2},
  [3121]={t="奇怪的要求",d="在莫沙彻营地北边拉瑞斯小亭的夏拉什·火刃有我所需要的东西！他调配出了一种混合物，我需要用它来……好吧，你以后会知道的。；快点出发，去找夏拉什。拿着这个东西，这是一颗皱缩的徽记，我答应夏拉什用此来交换草药。这是某个可怜侏儒的徽记，我在森林里撞见了他，然后就……我敢说夏拉什会很高兴得到这个东西的。；你可以在暗影裂谷里找到夏拉什。",o="将皱缩的徽记交给拉瑞斯小亭的夏拉什·火刃。",r={{i=9629,n="一颗皱缩的徽记",c=1}}},
  [3122]={t="向巫医尤克里回复",d="拿着这些草药，你。把它们交给巫医尤克里。；请告诉他，我对那些皱缩的徽记很满意。",o="将尼尔鲁的草药包送给菲拉斯的巫医尤克里。",p=3121,r={{i=9628,n="夏拉什的草药包",c=1}}},
  [3123]={t="测试容器",d="这是一个测试，对我将要进行的仪式和你的能力来说都是一个测试。拿着这个容器，你。你可以用它将一个生物的灵魂禁锢起来。；到东边的荒野中去寻找野兽吧。那些铁鬃熊，还有那些长牙奔跑者都是你的目标，你。杀死它们，在它们的灵魂逃跑之前用灵魂精华容器把它们收起来。",o="去杀掉10头铁鬃熊或是长牙奔跑者，然后使用灵魂精华容器捕获它们的灵魂。；将灵魂精华容器和10个野兽灵魂精华交给菲拉斯的巫医尤克里。",p=3122,r={{i=9594,n="野兽灵魂精华",c=10},{i=9618,n="野兽灵魂精华容器",c=1}}},
  [3124]={t="角鹰兽灵魂精华",d="既然你已经证明了自己是个值得信赖的$c，而且还具有使用灵魂精华容器的能力，那么现在我希望你能帮我抓住另一种生物。；角鹰兽多年来一直是暗夜精灵的忠实伙伴，它们的灵魂忠实而又坚定。；去杀掉十只乱羽角鹰兽，动作要快，将它的灵魂关在容器里，这样它的灵魂精华才可以保存下来。你可以在高原荒野一带找到这种角鹰兽，从这里一直向南走就到了。",o="杀掉10只任意种类的乱羽角鹰兽，然后用灵魂精华容器捕获它们的灵魂。",p=3123,r={{i=9595,n="角鹰兽灵魂精华",c=10},{i=9619,n="角鹰兽灵魂精华容器",c=1}}},
  [3125]={t="精灵龙灵魂精华",d="你，下一步我必须让你捕获一种看上去可能很脆弱，但却有着我们真正需要的强大精神力量的生物。我所说的就是精灵龙，它们是暗夜精灵的伙伴。我们必须抓一只精灵龙来进行研究，这样部落也可以从这种精神力量中获益。；我们需要它们的灵魂精华，你。杀掉八只小精龙或精龙，并俘获它们的灵魂。从这里向西就可以找到它们。",o="杀掉8只精龙或小精龙，然后用灵魂精华容器捕获它们的灵魂。",p=3124,r={{i=9596,n="精灵龙灵魂精华",c=8},{i=9620,n="精灵龙灵魂精华容器",c=1}}},
  [3126]={t="树人灵魂精华",d="在森林中到处游荡的森林漫游者是我们的下一个目标，你。暗夜精灵已经和树人结成联盟，共同与部落为敌。它们的行动也许很缓慢，但它们却是强大的卫士。；我们马上就能让这种力量为我们所用。；去找到三个森林漫游者，然后用灵魂精华容器将它们的灵魂捕获。",o="杀掉3个森林漫游者，然后用灵魂精华容器捕获它们的灵魂。",p=3125,r={{i=9593,n="树人灵魂精华",c=3},{i=9606,n="树人灵魂精华容器",c=1}}},
  [3129]={t="Weapons of Spirit",o="Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.",w={{i=9684,n="角鹰兽之力",c=1},{i=9686,n="精灵龙之魂",c=1},{i=9683,n="树人之力",c=1},{i=10652,n="山岭巨人的意志",c=1}},f=2},
  [3141]={t="洛拉姆斯",d="你想和恶魔战斗？听听我的故事会对你有好处。",o="听洛拉姆斯·萨里比迪斯讲述他的故事。",p=2744},
  [3161]={t="加兹瑞迪安",d="你，我是一个科学家，但是我真正的身份其实是一个赏金猎人！；很久以前，当巨魔还在片土地上横行的时候，他们制作了很多以加兹瑞拉为原型的饰物，并把它作为偶像膜拜。那些装饰物上的形象被称为“加兹瑞迪安”，也就是九头蛇之神的意思。；我自己找到了一些这种饰物，但是我需要更多来进行研究——也许你可以帮我搞到一些？；我甚至发明了一个可以帮助你寻找加兹瑞迪安的装置！把这件头盔拿去，开始寻找吧！",o="塔纳利斯的玛尔冯·瑞文斯克要你收集30件加兹瑞迪安饰物。",r={{i=8443,n="加兹瑞迪安饰物",c=30},{i=9978,n="加兹瑞迪安探测器",c=1}},w={{i=10827,n="勘探员外套",c=1},{i=10826,n="学识法杖",c=1}}},
  [3181]={t="玛尔戈的巨角",d="这根巨大的角上有许多擦痕和裂缝，还有一块金属物体嵌在粗糙的表面上。；仔细检查了一番之后，你发现这块金属实际上是一把断掉的斧头。金属上刻着一行字：；巡山人贝波蒂的财产。；当你试着把斧头拔出来的时候，它一下子变成了无数的碎片。；真糟糕！",o="将玛尔戈的巨角交给巡山人贝波蒂。",r={{i=10005,n="玛尔戈的巨角",c=1}}},
  [3182]={t="证明信",d="你指望我会相信这样一个故事？真正的角怎么会是这个样子？；听着，把这个明显是赝品的东西拿给铁炉堡的索里奥斯馆长看看。如果他能证明你的话是真的，那么你就能收到一份证明。把那份证明拿回来给我，我就给你一把灼热峡谷的钥匙。；快动身去找索里奥斯馆长！",o="把玛尔戈的巨角交给铁炉堡的索里奥斯馆长。",p=3181,r={{i=10005,n="玛尔戈的巨角",c=1}}},
  [3281]={t="被偷走的银币",d="你杀了迅猛龙，很好，但是它们偷走的那些银币必须要找回来！我接到报告说有大量的迅猛龙聚集在棘齿城南面，那里现在被称为迅猛龙平原，它们八成是把银币藏在那里了。；到那个迅猛龙平原去找到被偷走的银币，然后把银币送还到我这里来。",o="把被偷走的银币交给十字路口的加兹罗格。",p=869,r={{i=5061,n="被偷走的银币",c=1}},w={{i=11853,n="流浪之靴",c=1},{i=2694,n="移民者护腿",c=1}},f=2},
  [3301]={t="茉拉·符文图腾",d="我的族友茉拉·符文图腾去了银松森林，她去那里是为了帮助我们的亡灵盟友。银松森林状况不佳，那是一片濒死的森林，茉拉希望通过自己的努力给银松森林带来新的活力。也许在贫瘠之地找到的这种奇怪的生命形式能够对她在银松森林的工作有所帮助。；把你收集到的龟壳样品交给她吧，茉拉一般都在瑟伯切尔待着。如果运气够好的话，这些贝壳可以帮她找到治愈那片濒死之地的方法。",o="和银松森林瑟伯切尔的茉拉·符文图腾谈一谈。",p=880,r={{i=10414,n="钳嘴龟壳样本",c=1}},w={{i=10820,n="草种腰带",c=1},{i=10821,n="播种者披风",c=1}},f=2},
  [3321]={t="秘银会的认可",d="你为秘银会做了很多事情，你。像你这样无私而纯粹地奉献并不是人人都能做到的。在我和加尔文的心中，你无疑已经成为我们的一员了。；所以我觉得你应该获得一些小奖励。其实也没什么，也就是一个饰品，我想你应该很清楚它的意义，而且我相信它应该就是你到我们这里来的最初目的。",o="等待特伦顿完成他的工作。"},
  [3341]={t="寒冰之王",d="在贫瘠之地有一处藤蔓交错的地方，那里被称为剃刀高地。我们很久以前派去的斥候就已经发现那里的情况有些不对劲了，最近的发现表明那里的情况变得更加糟糕了……；剃刀高地的野猪人和亡灵天灾结成了同盟。有个名叫寒冰之王亚门纳尔的巫妖指挥着它们的每一步行动。；亚门纳尔与耐奥祖有着直接的心灵感应联系，我们必须切断这样的联系，你。我们必须干掉寒冰之王。",o="安德鲁·布隆奈尔要你杀了寒冰之王亚门纳尔并将其头骨带回来。",r={{i=10420,n="寒冰之王的徽记",c=1}},f=2},
  [3364]={t="热酒快递",d="嘿！我之前应该把这可口的热酒交给安威玛尔的德南·弗卡特，现在我终于想起来该把东西送过去了！但是我肯定没法在酒变凉之前把酒送给他！；你看起来挺灵敏的，也许你能……这杯热酒只能保温几分钟，而且德南要的可不是冰镇热酒，所以你一定要赶快！安威玛尔就在这里的东北面，那个在山壁上凿出来的大洞里。；不要忘了把我的杯子带回来！",o="在热酒冷掉之前把它交给安威玛尔的德南·弗卡特。",r={{i=10439,n="德南的热酒",c=1}}},
  [3367]={t="苏塔拉之石",d="<杜里奥斯痛苦地呻吟着。>；我受了重伤，$c。我感觉……头重脚轻……世界在旋转……身体里面在出血。；我必须回到铁炉堡，帮帮我，你……",o="帮助杜里奥斯回到铁炉堡。"},
  [3368]={t="苏塔拉之石",d="我的好兄弟：；如果你读到了这封信，那我已经不在这个世界上了。至于这封信是怎样到你手中的，我就不得而知了。 ；关于那些石头：它们确实存在，而且在黑铁矮人手里。他们的领袖，黑衣拉索里克正在使用石头的力量来禁锢我们勘探队的同伴。他们被带到了大熔炉那里。他们的意志已经被扭曲，被迫不分昼夜地干活以完成一个名叫奥比斯顿的东西。；帮帮他们，我的兄弟。这是一个死者最后的希望了。；——杜里奥斯",o="把烧焦的信件交给铁炉堡的索里奥斯，他在探险者大厅里。",p=3367,r={{i=10443,n="烧焦的信件",c=1}}},
  [3369]={t="在噩梦中",d="这块碎片中蕴含有巨大的秘密，它是翡翠梦境的精华所在。然而，我从这片碎片中看到的却不是梦境，而是一种噩梦。；我并不是想要警告你什么，你，但是我希望你尽快把这个碎片送到一位睿智的德鲁伊手里。；到雷霆崖的长者高地去找哈缪尔·符文图腾，我不能再多说了。",o="把噩梦碎片交给长者高地的哈缪尔·符文图腾。",p=6981,r={{i=10649,n="噩梦碎片",c=1}},w={{i=10657,n="塔巴尔护肩",c=1},{i=10658,n="泥潭沼泽长靴",c=1}},f=2},
  [3370]={t="在噩梦中",d="这块碎片中蕴含有巨大的秘密，它是翡翠梦境的精华所在。然而，我从这片碎片中看到的却不是梦境，而是一种噩梦。；我并不是想要警告你什么，你，但是我希望你尽快把这个碎片送到一位睿智的德鲁伊手里。；到达纳苏斯的塞纳里奥议会去找玛斯雷·驭熊者，我不能再多说了。",o="把噩梦碎片交给达纳苏斯的玛斯雷·驭熊者。",p=6981,r={{i=10649,n="噩梦碎片",c=1}},w={{i=10657,n="塔巴尔护肩",c=1},{i=10658,n="泥潭沼泽长靴",c=1}},f=1},
  [3372]={t="释放他们",d="释放他们，$c。即使他们的肉体已经不复存在，苏塔拉的力量也会让他们去完成自己的使命。；苏塔拉祭坛是关键。到这里的北边去，在洞穴上面的山顶……暮光之锤守卫着一件古器。拿到它，把它放在苏塔拉祭坛上。；<濒死的考古学家倒下了。>",o="到北方去找到被暮光之锤守卫着的神秘的古器，然后把它带到熔渣之池的苏塔纳祭坛上。",p=3371,r={{i=10442,n="神秘的古器",c=1}}},
  [3373]={t="伊兰尼库斯精华",d="当你接触宝石的时候，一个雄浑的声音回响在你的脑际。；“凡人，请聆听我的请求。我是绿龙军团的伊兰尼库斯，这座被诅咒的神庙的守护者。我的任务是阻止这些巨魔召唤出上古的邪神，但是现在看来，我失败了。我把我的精华力量注入了这块宝石中，我能感到自己对梦境的控制正在陷入混乱。请你帮帮我——把这块宝石放入我的巢穴中，让那里的魔法净化我心智中的污点，那样我才能够安息。”",o="把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。",r={{i=10454,n="伊兰尼库斯精华",c=1}}},
  [3374]={t="伊兰尼库斯精华",d="你碰触了一下誓言石，伊萨里奥斯的声音通过这块石头直接和你进行对话。；“一旦你拿起誓言石，就表示你会帮助我，并且准备帮助伊瑟拉的绿龙拯救伊兰尼库斯的灵魂。我们所要做的第一件事情，就是将禁锢着伊兰尼库斯自由心智的宝石交给我。”；“快一点吧，你，我们要共同努力来拯救一个值得拯救的灵魂。”",o="把伊瑟拉巨龙军团的誓言石和被禁锢的伊兰尼库斯精华交给悲伤沼泽的伊萨里奥斯。在那里你可以决定是否要帮助伊瑟拉的绿龙军团。",p=3373,r={{i=10589,n="伊瑟拉巨龙军团的誓言石",c=1},{i=10455,n="被禁锢的伊兰尼库斯精华",c=1}}},
  [3376]={t="刺鬃酋长",d="你，我听说过你的名字，也许你可以帮助我们一个忙。；我们牛头人在这块土地上创建了自己的家园，但是我们也付出了巨大的代价。刺刃峡谷中有一座刺背野猪人的村庄，在他们的首领——刺鬃酋长的带领下，野猪人一直在与我们交战，这让我们的生活变得非常艰难。我要你去取回刺鬃酋长的徽记！；你可以在东边的峡谷中找到他们那简陋的村庄，刺鬃酋长就在村子里面。",o="把刺鬃酋长的徽记交给红云台地的卫兵维萨罗·风羽。",r={{i=10459,n="刺鬃酋长的徽记",c=1}},w={{i=10635,n="彩色链甲护腿",c=1},{i=10636,n="游牧民手套",c=1}},f=2},
  [3377]={t="艾露恩祷言",d="你愿意帮我的忙吗？无论怎样，请先听听我的故事吧。",o="听萨麦尔讲述他的故事。"},
  [3378]={t="艾露恩祷言",d="你愿意帮我的忙吗？你能找到艾露恩祷言吗？；就如我所说的，祷言被刻在一块金色的石板上，那些崇拜它的恶棍把它占为己有。；如果你能够找回我的祷言，就把它交给达纳苏斯的阿斯塔利·逐星。如此我才能在遭受如此多不幸之后重新恢复信心，而且更加重要的是，我的祈祷能够有人听见，至于我是否能被宽恕，我根本不关心。",o="找到艾露恩祷言，然后将其交给达纳苏斯的阿斯塔利·逐星。",p=3377,r={{i=10458,n="艾露恩祷言",c=1}},w={{i=10745,n="凯拉雷护肩",c=1},{i=10746,n="符文钢质臂铠",c=1}},f=1},
  [3379]={t="暗影蛛丝",d="灼热峡谷的蜘蛛可以为我们提供暗影蛛丝，这使得它们的商业价值倍增。据我所知，暗影蛛丝在我们的交易中有着很大的需求量。；最近有一批偷猎者来到了这里，他们随意地屠杀蜘蛛，根本不关心他们的行为可能造成的长期影响。我给你的第一个任务非常简单：找到他们……然后终结他们。；到北边去开始你的搜索吧。；如果你需要帮助的话，就去和拆毁者谈谈。",o="杀死在灼热峡谷游荡的暗影蛛丝偷猎者小队。尼莉丝认为他们共有5名成员，你的任务就是把他们全都干掉。"},
  [3385]={t="黑市交易",d="他们把自己称为黑市成员，他们都是些贪财如命的杂碎，只要有利可图，他们什么都会倒卖！；现在情况变得更加糟糕了，你。他们在灼热峡谷创建了一个基地，贸易首领考维克在那里策划着所有的行动，并且和该地区的黑铁矮人保持着密切的关系。；我们必须对这种行为进行严厉打击，给他们一个严厉的警告。去杀掉贸易首领考维克和他的同伙科朗克，把他的商人的背包给我拿回来，你的任务就算完成了。；向大熔炉进发！",o="杀了贸易首领考维克和他的同伙科朗克。从他的尸体上拿回商人的背包，把它交给尼莉丝。",p=3379,r={{i=10467,n="商人的背包",c=1}}},
  [3441]={t="神圣的惩戒",d="听听我的故事吧，旅行者。",o="听卡拉然·温布雷讲述他的故事。"},
  [3442]={t="无瑕之焰",d="你做出了正确的决定，你。；我们必须对敌人的要害下手，除掉那四座哨塔。；一旦这四座塔都化为灰烬，我们就可以在他们反应之前发动攻击。；你需要合适的工具来点燃防御塔，而制作这样的工具就需要合适的材料。；给我弄四份烈焰之心和四份傀儡之油来，然后我就会给你制作出一把燃烧着无瑕之焰的火炬。；在这片土地上的傀儡和元素生物身上找找吧。",o="收集4份烈焰之心和4份傀儡之油，然后把这些东西交给卡拉然·温布雷。",p=3441,r={{i=10509,n="烈焰之心",c=4},{i=10511,n="傀儡之油",c=4}}},
  [3443]={t="铸造火炬杆",d="为了承载无瑕之焰，我们需要一根杆子和一只箱子，你必须首先从杆子入手。；大熔炉的黑铁工头和黑铁奴隶贩子使用附魔过的瑟银作为武器，那是一种很坚硬的合金。如果你可以给我弄八把瑟银匕首来，我就能将它们熔解并铸成一根杆子。",o="给卡拉然带去8把瑟银匕首。",p=3442,r={{i=10551,n="瑟银匕首",c=8}}},
  [3444]={t="石环",d="我曾经进入到沉没的神庙中的那个充满邪恶气息的房间，那里的恶魔会残忍地杀死每个进入房间的冒险者……我在那些满是泥泞的房间里艰难前进，差点就找不到出来的路了。我只记得自己蹒跚地穿过一个圆形的房间，房间里到处都是毒蛇塑像……；最后，我发现了一块圆石，上面印着相同的毒蛇标记，我把它打包运到棘齿城的车间去了。去把它取回来，也许我能让你知道更多的信息。",o="到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。",r={{i=10556,n="石环",c=1}}},
  [3449]={t="奥术符文",d="魔法曾经同艾露恩一样受到某些精灵的尊崇。他们中最厉害的法师发明了文字，并在石板上记录下了魔法的规律和他们对事物的认识，并将这些石板留在公开的场合供人研习。；我非常想要获得这些来自埃达拉斯废墟的文字拓片。我将为你提供工具来帮助你取得拓片，但是你必须自己去寻找它们。多加小心，对埃达拉斯废墟感兴趣的可不仅仅是探险者协会。",o="使用绘图工具包获取贝萨玛拉符文、辛耶尔符文、玛科里符文和塞尔哈符文的拓片，然后转至艾萨拉南部半岛外的小岛，把它们交给驾驶员西格斯·熔光。",p=3448,r={{i=10563,n="拓文：贝萨玛拉符文",c=1},{i=10564,n="拓文：辛耶尔符文",c=1},{i=10565,n="拓文：玛科里符文",c=1},{i=10566,n="拓文：塞尔哈符文",c=1}}},
  [3452]={t="烈焰之盒",d="我们还需要最后一部分来完成火炬。；在西北方的山脚下，你可以找到暮光之锤的营地。据说他们携带着特殊的徽章和石像，用以表示对神明的崇敬。这些徽章和石像具有强大的魔法能力，足以制成一个魔法容器。将拉格纳罗斯符记交给我，我将试着从里面提取魔法，然后制造一个容器。",o="找到一个拉格纳罗斯符记，把它交给卡拉然·温布雷。",p=3443,r={{i=10552,n="拉格纳罗斯符记",c=1}}},
  [3453]={t="惩戒火炬",d="给我一点时间来拼合这些碎片，然后对它进行必要的附魔。",o="等待卡拉然·温布雷完成惩戒火炬。",p=3452},
  [3461]={t="向法师泰摩尔回复",d="泰摩尔并没有给我什么可以付你报酬的东西，我建议你回铁炉堡去的时候好好跟他交流一下。我想他还在秘法区，去找他吧，他会付你报酬的。；再次感谢你帮助他摆脱困境，祝你好运。；哦，我不需要绘图工具包啦，你为什么不顺便把它还给泰摩尔呢？",o="到铁炉堡去，将法师泰摩尔的绘图工具包还给他。",p=3449,r={{i=10445,n="绘图工具包",c=1}},w={{i=10707,n="钢板胫甲",c=1},{i=10708,n="骨灵宝珠",c=1}},f=1},
  [3463]={t="烧掉它们！",d="听好了，你。虽然我们无法摧毁那四座哨塔，但是你可以使用惩戒火炬点燃它们，这种火焰是任何元素或力量都没法熄灭的。；在哨塔燃烧的过程中，没有什么部队可以驻扎在里面，这样他们的第一道防线就失效了。；你必须进入每一个塔楼，用惩戒火炬把它们烧掉。要小心黑铁矮人的精英哨兵，你。",o="使用惩戒火炬点燃北部、南部、东部和西部的哨塔。",p=3462,w={{i=10742,n="群龙护腿",c=1},{i=10743,n="龙火头盔",c=1},{i=10744,n="黑龙之斧",c=1}}},
  [3501]={t="多多益善",d="尽管你可能找不到纯净无瑕的德莱尼水晶，但是在你探索这片土地的过程中，一定可以找到若干有瑕疵的德莱尼水晶碎片。；库米沙是否可以利用这些碎片返回家园，这还很难说，但是这些碎片可以为德莱尼人所用。；把你发现的有瑕疵的德莱尼水晶碎片都交给我，我会给你报酬的。",o="将有瑕疵的德莱尼水晶碎片交给库米沙，你就可以得到相应的回报。",r={{i=10593,n="不完美的德莱尼水晶碎片",c=1}}},
  [3504]={t="叛徒",d="这个毫无诚信可言的女人！她只能配得上这个称呼——罪有应得！；我可能犯下了一个严重的错误，你。我相信了一个血精灵。更糟糕的是，她还是个女的！；她声称艾萨拉那里埋藏着数不尽的财富……我派了一些战士保护她去那里，满以为我可以有所斩获。但是，到头来我却被耍了——她把他们都杀掉了。；我要报仇，你，但是我手边已经没有可以派遣的人了。到哈达尔营地北边的瓦罗莫克去找阿格图，他会告诉你更详细的情况。",o="把这封给阿格图的密信交给艾萨拉的阿格图·血拳。",r={{i=10643,n="给阿格图的密信",c=1}}},
  [3505]={t="叛徒",d="我的计划是这样的：；我们从艾萨拉的北部半岛开始，沿着悬崖的南部开始进攻她的工人。把他们都干掉，让他们知道当叛徒的后果。；先别管她——她大部分时间都跟她的护卫一起在艾萨拉进行搜寻工作。在杀死她的工人之后，我们在去考虑怎么收拾她比较好。我们应该先仔细侦察一番，也许有一些可以激怒她的东西。",o="杀死10个血精灵搜寻者和10个血精灵勘测员，并找到大法师雷姆托里的营地。一旦你发现了营地，就去找到某个对她极为重要的东西，以用于激怒她，让她与你战斗。",p=3504},
  [3506]={t="叛徒",d="经过思考，你对眼下的情形已经有了大致的了解，你的脸上浮现出一丝笑容：也许摧毁水晶将使那些杀死众多兽人并背叛贝尔戈洛姆的血精灵方寸大乱？；你继续翻译着文字和图片，并了解到其中一块水晶就在这个石阵的制造者身上——其馀的则在更为邪恶的生物手中。；你合上书本，开始考虑要摧毁哪块水晶。",o="摧毁大法师雷姆托里携带的奥术聚焦水晶并杀死她。然后把她的徽记交给艾萨拉的阿格图·血拳。",p=3505,r={{i=10597,n="大法师雷姆托里的徽记",c=1}}},
  [3507]={t="叛徒",d="回到奥格瑞玛的贝尔戈洛姆那儿去，他肯定想要好好看看这个女人的徽记！我们很快就回去。；啊，这真是一个好日子。谢谢你的帮助，你。",o="与奥格瑞玛的贝尔戈洛姆·石槌谈一谈。",p=3506,r={{i=10597,n="大法师雷姆托里的徽记",c=1}},w={{i=10709,n="焚石宝珠",c=1},{i=11120,n="贝尔戈洛姆的战锤",c=1}},f=2},
  [3510]={t="恶魔之名",d="她杀了我的孩子，她称自己为海洋的统治者。她是个虚伪的神。杀死她，把她的所有徽记都带回来。；这样，你就能得知你要寻找的名字，并得到与其同样重要的东西。；她的名字叫做赫塔拉。；<亚考罗克指向西南方。>；去吧！",o="杀掉赫塔拉，将染血的赫塔拉徽记、破碎的赫塔拉徽记和淤血的赫塔拉徽记交给亚考罗克。",p=3509,r={{i=10599,n="破碎的赫塔拉徽记",c=1},{i=10598,n="染血的赫塔拉徽记",c=1},{i=10600,n="淤血的赫塔拉徽记",c=1}}},
  [3511]={t="恶魔之名",d="我曾许诺将恶魔之王污染者拉瑟莱克的名字告诉你。不过，我得先为你的旅程准备一些至关重要的东西。；你要铸造的武器必须有调剂才能制成。给我一点时间，让我从这些徽记中弄点血液出来。；<亚考罗克用他那巨大的手掌挤压徽记，压出了血液。>；将调剂交给洛拉姆斯，告诉他，那个恶魔的名字是拉瑟莱克。",o="将调剂交给洛拉姆斯·萨里比迪斯。",p=3510,r={{i=10610,n="赫塔拉之血",c=1}}},
  [3513]={t="符文卷轴",d="这份看起来很正式的卷轴被一条银色丝带紧紧地裹着。你觉得会有什么人对此感兴趣，但是这人是谁呢？；在灰谷边界以北有一处前哨站，如果卷轴上的信息与暗夜精灵有关，那么你就应该把它送到那儿去。",o="将符文卷轴带到贫瘠之地的北部警戒塔去。",r={{i=10621,n="符文卷轴",c=1}}},
  [3514]={t="部落的示威",d="这份卷轴是在石爪峰的树妖琳萨瑞尔那儿得来的，她是猛禽洞穴的头目。；她不会再与带着这份卷轴的信使有任何联系了，哈哈……但是我们必须保持警戒。部落不会允许此地再出现联盟的信使。；你，到猛禽洞穴去，杀死琳萨瑞尔，然后给他们一个所有人都能看到的信号。带上部落的旗帜，把它插在猛禽洞穴里，这样他们就不会急于派出另一个信使来到我们的地盘上送死了。",o="杀死猛禽洞穴的领袖琳萨瑞尔。",p=3513,w={{i=10653,n="开拓者长靴",c=1},{i=10654,n="黄麻手套",c=1}},f=2},
  [3517]={t="搜索知识",d="我承认，你，我大部分时间都呆在艾萨拉。贝尔戈洛姆的惩罚对我也有好处。；在离开这里之前，我进行了一些研究，你知道遍布这一地区废墟中的东西是多么的珍贵吗？；我可以告诉你更多细节，如果你帮我收集一些东西，我甚至会分给你一些利润。；在东边的埃达拉斯废墟里面有我需要的石板，它们都是以上层精灵的大法师命名的。去寻找石板，然后我们再来进一步详谈。",o="找到贝萨玛拉石板、辛耶尔石板、玛科里石板和塞尔哈石板，把它们交给艾萨拉的杰迪加。",r={{i=10538,n="贝萨玛拉石板",c=1},{i=10539,n="辛耶尔石板",c=1},{i=10540,n="玛科里石板",c=1},{i=10541,n="塞尔哈石板",c=1}}},
  [3518]={t="玛加萨的石版",d="第一块石板要交给一位名叫玛加萨的牛头人。她是雷霆崖的长者之一，也是牛头人和被遗忘者结盟的支持者。她比其它长者中的任何一个都更希望帮助亡灵返回人类的状态。；将贝萨玛拉石板交给她，这块石板或许能帮助被遗忘者……至少她是这么说的。",o="将贝萨玛拉石板交给雷霆崖的玛加萨·野性图腾。",p=3517,r={{i=10538,n="贝萨玛拉石板",c=1}}},
  [3520]={t="尖啸者的灵魂",d="我在寻找菲拉斯的山谷尖啸者的灵魂。它们是某位古老神灵的亲戚，它们的灵魂与那位神灵连在一起。；带上这根魔杖去菲拉斯，在菲拉斯南部和中部区域寻找并杀死山谷尖啸者，对它们的尸体使用我的魔杖。这将使它们的灵魂现出原形，此时你就可以收集灵魂的精华了。；将我的魔杖和尖啸者的灵魂精华交给我，我就会告诉你刚才我所说的那位神灵的详细情况。",o="在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。",r={{i=10699,n="叶基亚的树枝",c=1}}},
  [3521]={t="埃沃隆的解药",d="我们也许能帮埃沃隆的忙，我知道有种方法能解蛛毒。但是我需要一些成分来制作解药。；首先是紫蓝色蘑菇，它们一般生长在树下，你也可以从南边的劣魔身上找到它，劣魔们很喜欢这种蘑菇。我还需要月牙百合花，它们只生长在水池周围。；最后一种成分也许是最难获得的，你必须从咬伤了埃沃隆的蜘蛛身上获取树林蜘蛛的脓液。",o="在幽影谷中为迪兰妮亚·月光收集7朵紫蓝色蘑菇、4朵月牙百合花和一份树林蜘蛛的脓液。",p=3519,r={{i=10639,n="紫蓝色蘑菇",c=7},{i=10641,n="月牙百合花",c=4},{i=10640,n="树林蜘蛛的脓液",c=1}}},
  [3522]={t="埃沃隆的解药",d="解药准备好了，你。请确保埃沃隆把它喝下去。；你要知道，解药的有效时间只有5分钟。你必须及时地把解药送到他嘴边。；赶快去吧，你。",o="在5分钟内将埃沃隆的解药交给他。你可以北边的洞穴入口外面找到埃沃隆。",p=3521,r={{i=10642,n="埃沃隆的解药",c=1}},w={{i=10655,n="莎草短裤",c=1},{i=10656,n="树皮外衣",c=1}},f=1},
  [3523]={t="剃刀高地的亡灵天灾",d="太好了！我叫奔尼斯特拉兹，感谢你前来营救我。我已经放弃了求生的欲望……甚至想到自己会被这些亡灵天灾滋生的渣滓给吃了。是的——我说的是亡灵天灾。他们与野猪人达成了协议，你所看到的这些噩梦般的景象就是这个协议的结果。；听着……与其逃跑，我宁愿奋力一搏，为所有的生灵造福。你愿意帮助我吗？这也许很危险，但是你看起来应该可以胜任。",o="如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。",r={{i=10682,n="奔尼斯特拉兹的誓言石",c=1}}},
  [3524]={t="搁浅的巨兽",d="众所周知，巨大的海洋生物常年潜身于黑海岸边缘，它们在此游弋，直至死亡。近来，这些野兽的数量日益增加，并且开始侵袭海岸。我受月神殿的派遣到这里来调查，但是海水中的鱼人使调查变得非常困难。；被邪恶的灰雾鱼人所控制的奥伯丁南部海岸上躺着一头搁浅的巨型生物，你能帮忙去从这头巨兽身上弄点骨头回来以供我研究吗？",o="从奥伯丁南面的海岸上收集海洋生物的骨头，然后带着骨头向奥伯丁的温尼斯·布莱葛回复。",r={{i=12242,n="海洋生物的骸骨",c=1}}},
  [3525]={t="Extinguishing the Idol",o="Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.；Protect Belnistrasz while he performs the ritual to shut down the idol.",p=3523},
  [3527]={t="摩沙鲁的预言",d="摩沙鲁的古老预言中谈及获取神灵哈卡的灵魂精华的方法。这个方法被写在两块石板上，并被带到加基森西边的巨魔城市祖尔法拉克中。；把摩沙鲁石板交给我！；第一块石板在早已死去的巨魔殉教者塞卡那里。据说杀害他的凶手受到诅咒，都被变成了甲虫，正在他的神庙周围游荡。；第二块石板在加兹瑞拉圣水池的水占师维蕾萨手中。；得到石板之后，把它们交给我。",o="将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。",p=3520,r={{i=10660,n="第一块摩沙鲁石板",c=1},{i=10661,n="第二块摩沙鲁石板",c=1}}},
  [3528]={t="神灵哈卡",d="现在是获取哈卡化身的精华的时候了。；把哈卡之卵拿到悲伤沼泽的那座沉没的神庙中，在堕神圣地中使用卵的力量激怒死去的神灵。；他将派出那些被称作“嗜血者”的奴仆对付你，杀掉它们，取出它们的哈卡莱血液，然后用这些血液熄灭包含哈卡灵魂能量的不灭火焰。当你熄灭所有的火焰时，哈卡的化身就可以进入我们的世界了。；打败他，将他的精华封印在哈卡之卵中。",o="将装满的哈卡之卵交给塔纳利斯的叶基亚。",p=4787,r={{i=10662,n="装满的哈卡之卵",c=1}},w={{i=10749,n="灰岩头盔",c=1},{i=10750,n="生命之力短剑",c=1},{i=10751,n="珠光头饰",c=1}}},
  [3541]={t="杰斯雷蒙的石版",d="我在奥格瑞玛有个主顾，他住在暗巷区。如果你不熟悉那里，那么你是很难找到他的，不过如果你到那个区域中最高的那座建筑物里去，就应该能找到他。；不过呢，你可别让全卡利姆多的人都知道他在哪里，他在干什么——这对咱们俩都没好处。；为了这块辛耶尔石板，他会付给咱们一大笔钱的。我不知道他为什么如此在乎这块石板，不过你真该看看他听到这块石板的消息后有多激动。",o="将辛耶尔石板交给奥格瑞玛的杰斯雷蒙。",p=3517,r={{i=10539,n="辛耶尔石板",c=1}}},
  [3542]={t="安德隆·甘特的石版",d="安德隆·甘特是我的下一个主顾。他通常待在幽暗城里……就在炼金房附近。当我们谈到石板的用途时，他就有些藏不住话。显然幽暗城中的某些法师想要学习上层精灵所使用的魔法。他们认为这石板能对他们有所帮助。玛科里曾以善于召唤各种生物——特别是元素生物而闻名。；把玛科里石板给他带过去，然后回到我这儿来取你的报酬吧。",o="将玛科里石板交给幽暗城的安德隆·甘特。",p=3517,r={{i=10540,n="玛科里石板",c=1}}},
  [3561]={t="大法师克希雷姆的石版",d="最后这块石板要交给一个非常危险的家伙，你。听着，比起我先前让你接触的那些人，我对他可以说是非常不信任的。；大法师克希雷姆在艾萨拉的一处山顶上建了座高塔。他是个人类，但是他的行为跟我见过的……或是杀掉的那些人类大不相同。他充满了力量，我可不敢问他为什么想要这块石板。；他来找过我，但是他跟我说，当我准备就绪时，他的侍卫萨纳斯会带我到塔里去。到北边去找萨纳斯吧。",o="将塞尔哈石板交给艾萨拉的大法师克希雷姆。",p=3517,r={{i=10541,n="塞尔哈石板",c=1}}},
  [3566]={t="奥比斯顿",d="这……这……这是个陷阱。；原谅……我。；杀掉这个该死的混蛋……为我们杀掉他……为了索里奥斯。",o="杀死黑衣拉索里克和奥比斯顿，带着黑衣拉索里克的徽记和奥比斯顿的精华回到铁炉堡的索里奥斯那儿。",p=3372,r={{i=10447,n="黑衣拉索里克的徽记",c=1},{i=10446,n="奥比斯顿的精华",c=1}},w={{i=10740,n="百夫长腿甲",c=1},{i=10741,n="洛德莱克头盔",c=1},{i=10739,n="坚韧之戒",c=1}},f=1},
  [3568]={t="堕落之水",d="看见我后面的那个看上去随时都可能病倒的牛头人了吗？她前段时间去过艾萨拉。她说自己在经过埃达拉斯废墟时受到纳迦的攻击，而且负了伤。；在击退一些纳迦之后，她在海滩休息了一下，并饮用了海潮之池中的水，现在她感觉有些恶心……；我要找出她饮用的水。拿着这个盒子，我在里面放了一些空瓶子，用它们到各个海潮之池中收集一些水，然后回来。",o="在艾萨拉的埃达拉斯废墟旁的海潮之池中收集4瓶水，然后回到药剂师科雷那儿。",r={{i=10691,n="装满水的瓶子#1",c=1},{i=10692,n="装满水的瓶子#2",c=1},{i=10693,n="装满水的瓶子#3",c=1},{i=10694,n="装满水的瓶子#4",c=1}}},
  [3569]={t="堕落之水",d="把这个交给瑟尔萨。也许她可以痊愈……也许不能。反正要在她喝下后才能知道结果。",o="将科雷的药剂交给幽暗城的瑟尔萨·风歌。",p=3568,r={{i=10712,n="科雷的药剂",c=1}}},
  [3601]={t="我就是基姆加尔！",d="我就是基姆加尔！你知道基姆加尔对血精灵意味着什么吗，你？我对他们来说不过是一只小老鼠……或者其它类似老鼠的东西，那些该死的欺凌弱小的家伙！；他们雇佣我来帮他们在这里搜寻一些失落的宝物，当然，在他们告诉我要找什么东西以及他们愿意付给我多少钱之后，我就决定单干了。他们马上翻脸，还想干掉我……干掉我！；所以，你看，永远都不要相信血精灵。；问题是，我的一些东西还在他们手里，看样子我自己是拿不回来了。你能帮帮我吗？",o="搜索萨拉斯营地，找到基姆加尔的指南针、望远镜、烧鸡和花生，然后把它们交给艾萨拉的基姆加尔。",r={{i=10717,n="基姆加尔的指南针",c=1},{i=10715,n="基姆加尔的望远镜",c=1},{i=10722,n="基姆加尔的烧鸡",c=1},{i=10718,n="基姆加尔的花生",c=1}}},
  [3602]={t="艾萨拉水晶",d="艾萨拉南部地区的古代峭壁巨人以吞噬这个地区的岩石和建筑物为生。他们的排泄物具有高度的延展性和极其明显的水晶特性，所以被称作艾萨拉水晶。；这种东西主要在南部地区出现，但是由于那些巨人的暴力倾向，通常你很难得到它们。；你必需到艾萨拉南部去，收集足够多的艾萨拉水晶来制作武器的主体部分。我的地狱犬会帮助你收集水晶的。",o="在艾萨拉南部收集20块艾萨拉晶体。你可以使用地狱犬协助寻找一些隐藏的矿脉。；任务完成之后就回到洛拉姆斯那里去。",p=3511,r={{i=10714,n="艾萨莱特晶体",c=20}}},
  [3621]={t="武器的铸造",d="下一步就是铸造武器了。你必须把淬火过的艾萨拉水晶交给一个有能力操纵恶魔能量的铁匠。；在荆棘谷就有这样的一个铁匠——他就是加尔文，秘银会的领袖。他会按照你的要求打造武器，到祖尔格拉布和莫什奥格食人魔山之间的区域去寻找他的营地吧。；愿你的决心和信念引领你度过这场考验。如果你失败了，你的神会对你微笑。去吧，$r。",o="把货物交给荆棘谷的加尔文。",p=3602,r={{i=10738,n="给加尔文的货物",c=1}}},
  [3625]={t="魔化艾萨拉水晶武器",d="你，制造任何武器都需要花费一些时间。；另外，你每三分钟才可以使用一次恶魔诅咒的力量。它可以削弱污染者和他的爪牙们的力量，但效果持续的时间可能会有差异。因此，你必须在恰当的时候使用恶魔诅咒！；现在请稍等片刻，让我来为你锻造武器吧，你。",o="等待加尔文为你锻造武器。",p=3621,w={{i=10697,n="魔化艾萨莱特水晶匕首",c=1},{i=10698,n="魔化艾萨莱特水晶法杖",c=1},{i=10696,n="魔化艾萨莱特水晶剑",c=1}}},
  [3627]={t="收集破碎的护符",d="要见到污染者的话，你就必须摧毁他手下的三个头目的力量，然后把他们身上的护符碎片收集起来。当你拿到三块碎片之后再回到我这里来，我会给你进一步的指示。；出发吧，你！到诅咒之地去！把戈洛尔、瑟温妮、奥利斯塔全部除掉！",o="杀掉毁灭者戈洛尔、瑟温妮，以及大法师奥利斯塔。从他们到尸体上拿到戈洛尔的护符、瑟温妮的护符和奥利斯塔的护符。；记住使用你的魔化艾萨拉水晶武器来削弱他们，否则他们是无法被杀死的——你必须小心谨慎地使用你的武器……",p=3626,r={{i=10755,n="奥利斯塔的护符",c=1},{i=10753,n="戈洛尔的护符",c=1},{i=10754,n="瑟温妮的护符",c=1}}},
  [3628]={t="恶魔拉瑟莱克",d="拉瑟莱克的巢穴位于诅咒之地最高的山脉的顶端，通往巢穴的唯一途径就是使用山脉附近的传送符文。只要你拥有护身符，就可以轻松到达巢穴。到了那巢穴之后，你必须召唤那个恶魔，护身符就是召唤的关键，你，你要在污染者祭坛上使用它。；去打败污染者拉瑟莱克，把他的犄角带回来。这将成为我们希望的象征——在这个饱经战火的世界上仍然有英雄存在的证据。",o="消灭污染者拉瑟莱克，将污染者之角交给部落英雄的灵魂。另外你还要把污染者防护结界交给他，这样部落英雄的灵魂就可以消灭它，以避免它落入邪恶势力之手。",p=3627,r={{i=10759,n="污染者之角",c=1},{i=10757,n="污染者防护结界",c=1}}},
  [3636]={t="与圣光同在",d="亡灵天灾对联盟是一个长期的威胁，我想你应该明白这一点。最近，我们偶然发现了一些罕见的东西，你。；在贫瘠之地有一片令人恐怖的灌木林，它被称作剃刀高地。虽然那儿曾经是野猪人的家，但是很明显，它已经变成亡灵天灾的地盘，并衍生出了更加可怕的生物……这些生物都被巫妖寒冰之王亚门纳尔统治着。；愿圣光与你同在，你。终结那里的邪恶吧。",o="大主教本尼迪塔斯要你去杀死剃刀高地的寒冰之王亚门纳尔。",f=1},
  [3638]={t="保密协议",d="地精工程学追求的是高利润，以及更高的爆破性能！我们可以制作强力的炸弹和无敌的武器，你所阅读的手册中就包含这些知识。；这本手册中还包含了我们古老的保密协议。一旦你成为了地精技师，你就不能转而成为侏儒技师。；如果你愿意成为地精技师的话，请签署这份终生保密文件，然后再次和我说话。请谨慎考虑，你。",o="如果你同意成为一名地精技师，就右键点击保密协议，然后再次和加基森的尼克斯·斯普克斯宾谈一谈。",r={{i=11270,n="已签署给尼克斯的保密协议",c=1}}},
  [3639]={t="工作成果",d="作为你的指导者，我想看看你的工作成果。你是个熟练的技师，这是毫无疑问的，你。我要对你的工作进行分析，帮助你在地精工程学的光明大道上更快地前进。我需要以下物品：20颗重磅铁制炸弹、20颗实心炸弹和5只自爆绵羊——注意安全第一！；把这些东西交给我，我就可以发给你一张属于你自己的地精工程师协会会员卡，如果你想要拜访世界各地的地精工程学训练师，这张卡是必须的！",o="将20颗重磅铁制炸弹、20颗实心炸弹和5只自爆绵羊交给加基森的尼克斯·斯普克斯宾。",p=3638,r={{i=4394,n="重磅铁制炸弹",c=20},{i=10507,n="实心炸弹",c=20},{i=4384,n="自爆绵羊",c=5}}},
  [3640]={t="保密协议",d="侏儒工程学是一门可以满足我们日常生活需要的科学！我们设计的图纸让我们研制出可以控制世界的装置，你所阅读的手册中就包含这些知识。；这本手册中还包含了我们古老的保密协议。一旦你成为了侏儒技师，你就不能转而成为地精技师。；如果你愿意成为侏儒技师的话，请签署这份终生保密文件，然后再次和我说话。请谨慎考虑，你。",o="如果你同意成为一名侏儒技师，就右键点击保密协议，然后再次和铁炉堡的工匠大师欧沃斯巴克谈一谈。",r={{i=11283,n="已签署给欧沃斯巴克的保密协议",c=1}}},
  [3641]={t="工作成果",d="如果你已经准备好了要制作一些真正精彩的设备，那么你就来对地方了。看得出来，你是个熟练的技师，的那我还想看到一些你的作品。我要对你的工作进行分析，帮助你在侏儒工程学的光明大道上更快地前进。我需要以下物品：6根秘银管、1只精确瞄准镜和2个高级假人！；把这些东西交给我，你就能成为一名官方认可的侏儒技师，能够使用我们的全部设计图表了！",o="将6根秘银管、1只精确瞄准镜和2个高级假人交给铁炉堡的工匠大师欧沃斯巴克。",p=3640,r={{i=10559,n="秘银管",c=6},{i=4407,n="精确瞄准镜",c=1},{i=4392,n="高级假人",c=2}}},
  [3642]={t="保密协议",d="侏儒工程学是一门可以满足我们日常生活需要的科学！我们设计的图纸让我们研制出可以控制世界的装置，你所阅读的手册中就包含这些知识。；这本手册中还包含了我们古老的保密协议。一旦你成为了侏儒技师，你就不能转而成为地精技师。；如果你愿意成为侏儒技师的话，请签署这份终生保密文件，然后再次和我说话。请谨慎考虑，你。",o="如果你同意成为一名侏儒技师，就右键点击保密协议，然后再次和藏宝海湾的奥格索普·奥布诺提斯谈一谈。",r={{i=11282,n="已签署给奥格索普的保密协议",c=1}}},
  [3643]={t="工作成果",d="如果你已经准备好了要制作一些真正精彩的设备，那么你就来对地方了。看得出来，你是个熟练的技师，的那我还想看到一些你的作品。我要对你的工作进行分析，帮助你在侏儒工程学的光明大道上更快地前进。我需要以下物品：6根秘银管、1只精确瞄准镜和2个高级假人！；把这些东西交给我，你就能成为一名官方认可的侏儒技师，能够使用我们的全部设计图表了！",o="将6根秘银管、1只精确瞄准镜和2个高级假人交给藏宝海湾的奥格索普·奥布诺提斯。",p=3642,r={{i=10559,n="秘银管",c=6},{i=4407,n="精确瞄准镜",c=1},{i=4392,n="高级假人",c=2}}},
  [3661]={t="月神之兽？",d="枭兽是难以预测的生物，你。它们有着极端温顺的一面，如果它们重视的东西受到威胁，这些生物就会变得非常凶猛。；传说这些野兽是由艾露恩创造的，我对这种说法的真伪很感兴趣。；近来，我听说辛特兰的枭兽数量越来越多——这些凶残、原始、野蛮的家伙在辛特兰的野外四处横行。你能帮我收集一些枭兽的羽毛吗？",o="为鲁瑟兰村的艾瑞拉斯·琥珀收集15支枭兽羽毛。",r={{i=10819,n="枭兽羽毛",c=15}}},
  [3701]={t="索瑞森废墟",d="到燃烧平原的索瑞森废墟中去尽可能多地收集情报。；据说那里散布着许多神秘的上古遗物，也许你可以在那里搜寻一番，你。小心在那里保护着废墟的索瑞森的刺客们。",o="到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。",p=3702,f=1},
  [3702]={t="索瑞森废墟",d="你愿意听听黑铁矮人的简要历史吗？",o="听皇家历史学家阿克瑟努斯讲述索瑞森的历史。"},
  [3761]={t="安戈洛的泥土",d="据说安戈洛环形山一带的土壤非常肥沃，而且具有不可思议的魔法能量。塞纳里奥议会需要大量的这种土壤以进行研究，到安戈洛去帮我们收集足够的土壤吧。；有时肥沃的土壤会成堆地聚集在地表，某些野兽也可能带有这样的土壤。把它们都交给格德，它就在这附近的那一堆堆泥土旁。他脾气不错，但是别惹恼他！",o="收集20份安戈洛的泥土，把它们交给雷霆崖的格德。",r={{i=11018,n="安戈洛的泥土",c=20}}},
  [3764]={t="安戈洛的泥土",d="据说安戈洛环形山一带的土壤非常肥沃，而且具有不可思议的魔法能量。我想要知道这事的真假，到安戈洛去帮我们收集足够的土壤吧。；你可能会认为派你去做收集任务是委屈你了，我和塞纳里奥议会可不喜欢这种态度。将样本交给耶纳尔，他总躲在树后浪费时间，你只要去找那一堆堆的泥土就是了。剩下的事情都交给他办，别来找我。",o="收集20份安戈洛的泥土，把它们交给达纳苏斯的耶纳尔。",r={{i=11018,n="安戈洛的泥土",c=20}}},
  [3781]={t="晨光麦研究",d="有了这件名为常青袋的东西，我们已在来自安戈洛环形山的土壤上种植了萨伦迪斯种子。这些种子繁殖出了大片的草药。其中一种是晨光麦，我们对这种神秘的草药知之甚少，不过我打算揭开其中的奥秘。；把这个交给楼下的玛斯雷，他会给你一些种子，然后你就可以开始了。要是种子用完了的话，你就得从他那儿购买新的种子。",o="将大德鲁伊的草种购买券交给达纳苏斯城塞纳里奥区的玛斯雷·驭熊者。",p=3764,r={{i=11103,n="草种购买券",c=1}}},
  [3782]={t="晨光麦研究",d="有了这件名为常青袋的东西，我们已在来自安戈洛环形山的土壤上种植了萨伦迪斯种子。这些种子繁殖出了大片的草药。其中一种是晨光麦，我们对这种神秘的草药知之甚少，不过我打算揭开其中的奥秘。；把这个交给我的女儿巴珊娜，她会给你一些种子，然后你就可以开始了。要是种子用完了的话，你就得从她那儿购买新的种子。",o="将草种购买券交给雷霆崖的巴珊娜·符文图腾。",p=3761,r={{i=11103,n="草种购买券",c=1}}},
  [3783]={t="雪怪计划！",d="我的朋友总是不断想出天才般的点子来，我感觉我总是比不上他们……直到今天！我想到了一个好主意！如果你答应不告诉别人的话，我就和你分享这个秘密……；我要制作一个机械雪人！我的朋友看到它的时候肯定会被吓一跳，然后就会被我的技术和创意所震撼！；首先，我需要那些冰蓟雪人身上的厚雪人毛皮。你能帮帮我吗？雪人一般都在这里的东南边活动。",o="为永望镇的乌米收集10张厚雪人毛皮。",r={{i=12366,n="厚雪人毛皮",c=10}}},
  [3785]={t="晨光麦研究",d="这是你所需的与萨伦迪斯种子一同使用的常青袋，当然，你手中还必须有安戈洛的泥土样本给种子做肥料。这些东西都准备好了之后就使用常青袋，剩下的就交给它了。；当你种出足够的晨光麦之后，将它们交给我就行了。请不要打扰大德鲁伊，他事务繁忙，而且他也没必要为收集晨光麦的事情操心！",o="用一个常青袋、一包萨伦迪斯种子以及两份安戈洛的泥土来尝试种植晨光麦。；将10株晨光麦交给达纳苏斯的玛斯雷·驭熊者。",p=3781,r={{i=11040,n="晨光麦",c=10}}},
  [3786]={t="晨光麦研究",d="这是你所需的与萨伦迪斯种子一同使用的常青袋，当然，你手中还必须有安戈洛的泥土样本给种子做肥料。这些东西都准备好了之后就使用常青袋，剩下的就交给它了。；当你种出足够的晨光麦之后，将它们交给我就行了。请不要打扰大德鲁伊，他事务繁忙，而且他也没必要为收集晨光麦的事情操心！",o="用一个常青袋、一包萨伦迪斯种子以及两份安戈洛的泥土来尝试种植晨光麦。；将10株晨光麦交给雷霆崖的巴珊娜·符文图腾。",p=3782,r={{i=11040,n="晨光麦",c=10}}},
  [3791]={t="晨光麦的秘密",d="坦白说吧，你。我对达纳苏斯的大德鲁伊以塞纳里奥议会的名义、使用 议会的资源来大量生产晨光麦的原因很感兴趣——不，应该说是极度关注。我是一名研究员——研究诅咒是我的专长。我听说晨光麦在一定的条件下可以像其它草药那样用于进行诅咒。；我想了解更多的情况，因此我请求你的帮助。给我带十株晨光麦回来，我会好好报答你的。",o="将10株晨光麦交给羽月要塞的奎恩提斯。",r={{i=11040,n="晨光麦",c=10}},w={{i=11888,n="奎恩提斯的手套",c=1},{i=11889,n="铁树肩铠",c=1}},f=1},
  [3822]={t="克罗格鲁尔",d="你，我们整支小分队都被抓住了，除了我之外的所有同伴都被杀了。；他们的头领克罗格鲁尔想要把我留下来举行某种仪式。；我被绑在这个祭坛上，被那些野兽用酷刑折磨。不到一个小时，我就被活活折磨致死。那个野兽摘下了我的结婚鼻环，把它戴在了自己的手上。我从来没有见过如此无耻残暴的行为！；找到克罗格鲁尔，杀了他！把我的戒指交给萨特拉克。；另外，你，告诉他，我们会再次见面的……来世再见……",o="从克罗格鲁尔手中拿回沙妮的鼻环，把它还给卡加斯的萨特拉克。搜寻巨槌石的每一处山洞和矿井。",p=3821,r={{i=11058,n="沙妮的鼻环",c=1}},f=2},
  [3823]={t="消灭火腹食人魔",d="我们必须先发制人！；我先简单地向你介绍一下现在的状况，士兵。；燃烧平原上的火腹食人魔是黑石兽人的盟友。它们和那些邪恶的兽人一起工作，帮助守卫蕴藏着丰富矿藏的巨槌石，并保证那条补给线一直正常运作。；现在出发吧，你。削弱他们的力量然后回来向我报告。；<奥拉留斯向空中伸出手，然后作出被掐住脖子的表情。>；我要杀了你，温奇！",o="杀掉15个火腹食人魔法师、7个火腹食人魔和7个火腹蛮兵。"},
  [3824]={t="蛮王戈泰什",d="我告诉你，他们现在已经被搞得晕头转向了！我们的下一步行动将是决定性的。；干掉那个野蛮的食人魔之王戈泰什。更重要的是，你必须把他的徽记带回来，这样我就可以准备对火腹食人魔发动第三次攻击了。；你要留神，士兵，戈泰什并不在巨槌石上，而是在巨槌石西面的某座黑石兽人的建筑物中。；你的任务很简单。找到戈泰什，取走他的徽记。完成任务之后回到我这里来。；闭嘴，温奇！",o="取得戈泰什的标记。",p=3823,r={{i=11080,n="戈泰什的徽记",c=1}}},
  [3825]={t="示众扬威",d="士兵，你还有最后一件事要做。；我已经把戈泰什的徽记挂在了一支长矛上。现在你要做的就是把这支长矛带到巨槌石的山顶去，把它插在地上。这样，你就能看到那些怯懦的食人魔四散逃窜了！当你完成这个任务之后，回到我这里来，我会为你的辛勤工作而奖励你的。；<奥拉留斯看上去有些出神。>",o="把戈泰什的徽记放在巨槌石的山顶上。找一块软土堆把串着徽记的长矛插上去就可以了。",p=3824,w={{i=11867,n="狂乱护手",c=1},{i=11868,n="窒息指环",c=1}},f=1},
  [3841]={t="领养孤儿",d="噢，你好，你。很高兴再次见到你。去达纳苏斯的旅途怎么样？；你不在的这段时间里，我们取得了相当大的进展，你会为此感到高兴的。我们甚至保存了一整巢的蛋。不幸的是，我们找到这些蛋的母亲的时候，它已经死掉了。；呃，你要取一只作为宠物吗？它们很快就要孵化了，所以它们会需要一个好$G父亲:母亲;的。你认为呢？；如果你真的感兴趣的话，请带上一颗蛋，到闪光平原的赛车场去找奎恩丁。他会告诉你更多细节的。",o="与千针石林的奎恩丁谈一谈。",p=2972,r={{i=11102,n="未孵化的小精龙卵",c=1}}},
  [3842]={t="即将孵化",d="辛达尔和耶尔卡？这可太有意思了。我希望那些小精龙能意识到她们的一片好心。她们俩都相当能干。；这样看来，她们把这颗蛋作为礼物送给你了。呃，好吧，现在你应该对这颗蛋负责了。看起来它马上就要孵化了，但是我们应该确定它是健康的。；我需要两份坚韧药剂，然后用它们来施放一个小小的法术保护这颗蛋。至于其它的材料，我这里就有。",o="将2份坚韧药剂交给千针石林的奎恩丁。",p=3841,r={{i=3825,n="坚韧药剂",c=2}}},
  [3843]={t="新的生命",d="很不错，你。如果它的妈妈活着生下它的话，那它将是一只健康的宠物！；要是你正巧要去辛特兰的鹰巢山，那我建议你去找一个名叫阿格纳的矮人谈谈，他精于训练动物，可以就孵化的最终步骤对你进行指导。；但是你一定要快，你，这颗蛋很脆弱，要是没有悉心的照料，它可活不了多久。",o="带着这枚脆弱的小精龙卵去辛特兰，与阿格纳谈一谈，但是你一定要在它还有生命力的时候赶到，在蛋里的小生命夭折之前，你只有1小时的时间。",p=3842,r={{i=11471,n="脆弱的小精龙卵",c=1}}},
  [3845]={t="无人知晓的秘密",d="你把那只袋子从水中拉上了岸。如果你检查一下袋子中的东西，那么你应该可以知道它是谁的袋子。；在马绍尔营地那里有一些迷路的旅行者，也许你可以在那里发现更多的线索。",o="查看袋子里的东西，然后将它们交给物主。",p=3844,r={{i=11104,n="大指南针",c=1},{i=11105,n="卷曲的羊皮地图",c=1},{i=11106,n="狮头钥匙",c=1}}},
  [3882]={t="挖骨头",d="你也许认为我在马绍尔探险队里当挖掘工是因为我喜欢这活儿，好吧，世上可能的确有比这更糟糕的差事……但是我还真没见过。；我们本应是在恐惧小道那个鬼地方进行剑龙和双帆龙化石的挖掘工作——顺便提一句，那地名可真古怪。呃，那儿也有许多活着的恐龙！威利和霍莱坚持要研究这些东西，所以我们还是得弄些恐龙骨头来。咱们私下里说说，其实你只要从活着的恐龙身上给我取些骨头回来就行了。",o="将8根恐龙骨头交给安戈洛环形山的斯巴克·尼米尔。",r={{i=11114,n="恐龙骨头",c=8}},w={{i=11908,n="考古学家的工作靴",c=1},{i=11909,n="挖掘者的工作腰带",c=1}}},
  [3901]={t="断骨骷髅",d="你已经向我们展示了你在正常情况下的潜力，你——现在让我们来看看你在压力下的表现吧。；断骨骷髅是巫妖王手下的走狗，与你先前干掉的那些僵尸相比，它们更为强韧而凶残。去杀掉它们，再次向被遗忘者证明你的能力吧。别耽搁时间——当你完成任务后，就来找我谈谈。",o="杀掉8个断骨骷髅，然后回到丧钟镇的暗影牧师萨维斯那里。",p=364,w={{i=3274,n="麻布靴",c=1},{i=11851,n="食腐狼皮外套",c=1},{i=11852,n="漂泊者护腿",c=1}},f=2},
  [3902]={t="捡破烂",d="嘿，说你呢！要是你想实现自己的价值，那就听好了！；我们要求那些刚刚爬出坟墓的新兵转至丧钟镇，搜寻任何可以为我们所用的装备，这些装备极有可能装在成堆的箱子里。我们希望能立即招募到更多的新兵，因此，除非我们想让他们赤手空拳地上阵，否则我们就得搜寻一切可用之物！；开始工作吧，你这堆可悲的骨头！对那些不努力工作的家伙，我可是不会给予回报的。",o="在丧钟镇及临近地区搜寻6件破烂装备，把它们交给亡灵卫兵萨尔坦。",p=376,r={{i=11127,n="破烂装备",c=6}},w={{i=11848,n="粗麻腰带",c=1},{i=11849,n="锈铁护腕",c=1},{i=11850,n="夜行蝙蝠斗篷",c=1}},f=2},
  [3904]={t="米莉的葡萄",d="一伙迪菲亚盗贼趁我收割的时候闯进了北郡农场！我将这件事情报告给了北郡的卫兵，他们向我保证会尽快解决，但是……我担心我的那些葡萄！即使迪菲亚盗贼不去偷盗葡萄，恐怕那些卫兵在剿灭盗贼的过程中也会踩坏它们。；你一定得帮助我！我把大部分的葡萄都装在箱子里了，但是我把它们留在了东南边的农场。；把那些箱子给我拿回来吧！救救我的收成！",o="收集8箱米莉的葡萄，把它们交给北郡修道院的米莉·奥斯沃斯。",p=3903,r={{i=11119,n="米莉的葡萄",c=8}}},
  [3905]={t="葡萄出货单",d="我的作物完好无损，请将这张葡萄出货单交给尼尔斯修士。他在北郡经营一家销售食品和饮料的商店，我敢说当他知道他可以得到一批新鲜葡萄时一定会很高兴的。；你可以在修道院的钟塔上找到尼尔斯修士，他喜欢在那儿饮酒。",o="将葡萄出货单交给北郡修道院的尼尔斯修士。",p=3904,r={{i=11125,n="葡萄出货单",c=1}},w={{i=11475,n="酒渍披风",c=1},{i=2690,n="铁锁腰带",c=1}},f=1},
  [3906]={t="不和谐的烈焰",d="部落的长老感觉到元素中的一种扰动。黑铁矮人召唤出了一个肮脏的灵魂，这个灵魂将用冲天的大火完全毁灭这个世界。我们必须调查这种不和谐的火焰的来源。；到黑石山脉去，穿过火焰裂口，进入采石场。你应该可以在那里找到火焰之王——征服者派隆。；解决这个造成扰动的源泉，然后向我回报。",o="到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。"},
  [3907]={t="不和谐的火焰",d="我可以嗅出空气中的邪恶气息，你。在黑石山脉的深处依然隐藏着另一个控制着这种邪恶气息的生物。；风和大地都在哭喊着它的名字：伊森迪奥斯……但是有人……有什么东西……控制这这个生物，它只是一个傀儡。；找到它，找到它背后的主使者藏匿的地方。当你收集到这些信息之后就立刻回来向我报告。",o="进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。",p=3906,r={{i=11126,n="库尔尼亚石板",c=1}},w={{i=12113,n="阳焰斗篷",c=1},{i=12114,n="夜暮手套",c=1},{i=12112,n="地穴恶魔护腕",c=1},{i=12115,n="坚定束腰",c=1}},f=2},
  [3908]={t="无人知晓的秘密",d="你看，我已经对自己为什么会在这里完全没有概念了。没有人知道——这对所有的人来说都是个秘密！我什么都记不起来了……；不过……你带给我的东西却让我想起了什么……；我的剑！我想起来了，原本我是要去将其加强的，但是我不知道我为什么要那么做。很抱歉我不能告诉你更多的信息，因为我确实什么都记不起来了！；不管怎么样，我知道你应该把剑带到什么地方去——把它交给冬泉谷的多诺瓦·雪山。你可以在温泉旁边找到她，她会用温泉的泉水来给剑中注入力量。",o="把林克的剑交给冬泉谷的多诺瓦·雪山。",p=3845,r={{i=11133,n="林克的训练之剑",c=1}}},
  [3909]={t="视灵药剂",d="什么，你说什么？林克……失忆了？；哦，我明白了……他失去了自己的记忆……；好吧，这是他的剑。但是它并不完整。我知道有人可以把它变得完整，但是……和他说话也许会很困难。；听着，我知道有人可以帮助你，现在我没法把一切都给你解释清楚，总之你一定要得到视灵药剂。我所知道的唯一一个可以帮你的人就是格雷甘·山酒了。他行踪不定，但是我知道他眼下正在菲拉斯一带活动。",o="去菲拉斯找格雷甘·山酒。从他那里问到获取视灵药剂的方法，然后向冬泉谷的多诺瓦·雪山复命。",p=3908,r={{i=11243,n="视灵药剂",c=1}}},
  [3913]={t="寻找墓碑",d="如果你回到墓地，你，你会在那里找到一块墓碑……那不是一块普通的墓碑，它非常显眼。秘密就隐藏在其中。；推动墓碑，然后你就可以发现那些秘密……",o="复活，然后寻找加里杨让你去找的那块墓碑。",p=3912,r={{i=11136,n="林克的淬火之剑",c=1}}},
  [3914]={t="林克的剑",d="一阵强光闪过之后，你再次捡起了那把剑。它已经完全变成另一种样子了！",o="把林克的强化之剑交给安戈洛尔环形山的林克。",p=3913,r={{i=11162,n="林克的强化之剑",c=1}}},
  [3921]={t="维妮·布特巴克",d="我想我可能已经把主动式负载平衡器给弄坏了。这可不太妙，因为我已经对安德麦的一些同伴谈及它了，而且他们对此非常感兴趣。我们必须想办法修好它！；把这个坏掉的主动式负载平衡器交给维妮·布特巴克，她就在贫瘠之地和灰谷之间的部落前哨站里。她非常聪明而且好奇，如果你将主动式负载平衡器给她看的话，我敢打赌她会欣然帮你修理它。",o="将损坏的主动式负载平衡器交给维妮·布特巴克。",p=902,r={{i=11142,n="损坏的主动式负载平衡器",c=1}}},
  [3922]={t="高强度齿轮",d="我想修好这个主动式负载平衡器，但是，我需要一些材料。我用光了17.5规格的高强度齿轮，而我需要很多这样的东西才能继续工作。；要弄到这种齿轮的话，最近的地方是东面的淤泥沼泽。风险投资公司的家伙们通常会把齿轮放在他们的工具桶里。到淤泥沼泽去，检查一下你在那里找到的工具桶，当你搜集了足够的高强度齿轮后再回到我这里来。",o="把15个高强度齿轮交给贫瘠之地的维妮·布特巴克。",p=3921,r={{i=11143,n="高强度齿轮",c=15}}},
  [3923]={t="雷里·格里斯高布",d="好吧，我失败了。我在主动式负载平衡器上安装了更多的仪表来测量它的结构完整度，读出来的数据表明现在的完整度很低。我也许需要加些转盘或者一两根杠杆来继续尝试，但是……没准我把它会搞得更糟。；你应该把主动式负载平衡器交给雷里·格里斯高布。他过去是为风险投资公司干活的——如果有人知道该怎么修理这玩意的话，那一定就是雷里了。；你可以在奥格瑞玛荣誉谷中的诺格机械店找到他。",o="把破碎的主动式负载平衡器交给奥格瑞玛的雷里·格里斯高布。",p=3922,r={{i=11146,n="破碎的主动式负载平衡器",c=1}}},
  [3924]={t="主动式负载平衡器说明书",d="我想我可以修复主动式负载平衡器，但首先我需要一本用户手册。当我在风险投资公司干活的时候，我有个名叫考博普拉格的对手……他会把主动式负载平衡器的秘密告诉那些他信任的同党。不过我不是他的亲信……；考博普拉格应该在贫瘠之地东北部的石矿洞里。从他那里把手册拿过来，如果他把其中的一部分给了其它人的话，你也要把它们一起拿来。",o="把主动式负载平衡器说明书交给奥格瑞玛的雷里·格里斯高布。",p=3923,r={{i=11149,n="主动式负载平衡器说明书",c=1}},w={{i=11855,n="双头扳手",c=1},{i=11854,n="主动式负载平衡器螺丝刀",c=1}},f=2},
  [3961]={t="林克的冒险",d="真难想象林克来这里居然是为了帮助我们除掉火焰使者……他看上去是那么普通的一个侏儒，但是我确实感觉到他和别的侏儒有些不同，他居然对我的实验或者小装置一点都不感兴趣！他一定拥有一颗真正的战士之心。；把图腾交给他，看看这是否能够帮助唤起他的记忆。",o="把亚奎门塔斯的银图腾交给马绍尔营地里的林克。",p=4005,r={{i=11522,n="亚奎门塔斯的银图腾",c=1}}},
  [3962]={t="结伴而行",d="你，我终于想起来了……我来这里是要和火焰使者作战的。我经历了一段漫长的旅途，原本最重要的目标就是它。；但是我不再是英雄了……你才是。迄今为止你已经做了那么多——应该由你来完成这个任务，而不是我。；去找到火焰使者并打败它吧。它守护着一个被称作金色火焰的神器，这个神器的力量比我所见过的任何东西都要强大，如果它落在邪恶势力的手中，那会是一件非常危险的事情。；你应该找些同伴一起去完成这个任务——独自行动是很危险的。",o="到马绍尔营地南边的火羽山去。；找到火焰使者，并使用图腾除掉它的防护光环。在击败它之后从洞中取得金色火焰。",p=3961,r={{i=11179,n="金色火焰",c=1},{i=11522,n="亚奎门塔斯的银图腾",c=1}},w={{i=11902,n="林克之剑",c=1},{i=11904,n="亚奎门塔斯之魂",c=1}}},
  [3982]={t="出了什么事？",d="我受萨尔的差遣来到这里，你真的认为这些小丑可以抓住我吗？我是主动送上门的，这样我才能从他们这里收集情报。；<哥沙克压低了声音。>；黑铁皇帝索瑞森绑架了铁炉堡的公主，她就被关押在这座城市里！我敢打赌，当老麦格尼听到这个消息时，他的心脏大概会停止跳动的。；<哥沙克大笑了起来。>；嘘～～！你听到了吗？卫队来了！准备战斗！",o="保护哥沙克。",p=3981},
  [4001]={t="出了什么事？",d="到当前为止，我与大厅房间中的矮人卡兰之间的交流都很有限。但是我已经努力使他相信我——更准确地说，我们——对他没有恶意。；过去跟他谈谈吧，尽可能多地收集有关公主和绑架他的那些家伙的情报，然后将这些情报反馈给酋长。；萨尔不想让公主受到伤害，而是准备了某个重要的计划，其中包括使公主安全地返回铁炉堡。卡兰已对此了如指掌……快去吧！",o="与卡兰·巨锤谈一谈，收集关于绑架公主铁炉堡公主茉艾拉·铜须这一事件的情报。将情报反馈给奥格瑞玛城里的萨尔。；哥沙克提到过卡兰被关在附近的某个牢房中。",p=3982},
  [4003]={t="拯救公主",d="这次行动是针对黑铁矮人的，如果我们成功了，那么他们的整个王国都将遭到一次巨大的冲击。；茉艾拉公主正处于索瑞森大帝的控制之下。要想救她的话，你就必须杀了索瑞森。千万小心，你的任务非常危险，因为公主可能会在索瑞森的控制下向你发起攻击。；不要伤害她！",o="杀掉达格兰·索瑞森大帝，然后将铁炉堡公主茉艾拉·铜须从他的邪恶诅咒中拯救出来。",p=4002},
  [4004]={t="The Princess Saved?",o="Return to Thrall!；",p=4003,w={{i=12544,n="萨尔的决心",c=1},{i=12545,n="奥格瑞玛之眼",c=1}},f=2},
  [4005]={t="亚奎门塔斯",d="把所有你收集的东西和这本书都带到塔纳利斯去。在落帆海湾寻找一个石头法阵，最东边的半岛应该就是秘密所在……；当你身处石阵之中的时候，诵读阿奎尔之书，你将召唤出一个可以将你所收集的东西转化为一支与火焰使者作战所必需的图腾。；亚奎门塔斯被人唤醒当然不会高兴，但是你要记住，在它转换图腾的这段时间里，你一定要待在石阵里面。",o="把阿奎尔之书、银爪和铁树之心带到塔纳利斯去。；使用这本书召唤亚奎门塔斯。；在图腾完成之后，把它交给马绍尔营地的科琳。",p=4084,r={{i=11522,n="亚奎门塔斯的银图腾",c=1}}},
  [4023]={t="烈焰精华",d="你找到那些黑龙了？那就向我证明你的价值吧，$c。",o="向塞勒斯·萨雷芬图斯证明你的价值。；你感觉到塞勒斯似乎对你不屑一顾。",r={{i=10575,n="黑龙皮",c=1}}},
  [4024]={t="烈焰精华",d="我要为火焰之山中的炙热烈焰歌唱，我要让黑石山的熔岩瀑布贯穿我的身体。我所渴求的就是那种精华，那种炙焰的感觉。；在黑石深渊住着一个纯火焰铸成的怪物：贝尔加，他是从拉格纳罗斯的火焰中诞生的。杀掉贝尔加，然后从他燃烧的身体中取出他心中的烈焰。；使用黑龙皮就可以安全地萃取这种烈焰。；大功告成后，你会获得奖励的。",o="到黑石深渊去杀掉贝尔加。；你只知道这个巨型怪物住在黑石深渊的最深处。记住你要使用特殊的黑龙皮从贝尔加的尸体上采集烈焰精华。；将你采集到的烈焰精华交给塞勒斯·萨雷芬图斯。",p=4023,r={{i=11230,n="包起来的烈焰精华",c=1}},w={{i=12066,n="页岩斗篷",c=1},{i=12082,n="龙皮肩铠",c=1},{i=12083,n="火山腰带",c=1}}},
  [4061]={t="机器的崛起",d="在我们最初进攻灼热峡谷的时候就已经见识过了那些机器。在进行了更深入的调查之后，我们发现它们是从燃烧平原运送过来的——当然也可能是从黑石深渊里运出来的。这就是我们需要你帮忙的原因，你。；你的第一件任务是到燃烧平原去，从那里的石头傀儡身上收集一些元素碎片。一旦你收集到足够数量的碎片之后就回到我这里来，我会鉴定它们的来源。",o="到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。；塞朵拉曾经说过，那里的机械傀儡和元素生物是这种碎片的主要来源。",r={{i=11266,n="断裂的元素碎片",c=10}}},
  [4062]={t="机器的崛起",d="G.L.A.；那些碎片上刻着这样的文字。在这些大写字母下面有一个军衔标志。你在燃烧平原所摧毁的机器的等级是四，我相信这是个比较低的军衔。；把这块碎片样品交给东边一处营地里的鲁特维尔·沃拉图斯吧，他是个着名的元素学者，应该能对我们的研究有所帮助。",o="将元素碎片样本交给鲁特维尔·沃拉图斯。；塞朵拉说鲁特维尔就在东边的一处营地里。",p=4061,r={{i=11267,n="元素碎片样本",c=1}}},
  [4063]={t="机器的崛起",d="不可能是阿格曼奇！因为阿格曼奇在十年前就被杀掉了。什么？我为什么那么肯定？因为我就是杀死他的人之一。；他是个卑鄙的矮人，为了自己的邪恶计划而逼我为他工作。看来坏蛋总有办法逃脱正义的惩罚。；如果这一切都是阿格曼奇干的，那他就必须死！你去帮我弄些他最近制造的傀儡人的样品来吧，如果有合适的样品，我们也许就可以阻止他了。那些东西在黑石深渊里守护着阿格曼奇。",o="找到并杀掉傀儡统帅阿格曼奇，将他的徽记交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。",p=4062,r={{i=11268,n="阿格曼奇的徽记",c=1},{i=11269,n="完整的元素核心",c=10}},w={{i=12109,n="蓝月披肩",c=1},{i=12110,n="雨法师斗篷",c=1},{i=12108,n="黑陶鳞片护甲",c=1},{i=12111,n="熔岩护手",c=1}},f=2},
  [4081]={t="格杀勿论：黑铁矮人",d="根据卡加斯探险队的指挥官高图斯大人的命令：；黑石深渊中所有安格弗将军麾下的部队必须全部消灭。；安格弗的下属都是杀人不眨眼的暴徒，正是他们杀害了卡加斯探险队109分队的成员。遇到这群穷凶极恶的歹徒的时候要特别小心。；任何能消灭黑石深渊安格弗将军麾下部队的勇士都将得到奖励。",o="到黑石深渊去消灭那些邪恶的侵略者！；军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。"},
  [4084]={t="银爪铁心",d="我不知道你说的那个人是谁，你。；但是请不要担心，如果你的朋友原本打算大老远地来找我的话，我应该可以想象到他需要什么。；在安戈洛尔环形山的中心地带有一个极端邪恶的恶魔，它以一个名叫火焰使者的元素生物的形象出现……它被一层任何人都无法驱散的光环保护着……；没有人可以驱散……除非有足够的力量。我可以教你如何获得这样的力量，你。；首先按我说的去做，从费伍德森林的生物身上收集11个银爪和1个铁树之心，然后回来找我。",o="为费伍德森林的艾瑞丹·蓝风收集11只银爪和1颗铁树之心。",p=3942,r={{i=11172,n="银爪",c=11},{i=11173,n="铁木之心",c=1}}},
  [4101]={t="净化费伍德",d="植物给与费伍德森林以生命，然而即使是它们也遭受了腐化和堕落的痛苦。我知道净化它们的方法，但是我不会把这种方法告诉一个我不熟识或者不能信任的$r。向我证明你真的能帮助塞纳里奥议会！；这里的北面有一个铁木山洞，那里的曲木元素已经无法挽救了。我要你帮我从它们身上取得树汁，这些树汁被称作血琥珀。有了它们，我就可以研究拯救其它生命的办法了。",o="收集15颗血琥珀，把它们交给费伍德森林的阿拉珊蒂丝·银空。",r={{i=11503,n="血琥珀",c=15}}},
  [4102]={t="净化费伍德",d="植物给与费伍德森林以生命，然而即使是它们也遭受了腐化和堕落的痛苦。我知道净化它们的方法，但是我不会把这种方法告诉一个我不熟识或者不能信任的$r。向我证明你真的能帮助塞纳里奥议会！；这里的北面有一个铁木山洞，那里的曲木元素已经无法挽救了。我要你帮我从它们身上取得树汁，这些树汁被称作血琥珀。有了它们，我就可以研究拯救其它生命的办法了。",o="收集15颗血琥珀，把它们交给费伍德森林的梅贝丝·河风。",r={{i=11503,n="血琥珀",c=15}}},
  [4121]={t="押送囚徒",d="你真的以为可以把我押出去吗？你难道以为你能穿越戒备森严的黑石要塞，而且还能神不知鬼不觉地带走一个对他们来说如此重要的人吗？；你死定了！",o="押送你的囚犯格拉克·洛克鲁布。穿过燃烧平原和黑石山脉，一直走到灼热峡谷。；雷克斯洛特曾经告诉过你，他会让他的人等在黑石山脉的另外一边准备接收格拉克。；另外，你还要把瑟银镣铐一并还给雷克斯洛特。",p=4122,r={{i=11286,n="瑟银镣铐",c=1}}},
  [4126]={t="霍尔雷·黑须",d="在万恶的霍尔雷·黑须的带领下，那些黑铁矮人偷了我们的雷霆啤酒的配方，那些混蛋！他们不配得到如此美味的佳酿！；你，我有个艰巨的任务要交给你。去燃烧平原的黑石深渊，摧毁找到的所有装有雷霆啤酒的桶，然后把雷霆啤酒的配方带回来！；求求你了，你一定要把配方带回来，即使要把黑石深渊翻个底朝天你也一定要找到它。",o="把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。",r={{i=11312,n="遗失的雷酒秘方",c=1}},w={{i=11964,n="迅捷木槌",c=1},{i=12000,n="叉刃巨斧",c=1}},f=1},
  [4127]={t="船只的残骸",d="你的手沿着泥浆滑过，手指碰到了一把刀柄。它看起来护理得不错，而且肯定是曾经乘坐过这艘船的人把它给弄丢了。这可能和失踪的信使有关。；你抓住这把刀，想起羽月要塞的基恩诺·火花要你把任何能找到的线索都报告给他。然而，你有一种感觉，在水中并不是只有你一个人……",o="回到羽月要塞，给基恩诺·火花看看你找到的这把被丢弃的小刀。",p=4125,r={{i=11462,n="被丢弃的小刀",c=1}}},
  [4129]={t="奎恩提斯的技艺",d="要塞里有一个名叫奎恩提斯的德鲁伊，他有一些……非同寻常的技艺，比如心灵占卜术——通过触摸某件物品揭示与其关联的历史。不要问我他是怎么做到的，我认为那是一种我不懂也不愿去弄懂的魔法。然而我确实知道两件事：首先，那把戏的效果确实不错；其次，他还欠着我的债。；把小刀交给小树屋里的奎恩提斯，替我告诉他……如果他把他的本事用在那把刀子上的话，他跟我打牌时欠下的债务就一笔勾销。",o="把被丢弃的小刀交给羽月要塞的奎恩提斯。",p=4127,r={{i=11462,n="被丢弃的小刀",c=1}}},
  [4132]={t="行动：杀死安格弗将军",d="迄今为止你一直表现得很好，你。现在你应该去完成你的最后一个任务了。；黑铁矮人中的安格弗将军负责策划了对K.E.F.109师的攻击，并残杀我们的无数士兵——正义必须得到伸张！；这无疑是一个极端艰难的任务，但是成功之后，你也会获得丰厚的奖励。",o="到黑石深渊去杀掉安格弗将军！当任务完成之后向军官高图斯复命。",p=4121,f=2},
  [4134]={t="遗失的雷酒秘方",d="有传言说黑铁矮人霍尔雷·黑须偷到了一种酒的配方。这种被称作雷霆啤酒的饮料会使饮用者获得无穷的力量和勇气。我们希望能研究一下这种饮料。也许我们可以开发它的其它功能……能够帮助我们被遗忘者达成目标的功能。；我说了被遗忘者的目标？我的意思是……整个部落的目标，我当然是这个意思！；到黑石深渊去找到雷霆啤酒的配方，把它给我带回来。",o="把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。",r={{i=11312,n="遗失的雷酒秘方",c=1}},w={{i=11964,n="迅捷木槌",c=1},{i=12000,n="叉刃巨斧",c=1}},f=2},
  [4136]={t="雷布里·斯库比格特",d="我的兄弟雷布里就是我们系列的耻辱，他拿走了我们所有的钱，然后挥霍一空。；藏宝海湾的大财主里维加兹刚刚开始悬赏雷布里的徽记，这对他来说可能有些糟糕，但我简直无法形容斯库比格特系列在得知这个消息之后有多高兴了！我们的小雷布里终于有点价值了！；但是现在他躲在黑石深渊的深处。请你帮忙找到他，然后把他带到我这里来！；如果他不愿意来的话，那么也好……至少把他的徽记给我带来。",o="把雷布里的徽记交给燃烧平原的尤卡·斯库比格特。",r={{i=11313,n="雷布里的徽记",c=1}},w={{i=11865,n="怨恨之靴",c=1},{i=11963,n="忏悔肩铠",c=1},{i=12049,n="钢条护甲",c=1}}},
  [4141]={t="穆尔金和拉瑞安",d="看见那里的拉瑞安了吗？就是他的错导致我们不得不待在这里！；我告诉过他我们走错路了，但是他会听我的吗？你能相信他居然不和我说话吗？好吧，除非他改变主意，否则我们就准备看场好戏吧。；你注意到周围那些像植物一样的生物了吗？它们确实很麻烦，但是我认为只要经过正确的训练，我就可以让它们听命于我。；首先，我需要一些样品来进行研究。你可不可以帮我收集一些呢？",o="收集15朵血瓣花，然后向穆尔金回复。",r={{i=11316,n="血瓣花",c=15}}},
  [4142]={t="造访格雷甘",d="我不能完全确定这是由什么构成的，你。这些植物……好像具有一些最简单的智能。；虽然我并不是这方面的专家。但是我知道有人一定知道答案！；到菲拉斯去找我的一个名叫格雷甘·山酒的朋友，他是这方面的专家。；我敢肯定格雷甘能帮我们，你应该可以在菲拉斯的野外找到他，他可不是那种喜欢生活在大城市里的家伙。",o="把血瓣花交给菲拉斯的格雷甘·山酒。",p=4141,r={{i=11316,n="血瓣花",c=1}}},
  [4143]={t="邪恶之雾",d="我跟你说实话吧，你，在我的旅途生涯中，我从来没有看见过这样的植物。也许我应该去一下环形山……；不管怎么样，我想我知道穆尔金正在找什么东西——阿塔莱之雾。那是种恐怖的东西，而且非常难找，但是穆尔金需要这种材料来控制那些小怪兽。；你应该去悲伤沼泽里的那座沉没的神庙，那里的潜伏者、黑暗虫和泥浆怪身上都有阿塔莱之雾。祝你好运，你！",o="收集5份阿塔莱之雾的样本，然后向安戈洛环形山的穆尔金复命。",p=4142,r={{i=11318,n="阿塔莱之雾",c=5}}},
  [4145]={t="拉瑞安和穆尔金",d="看到那边的穆尔金了吗？就是他的错使我们迷路了！；我知道正确的路，但是他坚持说他知道一条捷径，然后我们就到了这里！；更糟的是，现在他还不断用他那些疯狂的植物来烦我。我很生气，所以我原本打算不和他说话了，但是这些该死的植物实在是太多，我没有足够的能力来清除它们。；那么，首先让我们来减少这些东西的数量吧，去帮我干掉一些血瓣花鞭笞者和血瓣花捕兽者。",o="为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者和5个血瓣花捕兽者。"},
  [4146]={t="除草器的燃料",d="你运气真不错，你！在玛尔冯离开之后，我一直都在进行一些实验，其中的一项就是研究一种专杀除草器。只要进行一些调整，它就可以帮助你轻松地除掉那些血瓣花。；我可以给你一部这种除草器的样品，但是你仍然得自行收集所需的燃料。你可以在沉没的神庙找到你要的阿塔莱之雾，那里的潜伏者、黑暗虫和泥浆怪身上都有这种东西。",o="收集5份阿塔莱之雾的样本，然后将它们送到马绍尔营地的拉瑞安那里。",p=4147,r={{i=11319,n="空除草器",c=1},{i=11318,n="阿塔莱之雾",c=5}}},
  [4182]={t="黑龙的威胁",d="燃烧平原上永远充满了争端。；看看这个地方！我们不知道这些建筑到底是怎么回事，但是我们会永远记住，在大爆炸之前，这些地方原本都是属于赤脊山范围的。；现在的情况真是太糟糕了！我们碰到了一个问题，你。你也许已经注意到在这道山脊下徘徊的那些龙了。杀了它们，越多越好。去完成这个任务，然后我们再来谈谈别的。",o="杀掉15条黑色小龙、10条黑色龙人、4条火鳞龙人和1条黑色幼龙。"},
  [4183]={t="真正的主人",d="我们以前总是认为黑石兽人的残忍是与生俱来的。不过我们在这里找到的东西却告诉我们另一个故事。；没错，嗜血和对战斗的饥渴使他们变成了如今的样子，但是这一切的幕后主使却是那些黑龙。我们认为，正是黑龙把愤怒和敌意灌输给了他们。；把这封信交给所罗门镇长，他会知道该做什么的。；<赫林迪斯把一封信交给了你。>",o="把赫林迪斯·河角的信交给赤脊山湖畔镇的所罗门镇长。",p=4182,r={{i=11366,n="赫林迪斯·河角的信",c=1}}},
  [4184]={t="真正的主人",d="这真是个可怕的消息，你。我们的敌人竟然只是一个更强大的势力的爪牙，这让我感到更加气馁。湖畔镇不可能抵抗黑石兽人和黑龙的联手攻击。如果湖畔镇陷落了，那么下一个就是夜色镇，接下来会是哪里？闪金镇？暴风城？；你必须把这个消息告诉瓦里安·乌瑞恩国王！如果暴风城不施以援手的话，那么一切就都完了。",o="到暴风城去把所罗门的求援信交给瓦里安·乌瑞恩国王。；瓦里安·乌瑞恩国王在暴风要塞里。",p=4183,r={{i=11367,n="所罗门写给乌瑞恩的求援信",c=1}}},
  [4185]={t="真正的主人",d="所罗门描绘了一幅恐怖的画面，但是我们不可能把原本就已经捉襟见肘的兵力再分派一部分去湖畔镇。我需要确凿的证据才能采取行动。；和女伯爵卡特拉娜·普瑞斯托谈谈吧，你。她是个学识渊博的女性，并且对龙类生物很有了解。她应该可以在这件事情上帮助我们。",o="与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。",p=4184},
  [4186]={t="真正的主人",d="我现在任命你为暴风城执行代表，你。；回到湖畔镇的所罗门镇长那里，向他传达这份命令。",o="把乌瑞恩的命令交给湖畔镇的所罗门镇长。",p=4185,r={{i=11368,n="乌瑞恩的命令",c=1}}},
  [4201]={t="爱情药水",d="啊，爱情的痛苦！我亲爱的罗克诺特下士对我的魅力不来电，他将我无情地拒绝了！这真是令我发狂！；你必须帮帮我！我们魅魔对于爱情了如指掌，所以我可以配制一种药水，用它来融化包围着罗克诺特心脏的铁墙。不过我需要一些材料才能分配这种药水——一种被称作格罗姆之血的药草，一块从艾萨拉的悬崖巨人那里得到的巨大银矿，还有从安戈洛的温泉中取得的水。你可以把水放在这个小瓶里。；你，请帮助一个可怜的灵魂追求她的快乐吧！",o="将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。",r={{i=8846,n="格罗姆之血",c=4},{i=11405,n="巨型银矿",c=10},{i=11413,n="装满水的娜玛拉之瓶",c=1}},w={{i=11962,n="镣铐护腕",c=1},{i=11866,n="娜玛拉的腰带",c=1}}},
  [4224]={t="真正的主人",d="什么？你以为你是第一个被派来这里的？我们到底要损失多少士兵，暴风城才会下决心采取行动？；对于黑石兽人可能造成的威胁，我们已经有了充足的证据，但是在指挥官温德索尔元帅被俘虏之后，我们损失了许多宝贵的情报。；我们需要的是那份文件。去跟约翰谈谈吧，你。他当时和温德索尔一起遇到了黑石氏族的袭击，现在他正在北边的一个洞穴里休息。",o="和狼狈不堪的约翰。",p=4223},
  [4242]={t="Abandoned Hope",o="Give Marshal Maxwell the bad news.",p=4241,w={{i=12018,n="监督官头盔",c=1},{i=12021,n="盾甲铁靴",c=1},{i=12041,n="风剪护腿",c=1}},f=1},
  [4244]={t="找回A-Me 01",d="你仔细看了看,发现有一块面板被打开了。在配线下面清楚地写着一行字，“更换秘银外壳，关闭电源之后再重新打开。”；更换面板之后，你不禁觉得没理由这么容易就能修好A-Me 01，并让她回到马绍尔营地附近的卡尔纳·雷塔维身边。；只有先试试看了。",o="找到一个秘银外壳，然后回到安戈洛环形山的A-Me 01身边。",p=4243,r={{i=10561,n="秘银外壳",c=1}}},
  [4261]={t="Ancient Spirit",o="Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.",p=4442,w={{i=11873,n="灵雾斗篷",c=1},{i=11874,n="云谷衬肩",c=1}},f=1},
  [4262]={t="征服者派隆",d="前五个试图进入黑石深渊的法师几乎个个都灰头土脸地回来了，有的情况还要更糟糕。；<加琳达从地上抓了一把灰尘洒向天空。>；造成这种情况的主要原因是有一个可恶的臭虫——征服者派隆给我们带来了很多麻烦。我们必须干掉这个元素生物，然后才能顺利地进入黑石深渊！；他就守在黑石采矿场的黑石深渊入口处。",o="杀掉征服者派隆。；加琳达告诉过你，派隆守在采矿场中，也许你应该去那里找找。"},
  [4263]={t="伊森迪奥斯！",d="你确定派隆临死之前喊出了“伊森迪奥斯”这个词？；<加琳达使劲咽了口唾沫。>；传说伊森迪奥斯是拉格纳罗斯的手下！哦，我的天啊，我的天啊……我们该怎么办啊？；你认为你能再去完成一个任务吗？我现在手头没有足够的人手了，你！；如果伊森迪奥斯不断复活派隆的话，那我们的队伍永远也不要想进去了。；你必须找到伊森迪奥斯，把他干掉！",o="在黑石深渊里找到伊森迪奥斯，然后把他干掉！",p=4262,w={{i=12113,n="阳焰斗篷",c=1},{i=12114,n="夜暮手套",c=1},{i=12112,n="地穴恶魔护腕",c=1},{i=12115,n="坚定束腰",c=1}},f=1},
  [4264]={t="弄皱的便笺",d="这份便笺上满是污渍，上面的文字已经模糊不清了，但是还是能看出个大概来：；……甜蜜的讽刺……；……联盟的分崩离析……；……如果不是因为安格弗将军的努力工作，也许我们至今还找不到译码的方法……；……阿格曼奇已经差不多可以完成温德索尔便笺的破译了。；我们的主人将从深渊中归来，摧毁所有剩馀的东西……；- 达格兰·索瑞森大帝。",o="温德索尔元帅也许会对你手中的东西感兴趣。毕竟，希望还没有被完全扼杀。",p=4242,r={{i=11446,n="弄皱的便笺",c=1}}},
  [4265]={t="逃离虫巢",d="当你触及虫茧时，虫茧裂开了一个小口，里面有一个暗夜精灵，他居然还活着。虽然他处于深度昏迷中，但看起来并没有缺胳膊少腿。当你把他从虫茧中弄出来时，他惊醒了过来。；“感谢艾露恩——你救了我的命，朋友！我……我是拉斯卡尔。我被这些虫子麻痹，并被封在这只虫茧里。你能帮我逃离这儿，然后去羽月要塞报告一下我已经脱险的消息吗？我没事，但我们必须离开这儿，要快！”；看起来你已经找到了失踪的信使！",o="将拉斯卡尔安全护送到祖卡什虫巢外。；回到羽月要塞的基恩诺·火花那儿，告诉他拉斯卡尔还活着，且状况良好。",p=4135},
  [4266]={t="A Hero's Welcome",o="Speak with Shandris Feathermoon in Feathermoon Stronghold.",p=4265,w={{i=11856,n="精灵典礼之刃",c=1},{i=11857,n="修女魔棒",c=1}},f=1},
  [4282]={t="一丝希望",d="<温德索尔元帅激动地抖着手里的信。>；你知道这意味着什么吗，你？；也许他们还没有得到所有的东西！我可以确定的是，现在有两个黑铁矮人——安格弗将军和傀儡统帅阿格曼奇——正在破解我的那些情报。我相信我们是不大可能很顺利地取回我的那封信的。；希望你已经做好了战斗准备。；去找到那两个恶棍！干掉他们，然后带回我遗失的情报。",o="找回温德索尔元帅遗失的情报。；温德索尔元帅确信那些情报在安格弗将军和傀儡统帅阿格曼奇的手里。",p=4264,r={{i=11464,n="温德索尔元帅遗失的情报",c=1},{i=11465,n="温德索尔元帅遗失的情报",c=1}}},
  [4284]={t="能量水晶",d="我确定你一定已经注意过它们了，你。它们到处都是！；我在说什么？这都不知道，我当然在说水晶！；那些水晶……它们遍布在整个环形山里。大多数人都会忽视它们，但我感觉到那些水晶里一定蕴含着特殊的力量。我一直以来都在用它们进行实验，但似乎总是没有什么成果。好吧，我承认至今为止我一无所获。；这么说吧，我这里的水晶已经不多了——我想你也许能够帮我收集一些水晶回来？",o="收集红色能量水晶、蓝色能量水晶、黄色能量水晶和绿色能量水晶各7块，把它们交给马绍尔营地里的科琳。",r={{i=11186,n="红色能量水晶",c=7},{i=11188,n="黄色能量水晶",c=7},{i=11185,n="绿色能量水晶",c=7},{i=11184,n="蓝色能量水晶",c=7}}},
  [4289]={t="安戈洛的猩猩",d="这个环形山中居住着许多奇怪的生物——它们似乎比我家乡那边的生物更加高贵。我无法解释这一点，但是这块地方在呼唤大地之母。每次我看到大地之母创造的某种美丽的生物时，我都会对她肃然起敬。；如果你也希望感觉到见证这伟大功绩的幸福感，就向北方出发吧。你将在那儿遇到巨大的猩猩，这对$r的力量来说是一个挑战。把它们的皮毛交给我……证明你的力量。",o="将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。",r={{i=11478,n="安戈洛猩猩的皮",c=2},{i=11479,n="安戈洛巨猩猩的皮",c=2},{i=11480,n="安戈洛大猩猩的皮",c=2}}},
  [4290]={t="拉克维的食物",d="很久以前，我的一个兄弟从拉克维的猎物身上拿了一些肉。他那时并不知道拉克维就潜伏在丛林中看着他。拉克维跟踪了我的兄弟好几天，毁灭了他碰过的一切。我的兄弟吓坏了，最终他决定从安戈洛逃走，彻底甩开拉克维。；拉克维就在这附近杀死了他。；如果你想激怒拉克维，就去寻找它刚刚杀死的猎物，并从尸体上取一些肉。；做完这些之后，就回到我这儿来。",o="找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。",r={{i=11504,n="蛇颈龙肉块",c=1}}},
  [4291]={t="拉克维的气味",d="它居然没有来攻击你，这让我感到很惊讶。但是不要紧，我有个计划可以让那头野兽出来。；作为这块区域的领袖，拉克维有权与任何雌性暴掠龙交配——而且它确实这么做了。你可以在这里的西边找到许多暴掠龙蛋，靠近它们，这时就会有雌性暴掠龙跑出来攻击你。这些雌性暴掠龙头上有一种腺体，它所散发出的味道可以告诉雄性暴掠龙：它准备进行交配了。给我带两个这样的腺体回来。",o="将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。",p=4290,r={{i=11509,n="暴掠龙信息素",c=2}}},
  [4292]={t="拉克维的诱饵",d="计划有些复杂，因此这是最困难的部分。沿着山脚向北面走，你可以发现一条很不起眼的小道直通山中。那是我最后一次看到拉克维的地方。那里应该散落着大型野兽的残骸，所以你很容易判断自己的位置是否正确。带上这块肉，把它放在那儿。然后在肉上涂抹我配制的这种液体。如果这还不能使拉克维现身的话，我想也没什么东西能把它引诱出来了。",o="使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的徽记交给安戈洛环形山入口处的托尔瓦·寻路者。",p=4291,r={{i=11510,n="拉克维的头颅",c=1}},w={{i=11876,n="平原行者外套",c=1},{i=11882,n="引导者护腿",c=1}}},
  [4297]={t="小精龙的食物",d="小精龙是杂食动物——它们既吃肉也吃植物。要是这颗蛋即将孵化的话，我们最好有所准备。信不信由你，这些小家伙最喜欢吃生的新鲜腰肉。我始终不明白为什么，但是这也许和艾露恩的旨意有关……或许它们将成为守护者或是别的什么，谁知道呢。；我会照顾好这颗蛋，而你要负责找到一些银鬃捕猎者的肉，以便在小精龙孵化后喂食。",o="将5块银鬃捕猎者的肉交给辛特兰的阿格纳。",p=3843,r={{i=11472,n="银鬃捕猎者的肉",c=5}}},
  [4300]={t="骨刃武器",d="嗯，或许你能对碎手氏族有所帮助。没错，杰斯雷蒙肯定需要你的帮助。；在安戈洛环形山生活着许多迅猛龙，它们的利爪是致命的武器。一些迅猛龙的爪子是白色的，还有一些是象征死亡的黑色。我们碎手氏族有些……顾客……他们需要由这些爪子制成的武器。给我带来一些白色的爪子，我会好好回报你的。如果你速度够快的话，也许我可以在其它方面帮助你。",o="将8只白色暴掠龙爪交给奥格瑞玛的杰斯雷蒙。",r={{i=11477,n="白色暴掠龙爪",c=8}},w={{i=11862,n="白骨指环",c=1},{i=11863,n="白骨切割者",c=1},{i=11864,n="白骨长矛",c=1}},f=2},
  [4301]={t="强大的尤尔查",d="在你探索安戈洛的时候，我看到了一些像你这样强大的猎手可能会感兴趣的东西。其中之一就是北方的一只巨大的猩猩，它混迹在其它的猩猩中间。你去过那座猩猩洞穴，但这次，我怀疑你是否能在遭遇那只大猩猩之后活下来。；我称他为尤尔查，他是大地母亲最强大的儿子之一，关于这一点你不用怀疑。打败尤尔查，把他的毛皮交给我。如果你能做到这一点，我就会扞卫你称自己为伟大猎手的权利。",o="把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。",p=4289,r={{i=11476,n="尤尔查的毛皮",c=1}},w={{i=11906,n="野兽粉碎者",c=1},{i=11907,n="野兽斩杀者",c=1}}},
  [4322]={t="冲破牢笼！",d="你，我们要离开这里。帮助我从补给区拿回我的装备，然后再去救我的朋友。如果我们能够活着逃出去的话，那就在麦克斯韦尔元帅的营地里碰面吧。；我们可以在那里想办法来破译这条情报。如果没有我的译码戒指的话，这个工作可就不简单了。；你准备好了吗？",o="帮助温德索尔元帅拿回他的装备并救出他的朋友。当你成功之后就回去向麦克斯韦尔元帅复命。",p=4282,w={{i=12061,n="清算之刃",c=1},{i=12062,n="作战之刃",c=1}},f=1},
  [4363]={t="The Princess's Surprise",o="Return to Ironforge and speak with King Magni Bronzebeard.",p=4362,w={{i=12548,n="麦格尼的意志",c=1},{i=12543,n="铁炉堡歌唱石",c=1}},f=1},
  [4421]={t="碧火萨特",d="很少有$r到这边来……费伍德森林的堕落已经遍布各个角落，而且仍在毫无节制地污染所有事物。；作为翡翠议会的一员，我在努力治愈这片土地，但是仍然有些家伙希望它被腐化堕落。；我所说的就是居住在西南方的克斯特拉斯废墟中的碧火萨特。他们的头目是一个名叫萨瓦瑟拉斯的萨特，这些邪恶的恶魔仍在继续将疾病散布给他们遇到的一切生物。；我们必须保卫这片原本属于我们的土地。击败萨瓦瑟拉斯，消灭他的爪牙。",o="杀掉11个碧火魔仆、9个碧火巡影者、9个碧火盗贼和萨瓦瑟拉斯。任务完成之后回到费伍德森林的艾瑞丹·蓝风处复命。"},
  [4441]={t="被禁锢的古树",d="你所发现的长笛是由某个守护古树——忠心守护着暗夜精灵的树人——雕刻而成的。；萨特能使他们接触到的任何东西受到腐蚀，其中也包括那些在费伍德森林安家的古树。他们的灵魂在恶魔能量的作用下受到束缚和折磨，永远无法解脱。你找到的碧火魔符就是禁锢古树的东西。；我们必须净化长笛，你。为我从达纳苏斯的月神殿取回一瓶祝福之水吧。",o="到达纳苏斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然后回到艾瑞丹那儿。",p=939,r={{i=5646,n="祝福之水",c=1}}},
  [4449]={t="被锁起来的矮人",d="嘿！嘿，你！过来！；你要帮帮我。我正在逃避黑铁矮人的追击，我藏在这里，满以为他们就找不到我了。但那些可恶的混蛋还有魔法！他们肯定看到我藏了起来，他们很快就把门锁上，说了些什么过一阵子再回来之类的话，然后就离开了。；你要给它们的颜色瞧瞧！给那些黑铁地质学家一个教训！哦……对了，你能不能给我弄几块丝绸来做……做……呃，没什么。",o="杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。",r={{i=4306,n="丝绸",c=15}}},
  [4450]={t="塔纳利斯的账本",d="哦，你猜怎么着？我想起了一件事情。；我现在仍然被困在这里，那么你可以帮我完成一项我在塔纳利斯接受的任务吗？很简单……嗯，对于你来说是这样的。；加基森的克林科·古德斯迪尔需要一些从灼热峡谷和其它地方收集的东西。也许你可以看一下清单，然后把东西交给他……；如果你感兴趣的话，我会把他的账本从门下递给你。把账本和他需要的那些东西交给他就行了。",o="把古德斯迪尔的账本和上面所列的物品交给塔纳利斯的克林科·古德斯迪尔。",p=4449,r={{i=11727,n="古德斯迪尔的账本",c=1},{i=11725,n="水晶蜘蛛腿",c=20},{i=11724,n="延误的包裹",c=1},{i=11723,n="古德斯迪尔的长剑",c=1}},w={{i=11860,n="充能闪电魔棒",c=1},{i=11861,n="报复束带",c=1}}},
  [4491]={t="朋友的帮助",d="啊……太热了……；我正在探索这片地域，突然之间，我就热得昏了过去，我一定是中暑了。；求求你，带我回到马绍尔营地的朋友斯普拉格那里去，我想我还可以坚持到走回去……；我感觉有些不对劲，如果我又晕倒了，就用斯普拉格的水壶里给我洒点水。我希望这能有点用……",o="把林格带回马绍尔营地的斯普拉格·弗劳克身边。；如果林格晕倒了，就用斯普拉格的水壶让他恢复。",p=4492,w={{i=11910,n="珠宝缀饰腿甲",c=1},{i=11911,n="树冠护腿",c=1},{i=11913,n="土岭头盔",c=1}}},
  [4492]={t="走丢了！",d="你必须帮帮我，你！我的朋友林格前不久离开这里去探索南边的火山了，但他一直没回来。我很为他担心。；你能帮我找找他吗？带着我的水壶，如果你找到了林格，没准他正需要它呢！",o="在火羽山找到林格。",r={{i=15722,n="斯普拉格的水壶",c=1}}},
  [4496]={t="擒虫先擒王",d="我的研究表明异种蝎就像蜜蜂一样，消灭蜂房中的蜂后，其馀的就会乱作一团。我可以制造一种诱饵来让你引出异种蝎的皇后，并且打倒她。；然而在那之前，我们需要一些材料，我可不想让你冒冒失失地进入丛林。到西边安戈洛环形山的异种蝎洞穴里去，从那里的某只虫子身上弄到它的信息素腺。另外我还需要一些安戈洛的土壤样本。",o="把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。",r={{i=11837,n="格里什信息素",c=1},{i=11018,n="安戈洛的泥土",c=5}}},
  [4501]={t="当心翼手龙",d="悬赏：寻找技艺精湛的冒险者来对付安戈洛尔环形山中的翼手龙。它们的数量正在不断增加，已经威胁到了这个地区的旅行者。；请杀掉10只狂怒的翼手龙来削减它们的数量。；在完成任务之后，请向斯普拉格·弗劳克报告并换取奖励。",o="杀掉10只狂怒的翼手龙，然后向马绍尔营地的斯普拉格·弗劳克报告。",w={{i=11918,n="洞穴岩石手套",c=1},{i=11919,n="峭崖胫甲",c=1}}},
  [4503]={t="希兹尔的飞行器",d="我正在做一架飞行器！；我被困在了这里，而且不敢轻易出去。如果我走出这里的话，肯定会迷路的，但是如果使用飞行器，我就可以轻松地回到加基森去。；那么，你愿意帮助我吗？我现在只剩下机翼没有完成了，我想翼手龙和双帆龙的鳞片会是非常合适的材料。我自己是不可能去搞到这些鳞片的，但是你看上去好像有两把刷子。为什么你不帮我找找呢？",o="为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。",r={{i=11830,n="精细的双帆龙鳞片",c=8},{i=11831,n="精细的翼手龙鳞片",c=8}},w={{i=11915,n="希兹尔的遮雨板",c=1},{i=11916,n="希兹尔的口罩",c=1},{i=11917,n="希兹尔的管道清洁器",c=1}}},
  [4505]={t="腐化之井",d="有人可能会说我非常残忍……但事实上，我只不过是迫切地希望以任何可能的方法使部落能够压倒联盟。；我最近对南边的克斯特拉斯废墟中的月亮井很感兴趣，这座月亮井是由碧火萨特守护的，它曾经是那些暗夜精灵新生的象征，但如今它已遭到腐化，被用于制造更多的萨特。；我有个主意，你，我需要一份井水的样品……给我们的那些“朋友”。",o="从碧火萨特的月亮井中收集一份被腐化的水的样本，把它交给血毒哨所的温娜·哈萨德。",r={{i=12567,n="装满的小瓶",c=1}}},
  [4507]={t="捕捉皇后",d="拿着这份诱饵。在四通八达的虫巢中一定有一块水晶之类的东西，我想异种蝎就是使用它作为协调设备的。至于水晶在哪里……我建议你到虫巢中的孵化室找找看。；在那里对水晶使用诱饵，这样就可以引出异种蝎的皇后了，但是你要小心——也许会有几个守卫保护着她。干掉皇后，然后拿出她的脑子。虽然这听上去有些恶心，但是我们必须对它进行研究。祝你好运，你！",o="召唤格里什皇后，然后击败她。；把格里什皇后的大脑交给加基森的炼金师匹斯特苏格。",p=4496,r={{i=11835,n="格里什皇后的大脑",c=1}}},
  [4508]={t="临危不惧",d="我最近的研究结果表明情况相当糟糕，我们必须得通知某个能采取一些实质行动的人，因为我们不可能单独解决这件事情。；把我的最新报告交给达纳苏斯的格拉希娜·灵风吧，她还在月神殿，不是吗？她的许多朋友都是联盟的要人，你，如果我们能让他们涉及这件事情，那解决问题的希望就大增了。",o="把匹斯特苏格的安戈洛报告交给达纳苏斯的格拉希娜·灵风。",p=4507,r={{i=11844,n="匹斯特苏格的安戈洛报告",c=1}}},
  [4509]={t="临危不惧",d="我最近的研究结果表明情况相当糟糕，我们必须得通知某个能采取一些实质行动的人，因为我们不可能单独解决这件事情。；把我的最新报告交给奥格瑞玛的基尔兹宾·鼓眼，他还在暗巷区里待着，不是吗？他的许多朋友都是部落的要人，你，如果我们能让他们涉及这件事情，那解决问题的希望就大增了。",o="把匹斯特苏格的安戈洛报告交给奥格瑞玛的基尔兹宾·鼓眼。",p=4507,r={{i=11844,n="匹斯特苏格的安戈洛报告",c=1}}},
  [4510]={t="临危不惧",d="你，你对我们的帮助是无价的。等到时机成熟时，我肯定会再次请求你帮助我们去对付异种蝎。我们必须清晰地解读我们在安戈洛得到的信息，恐怕我原本假设安戈洛是异种蝎发源地的想法是错误的……看来它们还有更大规模的聚居地。；把这封信交给银行的伊迪瑞娜。她会让你从我的仓库中挑选一件东西。感谢你为我们提供的帮助，勇敢的$c。",o="把银行赠券交给达纳苏斯银行的伊迪瑞娜。",p=4508,r={{i=11843,n="银行赠券",c=1}},w={{i=11870,n="湮灭宝珠",c=1},{i=11871,n="鲨鱼肩甲",c=1},{i=11872,n="逃避胫甲",c=1}},f=1},
  [4511]={t="临危不惧",d="你，你对我们的帮助是无价的。等到时机成熟时，我肯定会再次请求你帮助我们去对付异种蝎。我们必须清晰地解读我们在安戈洛得到的信息，恐怕我原本假设安戈洛是异种蝎发源地的想法是错误的……看来它们还有更大规模的聚居地。；把这封信交给银行的卡鲁斯。他会让你从我的仓库中挑选一件东西。感谢你为我们提供的帮助，勇敢的$c。",o="把银行赠券交给奥格瑞玛银行的卡鲁斯。",p=4509,r={{i=11843,n="银行赠券",c=1}},w={{i=11870,n="湮灭宝珠",c=1},{i=11871,n="鲨鱼肩甲",c=1},{i=11872,n="逃避胫甲",c=1}},f=2},
  [4512]={t="远方的软泥怪",d="我研究最多的生物是软泥怪。我知道这听上去很奇怪，但是那种东西已经到处都是了！；不久之前，我帮助米奈希尔港的一位女士找到了她的包——那个包被软泥怪吞掉了。我也看见幽暗城皇家药剂师学会派出了他们的成员去收集软泥怪的样品。我要知道这是为什么！软泥怪究竟是从哪里来的？；我听说在费伍德森林有许多软泥怪，我需要那些软泥怪的样品来进行研究。我会给你一些容器，这样你就可以帮我收集软泥怪了。",o="将6瓶被诅咒的软泥怪样本和6瓶被污染的软泥怪样本交给铁炉堡的拉里斯·空轮。",r={{i=11947,n="被诅咒的软泥怪样本",c=6},{i=11949,n="被污染的软泥怪样本",c=6}}},
  [4513]={t="远方的软泥怪",d="我需要更多的样品，你。但是——我不知道怎么搞到那些——嗯，纯净的样品，不过什么是纯净的样品呢？我也不知道。你拿来的这些都是已经被腐化的……就好像整个费伍德森林一样。这让我意识到一个重要的问题：看来软泥怪会适应周围的环境。我需要一些未经污染的样品以证实这一点。但是哪里有呢？哪里？！；啊！你，拿着这些容器，如果你找到未被污染的软泥怪，就把它交给我。",o="将10个纯净样本瓶交给铁炉堡的拉里斯·空轮。；如果你无法找到它们的话，不妨到拉里斯那里去再打听一些线索。",p=4512,r={{i=11954,n="纯净的样本",c=10}},w={{i=12050,n="踏雾长靴",c=1},{i=12051,n="黄铜护手",c=1}},f=1},
  [4521]={t="冬泉谷的枭兽",d="冬泉谷就在费伍德森林的东北面，木候要塞的另一边。你去过那儿吗？；我听说那片区域里到处都是一种被称作枭兽的生物，这些野兽以守护着暗夜精灵的秘密而知名。；我们必须找出可能隐藏在冬泉谷里的东西。；我听说你可在道路的南边找到蓬毛枭兽，而狂怒的枭兽则可在冬泉谷的中心地区找到。清除它们，控制那片土地。",o="费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀15头狂怒的枭兽和15头蓬毛枭兽。"},
  [4542]={t="给乱风岗的紧急信件",d="勇敢的旅行者，半人马已经加强了对这个地区的攻势。乱风岗必须马上得知这个新的麻烦！到东南方的乱风岗去，找到峭壁卫兵图林·长角，把这个十万火急的消息通知给他。；多加小心，避开附近的恐怖图腾氏族……他们最近对我们有一些很奇怪的举动。",o="把紧急信件交给乱风岗的峭壁卫兵图林·长角。",r={{i=11886,n="紧急信件",c=1}}},
  [4601]={t="超级清洁器5200型！",d="这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：；：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”",o="将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。",r={{i=9308,n="脏兮兮的东西",c=1}}},
  [4602]={t="超级清洁器5200型！",d="这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：；：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”",o="将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。",r={{i=9308,n="脏兮兮的东西",c=1}}},
  [4621]={t="敬礼，舰队司令！",d="仔细听着，海狗……藏宝海湾是让我们血帆海盗处处受制的根本原因。如果你杀死舰队指挥官卡拉·海角，我们就永远不会再遇到藏宝海湾的战舰了。如果你杀死大财主里维加兹，我们就永远不用被他们的法律捆住手脚了。；如果你想要成为一个有荣誉感的舰队司令——没错，舰队司令，那么就按照我说的，去杀了他们两个。现在去吧，$g小伙子:姑娘;，当你完成了任务之后就回到我这儿来。",o="杀死藏宝海湾的舰队指挥官卡拉·海角和大财主里维加兹，然后回到荆棘谷海边的红雾号上去，向舰队指挥官菲尔拉伦复命。"},
  [4642]={t="融合软泥怪",d="这里有一些你从费伍德森林收集的软泥怪样本。把它拿到安戈洛环形山去，在那里找到一个纯净的软泥怪……最原始的品种就可以了。当你离它够近的时候，倒出容器里的软泥怪，让我们看看这两种软泥怪之间会发生什么事情。；当这个试验完成之后，把剩下来的东西交给我。我会在炼金房这里等你。",o="把一块融合的软泥怪样本交给幽暗城的化学家弗雷。",r={{i=12291,n="融合的软泥怪样本",c=1}},w={{i=15702,n="药剂师戒指",c=1},{i=15703,n="药剂师工作服",c=1}},f=2},
  [4681]={t="搁浅的巨兽",d="黑海岸地区到处都是这种搁浅在海滩上的生物。它们大多出现在海岸线上，有一些甚至出现在海水中。我想让你调查另一只最近被发现的生物，据说它的尸体躺在奥伯丁西边的海水中，在一艘沉船附近。把你发现的任何有助于研究的信息都反馈给我。；此外，在旅途中，你可能会发现其它搁浅的生物，你一定要把这些新发现也告诉我们！",o="在奥伯丁西面海水中的海龟骸骨那里取回海龟残骸，然后与奥伯丁的温尼斯·布莱葛谈一谈。",p=3524,r={{i=12289,n="海龟的残骸",c=1}},w={{i=15398,n="沙浪之靴",c=1},{i=15399,n="枯草腰带",c=1},{i=15400,n="蚌壳护腕",c=1}},f=1},
  [4701]={t="座狼之源",d="你一定见过黑石兽人控制的座狼。；有趣的是，不管我们消灭多少座狼，它们的数量总是有增无减。我的探子报告说座狼是在黑石塔里面繁殖并驯养的，那里是黑石兽人的要塞。你必须去黑石塔找到座狼的源头。找到它……然后摧毁它。；祝你好运，$n。愿塞纳留斯保佑你……",o="到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。",w={{i=15824,n="阿斯托里长袍",c=1},{i=15825,n="吊钩外套",c=1},{i=15827,n="碧鳞胸甲",c=1}},f=1},
  [4724]={t="座狼的首领",d="有些人说黑石兽人控制的座狼是由超自然的力量创造的。另一些人说其实它们并不是座狼，而是一种恶魔犬，是由一个堕落的深渊领主赐予兽人的。；事实上，真相并没有这样夸张，但是同样很吓人。哈雷肯是一头巨型母座狼。她的配偶？没有人能活着回来描述他的样子。；打击座狼的关键就在于杀掉哈雷肯……另外，你，时刻小心你的背后。",o="杀死血斧座狼的领袖，哈雷肯。",w={{i=15824,n="阿斯托里长袍",c=1},{i=15825,n="吊钩外套",c=1},{i=15827,n="碧鳞胸甲",c=1}},f=2},
  [4726]={t="雏龙精华",d="我几个星期来都在研究燃烧平原的龙类，而且我终于有所突破了！我制作了一个装置——我把它叫做“龙灵采集器900型”，它可以采集雏龙的精华！；好吧，至少我认为它可以实现这个功能。；给你，拿着这个装置，然后到燃烧平原上去采集雏龙精华。首先使用它标记雏龙，然后再杀死被标记的雏龙，这样你就可以采集雏龙精华了。；如果一切正常的话，那就太棒了！把你采集的东西带回来供我进行研究！",o="将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。",r={{i=12283,n="雏龙精华",c=8},{i=12284,n="龙灵采集器900型",c=1}}},
  [4734]={t="冷冻龙蛋",d="$n，我一直都在忙着准备我的新装置，龙蛋冷冻器！这个装置可以对黑龙蛋喷出极冷的气流……然后就把蛋冻住了！你能不能帮我测试一下？；我听说在黑石塔的高处，黑龙有个专门的地方来孵化它们的蛋。你可以在那里对它进行测试，然后告诉我效果如何！；不要担心。被冻住的蛋是不会对你造成危害的。你所要担心的只是那些没有被冻住的而已！",o="在黑石塔的孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。",r={{i=12286,n="龙蛋冷冻器初号机",c=1}}},
  [4735]={t="收集龙蛋",d="$n，我终于做好采集真正龙蛋的准备了！给你，拿着这个电动采集模块，它可以萃取龙蛋精华并使你可以很方便地运输龙蛋。回到孵化间去，用这个东西来收集龙蛋。；不要忘了把它们先冰冻起来，不然的话，在你开始收集之前龙蛋就会孵化！；当你收集到足够的龙蛋之后，就把它们交给我！",o="将电动采集模块和8颗收集到的龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。",p=4734,r={{i=12241,n="收集到的龙蛋",c=8},{i=12287,n="电动采集模块",c=1}}},
  [4740]={t="通缉：莫克迪普！",d="注意！；杀死名为“莫克迪普”的鱼人就可获得一笔赏金。这只邪恶的野兽至少杀死了一名哨兵，还涉嫌使至少两条货船在黑海岸沉没！；莫克迪普最后一次出现是在是奥伯丁以南的一个有草棚的鱼人营地中，据信它保护着那里的草棚。杀死该鱼人后请到奥伯丁的哨兵戈琳达·纳希恩处领取赏金。；奥伯丁乡村委员会",o="找到并杀死名为莫克迪普的鱼人。它守护着位于奥伯丁南部海岸的鱼人营地。；向奥伯丁的哨兵戈琳达·纳希恩报告莫克迪普的死讯。",w={{i=5315,n="林木护臂",c=1},{i=15403,n="山阴护腕",c=1},{i=15404,n="破浪束带",c=1}},f=1},
  [4741]={t="冬泉谷的枭兽",d="冬泉谷北部区域的枭兽更加凶残，我们必须在那儿继续采取主动。；猎杀冬泉谷中的月光枭兽，并探察他们居住的区域。；那里是非常危险的地区，但是我知道你可以面对这样的挑战。当你杀死十三头枭兽之后就回到我这里来。",o="费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀13头月光枭兽。",p=4521},
  [4742]={t="晋升印章",d="正如你所见的一样，这个简单的印章有三个洞。每个洞都必须用代表领导力的宝石来填满。最终，下层要塞的领主维姆萨拉克会使用黑龙的火焰来铸造这个印章。；你一定要明白，下层要塞的三个将军并不总是随身带着命令宝石，你必须在执行任务的时候务必保持谨慎。一定要完成这个任务！",o="找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。；可能携带者三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。",r={{i=12336,n="尖石宝钻",c=1},{i=12335,n="燃棘宝钻",c=1},{i=12337,n="血斧宝钻",c=1},{i=12219,n="原始晋升印章",c=1}}},
  [4743]={t="晋升印章",d="上层要塞之外的黑龙很少有能力用它们的烈焰铸造印章。维姆萨拉克是其中的一员，但是他的意志是不可动摇的。；到尘泥沼泽中的巨龙沼泽去，在那里，你可以找到一条名叫埃博斯塔夫的上古老龙。你必须击溃他的意志，你。把他击垮，然后在他虚弱的躯体上使用这颗宝珠。你有很短的一段时间来控制他的意志，然后用他所喷出的烈焰铸造印章。",o="到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。；此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！",p=4742,r={{i=12324,n="铸造好的晋升印章",c=1}}},
  [4762]={t="壁泉河",d="壁泉河的河水正在逐渐变得污浊，这污浊的河水流入薄雾海，我担心奥伯丁也会很快受到影响。我怀疑居住在上游区域的黑木熊怪是造成污染的原因，但是我觉得它们并不是一切问题的真正源头。；带上这支试管，到北面的河口去，在第一个内陆瀑布的水潭中取出一份河水的样本来——在你抬头就可以看到一座桥的那个地方取水就可以了。拿到样本后就回奥伯丁来找我。",o="到奥伯丁的北面去，沿着壁泉河到达第一个瀑布处，从瀑布下的水潭中取出一份水样。；将壁泉河水样交给奥伯丁的桑迪斯·织风。",p=4761,r={{i=12349,n="壁泉河水样",c=1}}},
  [4763]={t="黑木熊怪的堕落",d="我们已经知道熊怪的堕落与萨特有很大的关系，他们使用魔法护符控制熊怪。如果我们要尝试拯救熊怪的话，就必须击败引诱熊怪的萨特，取回他的护符！；到我们的月亮井里去，在碗里盛满水，然后从北面的熊怪营帐中取回一些食物。把水和食物混合并放在河水边的营火旁，只要熊怪吃下食物，它就会得到净化，稍等片刻，那个引诱熊怪的萨特就会出现……这时你就要出手杀掉它！",o="在空的净化碗里盛满奥伯丁月亮井的井水。；在黑木熊怪的北部营地里收集水果、坚果和谷物各一份。；将水和三种食物混合起来，放置在壁泉河附近的营火边，这样就会召来唤引诱熊怪堕落的萨特。；取回堕落护符，将它交给奥伯丁的桑迪斯·织风。",p=4762,r={{i=12355,n="堕落护符",c=1}},w={{i=15204,n="月石魔杖",c=1},{i=15202,n="自然守护者腿甲",c=1},{i=15203,n="自然风暴腿甲",c=1}},f=1},
  [4764]={t="末日扣环",d="黑石塔高处有一座大厅，它曾被称为财富大厅。黑铁矮人将他们的遗物、战利品以及艺术品存放在那里。；那是很久以前的事儿了。据说大厅已经塌陷，现在用于……较为普通的用途。但是我相信里面可能仍藏有一些古代矮人的遗物。；其中一件是末日扣环，那上面镶有罕见的宝石，据说任何矮人看到它都会感动得潸然泪下。；那个扣环，你，就是你的目标。",o="将末日扣环交给燃烧平原的玛亚拉·布莱特文。",r={{i=12352,n="末日扣环",c=1}}},
  [4765]={t="瑞治维尔的箱子",d="我已经把末日扣环放入一只箱子，便于运送到暴风城。你，你帮了我的大忙，不过我能请你再帮我最后一个忙吗？；把这只箱子交给雷明顿·瑞治维尔伯爵，你可以在暴风城里找到他。我敢说他看到这东西之后会非常高兴的。",o="将瑞治维尔的箱子交给暴风城中暴风要塞的雷明顿·瑞治维尔。",p=4764,r={{i=12437,n="瑞治维尔的箱子",c=1}},w={{i=15861,n="迅捷皮靴",c=1},{i=15860,n="瞬击护臂",c=1}},f=1},
  [4768]={t="黑暗石板",d="很久以前就已经去世了的矮人乌赫尔德·黑石将他的着作写在了一块黑暗石板上。虽然他是一个技艺高超的炼金师，但却被同时代的人当成精神病患者，他的研究成果也从未得到重视。；不过他却把那些宝贵的知识刻在了石板上，而且我相信这块石板就在黑石塔中，在一个以前被称作幸运大厅的地方。我不知道现在那里叫什么，因为几乎没人可以进入黑石塔后再活着出来。；不过，如果你愿意勇敢地挑战那里的危险并带回黑暗石板，我保证会给你丰厚的奖赏。",o="将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。",r={{i=12358,n="黑暗石板",c=1}},w={{i=15861,n="迅捷皮靴",c=1},{i=15860,n="瞬击护臂",c=1}},f=2},
  [4771]={t="黎明先锋",d="我已经将黎明先锋放到你拿来的那个装龙蛋的容器里了。你的任务是把它带到通灵学院去。；亡灵法师维克图斯在那儿向一群天灾军团的学者传授知识……把黎明先锋放在名叫观察室的房间里,它会自动攻击房间里面的亡灵，如果运气好的话，它就能一举毁掉他们！；这样一来，杀死维克图斯就不是问题了。你明白了吗？",o="将黎明先锋放在通灵学院的观察室里。打败维克图斯，然后回到贝蒂娜·比格辛克那里去。",p=5531,w={{i=15853,n="断风者",c=1},{i=15854,n="舞动之藤",c=1}}},
  [4781]={t="魔化金线血袍",d="你的下一个任务和第一个任务同样简单，但是你必须去寻求他人的帮助。；我的披风需要一些金线作为装饰，但是要获得金线并不容易，很少有人知道如何制作金线。幸运地是，有个忠于我们的地精知道金线的制作工艺，并且愿意帮助那些有前途的$c。；把一块金锭交给藏宝海湾的希兹克·古斯提，他是个高明的裁缝，而且他会很乐意为你纺织金线的。金锭得由经验丰富的矿工熔炼出来，因此你必须寻求某个矿工的帮助。",o="将一块金锭交给荆棘谷的希兹克·古斯提。",p=1796,r={{i=3577,n="金锭",c=1}}},
  [4783]={t="魔化金线血袍",d="下一件必需的材料只有在石爪山西面的凄凉之地才能找到。；在大灾变之后，这片区域仍处于混乱之中。你的力量和智慧都将在此得到考验——你将面对满怀仇恨的生物，以及可怕的燃烧军团。；到凄凉之地的东北部去寻找怨怒萨特，取回它们的血。然后从玛诺洛克集会所的次级地狱火身上弄到一块次级地狱火石。；我们将在制作披风的过程中用到这两种东西。",o="将10瓶怨怒萨特之血和1块次级地狱火石交给贫瘠之地的梅纳拉·沃伦德。",p=4782,r={{i=6989,n="怨怒萨特之血",c=10},{i=6990,n="次级地狱火石",c=1}}},
  [4784]={t="魔化金线血袍",d="现在我只需要三件东西就可以完成你的披风了。；第一件是希兹克正在纺织的优质金线，你要回一趟藏宝海湾，把金线拿回来。；第二件是阿拉希高地的火元素身上的闷烧煤，这东西我要两块，如果我没记错的话，你可以在那个地区西部的索拉丁之墙附近找到它们。；最后一件是由你自己制造的一块灵魂碎片。；当你收集到所有的物品之后，就回到这座塔里来，我将为你完成披风。",o="将一些优质金线、2块闷烧煤和一块灵魂碎片交给贫瘠之地的梅纳拉·沃伦德。",p=4783,r={{i=12293,n="优质金线",c=1},{i=6991,n="闷烧煤",c=2},{i=6265,n="灵魂碎片",c=1}}},
  [4786]={t="完成金线血袍",d="稍等一下，我现在就为你织好披风。这需要一些时间，可别走得太远了。",o="等待梅纳拉·沃伦德织好披风，然后跟她谈一谈。",p=4784},
  [4787]={t="远古之卵",d="摩沙鲁的预言提到了一枚远古之卵。当巨魔建造的强大帝国还无人能敌时，那枚卵就已经存在了，它具有控制哈卡的灵魂精华的力量。也许它就是能使我们的世界免受邪恶侵扰的唯一希望。；把这枚远古之卵交给我，你。据说它被深藏在辛特兰地区的巨魔城市辛萨罗，就在城市最顶端的大广场后面的洞穴中。",o="将远古之卵交给塔纳利斯的叶基亚。",p=3527,r={{i=12402,n="远古之卵",c=1}}},
  [4788]={t="最后的石板",d="在我研究摩沙鲁的第三块和第四块石板的同时，你必须找到第五块和第六块！这并不容易，因为它们在黑石塔的燃棘巨魔手中。黑石塔位于燃烧平原和灼热峡谷之间，那是一座到处都是岩浆和火焰的黑色山脉。；祝你好运，你。黑石塔可不是个观光的去处……",o="将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。",p=5065,r={{i=12740,n="第五块摩沙鲁石板",c=1},{i=12741,n="第六块摩沙鲁石板",c=1}}},
  [4808]={t="菲诺克",d="我还有一件事要请你帮忙。；我对你收集的那些精华进行了研究，结果表明冷冻并运输龙蛋是有可能实现的。我想测试一下这个理论，但是首先我需要一些特别设计的零件。我的同事菲诺克可以制作我需要的东西。；现在，请你把这封信交给菲诺克，上面写着我所需要的东西的技术细节。你可以在冬泉谷的永望镇里找到菲诺克。",o="把丁奇的信交给冬泉谷永望镇的菲诺克。",p=4726,r={{i=12438,n="丁奇的信",c=1}}},
  [4809]={t="冰风奇美拉角",d="我有丁奇所需的大部分材料，但是唯独缺少一种很重要的零件，那就是冰风奇美拉的角。冰风奇美拉的角是寒冷的源泉，但是只有非常纯粹而完整的角才能用！我需要很多角才能完成丁奇的订单。；给我弄些完整的冰风奇美拉角来，我会为丁奇准备一个包裹。",o="收集8支完整的冰风奇美拉角。",p=4808,r={{i=12444,n="完整的冰风奇美拉角",c=8}}},
  [4810]={t="返回丁奇身边",d="好，所有的东西都已经打包准备好，只等着送货了！祝你旅途愉快，$n，别忘了告诉丁奇说她欠我一份人情！",o="把菲诺克的包裹交给燃烧平原烈焰峰的丁奇·斯迪波尔。",p=4809,r={{i=12445,n="菲诺克的包裹",c=1}},w={{i=15862,n="闪击斧",c=1},{i=15863,n="铭文节杖",c=1}}},
  [4811]={t="红色水晶",d="我们东边的区域出现了越来越多的有攻击性的枭兽。过去它们都是很温和的——甚至可以说是神秘的动物。尽管仍然有人对它们非常尊敬，但出于对奥伯丁安全的考虑，我不得不保持更现实一些的观点。；据说这段时间以来，月光枭兽被黑海岸东部山脉上的一块巨大的红色水晶吸引，聚集在它的周围。没有人知道那块水晶是什么，也没有人知道它是否真的存在。我想让你去找到它的位置，并把你所发现的任何东西都报告给我。",o="到奥伯丁的东边去，沿着黑海岸东部边界的山脉寻找一颗巨大的红色水晶，然后向奥伯丁的哨兵戈琳达·纳希恩汇报你的发现。"},
  [4812]={t="清洗水晶",d="用这支小瓶装一些奥伯丁月亮井的水。它潜在的魔法能量可以帮我们弄清这块水晶的成分，你必须把水倒在那块水晶上，剩下的就不用你操心了。；虽然我不觉得你会有什么不测，但我仍然希望你多加小心。我们东边就是费伍德森林，如果这块水晶真的与那个地方有关联，它就可能非常危险。",o="在奥伯丁月亮井中把空水瓶装满，然后调查黑海岸东部山脉的红水晶。",p=4811,r={{i=14339,n="月亮井水瓶",c=1}}},
  [4813]={t="The Fragments Within",o="Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine.",p=4812,w={{i=15335,n="石南钢剑",c=1},{i=15396,n="曲木匕首",c=1},{i=15397,n="橡木法杖",c=1}},f=1},
  [4821]={t="异型卵",d="在千针石林流传着一个有关异型卵的传言。那些声称见到它的旅行者都没能靠近它进行详细的观察。毒蛇守卫着那枚卵，就仿佛是在守卫它们自己的卵一样。；我想让你去把那枚异型卵找出来交给我，以便让我进行观察。据说它在某条毒蛇的窝里，但是沿着乱风岗南面与东北面的悬崖基部有好几处蛇窝。",o="把异型卵交给乱风岗的哈加尔·雷蹄。",r={{i=12467,n="异型卵",c=1}}},
  [4841]={t="清除半人马",d="你，现在我委托你去消灭那些半人马，让他们感受我们的怒气。进攻乱风岗北面的半人马营地！让怒火指引你的武器！",o="杀掉12个加拉克斥候、10个加拉克争斗者和6个加拉克逐风者，然后向乱风岗的峭壁卫兵图林·长角复命。",p=4542},
  [4842]={t="奇怪的源头",d="老实说，尽管冬泉谷没有火山，但是我相信这些温泉更为危险……；嗯，你应该是想亲自去看看。横跨冬泉谷，然后朝这个地区的最南端前进。当周围的空气变得污浊而闷热，天色也开始变暗时，你就会发现温泉的源头。；去看看吧，我想你回来时会带着许多疑问的。",o="根据多诺瓦·雪山的指示行动，然后回到她那里报告。",p=980},
  [4866]={t="蛛后的乳汁",d="这也许是世界上效力最强的毒药之一，$c！；在我转至黑石塔的旅途中，无意中听到过黑石兽人谈起一种致命的毒药。他们称其为“蛛后的乳汁”，这个名字是根据黑石塔里面那只烟网蛛后的名字得来的。；我需要一份在你体内流淌的“蛛后的乳汁”的样本，毒囊是远远不够的！让她在你体内注入毒汁，然后回到我这儿来！；然后……我就能得到乳汁了！；<他揉搓着双手，充满期待。>",o="你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。当你中毒之后，回到狼狈不堪的约翰那儿，他会从你的身体里抽取这些“蛛后的乳汁”。"},
  [4867]={t="乌洛克",d="啊！说起来就麻烦了！；拿上这张便笺！把我的蟑螂牵过来！",o="阅读瓦罗什的卷轴。将瓦罗什的蟑螂交给他。",r={{i=12712,n="瓦罗什的魔精",c=1}}},
  [4882]={t="守护秘密",d="你不清楚这条从你刚刚杀掉的那头枭兽身上拿到的项链究竟有什么重要的价值。它闪着奇特的光芒，时亮时暗。；特鲁尔·法贝恩也许对此更有了解，因为他对枭兽可谓了如指掌。也许你应该向他咨询一下。",o="把蓝羽项链交给血毒岗哨的特鲁尔·法贝恩。",r={{i=12558,n="蓝羽项链",c=1}}},
  [4883]={t="守护秘密",d="我确实比你更了解冬泉谷的枭兽，但是我不太了解它们所使用的魔法。我知道谁可以告诉你有关这条项链的更多信息。；雷霆崖的纳拉·蛮鬃是这方面的专家，去问问她吧。祝你好运，你。",o="把蓝羽项链交给纳拉·蛮鬃。",p=4882,r={{i=12558,n="蓝羽项链",c=1}},w={{i=15796,n="海泉护腕",c=1},{i=15797,n="闪亮的臂甲",c=1}},f=2},
  [4902]={t="Wildkin of Elune",o="Speak with Arch Druid Fandral Staghelm in Darnassus.",p=4901,w={{i=16622,n="荆棘投掷者",c=1},{i=16623,n="蛋白石勋章",c=1}},f=1},
  [4903]={t="高图斯的命令",d="根据军官高图斯的命令，黑石塔的下列主要首领必须被消灭：；对我们造成巨大威胁的欧莫克大王。；残忍无情的巨魔指挥官沃恩。；监督者维姆萨拉克。；如果你找到何重要的文件，也必须一并上缴。；成功则受人敬仰。；失败则被人遗忘。",o="杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。",r={{i=12562,n="重要的黑石文件",c=1}},w={{i=13958,n="维姆萨拉克的镣铐",c=1},{i=13959,n="欧莫克的瘦身腰带",c=1},{i=13961,n="哈雷肯的笼口",c=1},{i=13962,n="沃什加斯的绳索",c=1},{i=13963,n="沃恩的邪恶之握",c=1}},f=2},
  [4904]={t="终获解救",d="阿纳克要和我结婚……但是在我拒绝了他的提议之后，他当晚就回来绑架了我。我的兄弟试图阻止他，但是阿纳克太强大了，他……他杀了我的兄弟，然后把我带到了这里。我可怜的兄弟……；你，你能护送我离开恐怖图腾营地吗？求你了……我要回到萨利亚身边去！她一定非常思念我。",o="护送拉克塔·风歌离开恐怖图腾营地，然后与乱风岗的萨利亚谈一谈。",w={{i=15469,n="风歌腰带",c=1},{i=15468,n="风歌披风",c=1}},f=2},
  [4906]={t="更深重的堕落",d="第二个萨特营地在费伍德森林的北部，他们的头领是萨瓦里克。这个诡计多端的恶魔在不断吸收费伍德森林中的那些堕落生物的力量。；萨瓦瑟拉斯和他的手下只不过是一个宏大计划的一部分，他们要培养出一座堕落的月亮井，然后用它为萨瓦里克提供力量。；现在萨瓦瑟拉斯已经成为历史了，那么，$n，你的任务就是到北部去，打败萨瓦里克。",o="费伍德森林的艾瑞丹·蓝风要你去杀掉8个碧火唤魔者、8个碧火背叛者、8个碧火欺诈者和萨瓦里克。任务完成之后回到艾瑞丹那里复命。",p=4421,f=1},
  [4941]={t="伊崔格的智慧",d="雷德还活着？；不可能！；据说雷德在数十年前就被杀掉了。；去寻求伊崔格的建议吧，你。没有谁能比他更了解黑石氏族的情况了，如果这上面所写的都是真的，那么你应该通知伊崔格。谁都有复仇的权利。；你可以在奥格瑞玛找到他。；在你跟伊崔格谈过话之后，便去与酋长交流一下，搞清楚他想要如何处理这个问题。",o="和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。；你回忆起曾在萨尔的大厅中见过伊崔格。",p=4903},
  [4961]={t="奥拉赫宝珠的净化",d="啊，召唤师的宝珠——这肯定是污染的来源。如果你准备使用宝珠的话，我们就必须先驱除里面的恶魔，这对我来说很容易。；不过你的任务就困难一些了。一旦我释放出了恶魔，你就必须杀死他。；而且你的动作必须要快，如果你太慢的话，他就会回到宝珠里面去，那样我们可就白费力气了！；准备好你最强大的法术，把药水放在随手可及的地方，如果你有朋友的话，也叫几个来帮忙，这个任务真的不可掉以轻心。",o="杀死宝珠之魔，然后与塔贝萨谈一谈。",p=1799},
  [4964]={t="The Completed Orb of Dar'Orahil",o="Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.",p=4976,w={{i=15108,n="达奥拉赫宝珠",c=1},{i=15106,n="达奥拉赫法杖",c=1}}},
  [4966]={t="Protect Kanati Greycloud",o="Protect Kanati Greycloud from the centaur attack.",p=4881,w={{i=15461,n="轻蹄长靴",c=1},{i=15462,n="沃土护腕",c=1},{i=15463,n="暗淡护手",c=1}},f=2},
  [4971]={t="时间问题",d="一股邪恶的力量——很可能是天灾军团——出现在安多哈尔，扰乱了时间的流动！我可以尝试维持现有的时间进程，并修正它所遭到的破坏，但是我必须在一个安静的环境中才能做这些事情，这就需要你的帮助。；时光寄生虫——以改变的时间流为能源的食腐虫——在安多哈尔的仓库中大量繁殖，扭曲的蓝色脉搏是它们身体唯一可见的部分。它们阻挠了我的施法过程，所以，你，请你使用时光置换器帮我除掉这些寄生虫。",o="在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。；杀掉10只时光寄生虫，然后将时光置换器还给西瘟疫之地安多哈尔旅店的克罗米。",r={{i=12627,n="时光置换器",c=1}},w={{i=15812,n="紫兰花披肩",c=1},{i=15813,n="金链腰带",c=1}}},
  [4972]={t="找回时间",d="我需要借助你的能力进入这间房间以外的世界，你。请允许我稍后向你解释。；你发现这间房间与安多哈尔其它地方的不同了吧。我的飞龙以不同的方式在不同的时间线上工作着。要修复安多哈尔的损伤，我要从一个不同的时间线着手，避免过分污染它。要继续进行这项工作的话，我需要一些时间饰品，其中一个是在瘟疫袭击安多哈尔时产生的。在建筑物残骸中寻找时间饰品，这些建筑都是这个曾经繁华的城市的一部分。",o="在安多哈尔城中四处散落的保险箱里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。",p=4971,r={{i=12638,n="安多哈尔怀表",c=5}}},
  [4974]={t="为部落而战！",d="雷德受到黑龙的保护，因此他才如此狂妄嚣张。；你，你，必须寻找一条穿过晋升大厅的道路，找到大酋长雷德·黑手并杀死他——为部落而战！；<萨尔一拳打在王座上。>；高举着他的徽记凯旋吧，将徽记呈献给你的酋长。去吧，你将成为部落的英雄！",o="去黑石塔杀死大酋长雷德·黑手，带着他的徽记返回奥格瑞玛。",p=4941,r={{i=12630,n="雷德·黑手的徽记",c=1}},w={{i=13966,n="暴君印记",c=1},{i=13968,n="比斯巨兽之眼",c=1},{i=13965,n="黑手饰物",c=1}},f=2},
  [4975]={t="The Completed Orb of Noh'Orahil",o="Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.",p=4976,w={{i=15107,n="诺奥拉赫宝珠",c=1},{i=15105,n="诺奥拉赫法杖",c=1}}},
  [4976]={t="归还净化过的宝珠",d="把净化过的宝珠交给棘齿城的梅纳拉，你。代我向她问好，一路小心。我真的希望你能应付得了越来越强大的诱惑和腐蚀的力量。；祝你好运。",o="将净化过的地狱火宝珠交给贫瘠之地的梅纳拉·沃伦德。",p=4961,r={{i=12642,n="净化过的地狱火宝珠",c=1}}},
  [4982]={t="比修的装置",d="在夜里，当这个地方守备松懈的时候，我就会在城里偷偷地四处走动，记下我所看到的可能会对K.E.F.有战略价值的任何东西。；然而昨晚事情变得非常糟糕，我被一张网绊到并触动了一个机关，我马上把我的侦察装置藏起来去找藏身之所了！不幸的是，我没法取回那套装置。他们已经把巡逻兵的数量增加了两三倍！所有的情报都丢失了。；把我的东西拿回来，我就可以返回K.E.F.去了。",o="找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。",p=4981,r={{i=12345,n="比修的装置",c=1}}},
  [4983]={t="比修的侦察报告",d="把这份报告交给雷克斯洛特。它可以让我恢复好名声，并且肯定会让K.E.F.在对付这些兽人时占据战略上的优势。；跟你一起回去？我有太多的工作要做。快走吧，他们急需这些报告！",o="把比修的侦查报告交给卡加斯的雷克斯洛特。",p=4982,r={{i=12652,n="比修的侦察报告",c=1}},w={{i=15858,n="乱风手套",c=1},{i=15859,n="海港束带",c=1}},f=2},
  [4984]={t="大自然的苦楚",d="尽管我不可能以一己之力反抗亡灵天灾，但我仍然来到了这里，尽力治愈他们对大自然造成的伤害。这片土地上的生灵遭受着瘟疫所带来的灾难，这瘟疫使大地窒息。我想请你把我在这里未完成的工作继续下去。；对那些正在忍受折磨的动物们来说，除了仁慈地解放它们，没有什么其它的解决办法了。把附近生病的狼找出来，杀死它们。我请求你，你，结束它们的痛苦吧……这样做也会令我得到安宁。",o="消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"},
  [4985]={t="大自然的苦楚",d="在我们所在地的东方，东瘟疫之地边界的附近，从前骄傲而威严的灰熊在乡村游走。亡灵天灾所释放的瘟疫也已将这些动物趋散。它们在乡村游荡，饱受了肌肉僵硬和皮肉腐烂之苦。；我请求你也去结束它们的痛苦。治疗它们苦难的唯一方法就是让其痛快的死去，这必须由你亲手来完成。",o="消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。",p=4984},
  [4986]={t="雕文橡木枝",d="牛头人德鲁伊那毫无生气的手紧紧地抓着一根看上去极为结实的橡木枝，树皮上刻着一些德鲁伊教派的文字。；当你握着这根树枝时，你发现原本应该冰冷的树枝摸上去却非常温暖。巨树泰达希尔的画面清rn晰地浮现在你的脑海里，然后是达纳苏斯。“塞纳里奥议会”这几个字也涌到了你的唇边。你现在很清楚要把这根树枝带到哪儿去了。",o="根据雕文橡木枝上面所附加的魔法，这个牛头人德鲁伊本来准备把它交给达纳苏斯的塞纳里奥议会。看来你应该到那里去找一个德鲁伊，并寻求他的帮助。",p=4985,r={{i=12663,n="雕文橡木枝",c=1}},f=1},
  [4987]={t="雕文橡木枝",d="牛头人德鲁伊那毫无生气的手紧紧地抓着一根看上去极为结实的橡木枝，树皮上刻着一些德鲁伊教派的文字。；当你握着这根树枝时，你发现原本应该冰冷的树枝摸上去却非常温暖。莫高雷地区的雷霆崖的画面清晰地浮现在你的脑海里，然后是达纳苏斯。“塞纳里奥议会”这几个字也涌到了你的唇边。你现在很清楚要把这根树枝带到哪儿去了。",o="根据雕文橡木枝上面所附加的魔法，这个牛头人德鲁伊本来准备把它交给雷霆崖的塞纳里奥议会。看来你应该到那里去找一个德鲁伊，并寻求他的帮助。",p=4985,r={{i=12663,n="雕文橡木枝",c=1}},f=2},
  [5001]={t="比修的装置",d="通常我是不会与$r打交道的，但是现在看起来，我前有困境后有巨魔，进退两难。你知道，我在此地的任务对部落来说有极其重要的意义。然而我得到的情报对联盟来说也是有益的。请相信我，我不是联盟的支持者，但黑石氏族不只有一群兽人。；如果你帮我找到我的东西，我就会给你一些对你们也有用的情报。；同意吗？",o="找到比修的装置并把它们还给她。祝你好运！",r={{i=12345,n="比修的装置",c=1}}},
  [5002]={t="给麦克斯韦尔的消息",d="我是个说话算话的小地精。现在仔细听着：；这些兽人的主要用途是黑龙的苦工和炮灰！；他们真正的头领不是别人，正是奈法利安，死亡之翼的儿子。我还在这一带侦察到了一些奈法利安的下属所在的位置。；把这张地图交给燃烧平原的麦克斯韦尔元帅，地图上面标记着这些魔王的位置，很容易就可以辨认出来。",o="到燃烧平原去，把比修的情报交给麦克斯韦尔元帅。",p=5001,r={{i=12770,n="比修的情报",c=1}}},
  [5022]={t="迟到总比不到好",d="你捡起那只包裹，然后擦掉了积落在上面的一层薄薄的尘土和泥垢。这只包裹上面草草地写着要投寄给暴风城里的一个名叫艾玛·费尔斯通的人，而包裹的递送日期已经是四年之前了。；尽管你并不清楚艾玛·费尔斯通是否还活着，但暴风城的市政厅里应该还保留有城市居民的记录，你应该去找暴风城人口普查处的皇家代理人帮忙。",o="与暴风城的皇家代理人巴瑟罗尔协商，查找到艾玛·费尔斯通的下落。通常在市政厅里都有一个人口普查官。",p=5021,r={{i=12724,n="詹妮丝的包裹",c=1}}},
  [5023]={t="迟到总比不到好",d="你捡起那只包裹，然后擦掉了积落在上面的一层薄薄的尘土和泥垢。这只包裹上面草草地写着要投寄给洛丹伦的一个名叫杰雷米亚·费尔斯通的人，而包裹的递送日期已经是四年之前了。；尽管你并不清楚杰雷米亚·费尔斯通是否还活着，但幽暗城——也就是以前的洛丹伦——应该还保留有城市居民的记录，你应该去找幽暗城人口普查处的皇家管理人帮忙。",o="与幽暗城的皇家管理人巴哈乌斯协商，查找杰雷米亚·费尔斯通的下落。通常在公会注册处附近会有一个人口普查官。",p=5021,r={{i=12724,n="詹妮丝的包裹",c=1}}},
  [5047]={t="芬克·恩霍尔，为您效劳！",d="你可以在永望镇找到玛雷弗斯·暗锤，$c。告诉他“芬克一切都好”，还有衣服很不错。；然后给他这个。；<芬克给了你一块光鲜的肉。>；这是我“度假”时从比斯巨兽的内脏里摘出来的。；我敢打赌，玛雷弗斯对看到这个东西的时候会大吃一惊的！；哦，我猜你不知道永望镇在哪里，是吗？到冬泉谷去，$g小伙子:女士;！",o="与永望镇的玛雷弗斯·暗锤谈一谈。",r={{i=12710,n="比斯巨兽的发光肉块",c=1}}},
  [5050]={t="好运护符",d="看起来我错怪你了，你，为此我应向你道歉。我姐姐送给我许多东西，包括看起来很滑稽的费尔斯通农场地契，我想我一时半会是没法收回它了。；如果我姐姐的灵魂还被束缚在农场不能安息，请你帮帮忙……你能把这个还给她吗？这是她的半个护身符，她的丈夫拿着另外一半。；或许当她知道我拿到这些东西之后就可以安息了。",o="把半个好运护符还给西瘟疫之地的詹妮丝·费尔斯通。",r={{i=12721,n="一半好运护符",c=1}}},
  [5051]={t="两半合一",d="这个可怜的灵魂在继续喃喃自语：；“我好冷，约翰，把你的护符给我，这样我们就可以在一起了！快点，约翰，要在瘟疫把我们变成可恶的野兽之前！我看不到你，约翰……但是我知道你就在附近。我能感觉到你在我身旁……”；也许如果你能找到另一半护符并把两半拼凑起来，就能组合成詹妮丝·费尔斯通的灵魂寻求的东西。",o="在西瘟疫之地的费尔斯通农场某地找到另外一半好运护符，并把两半护符合并。；把好运护符交给西瘟疫之地费尔斯通农场的詹妮丝·费尔斯通。",p=5050,r={{i=12723,n="好运护符",c=1}}},
  [5052]={t="阿迦玛甘的血岩碎片",d="和荆棘一样，鲜血也影响了<猪哼声>大地的其它特性：血红的石头与别的矿石掺杂在一起，刺背野猪人挖出这些碎片并把它们带走，在战斗中把它们当作增强<猪哼声>力量和魔法能量的图腾。<猪哼声>；我知道那个魔法的秘密。；把一块血石碎片交给碎牙来表示你明白了。给碎牙拿来许多血牙碎片，他就会用野猪人的魔法保护你——阿迦玛甘的魔法！<猪哼声>",o="给陶拉祖营地的碎牙带去一块血岩碎片。；如果你想要他赐予你阿迦玛甘的力量，就搜集更多的血岩碎片。",p=878,r={{i=5075,n="血岩碎片",c=1}}},
  [5054]={t="碎齿熊尤西乌斯",d="在冬泉谷那白雪茫茫的山脉里，有一头狩猎技术纯熟精湛的碎齿熊，尤西乌斯。；现在我让你去对付他，尤西乌斯就在永望镇西边的山坡上徘徊。在它发现你的意图之前找到他，击败他。；所有前去猎杀尤西乌斯的猎人都很快发现自己变成了猎物，而尤西乌斯才是猎人。你要多加小心。",o="永望镇的斯托姆·影蹄想要你去杀死尤西乌斯。"},
  [5055]={t="冰风奇美拉布鲁米兰",d="布鲁米兰迅捷而又聪明，她悄无声息地在冬泉谷南边的雪地中滑翔。但是不要让她那优雅的外表迷惑了你，所有从她身旁经过的旅行者都受到了猛烈的攻击，而且多半会赔上他们的性命。；从那些冰风奇美拉中找出布鲁米兰，打败它，然后再回来见我。",o="永望镇的斯托姆·影蹄想要你去杀死布鲁米兰。",p=5054},
  [5056]={t="希洛塔姆",d="在冬泉谷的北方，有一大群凶猛的雪豹聚集在一处被称作霜刀石的地方。这些豹子的首领是希洛塔姆。打败她，你的同伴就会对你充满敬意。；再去一次冬泉谷，一到那里就开始从霜刃豹身上搜集它们的肉。找到希洛塔姆之石，把肉放在那里，这样就可以召来愤怒的希洛塔姆。；迎战狂怒的霜刃豹首领，并打败她。",o="永望镇的斯托姆·影蹄想要你去杀死希洛塔姆。",p=5055,w={{i=15783,n="猎兽匕首",c=1},{i=15782,n="驯兽者之剑",c=1}},f=2},
  [5057]={t="Past Endeavors",o="Bring Storm Shadowhoof's Marker to Melor Stonehoof in Thunder Bluff.",p=5056,f=2},
  [5060]={t="被锁起来的农夫",r={{i=12739,n="达尔松橱柜钥匙",c=1}}},
  [5061]={t="水栖形态",d="你已经学完了掌握水栖形态所必须具备的所有知识，现在回到达纳苏斯的玛斯雷·驭熊者那儿去吧。把坠饰拿给他看看，以此证明你已准备好接受新的知识。他会让你掌握变化为水栖形态的诀窍，让你在水中灵活自如。；再见，年轻的德鲁伊。我们会再见面的。",o="回到达纳苏斯，让玛斯雷·驭熊者看看你的海狮坠饰。",p=272,r={{i=15885,n="海狮坠饰",c=1}},f=1},
  [5062]={t="神圣之火",d="阿利卡拉是个致命的威胁，我们必须马上将其解决。你必须点燃生命圣火，这样就可以召唤出阿利卡拉了。；现在就去采集稀有的火岩龙舌兰植株。在你采集到了足够的植株后，到雷霆崖的长者高地上去找玛加萨·野性图腾。她是个具有强大力量的萨满祭司，她可以点化火岩龙舌兰来创造一种引燃圣火所需的材料。；到西北面的沸腾之池去收集火岩龙舌兰吧。",o="收集10支火岩龙舌兰，然后去找雷霆崖长者高地的玛加萨·野性图腾。",p=4865,r={{i=12732,n="火岩龙舌兰",c=10}}},
  [5063]={t="血色学者之帽",d="一顶你从未见过的帽子。我们熟练的工匠将使用比斯巨兽的皮制造出最漂亮华美的、每个施法者都梦寐以求的帽子！；另外还需要五十个金币的制作费用和下面列出的制造材料：；*比斯巨兽的皮。；*磨损的憎恶缝合线。；*奥术水晶。；*魔化红线。",o="为了制造血色学者之帽，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，8块奥术水晶，5根魔化红线。；另外你还必须支付50金币的制作费用。",p=5047,r={{i=12731,n="比斯巨兽的皮",c=1},{i=12735,n="磨损的憎恶缝合线",c=5},{i=12363,n="奥术水晶",c=8},{i=12734,n="魔化红线",c=5}}},
  [5064]={t="恐怖图腾的密信",d="$n，你曾为我们做了不少事情，现在我要交给你一个重要的任务。恐怖图腾氏族正在策划一些神秘的行动。最近几个星期，有三个神秘的访客去过恐怖图腾氏族的营地中。我们发现他们在黑云峰放置了几只分布的箱子，里面就藏着他们的密信。；你，如果你成功地完成了这个危险的任务，我一定会好好奖励你的。",o="在黑云峰拿到三封密信。",p=4841,r={{i=12765,n="密信#1",c=1},{i=12766,n="密信#2",c=1},{i=12768,n="密信#3",c=1}},w={{i=15457,n="沙漠护肩",c=1},{i=15458,n="苔原长靴",c=1},{i=15459,n="丧钟护腕",c=1}},f=2},
  [5065]={t="失落的摩沙鲁石板",d="那个巨魔没有对你说出真相。你为他弄来的那两块石板提到了哈卡精华，但是那个传说的内容应该还有更多才对。我已经研究很久了，而且我发现摩沙鲁石板应该总共有六块，并非两块！是六块！；我恐怕其它人所掌握的那些秘密会对我们不利……；找到第三块和第四块摩沙鲁石板。它们在东瘟疫之地，被居住在那里的烂苔巨魔控制着。找到它们并把它们交给我。",o="把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。",p=3528,r={{i=12411,n="第三块摩沙鲁石板",c=1},{i=12412,n="第四块摩沙鲁石板",c=1}}},
  [5067]={t="阿卡纳护腿",d="虽然历史上从来没有成功铸造这件装备的记录，但是只要有合适的环境，铸造它还是有可能的。；如果奥秘的追寻者想要得到这样一件具有强大力量的护腿，他就需要以下这些材料：；*比斯巨兽的皮。；*磨损的憎恶缝合线。；*奥金锭。；*莱斯·霜语的防腐液。",o="为了制造阿卡纳护腿，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，5块奥金锭，5份莱斯·霜语的防腐液。；另外你还必须支付50金币的制作费用。",p=5047,r={{i=12731,n="比斯巨兽的皮",c=1},{i=12735,n="磨损的憎恶缝合线",c=5},{i=12360,n="奥金锭",c=5},{i=12736,n="莱斯·霜语的防腐液",c=5}}},
  [5068]={t="嗜血胸甲",d="据说嗜血胸甲只有一件，那是为最强的刺客迦罗娜制造的。迄今为止，是否还存在其它的嗜血胸甲仍然是个悬而未决的谜。；但是！我们的工匠只要获得必要的材料就可以将它复制出来：；*比斯巨兽的皮。；*磨损的憎恶缝合线。；*奥金锭。；*暗影之皮。",o="为了制造嗜血胸甲，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，10根磨损的憎恶缝合线，5块奥金锭，5块暗影之皮。；另外你还必须支付50金币的制作费用。",p=5047,r={{i=12731,n="比斯巨兽的皮",c=1},{i=12735,n="磨损的憎恶缝合线",c=10},{i=12360,n="奥金锭",c=5},{i=12753,n="暗影之皮",c=5}}},
  [5081]={t="麦克斯韦尔的任务",d="这条消息正好弥补了我们对黑石塔情报的不足。；本次进攻具有决定性的战略意义，你。；首先，我们要消灭他们的主帅，巨魔沃恩。没有他的战斗计划，黑石兽人将陷入一片混乱之中。；接下来，你必须除掉食人魔之王欧莫克。黑石塔里那些胆小如鼠的食人魔如果没有了他的指挥，就会变成一盘散沙。；最后是黑石塔的核心将领维姆萨拉克。只要维姆萨拉克一死，他们的指挥中枢就会彻底瘫痪。",o="到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。",p=5002,w={{i=13958,n="维姆萨拉克的镣铐",c=1},{i=13959,n="欧莫克的瘦身腰带",c=1},{i=13961,n="哈雷肯的笼口",c=1},{i=13962,n="沃什加斯的绳索",c=1},{i=13963,n="沃恩的邪恶之握",c=1}},f=1},
  [5083]={t="冬泉火酒",d="你从冬泉熊怪那儿拣来的这只小瓶子是空的，但是里面有一些奇怪的绿色液体，它甚至发出了微微的光芒。；这会是什么重要的东西吗？；多诺瓦·雪山可能会告诉你更多的信息，她在冬泉谷的温泉附近有个营地。",o="将空的火酒瓶交给冬泉谷的多诺瓦·雪山。",r={{i=12771,n="空的火酒瓶",c=1}}},
  [5085]={t="神秘的粘液",d="锅里沸腾的绿色物质看起来与你在小瓶子中找到的东西一样。这种奇怪的粘液状的物体可能与制造它的熊怪一样，感染了严重的堕落力量……；如果冬泉熊怪在使用它，那么这是否意味着它们很快就会像死木部族一样堕落？；你最好赶快向多诺瓦汇报你的发现，顺便从锅里采集一点液体样本给她。",o="将你的发现报告给多诺瓦·雪山。",p=5084,r={{i=12813,n="神秘的粘液",c=1}}},
  [5086]={t="剧毒之水",d="我研究了你取回来的样本，虽然我还无法确定，但是我相信其中包含着有毒的成分。判断这一点的唯一方法是收集其它类似的物质进行比较。；我想死木熊怪也许会从费伍德森林的其它堕落生物那儿收集这些东西，尤其是生活在铁木森林中的那种被称作剧毒之水的元素生物。；为我收集一些样本以进行比较，但是要小心——那里是个非常危险的地方！",o="为冬泉谷的多诺瓦·雪山收集3份剧毒水滴。",p=5085,r={{i=12822,n="剧毒水滴",c=3}}},
  [5087]={t="冬泉信使",d="真有趣，你……；当这种有毒物质与温泉里的水混合的时候，它的毒性就消失了，对饮用者来说，它只会产生暂时的影响。这必定是冬泉熊怪如此热衷于守护温泉的原因——它们需要这些泉水来净化火酒。；我们必须阻止它们——截断冬泉熊怪与死木熊怪之间的联系。有一队冬泉熊怪的信使往返于它们的村子和费伍德森林之间。找到它们，把它们的货物劫下来。",o="找到冬泉信使，阻止他们向冬泉村运送物品。",p=5086,r={{i=12829,n="冬泉箱子",c=1}}},
  [5088]={t="阿利卡拉",d="把这些提纯净化的火岩粉拿到千针石林去，并洒在生命圣火之上。那团火焰位于黑云峰的一根用于埋葬死者的石针上。；我注入火岩粉中的魔法会将阿利卡拉召唤到你身旁，你。；我担心她可能在追踪凯恩·血蹄……牛头人的观念改变得太多了，而我担心这一点激怒了阿利卡拉。在事情变得无法收拾之前赶快行动吧，$c！",o="杀死阿利卡拉。把她的遗体和火岩粉交给白沙岗哨的莫特加·火鬃作为证明。",p=5062,r={{i=12785,n="火岩粉",c=1},{i=12925,n="阿利卡拉蛇皮",c=1}},w={{i=15464,n="野蛮之锤",c=1},{i=15465,n="钉击魔杖",c=1},{i=15466,n="裂缝之盾",c=1}},f=2},
  [5089]={t="达基萨斯将军的命令",d="你从尸体上发现了一封看上去很重要的信：一封来自于他的上级达基萨斯将军的信，信的内容似乎跟某种协议有关。；你的直觉告诉你，应该把它交给麦克斯韦尔元帅。",o="把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。",r={{i=12780,n="达基萨斯将军的命令",c=1}}},
  [5092]={t="扫清道路",d="安多哈尔城西和城北的入口防守非常严密，我正在努力从防御力较弱的东面入口寻找突破点。天灾军团以占据悔恨岭的亡灵部队所组成的第一道防线作为缓冲区，如果我们想要进攻安多哈尔的话，就必须穿过悔恨岭。；你的第一个任务是清除悔恨岭一带的障碍，扫除在这一地区出没的骷髅和食尸鬼，任务完成之后就回来向我汇报！",o="杀掉悔恨岭中的10个骷髅剥皮者和10个被奴役的食尸鬼。；然后向西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特复命。"},
  [5097]={t="标记哨塔",d="通过使用一种被称作信号火炬的魔法物品，我们可以为军队即将展开的行动标识出目标。我们认rn为亡灵天灾正在将安多哈尔的哨塔作为控制军队的手段。；你的任务就是突破安多哈尔的防线，将信标放置在四座哨塔中。你必须将信标放在每座哨塔的门口才行。信号火炬仅可使用五次，可别浪费了！",o="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。；在做完了标记之后，将信号火炬还给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。",p=5092},
  [5098]={t="标记哨塔",d="通过使用一种被称作信号火炬的魔法物品，我们可以为军队即将展开的行动标识出目标。我们认为亡灵天灾正在将安多哈尔的哨塔作为控制军队的手段。；你的任务就是突破安多哈尔的防线，将信标放置在四座哨塔中。你必须将信标放在每座哨塔的门口才行。信号火炬仅可使用五次，可别浪费了！",o="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。；在做完了标记之后，将信号火炬还给西瘟疫之地亡灵壁垒的高级执行官德灵顿。",p=5096},
  [5102]={t="达基萨斯将军之死",d="我们和这些怪物正在进行双线作战：在暴风城，我们努力不让它们的魔爪深入城市；在燃烧平原，我们把战火烧到它们门前。我们必须时刻保持着警惕，你。当它们侵占我们的领地，残害我们家人的时候，我们要把怒火全部倾泻出来。；找到达基萨斯将军，然后干掉它！；这个任务显然不简单，但是完成它所能得到的奖励也是相当丰厚的。",o="到黑石塔去杀掉达基萨斯将军。",p=5089,w={{i=13966,n="暴君印记",c=1},{i=13968,n="比斯巨兽之眼",c=1},{i=13965,n="黑手饰物",c=1}},f=1},
  [5121]={t="冬泉酋长",d="虽然我们还不太清楚为什么熊怪会吃下这种奇怪的物质，但我们最好尽快阻止它们。；冬泉熊怪并不是一个好战的部族，它们的巨大变化让我认为它们一定是在执行领袖的命令。我们无法挽回它们已经造成的损失，但是我想，如果它们的领袖被除掉的话，事态至少不会进一步恶化。；快去冬泉村吧。",o="冬泉谷的多诺瓦·雪山要你去击败冬泉酋长。",p=5087,w={{i=15784,n="水晶之风衬肩",c=1},{i=15786,n="蕨脉外套",c=1},{i=15787,n="柳环锁甲",c=1}}},
  [5122]={t="信仰奖章",r={{i=12845,n="信仰奖章",c=1}}},
  [5123]={t="最后一片",d="你在冬泉酋长身上找到的日志看起来内容丰富，但是看完几页之后，你发现自己完全看不懂这本书。上面的符号粗糙而又拙劣——你不禁怀疑是否真的有人能读懂它们。；不过，多诺瓦也许能告诉你这本书上写了些什么……",o="把潦草的日志交给冬泉谷的多诺瓦·雪山。",p=5087,r={{i=12842,n="潦草的日志",c=1}}},
  [5124]={t="炽热板甲护手",d="以索瑞森胡须的名义！；你是在哪儿找到这些东西的？；更重要的是，你愿意出售它们吗？我自然会付给你丰厚的酬劳。；我跟你说啊，你，要是你把这些没淬火的护手给我，我就教你如何打造自己的装备。你要做的就是为我收集这些东西，这样我就能获得精确的配方了。；你觉得怎么样？；这是一张我需要的东西的列表，你把护手交给我之后，其它的材料我自己搞定。",o="将6块魔化瑟银锭、2份火焰精华和4颗红宝石交给玛雷弗斯·暗锤。另外你还得把未淬火的板甲护手也交给他。",p=5103,r={{i=12812,n="未淬火的板甲护手",c=1},{i=12655,n="魔化瑟银锭",c=6},{i=7078,n="火焰精华",c=2},{i=7910,n="红宝石",c=4}}},
  [5125]={t="Aurius' Reckoning",p=5122,w={{i=17044,n="殉难者的意志",c=1},{i=17045,n="殉难者之血",c=1}}},
  [5147]={t="通缉：阿纳克·恐怖图腾",d="通缉：阿纳克·恐怖图腾；流放者阿纳克因罪大恶极的谋杀和绑架行为而被通缉。那些敢于将这名罪犯绳之以法的勇士将获得丰厚的报酬。；阿纳克最后一次被发现是在黑云峰附近的悬崖上。请向乱风岗的峭壁卫兵图林·长角出示你杀死阿纳克的证明。",o="杀死阿纳克·恐怖图腾，并向乱风岗的峭壁卫兵图林·长角出示证据。",r={{i=12884,n="阿纳克的蹄子",c=1}},w={{i=15471,n="韧革护甲",c=1},{i=15470,n="平原卫士护腿",c=1}},f=2},
  [5149]={t="帕米拉的洋娃娃",d="玛莱恩姑妈让我留在家里，因为我的爸爸出去作战了。爸爸是世界上最勇敢的人！；但是我在这里等了很长时间，他一直都没有回来。有时候会有坏人来和我说话，我想让爸爸把他们赶走，但是他不在这里！；有时候，天黑了以后，我会和我的洋娃娃玩，但是我把它丢在镇子里了。；你能不能去帮我找到洋娃娃呢？",o="找到帕米拉的洋娃娃。",r={{i=12885,n="帕米拉的洋娃娃",c=1}}},
  [5151]={t="超适应齿轮",d="我们的商队被半人马袭击了，而我是唯一的幸存者！但是那头罕见的黑豹守护着我最完美的发明，嗯，就挂在它的脖子上。哈哈！即使是半人马也会在那头凶猛的野兽面前颤抖！；这是那个笼子的钥匙。他们拿走了那里所有的东西，但是把黑豹留在了那里。把那头野兽杀了，然后拿回我的超适应齿轮，我会好好奖励你的。；商队的残骸就在这里的北面。",o="杀了那头野兽，把超适应齿轮和钥匙交给维兹罗。",r={{i=12942,n="豹笼钥匙",c=1},{i=12946,n="超适应齿轮",c=1}},f=2},
  [5153]={t="古怪的历史学家",d="我希望约瑟夫重新回到她女儿身边，但是这已经不可能了。他的灵魂已经属于亡灵天灾，他已经变成了一个怪物。唉，他命中注定如此！；但是，也许我们能改变他的命运。；在墓地外围寻找约瑟夫的墓碑。他的躯体不在那里，因为他已经在几年前灰飞烟灭了，但是在墓碑下埋着他的戒指。把戒指交给克罗米……那是个具有强大魔法力量的侏儒。；克罗米在安多哈尔南墙附近的旅馆废墟中。",o="把约瑟夫的结婚戒指交给安多哈尔的克罗米。",p=5152,r={{i=12894,n="约瑟夫的结婚戒指",c=1}}},
  [5154]={t="达隆郡的历史",d="要拯救约瑟夫·雷德帕斯，我们首先得找到他的过去。安多哈尔城镇中心有一本书，名叫《达隆郡的历史》，它可以告诉我们一些重要的事情。；把书拿来给我，然后我们就可以了解约瑟夫的命运，如果运气好的话……我们还能改变它！",o="把《达隆郡的历史》交给安多哈尔的克罗米。",p=5153,r={{i=12900,n="达隆郡的历史",c=1}}},
  [5155]={t="加德纳尔的势力",d="如果要我完全信任你的话，你就必须先证明自己的实力。；我必须确信你可以击败暗影议会。；到费伍德森林的深处去，你可以在路的西边看到一条通往加德纳尔的小径。暗影议会就在那里与燃烧军团密谋着邪恶的计划。；进入被腐化的兽穴，然后杀了他们的成员。当你完成任务之后再回到我这里来。这样我可以相信你是真的想要帮助我们了。",o="到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。"},
  [5157]={t="收集堕落之水",d="在加德纳尔深处有一座暗影堡，那里是堕落和邪恶的主要源头。；暗影议会使用几座火盆制造防护结界，将他们的巢穴保护了起来。；如果我想要通过占卜来获得更多有关他们的情报，那你首先要想办法熄灭那些火盆，然后我就可以侦测暗影议会并找到究竟是谁在领导他们了。；如果你愿意帮忙的话，拿着这只水壶，用它在加德纳尔中心的月亮井中装满水，然后回到我这里来。",o="把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。",p=5155,r={{i=12907,n="腐化的月亮井水",c=1}}},
  [5158]={t="水之魂的帮助",d="把腐化的月亮井水拿到贫瘠之地去，你。棘齿城南面的海岸边上住着我的一个老朋友，水之先知伊斯伦。她是个强大的萨满祭司，并且愿意帮助我们。她和水之魂的关系不错，我们高尚的目标一定可以让她和水之魂出手帮助我们。；你可以在水边的一个小帐篷中找到她。另外，你，不要管那些海盗……他们对你完全不构成威胁。",o="把腐化的月亮井水交给贫瘠之地的水之先知伊斯伦。",p=5157,r={{i=12907,n="腐化的月亮井水",c=1}}},
  [5159]={t="净化过的水",d="感谢水之魂，你。它们答应帮助你了。；现在我就把这瓶净化好的水交给你。代我向格雷塔问好，她正在做的事情比我们大多数人所做的事情都要伟大……我确信不久之后她也会发现这一点的。；不要小看暗影议会的力量，你。记住这一点。；现在就出发吧，把水交给格雷塔。",o="把净化过的月亮井水交给费伍德森林的格雷塔·苔蹄。",p=5158,r={{i=12906,n="净化过的月亮井水",c=1}}},
  [5160]={t="监护者",d="到卡利姆多去，$r。我们蓝龙军团在寒冷的冬泉谷定居。在你到达冬泉谷之后，就去寻找麦索瑞尔洞穴。；在麦索瑞尔的冰冷的地板上，你将会找到钴蓝色的符文。拿着我的鳞片站在某个符文上，你就会被传送到哈尔琳身边, 她是我们的监护者。；把鳞片交给她，让她用水晶球占卜一下我在这个可怕的地方所看到和感觉到的是什么。",o="到冬泉谷去找到哈尔琳，把奥比的鳞片交给她。",r={{i=12923,n="奥比的鳞片",c=1}}},
  [5163]={t="雪怪计划！",d="搞定！；现在，我已经给我的朋友们发信了，说是我有个惊喜要给他们看看。这就是你要做的事情！；我要把机械雪人给你，然后你就去访问我所有的朋友并给他们一个惊喜，启动机械雪人，然后让他们大开眼界！；让永望镇的莱加奇、加基森的斯普琳科，还有马绍尔营地的奎克希尔看看它，然后回来告诉我他们有什么反应！；别忘了把我的雪人也带回来。",o="带着乌米的机械雪人去吓唬她的朋友：；永望镇的莱加奇（冬泉谷）、加基森的斯普琳科（塔纳利斯），还有马绍尔营地的奎克希尔（安戈洛环形山）。；当你完成任务之后，把机械雪人还给乌米。",p=977,r={{i=12928,n="乌米的机械雪人",c=1}}},
  [5165]={t="熄灭火焰",d="现在，你必须回到加德纳尔去。那些火盆分布在暗影堡中，熄灭它们的火焰，这样保护暗影议会的屏障就会消失一段时间——我正在等待着那个时刻的到来。如果你成功了，我就会仔细查看暗影堡，然后找出他们的头目。然后，我们将决定是否发起正面攻击。",o="使用净化过的月亮井水熄灭暗影堡内部的四座火盆的火焰，从而破除其保护效果，然后向翡翠圣地的格雷塔·苔蹄复命。",p=5159},
  [5166]={t="多彩巨龙胸甲",d="铸造一件足以抵御彩色巨龙冷酷攻击的胸甲，就必须使用最坚硬的材料。；我们需要把成年彩色巨龙的多彩龙鳞和那些被我们击败的凶残的野兽的外皮缝合在一起。这些东西的存在并不为人所知，愿它们永不存在于这个世界。；另外，最难以得到的东西就是英雄之血。；雕刻者将会为你完成铸造。",o="为了铸造多彩巨龙胸甲，你必须把以下材料交给雕刻者耶兹巴：；1块多彩龙鳞。；10块闪亮的彩色龙鳞。；10份英雄之血。；10块磨损的憎恶缝合线。",p=5164,r={{i=12871,n="多彩龙鳞",c=1},{i=12607,n="闪亮的彩色龙鳞",c=10},{i=12938,n="英雄之血",c=10},{i=12735,n="磨损的憎恶缝合线",c=10}}},
  [5167]={t="多彩挑战者腿甲",d="成年彩色巨龙的外壳是制造护腿的基础。彩色龙鳞将被用于制作镶边，最后在英雄之血中进行洗礼。最后，暗影之皮的力量将被注入护腿中。",o="为了铸造多彩挑战者腿甲，你必须把以下材料交给雕刻者耶兹巴：；1块多彩龙鳞。；10块闪亮的彩色龙鳞。；10份英雄之血。；5块暗影之皮。",p=5164,r={{i=12871,n="多彩龙鳞",c=1},{i=12607,n="闪亮的彩色龙鳞",c=10},{i=12938,n="英雄之血",c=10},{i=12753,n="暗影之皮",c=5}},w={{i=12903,n="多彩挑战者护腿",c=1},{i=12945,n="多彩挑战者腿甲",c=1}}},
  [5202]={t="奇怪的红钥匙",d="这把红色的小钥匙似乎是由某种骨头制成的。它非常沉重，但是看上去却非常脆弱。为什么暗影议会的成员会拿着这样的东西呢？或许在加德纳尔内部有什么东西可以用这把奇怪的钥匙打开。",o="搜寻加德纳尔，找出血红钥匙的用途。",r={{i=13140,n="血红钥匙",c=1}}},
  [5203]={t="逃出加德纳尔",d="虽然我承受了很大的痛苦，但是有件事情我们必须先做好：我要找到特雷·莱弗治，然后从暗影堡逃出去，把这里所发生的一切都报告给我们的上司。你能帮我吗，你？；我的装备就在离这里不远的地方，而且你已经证明了你的实力。；在我们逃脱之后，我会去达纳苏斯，请你到灰谷的边界地带去找到杰希尔。她应该在那里的翡翠议会营地中。；你认为怎么样，$n？你能再帮我一次吗？",o="护送亚科纳琳到莱弗治和她的装备所在的地方，然后保护她逃离暗影堡。之后，在费伍德森林找杰希尔·月弓，并告诉她刚才发生的事情。",p=5202},
  [5204]={t="光明的惩戒",d="她假装自己没事。她希望我认为她有足够坚强，可以独自承担所有的悲伤，这一点我很清楚。特雷的死和他被折磨时发出的惨叫会让她在很长一段时间里都被痛苦煎熬，我们对此无能为力。但是我们至少可以给她一些安慰！；你，回到暗影堡去，杀了折磨特雷的混蛋，并找回他的遗体。在亚科纳琳默默承受痛苦的时候，我们可不能留在这里什么事情都不做。",o="回到加德纳尔杀了魅魔拉凯雅，然后找到特雷·莱弗治的残骸。",p=5203},
  [5206]={t="达隆郡的掠夺者",d="克罗米说你所收集的那些遗物是施放一个强大的法术所必需的材料，此外还需要一样东西：参加达隆郡战役的天灾军团士兵的徽记。；带着这块水晶去猎杀天灾军团的士兵，并拿到他们的徽记。这块水晶已经被施了魔法，如果某个士兵曾参加过那场战斗，那么当你把水晶球放在他的徽记上时，它就会发出共鸣。把那些可以与水晶共鸣的徽记交给我。；快去，你。你可以在北方的剧毒林地和西方的蘑菇林中找到亡灵天灾的士兵。",o="把5个共鸣徽记和神秘水晶交给东瘟疫之地的卡林·雷德帕斯。",r={{i=13155,n="共鸣徽记",c=5},{i=13156,n="秘法水晶",c=1}}},
  [5210]={t="卡林·雷德帕斯",d="借助我的魔法，《达隆郡的历史》被增补了，现在它所记述的历史已近包括战争之后的事情了。新增的章节里有一部分讲述了另一个雷德帕斯系列成员的下落，他在约瑟夫叛变后侥幸活了下来。卡林·雷德帕斯在东瘟疫之地的圣光之愿礼拜堂里。；拿着这本书去找他吧。",o="将《达隆镇全史》交给东瘟疫之地的卡林·雷德帕斯。",p=5154,r={{i=13202,n="达隆郡全史",c=1}}},
  [5212]={t="血肉不会撒谎",d="被遗忘者的药剂师并不是这个世界上唯一接受过科学教育的学者。；我已经研究这场瘟疫好多年了，$c。我们以前曾认为瘟疫的力量正在衰减，但是我在瘟疫之地的研究成果却令人吃惊。瘟疫的力量似乎仍在增长！；我需要进行更多的试验！最有潜质的瘟疫源泉就是那些最近感染瘟疫的躯体。到斯坦索姆去给我带回一些标本来，你。",o="从斯坦索姆找回10个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……",r={{i=13174,n="疫病肉块",c=10}}},
  [5213]={t="活跃的探子",d="你必须更加深入斯坦索姆，你。；穿过第一道门之后，你就可以看到巨大的通灵塔。我们知道亡灵天灾正在源源不断地从这些建筑物中汲取力量。搜索通灵塔，并把你找到的任何有价值的情报带回来。",o="到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。",p=5212,r={{i=13176,n="天灾军团档案",c=1}},w={{i=13209,n="黎明之印",c=1},{i=19812,n="黎明符文",c=1}}},
  [5214]={t="弗拉斯·希亚比",d="可怕的事情……弗拉斯。你知道，城镇被毁灭了，而弗拉斯不想离开他那珍贵的货物。我还记得他说的最后一句话：“我要在他们该死的脏手碰到我的烟叶之前把所有东西都烧光！”；我可能比较贪财，但我不是傻瓜，于是我离开了弗拉斯和他的商店。我觉得他应该是已经被烧死了，但是如果……万一他的名牌烟草还有一部分没有被烧毁……；你怎么说，你？去帮烟鬼找包烟吧？",o="找到弗拉斯·希亚比在斯坦索姆的烟草店，并从中找回一盒希亚比的烟草，把它交给烟鬼拉鲁恩。",r={{i=13172,n="希亚比的烟草",c=1}}},
  [5216]={t="目标：费尔斯通农场",d="在西瘟疫之地的四口瘟疫之锅中，费尔斯通农场里的那一口可能是最容易进入的了。亡灵天灾在那边驻扎的都是新兵，尽管他们也不是轻易可以击败的对手，但相对来说毕竟容易一些。；到费尔斯通农场去，它就在这里的正东方，安多哈尔的西北方，并与那里的护锅者交战。它身上有一把可以打开瘟疫之锅的钥匙。当你开启那口锅之后，用这个瓶子装满锅里的毒药样品，我们要对它进行研究以制造出一种解药。",o="到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。",p=5215,r={{i=13194,n="费尔斯通农场的天灾之锅钥匙",c=1},{i=13186,n="费尔斯通农场的空瓶",c=1}}},
  [5217]={t="返回冰风岗",d="你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。；现在你应该带着毒药回到冰风岗的高阶牧师玛多妮尔那里去了。",o="把费尔斯通农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。",p=5216,r={{i=13190,n="费尔斯通农场的样本瓶",c=1}}},
  [5219]={t="目标：达尔松之泪",d="有一口瘟疫之锅被放置在一座早已废弃的农场上，现在这里被称为达尔松之泪。不过现在我们没时间掉眼泪，$c。我们必须打开这口瘟疫之锅！；到安多哈尔正北方的达尔松之泪去，消灭那里的护锅者。像上次一样，护锅者身上应该有一把可以打开瘟疫之锅的钥匙。用这个瓶子从锅里装一份样品拿回来，每口锅所使用的毒素配方都是截然不同的。",o="到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。",p=5217,r={{i=13195,n="达尔松之泪的天灾之锅钥匙",c=1},{i=13187,n="达尔松之泪的空瓶",c=1}}},
  [5220]={t="返回冰风岗",d="你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。；现在你应该带着毒药回到冰风岗的高阶牧师玛多妮尔那里去了。",o="把达尔松之泪的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。",p=5219,r={{i=13191,n="达尔松之泪的样本瓶",c=1}}},
  [5222]={t="目标：嚎哭鬼屋",d="已经有两口瘟疫之锅被成功打开了，虽然并不确定你能否继续前进，但我们仍然想要打开剩下的两口瘟疫之锅。这可以让我们的解药发挥更大的效果！；这次你的目标是嚎哭鬼屋的瘟疫之锅。那个地方在安多哈尔正东边，相对来说比较靠近被毁坏的城墙。和以前一样，消灭那里的护锅者，拿到它的钥匙。用这只瓶子从锅里取得样品。；祝一切顺利，你！",o="到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。",p=5220,r={{i=13197,n="嚎哭鬼屋的天灾之锅钥匙",c=1},{i=13188,n="嚎哭鬼屋的空瓶",c=1}}},
  [5223]={t="返回冰风岗",d="你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。；现在你应该带着毒药回到冰风岗的高阶牧师玛多妮尔那里去了。",o="把嚎哭鬼屋的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。",p=5222,r={{i=13192,n="嚎哭鬼屋的样本瓶",c=1}}},
  [5225]={t="目标：盖罗恩农场",d="最后的一口瘟疫之锅在一个被称作盖罗恩农场的地方，由亡灵天灾中较为强大的爪牙守卫着——那里的鬼魂和幽灵尤其危险。你可不能掉以轻心，你。；盖罗恩农场在这里的东北方向，靠近东瘟疫之地的边界。和以前一样，消灭那里的护锅者以获取他的钥匙。拿着这个空样品瓶，把它装满给我拿回来。愿圣光护佑你平安完成这次危险的任务，$c。",o="到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。",p=5223,r={{i=13196,n="盖罗恩农场的天灾之锅钥匙",c=1},{i=13189,n="盖罗恩农场的空瓶",c=1}}},
  [5226]={t="返回冰风岗",d="你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。；现在你应该带着毒药回到冰风岗的高阶牧师玛多妮尔那里去了。",o="把盖罗恩农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。",p=5225,r={{i=13193,n="盖罗恩农场的样本瓶",c=1}}},
