  [5230]={t="返回亡灵壁垒",d="你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。；现在你应该带着毒药回到亡灵壁垒的暗影牧师范蒂丝那里去了。",o="把费尔斯通农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。",p=5229,r={{i=13190,n="费尔斯通农场的样本瓶",c=1}}},
