  [5232]={t="返回亡灵壁垒",d="你往瓶子里装满了瘟疫之锅中的毒液，制成了一份合适的样品。；现在你应该带着毒药回到亡灵壁垒的暗影牧师范蒂丝那里去了。",o="把装满的达尔松眼泪之瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。",p=5231,r={{i=13191,n="达尔松之泪的样本瓶",c=1}}},
