  [7877]={t="The Treasure of the Shen'dralar",o="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!",p=7461,w={{i=18420,n="碾骨者",c=1},{i=18421,n="密林头盔",c=1},{i=18424,n="莎草长靴",c=1}}},
  [7907]={t="暗月野兽套牌",d="你现在已经收集到了野兽套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。",o="当暗月马戏团来到镇上的时候，把野兽套牌交给他们。",r={{i=19228,n="野兽套牌",c=1}}},
  [7927]={t="暗月入口套牌",d="你现在已经收集到了入口套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。",o="当暗月马戏团来到镇上的时候，把入口套牌交给他们。",r={{i=19277,n="入口套牌",c=1}}},
  [7928]={t="暗月督军套牌",d="你现在已经收集到了督军套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。",o="当暗月马戏团来到镇上的时候，把督军套牌交给他们。",r={{i=19257,n="督军套牌",c=1}}},
  [7929]={t="暗月元素套牌",d="你现在已经收集到了元素套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。",o="当暗月马戏团来到镇上的时候，把元素套牌交给他们。",r={{i=19267,n="元素套牌",c=1}}},
  [7930]={t="5张奖券 - 暗月花束",r={{i=19182,n="破损的暗月马戏团奖券",c=5}}},
