  [8762]={t="驯鹿梅森",d="出大事啦！驯鹿梅森被绑架了！；冬天爷爷有八头驯鹿，梅森是其中的一头，也是烟林牧场的财产。我们收到了宣称对此次绑架事件负责的组织寄来的勒索信，而且不是一封，是两封！两封，你明白吗？节日即将来临，我们早已经穷得叮当响啦！帮帮忙吧，帮我们找到梅森，把它救回来！；你可以看看这些勒索信里面有什么线索，找到梅森之后，把驯鹿之尘洒在它身上，这样就可以让它摆脱一切束缚！；事不宜迟！",o="找到驯鹿梅森。在你手头上的便笺中查找有关梅森下落的线索。；当你找到它之后，往它身上洒一些驯鹿之尘，这样就可以让它摆脱任何束缚。；解救梅森之后，把驯鹿之尘还给铁炉堡的乌莫尔特。",r={{i=21211,n="一包驯鹿之尘",c=1}}},
  [8764]={t="远离保护者之路",r={{i=21200,n="青铜龙军团的徽记之戒",c=1},{i=20858,n="岩石甲虫",c=15},{i=20859,n="黄金甲虫",c=15},{i=20860,n="银质甲虫",c=15}},w={{i=21210,n="青铜龙军团的徽记之戒",c=1},{i=21205,n="青铜龙军团的徽记之戒",c=1}}},
