  [8766]={t="远离征服者之路",r={{i=21205,n="青铜龙军团的徽记之戒",c=1},{i=20864,n="白骨甲虫",c=15},{i=20865,n="象牙甲虫",c=15},{i=20858,n="岩石甲虫",c=15}},w={{i=21200,n="青铜龙军团的徽记之戒",c=1},{i=21210,n="青铜龙军团的徽记之戒",c=1}}},
  [8789]={t="其拉帝王武器",d="一千年以来，我们并没有无所事事地留在这里，你。；我们在这里看着这些野兽耗尽资源时自相残杀，我们倾听了它们密谋毁灭我们世界的谈话，我们还知道了它们内部的争权夺利。；它们确实有弱点，而且我们知道如何利用这些弱点。；找到它们在葬礼仪祭上陪葬用的武器，把它和他们自己的神所创造的最强的元素融合在一起，我们就可以创造出终结一切的武器。",o="把其拉帝王武器和3块源质矿石交给安其拉神殿的亚雷戈斯，他会帮你制作使用源质强化过的武器。",r={{i=21232,n="其拉帝王武器",c=1},{i=18562,n="源质铸块",c=3}},w={{i=21242,n="神圣其拉战斧",c=1},{i=21272,n="神圣其拉火枪",c=1},{i=21244,n="神圣其拉短剑",c=1},{i=21269,n="神圣其拉壁垒",c=1}}},
  [8790]={t="其拉帝王徽记",d="亚雷戈斯认为，在一定情况下，因上古之神和他们的仆从之间的冲突而产生的元素也会对他们本身造成致命的威胁。凡人，我指的是源质。；将其拉帝王徽记和这种元素交给我，我就能为武器注入巨大的力量。",o="把其拉帝王徽记和3块源质矿石交给安其拉神殿的梦境之龙麦琳瑟拉，她会帮你制作使用源质强化过的武器。",r={{i=21237,n="其拉帝王徽记",c=1},{i=18562,n="源质铸块",c=3}},w={{i=21273,n="神圣其拉侍僧法杖",c=1},{i=21275,n="神圣其拉占卜法杖",c=1},{i=21268,n="神圣其拉战锤",c=1}}},
  [8791]={t="奥斯里安之死",d="来自其拉虫人的威胁已经被平息。可怕的奥斯里安被消灭了。；卡利姆多的人民听到这个消息应该可以松口气了。将奥斯里安的徽记交给塞纳里奥要塞的指挥官玛尔利斯。",o="将无疤者奥斯里安的徽记交给希利苏斯塞纳里奥要塞的指挥官玛尔利斯。",r={{i=21220,n="无疤者奥斯里安的徽记",c=1}},w={{i=21504,n="流沙护符",c=1},{i=21507,n="流沙咒符",c=1},{i=21505,n="流沙颈饰",c=1},{i=21506,n="流沙坠饰",c=1}}},
  [8801]={t="克苏恩的遗产",d="安其拉的高墙在震颤。一个比这个世界本身还要古老的邪恶力量已经被摧毁了。；你看着巨大的尸体，心跳几乎要停止了。在死一般的寂静中，你还是能感受到克苏恩的邪恶力量。；你完成了一件不可能完成的任务。；你取下了这个恶魔的眼珠，把它放入背包。；把克苏恩之眼交给下一间房子里的龙类吧。",o="将克苏恩之眼交给安其拉神殿的凯雷斯特拉兹。",r={{i=21221,n="克苏恩之眼",c=1}}},
  [8802]={t="卡利姆多的救世主",d="到时光之穴去吧，你$g大人:女士;。阿纳克洛斯还在等你回去呢。把克苏恩之眼交给他，我相信他一定会很乐意在自己的收藏品中增加这么一件东西。",o="把克苏恩之眼交给时光之穴的阿纳克洛斯。",p=8801,r={{i=21221,n="克苏恩之眼",c=1}},w={{i=21712,n="堕落神明咒符",c=1},{i=21710,n="堕落神明披风",c=1},{i=21709,n="堕落神明之戒",c=1}}},
